    public function __construct($key, $i18n)
    {
        $this->key      = $key;
        // Адрес из бота/CLI (config/telegram_api), затем TELEGRAM_API из .env,
        // затем api.telegram.org — см. TelegramApi::current().
        $this->telegramApiUse(TelegramApi::current($this->telegramApiFile)['url']);
        $this->ip       = getenv('IP');
        $this->i18n     = $i18n;
        $this->language = $this->getPacConf()['language'] ?: 'en';
        Lang::$en = $this->language === 'en';
        $this->dns      = '1.1.1.1, 8.8.8.8';
        $this->mtu      = 1350;
        $this->limit    = $this->getPacConf()['limitpage'] ?: 5;
        $this->logs = [
            'nginx_default_access',
            'nginx_domain_access',
            'upstream_access',
            'xray',
            'ocserv.log',
            'telemt',
            // caddy (naive): появился вместе с блоком `log` в Caddyfile —
            // раньше вывод уходил в /dev/null и причину падения было не узнать.
            'caddy',
        ];
        $this->reg = '~' . implode('|', [
            'GET / HTTP',
            'GET /favicon.ico HTTP',
            preg_quote($this->getHashBot(1))
        ]) . '~';
        // Значение — порт ВНУТРИ контейнера (setPort строит из него маппинг
        // "внешний:внутренний"). Внешний фолбэк, когда секции сервиса нет в
        // /docker/compose, задаётся отдельно — см. getPorts()/PORT_FALLBACK.
        $this->ports = [
            'hy'    => '443/udp',
            'wg'    => '51820/udp',
            'wg1'   => '51820/udp',
            'ss'    => '8388',
            'ad'    => '853',
            'dnstt' => '53/udp',
            'telemt' => '443',
        ];
    }

    public function input($data = false)
    {
        $this->chatNavigationActive = false;
        $this->admin     = false;
        // Пер-запросный инстанс WG обязан сбрасываться вместе с $this->admin:
        // в polling один объект Bot живёт на ВСЕ апдейты, а action() выставляет
        // $this->wg, только когда сообщение нашлось в карте wg_msg. Кнопка меню
        // wg1 «залипала», и следующая команда без инстанса (например /delete 3
        // на сообщении, которого в карте нет) сносила пира ЧУЖОГО инстанса
        // вместо фолбэка в нулевой.
        $this->wg        = null;
        // Флаг «на callback уже ответили»: см. answer()/callbackCheck().
        $this->callback  = false;
        $this->input_raw = $input = $data ?: json_decode(file_get_contents('php://input'), true);
        $this->input     = [
            'message'           => $input['callback_query']['message']['text'] ?? $input['message']['text'] ?? $input['channel_post']['text'] ?? '',
            // ?? null в конце каждой цепочки: у неучтённых типов апдейтов
            // (edited_message, chat_member, poll_answer, message_reaction) не
            // совпадает ни одна ветка, и последний операнд вычислялся без
            // защиты — warning на каждый такой апдейт. Значение null дальше
            // отсекает auth(), см. там же.
            'message_id'        => $input['callback_query']['message']['message_id'] ?? $input['message']['message_id'] ?? $input['channel_post']['message_id'] ?? null,
            'chat'              => $input['message']['chat']['id'] ?? $input['callback_query']['message']['chat']['id'] ?? $input['channel_post']['chat']['id'] ?? $input['my_chat_member']['chat']['id'] ?? null,
            'from'              => $input['message']['from']['id'] ?? $input['inline_query']['from']['id'] ?? $input['callback_query']['from']['id'] ?? $input['channel_post']['chat']['id'] ?? $input['my_chat_member']['from']['id'] ?? null,
            'username'          => $input['message']['from']['username'] ?? $input['inline_query']['from']['username'] ?? $input['callback_query']['from']['username'] ?? null,
            'query'             => $input['inline_query']['query'] ?? '',
            'inlid'             => $input['inline_query']['id'] ?? '',
            'group'             => !empty($input['message']['chat']['type']) && 'group' == $input['message']['chat']['type'],
            'sticker_id'        => $input['message']['sticker']['file_id'] ?? false,
            'channel'           => !empty($input['channel_post']['message_id']),
            'callback'          => $input['callback_query']['data'] ?? false,
            'callback_id'       => $input['callback_query']['id'] ?? false,
            'photo'             => $input['message']['photo'] ?? false,
            'file_name'         => $input['message']['document']['file_name'] ?? false,
            'file_id'           => $input['message']['document']['file_id'] ?? false,
            'caption'           => $input['message']['caption'] ?? false,
            'reply'             => $input['message']['reply_to_message']['message_id'] ?? false,
            'reply_from'        => $input['message']['reply_to_message']['from']['id'] ??  $input['callback_query']['message']['reply_to_message']['from']['id'] ?? false,
            'reply_text'        => $input['message']['reply_to_message']['text'] ?? false,
            'new_member_id'     => $input['my_chat_member']['new_chat_member']['user']['id'] ?? false,
            'new_member_status' => $input['my_chat_member']['new_chat_member']['status'] ?? false,
        ];
        $this->auth();
        if ($this->admin) {
            $this->session();
            // Отпускаем session lock ДО диспатча: PHP сериализует запросы
            // одного юзера на файловом локе сессии, и долгий хендлер (certbot,
            // рестарты, ssh-пробы) замораживал все следующие нажатия. Чтения
            // $_SESSION дальше работают из памяти; точечные записи идут через
            // stashReply()/takeReply() (reopen → write/read → close).
            session_write_close();
            try {
                $this->action();
            } catch (Throwable $error) {
                $this->actionFailed($error);
            }
        }
        $this->callbackCheck();
        $this->chatNavigationActive = false;
    }

    // Необработанный отказ действия (контейнер не ответил и т. п.): раньше PHP
    // завершался фатальной ошибкой, и кнопка «крутилась» без ответа. Текст
    // сообщения в журнал не пишется: это может быть введённый пароль.
    public function actionFailed(Throwable $error): void
    {
        error_log('action ' . (string) ($this->input['callback'] ?: 'message') . ': ' . get_class($error) . ': '
            . $error->getMessage() . ' @ ' . basename($error->getFile()) . ':' . $error->getLine());
        $text = mb_substr($this->t('Не выполнено: ', 'Not done: ') . $error->getMessage(), 0, 200);
        if (!empty($this->input['callback_id']) && empty($this->callback)) $this->answer($this->input['callback_id'], $text, true);
        elseif (!empty($this->input['chat'])) $this->send($this->input['chat'], self::esc($text));
    }

    /**
     * Проверка Telegram initData для эндпоинтов /webapp$hash/*.
     *
     * Три независимых условия, все обязательны:
     *
     * 1) Подпись. HMAC по отсортированным парам ключ=значение, ключ выводится
     *    из токена бота. Доказывает только то, что initData выдан Telegram
     *    для ЭТОГО бота.
     * 2) Свежесть (auth_date). initData уезжает query-строкой в POST
     *    /webapp$hash/{save,load} и попадал в access_log целиком. Без окна
     *    жизни строка из лога остаётся валидным пропуском НАВСЕГДА, а он даёт
     *    xray.json (uuid/password/subtoken всех клиентов) и запись шаблонов.
     * 3) Владелец (user.id). Подпись не говорит, КТО открыл webapp: Telegram
     *    подписывает initData любого пользователя тем же ключом. Сейчас
     *    не-админ не получает web_app-кнопку (диспетчер админ-гейтед), но это
     *    соглашение, а не проверка, — сверяем со списком админов явно.
     */
    public function webappAuth(array $get, string $key, array $admins, int $maxAge = 86400, ?int $now = null): bool
    {
        // Массив в hash (?hash[]=x) прошёл бы empty() и упёрся в (string) на
        // массиве — «Array to string conversion» и сравнение со строкой «Array».
        if (empty($get['hash']) || !is_string($get['hash'])) {
            return false;
        }
        $t = $get;
        unset($t['hash']);
        ksort($t);
        $s = [];
        foreach ($t as $k => $v) {
            // Любой параметр массивом («?x[]=1») тоже даёт warning на "$k=$v" и
            // мусор в подписываемой строке. Telegram шлёт только скаляры.
            if (!is_scalar($v)) {
                return $this->webappReject('non-scalar param');
            }
            $s[] = "$k=$v";
        }
        $sk = hash_hmac('sha256', $key, 'WebAppData', true);
        if (!hash_equals(hash_hmac('sha256', implode("\n", $s), $sk), $get['hash'])) {
            return $this->webappReject('bad signature');
        }

        $authDate = (int) ($get['auth_date'] ?? 0);
        $now      = $now ?? time();
        if ($authDate <= 0 || $now - $authDate > $maxAge) {
            return $this->webappReject('stale auth_date');
        }

        // Пустой список админов — бот ещё не присвоен (auth() заполняет его
        // первым написавшим). Пускать в этом состоянии некого.
        if (empty($admins)) {
            return $this->webappReject('no admins configured');
        }
        $wu = is_string($get['user'] ?? null) ? json_decode($get['user'], true) : null;
        if (empty($wu['id'])) {
            return $this->webappReject('no user.id');
        }

        if (!in_array((string) $wu['id'], array_map('strval', $admins), true)) {
            // Штатно сюда попадает чужой, но сюда же попадёт и САМ владелец,
            // если бот присвоен каналом/группой: там auth() кладёт в admin
            // chat.id канала, а initData несёт личный user.id нажавшего. Без
            // этой строки редактор шаблонов просто показывал бы «error».
            return $this->webappReject('user is not admin');
        }

        return true;
    }

    /**
     * Причина отказа — в лог, без единого значения из initData: сама строка
     * (в т.ч. hash) остаётся валидным пропуском до истечения окна.
     */
    private function webappReject(string $reason): bool
    {
        error_log("webappAuth: rejected ($reason)");

        return false;
    }

    /**
     * Запись приватного ключа TLS с правами 0600 БЕЗ окна на 0644.
     *
     * file_put_contents создаёт файл по umask, то есть 0644, и ./certs
     * смонтирован в девять контейнеров — ключ был читаем всем. Проставить
     * chmod после записи мало: между созданием и chmod ключ уже лежит на
     * диске с открытыми правами. Поэтому сначала создаём пустой файл и
     * сужаем права, и только потом пишем содержимое.
     */
    public function writePrivateKey(string $path, string $data): bool
    {
        // Пишем во временный файл и подменяем rename'ом: права сужаются, пока
        // файл ещё ПУСТ, а секрет попадает сразу в файл с 0600 — окна на 0644
        // не остаётся вовсе (прежний вариант с touch+chmod сужал его, но не
        // закрывал, вопреки докблоку). rename сохраняет права временного файла
        // и атомарен для читателей.
        $tmp = $path . '.' . bin2hex(random_bytes(8)) . '.tmp';
        $mask = umask(0077);
        $h   = @fopen($tmp, 'x');
        umask($mask);
        if ($h === false) {
            error_log("writePrivateKey: cannot create $tmp");

            return false;
        }
        $ok = @chmod($tmp, 0600) && fwrite($h, $data) === strlen($data) && fflush($h) && fsync($h);
        fclose($h);
        // Результат записи раньше не проверялся: при переполненном диске в
        // ./certs оставался обрезанный ключ, а nginx падал на рестарте.
        if (!$ok || !rename($tmp, $path)) {
            @unlink($tmp);
            error_log("writePrivateKey: $path not written");

            return false;
        }
        // Существовавший ранее файл мог быть создан старой версией с 0644.
        $dir = @fopen(dirname($path), 'r');
        if ($dir === false) return false;
        try { return fsync($dir); }
        finally { fclose($dir); }
    }

    public function auth()
    {
        $file = __DIR__ . '/config.php';
        require $file;
        if (empty($c['admin'])) {
            // Владелец задаётся при установке (VPNBOT_ADMIN_ID). Раньше права
            // владельца получал первый написавший боту — любой посторонний,
            // успевший раньше настоящего владельца. ID отправителя пишется в
            // журнал, чтобы владелец мог вписать свой: 'admin' => [ID].
            if (!empty($this->input['from']) && is_scalar($this->input['from']) && preg_match('~^[1-9][0-9]{0,15}$~D', (string) $this->input['from'])) {
                error_log('vpnbot: owner is not configured; ignored Telegram ID ' . $this->input['from']
                    . ". To make it the owner add 'admin' => [" . $this->input['from'] . '] to app/config.php');
            }
            return;
        } elseif (!is_array($c['admin'])) {
            $c['admin'] = [$c['admin']];
            file_put_contents($file, "<?php\n\n\$c = " . var_export($c, true) . ";\n");
        }
        // Строгое сравнение: addAdmin() кладёт в список СЫРОЙ текст ответа, то
        // есть там может лежать строка, а не int.
        if (in_array((int) $this->input['from'], array_map('intval', (array) $c['admin']), true)) {
            $this->admin = true;
        }
    }

    public function callbackCheck()
    {
        if (empty($this->callback) && !empty($this->input['callback_id'])) {
            // !empty вместо прямого чтения: $GLOBALS['debug'] объявляется только
            // в debug-режиме (см. index.php), и в обычном каждое нажатие кнопки
            // давало «Undefined array key debug». Тот же глобал в ssh() читается
            // именно так.
            $this->answer($this->input['callback_id'], !empty($GLOBALS['debug']) ? $this->input['callback'] : false);
        }
    }

    public function session()
    {
        session_id($this->input['from']);
        @session_start();
        if (!empty($_SESSION['reply'])) {
            if (empty($this->input['reply'])) {
                $pending = [];
                foreach ($_SESSION['reply'] as $k => $v) {
                    // Старые записи не содержат chat: их нельзя безопасно
                    // привязать к текущему чату по одному message_id.
                    if (!isset($v['chat'])) { unset($_SESSION['reply'][$k]); continue; }
                    if ((string) $v['chat'] !== (string) $this->input['chat']) continue;
                    $promptId = str_contains((string) $k, ':') ? (int) substr((string) $k, strrpos((string) $k, ':') + 1) : (int) $k;
                    // Только свежий запрос может принять ответ без пометки reply:
                    // давно брошенный ввод не должен получить случайное сообщение.
                    $pending[$promptId] = [$k, time() - (int) ($v['time'] ?? 0) <= 1800];
                }
                // Ответ без пометки reply (вставка в Telegram Desktop, закрытая
                // панель ответа) раньше отменял запрос: ссылка оставалась в чате
                // и не применялась. В личном чате обычное сообщение — не команда и
                // не кнопка — считается ответом на последний запрос бота.
                $text = (string) ($this->input['message'] ?? '');
                // Личный чат: id чата совпадает с id отправителя. Признак group
                // не покрывает супергруппы (type=supergroup).
                $answer = $pending && empty($this->input['callback']) && empty($this->input['group'])
                    && (string) $this->input['chat'] === (string) $this->input['from']
                    && (($text !== '' && $text[0] !== '/') || !empty($this->input['file_id']));
                if ($answer && $pending[$latest = max(array_keys($pending))][1]) {
                    $this->input['reply'] = $latest;
                    unset($pending[$latest]);
                }
                foreach ($pending as $promptId => [$k]) {
                    $this->delete($this->input['chat'], $promptId);
                    unset($_SESSION['reply'][$k]);
                }
            }
        }
    }

    // Записи в закрытую сессию (input() отпускает lock до action()) молча
    // теряются, поэтому все записи $_SESSION['reply'] идут через эти хелперы:
    // короткий reopen → write → close, лок держится миллисекунды.
    protected function sessionApply(callable $fn)
    {
        $reopened = false;
        if (session_status() !== PHP_SESSION_ACTIVE) {
            session_id((string) $this->input['from']);
            @session_start();
            $reopened = true;
        }
        $fn();
        if ($reopened) {
            session_write_close();
        }
    }

    public function stashReply($r, array $state)
    {
        if (empty($r['result']['message_id'])) {
            return;
        }
        if (in_array($state['callback'] ?? '', ['previewXrayEdit', 'setTimerXr', 'setXrPwd', 'renXrUs', 'saveTrafficXr', 'saveHwidUserLimit', 'extAddSave', 'extRenameSave'], true)) {
            $state['xray_source'] = $this->xrayActionSource ?? '';
        }
        $state['chat'] = $this->input['chat'];
        $state['time'] = time();
        if ($this->protocolReturnMain && in_array($state['callback'] ?? '', ['protocolReply', 'protocolOptionReply', 'protocolRelayReply'], true)) {
            $state['protocol_main'] = true;
        }
        if ($this->protocolRelayOrigin) $state['protocol_relay'] = $this->protocolRelayOrigin;
        if ($this->managedNodeNavigation) $state['managed_node_navigation'] = $this->managedNodeNavigation;
        $this->sessionApply(function () use ($r, $state) {
            $_SESSION['reply'][$state['chat'] . ':' . $r['result']['message_id']] = $state;
        });
    }

    // Забираем reply-state и удаляем его ОДНОЙ операцией под session-lock.
    // Долгие обработчики (OpenConnect, OpenVPN, L2TP/IPsec, IKEv2,
    // TrustTunnel) могут не успеть закончить до повтора webhook Telegram.
    // Если удалять state после callback, оба воркера успевают прочитать его и
    // дважды выполняют действие/рисуют меню. Повторный воркер теперь получает
    // null ещё до начала долгой работы первого.
    protected function takeReply($messageId): ?array
    {
        $state = null;
        $this->sessionApply(function () use ($messageId, &$state) {
            $key = ($this->input['chat'] ?? '') . ':' . $messageId;
            if (!isset($_SESSION['reply'][$key])) $key = $messageId;
            if (isset($_SESSION['reply'][$key]) && !isset($_SESSION['reply'][$key]['chat'])) {
                unset($_SESSION['reply'][$key]);
                return;
            }
            if (isset($_SESSION['reply'][$key]) && is_array($_SESSION['reply'][$key])
                && (string) $_SESSION['reply'][$key]['chat'] === (string) $this->input['chat']) {
                $state = $_SESSION['reply'][$key];
                unset($_SESSION['reply'][$key]);
            }
        });

        return $state;
    }

    public function sd($var, $log = false, $json = false, $raw = false)
    {
        if ($log) {
            if ($json) {
                file_put_contents('/logs/debug', json_encode($var, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES));
            } elseif ($raw) {
                file_put_contents('/logs/debug', $var);
            } else {
                file_put_contents('/logs/debug', var_export($var, true));
            }
        } else {
            $this->send($this->input['chat'], var_export($var, true), $this->input['message_id']);
        }
    }

    private ?string $xrayActionSource = null;

    private static function xrayCallbackIndex(string $command): ?int
    {
        $command = preg_replace('~^wg[01]:~', '', $command);
        if (preg_match('~^/(?:userXr|switchXr|delxr|renameXrUser|changeXrPwd|genXrPwd|resetXrUser|setTrafficXr|timerXr|regenIdXr|rotateSub|hwidUser|hwidUserToggle|hwidUserDefault|setHwidUserLimit|hwidUserDel|extUser|extAdd|extRename|extToggle|extDel|setVlessLink|clientLogClear) ([0-9]+)(?:[ _]|$)~D', $command, $m)) return (int) $m[1];
        if (preg_match('~^/templateUser \w+ ([0-9]+)$~D', $command, $m)) return (int) $m[1];
        if (preg_match('~^/choiceTemplate [a-z]+_([0-9]+)(?:_|$)~D', $command, $m)) return (int) $m[1];
        return null;
    }

    // Full 128-bit identity for state-changing buttons. The compact template
    // route uses a 64-bit locator and resolves exactly one full identity before dispatch.
    public function xrayIdentityButtons(array $buttons, array $xray): array
    {
        foreach ($buttons as &$row) foreach ($row as &$button) {
            $command = $button['callback_data'] ?? '';
            if (!is_string($command) || self::xrayIdentityTokened($command)) continue;
            $index = self::xrayCallbackIndex($command);
            $client = $index === null ? null : ($xray['inbounds'][0]['settings']['clients'][$index] ?? null);
            if ($client === null) continue;
            $source = ManagedProtocol::xraySource($client);
            if (preg_match('~^/choiceTemplate ([a-z]+)_[0-9]+(?:_(.*))?$~D', $command, $m)) {
                $token = rtrim(strtr(base64_encode(hex2bin(substr($source, 0, 16))), '+/', '-_'), '=');
                $tokened = '/ct ' . $token . ' ' . $m[1] . ' ' . (($m[2] ?? '') ?: '-');
            } else {
                $token = rtrim(strtr(base64_encode(hex2bin($source)), '+/', '-_'), '=');
                $tokened = $command . ' !' . $token;
            }
            // Telegram rejects the whole keyboard when one callback exceeds 64 bytes.
            if (strlen($tokened) <= 64) $button['callback_data'] = $tokened;
        }
        unset($row, $button);
        return $buttons;
    }

    private static function xrayIdentityTokened(string $command): bool
    {
        return str_starts_with($command, '/ct ') || (bool) preg_match('~ ![A-Za-z0-9_-]{22}\z~', $command);
    }

    // Every keyboard leaves through send()/update(): a button that addresses an
    // Xray user by number gets that user's token here, so a screen that built
    // it without one (connection log, help, ...) does not turn its Back into
    // "The user list has changed". Already tokened buttons keep their token.
    public function xrayIdentityKeyboard($buttons)
    {
        if (!is_array($buttons)) return $buttons;
        foreach ($buttons as $row) foreach ((array) $row as $button) {
            $command = is_array($button) ? ($button['callback_data'] ?? null) : null;
            if (is_string($command) && !self::xrayIdentityTokened($command) && self::xrayCallbackIndex($command) !== null)
                return $this->xrayIdentityButtons($buttons, $this->getXray() ?: []);
        }
        return $buttons;
    }

    private function xrayClientMatches(int $index): bool
    {
        $client = $this->getXray()['inbounds'][0]['settings']['clients'][$index] ?? null;
        return $client !== null && ($this->xrayActionSource === null
            || hash_equals($this->xrayActionSource, ManagedProtocol::xraySource($client)));
    }

    private function staleXrayAction(): void
    {
        if (!empty($this->input['callback_id'])) $this->answer($this->input['callback_id'], $this->i18n('confirm stale'), true);
        else $this->send($this->input['chat'] ?? '', $this->i18n('confirm stale'));
        $this->xray();
    }

    public function action()
    {
        $previous = $this->xrayActionSource;
        $this->xrayActionSource = null;
        try { return $this->actionDispatch(); }
        finally { $this->xrayActionSource = $previous; }
    }

    private function actionDispatch()
    {
        $command = (string) ($this->input['callback'] ?? '');
        if (preg_match('~^/ct ([A-Za-z0-9_-]{11}) ([a-z]+) ([A-Za-z0-9+/=]+|-)\z~', $command, $m)) {
            $bytes = base64_decode(strtr($m[1], '-_', '+/') . '=', true);
            $matches = [];
            if (is_string($bytes) && strlen($bytes) === 8) foreach ($this->getXray()['inbounds'][0]['settings']['clients'] ?? [] as $index => $client) {
                $source = ManagedProtocol::xraySource($client);
                if (hash_equals(bin2hex($bytes), substr($source, 0, 16))) $matches[$index] = $source;
            }
            if (count($matches) !== 1) return $this->staleXrayAction();
            $index = array_key_first($matches); $this->xrayActionSource = $matches[$index];
            $this->input['callback'] = '/choiceTemplate ' . $m[2] . '_' . $index . ($m[3] === '-' ? '' : '_' . $m[3]);
        } elseif (preg_match('~^(.*) !([A-Za-z0-9_-]{22})\z~s', $command, $m)) {
            $bytes = base64_decode(strtr($m[2], '-_', '+/') . '==', true);
            if (!is_string($bytes) || strlen($bytes) !== 16 || self::xrayCallbackIndex($m[1]) === null) return $this->staleXrayAction();
            $this->xrayActionSource = bin2hex($bytes);
            $this->input['callback'] = $m[1];
        } elseif (self::xrayCallbackIndex($command) !== null) {
            // Pre-upgrade numeric buttons have no stable target and cannot mutate a replacement user.
            return $this->staleXrayAction();
        }

        $this->chatNavigationStart();
        $this->managedNodeNavigationStart();
        try { $this->managedNodeTrackScreen(); } catch (Throwable $e) { /* Navigation must never fail on node state. */ }
        $telemtRoute = (string) (($this->input['callback'] ?? '') ?: ($this->input['message'] ?? ''));
        if (preg_match('~^(?:/telemt(?:[A-Z]|$)|/tuc? )~', $telemtRoute) && !$this->protocolModuleEnabled('telemt')) {
            if ($this->admin) $this->protocolModulesMenu();
            return;
        }
        // Carry the entry point in each callback, including old messages and concurrent chats.
        $this->protocolReturnMain = false;
        if (!empty($this->input['callback']) && preg_match('~^/!(protocol|pr|prset|prmanage|po|ps|pf|menuhelp) ~', $this->input['callback'])) {
            $this->protocolReturnMain = true;
            $this->input['callback'] = '/' . substr($this->input['callback'], 2);
        }
        $this->protocolNavigationStart();
        // Инстанс нажатого сообщения (карта wg_msg.json) — пер-запросный
        // $this->wg: кнопки без инстанса в callback_data (delete, client,
        // torrent…) действуют на инстанс СВОЕГО меню, а не на глобальный
        // указатель. Явные роуты с инстансом ниже перекрывают через selectWG.
        if (!empty($this->input['callback']) && ($mi = $this->getWgMsg()) !== null) {
            $this->wg = (int) $mi;
        }
        // Инстанс, вшитый в саму кнопку (cbWG, см. WG_CB_INST) — сильнее карты:
        // он не зависит ни от её вытеснения, ни от того, чем перерисовали
        // сообщение. Снимаем префикс здесь, чтобы роуты ниже разбирали команду
        // в прежнем виде. selectWG (а не просто $this->wg) — как в роуте
        // «/menu wg <inst>»: остальные кнопки того же меню, отрисованные до
        // деплоя и потому без префикса, должны резолвиться в тот же инстанс.
        if (!empty($this->input['callback'])
            && preg_match('~^wg(?P<inst>[01]):(?P<cb>.+)$~s', $this->input['callback'], $mw)) {
            $this->selectWG($mw['inst']);
            $this->input['callback'] = $mw['cb'];
        }
        switch (true) {
            case preg_match('~^/ag(?: (list|new|show|rename|members)(?: ([a-f0-9]{10})(?: ([0-9]{1,6}))?)?)?$~D', $this->input['callback'], $m):
                $this->accessGroupCommand($m[1] ?? 'list', $m[2] ?? '', '', (int) ($m[3] ?? 0));
                break;
            case preg_match('~^/agxr ([a-f0-9]{10}) ([0-9]{1,6})$~D', $this->input['callback'], $m):
                $this->groupXrayPrompt($m[1], (int) $m[2]);
                break;
