                $this->xrayStatsUser();
                $this->xray((int) ($m[1] ?? 0));
                break;
            case preg_match('~^/xray(?: (\d+))?$~', $this->input['callback'], $m):
                $this->xray(($m[1] ?? '') ?: 0);
                break;
            case preg_match('~^/xtlsblock(?: (\d+))?$~', $this->input['callback'], $m):
                $this->xtlsblock(($m[1] ?? '') ?: 0);
                break;
            case preg_match('~^/routes(?: (\d+))?$~', $this->input['callback'], $m):
                $this->routes(($m[1] ?? '') ?: 0);
                break;
            case preg_match('~^/routeshelp(?: (\d+))?$~', $this->input['callback'], $m):
                $this->routesHelp((int) ($m[1] ?? 0));
                break;
            case preg_match('~^/tun$~', $this->input['callback'], $m):
                $this->tun();
                break;
            case preg_match('~^/tunpackage(?: (\d+))?$~', $this->input['callback'], $m):
                $this->tunpackage(($m[1] ?? '') ?: 0);
                break;
            case preg_match('~^/tunpackagemode$~', $this->input['callback'], $m):
                $this->tunpackagemode();
                break;
            case preg_match('~^/tunprocessmode$~', $this->input['callback'], $m):
                $this->tunprocessmode();
                break;
            case preg_match('~^/tunprocess(?: (\d+))?$~', $this->input['callback'], $m):
                $this->tunprocess(($m[1] ?? '') ?: 0);
                break;
            case preg_match('~^/xtlswarp(?: (\d+))?$~', $this->input['callback'], $m):
                $this->xtlswarp(($m[1] ?? '') ?: 0);
                break;
            case preg_match('~^/xtlsproxy(?: (\d+))?$~', $this->input['callback'], $m):
                $this->xtlsproxy(($m[1] ?? '') ?: 0);
                break;
            case preg_match('~^/xtlsapp(?: (\d+))?$~', $this->input['callback'], $m):
                $this->xtlsapp(($m[1] ?? '') ?: 0);
                break;
            case preg_match('~^/xtlsprocess(?: (\d+))?$~', $this->input['callback'], $m):
                $this->xtlsprocess(($m[1] ?? '') ?: 0);
                break;
            case preg_match('~^/xtlssubnet(?: (\d+))?$~', $this->input['callback'], $m):
                $this->xtlssubnet(($m[1] ?? '') ?: 0);
                break;
            case preg_match('~^/xtlsrulesset(?: (\d+))?$~', $this->input['callback'], $m):
                $this->xtlsrulesset(($m[1] ?? '') ?: 0);
                break;
            case preg_match('~^/xtlsdat(?: (\d+))?$~', $this->input['callback'], $m):
                $this->xtlsdat(($m[1] ?? '') ?: 0);
                break;
            case preg_match('~^/datrefresh$~', $this->input['callback'], $m):
                $this->datRefresh();
                break;
            case preg_match('~^/datschedule$~', $this->input['callback'], $m):
                $this->datSchedule();
                break;
            case preg_match('~^/datscheduleset (\d+)$~', $this->input['callback'], $m):
                $this->datScheduleSet((int) $m[1]);
                break;
            case preg_match('~^/datschedulecustom$~', $this->input['callback'], $m):
                $this->datScheduleCustom();
                break;
            case preg_match('~^/datschedulehour (\d{1,2}|off)$~', $this->input['callback'], $m):
                $this->datScheduleHour($m[1] === 'off' ? null : (int) $m[1]);
                break;
            case preg_match('~^/datfiles$~', $this->input['callback'], $m):
                $this->datFiles();
                break;
            case preg_match('~^/datcats (k[0-9a-f]{12})(?: (\d+))?(?: ([a-z0-9!@._-]{1,24}))?$~D', $this->input['callback'], $m):
                $this->datCats($m[1], (int) ($m[2] ?? 0), $m[3] ?? '');
                break;
            case preg_match('~^/datcatsearch (k[0-9a-f]{12})$~', $this->input['callback'], $m):
                $this->datCatSearch($m[1]);
                break;
            case preg_match('~^/templateCopy (\w+)(?: (.+))?$~', $this->input['callback'], $m):
                $this->templateCopy($m[1], $m[2] ?? false);
                break;
            case preg_match('~^/delTemplate (\w+)(?: (.+))?$~', $this->input['callback'], $m):
                $this->delTemplate($m[1], $m[2] ?? false);
                break;
            case preg_match('~^/downloadOrigin (\w+)$~', $this->input['callback'], $m):
                $this->downloadOrigin($m[1]);
                break;
            case preg_match('~^/downloadTemplate (\w+)(?: (.+))?$~', $this->input['callback'], $m):
                $this->downloadTemplate($m[1], $m[2] ?? false);
                break;
            case preg_match('~^/defaultTemplate (\w+)(?: (.+))?$~', $this->input['callback'], $m):
                $this->defaultTemplate($m[1], $m[2] ?? false);
                break;
            case preg_match('~^/resetTemplate (sing|clash) ([A-Za-z0-9+/=]{1,40})( yes)?$~D', $this->input['callback'], $m):
                $this->resetTemplate($m[1], $m[2], !empty($m[3]));
                break;
            case preg_match('~^/templates (\w+)$~', $this->input['callback'], $m):
                $this->templates($m[1]);
                break;
            case preg_match('~^/templateAdd (\w+)$~', $this->input['callback'], $m):
                $this->templateAdd($m[1]);
                break;
            case preg_match('~^/changeFakeDomain$~', $this->input['callback'], $m):
                $this->changeFakeDomain();
                break;
            case preg_match('~^/autoCleanLogs$~', $this->input['callback'], $m):
                $this->autoCleanLogs();
                break;
            case preg_match('~^/selfFakeDomain$~', $this->input['callback'], $m):
                $this->selfFakeDomain();
                break;
            case preg_match('~^/checkFakeDomain$~', $this->input['callback'], $m):
                $this->checkFakeDomain();
                break;
            case preg_match('~^/include (\w+)$~', $this->input['callback'], $m):
                $this->include($m[1]);
                break;
            case preg_match('~^/dedupeList (\w+)(?: (\d+))?$~', $this->input['callback'], $m):
                $this->dedupeList($m[1], (int) ($m[2] ?? 0));
                break;
            case preg_match('~^/exclude (\d+)$~', $this->input['callback'], $m):
                $this->exclude($m[1]);
                break;
            case preg_match('~^/reverse (\d+)$~', $this->input['callback'], $m):
                $this->reverse($m[1]);
                break;
            case preg_match('~^/subzones (\d+)$~', $this->input['callback'], $m):
                $this->subzones($m[1]);
                break;
            case preg_match('~^/proxy$~', $this->input['callback'], $m):
                $this->proxy();
                break;
            case preg_match('~^/addOverrideHtml$~', $this->input['callback'], $m):
                $this->addOverrideHtml();
                break;
            case preg_match('~^/export$~', $this->input['callback'], $m):
                if (!$this->pinBackup()) $this->send($this->input['chat'], $this->i18n('backup create failed'));
                break;
            case preg_match('~^/import$~', $this->input['callback'], $m):
                $this->import();
                break;
            case preg_match('~^/importList (\w+)$~', $this->input['callback'], $m):
                $this->importList($m[1]);
                break;
            case preg_match('~^/rename (?P<arg>\d+(?:_(?:-)?\d+)?)$~', $this->input['callback'], $m):
                $this->rename(...explode('_', $m['arg']));
                break;
            case preg_match('~^/timer (?P<arg>\d+(?:_(?:-)?\d+)?)$~', $this->input['callback'], $m):
                $this->timer(...explode('_', $m['arg']));
                break;
            case !empty($this->input['reply']):
                $this->reply();
                break;
        }
    }

    // ── telemt (TeleMT) ─────────────────────────────────────────────────
    // MTProto-прокси (Rust, fake-TLS) из проекта telemt/telemt. Конфиг
    // хранится в pac-conf (telemt_*), сам telemt.toml перегенерируется при
    // каждом рестарте.
    public function telemtBool(array $conf, string $key, bool $default = false): bool
    {
        return array_key_exists($key, $conf) ? !empty($conf[$key]) : $default;
    }

    // Дефолты masking-флагов telemt. mask_shape_hardening у telemt включён по
    // умолчанию (дёшево, работает только на mask-пути, ломает shape-анализ при
    // активном пробинге) — не глушим его на свежем конфиге. Остальные — off.
    public function telemtMaskDefault(string $key): bool
    {
        return $key === 'telemt_mask_hardening';
    }

    public function telemtInt(array $conf, string $key, int $default, int $min, int $max): int
    {
        $value = (int) ($conf[$key] ?? $default);
        return max($min, min($max, $value));
    }

    public function telemtState(bool $enabled): string
    {
        return $this->i18n($enabled ? 'on' : 'off');
    }

    public function telemtToml($conf = false)
    {
        [$conf] = $this->normalizeTelemtUsers($conf ?: $this->getPacConf());
        $domain = $conf['telemt_domain'] ?? 'www.google.com';
        $users  = $conf['telemt_users'] ?? [];
        $userEnabled = is_array($conf['telemt_user_enabled'] ?? null) ? $conf['telemt_user_enabled'] : [];
        $limits = $this->telemtLimitsOf($conf);
        $beobachten = $this->telemtBool($conf, 'telemt_beobachten', false);
        $beobachtenMinutes = $this->telemtInt($conf, 'telemt_beobachten_minutes', 10, 1, 1440);
        $maskHardening = $this->telemtBool($conf, 'telemt_mask_hardening', $this->telemtMaskDefault('telemt_mask_hardening'));
        $maskTiming = $this->telemtBool($conf, 'telemt_mask_timing', $this->telemtMaskDefault('telemt_mask_timing'));
        // Готовность WEB-режима считаем один раз: она нужна и листенеру, и
        // секции [web] в самом конце файла.
        $web = $this->telemtWebEnabled($conf);
        // telemt отказывается стартовать, если aggressive/blur включены без
        // mask_shape_hardening (load.rs: "requires mask_shape_hardening = true").
        // UI-тоггл держит инвариант, но импортированный бэкап или правленый
        // pac-conf могут принести несогласованную пару — гасим её здесь, в
        // единственном месте, которое генерирует telemt.toml.
        $maskAggressive = $maskHardening && $this->telemtBool($conf, 'telemt_mask_aggressive', $this->telemtMaskDefault('telemt_mask_aggressive'));
        $maskBlur = $maskHardening && $this->telemtBool($conf, 'telemt_mask_blur', $this->telemtMaskDefault('telemt_mask_blur'));
        $announce = $this->ip;
        $b      = fn($v) => $v ? 'true' : 'false';
        $q      = fn($v) => json_encode((string) $v, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);

        $showLink = implode(', ', array_map($q, array_keys($users)));
        $t  = "show_link = [$showLink]\n\n";
        $t .= "[general]\n";
        // log_level/disable_colors — поля [general] (а не top-level: там telemt
        // их игнорирует). disable_colors убирает ANSI-escape из /logs/telemt;
        // env NO_COLOR telemt не читает, только этот ключ.
        $t .= "log_level = \"normal\"\n";
        $t .= "disable_colors = true\n";
        $t .= "prefer_ipv6 = false\n";
        $t .= "fast_mode = true\n";
        $t .= "beobachten = " . $b($beobachten) . "\n";
        $t .= "beobachten_minutes = $beobachtenMinutes\n";
        // beobachten пишет наблюдения JA3/JA4 в файл (НЕ в HTTP-API). Кладём
        // его в data-path (/telemt/data ⇄ host ./config/telemt/data ⇄ php
        // /config/telemt/data), чтобы бот читал журнал напрямую, без API.
        $t .= "beobachten_file = " . $q('/telemt/data/beobachten.txt') . "\n";
        $t .= "use_middle_proxy = false\n\n";
        // Ровно один режим активен (radio). Секрет ссылки зависит от него:
        // classic = <hex>, secure = dd<hex>, tls = ee<hex><domainHex>
        // (linkTelemt держит ту же логику). Невалидное значение → tls.
        $mode = $this->telemtModeOf($conf);
        $t .= "[general.modes]\n";
        $t .= "classic = " . $b($mode === 'classic') . "\n";
        $t .= "secure = " . $b($mode === 'secure') . "\n";
        $t .= "tls = " . $b($mode === 'tls') . "\n\n";
        $t .= "[server]\n";
        // В бридж-сети vpnbot telemt всегда слушает 443 внутри контейнера;
        // наружу порт пробрасывается через override (setPort), как у tg.
        $t .= "port = 443\n";
        $t .= "listen_addr_ipv4 = \"0.0.0.0\"\n\n";
        // Управляющий HTTP-API нужен боту для расширенной диагностики
        // (/v1/* эндпоинты: health, stats, security posture), квот и учёта
        // подключений (BotTelemtActivity). Включён всегда, строго на loopback внутри
        // контейнера (listen 127.0.0.1 + whitelist). Наружу 9091 НЕ
        // публикуется (нет ports: в compose), дополнительно режется nft на
        // хосте; бот ходит к API по ssh изнутри контейнера. auth_header пуст —
        // loopback-изоляции network namespace достаточно (как в upstream
        // prod-образе). Для квот API снимает контрольные записи расхода.
        $t .= "[server.api]\n";
        $t .= "enabled = true\n";
        $t .= "listen = \"127.0.0.1:9091\"\n";
        $t .= "whitelist = [\"127.0.0.1/32\", \"::1/128\"]\n";
        // read_only отключает ТОЛЬКО изменяющие маршруты, все GET-эндпоинты
        // остаются — а бот ходит сюда исключительно GET'ами (telemtApiFetch).
        // Без него API без аутентификации отдаёт PATCH /v1/config (вместе с
        // секцией [web]), /v1/users (создание, удаление и ротация секретов) и
        // POST /v1/runtime/web/* — с 3.5.6 среди них lifecycle pause/drain/
        // resume, то есть выключение приёма WEB-трафика одним запросом. Защита
        // и так держится на сетевой изоляции, но диагностике право на запись не
        // нужно вовсе.
        $t .= "read_only = true\n\n";
        $t .= "[[server.listeners]]\n";
        $t .= "ip = \"0.0.0.0\"\n";
        // telemt отвергает пустой announce_ip ("invalid IP address syntax") и не
        // стартует вовсе. getenv('IP') бывает пуст, когда стек подняли не через
        // make (make экспортирует IP из hostname -I; .env держит IP пустым, а
        // bare `docker compose up` даёт IP=""). В этом случае ключ опускаем —
        // telemt сам определит announce-адрес, а не падает.
        if ($announce !== '') {
            $t .= "announce_ip = " . $q($announce) . "\n";
        }
        $t .= "\n";
        // WEB-листенер: отдельный plain-HTTP порт для трафика, который к нам
        // приводит ng (см. блок #-tgweb в nginx.conf). Пишем его ТОЛЬКО когда
        // WEB реально настроен: telemt отвергает конфиг, где WEB-листенер есть,
        // а [[web.vhosts]] пуст, и тогда не поднимется весь прокси целиком.
        // proxy_protocol/reuse_allow/announce_ip для transport=web запрещены
        // самим telemt — здесь их нет намеренно.
        if ($web) {
            $t .= "[[server.listeners]]\n";
            $t .= "ip = \"0.0.0.0\"\n";
            $t .= "port = " . self::TELEMT_WEB_PORT . "\n";
            $t .= "transport = \"web\"\n";
            $t .= "proxy_protocol = false\n";
            $t .= "web_client_ip_source = \"x_forwarded_for\"\n";
            $t .= "web_trusted_proxy_cidrs = [" . $q(self::TELEMT_WEB_TRUSTED_CIDR) . "]\n\n";
        }
        // Fake-TLS домен указывает на нас самих → маршрутим mask/tls_front мимо
        // хайрпина, прямо на upstream-nginx (см. telemtMaskIsSelf). Ключ
        // адресный: переопределяется ровно пара host:port, всё остальное, включая
        // соединения с DC Telegram, резолвится как прежде.
        if ($this->telemtMaskIsSelf($conf, $domain)) {
            $t .= "[network]\n";
            $t .= "dns_overrides = [" . $q("$domain:443:" . self::TELEMT_MASK_SELF_IP) . "]\n\n";
        }
        $t .= "[censorship]\n";
        $t .= "tls_domain = " . $q($domain) . "\n";
        $t .= "mask = true\n";
        // Поведение на ClientHello с ЧУЖИМ SNI (active-probe / сканер портов).
        // Дефолт telemt — "drop" (молча закрыть соединение), но настоящий
        // HTTPS-сервер так не делает: он отдаёт default-vhost или фатальный
        // alert unrecognized_name. Тихий drop сам по себе — пассивный
        // фингерпринт, отличающий прокси от обычного веб-сервера. Ставим
        // "reject_handshake" — на проводе неотличимо от nginx с
        // `ssl_reject_handshake on;` (RFC 6066, alert 112), без cert-mismatch
        // и без исходящего соединения на каждый зонд (в отличие от "mask").
        // Ветка ВАЛИДНОГО SNI + невалидного MTProto по-прежнему уходит в
        // mask-fronting на mask_host (= tls_domain), где и работает весь
        // shape/timing-хардненинг ниже. Значение настраивается в боте
        // (TeleMT -> unknown SNI): mask — прозрачный фронт на mask_host для
        // ЛЮБОГО SNI (FAQ-рекомендация при ошибке "Unknown TLS SNI", удобно при
        // рассинхроне домена ссылки и tls_domain); drop — молчаливое закрытие.
        $sni = $this->telemtSniOf($conf);
        $t .= "unknown_sni_action = \"$sni\"\n";
        $t .= "mask_port = 443\n";
        $t .= "fake_cert_len = 2048\n";
        $t .= "tls_emulation = true\n";
        // Кол-во post-handshake NewSessionTicket. Дефолт telemt И проверенного
        // рабочего конфига = 0. Раньше бот жёстко слал 2
        // «для реализма», но это единственная строка [censorship], меняющая сам
        // КЛИЕНТСКИЙ handshake и отсутствующая в рабочем конфиге — а ровно там
        // клиент рвал связь после TLS («expected 64 bytes, got 0»). Возвращаем
        // дефолт 0; значение можно переопределить ключом telemt_session_tickets.
        $tickets = max(0, min(8, (int) ($conf['telemt_session_tickets'] ?? 0)));
        $t .= "tls_new_session_tickets = $tickets\n";
        $t .= "mask_shape_hardening = " . $b($maskHardening) . "\n";
        $t .= "mask_shape_bucket_floor_bytes = 512\n";
        $t .= "mask_shape_bucket_cap_bytes = 4096\n";
        $t .= "mask_shape_hardening_aggressive_mode = " . $b($maskAggressive) . "\n";
        $t .= "mask_shape_above_cap_blur = " . $b($maskBlur) . "\n";
        $t .= "mask_shape_above_cap_blur_max_bytes = 512\n";
        $t .= "mask_timing_normalization_enabled = " . $b($maskTiming) . "\n";
        $t .= "mask_timing_normalization_floor_ms = 180\n";
        $t .= "mask_timing_normalization_ceiling_ms = 320\n\n";
        $t .= "[access]\n";
        $t .= "user_max_unique_ips_global_each = 0\n";
        $t .= "user_max_unique_ips_mode = \"active_window\"\n";
        $t .= "replay_check_len = 65536\n";
        $t .= "ignore_time_skew = false\n\n";
        $disabledUsers = array_filter(
            array_keys($users),
            fn($name) => array_key_exists($name, $userEnabled) && empty($userEnabled[$name])
        );
        if ($disabledUsers) {
            $t .= "[access.user_enabled]\n";
            foreach ($disabledUsers as $name) {
                $t .= $q($name) . " = false\n";
            }
            $t .= "\n";
        }
        $t .= "[access.users]\n";
        foreach ($users as $name => $secret) {
            $t .= $q($name) . " = " . $q($secret) . "\n";
        }
        foreach (['quota' => 'user_data_quota', 'ips' => 'user_max_unique_ips'] as $field => $table) {
            $values = [];
            foreach ($limits as $name => $row) if (!empty($row[$field])) $values[] = $q($name) . ' = ' . $row[$field];
            // В ядре quota=0 запрещает трафик; безлимит означает отсутствие ключа.
            if ($values) $t .= "\n[access.$table]\n" . implode("\n", $values) . "\n";
        }
        // Период сброса квоты — только при положительной квоте (её требует
        // ядро) и только ядру 3.5.15+: строгий разбор ключей старого ядра
        // отверг бы неизвестную таблицу, и TeleMT не запустился бы.
        $periods = [];
        foreach ($limits as $name => $row) if (!empty($row['period']) && !empty($row['quota'])) $periods[] = $q($name) . ' = ' . $q($row['period']);
        if ($periods && $this->telemtVersionAtLeast(self::TELEMT_QUOTA_PERIOD_MIN)) {
            $t .= "\n[access.user_quota_periods]\n" . implode("\n", $periods) . "\n";
        }
        $deny = [];
        foreach ($limits as $name => $row) if (!empty($row['deny'])) $deny[] = $q($name) . ' = [' . implode(', ', array_map($q, $row['deny'])) . ']';
        if ($deny && $this->telemtVersionAtLeast(self::TELEMT_SOURCE_DENY_MIN)) {
            $t .= "\n[access.user_source_deny]\n" . implode("\n", $deny) . "\n";
        }
        $t .= "\n[[upstreams]]\n";
        $t .= "type = \"direct\"\n";
        $t .= "enabled = true\n";
        $t .= "weight = 10\n";
        // [web] идёт последним: это top-level таблицы, и любой ключ после них
        // уехал бы уже не в те секции.
        if ($web) {
            $t .= "\n[web]\n";
            $t .= "enabled = true\n";
            // Что делать с уже ПРИНЯТЫМ сокетом, когда max_http_connections
            // исчерпан (ключ появился в telemt 3.5.6). Дефолт "drop" — молча
            // закрыть; до клиента это доезжает как 502 от ng (пустой ответ
            // апстрима). "wait" сначала ждёт освобождения обычной ёмкости не
            // дольше web.timeouts.http_overload_timeout_ms (дефолт 250 мс) и
            // только по таймауту отдаёт пустой 503 с Retry-After: 1 — его бридж
            // считает повторяемым и уходит в свой backoff. Ожидание живёт вне
            // accept-цикла и ограничено max_http_overload_connections (дефолт
            // 64, +256 KiB к резервациям envelope), листенер оно не тормозит.
            // Нам это нужнее, чем публичному узлу: пин max_http_connections =
            // 256 вчетверо ниже дефолтного, а ng держит к telemt keepalive-пул
            // на 64 соединения и на всплеске lane-carrier'ов открывает новые.
            // Образ < 3.5.6 ключ игнорирует (warning в лог) и остаётся на
            // "drop" — в меню ключ ничего не обещает, поэтому версионного гейта,
            // в отличие от carriers, здесь нет.
            $t .= "http_connection_capacity_action = \"wait\"\n";
            // lane-carrier'ы (https-lanes, websocket-lanes) дают каждому
            // логическому потоку свои uplink/downlink и снимают HOL-блокировку
            // на уровне протокола. https-lanes нужен HTTP/2 на терминаторе, а
            // websocket-* — проброс Upgrade; и то и другое есть в блоке #-tgweb.
            $cands = $this->telemtWebCandidates($conf);
            if ($cands) {
                // Последний элемент пресета — fallback (web.carrier), остаток —
                // web.carriers. telemt дописывает fallback в конец списка сам и
                // ровно один раз, поэтому в carriers его быть не должно.
                $fallback = array_pop($cands);
                $t .= "carrier = " . $q($fallback) . "\n";
                $t .= "carriers = [" . implode(', ', array_map($q, $cands)) . "]\n";
                // Обучение локально для процесса, живёт в памяти и учитывает
                // только положительный исход — порядок кандидатов подстраивается
                // под то, что реально работает у наших клиентов.
                $t .= "carrier_learning = true\n";
                // conservative: самая широкая выборка перед выводом и никакого
                // ранжирования по IP. На горстке пользователей личного сервера
                // aggressive принимал бы решение по одному наблюдению.
                $t .= "carrier_negotiation_aggressiveness = \"conservative\"\n\n";
            } else {
                $t .= "carrier = " . $q($this->telemtWebCarrierOf($conf)) . "\n\n";
            }
            $t .= "carrier_method = " . $q($this->telemtWebCarrierMethodOf($conf)) . "\n";
            $t .= "conveyor = " . $b($this->telemtBool($conf, 'telemt_web_conveyor', true)) . "\n\n";
            $t .= $this->telemtWebLimitsToml();
            // Отчёты бриджа о событиях ДО рукопожатия (telemt >= 3.5.8). Фича
            // работает только при enabled + sideband + capture_lifecycle, а
            // остальная запись трассы нам не нужна: заголовки, тайминги, кадры
            // и тела выключаем. Краткую запись о каждом запросе (метод, путь,
            // IP, User-Agent) telemt при enabled ведёт всё равно — она живёт
            // только в памяти, в кольце на debug_records_capacity записей.
            // Отчёт читает из него лишь события бриджа (telemtBridgeDiagnostics).
            if ($this->telemtBool($conf, 'telemt_web_diag')) {
                $t .= "[web.debug]\n";
                $t .= "enabled = true\n";
                $t .= "sideband = true\n";
                $t .= "capture_lifecycle = true\n";
                $t .= "capture_headers = false\n";
                $t .= "capture_timings = false\n";
                $t .= "capture_frames = false\n";
                $t .= "body_capture = \"off\"\n\n";
            }
            $decoy = $this->telemtWebDecoyOf($conf);
            if ($decoy !== null && $decoy['name']) {
                // Неразрешимое имя — отказ подготовки конфигурации, то есть
                // telemt не стартует вовсе. Короткий срок держит такой отказ
                // внутри окна, в котором applyTelemt() его ещё замечает.
                $t .= "[web.timeouts]\n";
                $t .= "decoy_resolve_secs = " . self::TELEMT_WEB_DECOY_RESOLVE_SECS . "\n\n";
            }
            $t .= "[[web.vhosts]]\n";
            $t .= "host = " . $q($this->telemtWebHost($conf)) . "\n";
            $path = $this->telemtWebPathOf($conf);
            if ($path !== '') {
                $t .= "base_path = " . $q($path) . "\n";
            }
            // Конкретный публичный адрес на 443: он участвует во внутреннем
            // destination-tuple relay, поэтому 0.0.0.0 и любой другой порт
            // telemt отвергает.
            $address = str_contains((string) $this->ip, ':') ? "[{$this->ip}]" : $this->ip;
            $t .= "public_addr = " . $q("$address:443") . "\n\n";
            $t .= "[web.vhosts.decoy]\n";
            if ($decoy === null) {
                $t .= "mode = \"static_directory\"\n";
                $t .= "directory = " . $q(self::TELEMT_WEB_DECOY_DIR) . "\n";
                $t .= "index = \"index.html\"\n";
            } else {
                $t .= "mode = \"http_upstream\"\n";
                $t .= "upstream = " . $q($decoy['origin']) . "\n";
                // Имя хоста telemt разрешает один раз, при подготовке
                // конфигурации, и закрепляет адрес до следующей (3.5.14+).
                if ($decoy['name']) {
                    $t .= "resolve = \"startup\"\n";
                }
            }
            $secretMode = $this->telemtWebSecretModeOf($conf);
            foreach ($this->telemtWebProfiles($conf) as $name) {
                $t .= "\n[[web.vhosts.profiles]]\n";
                $t .= "user = " . $q($name) . "\n";
                $t .= "secret_mode = " . $q($secretMode) . "\n";
            }
        }
        return $t;
    }

    // Удаление пользователя и смена секрета сначала переписывают telemt.toml, а
    // работающий процесс держит прежние секреты до остановки. Метка снимается
    // только после успешного применения; при отказе (например, остановки) её
    // видит cron (retryTelemtApply) и повторяет, пока отзыв не применится.
    public function telemtApplyPendingPath(): string { return '/config/telemt/apply.pending'; }

    public function restartTelemt()
    {
        return $this->withLock('telemt', function () {
            $pending = $this->telemtApplyPendingPath();
            @mkdir(dirname($pending), 0755, true);
            if (@file_put_contents($pending, (string) time()) === false) error_log('restartTelemt: apply marker was not written');
            $result = $this->applyTelemt();
            @unlink($pending);
            return $result;
        });
    }

    public function retryTelemtApply(): void
    {
        if (!is_file($this->telemtApplyPendingPath()) || !$this->protocolModuleEnabled('telemt')) return;
        try {
            $this->restartTelemt();
        } catch (Throwable $e) {
            error_log('retryTelemtApply: ' . get_class($e));
        }
    }

    public function telemtWriteServiceState(bool $enabled): void
    {
        @mkdir('/config/telemt', 0755, true);
        if (!$this->writePrivateKey('/config/telemt/service-enabled', $enabled ? "1\n" : "0\n")) {
            throw new RuntimeException($this->t('Не удалось сохранить состояние TeleMT', 'Could not save the TeleMT state'));
        }
    }

    public function toggleTelemtService(): void
    {
        if (!$this->admin) return;
        $this->withLock('telemt', function () {
            $modules = new ProtocolModules($this->protocolModulesFile);
            $enabled = $modules->enabled('telemt');
            if ($enabled) {
                // Остановка до смены модуля: ssh() не обращается к выключенным сервисам.
                $this->telemtWriteServiceState(false);
                try { $this->telemtStop(); }
                catch (Throwable $error) { $this->telemtWriteServiceState(true); throw $error; }
            }
            try {
                $modules->set('telemt', !$enabled);
                if (!$enabled) $this->applyTelemt(deferStart: true);
            } catch (Throwable $e) {
                if ($modules->enabled('telemt') !== $enabled) $modules->set('telemt', $enabled);
                $this->telemtWriteServiceState($enabled);
                if ($enabled) $this->applyTelemt();
                throw $e;
            }
        });
        if (!empty($this->getPacConf()['telemt_web'])) $this->cloakNginx();
    }

    // Один порядок блокировок для кнопок и перезапуска: telemt → pac.
    // Старый перезапуск не должен снова разрешать отключённого пользователя.
    public function telemtConfUpdate(callable $fn)
    {
        return $this->withLock('telemt', fn() => $this->telemtSave($fn));
    }

    private function telemtSave(callable $fn)
    {
        return $this->pacConfUpdate($fn);
    }

    protected function applyTelemt(?string $resetQuota = null, bool $deferStart = false)
    {
        if (!$this->protocolModuleEnabled('telemt')) {
            $this->telemtWriteServiceState(false);
            return;
        }
        $conf = $this->telemtSave(function (&$current) {
            [$current] = $this->normalizeTelemtUsers($current);
            return $current;
        });
        @mkdir('/config/telemt/data', 0755, true);
        $web = $this->telemtWebEnabled($conf);
        $limits = $this->telemtLimitsOf($conf);
        if ($limits && !$deferStart) $this->telemtStateRun('version');
        // Snapshot decoy-сайта telemt читает один раз при старте — файл должен
        // существовать РАНЬШЕ запуска бинаря, иначе конфиг не загрузится.
        if ($web) {
            $this->telemtWebDecoy();
        }
        $this->telemtWriteToml($this->telemtToml($conf));
        // После выключения хостовая служба удаляет контейнер. Готовим файлы
        // без SSH: новый контейнер (или супервизор ручного Docker) запустит
        // ядро после освобождения общей блокировки, восстановив квоты.
        if ($deferStart) {
            $this->telemtWriteServiceState(true);
            return;
        }
        $this->telemtWriteServiceState(false);
        $this->telemtStop();
        if ($resetQuota !== null) $this->telemtStateRun('reset', $resetQuota);
        $this->telemtStateRun('prepare', required: (bool) $limits);
        $this->telemtWriteServiceState(true);
        if (empty($conf['telemt_users'])) {
            return;
        }
        $this->ssh('telemt run --data-path /telemt/data /telemt/telemt.toml', 'telemt', false, '/logs/telemt');
        // Страховка последнего рубежа. Невалидную секцию [web] telemt не
        // «игнорирует», а отказывается грузить КОНФИГ ЦЕЛИКОМ — вместе с
        // обычным MTProto-листенером, то есть падает весь прокси. Предусловия
        // (telemtWebEnabled) и лимит профилей закрывают известные причины, но
        // не закроют неизвестные: откат образа telemt на 3.4.x, где ключей
        // [web] ещё нет, ручную правку pac.json, будущее ужесточение
        // валидации в самом telemt.
        // Поэтому: если с WEB процесс не поднялся — выключаем WEB и стартуем
        // заново без него. Лучше потерять WEB, чем весь telemt, и это видно —
        // тумблер в меню окажется выключенным.
        // Ждём до 3 секунд, выходя сразу, как процесс увиден: невалидный конфиг
        // telemt отвергает ДО всех сетевых проб, то есть падает почти мгновенно,
        // а вот появление процесса под нагрузкой может чуть запоздать — плоский
        // sleep 1 дал бы ложный откат.
        $probe = $web ? $this->ssh(
            'i=0; while [ $i -lt 3 ]; do sleep 1; pgrep -x telemt && break; i=$((i+1)); done',
            'telemt'
        ) : '1';
        // Имя хоста своего сайта-приманки telemt разрешает уже после старта
        // процесса: пока ответа DNS нет, pgrep его видит. Ждём дольше срока
        // разрешения и смотрим ещё раз — иначе отказ остался бы незамеченным.
        $decoy = $web ? $this->telemtWebDecoyOf($conf) : null;
        if ($probe && $decoy !== null && $decoy['name']) {
            $probe = $this->ssh('sleep ' . (self::TELEMT_WEB_DECOY_RESOLVE_SECS + 1) . '; pgrep -x telemt', 'telemt');
        }
        // Первая ступень отката — свой сайт-приманка: адрес задаёт администратор,
        // и его доступность от бота не зависит. Возвращаем встроенную страницу.
        if ($web && !$probe && !$this->sshFailed && $decoy !== null) {
            error_log('restartTelemt: telemt не поднялся со своим сайтом-приманкой — возвращаем встроенную страницу');
            $conf = $this->telemtSave(static function (&$current) {
                unset($current['telemt_web_decoy']);
                return $current;
            });
            $this->telemtWriteToml($this->telemtToml($conf));
            $this->ssh('telemt run --data-path /telemt/data /telemt/telemt.toml', 'telemt', false, '/logs/telemt');
            $probe = $this->ssh(
                'i=0; while [ $i -lt 3 ]; do sleep 1; pgrep -x telemt && break; i=$((i+1)); done',
                'telemt'
            );
        }
        // Промежуточная ступень отката: сначала снимаем ТОЛЬКО негоциацию.
        // Незнакомый ключ сам по себе конфиг не рушит (telemt его игнорирует,
        // см. telemtWebNegotiationVersionOk), но НЕВАЛИДНАЯ КОМБИНАЦИЯ значений
        // — рушит: набор кандидатов проверяется совместно с [web.limits]
        // (https-lanes требует max_http_handlers >= 4, WebSocket — свой
        // подбюджет и резерв соединений, обучение — >= 3 записей). Если такая
        // связка когда-нибудь разъедется, дешевле потерять подбор, чем весь
        // WEB: без carriers конфиг заведомо проще и валиден.
        if ($web && !$probe && !$this->sshFailed && $this->telemtWebCandidates($conf)) {
            error_log('restartTelemt: telemt не поднялся с авто-негоциацией carrier — снимаем её и пробуем снова');
            $conf = $this->telemtSave(static function (&$current) {
                $current['telemt_web_negotiation'] = 'off';
                return $current;
            });
            $this->telemtWriteToml($this->telemtToml($conf));
            $this->ssh('telemt run --data-path /telemt/data /telemt/telemt.toml', 'telemt', false, '/logs/telemt');
            $probe = $this->ssh(
                'i=0; while [ $i -lt 3 ]; do sleep 1; pgrep -x telemt && break; i=$((i+1)); done',
                'telemt'
            );
        }
        // sshFailed отделяет «процесс не поднялся» от «контейнер недоступен»:
        // во втором случае выключать WEB не за что, там не работает вообще
        // ничего, и следующий рестарт всё равно всё переделает.
        if ($web && !$probe && !$this->sshFailed) {
            error_log('restartTelemt: telemt не поднялся с секцией [web] — откатываем WEB и стартуем без него');
            $conf = $this->telemtSave(static function (&$current) {
                $current['telemt_web'] = 0;
                return $current;
            });
            $this->telemtWriteToml($this->telemtToml($conf));
            $this->ssh('telemt run --data-path /telemt/data /telemt/telemt.toml', 'telemt', false, '/logs/telemt');
            // Вместе с секцией [web] обязан уйти и блок #-tgweb: иначе nginx
            // остаётся проксировать на листенер, которого больше нет, и
            // WEB-хост отвечает 502 вместо decoy. Рекурсии тут нет —
            // cloakNginx() дёргает restartXray, но не restartTelemt.
            $this->cloakNginx();
        }
        if ($limits) {
            try { $this->telemtStateRun('ready'); }
            catch (Throwable $error) {
                $this->telemtWriteServiceState(false);
                $this->telemtStop();
                throw $error;
            }
        }
    }

    // Вынесено отдельным методом ради тестируемости отката выше: тест
    // подменяет запись файла и ssh, а логика самолечения остаётся настоящей.
    public function telemtWriteToml(string $toml): void
    {
        if (!$this->writePrivateKey('/config/telemt/telemt.toml', $toml)) {
            throw new RuntimeException($this->t('Не удалось записать конфигурацию Telemt; перезапуск отменён', 'Could not write the Telemt configuration; restart cancelled'));
        }
    }

    public function telemtSecret()
    {
        return bin2hex(random_bytes(16));
    }

    // Validated active mode / unknown-SNI policy with safe defaults. NB: keep
    // the bare-access OUT of the in_array ternary — `in_array($conf[k] ?? 'def')
    // ? $conf[k] : 'def'` returns null (E_WARNING) when k is unset, because the
    // true-branch reads the undefined key. Resolve via a temp var instead.
    public function telemtModeOf(array $conf): string
    {
        $m = $conf['telemt_mode'] ?? 'tls';
        return in_array($m, ['classic', 'secure', 'tls'], true) ? $m : 'tls';
    }

    public function telemtSniOf(array $conf): string
    {
        $a = $conf['telemt_unknown_sni'] ?? 'reject_handshake';
        return in_array($a, ['mask', 'reject_handshake', 'drop'], true) ? $a : 'reject_handshake';
    }

    // Куда telemt ходит за НАСТОЯЩИМ TLS-фронтом (tls_emulation клонирует
    // ServerHello с сертификатом) и куда уводит mask-fronting: mask_host, а он
    // по умолчанию равен tls_domain, порт mask_port = 443.
    //
    // Если fake-TLS домен указывает на ЭТОТ ЖЕ сервер (обычный выбор: SNI в
    // ClientHello тогда совпадает с реально существующим сайтом), соединение
    // уезжает на собственный публичный IP и разворачивается хайрпином. Он не
    // работает: DNAT на хосте переписывает адресата на upstream-контейнер, но
    // docker→docker трафик намеренно НЕ SNAT-ится, поэтому SYN-ACK возвращается
    // с адреса контейнера и сокету telemt не соответствует. Фетч висит до
    // таймаута («TLS emulation initial fetch failed» в /logs/telemt),
    // ServerHello подменяется синтетическим сертификатом вместо клона
    // настоящего, а mask-fronting перестаёт отдавать зондам реальный сайт
    // (при unknown_sni_action = mask соединение зонда просто виснет).
    //
    // dns_overrides снимает это без всякого NAT: telemt соединяется напрямую с
    // upstream-nginx — ровно тем же путём, каким приходят внешние клиенты
    // (SNI-preread → ng с proxy_protocol), и получает настоящий сертификат.
    public const TELEMT_MASK_SELF_IP = '10.10.0.10';

    // Указывает ли fake-TLS домен на этот же сервер: сам домен установки, его
    // алиас или поддомен любого из них. Сравнение строковое, без резолва:
    // telemtToml() генерируется на КАЖДЫЙ рестарт telemt, и блокирующий
    // DNS-запрос в этом пути означал бы подвисшее меню при недоступном
    // резолвере. Домен, который админ увёл на чужое имя (дефолт
    // www.google.com), под это не попадает — там внешний фетч и так работает.
    public function telemtMaskIsSelf(array $conf, string $domain): bool
    {
        $domain = strtolower(trim($domain));
        if ($domain === '') {
            return false;
        }
        $own = array_merge(
            [(string) ($conf['domain'] ?? '')],
            is_array($conf['domain_aliases'] ?? null) ? $conf['domain_aliases'] : []
        );
        foreach ($own as $name) {
            $name = strtolower(trim((string) $name));
            if ($name !== '' && ($domain === $name || str_ends_with($domain, ".$name"))) {
                return true;
            }
        }
        return false;
    }

    // ── telemt WEB (тип прокси «WEB» в Telegram Desktop и Android) ──────────
    // telemt >= 3.5.0 умеет нести MTProto внутри ОБЫЧНОГО HTTPS: клиент ходит
    // на 443 отдельного FQDN, TLS терминирует наш ng, а telemt слушает plain
    // HTTP/1.1 на приватном порту в docker-сети. Ссылка — tg://webproxy БЕЗ
    // порта (Telegram Desktop требует ровно 443), секрет только plain или dd:
    // ee (Fake-TLS) в WEB-режиме не поддерживается.
    //
    // Приватный порт WEB-листенера. Наружу НЕ публикуется (в compose у telemt
    // нет ports:), единственный, кто в него ходит, — ng, он же и стоит в
    // web_trusted_proxy_cidrs. Значение продублировано в nginx-шаблоне
    // (upstream telemt_web) — тест держит их в согласии.
    public const TELEMT_WEB_PORT = 8080;
    // Адрес ng в дефолтной сети сборки: тот самый доверенный L7-пир, чьему
    // X-Forwarded-For telemt верит. Тот же литерал уже зашит в listen-строки
    // nginx.conf, так что новой хрупкости не появляется.
    public const TELEMT_WEB_TRUSTED_CIDR = '10.10.0.2/32';
    // web.limits.max_profiles у telemt = 32, и превышение — не «лишние
    // профили молча выброшены», а ОТКАЗ ЗАГРУЗКИ конфига: telemt не стартует
    // вовсе, вместе с обычным MTProto. Режем список здесь, меню сообщает
    // об урезании.
    public const TELEMT_WEB_MAX_PROFILES = 32;
    // Каталог decoy-сайта внутри контейнера telemt (= /config/telemt/decoy у
    // php: ./config/telemt смонтирован в оба).
    public const TELEMT_WEB_DECOY_DIR = '/telemt/decoy';

    // Пресеты авто-негоциации carrier (telemt >= 3.5.4). Значение — ПОЛНЫЙ
    // упорядоченный список кандидатов ВМЕСТЕ с fallback: telemtToml() отрезает
    // последний элемент в web.carrier, а остаток кладёт в web.carriers. Так
    // fallback физически не может продублироваться внутри списка (telemt
    // отвергает дубликаты) и не зависит от кнопки carrier:, которая остаётся
    // жить только в режиме off.
    //
    // Клиент перебирает кандидатов по накопительным дедлайнам [3,5,8,12]s и
    // фиксируется на первом заработавшем; после commit смена carrier невозможна
    // до новой сессии. Кандидатов не больше четырёх — это потолок telemt.
    //
    // fallback именно https, а не https-lanes: нативный клиент БЕЗ метаданных
    // negotiation (сегодня это Telegram iOS) всегда берёт фиксированный
    // web.carrier, а https-lanes он не поддерживает. Desktop от этого ничего
    // не теряет — https-lanes остаётся в списке кандидатов перед fallback.
    public const TELEMT_WEB_NEGOTIATION = [
        'off'   => [],
        'https' => ['https-lanes', 'https'],
        'full'  => ['websocket-lanes', 'websocket', 'https-lanes', 'https'],
    ];

    // Пин [web.limits] под масштаб личного сервера.
    //
    // Зачем вообще пинить: дефолты telemt рассчитаны на публичный узел, и в
    // 3.5.5 заявленный memory_envelope_bytes вырос 768 MiB → 1280 MiB (прежнее
    // значение больше НЕ проходит валидацию: сумма резерваций стала 1011 MiB).
    // На VPS с 2 ГБ это потолок буферов больше самой машины — telemt разрешил
    // бы себе очереди, на которых cgroup убил бы контейнер целиком, вместе с
    // обычным MTProto. С этим блоком раньше срабатывает собственный
    // backpressure telemt, а не OOM-killer.
    //
    // Значения ПРОВЕРЕНЫ против совместной валидации telemt (validate_web.rs и
    // validate_web/{memory,websocket}.rs): сумма резерваций 186.9 MiB при
    // потолке 256 MiB. В 3.5.6 в неё добавились ещё две статьи, обе на
    // дефолтных (не пинуемых нами) ключах: max_http_overload_connections * 4
    // KiB = 256 KiB и max_profiles * 32 B = 1 KiB. Любая правка здесь обязана
    // пройти тест telemt_web_test.php, который пересчитывает те же формулы:
    // ошибка означает не «лишний ключ проигнорирован», а отказ загрузки
    // конфига.
    //
    // web.limits — process-owned: telemt применяет их только при рестарте
    // процесса, а restartTelemt() его и делает.
    public const TELEMT_WEB_LIMITS = [
        // Потолок принятых соединений и одновременных handler'ов. https-lanes
        // требует max_http_handlers >= 4, простой https >= 2.
        'max_http_connections'         => 256,
        'max_http_handlers'            => 128,
        // Очереди relay: главный реальный потребитель памяти.
        'pending_bytes_global'         => 100663296,
        // Подбюджет WebSocket внутри pending_bytes_global.
        'websocket_bytes_global'       => 50331648,
        'max_body_readers'             => 16,
        'max_body_bytes_global'        => 33554432,
        // Snapshot decoy — один index.html.
        'max_static_bytes'             => 8388608,
        'max_sessions_global'          => 64,
        'max_streams_per_session'      => 64,
        // Входит в резервацию lane-state квадратично по сессиям, поэтому 512, а
        // не дефолтные 4096.
        'max_tombstones_per_session'   => 512,
        'max_carrier_learning_entries' => 1024,
        // Кольцо web.debug мы не включаем, но его резервация считается всегда.
        'debug_records_capacity'       => 4096,
        'debug_bytes_global'           => 4194304,
        'memory_envelope_bytes'        => 268435456,
    ];

    public function telemtWebCarrierOf(array $conf): string
    {
        $c = $conf['telemt_web_carrier'] ?? 'https-lanes';
        return in_array($c, ['https', 'https-lanes'], true) ? $c : 'https-lanes';
    }

    // Пресет негоциации. Мусор и отсутствие ключа → off, то есть ровно прежнее
    // поведение: один carrier без перебора.
    public function telemtWebNegotiationOf(array $conf): string
    {
        $n = $conf['telemt_web_negotiation'] ?? 'off';
        return is_string($n) && isset(self::TELEMT_WEB_NEGOTIATION[$n]) ? $n : 'off';
    }

    // Упорядоченный список кандидатов включая fallback; [] когда негоциация
    // выключена.
    public function telemtWebCandidates(array $conf): array
    {
        return self::TELEMT_WEB_NEGOTIATION[$this->telemtWebNegotiationOf($conf)];
    }

    // Ключи web.carriers/carrier_learning появились в 3.5.4. Порог отдельный от
    // telemtWebVersionOk() (3.5.0, сам WEB): бинарь 3.5.0-3.5.3 прекрасно несёт
    // WEB, но про подбор не знает.
    //
    // Гейт защищает НЕ от падения. Проверено на 3.4.25 и на живом 3.5.5:
    // неизвестные ключи telemt всегда лишь логирует («Unknown config key
    // ignored») и продолжает работать; жёсткой ошибкой они становятся только
    // при general.config_strict = true, которого бот не ставит намеренно —
    // иначе любое будущее переименование ключа в telemt роняло бы весь прокси.
    // Без гейта старый бинарь просто игнорировал бы carriers, а меню при этом
    // показывало бы включённый подбор, которого нет: клиент молча получал бы
    // один web.carrier. Гейт закрывает именно это расхождение.
    //
    // Как и у соседа — fail-open на unknown и вызов только из интерактивного
    // пути (проверка ходит по ssh).
    public function telemtWebNegotiationVersionOk(): bool
    {
        $v = $this->telemtVersion();
        if ($v === 'unknown') {
            return true;
        }
        return version_compare(ltrim($v, 'vV'), '3.5.4', '>=');
    }

    // Блок [web.limits]. Отдельным методом — чтобы тест мог сверить отрендеренный
    // toml с константой, а не парсить весь конфиг.
    public function telemtWebLimitsToml(): string
    {
        $t = "[web.limits]\n";
        foreach (self::TELEMT_WEB_LIMITS as $k => $v) {
            $t .= "$k = $v\n";
        }
        return $t . "\n";
    }

    public function telemtWebCarrierMethodOf(array $conf): string
    {
        return ($conf['telemt_web_carrier_method'] ?? 'post') === 'put' ? 'put' : 'post';
    }

    public function telemtWebSecretModeOf(array $conf): string
    {
        $m = $conf['telemt_web_secret_mode'] ?? 'dd';
        return in_array($m, ['plain', 'dd'], true) ? $m : 'dd';
    }

    // Префикс WEB-эндпоинтов (web.vhosts[].base_path, telemt >= 3.5.8). Пусто —
    // прежние корневые маршруты. Непустой уводит бридж и все приватные
    // эндпоинты под /<path>/, а capability привязывается к хосту И пути: смена
    // префикса гасит все выданные ссылки разом, не трогая секреты
    // пользователей. Правила — ровно валидатор telemt (validate_web/vhosts.rs):
    // невалидное значение он не игнорирует, а отвергает конфиг целиком, поэтому
    // мусор из pac.json превращаем в «выключено».
    public function telemtWebPathOf(array $conf): string
    {
        $p = $conf['telemt_web_path'] ?? '';
        return is_string($p) && strlen($p) <= 128
            && preg_match('~^[A-Za-z0-9][A-Za-z0-9_-]*(?:/[A-Za-z0-9][A-Za-z0-9_-]*)*$~D', $p) ? $p : '';
    }

    // ---- Свой сайт-приманка WEB (web.vhosts.decoy = http_upstream) ----------
    // По умолчанию запрос без секрета получает встроенную страницу. Вместо неё
    // telemt может передавать такие запросы на приватный HTTP-origin: по
    // IP-адресу — с появления WEB, по имени хоста — с 3.5.14 (resolve =
    // "startup": имя разрешается при подготовке конфигурации и закрепляется).
    //
    // Всё, что отвечает по этому адресу, становится доступно из интернета под
    // именем WEB-хоста. Поэтому правило telemt («loopback, приватный или
    // link-local адрес») здесь сужено: без loopback контейнера telemt (там его
    // собственный API), без сети самой сборки (панель, unit без аутентификации,
    // AdGuard, Docker API) и без link-local (метаданные облака). Остаются хост
    // — шлюз docker-сети — и прочие приватные адреса.
    public const TELEMT_WEB_DECOY_NAME_MIN     = '3.5.14';
    public const TELEMT_WEB_DECOY_GATEWAY      = '10.10.0.1';
    public const TELEMT_WEB_DECOY_RESOLVE_SECS = 2;

    public static function telemtWebDecoyAddressOk(string $ip): bool
    {
        if (filter_var($ip, FILTER_VALIDATE_IP, FILTER_FLAG_IPV4)) {
            if ($ip === self::TELEMT_WEB_DECOY_GATEWAY) {
                return true;
            }
            $n  = ip2long($ip);
            $in = static fn(string $net, int $bits): bool => ($n >> (32 - $bits)) === (ip2long($net) >> (32 - $bits));
            [$own, $ownBits] = explode('/', self::DOCKER_NET);

            return !$in($own, (int) $ownBits)
                && ($in('10.0.0.0', 8) || $in('172.16.0.0', 12) || $in('192.168.0.0', 16));
        }
        $raw = filter_var($ip, FILTER_VALIDATE_IP, FILTER_FLAG_IPV6) ? inet_pton($ip) : false;

        // fc00::/7. IPv4-mapped адреса (::ffff:a.b.c.d) telemt приватными не считает.
        return $raw !== false && (ord($raw[0]) & 0xfe) === 0xfc;
    }

    // Разбор по правилам telemt (config/load/decoy_dns.rs), но строже. URL-парсер
    // ядра принимает за IPv4 и «127.1», и «0x7f000001», и восьмеричные октеты:
    // здесь IPv4 допускается только каноническим, а имя не может кончаться
    // числом — иначе проверенный адрес и адрес, по которому пойдёт запрос,
    // могли бы разойтись.
    // Возвращает ['origin', 'host', 'port', 'name'] либо ['error' => ключ i18n].
    public static function telemtWebDecoyParse(string $value): array
    {
        $bad = ['error' => 'telemt web decoy bad url'];
        if (!preg_match('~^http://(\[[0-9A-Fa-f:.]+\]|[^\s/:?#@\[\]\\\\]+)(?::(\d{1,5}))?/?$~D', trim($value), $m)) {
            return $bad;
        }
        $host = strtolower($m[1]);
        $port = ($m[2] ?? '') === '' ? 80 : (int) $m[2];
        if ($port < 1 || $port > 65535) {
            return $bad;
        }
        // WEB-листенер слушает 0.0.0.0, и любой адрес на его порту telemt
        // отвергает как петлю на самого себя.
        if ($port === self::TELEMT_WEB_PORT) {
            return ['error' => 'telemt web decoy own port'];
        }
        $name = false;
        if ($host[0] === '[') {
            $ip = substr($host, 1, -1);
            if (!filter_var($ip, FILTER_VALIDATE_IP, FILTER_FLAG_IPV6)) {
                return $bad;
            }
            $ip   = inet_ntop(inet_pton($ip));
            $host = "[$ip]";
        } elseif (preg_match('~^[0-9.]+$~D', $host)) {
            if (!filter_var($host, FILTER_VALIDATE_IP, FILTER_FLAG_IPV4)) {
                return $bad;
            }
            $ip = $host;
        } else {
            $labels = explode('.', $host);
            if (strlen($host) > 253
                || !preg_match('~^[a-z0-9_](?:[a-z0-9_-]{0,61}[a-z0-9_])?(?:\.[a-z0-9_](?:[a-z0-9_-]{0,61}[a-z0-9_])?)*$~D', $host)
                || preg_match('~^(?:\d+|0x[0-9a-f]*)$~D', end($labels))
                || str_contains($host, 'xn--')) {
                return $bad;
            }
            $name = true;
        }
        if (!$name && !self::telemtWebDecoyAddressOk($ip)) {
            return ['error' => 'telemt web decoy not private'];
        }

        return [
            'origin' => 'http://' . $host . (($m[2] ?? '') === '' ? '' : ':' . $port),
            'host'   => $name ? $host : $ip,
            'port'   => $port,
            'name'   => $name,
        ];
    }

    // Сохранённый свой сайт-приманка либо null — встроенная страница. Мусор из
    // pac.json или бэкапа равен отсутствию настройки.
    public function telemtWebDecoyOf(array $conf): ?array
    {
        $value = $conf['telemt_web_decoy'] ?? '';
        if (!is_string($value) || $value === '') {
            return null;
        }
        $decoy = self::telemtWebDecoyParse($value);

        return isset($decoy['error']) ? null : $decoy;
    }

    // Проверка изнутри контейнера telemt — оттуда же пойдут запросы: куда
    // разрешается имя и отвечает ли адрес по HTTP. Отдельным методом — тест
    // подменяет только его.
    public function telemtWebDecoyProbe(array $decoy): ?array
    {
        $code = 'import socket,sys,json,http.client' . "\n"
            . 'h,p,a=sys.argv[1],int(sys.argv[2]),sys.argv[3]' . "\n"
            . 'o={"addresses":[],"status":0,"location":""}' . "\n"
            . 'try:' . "\n"
            . ' for x in socket.getaddrinfo(h,p,type=socket.SOCK_STREAM):' . "\n"
            . '  if x[4][0] not in o["addresses"]:o["addresses"].append(x[4][0])' . "\n"
            . 'except OSError:pass' . "\n"
            . 'if o["addresses"]:' . "\n"
            . ' try:' . "\n"
            . '  c=http.client.HTTPConnection(o["addresses"][0],p,timeout=3);c.request("GET","/",headers={"Host":a})' . "\n"
            . '  r=c.getresponse();o["status"]=r.status;o["location"]=r.getheader("Location") or ""' . "\n"
            . ' except Exception:pass' . "\n"
            . 'print(json.dumps(o))';
        $out = $this->ssh('python3 -c ' . escapeshellarg($code) . ' ' . escapeshellarg($decoy['host']) . ' '
            . (int) $decoy['port'] . ' ' . escapeshellarg(substr($decoy['origin'], 7)), 'telemt');
        $probe = $this->sshFailed ? null : json_decode(trim((string) $out), true);

        return is_array($probe) && is_array($probe['addresses'] ?? null) ? $probe : null;
    }

    // Сохраняет свой сайт-приманку ('' — вернуть встроенную страницу) и
    // перезапускает активный WEB. Возвращает ключ сообщения об отказе либо ''.
    public function telemtWebDecoyApply(string $value): string
    {
        $decoy = null;
        if (trim($value) !== '') {
            $decoy = self::telemtWebDecoyParse($value);
            if (isset($decoy['error'])) {
                return $decoy['error'];
            }
            // Образ старше имя не примет: ключ resolve он сочтёт неизвестным,
            // а сам адрес отвергнет как «не IP-литерал».
            if ($decoy['name'] && !$this->telemtVersionAtLeast(self::TELEMT_WEB_DECOY_NAME_MIN)) {
                return 'telemt web decoy need version';
            }
            $probe = $this->telemtWebDecoyProbe($decoy);
            if ($probe === null) {
                return 'telemt web decoy unchecked';
            }
            if (!$probe['addresses']) {
                return 'telemt web decoy unresolved';
            }
            foreach ($probe['addresses'] as $address) {
                if (!is_string($address) || !self::telemtWebDecoyAddressOk($address)) {
                    return 'telemt web decoy not private';
                }
            }
            if (empty($probe['status'])) {
                return 'telemt web decoy no answer';
            }
            // Перенаправление на сам WEB-хост — петля: запрос вернётся в telemt
            // и снова уйдёт на этот же адрес.
            $target = parse_url((string) ($probe['location'] ?? ''), PHP_URL_HOST);
            $host   = $this->telemtWebHost($this->getPacConf());
            if ((int) $probe['status'] >= 300 && (int) $probe['status'] < 400
                && is_string($target) && $host !== '' && strtolower($target) === $host) {
                return 'telemt web decoy redirect';
            }
        }
        $origin = $decoy['origin'] ?? '';
        $changed = $this->telemtConfUpdate(function (&$conf) use ($origin) {
            if (($conf['telemt_web_decoy'] ?? '') === $origin) {
                return false;
            }
            if ($origin === '') {
                unset($conf['telemt_web_decoy']);
            } else {
                $conf['telemt_web_decoy'] = $origin;
            }

            return true;
        });
        if ($changed && $this->telemtWebEnabled($this->getPacConf())) {
            $this->restartTelemt();
            // Лестница откатов в applyTelemt() могла снять настройку сама.
            if ($origin !== '' && $this->telemtWebDecoyOf($this->getPacConf()) === null) {
                return 'telemt web decoy reverted';
            }
        }

        return '';
    }

    // Порог для ключей 3.5.8 (base_path, web.debug.sideband). Старый бинарь их
    // молча игнорирует: с путём это ссылки, которые сервер не узнаёт, с
    // диагностикой — тумблер без эффекта. Как у соседних гейтов — fail-open на
    // unknown и вызов только из интерактивного пути (проверка ходит по ssh).
    public function telemtVersionAtLeast(string $min): bool
    {
        $v = $this->telemtVersion();
        if ($v === 'unknown') {
            return true;
        }
        return version_compare(ltrim($v, 'vV'), $min, '>=');
    }

    // Хост WEB-vhost: отдельный поддомен основного домена (как у ocserv и
    // naive). Отдельный, а не сам домен, — принципиально: в WEB-режиме vhost
    // уходит в telemt ЦЕЛИКОМ вместе с decoy-политикой, а на основном домене
    // живут панель, подписки и ws/grpc-локации xray. Если отдать telemt только
    // carrier-пути, ответы «обычного» и «аутентифицированного» запроса станут
    // различимы снаружи, то есть ровно то, от чего decoy и защищает.
    public function telemtWebHost(array $conf): string
    {
        $domain = (string) ($conf['domain'] ?? '');
        if ($domain === '' || !$this->isHostname($domain)) {
            return '';
        }
        $sub = $this->getHashSubdomain('tw');
        return $sub === '' ? '' : "$sub.$domain";
    }

    // Пользователи, попадающие в WEB-профили: все заведённые в telemt, но не
    // больше лимита. Профиль ссылается на запись [access.users], поэтому
    // выключенные (user_enabled=false) тоже перечисляем — admission их и так
    // не пустит, зато конфиг не переписывается на каждый тумблер.
    public function telemtWebProfiles(array $conf): array
    {
        $users = is_array($conf['telemt_users'] ?? null) ? array_keys($conf['telemt_users']) : [];
        return array_slice($users, 0, self::TELEMT_WEB_MAX_PROFILES);
    }

    // Чего не хватает для WEB-режима (ключи i18n). Пустой массив — всё готово.
    // Проверки не косметические: telemt ОТКАЗЫВАЕТСЯ грузить конфиг, если
    // public_addr не конкретный адрес на 443 или список профилей пуст, а без
    // сертификата на своё имя Telegram Desktop не откроет соединение.
    public function telemtWebBlockers(array $conf): array
    {
        $out = [];
        if ($this->telemtWebHost($conf) === '') {
            $out[] = 'telemt web need domain';
        } elseif (empty($conf['letsencrypt'])) {
            $out[] = 'telemt web need cert';
        }
        if (!filter_var((string) $this->ip, FILTER_VALIDATE_IP)
            || trim(inet_pton((string) $this->ip), "\0") === '') {
            $out[] = 'telemt web need ip';
        }
        if (!$this->telemtWebProfiles($conf)) {
            $out[] = 'telemt web need users';
        }
        return $out;
    }

    public function telemtWebEnabled(array $conf): bool
    {
        return $this->protocolModuleEnabled('telemt') && !empty($conf['telemt_web']) && !$this->telemtWebBlockers($conf);
    }

    // WEB появился в telemt 3.5.0. Старый бинарь от секции [web] НЕ падает:
    // проверено прогоном нашего конфига на 3.4.25 — он игнорирует и [web], и
    // web-листенер и поднимается обычным MTProto-прокси. Гейт нужен против
    // молчаливого расхождения: ссылки tg://webproxy выданы, а обслуживать их
    // некому. (Невалидные ЗНАЧЕНИЯ — другое дело, они конфиг рушат, см.
    // telemtWebBlockers.) Расхождение реально: код app/ приезжает bind-mount'ом и
    // обновляется НЕЗАВИСИМО от образа telemt, так что новый бот со старым
    // образом — штатная промежуточная ситуация. Проверка ходит по ssh, поэтому
    // живёт только в интерактивном пути (меню и тумблер), а не в telemtToml.
    public function telemtWebVersionOk(): bool
    {
        $v = $this->telemtVersion();
        if ($v === 'unknown') {
            return true;
        }
        return version_compare(ltrim($v, 'vV'), '3.5.0', '>=');
    }

    // Секрет ссылки tg://webproxy. Формат задаёт secret_mode ПРОФИЛЯ и он не
    // связан с [general.modes] обычного MTProto-листенера (telemt разводит их
    // в mode_enabled_for_proto_with_policy): tls (ee) на TCP-пути и dd в WEB
    // прекрасно уживаются на одном пользователе.
    public function linkTelemtWeb($name, $conf = false)
    {
        if (!$this->protocolModuleEnabled('telemt')) return '';
        $conf = is_array($conf) ? $conf : $this->getPacConf();
        $secret = $conf['telemt_users'][$name] ?? '';
        if ($secret === '') {
            return '';
        }
        $host = $this->telemtWebHost($conf);
        if ($host === '') {
            return '';
        }
        $dd   = $this->telemtWebSecretModeOf($conf) === 'dd';
        $path = $this->telemtWebPathOf($conf);
        if ($path !== '') {
            // Ссылка на префикс — другой формат Telegram Desktop (тот же, что
            // печатает сам telemt, maestro/helpers/runtime.rs): server несёт
            // «host/path», а секрет — base64url без паддинга от маркера 0x70,
            // байта 0xdd для dd-режима и сырых 16 байт секрета. Hex-строка тут
            // уже не принимается. preg_match, а не ctype_xdigit: расширения
            // ctype в php-образе нет, и вызов был бы фаталом.
            $bin = is_string($secret) && preg_match('~^(?:[0-9a-fA-F]{2})+$~D', $secret) ? hex2bin($secret) : false;
            if ($bin === false) {
                return '';
            }
            $host  .= "/$path";
            $secret = rtrim(strtr(base64_encode("\x70" . ($dd ? "\xdd" : '') . $bin), '+/', '-_'), '=');
        } elseif ($dd) {
            $secret = "dd$secret";
        }
        // Порта в ссылке нет намеренно: Telegram Desktop принимает WEB-прокси
        // только на 443 и ссылку с портом отвергает.
        return 'tg://webproxy?' . http_build_query([
            'server' => $host,
            'secret' => $secret,
        ], '', '&', PHP_QUERY_RFC3986);
    }

    // Обычный сайт, который telemt отдаёт на неаутентифицированные запросы.
    // Берём static_directory, а не http_upstream: единственный приватный
    // HTTP-origin в сборке (ng:80) отвечает 301 на https://$host — на своём же
    // vhost это петля редиректа, то есть заметнее любого статического 404.
    // Snapshot читается ОДИН раз при старте telemt, поэтому файл пишем до
    // запуска бинаря (restartTelemt).
    public function telemtWebDecoy(): void
    {
        $dir = $this->telemtDecoyDir;
        if (is_link($dir) || (!is_dir($dir) && !@mkdir($dir, 0755, true))) {
            throw new RuntimeException($this->t('Не удалось создать каталог страницы TeleMT', 'Could not create the TeleMT page directory'));
        }
        $file = "$dir/index.html";
        $css = "$dir/loading.css";
        if (is_link($file) || is_link($css)) {
            throw new RuntimeException($this->t('Файлы страницы TeleMT не должны быть символическими ссылками', 'TeleMT page files must not be symbolic links'));
        }
        $template = __DIR__ . '/telemt-decoy';
        // Обновляем только прежнюю штатную «It works!» или наш текущий HTML.
        // Страницу и CSS, изменённые администратором, сохраняем.
        $existing = is_file($file) ? hash_file('sha256', $file) : null;
        $current = hash_file('sha256', "$template/index.html");
        if ($existing !== null && !in_array($existing, [
            '4a46bda8c97f74bb2deb2791008c6ffde525da0b73b181f9c5557e21d973ee2a',
            $current,
        ], true)) {
            return;
        }
        // Сначала CSS, затем HTML: ошибка записи не публикует неполную страницу.
        foreach (['loading.css', 'index.html'] as $name) {
            $target = "$dir/$name";
            if (($name === 'loading.css' && is_file($target))
                || ($name === 'index.html' && $existing === $current)) {
                continue;
            }
            $body = file_get_contents("$template/$name");
            $tmp = tempnam($dir, '.decoy-');
            try {
                if ($body === false || $tmp === false
                    || file_put_contents($tmp, $body) !== strlen($body)
                    || !chmod($tmp, 0644) || !rename($tmp, $target)) {
                    throw new RuntimeException($this->t('Не удалось сохранить страницу TeleMT', 'Could not save the TeleMT page'));
                }
            } finally {
                if ($tmp !== false && is_file($tmp)) @unlink($tmp);
            }
        }
    }

    // Версия telemt. Сам бинарь команды версии НЕ имеет (CLI рукописный,
    // неизвестный флаг вроде --version уходит в дефолтный Run — опрашивать
    // бинарь по ssh, как hysteriaVersion(), нельзя), поэтому версию при
    // сборке впекаем в образ файлом /etc/telemt_version
    // (dockerfile/telemt.dockerfile) и читаем ПО SSH ИЗ КОНТЕЙНЕРА — это
    // версия реально запущенного образа. Fallback — build-пин TELEMT_VERSION
    // из .env (образы, собранные до появления файла): он может расходиться с
    // контейнером, пока образ не пересобран.
    // Версия caddy в контейнере np. `caddy version` печатает «v2.11.2 h1:…» —
    // берём первый токен версии. Фолбэк — build-пин CADDY_VERSION из .env
    // (контейнер не отвечает); он может расходиться с образом, пока тот не
    // пересобран, поэтому источник помечаем в меню.
    public function naiveVersion(): array
    {
        $out = trim((string) $this->ssh('caddy version 2>/dev/null', 'np'));
        $run = preg_match('~v?\d+(?:\.\d+)+[0-9A-Za-z.\-]*~', $out, $m) ? $m[0] : '';
        return [
            'running' => $run,
            'pinned'  => trim((string) getenv('CADDY_VERSION')),
        ];
    }

    public function telemtVersion(): string
    {
        $v = trim((string) $this->ssh('cat /etc/telemt_version 2>/dev/null', 'telemt'));
        if ($v === '') {
            $v = trim((string) getenv('TELEMT_VERSION'));
        }
        if ($v === '') {
            return 'unknown';
        }
        if (preg_match('~\bv?\d+(?:\.\d+)+(?:[-+][0-9A-Za-z.-]+)?\b~', $v, $m)) {
            return htmlspecialchars($m[0], ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
        }
        return htmlspecialchars(mb_substr($v, 0, 40, 'UTF-8'), ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
    }

    public function normalizeTelemtUsers(array $conf): array
    {
        if (!isset($conf['telemt_users'])) {
            $changed = isset($conf['telemt_user_enabled']);
            unset($conf['telemt_user_enabled']);
            return [$conf, $changed];
        }
        if (!is_array($conf['telemt_users'])) {
            $conf['telemt_users'] = [];
            unset($conf['telemt_user_enabled']);
            return [$conf, true];
        }
        if (!$conf['telemt_users']) {
            if (!empty($conf['telemt_user_enabled'])) {
                $conf['telemt_user_enabled'] = [];
                return [$conf, true];
            }
            return [$conf, false];
        }

        $changed = false;
        $seen    = [];

        foreach ($conf['telemt_users'] as $name => $secret) {
            $secret = strtolower(trim((string) $secret));
            if (
                !preg_match('~^[a-f0-9]{32}$~', $secret)
                || isset($seen[$secret])
            ) {
                do {
                    $secret = $this->telemtSecret();
                } while (isset($seen[$secret]));
                $changed = true;
            } elseif ($conf['telemt_users'][$name] !== $secret) {
                $changed = true;
            }

            $conf['telemt_users'][$name] = $secret;
            $seen[$secret] = true;
        }
        if (!is_array($conf['telemt_user_enabled'] ?? null)) {
            $conf['telemt_user_enabled'] = [];
        }
        foreach (array_keys($conf['telemt_user_enabled']) as $name) {
            if (!array_key_exists($name, $conf['telemt_users'])) {
                unset($conf['telemt_user_enabled'][$name]);
                $changed = true;
            }
        }

        return [$conf, $changed];
    }

    // Resolve a dedicated TeleMT relay by name → ['address'=>.., 'portmap'=>[..]]
    // or null. Separate from the xray $pac['relays'] store on purpose.
    public function telemtRelay($name)
    {
        $r = $this->getPacConf()['telemt_relays'][$name] ?? null;
        return is_array($r) && !empty($r['address']) ? $r : null;
    }

    // Build a tg://proxy link. The secret format depends on the active mode
    // (classic = <hex>, secure = dd<hex>, tls = ee<hex><domainHex>). When a
    // $relay is given, only server+port are swapped (port through relayPort():
    // explicit 'port' wins over 'portmap'); the secret and the Fake-TLS domain
    // stay untouched — same idea as applyRelay keeping SNI real.
    public function linkTelemt($name, $relay = null)
    {
        if (!$this->protocolModuleEnabled('telemt')) return '';
        [$conf, $changed] = $this->normalizeTelemtUsers($this->getPacConf());
        if ($changed) {
            $conf = $this->telemtConfUpdate(function (&$current) {
                [$current] = $this->normalizeTelemtUsers($current);
                return $current;
            });
            $this->restartTelemt();
        }
        $secret = $conf['telemt_users'][$name] ?? '';
        $domain = $conf['telemt_domain'] ?? 'www.google.com';
        $dhex   = bin2hex($domain);
        $mode   = $this->telemtModeOf($conf);
        $secret = match ($mode) {
            'classic' => $secret,
            'secure'  => "dd$secret",
            default   => "ee$secret$dhex",
        };
        $server = $this->getDomain();
        $port   = $this->getPorts()['telemt']['port'];
        if (is_array($relay) && !empty($relay['address'])) {
            $server = $relay['address'];
            $port   = self::relayPort($relay, $port);
        }
        return 'tg://proxy?' . http_build_query([
            'server' => $server,
            'port'   => $port,
            'secret' => $secret,
        ], '', '&', PHP_QUERY_RFC3986);
    }

    public function restartXray($c, $norestart = false)
    {
        return $this->withXrayApplyLock(fn() => $this->applyXrayConfig($c, $norestart));
    }

    private ?string $heldXrayApplyPath = null;

    protected function withXrayApplyLock(callable $fn)
    {
        // Отдельный от xrayConfUpdate лок: сериализует запись/API/полный старт,
        // включая старые вызывающие методы, не использующие xrayConfUpdate.
        $path = $this->xrayConf . '.apply.lock';
        // Reset/restore keep apply locked across ledger publication and restart.
        // Re-entry is restricted to this instance and the pinned pathname.
        if ($this->heldXrayApplyPath !== null) {
            if ($this->heldXrayApplyPath !== $path) throw new RuntimeException('Xray apply lock path changed');
            return $fn();
        }
        if (is_link($path)) return false;
        $mask = umask(0077);
        $lock = @fopen($path, 'c');
        umask($mask);
        if ($lock === false) return false;
        try {
            $deadline = microtime(true) + 20;
            while (!flock($lock, LOCK_EX | LOCK_NB)) {
                if (microtime(true) >= $deadline) return false;
                usleep(100000);
            }
            $this->heldXrayApplyPath = $path;
            return $fn();
        } finally {
            $this->heldXrayApplyPath = null;
            flock($lock, LOCK_UN);
            fclose($lock);
        }
    }

    private function applyXrayConfig($c, $norestart = false)
    {
        $c = $this->guardXrayUnknownStats($c);
        $c['inbounds'][0]['settings']['clients'] = array_values($c['inbounds'][0]['settings']['clients']);
        $c['log']['access'] = '/logs/xray';
        foreach ($c['inbounds'] as $v) {
            if ($v['tag'] == 'api') {
                $api = true;
                break;
            }
        }
        if (empty($api)) {
            $c['inbounds'][] = [
                "listen"   => "127.0.0.1",
                "port"     => 8080,
                "protocol" => "dokodemo-door",
                "settings" => [
                    "address" => "127.0.0.1"
                ],
                "tag" => "api"
            ];
        }
        foreach ($c['routing']['rules'] as $v) {
            // У правил узлов выхода вместо outboundTag — balancerTag.
            if (($v['outboundTag'] ?? '') === 'api') {
                $rule = true;
                break;
            }
        }
        if (empty($rule)) {
            $c['routing']['rules'][] = [
                "inboundTag"  => ["api"],
                "outboundTag" => "api",
                "type"        => "field"
            ];
        }

        foreach ($c['inbounds'] as $v) {
            if ($v['tag'] == 'wg-in') {
                $wg = true;
                break;
            }
        }
        if (empty($wg)) {
            $c['inbounds'][] = [
                "port"     => 10808,
                "protocol" => "socks",
                "settings" => [
                    "auth" => "noauth",
                    "udp"  => true,
                    "ip"   => "0.0.0.0"
                ],
                "tag"      => "wg-in",
                "sniffing" => [
                    "destOverride" => [
                        "http",
                        "tls",
                        "quic"
                    ],
                    "enabled" => true
                ]
            ];
        }
        $pac = $this->getPacConf();
        if (!VlessEncryption::applyServer($c, $pac)) {
            error_log('restartXray: invalid VLESS Encryption settings');
            return false;
        }
        $this->applySniffingToXray($c, $pac);
        // До гейтов ниже: они собирают теги всех входов с пользователями, и
        // вход XDRIVE должен получить те же запреты, что и основной.
        $this->ensureXdriveInbound($c, $pac);
        // IPv6 enters directly after DNAT, while IPv4 keeps nginx's PROXY protocol.
        // Clone before policy gates so the direct listener receives all restrictions.
        $this->ensureNode6Inbound($c, $pac);
        $this->ensureTrustedXff($c);
        $this->ensureFreedomCompat($c);
        // Строго до ensureWgGuard(): тот кладёт свои гейты в голову правил, и
        // правило торрентов обязано оказаться ПОД ними, а не над.
        $this->ensureTorrentBlock($c, $pac);
        // Узлы выхода — тоже до ensureWgGuard(): их служебные входы проверки
        // получают те же гейты, а правила встают под защитными.
        $this->ensureExitNodes($c, $pac);
        if (array_filter($c['outbounds'] ?? [], static fn($o) => isset($o['_vpnbot_ipv4']) || ($o['sendThrough'] ?? '') === self::EXIT_IPV6_SOURCE)) {
            $versions = $this->xrayCoreInventory();
            self::exitFreedomStrategies($c, $versions[$this->xrayCoreSelection($pac)] ?? '');
        }
        $this->ensureFreedomCompat($c);
        $this->ensureWgGuard($c);
        $this->ensureSmuxInbound($c);
        $this->ensureXhttpMuxInbound($c, $pac);
        if (is_array($c['inbounds'][0]['streamSettings']['realitySettings'] ?? null)) {
            $this->ensureRealityRequireMlkem($c['inbounds'][0]['streamSettings']['realitySettings'], $pac);
        }
        if (!$this->finalmaskCoreCompatible($pac, $this->xrayCoreSelection($pac))) return false;
        $this->ensureFinalmaskInbound($c);
        $c['stats'] = new stdClass();
        $c['api'] = [
            'services' => ['StatsService', 'HandlerService', 'RoutingService'],
            'tag'      => 'api'
        ];
        $l = new stdClass();
        $l->{'0'} = [
            "statsUserUplink"   => true,
            "statsUserDownlink" => true,
            // Без этого флага ядро не ведёт карту «email -> живые IP»
            // (app/dispatcher/default.go: trackOnlineIP зовётся только при
            // p.Stats.UserOnline), и `xray api statsonlineiplist` отдаёт пусто.
            // Её читает xrayOnlineIps() — источник онлайна, не зависящий от
            // access-лога. Старые ядра неизвестное поле политики игнорируют.
            "statsUserOnline"   => true
        ];
        $c['policy']['levels'] = $l;
        $c['policy']['system'] = [
            "statsInboundUplink"    => true,
            "statsInboundDownlink"  => true,
            "statsOutboundUplink"   => true,
            "statsOutboundDownlink" => true
        ];
        // Кодируем ДО записи и до pkill: json_encode() возвращает FALSE на
        // невалидном UTF-8 (имя/комментарий клиента из импорта, байты из
        // ssh-вывода), а file_put_contents($f, false) пишет ПУСТОЙ файл и
        // рапортует об успехе — то есть xray.json обнулялся, а следом мы гасили
        // ядро, которое с пустым конфигом уже не поднималось. Лучше не
        // перезапускать вовсе: старый конфиг на диске остаётся рабочим.
        $json = json_encode($c, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
        if (false === $json) {
            error_log('restartXray: xray.json not written — ' . json_last_error_msg());

            return false;
        }
        if (empty($norestart)) {
            // Проверяет именно выбранное ядро (включая форк) до замены
            // рабочего файла и остановки процесса. Корректного JSON мало:
            // ядро может не знать транспорт, алгоритм или поле конфигурации.
            if (!$this->validateXrayConfig($c)) {
                error_log('restartXray: configuration rejected by active core; previous configuration preserved');
                return false;
            }
            $previous = $this->getXray() ?? [];
            if (!$this->syncXrayNginxRoutes($c)) {
                error_log('restartXray: NGINX transport routes rejected; previous configuration preserved');
                return false;
            }
            if (!$this->writeXrayJson($json)) {
                $this->syncXrayNginxRoutes($previous);
                return false;
            }
            if (!$this->xrayStatsResetting && $this->tryXrayHotApply($previous, $c)) return true;
            $this->collectSession();
            $stopped = $this->ssh('pkill xray; code=$?; [ "$code" -le 1 ] || exit "$code"; n=0; while pgrep -f "[x]ray run" >/dev/null; do [ "$n" -lt 25 ] || exit 1; n=$((n+1)); sleep 0.2; done; printf VPNBOT_XRAY_STOPPED', 'xr');
            if ($this->sshFailed || trim((string) $stopped) !== 'VPNBOT_XRAY_STOPPED') return false;
            // XRAY_LOCATION_ASSET указывает ядру, где искать .dat (ext:/extip: из
            // routes → dat лежат в общем /logs/geodata). Задаём прямо в команде
            // старта — не требует правки override.env и совпадает с datDir().
            $started = $this->ssh('mkdir -p /logs/geodata || exit 1; XRAY_LOCATION_ASSET=/logs/geodata xray run -config /xray.json >> /logs/xray_stdout 2>&1 & '
                . 'xray_pid=$!; python3 /xray_hot_apply.py mark --pid "$xray_pid" >/dev/null 2>&1 || true; kill -0 "$xray_pid" 2>/dev/null && printf VPNBOT_XRAY_LAUNCHED', 'xr');
            if ($this->sshFailed || trim((string) $started) !== 'VPNBOT_XRAY_LAUNCHED') return false;
            return $this->xrayCoreStarted($this->xrayCoreSelection($pac));
        } else {
            $previous = $this->getXray() ?? [];
            if (!$this->writeXrayJson($json)) return false;
            // Запись без применения (срок, лимит, шаблоны): если ядро этих полей
            // не видит, маркер горячего применения переносится на новый конфиг.
            // Иначе следующее изменение (отключение, ключ) шло полным перезапуском.
            $this->tryXrayHotApply($previous, $c, 'sync');
            return true;
        }
        return true;
    }

    protected function tryXrayHotApply(array $previous, array $target, string $action = 'apply'): bool
    {
        if (!in_array('HandlerService', $previous['api']['services'] ?? [], true)
            || !in_array('RoutingService', $previous['api']['services'] ?? [], true)) return false;
        $input = json_encode(['previous' => $previous, 'target' => $target], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
        if ($input === false || strlen($input) > 32 * 1024 * 1024) return false;
        $out = $this->sshInputCommand('python3 /xray_hot_apply.py ' . ($action === 'sync' ? 'sync' : 'apply') . ' --size ' . strlen($input) . ' 2>/dev/null', $input, 'xr');
        return !$this->sshFailed && trim($out) === ($action === 'sync' ? 'SYNCED' : 'APPLIED');
    }

    // Подсеть docker-compose сборки: в ней живут adguard (10.10.0.5), панель,
    // sshd всех контейнеров и warp. Клиентские подсети wg/awg сюда НЕ входят
    // (WGADDRESS/WG1ADDRESS по умолчанию 10.0.1.0/24 и 10.0.3.0/24).
    public const DOCKER_NET = '10.10.0.0/16';
    // Внутренний DNS, который бот сам прописывает клиентам кнопкой
    // «set internal dns» — единственное, что клиенту в этой подсети нужно.
    public const INTERNAL_DNS = '10.10.0.5/32';
    // Sing-box-шаблоны заводят outbound warpSOCKS5 как 10.10.0.13:1080 с
    // detour через основной VLESS. Это не произвольный доступ в docker-сеть:
    // ровно этот адрес закреплён за wp в compose, microsocks принимает
    // соединения только от xr, а ходить через него ВГЛУБЬ сети проекта
    // запрещает egress-ACL (обе цепочки WARP_SOCKS* в start_wp.sh).
    public const WARP_SOCKS_IP   = '10.10.0.13/32';
    public const WARP_SOCKS_PORT = '1080';
    // Relay-порты WARP SOCKS; синхронно с SOCKS_UDP_PORTS в start_wp.sh.
    public const WARP_SOCKS_UDP_PORTS = '20000-29999';

    // Фактический адрес wp из compose: в override его можно переназначить, и
    // тогда захардкоженная константа молча разъедется с реальностью — правило
    // в гейте перестанет совпадать, а наружу это выглядит как «WARP отвалился»
    // без единой строки в логах. Константа остаётся дефолтом на случай, когда
    // /docker/compose недоступен (тесты, панель).
    public function warpSocksIp(): string
    {
        $f = '/docker/compose';
        if (is_file($f)) {
            $nets = yaml_parse_file($f)['services']['wp']['networks'] ?? [];
            foreach ((array) $nets as $n) {
                $ip = is_array($n) ? (string) ($n['ipv4_address'] ?? '') : '';
                if (filter_var($ip, FILTER_VALIDATE_IP, FILTER_FLAG_IPV4)) {
                    return "$ip/32";
                }
            }
        }

        return self::WARP_SOCKS_IP;
    }

    // Внутренние socks-inbound'ы без авторизации, слушающие в docker-сети.
    // 'wg-in' (10808) создаёт restartXray() — в него tun2socks отдаёт трафик
    // wg/awg-клиентов. 'socks-in' (10085) в этом репозитории и в upstream не
    // создаётся вовсе, но лежит в рантайме на боевых хостах (добавлен когда-то
    // вручную и переживает все рестарты: restartXray() чужие inbound'ы не
    // трогает). Потребителей у него нет — ноль записей в логе ядра за двое
    // суток, ноль упоминаний в pac.json и в конфигах контейнеров.
    //
    // Гейт ниже вешаем на оба: пока inbound существует, он одинаково пригоден
    // для бокового движения по сети.
    public const INTERNAL_SOCKS_TAGS = ['wg-in', 'socks-in'];

    // Inbound'ы, которым гейт не ставим. 'api' — служебный dokodemo для
    // `xray api statsquery` (127.0.0.1:8080 внутри xr): он маршрутизируется
    // отдельным правилом inboundTag:api → outboundTag:api, и лишнее правило в
    // голове списка тут только мешало бы читать конфиг.
    public const GUARD_EXEMPT_TAGS = ['api'];

    // Клиенты wg/awg входят в xray через socks-inbound 'wg-in' (tun2socks в
    // wg-контейнерах), а `ip rule from $ADDRESS table 100` в start_wg.sh уводит
    // туда ВЕСЬ их трафик — включая назначения внутри docker-сети. Отдельного
    // ограничения на этот inbound не было, а ensureFreedomCompat даже явно
    // allow'ит 10.10.0.0/16 на freedom, так что клиент VPN мог открыть
    // соединение к adguard, к sshd любого контейнера или к панели — и оно
    // уходило с адреса xr-контейнера, то есть ИЗНУТРИ доверенной зоны (проверено
    // на рабочем сервере: через xr:10808 снимался ssh-баннер service-контейнера, где лежит
    // приватный ключ, и открывалась панель, до которой сам wg-контейнер
    // напрямую не доходит — её закрывает nft). Тот же класс, что закрывали для
    // WARP-SOCKS.
    //
    // ВАЖНО (аудит 2026-08-18): гейт стоял ТОЛЬКО на INTERNAL_SOCKS_TAGS, то
    // есть закрывал боковое движение клиентам wg/awg и оставлял его открытым
    // основному клиентскому inbound'у (vless/vmess/trojan, config/xray.json).
    // Ровно тем же способом любой обладатель подписки доходил до control API
    // unit (10.10.0.7:8080, без аутентификации, приложения от root), до панели
    // и до sshd контейнеров. Поэтому теги берём из ВСЕХ inbound'ов конфига за
    // вычетом GUARD_EXEMPT_TAGS.
    //
    // Режем ровно docker-сеть (остальное приватное пространство уже закрыто
    // finalRules у freedom) и оставляем две точечные дырки: внутренний DNS и
    // WARP SOCKS. Вторая нужна только внешним клиентским inbound'ам: sing-box
    // подключает warpSOCKS5 к 10.10.0.13:1080 с detour через VLESS, поэтому
    // Xray видит именно клиентское НАЗНАЧЕНИЕ 10.10.0.13:1080. Аудитный гейт
    // d47438b ошибочно считал этот дозвон внутренней работой outbound и начал
    // отправлять его в blackhole; sing-box получал EOF на каждом WARP-домене.
    // wg-in/socks-in исключение не получают: их клиенты используют серверное
    // правило outboundTag=warp и напрямую к microsocks ходить не должны.
    // Остальные адреса/порты docker-сети, включая panel/API/sshd, закрыты.
    //
    // Правила ставим В НАЧАЛО: xray берёт первое совпавшее, и пользовательские
    // block/warp-списки (xrayUpdateRules) не должны их обгонять. Матчим по
    // явным CIDR, а не по 'geoip:private': последнее требует geoip.dat в
    // XRAY_LOCATION_ASSET, и без файла ядро не стартует вовсе.
    public function ensureWgGuard(array &$c): void
    {
        // Теги берём из фактических inbound'ов, а не списком константы: правило
        // на несуществующий тег — мёртвый груз в конфиге, а набор inbound'ов на
        // разных хостах разный. Безымянные inbound'ы пропускаем: правило без
        // рабочего inboundTag ядро применит не к тому трафику.
        $tags = [];
        foreach (($c['inbounds'] ?? []) as $i) {
            $t = (string) ($i['tag'] ?? '');
            if ($t === '' || in_array($t, self::GUARD_EXEMPT_TAGS, true) || in_array($t, $tags, true)) {
                continue;
            }
            $tags[] = $t;
        }
        $warpTags   = array_values(array_diff($tags, self::INTERNAL_SOCKS_TAGS));
        $warpSocksIp = $this->warpSocksIp();

        // Снимаем прежние копии гейта — их inboundTag почти наверняка у́же
        // нынешнего (до аудита 2026-08-18 там были только wg-in/socks-in),
        // поэтому опознаём по сигнатуре самого правила, а не по списку тегов:
        // иначе старые узкие копии остались бы в конфиге дублями и продолжали
        // бы совпадать раньше нового гейта.
        $rules = [];
        $unavailable = [];
        foreach (($c['routing']['rules'] ?? []) as $r) {
            if (in_array($r['ruleTag'] ?? '', ['vpnbot:ipv6:relay-guard', 'vpnbot:exit:full-guard'], true)) continue;
            if (str_starts_with($r['ruleTag'] ?? '', self::EXIT_UNAVAILABLE)) { $unavailable[] = $r; continue; }
            $in  = (array) ($r['inboundTag'] ?? []);
            $ip  = (array) ($r['ip'] ?? []);
            $out = (string) ($r['outboundTag'] ?? '');
            $isGuard = $in !== [] && (
                ($ip === [self::DOCKER_NET] && $out === 'block')
                || ($ip === [self::INTERNAL_DNS] && $out === 'direct' && (string) ($r['port'] ?? '') === '53')
                // Опознаём по порту+network, а не по конкретному адресу: после
                // смены адресации в override старая копия обязана сняться, а не
                // остаться дублем впереди новой.
                || (count($ip) === 1 && $out === 'direct'
                    && (((string) ($r['port'] ?? '') === self::WARP_SOCKS_PORT
                            && (string) ($r['network'] ?? '') === 'tcp')
                        || ((string) ($r['port'] ?? '') === self::WARP_SOCKS_UDP_PORTS
                            && (string) ($r['network'] ?? '') === 'udp')))
            );
            if (!$isGuard) {
                $rules[] = $r;
            }
        }

        if (empty($tags)) {
            $c['routing']['rules'] = array_merge($unavailable, $rules);
            return;
        }

        $this->ensureBlockOutbound($c);

        // Порядок: оба точечных allow обязаны стоять перед блоком подсети —
        // Xray берёт первое совпавшее правило.
        $guards = [[
                'type'        => 'field',
                'inboundTag'  => $tags,
                'ip'          => [self::INTERNAL_DNS],
                'port'        => '53',
                'outboundTag' => 'direct',
        ]];
        if ($warpTags !== []) {
            $guards[] = [
                'type'        => 'field',
                'inboundTag'  => $warpTags,
                'ip'          => [$warpSocksIp],
                'port'        => self::WARP_SOCKS_PORT,
                'network'     => 'tcp',
                'outboundTag' => 'direct',
            ];
            $guards[] = [
                'type'        => 'field',
                'inboundTag'  => $warpTags,
                'ip'          => [$warpSocksIp],
                'port'        => self::WARP_SOCKS_UDP_PORTS,
                'network'     => 'udp',
                'outboundTag' => 'direct',
            ];
        }
        $guards[] = [
                'type'        => 'field',
                'inboundTag'  => $tags,
                'ip'          => [self::DOCKER_NET],
                'outboundTag' => 'block',
        ];
        // Строгому профилю узла не нужны исключения DNS/WARP во внутреннюю
        // Docker-сеть. Иначе ранний allow обходил бы его конечный IPv6-выход.
        $strictRelay = $fullUsers = [];
        foreach ($c['inbounds'][0]['settings']['clients'] ?? [] as $client) {
            if (!is_array($client)) continue;
            if (self::exitFullId($client) !== '-' && empty($client['off']) && is_string($client['email'] ?? null) && $client['email'] !== '') {
                $fullUsers[] = self::exitExactUser($client['email']);
            }
            if (!empty($client['exit_relay']) && !empty($client['exit_ipv6']) && empty($client['off']) && !empty($client['email'])) $strictRelay[] = $client['email'];
        }
        // Keep the internal DNS service, but prevent the client-side WARP SOCKS shortcut.
        if ($fullUsers) array_splice($guards, 1, 0, [['type' => 'field', 'ruleTag' => 'vpnbot:exit:full-guard',
            'user' => $fullUsers, 'ip' => [self::DOCKER_NET], 'outboundTag' => 'block']]);
        if ($strictRelay) array_unshift($guards, ['type' => 'field', 'ruleTag' => 'vpnbot:ipv6:relay-guard',
            'user' => array_values(array_unique($strictRelay)), 'ip' => [self::DOCKER_NET], 'outboundTag' => 'block']);
        $c['routing']['rules'] = array_merge($unavailable, $guards, $rules);
    }

    // blackhole обязан существовать: правило с несуществующим тегом молча
    // теряет смысл — xray его игнорирует, и трафик уходит в первый аутбаунд,
    // то есть НАРУЖУ. Свои outbounds админа не трогаем.
    public function ensureBlockOutbound(array &$c): void
    {
        foreach (($c['outbounds'] ?? []) as $o) {
            if (($o['tag'] ?? '') === 'block') {
                return;
            }
        }
        $c['outbounds'][] = ['protocol' => 'blackhole', 'tag' => 'block'];
    }

    // ── Торренты клиентов xray (routing protocol: bittorrent) ──────────────
    // У WG/AWG торренты режет block_torrent.sh (ipp2p + сигнатуры на FORWARD
    // инстанса wg). До трафика xray-клиентов он не достаёт вовсе: тот выходит
    // из ядра в контейнере xr и через FORWARD инстанса wg не проходит. Здесь
    // ту же работу делает сам xray — правилом роутинга по protocol, то есть по
    // результату sniffing'а, а не по сигнатуре в каждом пакете.
    //
    // Матчинг есть на ОБОИХ ядрах, но покрытие разное:
    //   апстрим до v26.9.8 — только TCP-handshake ('BitTorrent protocol'); его
    //     UDP-сниффер uTP сравнивал 32-битные монотонные часы с
    //     epoch-микросекундами и не срабатывал ни разу;
    //   апстрим v26.9.8+ (PR #6667) — плюс рабочий uTP: ST_SYN опознаётся по
    //     типу+версии, нулевой разнице таймстампов и цепочке расширений,
    //     которая обязана закончиться ровно на конце пакета;
    //   форк v26.8.21+ — сверх того DHT/KRPC (BEP 5) и UDP-трекеры (BEP 15),
    //     а v26.8.23 закрывает ложные срабатывания на DNS-запросах
    //     (v26.8.22 роняла в блок примерно один DNS-запрос из 13000).
    // Гейта по xrayCore() поэтому нет: правило безвредно и на апстриме, просто
    // ловит меньше — про разницу предупреждает меню (xrayTorrentHintKey()).
    //
    // Обязательное условие — sniffing: content.Protocol ядро заполняет ТОЛЬКО
    // при sniffing.enabled и metadataOnly=false (app/dispatcher/default.go).
    // destOverride на матчинг не влияет — он гейтит лишь подмену адреса.
    public function xrayTorrentBlocked(?array $p = null): bool
    {
        $p = $p ?? $this->getPacConf();

        return !empty($p['xray_blocktorrent']);
    }

    // Сработает ли правило вообще. Без sniffing (или с metadataOnly) оно не
    // совпадёт никогда, и меню обязано сказать это вслух, а не рисовать
    // «включено» у фильтра, который молча пропускает всё.
    //
    // Смотрим на ФАКТИЧЕСКИЙ блок клиентского inbound'а, а не на дефолты
    // sniffingSettings(): пока админ не трогал sniffing, ключа 'sniffing' в pac
    // нет, applySniffingToXray() inbound не трогает вовсе — и на установке, где
    // блока в xray.json нет, дефолт «enabled=true» соврал бы про готовность.
    // Настройка из pac важнее конфига: она уедет в него на ближайшем рестарте.
    public function xrayTorrentReady(?array $p = null, ?array $c = null): bool
    {
        $p = $p ?? $this->getPacConf();
        $c = $c ?? $this->getXray();
        if (is_array($p['sniffing'] ?? null)) {
            $s = $this->sniffingConfig($p);
        } else {
            $s = [];
            foreach ((is_array($c) ? ($c['inbounds'] ?? []) : []) as $in) {
                if (!empty($in['settings']['clients'])) {
                    $s = is_array($in['sniffing'] ?? null) ? $in['sniffing'] : [];
                    break;
                }
            }
        }

        return !empty($s['enabled']) && empty($s['metadataOnly']);
    }

    // Какой подсказкой отвечать на включённый тумблер: что именно ядро ловит,
    // зависит от АКТИВНОГО ядра и его версии, а не от нашего пина в .env —
    // образ xr мог не пересобираться с прошлого обновления, и обещать в меню
    // uTP на ядре, которое его не видит, нельзя (тот же критерий, что у
    // smuxHalfCloseReady()/smuxFrameReady()).
    //
    //   форк 26.8.21+        — handshake + uTP + DHT/KRPC + UDP-трекеры;
    //   апстрим 26.9.8+      — handshake + uTP (DHT и трекеры только на форке);
    //   любое ядро старее    — только handshake: у обоих до этих версий стоял
    //                          общий сломанный uTP-сниффер апстрима.
    //
    // Проба не ответила (контейнер лежит) — версии нет, и врать нечем: берём
    // ядро, ВЫБРАННОЕ в настройках, и не пугаем старым ядром на ровном месте.
    public function xrayTorrentHintKey(?array $p = null): string
    {
        $probe = $this->xrayCoreProbe();
        $core  = !empty($probe['ok']) ? (string) ($probe['active'] ?? '') : $this->xrayCore($p);
        $fork  = $core === 'fork';
        $v     = $this->getXrayVersion();
        if ($v !== '' && version_compare($v, $fork ? '26.8.21' : '26.9.8', '<')) {
            return $fork ? 'torrent xray hint fork old' : 'torrent xray hint origin old';
        }

        return $fork ? 'torrent xray hint' : 'torrent xray hint origin';
    }

    public function ensureTorrentBlock(array &$c, ?array $p = null): void
    {
        $p = $p ?? $this->getPacConf();
        // Прежние копии снимаем по СИГНАТУРЕ, а не по списку тегов: смена
        // транспорта переименовывает клиентский inbound, и сверка по тегам
        // оставила бы старое правило дублем впереди нового.
        $rules = [];
        foreach (($c['routing']['rules'] ?? []) as $r) {
            $isOurs = (string) ($r['outboundTag'] ?? '') === 'block'
                && (array) ($r['protocol'] ?? []) === ['bittorrent'];
            if (!$isOurs) {
                $rules[] = $r;
            }
        }
        $c['routing']['rules'] = $rules;
        if (empty($p['xray_blocktorrent'])) {
            return;
        }

        // Только клиентские inbound'ы (те же, что получают sniffing от
        // applySniffingToXray). api/wg-in не трогаем: через wg-in ходят
        // WG/AWG-клиенты, у них свой тумблер торрентов — один выключатель не
        // должен молча решать за другой.
        $tags = [];
        foreach (($c['inbounds'] ?? []) as $in) {
            if (!empty($in['settings']['clients']) && (string) ($in['tag'] ?? '') !== '') {
                $tags[] = (string) $in['tag'];
            }
        }
        if ($tags === []) {
            return;
        }
        $this->ensureBlockOutbound($c);
        // В начало: правило обязано стоять раньше пользовательских маршрутов
        // (warp/direct по доменам и спискам) — xray берёт первое совпавшее.
        // Гейты wg (DNS :53 → direct, docker-сеть → block) уезжают ещё выше:
        // ensureWgGuard() вызывается ПОСЛЕ и делает свой array_merge в голову.
        array_unshift($c['routing']['rules'], [
            'type'        => 'field',
            'inboundTag'  => $tags,
            'protocol'    => ['bittorrent'],
            'outboundTag' => 'block',
        ]);
    }

    // Дотягивает sockopt.trustedXForwardedFor на клиентский inbound, если его
    // транспорт слушает за nginx (ws / xhttp / grpc). changeTransport ставит его
    // сам, но только в момент переключения транспорта — у всех, кто уже сидит на
    // ws/xhttp/trojan-grpc, конфиг иначе остался бы без него до ручного
    // перещёлкивания кнопки. Ставим ровно один раз и не трогаем уже заданное
    // значение: админ мог прописать своё имя заголовка руками в webapp.
    // Чем это лечится — см. nginxFrontedSockopt().
    public function ensureTrustedXff(array &$c): void
    {
        $net = $c['inbounds'][0]['streamSettings']['network'] ?? '';
        if (!in_array($net, ['ws', 'xhttp', 'grpc'], true)) {
            return;
        }
        if (!empty($c['inbounds'][0]['streamSettings']['sockopt']['trustedXForwardedFor'])) {
            return;
        }
        $c['inbounds'][0]['streamSettings']['sockopt'] = array_merge(
            $c['inbounds'][0]['streamSettings']['sockopt'] ?? [],
            $this->nginxFrontedSockopt(),
        );
    }

    // Безопасная запись xray.json для функций, которые меняют лишь метаданные
    // клиента (шаблоны подписки, HWID) и НЕ перезапускают ядро. getXray() читает
    // конфиг как ассоц-массив, из-за чего json round-trip превращает пустые/
    // числовые-ключ объекты `stats:{}` → `[]` и `policy.levels:{"0":..}` → `[..]`,
    // а xray такой конфиг ОТВЕРГАЕТ ("cannot unmarshal array into ... stats") и не
    // стартует при следующем старте контейнера. Восстанавливаем тип объекта (как
    // это делает restartXray) перед записью.
    public function saveXray(array $c): void
    {
        $c['stats'] = new stdClass();
        if (isset($c['policy']['levels']) && is_array($c['policy']['levels'])) {
            $lv = new stdClass();
            foreach ($c['policy']['levels'] as $k => $v) {
                $lv->{(string) $k} = $v;
            }
            $c['policy']['levels'] = $lv;
        }
        $this->ensureFreedomCompat($c);
        // По той же причине, что и ensureFreedomCompat: этот путь пишет
        // xray.json из редактора, и гейт wg-in не должен теряться при ручной
        // правке конфига.
        $this->ensureWgGuard($c);
        // Как и в restartXray(): FALSE от кодировщика превратился бы в пустой
        // xray.json (file_put_contents($f, false) пишет '' и рапортует успех),
        // то есть в потерю всех клиентов при следующем старте ядра.
        $json = json_encode($c, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
        if (false === $json) {
            error_log('saveXray: xray.json not written — ' . json_last_error_msg());

            throw new RuntimeException($this->t('Не удалось кодировать настройки Xray', 'Could not encode Xray settings'));
        }
        $saved = $this->withXrayApplyLock(function () use ($json, $c) {
            $previous = $this->getXray() ?? [];
            if ($this->writeXrayJson($json)) {
                // HWID, шаблон и ссылка подписки также должны обновлять
                // маркер, иначе следующая правка зря перезапустит ядро.
                $this->tryXrayHotApply($previous, $c, 'sync');
                return true;
            }
            return false;
        });
        if ($saved !== true) throw new RuntimeException($this->t('Не удалось сохранить настройки Xray', 'Could not save Xray settings'));
    }

    // Запись xray.json ТОЛЬКО поверх существующего inode. Файл читается
    // публичными эндпоинтами подписки (sub(), subscription()) из нескольких
    // воркеров: при голом file_put_contents читатель ловил файл на середине
    // записи, json_decode() отдавал null, и findClientBySid(array $xr, …)
    // падал с TypeError — 500 вместо конфига. Поэтому пишем под LOCK_EX, а
    // getXray() читает под LOCK_SH: читатель ждёт конца записи и видит файл
    // целиком.
    //
    // Приём «tmp + rename», которым пишутся pac.json и clients.json, здесь
    // применять НЕЛЬЗЯ, хотя он атомарен и без локов: config/xray.json
    // прокинут в контейнер xray ОТДЕЛЬНЫМ файловым bind-mount'ом
    // (config/xray.json → /xray.json, см. docker-compose.yml). Такой mount
    // держит inode, а не путь: rename() подменяет запись в каталоге на НОВЫЙ
    // inode, и контейнер до самого пересоздания продолжает видеть старый файл.
    // Итог — pkill+`xray run -config /xray.json` в restartXray() поднимает
    // ядро на конфиге, замороженном в момент старта контейнера: клиентов в нём
    // нет, транспорт не тот, reality-заглушка не отдаётся. Правится только
    // перезагрузкой/пересозданием контейнеров, а бот при этом рапортует об
    // успехе. То же ограничение у всех остальных файлов из config/, прокинутых
    // по одному (nginx.conf, upstream.conf, wg0.conf, sslocal.json, deny, …) —
    // они пишутся in-place и должны так и остаться.
    // Конфиг с боевым секретом: приватные ключи, пароли, UUID. В git эти файлы
    // лежат пустыми шаблонами с режимом 100644, а код записи chmod не делал —
    // значит на свежей установке боевой файл создавался 0644 и был читаем всем
    // внутри девяти контейнеров, куда смонтирован ./config. Ключи TLS и
    // ipsec/ovpn в проекте уже пишутся 0600, приводим остальные к тому же.
    public function chmodSecret(string $path): void
    {
        @chmod($path, 0600);
    }

    public function writeXrayJson(string $json): bool
    {
        return $this->withXrayApplyLock(fn() => $this->writeXrayJsonLocked($json)) === true;
    }

    private function writeXrayJsonLocked(string $json): bool
    {
        $ok = $this->backupWriteInPlace($this->xrayConf, $json);
        if (!$ok) error_log('writeXrayJson: write failed; previous data restored where possible');
        if ($ok) {
            try { $this->syncXrayProtocolUsers(); }
            catch (Throwable $e) { error_log('syncXrayProtocolUsers: failed; background retry pending'); }
        }

        return $ok;
    }

    // Xray >= v26.4.15 (PR #5947, «Direct/Freedom outbound: default safe policy»)
    // вешает на freedom/direct-outbound встроенное правило, которое МОЛЧА рвёт
    // любое соединение, чей адрес назначения попадает в приватный/зарезерви-
    // рованный диапазон (0/8, 10/8, 100.64/10, 127/8, 169.254/16, 172.16/12,
    // 192.168/16, 198.18/15, CGNAT, …), и принудительно резолвит домен ДО дозвона.
    // Срабатывает, когда исходящий inbound — vless/vmess/trojan/hysteria/wireguard
    // /shadowsocks. Именно это ломает warp (socks → microsocks @ 10.10.0.13) и
    // любой внутрикластерный/LAN-адрес, идущий через "direct": поэтому warp
    // работает на v26.4.13 и отваливается начиная с v26.4.15.
    //
    // Возвращаем работоспособность warp, перекрывая встроенное правило своим
    // явным finalRules (матчится раньше default-правила; первое совпадение
    // выигрывает — см. proxy/freedom/freedom.go: matchFinalRule). Вместо «глухого»
    // allow-all делаем «закалённый» вариант, сохраняющий защиту от SSRF:
    //   1) allow 10.10.0.0/16 — внутренние docker-сети проекта (10.10.0.0/24 и
    //      10.10.1.0/24), сюда входит warp-socks @ 10.10.0.13 и прочие контейнеры;
    //   2) block — полный приватный/зарезервированный набор (как в апстрим-политике
    //      #5947: loopback, CGNAT, link-local/metadata 169.254.169.254, RFC1918,
    //      IPv6 ULA/link-local), чтобы клиент не дотянулся через "direct" до
    //      внутренностей хоста/LAN/облачного metadata.
    // Публичные адреса не матчат ни одно правило → default Allow. ВАЖНО: адрес
    // назначения-домен ядро для этой проверки РЕЗОЛВИТ до дозвона, что требует
    // рабочего системного резолвера в контейнере xr — у нас он есть. С v26.9.8
    // (PR #6058) резолв перестал переписывать адрес дозвона: ядро смотрит
    // стратегию sockopt.domainStrategy, а без неё спрашивает системный резолвер
    // отдельно — на наши правила это не влияет, они матчат по IP назначения, а
    // клиентский warp-socks (10.10.0.13) приходит уже адресом, а не именем.
    // Ядра < v26.4.17 не знают поля "finalRules" и игнорируют его (нестрогий
    // JSON-загрузчик), а safe policy там либо отсутствует (<= v26.4.13) —
    // регрессий нет. Конфиги с собственными finalRules не трогаем.
    // Единственное, что снимает finalRules целиком, — sockopt.dialerProxy на
    // самом freedom (с v26.9.9 ядро тогда пишет warning и правила не строит):
    // на сервере такого freedom нет, dialerProxy живёт только в клиентских
    // конфигах подписки (applyDpiFragment).
    //
    // Аудит 2026-10-31: «allow 10.10.0.0/16» доверял запрету внутренней сети
    // на уровне маршрутизации, а тот совпадает только по IP. При IPIfNonMatch
    // ядро сначала проходит правила с ДОМЕННОЙ целью, и совпавшее доменное
    // правило в direct (группа узлов «напрямую», запасной direct упавшего
    // узла) выигрывало до правил по IP: клиент просил 10.10.0.15.nip.io и
    // получал sshd service, AdGuard мимо пропуска nginx, dockerproxy
    // (проверено на тестовом сервере лабораторным ядром с боевыми правилами). Теперь
    // freedom сам пускает внутрь только то, что разрешают и гейты:
    // DNS AdGuard и WARP-socks (TCP-порт и UDP-порты relay).
    public const FREEDOM_LEGACY_INTERNAL = [['action' => 'allow', 'ip' => ['10.10.0.0/16']]];

    public function ensureFreedomCompat(array &$c): void
    {
        if (empty($c['outbounds']) || !is_array($c['outbounds'])) {
            return;
        }
        $warp = $this->warpSocksIp();
        $finalRules = [
            ['action' => 'allow', 'network' => 'tcp,udp', 'port' => '53', 'ip' => [self::INTERNAL_DNS]],
            ['action' => 'allow', 'network' => 'tcp', 'port' => self::WARP_SOCKS_PORT, 'ip' => [$warp]],
            ['action' => 'allow', 'network' => 'udp', 'port' => self::WARP_SOCKS_UDP_PORTS, 'ip' => [$warp]],
            ['action' => 'block', 'ip' => [
                '0.0.0.0/8',
                '10.0.0.0/8',
                '100.64.0.0/10',
                '127.0.0.0/8',
                '169.254.0.0/16',
                '172.16.0.0/12',
                '192.0.0.0/24',
                '192.0.2.0/24',
                '192.88.99.0/24',
                '192.168.0.0/16',
                '198.18.0.0/15',
                '198.51.100.0/24',
                '203.0.113.0/24',
                '224.0.0.0/3',
                '::/127',
                'fc00::/7',
                'fe80::/10',
                'ff00::/8',
            ]],
        ];
        foreach ($c['outbounds'] as &$ob) {
            if (($ob['protocol'] ?? '') !== 'freedom') {
                continue;
            }
            if (!isset($ob['settings']) || !is_array($ob['settings'])) {
                $ob['settings'] = [];
            }
            $current = $ob['settings']['finalRules'] ?? null;
            if ($current === null) {
                $ob['settings']['finalRules'] = $finalRules;
                continue;
            }
            // Прежняя пара по умолчанию (allow 10.10.0.0/16 + тот же запрет)
            // заменяется на месте: запрет ::/0 узлов IPv6 и собственные правила
            // администратора остаются, где были.
            $at = is_array($current) ? array_search(self::FREEDOM_LEGACY_INTERNAL[0], $current, true) : false;
            if ($at !== false && ($current[$at + 1] ?? null) === $finalRules[3]) {
                array_splice($current, $at, 2, $finalRules);
                $ob['settings']['finalRules'] = $current;
            }
        }
        unset($ob);
    }

    // Свернуть session в global — общий и по каждому клиенту. Вынесено из
    // collectSession() чистой функцией: то же самое нужно сделать, когда ядро
    // перезапустилось МИМО нас (см. xrayStatsUser), и читать/писать файл там
    // второй раз незачем.
    public static function foldSession(array $p): array
    {
        $p['global'] = [
            'download' => ($p['global']['download'] ?? 0) + ($p['session']['download'] ?? 0),
            'upload'   => ($p['global']['upload'] ?? 0) + ($p['session']['upload'] ?? 0),
        ];
        $p['session'] = [
            'download' => 0,
            'upload'   => 0,
        ];
        // Разбивка по inbound'ам — снимок тех же счётчиков xray, которые его
        // рестарт обнуляет. В global она не сворачивается (это диагностика, не
        // учёт), но и оставлять её означало бы показывать в меню до минуты
        // цифры, которых в ядре уже нет.
        unset($p['inbounds']);
        // Узлы выхода: session — абсолютный счётчик ядра, base — его значение
        // в момент сброса счётчика админом (до следующего рестарта ядра).
        foreach (($p['exits'] ?? []) as $id => $v) {
            foreach (array_keys($v['modes']['raw'] ?? []) as $mode) {
                $p['exits'][$id]['modes']['raw'][$mode] = ['up' => 0, 'down' => 0];
            }
            foreach (['up', 'down'] as $dir) {
                $p['exits'][$id]['global'][$dir] = ($v['global'][$dir] ?? 0) + max(0, ($v['session'][$dir] ?? 0) - ($v['base'][$dir] ?? 0));
                $p['exits'][$id]['session'][$dir] = 0;
                $p['exits'][$id]['base'][$dir] = 0;
            }
        }
        foreach (($p['users'] ?? []) as $k => $v) {
            $p['users'][$k]['global']['download'] = ($v['global']['download'] ?? 0) + ($v['session']['download'] ?? 0);
            $p['users'][$k]['global']['upload']   = ($v['global']['upload'] ?? 0) + ($v['session']['upload'] ?? 0);
            $p['users'][$k]['session']['download'] = 0;
            $p['users'][$k]['session']['upload']   = 0;
        }
        return $p;
    }

    public function collectSession() {
        try {
            $this->withXrayStatsLock(function () {
                if ($this->setXrayStats(self::foldSession($this->getXrayStats())) === false) {
                    throw new RuntimeException('Could not persist Xray statistics');
                }
            });
        } catch (XrayStatsUnavailable $error) {
            // Preserve unknown state, but permit independent revocations and
            // quota enforcement to reach the running core.
            error_log('collectSession: Xray statistics unavailable; ledger preserved');
        }
    }

    public function setLang($lang)
    {
        $this->pacConfUpdate(function (&$conf) use ($lang) { $conf['language'] = $lang; });
        $this->language = $lang;
        Lang::$en = $this->language === 'en';
        $this->menu('config');
    }

    public function checkurl()
    {
        $r = $this->send(
            $this->input['chat'],
            $this->t("@{$this->input['username']} введите адрес", "@{$this->input['username']} enter url"),
            $this->input['message_id'],
            reply: $this->t('введите адрес', 'enter url'),
        );
        $this->stashReply($r, [
            'start_message'  => $this->input['message_id'],
            'start_callback' => $this->input['callback_id'],
            'callback'       => 'urlcheck',
            'args'           => [],
        ]);
    }

    public function urlcheck($url)
    {
        if (file_exists(__DIR__ . '/zapretlists/mpac')) {
            $domains = explode("\n", file_get_contents(__DIR__ . '/zapretlists/mpac'));
            // Проверка отвечала «match» ВСЕГДА: файл заканчивается переводом
            // строки, поэтому последним элементом идёт '', а preg_match('~~',…)
            // истинно для любой строки. Пустые строки отбрасываем, а $flag
            // инициализируем — иначе warning на каждом «not match».
            $flag = 0;
            foreach (array_filter($domains, fn($e) => trim($e) !== '') as $k => $v) {
                if (preg_match("~$v~", $url)) {
                    $flag = 1;
                    break;
                }
            }
            if ($flag) {
                $text = "$url\nmatch";
            } else {
                $text = "$url\nnot match";
            }
        } else {
            $text = 'no file, update pac';
        }
        $this->update($this->input['chat'], $this->input['message_id'], $text);
        sleep(3);
        $this->menu('pac');
    }

    public function sspswd()
    {
        $r = $this->send(
            $this->input['chat'],
            $this->t("@{$this->input['username']} введите пароль", "@{$this->input['username']} enter password"),
            $this->input['message_id'],
