    protected function normalizeOcCamouflageSecret($secret)
    {
        $secret = trim((string) $secret);
        if ($secret === '') {
            return '';
        }
        if (!preg_match('#^[A-Za-z0-9._~-]{1,128}$#', $secret)) {
            return false;
        }
        return $secret;
    }

    protected function extractOcCamouflageSecret(string $conf): string
    {
        if (preg_match('~^camouflage_secret\s*=\s*"((?:\\\\.|[^"\\\\])*)"~m', $conf, $m)) {
            return stripcslashes($m[1]);
        }
        if (preg_match('~^camouflage_secret\s*=\s*([^\s#]+)~m', $conf, $m)) {
            return trim($m[1], "\"'");
        }
        return '';
    }

    protected function ocCamouflageSecretForConf(string $conf, bool $migrate = false): string
    {
        $pac    = $this->getPacConf() ?: [];
        $secret = $this->normalizeOcCamouflageSecret($pac[self::OC_CAMOUFLAGE_SECRET] ?? '');
        if ($secret === false) {
            $secret = '';
        }

        if ($secret === '') {
            $legacy = $this->normalizeOcCamouflageSecret($this->extractOcCamouflageSecret($conf));
            if ($legacy !== false && $legacy !== '') {
                $secret = $legacy;
                if ($migrate) {
                    $secret = $this->pacConfUpdate(function (&$pac) use ($secret) {
                        $current = $this->normalizeOcCamouflageSecret($pac[self::OC_CAMOUFLAGE_SECRET] ?? '');
                        if ($current !== false && $current !== '') return $current;
                        $pac[self::OC_CAMOUFLAGE_SECRET] = $secret;
                        return $secret;
                    });
                }
            }
        }

        return $secret;
    }

    protected function applyOcCamouflage(string $conf, string $secret): string
    {
        $enabled    = $secret === '' ? 'false' : 'true';
        $secretLine = 'camouflage_secret = "' . addcslashes($secret, "\\\"") . '"';

        $conf = preg_replace('~^camouflage\s*=.*$~m', "camouflage = $enabled", $conf, 1, $count);
        if (!$count) {
            $conf .= "\ncamouflage = $enabled\n";
        }

        $conf = preg_replace_callback('~^camouflage_secret\s*=.*$~m', fn () => $secretLine, $conf, 1, $count);
        if (!$count) {
            $conf .= "$secretLine\n";
        }

        return $conf;
    }

    protected function ocConnectionUrl(string $secret = ''): string
    {
        $domain = $this->getDomain();
        $oc     = $this->getHashSubdomain('oc');
        $host   = trim(($oc ? "$oc." : '') . $domain, '.');

        if ($host === '') {
            $host = $this->ip;
        }

        return 'https://' . $host . '/' . ($secret === '' ? '' : '?' . rawurlencode($secret));
    }

    protected function normalizeOcUsername($user)
    {
        $user = trim((string) $user);
        if (!preg_match('#^[A-Za-z0-9._-]{1,64}$#', $user)) {
            return false;
        }
        return $user;
    }

    protected function normalizeOcPassword($pass)
    {
        $pass = trim((string) $pass);
        if ($pass === '' || strlen($pass) > 128 || preg_match('/[\r\n]/', $pass)) {
            return false;
        }
        return $pass;
    }

    protected function genOcPassword(): string
    {
        return bin2hex(random_bytes(16));
    }

    protected function syncOcUsers(?array $clients = null): array
    {
        $users = $this->withLock('oc-users', fn() => $this->syncOcUsersLocked($clients));
        if (!is_array($users)) throw new RuntimeException($this->t('Не удалось заблокировать пользователей OpenConnect', 'Could not lock OpenConnect users'));
        return $users;
    }

    // Только под oc-users; pac удерживается лишь на recovery/commit, без RPC.
    private function syncOcUsersLocked(?array $clients = null): array
    {
        if ($this->withLock('pac', fn() => $this->recoverOcPasswordUpdateLocked(), 20, false) !== true) {
            throw new RuntimeException($this->t('Восстановление паролей OpenConnect не подтверждено', 'OpenConnect password recovery is not confirmed'));
        }
        $clients = $clients ?? $this->getClientsOc();
        return $this->pacConfUpdate(function (&$pac) use ($clients) {
            $current = is_array($pac[self::OC_USERS] ?? null) ? $pac[self::OC_USERS] : [];
            $legacy = (string) ($pac['ocserv'] ?? '');
            $users = [];
            foreach ($clients as $user) {
                if (array_key_exists($user, $current)) $users[$user] = (string) $current[$user];
                elseif ($legacy !== '') $users[$user] = $legacy;
            }
            $pac[self::OC_USERS] = $users;
            return $users;
        });
    }

    // callback получает согласованный passwd; его PAC/TeleMT snapshot надо
    // прочитать здесь же. Не вызывать из callback другие владельцы oc-users.
    protected function withOcUsersSnapshot(callable $fn)
    {
        $entered = false;
        $result = $this->withLock('oc-users', function () use ($fn, &$entered) {
            $entered = true;
            $this->syncOcUsersLocked();
            $raw = @file_get_contents($this->ocPasswordPath());
            if ($raw === false) throw new RuntimeException('OpenConnect password snapshot is unavailable');
            return $fn($raw);
        });
        if (!$entered) throw new RuntimeException('OpenConnect snapshot lock is unavailable');
        return $result;
    }

    public static function ocPasswordFile(string $contents, string $user, ?string $hash): string
    {
        $lines = [];
        $group = '*';
        foreach (explode("\n", rtrim($contents, "\n")) as $line) {
            if (str_starts_with($line, $user . ':')) {
                $group = explode(':', $line, 3)[1];
            } elseif ($line !== '') {
                $lines[] = $line;
            }
        }
        if ($hash !== null) $lines[] = "$user:$group:$hash";
        return $lines ? implode("\n", $lines) . "\n" : '';
    }

    protected function ocPasswordPath(): string
    {
        return '/config/ocserv.passwd';
    }

    // Вызывается только под oc-users → pac. Prepared означает: публикация
    // двух файлов не подтверждена; следующий процесс обязан вернуть оба.
    private function recoverOcPasswordUpdateLocked(bool $rollback = false): bool
    {
        $path = $this->ocPasswordPath(); $journal = $path . '.update.json';
        if (!file_exists($journal) && !is_link($journal)) return true;
        if (is_link($journal) || !is_file($journal)) return false;
        try {
            $intent = json_decode((string) file_get_contents($journal), true, 32, JSON_THROW_ON_ERROR);
            if (($intent['version'] ?? null) !== 1 || !in_array($intent['phase'] ?? '', ['prepared', 'committed'], true)
                || !is_string($intent['password_file'] ?? null) || !is_bool($intent['users_present'] ?? null)
                || !is_array($intent['users'] ?? null)
                || (array_key_exists('password_present', $intent) && !is_bool($intent['password_present']))
                || (array_key_exists('legacy_present', $intent) && (!is_bool($intent['legacy_present']) || !is_string($intent['legacy'] ?? null)))) return false;
            $raw = base64_decode($intent['password_file'], true);
            if ($raw === false) return false;
            if ($rollback || $intent['phase'] === 'prepared') {
                $pac = $this->getPacConf();
                if (!is_array($pac)) return false;
                if ($intent['users_present']) $pac[self::OC_USERS] = $intent['users']; else unset($pac[self::OC_USERS]);
                // Старые version=1 journals не содержали legacy/presence полей.
                if (array_key_exists('legacy_present', $intent)) {
                    if ($intent['legacy_present']) $pac['ocserv'] = $intent['legacy']; else unset($pac['ocserv']);
                }
                // false после rename/fsync тоже требует компенсации ОБОИХ файлов.
                $passwordRestored = ($intent['password_present'] ?? true)
                    ? $this->writePrivateKey($path, $raw)
                    : ((!file_exists($path) && !is_link($path)) || @unlink($path));
                $pacRestored = $this->setPacConf($pac) !== false;
                if (!$passwordRestored || !$pacRestored) return false;
            }
            if (!@unlink($journal)) return false;
            $dir = @fopen(dirname($journal), 'r');
            if ($dir === false) return false;
            try { return fsync($dir); } finally { fclose($dir); }
        } catch (Throwable $e) {
            error_log('OpenConnect password recovery not confirmed');
            return false;
        }
    }

    // Вызывать только под oc-users → pac, после recovery. Содержимое двух
    // файлов публикуется вместе; prepared journal восстанавливает только OC.
    private function writeOcPasswordPairLocked(string $raw, array $next): bool
    {
        $path = $this->ocPasswordPath(); $journal = $path . '.update.json';
        $present = file_exists($path) || is_link($path);
        $old = $present ? @file_get_contents($path) : '';
        $pac = $this->getPacConf();
        if ($old === false || !is_array($pac)) return false;
        $intent = ['version' => 1, 'phase' => 'prepared', 'password_file' => base64_encode($old), 'password_present' => $present,
            'users_present' => array_key_exists(self::OC_USERS, $pac), 'users' => is_array($pac[self::OC_USERS] ?? null) ? $pac[self::OC_USERS] : [],
            'legacy_present' => array_key_exists('ocserv', $pac), 'legacy' => (string) ($pac['ocserv'] ?? '')];
        try {
            if (!$this->writePrivateKey($journal, json_encode($intent, JSON_THROW_ON_ERROR))) {
                $this->recoverOcPasswordUpdateLocked(true);
                return false;
            }
            $passwordSaved = $this->writePrivateKey($path, $raw);
            $pacSaved = $passwordSaved && $this->setPacConf($next) !== false;
            if (!$pacSaved) {
                if (!$this->recoverOcPasswordUpdateLocked(true)) error_log('OpenConnect password rollback not confirmed');
                return false;
            }
            $intent['phase'] = 'committed';
            if (!$this->writePrivateKey($journal, json_encode($intent, JSON_THROW_ON_ERROR))) {
                if (!$this->recoverOcPasswordUpdateLocked(true)) error_log('OpenConnect password rollback not confirmed');
                return false;
            }
            // Committed intent is safe to retain: recovery only removes it.
            $this->recoverOcPasswordUpdateLocked();
            return true;
        } catch (Throwable $e) {
            if (!$this->recoverOcPasswordUpdateLocked(true)) error_log('OpenConnect password rollback not confirmed');
            return false;
        }
    }

    // Полная замена только OC-пары: остальные PAC поля всегда берутся свежими.
    // Ранний full PAC restore должен сохранять текущие ocserv/ocserv_users.
    protected function restoreOcPasswordPair(string $raw, array $sourcePac): bool
    {
        if (array_key_exists(self::OC_USERS, $sourcePac) && !is_array($sourcePac[self::OC_USERS])) return false;
        if (array_key_exists('ocserv', $sourcePac) && !is_string($sourcePac['ocserv'])) return false;
        foreach ($sourcePac[self::OC_USERS] ?? [] as $pass) if (!is_string($pass)) return false;
        return $this->withLock('oc-users', function () use ($raw, $sourcePac) {
            return $this->withLock('pac', function () use ($raw, $sourcePac) {
                if (!$this->recoverOcPasswordUpdateLocked()) return false;
                $next = $this->getPacConf();
                if (!is_array($next)) return false;
                foreach ([self::OC_USERS, 'ocserv'] as $key) {
                    if (array_key_exists($key, $sourcePac)) $next[$key] = $sourcePac[$key]; else unset($next[$key]);
                }
                return $this->writeOcPasswordPairLocked($raw, $next);
            }, 20, false);
        }, 20, false) === true;
    }

    protected function saveOcPassword(string $user, ?string $pass): bool
    {
        return $this->withLock('oc-users', function () use ($user, $pass) {
            return $this->withLock('pac', function () use ($user, $pass) {
                if (!$this->recoverOcPasswordUpdateLocked()) return false;
                $raw = @file_get_contents($this->ocPasswordPath()); $pac = $this->getPacConf();
                if ($raw === false || !is_array($pac)) return false;
                $hash = $pass === null ? null : crypt($pass, '$6$' . bin2hex(random_bytes(8)) . '$');
                if ($hash !== null && !str_starts_with($hash, '$6$')) return false;
                $users = is_array($pac[self::OC_USERS] ?? null) ? $pac[self::OC_USERS] : [];
                if ($pass === null) unset($users[$user]); else $users[$user] = $pass;
                $pac[self::OC_USERS] = $users;
                return $this->writeOcPasswordPairLocked(self::ocPasswordFile($raw, $user, $hash), $pac);
            }, 20, false);
        }, 20, false) === true;
    }

    protected function setOcUserPassword(string $user, string $pass): bool
    {
        if (!$this->saveOcPassword($user, $pass)) {
            $this->send($this->input['chat'], $this->t('OpenConnect: не удалось сохранить пароль', 'OpenConnect: could not save the password'));
            return false;
        }
        $this->restartOcserv(file_get_contents('/config/ocserv.conf'));
        return true;
    }

    protected function getOcOnlineUsers(?array $clients = null): array
    {
        $clients = $clients ?? $this->getClientsOc();
        if (empty($clients)) {
            return [];
        }

        $out = (string) $this->ssh('occtl show users 2>/dev/null', 'oc');
        if (trim($out) === '') {
            return [];
        }

        $online = [];
        foreach ($clients as $user) {
            if (preg_match('~(?<![A-Za-z0-9._-])' . preg_quote($user, '~') . '(?![A-Za-z0-9._-])~', $out)) {
                $online[$user] = true;
            }
        }

        return $online;
    }

    public function syncOcservCamouflage()
    {
        $this->editUpstream(fn($upstream) => self::ocservDtlsUpstream($upstream));
        if (!$this->protocolModuleEnabled('oc')) return;
        $conf   = file_get_contents('/config/ocserv.conf');
        $secret = $this->ocCamouflageSecretForConf($conf, true);
        $next   = $this->applyOcCamouflage($conf, $secret);

        if ($next !== $conf) {
            $this->restartOcserv($next, false);
        }
    }

    public function restartOcserv($conf, bool $syncCamouflage = true)
    {
        return $this->withLock('oc-users', function () use ($conf, $syncCamouflage) {
            if ($this->withLock('pac', fn() => $this->recoverOcPasswordUpdateLocked(), 20, false) !== true) return false;
            return $this->restartOcservLocked($conf, $syncCamouflage);
        }, 20, false);
    }

    private function restartOcservLocked($conf, bool $syncCamouflage = true)
    {
        if ($syncCamouflage) {
            $conf = $this->applyOcCamouflage($conf, $this->ocCamouflageSecretForConf($conf, true));
        }
        // Тот же класс, что в restartNaive(): сюда приезжает результат
        // preg_replace* от пятерых вызывающих, а движок при ошибке отдаёт null —
        // file_put_contents записал бы пустой ocserv.conf, и сервис не поднялся
        // бы уже никогда, без единого сообщения.
        if (!is_string($conf) || trim($conf) === '') {
            error_log('restartOcserv: ocserv.conf not written — empty config');

            return false;
        }
        if (!$this->writePrivateKey('/config/ocserv.conf', $conf)) return false;
        if (!$this->protocolModuleEnabled('oc')) return true;
        $this->ssh('pkill ocserv', 'oc');
        $pac = $this->getPacConf();
        $ocUsers = is_array($pac[self::OC_USERS] ?? null)
            ? array_filter($pac[self::OC_USERS], fn ($pass) => (string) $pass !== '')
            : [];
        if ((!empty($pac['ocserv']) || !empty($ocUsers)) && !empty($this->getHashSubdomain('oc'))) {
            $this->ssh('mkdir -p /logs; touch /logs/ocserv.log', 'oc');
            $this->ssh('ocserv -f -c /etc/ocserv/ocserv.conf', 'oc', false, '/logs/ocserv.log');
        }
        return true;
    }

    // Логин/пароль naive уезжают в Caddyfile строкой «basic_auth <user> <pass>»,
    // то есть в СИНТАКСИС конфига. Пробел разбил бы директиву на лишние
    // аргументы, `}` или перевод строки — развалили бы блок, `#` съел бы
    // остаток строки, и caddy просто не поднялся бы. Разрешаем только то, что
    // заведомо безопасно и внутри Caddyfile, и в userinfo ссылки.
    //
    // Разделитель регулярки — '#', а не привычный '~': '~' входит в разрешённый
    // набор (unreserved по RFC 3986), и как делимитр он обрывал шаблон на
    // середине класса — preg_match ругался «Unknown modifier '!'» и возвращал
    // false ВСЕГДА, то есть любой пароль считался бы негодным и naive гасился
    // бы на рестарте.
    public static function naiveCredOk($v): bool
    {
        return is_string($v) && $v !== '' && strlen($v) <= 128
            && (bool) preg_match('#^[A-Za-z0-9._~!$&\'()*+,;=:@%-]+$#D', $v);
    }

    // Есть ли смысл показывать ссылку naive: пока креды пустые/негодные,
    // restartNaive пишет в Caddyfile плейсхолдер, а start_np.sh по нему гасит
    // caddy — ссылка вела бы в никуда. CHANGEME проверяем отдельно: формально
    // он валиден (naiveCredOk), но это ровно то значение, по которому гард в
    // start_np.sh не поднимает сервис.
    public static function naiveReady($pac): bool
    {
        $user = $pac['naive']['user'] ?? null;
        $pass = $pac['naive']['pass'] ?? null;
        // Домен обязателен наравне с кредами: клиент naive берёт SNI из хоста
        // ссылки и проверяет по нему сертификат. Без домена linkNaive() собирал
        // «https://user:pass@<hash>.» — ссылку, которая не работает нигде, а
        // проверка кредов её пропускала.
        if (empty($pac['domain'])) {
            return false;
        }
        return self::naiveCredOk($user) && self::naiveCredOk($pass)
            && !($user === 'CHANGEME' && $pass === 'CHANGEME');
    }

    public static function migrateNaiveAcl(string $conf): string
    {
        // Исправляем только прежний штатный ACL. allow all перед встроенными
        // правилами forwardproxy открывал приватные адреса на портах 80/443.
        return preg_replace(
            '~(acl\s*\{\s*deny\s+169\.254\.0\.0/16\s+deny\s+100\.64\.0\.0/10)\s+allow\s+all(\s*\})~',
            '$1$2',
            $conf
        ) ?? $conf;
    }

    public function restartNaive()
    {
        return $this->withLock('naive', fn() => $this->applyNaive());
    }

    public function controlContainerService(string $container, string $service, string $action): bool
    {
        if (!preg_match('~^[a-z0-9-]+$~D', $container)
            || !in_array($service, ['adguard', 'ssserver', 'sslocal', 'ck-server', 'simple-tls', 'naive', 'trusttunnel', 'dnstt'], true)
            || !in_array($action, ['start', 'stop', 'restart'], true)) throw new InvalidArgumentException('Invalid service operation');
        $result = $this->ssh('/bin/sh /service_supervisor.sh ' . $action . ' ' . $service, $container);
        $marker = $action === 'stop' ? 'VPNBOT_SERVICE_STOPPED:' : 'VPNBOT_SERVICE_READY:';
        return !$this->sshFailed && trim((string) $result) === $marker . $service;
    }

    public static function migrateNaiveTimeout(string $conf): string
    {
        // Дополняем только штатный servers-блок без ручной timeout-политики.
        // Сохранённый Caddyfile переживает обновление и восстановление бэкапа.
        if (preg_match('~^[ \t]*(?:timeouts|read_body_idle)\b~m', $conf)
            || preg_match_all('~^[ \t]*servers[ \t]*\{[ \t]*$~m', $conf) !== 1) {
            return $conf;
        }
        return preg_replace('~(^[ \t]*servers[ \t]*\{[ \t]*$)~m',
            "$1\n\t\ttimeouts {\n\t\t\tread_body_idle -1s\n\t\t}", $conf, 1) ?? $conf;
    }

    private function applyNaive()
    {
        $pac  = $this->getPacConf();
        $user = (string) ($pac['naive']['user'] ?? '');
        $pass = (string) ($pac['naive']['pass'] ?? '');
        $c    = self::migrateNaiveTimeout(self::migrateNaiveAcl(file_get_contents('/config/Caddyfile')));
        // Плейсхолдер — то же значение, что в шаблоне config/Caddyfile: пока
        // креды не заданы, caddy не должен подниматься (тот же гард в
        // start_np.sh), иначе сервис работает с угадываемым паролем.
        $ok = self::naiveCredOk($user) && self::naiveCredOk($pass)
            && !($user === 'CHANGEME' && $pass === 'CHANGEME');
        // preg_replace_callback, а не preg_replace: user/pass идут в замену как
        // литералы (иначе `$`/`\` в пароле трактуются как backreference).
        $t = preg_replace_callback(
            '~^([ \t]*)basic_auth[ \t]+[^\n]+~m',
            fn($m) => ($m[1] ?? '') . 'basic_auth ' . ($ok ? "$user $pass" : 'CHANGEME CHANGEME'),
            $c,
            -1,
            $replacements
        );
        // Не запускать конфиг без аутентификации или с неоднозначными реквизитами.
        // preg_replace_callback отдаёт null при ошибке движка.
        if (!is_string($t) || $t === '' || $replacements !== 1) {
            error_log('restartNaive: Caddyfile not written — expected one basic_auth directive');

            return false;
        }
        if (!$ok || empty($this->getHashSubdomain('np'))) {
            // Пока реквизиты неполные или нет поддомена, Naive выключен: заглушка
            // отзывает прежний пароль (start_np.sh по ней caddy не поднимает), а
            // служба останавливается. null — выключено намеренно, false — отказ.
            if (!$this->writePrivateKey('/config/Caddyfile', $t)) {
                throw new RuntimeException($this->t('Не удалось сохранить конфигурацию Naive', 'Could not save the Naive configuration'));
            }
            return $this->controlContainerService('np', 'naive', 'stop') ? null : false;
        }
        // Проверяем отдельный кандидат до замены активного файла и остановки.
        // Вывод валидатора может содержать реквизиты, поэтому нужен только marker.
        $candidate = '/config/Caddyfile.pending-' . bin2hex(random_bytes(8));
        try {
            if (!$this->writePrivateKey($candidate, $t)) {
                throw new RuntimeException($this->t('Не удалось сохранить конфигурацию Naive', 'Could not save the Naive configuration'));
            }
            $v = $this->ssh('caddy validate -c ' . escapeshellarg($candidate) . ' >/dev/null 2>&1 && printf VPNBOT_NAIVE_VALID', 'np');
            if ($this->sshFailed || trim((string) $v) !== 'VPNBOT_NAIVE_VALID') return false;
            // /config монтируется каталогом: атомарная замена видна контейнеру.
            if (!$this->writePrivateKey('/config/Caddyfile', $t)) {
                throw new RuntimeException($this->t('Не удалось сохранить конфигурацию Naive', 'Could not save the Naive configuration'));
            }
        } finally {
            if (is_file($candidate)) unlink($candidate);
        }
        return $this->controlContainerService('np', 'naive', 'restart');
    }

    public static function hysteriaGuard(array $conf): array
    {
        // Внешний ACL — ручная политика администратора. Не смешиваем file и
        // inline: Hysteria запрещает одновременно использовать оба формата.
        if (!empty($conf['acl']['file'])) return $conf;
        $guard = [
            'direct(10.10.0.5, */53)',
            'reject(0.0.0.0/8)', 'reject(10.0.0.0/8)', 'reject(127.0.0.0/8)',
            'reject(169.254.0.0/16)', 'reject(172.16.0.0/12)', 'reject(192.168.0.0/16)',
            'reject(100.64.0.0/10)', 'reject(::/128)', 'reject(::1/128)',
            'reject(fc00::/7)', 'reject(fe80::/10)',
        ];
        $conf['acl']['inline'] = array_values(array_unique(array_merge($guard, $conf['acl']['inline'] ?? [])));
        return $conf;
    }

    public int $hysteriaApplyTimeout = 30;

    // runtime/status.json службы: config_sha256 — работающий файл, checked_sha256 —
    // последний проверенный. Отказ окончателен, только когда отвергнут именно наш файл.
    private function hysteriaConfirmApplied(string $sha): bool
    {
        $file = $this->hysteriaUsersRoot . '/runtime/status.json';
        $deadline = microtime(true) + $this->hysteriaApplyTimeout;
        do {
            clearstatcache(true, $file);
            $status = json_decode((string) @file_get_contents($file), true);
            if (is_array($status)) {
                // Служба прежнего образа не сообщает, какой файл работает.
                if (!array_key_exists('config_sha256', $status)) return true;
                $error = (string) ($status['error'] ?? '');
                if ($status['config_sha256'] === $sha && !empty($status['running']) && $error === '') return true;
                if ($error !== '' && ($status['checked_sha256'] ?? null) === $sha && $status['config_sha256'] !== $sha) {
                    error_log('Hysteria: the service rejected the new configuration; the previous one keeps running');
                    return false;
                }
            }
            usleep(200000);
        } while (microtime(true) < $deadline);
        error_log('Hysteria: the service did not confirm the new configuration');
        return false;
    }

    public function restartHysteria()
    {
        return $this->withLock('hysteria', fn() => $this->restartHysteriaLocked());
    }

    private function restartHysteriaLocked(): bool
    {
        $pac = $this->getPacConf();
        $c = @yaml_parse_file($this->hysteriaConf);
        if (!is_array($c)) {
            error_log('Hysteria: configuration could not be read; running core preserved');
            return false;
        }
        $c = self::hysteriaGuard($c);
        $c['auth']['password'] = $pac['hysteria_pass'] ?? '';

        // obfs — обфускация QUIC-пакетов общим секретом, ломает QUIC-фингерпринтинг
        // и активные пробы. Пароль и тип ОБЯЗАНЫ совпадать у всех клиентов (идут в
        // hy2://-ссылку). Пусто = obfs выключен.
        // bandwidth включает congestion control Brutal (агрессивный, лучше на
        // потерях/перегруженных каналах). Без значений — контроллер из hysteria_cc.
        $c = $this->hyApplyTuning($c, $pac);

        // Masquerade decoy host (server-only): reverse-proxy для зондов на тот
        // же UDP-порт. Кастомный hysteria_sni имеет приоритет над доменом; см.
        // chHySNI()/setHyMasq(). Это НЕ клиентский TLS SNI (тот = домен).
        $sni = !empty($pac['hysteria_sni']) ? $pac['hysteria_sni'] : $this->getDomain();
        if (!empty($sni)) {
            $c['masquerade']['type']                 = 'proxy';
            $c['masquerade']['proxy']['url']         = "https://$sni";
            $c['masquerade']['proxy']['rewriteHost'] = true;
        }
        $yaml = yaml_emit($c);
        if (!is_string($yaml) || !$this->writePrivateKey($this->hysteriaConf, $yaml)) return false;
        // Выключенный контейнер сохраняет настройки и пользователей, но не
        // обязан отвечать на проверку supervisor во время восстановления.
        if (!$this->protocolModuleEnabled('hy')) return true;
        // New images validate/apply changes and enforce personal restrictions
        // themselves. Old images keep the shared-password lifecycle.
        // Служба проверяет файл и при отказе продолжает работать с прежним, поэтому
        // успех — только её подтверждение SHA-256 именно записанного YAML.
        if (trim((string) $this->ssh('test -f /hysteria_service.py && printf managed', 'hy')) === 'managed') {
            return $this->hysteriaConfirmApplied(hash('sha256', $yaml));
        }
        if (is_file($this->hysteriaUsersRoot . '/users.json')) return false;
        $this->ssh('pkill hysteria', 'hy');
        if (!empty($pac['hysteria_pass'])) {
            $this->ssh('hysteria server -c ' . escapeshellarg($this->hysteriaConf), 'hy', false, '/logs/hysteria');
        }
        return true;
    }

    // Список реальных decoy-сайтов для masquerade. Указывать на реальный
    // сторонний сайт (а не на собственный IP/nip.io) — иначе зонд видит не
    // убедительную легенду. Используется hyMasqMenu()/setHyMasq().
    public function hyMasqPresets()
    {
        return [
            'www.bing.com',
            'news.ycombinator.com',
            'www.cloudflare.com',
            'www.microsoft.com',
            'www.apple.com',
            'mirror.gcr.io',
        ];
    }

    // hy2://-ссылка для клиента. host/port — внешние (домен:порт-проброс),
    // sni добавляем только при коннекте по IP без домена. obfs/insecure
    // прокидываем из pac. Возвращает '' если нет пароля или порт скрыт.
    // $relay (запись из $pac['relays'] с 'hy_address') подменяет ТОЛЬКО адрес
    // и порт (через hy_portmap) на relay — sni/obfs/пароль остаются от origin:
    // TLS/QUIC терминируется на origin через DNAT. Отдельная пара
    // hy_address/hy_portmap — по образцу awg_address/awg_portmap: hysteria-канал
    // (UDP) у relay может жить на другом хосте/портах, чем TCP vless.
    public function linkHysteria($relay = null, ?string $credential = null)
    {
        $pac   = $this->getPacConf();
        $ports = $this->getPorts();
        $port  = $ports['hy']['enable'] ? $ports['hy']['port'] : null;
        $pass  = $credential ?? ($pac['hysteria_pass'] ?? '');
        // Port hopping: клиент бьёт по диапазону портов, а firewall (ручной nft
        // либо docker) реднатит весь диапазон на реальный порт Hysteria. Диапазон
        // в Hysteria 2 кодируется прямо в host:port части ссылки (host:20000-50000,
        // мультипорт через запятую/дефис) — НЕ отдельным query-параметром. Когда
        // hopping включён, одиночный реальный порт в ссылке не нужен (клиент его
        // не использует), поэтому ссылку отдаём даже если getPorts его не видит.
        $hop      = $pac['hysteria_hop'] ?? '';
        $portSpec = $hop !== '' ? $hop : $port;
        if (empty($pass) || empty($portSpec)) {
            return '';
        }
        $domain = $this->getDomain();
        $host   = $domain ?: $this->ip;
        $label  = $host;
        if (is_array($relay) && !empty($relay['hy_address'])) {
            // Явный hy_port перебивает всё: relay слушает один UDP-порт, и
            // диапазон хоппинга в ссылке схлопывается в него (сам хоппинг на
            // origin при этом остаётся — им пользуются прямые подключения).
            // Иначе одиночные порты прогоняем через hy_portmap (как
            // applyAwgRelay — только своя карта, без отката на общий
            // vless-portmap); диапазоны N-M через одиночную карту не
            // отобразить — остаются как есть (relay должен реднатить тот же
            // диапазон).
            $map      = $relay['hy_portmap'] ?? [];
            $portSpec = ($fixed = self::relayPortInput($relay['hy_port'] ?? '')) !== ''
                ? $fixed
                : implode(',', array_map(
                    fn($t) => preg_match('~^\d+$~', $t) ? (string) ($map[$t] ?? $t) : $t,
                    preg_split('~,~', (string) $portSpec, -1, PREG_SPLIT_NO_EMPTY),
                ));
            if ($portSpec === '') {
                return '';
            }
            $host  = $relay['hy_address'];
            // Метка в стиле relay-подписок: флаг relay, затем origin.
            $label = $this->flagName($host, [$relay['hy_address'], $this->ip]);
        }
        $q = [];
        // Клиентский TLS SNI = домен сертификата. Указываем ВСЕГДА, когда домен
        // известен: многие клиенты не подставляют SNI из host автоматически
        // при импорте ссылки, а без верного SNI (совпадающего с сертификатом)
        // валидация TLS у клиента падает. При коннекте по IP без домена SNI
        // опускаем — там self-signed, клиент идёт с insecure.
        if (!empty($domain)) {
            $q['sni'] = $domain;
        }
        if (!empty($pac['hysteria_insecure'])) {
            $q['insecure'] = '1';
        }
        if (!empty($pac['hysteria_obfs'])) {
            $q['obfs']          = $this->hyObfsType($pac);
            $q['obfs-password'] = $pac['hysteria_obfs'];
        }
        $query = $q ? '?' . http_build_query($q) : '';
        // #fragment — отображаемое имя подключения в клиенте; без него поле
        // имени пустое. Используем хост (домен/IP) как узнаваемую метку; для
        // relay — адрес relay с флагами (relay + origin).
        $name = '#' . rawurlencode($label);
        if (filter_var($host, FILTER_VALIDATE_IP, FILTER_FLAG_IPV6)) $host = '[' . $host . ']';
        return 'hysteria2://' . rawurlencode($pass) . "@$host:$portSpec/$query$name";
    }

    // $dns уходит директивой в ocserv.conf, а приходит сырым текстом сообщения:
    // многострочный ввод превращал каждую строку после первой в самостоятельную
    // директиву конфига. Принимаем только адрес (IPv4/IPv6) — ровно то, что
    // ocserv в этом поле и ждёт; ср. chHySNI/chStlsSNI, где проверка уже есть.
    public function chocdns($dns)
    {
        $dns = trim((string) $dns);
        if (filter_var($dns, FILTER_VALIDATE_IP) === false) {
            $this->send($this->input['chat'], $this->t("$dns: неверный адрес DNS", "$dns - wrong dns address"), $this->input['message_id']);
            return $this->menu('oc');
        }
        $c = file_get_contents('/config/ocserv.conf');
        $t = preg_replace_callback('~^dns[^\n]+~sm', fn() => "dns = $dns", $c);
        $this->restartOcserv($t);
        $this->menu('oc');
    }

    // Поддомен — ОДНА метка имени: она склеивается с основным доменом
    // («<sub>.<domain>») и уезжает в upstream.conf и ocserv.conf. Точку тоже не
    // пускаем: своей зоны у метки быть не может, а сертификат выписан на
    // *.<domain>, то есть только на один уровень.
    public static function isSubdomainLabel($v): bool
    {
        return (bool) preg_match('~^[a-zA-Z0-9]([a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?$~', (string) $v);
    }

    public function chOcSubdomain($domain)
    {
        if ($domain != -1 && !self::isSubdomainLabel($domain)) {
            $this->send($this->input['chat'], $this->t("$domain: неверный формат поддомена", "$domain - wrong subdomain format"), $this->input['message_id']);
            return $this->menu('oc');
        }
        $pac = $this->pacConfUpdate(function (&$pac) use ($domain) {
            if ($domain == -1) unset($pac['oc_domain']);
            else $pac['oc_domain'] = $domain;
            return $pac;
        });
        // ?? '' — поддомен можно задать до основного домена: тогда обе функции
        // получают пустую строку (их штатный «сброс»), а не warning.
        $this->chocdomain($pac['domain'] ?? '');
        $this->setUpstreamDomainOcserv($pac['domain'] ?? '');
        $this->menu('oc');
    }

    public function chNpSubdomain($domain)
    {
        if ($domain != -1 && !self::isSubdomainLabel($domain)) {
            $this->send($this->input['chat'], $this->t("$domain: неверный формат поддомена", "$domain - wrong subdomain format"), $this->input['message_id']);
            return $this->menu('naive');
        }
        $pac = $this->pacConfUpdate(function (&$pac) use ($domain) {
            if ($domain == -1) unset($pac['np_domain']);
            else $pac['np_domain'] = $domain;
            return $pac;
        });
        if ($this->restartNaive() === false) throw new RuntimeException($this->t(
            'Naive: настройки сохранены, но применение не подтверждено. Прежний доступ может ещё действовать; повторите операцию.',
            'Naive: settings were saved but application was not confirmed. Previous access may still work; retry the operation.'));
        $this->setUpstreamDomainNaive($pac['domain'] ?? '');
        $this->menu('naive');
    }

    // Отказ вместо тихой поломки: значение уходит в синтаксис Caddyfile, и
    // раньше пробел или `}` в пароле роняли caddy без единого сообщения
    // (см. naiveCredOk / restartNaive).
    public function naiveCredReject(): void
    {
        $this->update(
            $this->input['chat'],
            $this->input['message_id'],
            $this->t('значение не принято: допустимы латиница, цифры и . _ ~ - ! $ & \' ( ) * + , ; = : @ % (до 128 символов), без пробелов', 'value rejected: allowed are Latin letters, digits and . _ ~ - ! $ & \' ( ) * + , ; = : @ % (up to 128 characters), no spaces')
        );
        sleep(3);
        $this->menu('naive');
    }

    public function chnplogin($user)
    {
        $user = trim((string) $user);
        if (!self::naiveCredOk($user)) {
            return $this->naiveCredReject();
        }
        $this->pacConfUpdate(function (&$pac) use ($user) { $pac['naive']['user'] = $user; });
        if ($this->restartNaive() === false) throw new RuntimeException($this->t(
            'Naive: настройки сохранены, но применение не подтверждено. Прежний доступ может ещё действовать; повторите операцию.',
            'Naive: settings were saved but application was not confirmed. Previous access may still work; retry the operation.'));
        $this->menu('naive');
    }

    public function chnppass($pass)
    {
        $pass = trim((string) $pass);
        if (!self::naiveCredOk($pass)) {
            return $this->naiveCredReject();
        }
        $this->pacConfUpdate(function (&$pac) use ($pass) { $pac['naive']['pass'] = $pass; });
        if ($this->restartNaive() === false) throw new RuntimeException($this->t(
            'Naive: настройки сохранены, но применение не подтверждено. Прежний доступ может ещё действовать; повторите операцию.',
            'Naive: settings were saved but application was not confirmed. Previous access may still work; retry the operation.'));
        $this->menu('naive');
    }

    public function genNaivePass()
    {
        // 16 случайных байт в hex — 32 печатных символа, как у SS, Hysteria,
        // OpenConnect, Xray и пароля панели.
        $this->chnppass(bin2hex(random_bytes(16)));
    }

    public function chhypass($pass)
    {
        [$before, $after] = $this->pacConfUpdate(function (&$pac) use ($pass) {
            $before = $pac;
            if (!empty($pass)) {
                $pac['hysteria_pass'] = $pass;
            } else {
                unset($pac['hysteria_pass']);
            }
            return [$before, $pac];
        });
        if (!$this->restartHysteria()) {
            // Служба не приняла пароль и работает со старым: настройки и YAML
            // возвращаются к нему, чтобы ссылки клиентов совпадали с сервером.
            $restored = $this->restorePacFields($before, $after, ['hysteria_pass']) && $this->restartHysteria();
            $this->send($this->input['chat'], $restored
                ? $this->t('Hysteria не приняла новый пароль: действует прежний.', 'Hysteria rejected the new password: the previous one stays in effect.')
                : $this->t('Hysteria не приняла новый пароль; возврат прежнего не подтверждён — проверьте службу.', 'Hysteria rejected the new password; restoring the previous one is unconfirmed — check the service.'));
        }
        $this->menu('hy');
    }

    // Генерация случайного пароля для hysteria (32 hex-символа, как у SS).
    // Переиспользуем chhypass(): он сохраняет pac, рестартит демон и
    // перерисовывает меню.
    public function genHyPass()
    {
        $this->chhypass(bin2hex(random_bytes(16)));
    }

    public function changeHySNI()
    {
        $r = $this->send(
            $this->input['chat'],
            $this->t("@{$this->input['username']} введите SNI Hysteria / домен маскировки (например {$this->getDomain()}), <code>0</code> = по умолчанию", "@{$this->input['username']} enter hysteria SNI / masquerade host (e.g. {$this->getDomain()}), <code>0</code> = default"),
            $this->input['message_id'],
            reply: $this->t('введите SNI Hysteria', 'enter hysteria SNI'),
        );
        $this->stashReply($r, [
            'start_message'  => $this->input['message_id'],
            'start_callback' => $this->input['callback_id'],
            'callback'       => 'chHySNI',
            'args'           => [],
        ]);
    }

    // SNI hysteria — это host в masquerade.proxy.url (decoy-сайт для
    // неаутентифицированных запросов). Храним кастомный выбор в pac, чтобы
    // restartHysteria() не затирал его доменом. Пустой ввод сбрасывает на
    // домен по умолчанию.
    public function chHySNI($name)
    {
        $name = trim($name);
        if ($name !== '' && $name !== '0' && !preg_match('~^[A-Za-z0-9.-]+$~D', $name)) return $this->menu('hy');
        $this->pacConfUpdate(function (&$pac) use ($name) {
            if ($name === '' || $name === '0') unset($pac['hysteria_sni']);
            else $pac['hysteria_sni'] = $name;
        });
        $this->restartHysteria();
        $this->menu('hy');
    }

    // Salamander obfs on/off. При включении генерируем пароль, если его нет;
    // при выключении НЕ стираем пароль (чтобы повторное включение вернуло тот
    // же секрет) — просто помечаем выключенным пустым значением.
    public function toggleHyObfs()
    {
        $this->pacConfUpdate(function (&$pac) {
            if (!empty($pac['hysteria_obfs'])) {
                $pac['hysteria_obfs_saved'] = $pac['hysteria_obfs'];
                unset($pac['hysteria_obfs']);
            } else {
                $pac['hysteria_obfs'] = $pac['hysteria_obfs_saved'] ?? bin2hex(random_bytes(12));
            }
        });
        $this->restartHysteria();
        $this->menu('hy');
    }

    // Сгенерировать новый obfs-пароль (только когда obfs включён). После смены
    // все клиенты должны обновить obfs-password из новой hy2://-ссылки.
    public function genHyObfs()
    {
        $changed = $this->pacConfUpdate(function (&$pac) {
            if (empty($pac['hysteria_obfs'])) return false;
            $pac['hysteria_obfs'] = bin2hex(random_bytes(12));
            return true;
        });
        if ($changed) $this->restartHysteria();
        $this->menu('hy');
    }

    // Показать используемый серверный конфиг Hysteria (/config/hysteria.yaml)
    // отдельным сообщением, не трогая меню — по аналогии с тем, как warp()
    // выводит wgcf-profile.conf. Паролей в чате не прячем: меню Hysteria и так
    // показывает passwd/obfs открыто.
    public function hyConfig()
    {
        $conf = @file_get_contents($this->hysteriaConf);
        if ($conf === false || trim($conf) === '') {
            return $this->send($this->input['chat'], 'hysteria.yaml: ' . $this->i18n('not found'));
        }
        $conf = htmlspecialchars($conf, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
        $this->send($this->input['chat'], "<b>hysteria.yaml</b>\n<pre>$conf</pre>");
    }

    // Port hopping (multi-port). Клиент случайно скачет по диапазону UDP-портов,
    // а firewall реднатит весь диапазон на реальный порт Hysteria — это сбивает
    // блокировки по фиксированному порту/объёму на одном порту. Серверный конфиг
    // Hysteria НЕ меняется (он слушает один порт), меняется только ссылка и
    // правило firewall. Поэтому restartHysteria здесь не нужен.
    public function setHyHop()
    {
        $r = $this->send(
            $this->input['chat'],
            $this->t("@{$this->input['username']} введите диапазон UDP-портов для смены портов, например <code>20000-50000</code> ", "@{$this->input['username']} enter UDP port range for hopping, e.g. <code>20000-50000</code> ")
            . "(comma/dash multi-port: <code>1234,5000-6000</code>) — <code>0</code> = off.\n\n"
            . "⚠️ " . $this->i18n('port hopping fw hint'),
            $this->input['message_id'],
            reply: $this->t('введите диапазон портов', 'enter port range'),
        );
        $this->stashReply($r, [
            'start_message'  => $this->input['message_id'],
            'start_callback' => $this->input['callback_id'],
            'callback'       => 'chHyHop',
            'args'           => [],
        ]);
    }

    // Нормализуем/валидируем строку мультипорта Hysteria: токены через запятую,
    // каждый — либо одиночный порт N, либо диапазон N-M (1..65535, N<=M). Вернёт
    // нормализованную строку или false, если формат неверный.
    public function normalizeHyHop(string $s)
    {
        $s = trim($s);
        if ($s === '') {
            return '';
        }
        $tokens = preg_split('~\s*,\s*~', $s, -1, PREG_SPLIT_NO_EMPTY);
        $out    = [];
        foreach ($tokens as $t) {
            if (preg_match('~^(\d{1,5})-(\d{1,5})$~', $t, $m)) {
                $lo = (int) $m[1];
                $hi = (int) $m[2];
                if ($lo < 1 || $hi > 65535 || $lo > $hi) {
                    return false;
                }
                $out[] = "$lo-$hi";
            } elseif (preg_match('~^(\d{1,5})$~', $t, $m)) {
                $p = (int) $m[1];
                if ($p < 1 || $p > 65535) {
                    return false;
                }
                $out[] = (string) $p;
            } else {
                return false;
            }
        }
        return implode(',', $out);
    }

    public function chHyHop($text)
    {
        // Пустое сообщение Telegram не отправит: выключение — нулём.
        $hop = trim((string) $text) === '0' ? '' : $this->normalizeHyHop((string) $text);
        if ($hop === false) {
            $this->send($this->input['chat'], $this->i18n('port hopping bad') . ': <code>' . htmlspecialchars((string) $text, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8') . '</code>');
            return $this->menu('hy');
        }
        $this->pacConfUpdate(function (&$pac) use ($hop) {
            if ($hop === '') unset($pac['hysteria_hop']);
            else $pac['hysteria_hop'] = $hop;
        });
        if ($hop === '') {
            $this->send($this->input['chat'], 'port hopping: ' . $this->i18n('off'));
            return $this->menu('hy');
        }
        // Сервер не трогаем — слушает один порт; правило firewall на стороне юзера.
        $this->send($this->input['chat'], "port hopping: <code>$hop</code> ✅");
        $this->hyHopNft();
        $this->menu('hy');
    }

    // Готовое к вставке правило nft для ручного режима (nft_conf). Бот сам host-
    // firewall НЕ трогает (он вне контейнера, hand-maintained), поэтому только
    // показываем сниппет. Реднатим весь диапазон на реальный порт Hysteria
    // ($HYSTERIA_IP:$HYSTERIA_OUTPUT) и пропускаем диапазон в INPUT/FORWARD —
    // по аналогии с одиночным $HYSTERIA_INPUT в твоём конфиге.
    public function hyHopNft()
    {
        $pac = $this->getPacConf();
        $hop = $pac['hysteria_hop'] ?? '';
        if ($hop === '') {
            return $this->send($this->input['chat'], 'port hopping: ' . $this->i18n('off'));
        }
        // nft хочет диапазон через дефис (20000-50000); запятые-списки разворачиваем
        // в anonymous set { ... } прямо в правиле.
        $set = (strpos($hop, ',') !== false) ? '{ ' . str_replace(',', ', ', $hop) . ' }' : $hop;
        $snippet = $this->language === 'en' ? <<<NFT
# ── Hysteria port hopping: re-DNAT of the UDP range to the real port ──
# The range must match the one in the hy2:// link ($hop).
# REQUIRED (this is enough for hopping to work):
# 1) table ip nat (dockernat), chain prerouting, next to the Hysteria DNAT line:
        fib daddr type local udp dport $set dnat to \$HYSTERIA_IP:\$HYSTERIA_OUTPUT
# 2) table ip nat (dockernat), chain output, next to the Hysteria output line:
        ip daddr != 127.0.0.0/8 fib daddr type local udp dport $set dnat to \$HYSTERIA_IP:\$HYSTERIA_OUTPUT
#
# NOT needed (explained so you are not tempted to add it):
# - FORWARD: after DNAT dport = \$HYSTERIA_OUTPUT (not the range); the traffic is
#   already covered by the existing FWD-HYSTERIA (daddr \$HYSTERIA_IP + dport OUTPUT).
# - INPUT: DNAT in prerouting happens BEFORE INPUT, and a packet with the container
#   daddr goes to FORWARD, not INPUT; hopping needs no range in INPUT.
# After editing: nft -c -f <your_conf> (check) → nft -f <your_conf>.
NFT : <<<NFT
# ── Hysteria port hopping: реднат UDP-диапазона на реальный порт ──
# Диапазон должен совпадать с тем, что в hy2://-ссылке ($hop).
# ОБЯЗАТЕЛЬНО (этого достаточно для работы хоппинга):
# 1) table ip nat (dockernat), chain prerouting — рядом со строкой Hysteria DNAT:
        fib daddr type local udp dport $set dnat to \$HYSTERIA_IP:\$HYSTERIA_OUTPUT
# 2) table ip nat (dockernat), chain output — рядом с output-строкой Hysteria:
        ip daddr != 127.0.0.0/8 fib daddr type local udp dport $set dnat to \$HYSTERIA_IP:\$HYSTERIA_OUTPUT
#
# НЕ нужно (объясняю, чтобы не было соблазна добавить):
# - FORWARD: после DNAT dport = \$HYSTERIA_OUTPUT (не диапазон), трафик уже
#   покрыт существующим FWD-HYSTERIA (daddr \$HYSTERIA_IP + dport OUTPUT).
# - INPUT: DNAT в prerouting срабатывает ДО INPUT, и пакет с daddr контейнера
#   идёт в FORWARD, а не в INPUT — диапазон в INPUT хоппингу не требуется.
# После правок: nft -c -f <твой_conf> (проверка) → nft -f <твой_conf>.
NFT;
        $this->send(
            $this->input['chat'],
            "<b>nft (manual mode)</b>\n<pre>" . htmlspecialchars($snippet, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8') . "</pre>",
        );
    }

    // Выбор relay для Hysteria из общего стора $pac['relays'] (тот же, что у
    // relay-подписок vless): список relay с health, тап — экран hyRelaySub с
    // hy2://-ссылкой через выбранный relay. Годятся только relay с заданным
    // hy_address (отдельный hysteria-канал, по образцу awg_address для wg/awg;
    // сам hy_address задаётся в карточке relay xray-меню).
    public function hyRelay()
    {
        $pac    = $this->getPacConf();
        $relays = array_filter($pac['relays'] ?? [], fn($e) => !empty($e['hy_address']));
        if (empty($relays)) {
            return $this->menu('hy');
        }
        $text[] = "Menu -> Hysteria -> " . $this->i18n('relay');
        $text[] = $this->i18n('hysteria relay hint');

        $data   = [];
        foreach ($relays as $name => $relay) {
            // Имя из одних цифр JSON-декодер делает int-ключом — приводим.
            // Статуса нет: Hysteria — UDP, а проба relay стучит по TCP в адрес
            // VLESS; её «✅» здесь выдавал бы чужой канал за рабочий.
            $name   = (string) $name;
            $data[] = [
                [
                    'text'          => "🔗 $name: {$relay['hy_address']}",
                    'callback_data' => "/hyRelaySub $name",
                ],
            ];
        }
        $data[] = [
            [
                'text'          => $this->i18n('back'),
                'callback_data' => '/menu hy',
            ],
        ];
        $this->update(
            $this->input['chat'],
            $this->input['message_id'],
            implode("\n", $text),
            $data,
        );
    }

    // hy2://-ссылка через один relay: linkHysteria() с подменой адреса+порта
    // (hy_address/hy_portmap), всё остальное — от origin. Health показываем с
    // возрастом, как на карточке relay в xray-меню.
    public function hyRelaySub($name)
    {
        $pac   = $this->getPacConf();
        $relay = $pac['relays'][$name] ?? null;
        if ($relay === null || empty($relay['hy_address'])) {
            return $this->hyRelay();
        }
        $link = $this->linkHysteria($relay);

        $text[] = "Menu -> Hysteria -> " . $this->i18n('relay') . " -> <b>" . self::esc($name) . "</b> (" . self::esc($relay['hy_address']) . ")";
        // Явный порт перебивает карту — показываем то, что реально в ссылке.
        if (($hp = self::relayPortInput($relay['hy_port'] ?? '')) !== '') {
            $text[] = $this->i18n('relay hy port') . ": <code>$hp</code>";
        } elseif (!empty($relay['hy_portmap'])) {
            $pm = [];
            foreach ($relay['hy_portmap'] as $src => $dst) {
                $pm[] = "$src:$dst";
            }
            $text[] = $this->i18n('relay hy port map') . ': <code>' . self::esc(implode(', ', $pm)) . '</code>';
        }
        $text[] = $this->i18n('hysteria relay hint');
        $text[] = $link !== ''
            ? "\n<code>$link</code>"
            : "\n" . $this->i18n('hysteria relay no link');

        $data[] = [
            [
                'text'          => $this->i18n('back'),
                'callback_data' => '/hyRelay',
            ],
        ];
        $this->update(
            $this->input['chat'],
            $this->input['message_id'],
            implode("\n", $text),
            $data,
        );
    }

    // Подменю выбора decoy-сайта для masquerade из пресетов + ручной ввод.
    public function hyMasqMenu()
    {
        $pac     = $this->getPacConf();
        $current = !empty($pac['hysteria_sni']) ? $pac['hysteria_sni'] : $this->getDomain();
        $text    = "Menu -> Hysteria -> " . $this->i18n('masquerade') . "\n\n"
                 . $this->i18n('masquerade host') . ": <code>$current</code>\n\n"
                 . "<i>" . $this->i18n('masquerade hint') . "</i>";
        $data = [];
        foreach ($this->hyMasqPresets() as $i => $host) {
            $mark   = ($host === $current) ? '✅ ' : '';
            $data[] = [[
                'text'          => "$mark$host",
                'callback_data' => "/setHyMasq $i",
            ]];
        }
        $data[] = [[
            'text'          => $this->i18n('change sni') . ' (custom)',
            'callback_data' => "/changeHySNI",
        ]];
        $data[] = [[
            'text'          => $this->i18n('back'),
            'callback_data' => "/menu hy",
        ]];
        $this->update($this->input['chat'], $this->input['message_id'], $text, $data);
    }

    public function setHyMasq($i)
    {
        $presets = $this->hyMasqPresets();
        $i       = (int) $i;
        if (!isset($presets[$i])) {
            return $this->hyMasqMenu();
        }
        $this->pacConfUpdate(function (&$pac) use ($presets, $i) {
            $pac['hysteria_sni'] = $presets[$i];
        });
        $this->restartHysteria();
        $this->hyMasqMenu();
    }

    public function changeHyBw()
    {
        $r = $this->send(
            $this->input['chat'],
            $this->t("@{$this->input['username']} введите полосу: отдача и приём (Мбит/с), например 200 200; <code>0</code> = BBR (авто)", "@{$this->input['username']} enter bandwidth: up down (mbps), e.g. 200 200 — <code>0</code> = BBR (auto)"),
            $this->input['message_id'],
            reply: $this->t('введите полосу', 'enter bandwidth'),
        );
        $this->stashReply($r, [
            'start_message'  => $this->input['message_id'],
            'start_callback' => $this->input['callback_id'],
            'callback'       => 'chHyBw',
            'args'           => [],
        ]);
    }

    // Парсим "up down" в mbps. Пусто/0 → удаляем bandwidth (Brutal off → BBR).
    public function chHyBw($text)
    {
        $this->pacConfUpdate(function (&$pac) use ($text) {
            $nums = preg_split('~[\s,]+~', trim((string) $text), -1, PREG_SPLIT_NO_EMPTY);
            $up   = (int) ($nums[0] ?? 0);
            $down = (int) ($nums[1] ?? $nums[0] ?? 0);
            if ($up <= 0 || $down <= 0) {
                unset($pac['hysteria_bw_up'], $pac['hysteria_bw_down']);
            } else {
                $pac['hysteria_bw_up']   = "$up mbps";
                $pac['hysteria_bw_down'] = "$down mbps";
            }
        });
        $this->restartHysteria();
        $this->menu('hy');
    }

    // Флаг insecure для клиентской hy2://-ссылки (нужен при self-signed серте,
    // иначе TLS-handshake клиента падает). На сервер не влияет.
    public function toggleHyInsecure()
    {
        $this->pacConfUpdate(function (&$pac) {
            if (!empty($pac['hysteria_insecure'])) {
                unset($pac['hysteria_insecure']);
            } else {
                $pac['hysteria_insecure'] = 1;
            }
        });
        $this->menu('hy');
    }

    public function chockey($pass)
    {
        $pass = $this->normalizeOcCamouflageSecret($pass);
        if ($pass === false) {
            $this->send($this->input['chat'], 'camouflage secret: use 1-128 chars: A-Z a-z 0-9 . _ ~ -');
            $this->menu('oc');
            return;
        }

        $this->pacConfUpdate(function (&$pac) use ($pass) {
            if ($pass === '') {
                unset($pac[self::OC_CAMOUFLAGE_SECRET]);
            } else {
                $pac[self::OC_CAMOUFLAGE_SECRET] = $pass;
            }
        });

        $c = file_get_contents('/config/ocserv.conf');
        $t = $this->applyOcCamouflage($c, $pass);
        $this->restartOcserv($t, false);
        $this->menu('oc');
    }

    public function disableOcCamouflage()
    {
        $this->chockey('');
    }

    public function chocdomain($domain)
    {
        $oc = $this->getHashSubdomain('oc');
        $c  = file_get_contents('/config/ocserv.conf');
        $t  = preg_replace_callback('~^default-domain[^\n]+~sm', fn() => "default-domain = $oc.$domain", $c);
        $this->restartOcserv($t);
    }

    public function chocpass($pass, $i = null)
    {
        $clients = $this->getClientsOc();
        if ($i === null || !isset($clients[$i])) {
            $this->menu('oc');
            return;
        }

        $pass = $this->normalizeOcPassword($pass);
        if ($pass === false) {
            $this->send($this->input['chat'], $this->t('Пароль OpenConnect: 1–128 символов, без переводов строк', 'OpenConnect password: use 1-128 chars, no new lines'));
            $this->ocUser($i);
            return;
        }

        $this->setOcUserPassword($clients[$i], $pass);
        $this->ocUser($i);
    }

    public function genOcPass($i)
    {
        $this->chocpass($this->genOcPassword(), $i);
    }

    private int $shadowsocksLockDepth = 0;

    public function withShadowsocksLock(callable $fn)
    {
        // Scoped reentrancy only for this SS pair and this Bot instance.
        // Common withLock remains non-reentrant.
        if ($this->shadowsocksLockDepth > 0) {
            $this->shadowsocksLockDepth++;
            try { return $fn(); }
            finally { $this->shadowsocksLockDepth--; }
        }
        $entered = false;
        $result = $this->withLock('shadowsocks', function () use ($fn, &$entered) {
            $entered = true; $this->shadowsocksLockDepth = 1;
            try { return $fn(); }
            finally { $this->shadowsocksLockDepth = 0; }
        }, 120, false);
        if (!$entered) throw new RuntimeException($this->t('Не удалось заблокировать Shadowsocks', 'Could not lock Shadowsocks'));
        return $result;
    }

    private function shadowsocksConfig(string $section): array
    {
        $path = dirname($this->pac) . '/' . ($section === 'ss' ? 'ssserver' : 'sslocal') . '.json';
        if (is_link($path) || !is_file($path)) throw new RuntimeException('Shadowsocks configuration unavailable');
        $raw = @file_get_contents($path);
        $config = is_string($raw) ? json_decode($raw, true) : null;
        if (!is_array($config)) throw new RuntimeException('Shadowsocks configuration invalid');
        return $config;
    }

    // Caller holds shadowsocks across snapshot, writes and confirmed apply.
    // Configs are individual bind mounts: preserve every existing inode.
    private function applyShadowsocksConfigsLocked(array $configs, bool $restorePrevious = false): bool
    {
        $files = []; $before = []; $bodies = []; $services = [];
        foreach ($configs as $section => $config) {
            if (!in_array($section, ['ss', 'sl'], true) || !is_array($config)
                || !is_string($config['password'] ?? null) || $config['password'] === ''
                || strlen($config['password']) > 1024 || str_contains($config['password'], "\0")
                || !is_int($config['server_port'] ?? null) || $config['server_port'] < 1 || $config['server_port'] > 65535
                || (isset($config['method']) && (!is_string($config['method']) || $config['method'] === ''))) return false;
            $binary = $section === 'ss' ? 'ssserver' : 'sslocal';
            $file = dirname($this->pac) . '/' . $binary . '.json';
            if (is_link($file) || (file_exists($file) && !is_file($file)) || (!$restorePrevious && !is_file($file))) return false;
            $before[$file] = is_file($file) ? @file_get_contents($file) : null;
            if ($before[$file] === false) return false;
            $files[$section] = $file;
            $bodies[$file] = json_encode($config, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_THROW_ON_ERROR);
            $container = $section === 'ss' ? 'ss' : 'proxy';
            if ($this->protocolModuleEnabled($container)) $services[$container] = $binary;
        }
        // No destructive operation until the whole local candidate is valid.
        if (isset($configs['ss']) && self::ssWarpOn($configs['ss']) && !$this->warpSocksAllowSS(true)) return false;
        $stopped = true;
        foreach ($services as $container => $binary) if (!$this->controlContainerService($container, $binary, 'stop')) $stopped = false;
        if (!$stopped) return false;
        try {
            foreach ($bodies as $file => $body) if (!$this->backupWriteInPlace($file, $body)) throw new RuntimeException('Shadowsocks write failed');
            if (isset($configs['ss']) && !self::ssWarpOn($configs['ss']) && $this->protocolModuleEnabled('wp')) {
                $oldServer = $before[$files['ss']] === null ? null : json_decode($before[$files['ss']], true);
                if (($restorePrevious || self::ssWarpOn($oldServer)) && !$this->warpSocksAllowSS(false)) throw new RuntimeException('Shadowsocks ACL apply failed');
            }
            foreach ($services as $container => $binary) if (!$this->controlContainerService($container, $binary, 'start')) throw new RuntimeException('Shadowsocks apply failed');
            return true;
        } catch (Throwable $error) {
            $safe = true;
            foreach ($services as $container => $binary) if (!$this->controlContainerService($container, $binary, 'stop')) $safe = false;
            foreach ($before as $file => $raw) {
                if (!($raw === null ? (!file_exists($file) || @unlink($file)) : $this->backupWriteInPlace($file, $raw))) $safe = false;
            }
            // Import may restore its previous working generation. Credential
            // rotation never automatically starts the old credentials again.
            if ($restorePrevious && $safe) {
                if (isset($files['ss']) && $before[$files['ss']] !== null) {
                    $old = json_decode($before[$files['ss']], true);
                    if (is_array($old) && self::ssWarpOn($old) && !$this->warpSocksAllowSS(true)) $safe = false;
                }
                if ($safe) foreach ($services as $container => $binary) {
                    $file = dirname($this->pac) . '/' . $binary . '.json';
                    if ($before[$file] !== null && !$this->controlContainerService($container, $binary, 'start')) $safe = false;
                }
            }
            if (!$safe) throw new RuntimeException($this->t('Применение или откат Shadowsocks не подтверждены', 'Shadowsocks apply or rollback is unconfirmed'));
            return false;
        }
    }

    public function sspwdch($pass, $nomenu = false)
    {
        if (!is_string($pass) || $pass === '' || strlen($pass) > 1024 || str_contains($pass, "\0")) {
            throw new InvalidArgumentException($this->t('Некорректный пароль Shadowsocks', 'Invalid Shadowsocks password'));
        }
        $ok = $this->withShadowsocksLock(function () use ($pass) {
            $c = $this->shadowsocksConfig('ss'); $l = $this->shadowsocksConfig('sl');
            if (empty($c['acl'])) $c['acl'] = '/config/ss.acl';
            $c['password'] = $l['password'] = $pass;
            return $this->applyShadowsocksConfigsLocked(['ss' => $c, 'sl' => $l]);
        });
        if (!$ok) throw new RuntimeException($this->t('Не удалось применить пароль Shadowsocks; отзыв прежнего доступа не подтверждён', 'Could not apply the Shadowsocks password; previous access revocation is unconfirmed'));
        if (empty($nomenu)) $this->menu('ss');
        return true;
    }

    public function v2ray()
    {
        return $this->withShadowsocksLock(fn() => $this->v2rayLocked());
    }

    private function v2rayLocked()
    {
        $ssl = $this->nginxGetTypeCert();
        $c = $this->shadowsocksConfig('ss');
        $l = $this->shadowsocksConfig('sl');
        $domain = $this->getPacConf()['domain'] ?: $this->ip;
        // ?? — в ssserver.json ключа plugin нет, пока плагин ни разу не
        // включали (шаблон в репозитории без него): голое $c['plugin'] давало
        // «Undefined array key» на каждый первый вход в тумблер.
        if (!empty($c['plugin'])) {
            unset($c['plugin']);
            unset($c['plugin_opts']);
            unset($l['plugin']);
            unset($l['plugin_opts']);
            // ssserver ВСЕГДА слушает внутренний 8388 (start_ss.sh хардкодит его,
            // docker маппит host:EXT->ss:8388), а sslocal в proxy-контейнере
            // коннектится к ss:8388. Внешний порт идёт только в ss://-ссылку
            // (buildSSLink/menuSS), а не в конфиг демонов — иначе ssserver
            // забиндит не тот порт и plain SS станет недоступен снаружи.
            $ssport           = self::SS_INTERNAL_PORT;
            $l['server']      = 'ss';
            $l['server_port'] = $ssport;
            $c['server_port'] = $ssport;
        } else {
            // v2ray и cloak/simple-tls конфликтуют: при v2ray ssserver работает
            // через плагин и не отдаёт plain SS на 8388, поэтому глушим оба.
            $this->disableCloakIfOn();
            $this->disableSimpleTlsIfOn();
            $hash             = $this->getHashBot();
            $c['plugin']      = 'v2ray-plugin';
            $c['plugin_opts'] = 'server;loglevel=none';
            $l['server']      = 'up';
            $l['server_port'] = $ssl ? 443 : 80;
            $l['plugin']      = 'v2ray-plugin';
            $l['plugin_opts'] = ($ssl ? 'tls;' : '') . "fast-open;path=/v2ray$hash;host=$domain";
        }
        if (!$this->applyShadowsocksConfigsLocked(['ss' => $c, 'sl' => $l])) {
            throw new RuntimeException($this->t('Не удалось применить Shadowsocks', 'Could not apply Shadowsocks'));
        }
        $this->menu('ss');
    }

    public function getStlsConfig()
    {
        $f = '/config/stlsserver.json';
        return file_exists($f) ? (json_decode(file_get_contents($f), true) ?: []) : [];
    }

    public function setStlsConfig(array $c)
    {
        if (!$this->writePrivateKey('/config/stlsserver.json', json_encode($c,
            JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_THROW_ON_ERROR))) {
            throw new RuntimeException('Could not save simple-tls settings');
        }
    }

    // simple-tls работает поверх plain ssserver (как cloak), но UI держит
    // транспорты взаимоисключающими: при включении одного глушим остальные.
    public function simpleTls()
    {
        return $this->withShadowsocksLock(fn() => $this->simpleTlsLocked());
    }

    private function simpleTlsLocked()
    {
        $c = $this->getStlsConfig();
        if (!empty($c['Enabled'])) {
            $this->disableSimpleTlsIfOn();
        } else {
            // Раньше при активном v2ray-plugin вызывался v2ray() с return —
            // получался UX-баг: пользователь жмёт «simple-tls: OFF→ON»,
            // а на деле просто выключается v2ray, simple-tls не запускается.
            // Теперь снимаем плагин inline и идём дальше.
            $this->disableV2rayPluginIfOn();
            $this->disableCloakIfOn();
            $domain = $this->getPacConf()['domain'] ?: $this->ip;
            $c['Enabled']    = 1;
            $c['ServerName'] = $c['ServerName'] ?? $domain;
            $this->setStlsConfig($c);
            $this->requireSsTransportControl('simple-tls', 'restart');
        }
        $this->menu('ss');
    }

    public function changeStlsPort()
    {
        $r = $this->send(
            $this->input['chat'],
            $this->t("@{$this->input['username']} введите порт simple-tls", "@{$this->input['username']} enter simple-tls port"),
            $this->input['message_id'],
            reply: $this->t('введите порт simple-tls', 'enter simple-tls port'),
        );
        $this->stashReply($r, [
            'start_message'  => $this->input['message_id'],
            'start_callback' => $this->input['callback_id'],
            'callback'       => 'chStlsPort',
            'args'           => [],
        ]);
    }

    public function chStlsPort($port)
    {
        return $this->withShadowsocksLock(fn() => $this->chStlsPortLocked($port));
    }

    private function chStlsPortLocked($port)
    {
        $port = (int) $port;
        if ($port < 1 || $port > 65535) {
            $this->menu('ss');
            return;
        }
        $this->setEnvVar('STLSPORT', (string) $port);
        $this->pacConfUpdate(function (&$pac) {
            $pac['restart'] = 1;
        });
        $this->menu('ss');
    }

    public function changeStlsSNI()
    {
        $r = $this->send(
            $this->input['chat'],
            $this->t("@{$this->input['username']} введите SNI simple-tls (имя сервера в сертификате, например {$this->getDomain()})", "@{$this->input['username']} enter simple-tls SNI (server name in cert, e.g. {$this->getDomain()})"),
            $this->input['message_id'],
            reply: $this->t('введите SNI simple-tls', 'enter simple-tls SNI'),
        );
        $this->stashReply($r, [
            'start_message'  => $this->input['message_id'],
            'start_callback' => $this->input['callback_id'],
            'callback'       => 'chStlsSNI',
            'args'           => [],
        ]);
    }

    public function chStlsSNI($name)
    {
        return $this->withShadowsocksLock(fn() => $this->chStlsSNILocked($name));
    }

    private function chStlsSNILocked($name)
    {
        $name = trim($name);
        if (!preg_match('~^[A-Za-z0-9.-]+$~', $name)) {
            $this->menu('ss');
            return;
        }
        $c = $this->getStlsConfig();
        $c['ServerName'] = $name;
        $this->setStlsConfig($c);
        $this->menu('ss');
    }

    public function getCloakConfig()
    {
        $f = '/config/ckserver.json';
        $c = file_exists($f) ? (json_decode(file_get_contents($f), true) ?: []) : [];
        return $c;
    }

    // Сборка ss://-ссылки с учётом активного плагина. Приоритет:
    //   cloak > simple-tls > v2ray-plugin > чистый shadowsocks.
    // Переключатели выше держат плагины взаимоисключающими; приоритет нужен
    // только для старых/ручных конфигов, где несколько флагов уже включены.
    //
    // $cloakUid — если задан, идёт в plugin-opts вместо $ck['UID']. Нужно
    // для per-user QR из cloak users menu (Phase 2 multi-user).
    public function buildSSLink($hash = '', $cloakUid = null)
    {
        $ss     = $this->getSSConfig();
        $domain = $this->getDomain();
        $ck     = $this->getCloakConfig();
        $st     = $this->getStlsConfig();
        // SIP002: userinfo — websafe-base64 (base64url) без паддинга.
        // Раньше был обычный base64_encode + вырезание «==» регуляркой по всей
        // строке: алфавит остаётся стандартным, поэтому в userinfo могли
        // попасть '+' и особенно '/', который часть клиентов принимает за
        // начало path и рвёт ссылку; одиночный '=' при этом не срезался вовсе.
        // strtr на '-_' + rtrim('=') даёт ровно то, что описывает спека.
        $b64    = 'ss://' . rtrim(strtr(base64_encode("{$ss['method']}:{$ss['password']}"), '+/', '-_'), '=');

        if (!empty($ck['Enabled'])) {
            $ckPort = (int) (getenv('CKPORT') ?: 7443);
            $ckSrv  = $ck['ServerName'] ?? ($ck['RedirAddr'] ?? $domain);
            $effUid = $cloakUid !== null && $cloakUid !== '' ? $cloakUid : ($ck['UID'] ?? '');
            $opts   = "ck-client;UID=" . $effUid
                    . ";PublicKey=" . ($ck['PublicKey'] ?? '')
                    . ";ServerName=$ckSrv"
                    . ";ProxyMethod=shadowsocks"
                    . ";EncryptionMethod=" . ($ck['EncryptionMethod'] ?? 'aes-256-gcm')
                    . ";NumConn=" . ($ck['NumConn'] ?? 4)
                    . ";BrowserSig=" . ($ck['BrowserSig'] ?? 'chrome');
            return $b64 . "@$domain:$ckPort/?plugin=" . urlencode($opts);
        }

        if (!empty($st['Enabled'])) {
            $stPort  = (int) (getenv('STLSPORT') ?: 3443);
            $stSrv   = $st['ServerName'] ?? $domain;
            // Если используется self-signed cert — клиенту нужен no-verify,
            // иначе TLS-handshake провалится. LE-бандл валидируется штатно.
            $ssl     = $this->nginxGetTypeCert();
            $opts    = "simple-tls;n=$stSrv" . ($ssl === 'letsencrypt' ? '' : ';no-verify');
            return $b64 . "@$domain:$stPort/?plugin=" . urlencode($opts);
        }

        if (!empty($ss['plugin'])) {
            $ssl  = $this->nginxGetTypeCert();
            $port = $ssl ? 443 : 80;
            $opts = "v2ray-plugin;path=/v2ray$hash;host=$domain" . ($ssl ? ';tls' : '');
            return $b64 . "@$domain:$port/?plugin=" . urlencode($opts);
        }

        $ports = $this->getPorts();
        return $b64 . "@$domain:{$ports['ss']['port']}/";
    }

    public function setCloakConfig(array $c)
    {
        if (!$this->writePrivateKey('/config/ckserver.json', json_encode($c,
            JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_THROW_ON_ERROR))) {
            throw new RuntimeException('Could not save Cloak settings');
        }
    }

    // Лениво создаём ключи и UID через ck-server -key / -uid в ss-контейнере.
    // Cloak печатает их в человекочитаемом формате с ANSI-цветами и
    // выравниванием по ширине поля (%65s/%47s/%s после "Your X is:"),
    // поэтому надёжнее искать сами base64-строки фиксированной длины:
    // curve25519 ключ = 32 байта = 44 символа base64 с одним '=' в конце,
    // UID = 16 байт = 22 символа + '==' (24 всего). Создаём один раз и
    // храним, чтобы клиентские ссылки переживали recreate.
    public function ensureCloakIdentity()
    {
        return $this->withShadowsocksLock(fn() => $this->ensureCloakIdentityLocked());
    }

    private function ensureCloakIdentityLocked()
    {
        $c = $this->getCloakConfig();
        if (empty($c['PrivateKey']) || empty($c['PublicKey']) || empty($c['UID'])) {
            $key = $this->ssh('ck-server -key 2>&1', 'ss') ?: '';
            $uid = $this->ssh('ck-server -uid 2>&1', 'ss') ?: '';
            if (preg_match_all('~[A-Za-z0-9+/]{43}=~', $key, $m) && count($m[0]) >= 2) {
                $c['PublicKey']  = $m[0][0];
                $c['PrivateKey'] = $m[0][1];
            }
            if (preg_match('~[A-Za-z0-9+/]{22}==~', $uid, $m)) {
                $c['UID'] = $m[0];
            }
            $this->setCloakConfig($c);
        }
        return $c;
    }

    // Intentional stop is recorded by the supervisor; a later crash recovery
    // must not silently undo it. Success requires its exact readiness marker.
    private function requireSsTransportControl(string $service, string $action): void
    {
        if (!$this->controlContainerService('ss', $service, $action)) {
            throw new RuntimeException($this->t('Применение транспорта не подтверждено: ', 'Transport application is unconfirmed: ') . $service);
        }
    }

    private function restartCloakIfRunning(): void
    {
        $c = $this->getCloakConfig();
        if (!empty($c['Enabled'])) {
            $this->requireSsTransportControl('ck-server', 'restart');
        }
    }

    // Phase 2 — multi-user storage для cloak. Параллельно ckserver.json
    // (где BypassUID — список UID-ов, который читает сам ck-server) держим
    // side-store /config/ckusers.json с метой: имя, UID, время создания.
    // На первом чтении бутстрапим из текущего ckserver.json: основной UID
    // → "default", всё, что лежало в BypassUID отдельно — "user2", "user3"…
    // BypassUID всегда пересчитывается из ckusers.json через syncCloakBypassUIDs().
    public function getCloakUsers(): array
    {
        return $this->withShadowsocksLock(fn() => $this->getCloakUsersLocked());
    }

    private function getCloakUsersLocked(): array
    {
        $f = '/config/ckusers.json';
        $list = file_exists($f) ? (json_decode(file_get_contents($f), true) ?: []) : [];
        if (!empty($list)) {
            return array_values($list);
        }
        // bootstrap from current ckserver.json
        $c = $this->getCloakConfig();
        $defaultUid = $c['UID'] ?? '';
        if ($defaultUid !== '') {
            $list[] = ['name' => 'default', 'uid' => $defaultUid, 'created' => time()];
        }
        $idx = 2;
        foreach (($c['BypassUID'] ?? []) as $u) {
            if ($u === '' || $u === $defaultUid) {
                continue;
            }
            $list[] = ['name' => 'user' . $idx, 'uid' => $u, 'created' => time()];
            $idx++;
        }
        if (!empty($list)) {
            $this->setCloakUsers($list);
        }
        return $list;
    }

    public function setCloakUsers(array $list): void
    {
        if (!$this->writePrivateKey('/config/ckusers.json', json_encode(array_values($list),
            JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_THROW_ON_ERROR))) {
            throw new RuntimeException('Could not save Cloak users');
        }
    }

    // sha1-prefix как route id: UID содержит '/' и '+' и не лезет в callback
    // напрямую без urlencode, что ломается на парсинге Telegram (пробел —
    // разделитель аргументов). 12 hex-символов это 48 бит — коллизии
    // практически невозможны при количестве пользователей в десятки.
    public function findCloakUserByHash(string $hash): ?array
    {
        foreach ($this->getCloakUsers() as $u) {
            if (substr(sha1($u['uid']), 0, 12) === $hash) {
                return $u;
            }
        }
        return null;
    }

    // BypassUID — то, что читает сам ck-server. Держим его в синхронизации
    // с ckusers.json: после любого add/delete пересчитываем заново.
    private function syncCloakBypassUIDs(): void
    {
        $c = $this->getCloakConfig();
        $uids = array_values(array_unique(array_filter(
            array_map(fn($u) => $u['uid'] ?? '', $this->getCloakUsers())
        )));
        $c['BypassUID'] = $uids;
        $this->setCloakConfig($c);
    }

    // Toggle cloak on/off. Конфиг ckserver.json хранится в общей папке
    // /config (разделяется между php и ss контейнерами); поле Enabled
    // не понимается самим ck-server, мы используем его как флаг для
    // start_ss.sh и для UI бота.
    public function cloak()
    {
        return $this->withShadowsocksLock(fn() => $this->cloakLocked());
    }

    private function cloakLocked()
    {
        $c = $this->ensureCloakIdentity();
        $domain = $this->getPacConf()['domain'] ?: $this->ip;
        $port   = (int) (getenv('CKPORT') ?: 7443);
        $ssport = self::SS_INTERNAL_PORT;

        if (!empty($c['Enabled'])) {
            $this->requireSsTransportControl('ck-server', 'stop');
            $c['Enabled'] = 0;
            $this->setCloakConfig($c);
        } else {
            // v2ray-plugin несовместим с cloak (ssserver слушал бы с плагином,
            // не plain). Раньше тут был return после v2ray()-toggle, что давало
            // UX-баг: "включаю cloak" → выключился v2ray, cloak не включился.
            // Теперь честно отключаем плагин inline и идём дальше.
            $this->disableV2rayPluginIfOn();
            $this->disableSimpleTlsIfOn();
            // Гарантируем, что в ckusers.json есть default запись для текущего
            // UID — getCloakUsers() сам бутстрапит, дальше syncCloakBypassUIDs()
            // переписывает BypassUID из side-store.
            $this->getCloakUsers();
            $c = $this->getCloakConfig();
            $c['Enabled']    = 1;
            $c['BindAddr']   = [":$port"];
            $c['ProxyBook']  = ['shadowsocks' => ['tcp', "127.0.0.1:$ssport"]];
            $c['RedirAddr']  = $c['RedirAddr'] ?: 'www.bing.com';
            // ServerName — это SNI, который клиент показывает провайдеру.
            // README Cloak: «the domain you want to make your ISP or firewall
            // think you are visiting… ideally it should match RedirAddr in the
            // server's configuration, a major site the censor allows».
            // Раньше по умолчанию подставлялся СОБСТВЕННЫЙ домен установки —
            // то есть в SNI на порту cloak светился реальный домен VPN, ровно
            // то, что Cloak и должен прятать. Дефолт = RedirAddr; заданное
            // вручную значение (cloakDomain) не трогаем.
            $c['ServerName'] = ($c['ServerName'] ?? '') ?: $c['RedirAddr'];
            $this->setCloakConfig($c);
            $this->syncCloakBypassUIDs();
            $this->requireSsTransportControl('ck-server', 'restart');
        }
        $this->menu('ss');
    }

    private function disableCloakIfOn(): void
    {
        $c = $this->getCloakConfig();
        if (empty($c['Enabled'])) {
            return;
        }
        $this->requireSsTransportControl('ck-server', 'stop');
        $c['Enabled'] = 0;
        $this->setCloakConfig($c);
    }

    private function disableSimpleTlsIfOn(): void
    {
        $c = $this->getStlsConfig();
        if (empty($c['Enabled'])) {
            return;
        }
        $this->requireSsTransportControl('simple-tls', 'stop');
        $c['Enabled'] = 0;
        $this->setStlsConfig($c);
    }

    // Снимает плагин v2ray-plugin с ssserver/sslocal без перерисовки меню.
    // Раньше cloak()/simpleTls() при активном v2ray вызывали v2ray() и делали
    // return — это рендерило меню от лица v2ray и обрывало текущий toggle,
    // т.е. кнопка "включить cloak" фактически выключала v2ray. Теперь это
    // выделено и вызывается inline перед собственным enable.
    private function disableV2rayPluginIfOn(): void
    {
        $this->withShadowsocksLock(fn() => $this->disableV2rayPluginIfOnLocked());
    }

    private function disableV2rayPluginIfOnLocked(): void
    {
        $c = $this->shadowsocksConfig('ss');
        if (empty($c['plugin'])) {
            return;
        }
        $l = $this->shadowsocksConfig('sl');
        unset($c['plugin'], $c['plugin_opts'], $l['plugin'], $l['plugin_opts']);
        $ssport = self::SS_INTERNAL_PORT;
        $l['server']      = 'ss';
        $l['server_port'] = $ssport;
        $c['server_port'] = $ssport;
        if (!$this->applyShadowsocksConfigsLocked(['ss' => $c, 'sl' => $l])) {
            throw new RuntimeException($this->t('Не удалось применить Shadowsocks', 'Could not apply Shadowsocks'));
        }
    }

    // ---- SS через WARP (outbound_proxy у ssserver) --------------------------
    // shadowsocks-rust 1.25.0 (#2106) научился отдавать ИСХОДЯЩИЕ соединения
    // ssserver'а в socks5/http-прокси: ключ outbound_proxy, значение — URL с
    // ОБЯЗАТЕЛЬНЫМ портом. Рядом уже живёт microsocks WARP'а, поэтому тумблер
    // сводится к одной строке в ssserver.json.
    //
    // Три вещи, которые видно только на живом ядре (проверены прогоном
    // релизных бинарей 1.25.0 с нашими конфигами, см. AUDIT-2026-09-01-ss-warp):
    //   1. цепочку применяет ТОЛЬКО tcp-релей сервера (server/tcprelay.rs);
    //      udprelay.rs про неё не знает вовсе, то есть UDP клиентов (QUIC, DNS
    //      по UDP) продолжает уходить НАПРЯМУЮ, с адреса сервера. Это не наш
    //      выбор, а поведение ядра — и о нём обязано быть написано в меню;
    //   2. отката на direct нет: пока прокси недоступен, каждый TCP-коннект
    //      падает с «connect failed». Поэтому включаем только после успешной
    //      пробы WARP, а не вслепую;
    //   3. UDP при этом работает как ни в чём не бывало — то есть авария
    //      выглядит как «TCP не ходит, а видео крутится», её легко не узнать.
    public const SS_WARP_KEY = 'outbound_proxy';

    // Включён ли тумблер. Источник истины — сам ssserver.json (как plugin у
    // v2ray и Enabled у cloak/simple-tls): дублировать состояние в pac.json
    // значит завести второе место, которое может разъехаться с конфигом,
    // который реально читает демон.
    public static function ssWarpOn(?array $ss): bool
    {
        return !empty($ss[self::SS_WARP_KEY]);
    }

    // URL цепочки. Порт обязателен: OutboundProxy::from_url() отвергает URL без
    // него, и ssserver не поднимется вовсе.
    public function ssWarpUrl(): string
    {
        $ip = explode('/', $this->warpSocksIp())[0];

        return 'socks5://' . $ip . ':' . self::WARP_SOCKS_PORT;
    }

    // Маркеры фактического состояния ACL в выводе команды ниже. Два разных
    // слова, а не «on»/«off»: одно не должно быть подстрокой другого, иначе
    // str_contains() спутает их.
    public const SS_ACL_PRESENT = 'ss-acl-present';
    public const SS_ACL_ABSENT  = 'ss-acl-absent';

    // Команда для ACL microsocks внутри wp. start_wp.sh ставит это правило на
    // старте контейнера (условие — тот же ключ в ssserver.json), но тумблер
    // обязан работать и без пересоздания wp, поэтому то же правило ставим
    // вживую. -C перед -I делает вставку идемпотентной, -I без позиции кладёт
    // ACCEPT ПЕРЕД финальным DROP цепочки (иначе правило бесполезно).
    // Снятие — циклом: одинаковых правил могло накопиться несколько.
    //
    // Хвост с -C — проверка РЕЗУЛЬТАТА: ssh() не смотрит код возврата и не
    // читает stderr, поэтому отказавший iptables неотличим от успеха. А
    // отказать он может штатно: sshd в wp поднимается первой строкой
    // start_wp.sh, а цепочка WARP_SOCKS создаётся в самом конце — между
    // стартом microsocks (проба warpStatus() уже проходит) и созданием цепочки
    // и -C, и -I падают с «No chain by that name». Спрашиваем сам iptables.
    public static function warpSocksAllowCmd(string $ip, bool $on): string
    {
        $rule = "WARP_SOCKS -s $ip -j ACCEPT";
        $cmd  = $on
            ? "iptables -C $rule 2>/dev/null || iptables -I $rule"
            : "while iptables -C $rule 2>/dev/null; do iptables -D $rule; done";

        return "$cmd; iptables -C $rule 2>/dev/null && echo " . self::SS_ACL_PRESENT
            . ' || echo ' . self::SS_ACL_ABSENT;
    }

    // Адрес контейнера ss глазами docker-DNS. Резолвим ЗДЕСЬ, в php: внутри wp
    // start_wp.sh подменяет /etc/resolv.conf на 1.1.1.1, и имена контейнеров
    // оттуда уже не резолвятся (ровно поэтому XRAY_IPS там считается до
    // подмены). Фолбэк — адрес из compose.
    public function ssContainerIp(): string
    {
        $ip = gethostbyname('ss');

        return filter_var($ip, FILTER_VALIDATE_IP, FILTER_FLAG_IPV4) ? $ip : '10.10.0.6';
    }

    // true — ACL действительно приведён к запрошенному виду: ssh дошёл до wp И
    // сам iptables подтвердил правило маркером. Всё остальное — false.
    public function warpSocksAllowSS(bool $on): bool
    {
        $out = $this->ssh(self::warpSocksAllowCmd($this->ssContainerIp(), $on), 'wp');

        return !$this->sshFailed
            && str_contains((string) $out, $on ? self::SS_ACL_PRESENT : self::SS_ACL_ABSENT);
    }

    public function ssWarp()
    {
        return $this->withShadowsocksLock(fn() => $this->ssWarpLocked());
    }

    private function ssWarpLocked()
    {
        $c = $this->shadowsocksConfig('ss');
        // Битый/пропавший ssserver.json: json_decode отдаёт null, и запись ниже
        // сделала бы из конфига объект С ОДНИМ ключом outbound_proxy — то есть
        // снесла бы пароль, шифр и режим. Лучше ничего не менять.
        if (!is_array($c)) {
            error_log('ssWarp: /config/ssserver.json не читается — тумблер не тронут');

            return $this->menu('ss');
        }
        if (self::ssWarpOn($c)) {
            unset($c[self::SS_WARP_KEY]);
            $this->warpSocksAllowSS(false);
        } else {
            // Проба стоит одного ssh, а цена ошибки — весь TCP через SS: пока
            // прокси не отвечает, ядро не откатывается на direct (см. коммент
            // выше), и клиенты остаются без связи молча.
            if ($this->warpStatus() === 'off') {
                $this->update($this->input['chat'], $this->input['message_id'], $this->i18n('warp is off for ss'));
                sleep(3);

                return $this->menu('ss');
            }
            // Сначала ACL, потом конфиг: наоборот ssserver успел бы
            // перезапуститься и получить DROP на первом же коннекте.
            // Проба выше НЕ доказывает, что правило встало: она ходит
            // бот→xr→wp:1080, а iptables идёт бот→wp:22 — это разные пути, и
            // sshd в wp может лежать при живых туннеле и microsocks. Мало и
            // живого ssh: цепочки WARP_SOCKS может ещё не быть, и тогда
            // iptables отказывает молча. Смотрим подтверждение от самого
            // iptables и отменяем включение ДО записи конфига — иначе конфиг с
            // outbound_proxy уедет к ssserver без ACCEPT, и весь TCP клиентов
            // ss встанет молча (отката на direct у ядра нет).
            if (!$this->warpSocksAllowSS(true)) {
                $this->update($this->input['chat'], $this->input['message_id'], $this->i18n('ss warp acl failed'));
                sleep(3);

                return $this->menu('ss');
            }
            $c[self::SS_WARP_KEY] = $this->ssWarpUrl();
        }
        if (!$this->applyShadowsocksConfigsLocked(['ss' => $c])) {
            throw new RuntimeException($this->t('Не удалось применить Shadowsocks', 'Could not apply Shadowsocks'));
        }
        $this->menu('ss');
    }

    public function changeCloakPort()
    {
        $r = $this->send(
            $this->input['chat'],
            $this->t("@{$this->input['username']} введите порт Cloak", "@{$this->input['username']} enter cloak port"),
            $this->input['message_id'],
            reply: $this->t('введите порт Cloak', 'enter cloak port'),
        );
        $this->stashReply($r, [
            'start_message'  => $this->input['message_id'],
            'start_callback' => $this->input['callback_id'],
            'callback'       => 'chCloakPort',
            'args'           => [],
        ]);
    }

    public function chCloakPort($port)
    {
        return $this->withShadowsocksLock(fn() => $this->chCloakPortLocked($port));
    }

    private function chCloakPortLocked($port)
    {
        $port = (int) $port;
        if ($port < 1 || $port > 65535) {
            $this->menu('ss');
            return;
        }
        // Главный compose уже разворачивает ${CKPORT:-7443}:${CKPORT:-7443}/tcp
        // на сервисе ss, так что одного setEnvVar достаточно — после `make r`
        // докер подхватит новое значение. Флаг restart в pac заставит бот
        // напомнить пользователю про пересоздание контейнера.
        $this->setEnvVar('CKPORT', (string) $port);
        $c = $this->getCloakConfig();
        if (!empty($c)) {
            $c['BindAddr'] = [":$port"];
            $this->setCloakConfig($c);
        }
        $this->pacConfUpdate(function (&$pac) {
            $pac['restart'] = 1;
        });
        $this->menu('ss');
    }

    public function changeCloakDomain()
    {
        $r = $this->send(
            $this->input['chat'],
            $this->t("@{$this->input['username']} введите домен маскировки (например www.bing.com)", "@{$this->input['username']} enter masquerade domain (e.g. www.bing.com)"),
            $this->input['message_id'],
            reply: $this->t('введите домен маскировки', 'enter masquerade domain'),
        );
        $this->stashReply($r, [
            'start_message'  => $this->input['message_id'],
            'start_callback' => $this->input['callback_id'],
            'callback'       => 'chCloakDomain',
            'args'           => [],
        ]);
    }

    public function chCloakDomain($domain)
    {
        return $this->withShadowsocksLock(fn() => $this->chCloakDomainLocked($domain));
    }

    private function chCloakDomainLocked($domain)
    {
        $domain = trim($domain);
        if (!preg_match('~^[A-Za-z0-9.-]+$~', $domain)) {
            $this->menu('ss');
            return;
        }
        $c = $this->ensureCloakIdentity();
        $c['RedirAddr']  = $domain;
        $c['ServerName'] = $domain;
        $this->setCloakConfig($c);
        // Перезапускаем ck-server с новым RedirAddr/ServerName.
        $this->restartCloakIfRunning();
        $this->menu('ss');
    }

    // Регенерация ключей cloak (PrivateKey/PublicKey/UID). После выполнения
    // все ранее розданные клиентские ссылки/QR становятся невалидными —
    // пользователю нужно заново раздать новый ss:// или скан QR. ck-server
    // глушится перед очисткой, чтобы не держал старые ключи в памяти.
    // Cloak принимает только фиксированный набор EncryptionMethod;
    // совпадение с SS method (например chacha20-ietf-poly1305 у SS vs
    // chacha20-poly1305 у Cloak) безопасно — это два независимых слоя
    // шифрования с разными ключами.
    public function cycleCloakMethod()
    {
        return $this->withShadowsocksLock(fn() => $this->cycleCloakMethodLocked());
    }

    private function cycleCloakMethodLocked()
    {
        $methods = ['aes-256-gcm', 'aes-128-gcm', 'chacha20-poly1305', 'plain'];
        $c       = $this->getCloakConfig();
        $cur     = $c['EncryptionMethod'] ?? 'aes-256-gcm';
        $i       = array_search($cur, $methods, true);
        $c['EncryptionMethod'] = $methods[($i === false ? 0 : $i + 1) % count($methods)];
        $this->setCloakConfig($c);
        $this->restartCloakIfRunning();
        $this->menu('ss');
    }

    public function regenCloakKeys()
    {
        return $this->withShadowsocksLock(fn() => $this->regenCloakKeysLocked());
    }

    private function regenCloakKeysLocked()
    {
        $c     = $this->getCloakConfig();
        $wasOn = !empty($c['Enabled']);

        $this->requireSsTransportControl('ck-server', 'stop');

        // Сбрасываем идентификационные поля. ensureCloakIdentity() их
        // восстановит через ck-server -key / -uid.
        unset($c['PrivateKey'], $c['PublicKey'], $c['UID'], $c['BypassUID']);
        $this->setCloakConfig($c);

        // Старые UID-ы из ckusers.json (Phase 2 multi-user) теперь не подходят
        // к новой паре PrivateKey/PublicKey — все ранее розданные клиентские
        // ссылки и так умерли вместе с server-keys, поэтому стираем
        // side-store, чтобы getCloakUsers() забутстрапился под новый
        // default-UID. Без этого в списке остались бы «мёртвые» имена.
        @unlink('/config/ckusers.json');

        $c = $this->ensureCloakIdentity();

        if ($wasOn) {
            $domain = $this->getPacConf()['domain'] ?: $this->ip;
            $port   = (int) (getenv('CKPORT') ?: 7443);
            $ssport = self::SS_INTERNAL_PORT;

            $c['Enabled']    = 1;
            $c['BindAddr']   = [":$port"];
            $c['ProxyBook']  = ['shadowsocks' => ['tcp', "127.0.0.1:$ssport"]];
            $c['RedirAddr']  = $c['RedirAddr'] ?: 'www.bing.com';
            // ServerName — это SNI, который клиент показывает провайдеру.
            // README Cloak: «the domain you want to make your ISP or firewall
            // think you are visiting… ideally it should match RedirAddr in the
            // server's configuration, a major site the censor allows».
            // Раньше по умолчанию подставлялся СОБСТВЕННЫЙ домен установки —
            // то есть в SNI на порту cloak светился реальный домен VPN, ровно
            // то, что Cloak и должен прятать. Дефолт = RedirAddr; заданное
            // вручную значение (cloakDomain) не трогаем.
            $c['ServerName'] = $c['ServerName'] ?: $c['RedirAddr'];
            $this->setCloakConfig($c);
            // bootstrap default user в ckusers.json и пересинхронизируем
            // BypassUID — иначе ck-server стартует с пустым allow-list.
            $this->getCloakUsers();
            $this->syncCloakBypassUIDs();
            $this->requireSsTransportControl('ck-server', 'restart');
        }

        $this->menu('ss');
    }

    // ── cloak users (Phase 2) ────────────────────────────────────────

    // Открывает prompt-режим для имени нового пользователя; ответ ловится
    // sessions[]['callback'] => 'addCkUserSubmit' и передаётся в submit-метод.
    public function addCloakUser()
    {
        $r = $this->send(
            $this->input['chat'],
            $this->t("@{$this->input['username']} введите имя пользователя Cloak", "@{$this->input['username']} enter cloak user name"),
            $this->input['message_id'],
            reply: $this->t('введите имя пользователя Cloak', 'enter cloak user name'),
        );
        $this->stashReply($r, [
            'start_message'  => $this->input['message_id'],
            'start_callback' => $this->input['callback_id'],
            'callback'       => 'addCkUserSubmit',
            'args'           => [],
        ]);
    }

    // Регистрирует нового пользователя cloak. Имя нормализуется (тот же
    // санитайзер, что у ovpn — буквы/цифры/_-.), UID берём через
    // ck-server -uid (16 байт base64). Дальше переписываем BypassUID и
    // рестартуем ck-server, если он крутится.
    public function addCkUserSubmit($name)
    {
        return $this->withShadowsocksLock(fn() => $this->addCkUserSubmitLocked($name));
    }

    private function addCkUserSubmitLocked($name)
    {
        $name = preg_replace('~[^a-zA-Z0-9_.\- ]~', '', (string) $name);
        $name = trim($name);
        if ($name === '') {
            $this->send($this->input['chat'], 'wrong name');
            return $this->menuCkUsers();
        }
        $list = $this->getCloakUsers();
        foreach ($list as $u) {
            if (($u['name'] ?? '') === $name) {
                $this->send($this->input['chat'], "user $name already exists");
                return $this->menuCkUsers();
            }
        }
        $uidOut = $this->ssh('ck-server -uid 2>&1', 'ss') ?: '';
        if (!preg_match('~[A-Za-z0-9+/]{22}==~', $uidOut, $m)) {
            $this->send($this->input['chat'], $this->t('Не удалось создать UID', 'failed to generate UID'));
            return $this->menuCkUsers();
        }
        $list[] = ['name' => $name, 'uid' => $m[0], 'created' => time()];
        $this->setCloakUsers($list);
        $this->syncCloakBypassUIDs();
        $this->restartCloakIfRunning();
        $this->menuCkUsers();
    }

    // Удаляет пользователя по sha1-prefix UID. Default user (тот, что лежит
    // в $ck['UID']) защищён: он используется как admin/identity-маркер при
    // регенерации, и часть кода (ensureCloakIdentity) на него полагается.
    public function delCloakUser($hash)
    {
        return $this->withShadowsocksLock(fn() => $this->delCloakUserLocked($hash));
    }

    private function delCloakUserLocked($hash)
    {
        $u = $this->findCloakUserByHash($hash);
        if (!$u) {
            return $this->menuCkUsers();
        }
        $c = $this->getCloakConfig();
        if (($u['uid'] ?? '') === ($c['UID'] ?? '')) {
            $this->send($this->input['chat'], $this->t('Пользователя по умолчанию удалить нельзя (смените ключи кнопкой regen keys)', 'cannot delete default user (use regen keys instead)'));
            return $this->menuCkUsers();
        }
        $list = array_values(array_filter(
            $this->getCloakUsers(),
            fn($x) => ($x['uid'] ?? '') !== ($u['uid'] ?? '')
        ));
        // Confirm revocation of the old generation before removing its retry
        // identity. A failed later write/start must not leave that UID live.
        if (!empty($c['Enabled'])) $this->requireSsTransportControl('ck-server', 'stop');
        $c['BypassUID'] = array_values(array_unique(array_filter(array_column($list, 'uid'))));
        $this->setCloakConfig($c);
        $this->setCloakUsers($list);
        $this->restartCloakIfRunning();
        $this->menuCkUsers();
    }

    // Per-user QR. ss://-ссылка та же, что в qrSS, но в plugin-opts UID=
    // подменяется на UID этого юзера. Файл именуем по name (с санитайзером,
    // чтобы exec/qrencode не получили опасных символов в пути).
    public function qrCloakUser($hash)
    {
        $u = $this->findCloakUserByHash($hash);
        if (!$u) {
            return $this->menuCkUsers();
        }
        $link    = $this->buildSSLink($this->getHashBot(), $u['uid']);
        $safe    = preg_replace('~[^a-zA-Z0-9_.\-]~', '_', $u['name']);
        $qr_file = __DIR__ . "/qr/cloak_$safe.png";
        exec('qrencode -t png -o ' . escapeshellarg($qr_file) . ' ' . escapeshellarg($link));
        $this->sendPhoto(
            $this->input['chat'],
            curl_file_create($qr_file),
            "<code>$link</code>\n\n<b>" . htmlspecialchars($u['name'], ENT_QUOTES) . "</b>"
        );
        @unlink($qr_file);
        if (($this->getPacConf()['blinkmenu'] ?? false)) {
            $this->delete($this->input['chat'], $this->input['message_id']);
            $this->input['message_id'] = $this->send($this->input['chat'], '.')['result']['message_id'];
            $this->ckUserMenu($hash);
        }
    }

    // Список всех cloak-пользователей. Default помечен ★. Если cloak
    // отключён — всё равно показываем список (можно подготовить юзеров
    // заранее, BypassUID применится при следующем enable).
    public function menuCkUsers()
    {
        $users      = $this->getCloakUsers();
        $c          = $this->getCloakConfig();
        $defaultUid = $c['UID'] ?? '';
        $cloakOn    = !empty($c['Enabled']);

        $text   = [];
        $text[] = 'Menu -> ShadowSocks -> ' . $this->i18n('cloak users');
        $text[] = 'cloak: ' . $this->i18n($cloakOn ? 'on' : 'off');
        $text[] = 'users: ' . count($users);

        $data   = [];
        $data[] = [[
            'text'          => $this->i18n('add user'),
            'callback_data' => '/addCloakUser',
        ]];
        foreach ($users as $u) {
            $hash   = substr(sha1($u['uid'] ?? ''), 0, 12);
            $marker = (($u['uid'] ?? '') === $defaultUid) ? '★ ' : '';
            $data[] = [[
                'text'          => $marker . ($u['name'] ?? '?'),
                'callback_data' => "/ckUser $hash",
            ]];
        }
        $data[] = [[
            'text'          => $this->i18n('back'),
            'callback_data' => '/menu ss',
        ]];

        if (!empty($this->input['callback_id'])) {
            $this->update($this->input['chat'], $this->input['message_id'], implode("\n", $text), $data);
        } else {
            $this->send($this->input['chat'], implode("\n", $text), $this->input['message_id'], $data);
        }
    }

    // Per-user submenu — мета (UID, дата) и actions (QR / delete).
    public function ckUserMenu($hash)
    {
        $u = $this->findCloakUserByHash($hash);
        if (!$u) {
            return $this->menuCkUsers();
        }
        $c         = $this->getCloakConfig();
        $isDefault = (($u['uid'] ?? '') === ($c['UID'] ?? ''));
        $created   = !empty($u['created']) ? date('Y-m-d', (int) $u['created']) : '?';

        $text   = [];
        $text[] = 'Menu -> ShadowSocks -> ' . $this->i18n('cloak users')
            . ' -> <code>' . htmlspecialchars($u['name'] ?? '?', ENT_QUOTES) . '</code>';
        $text[] = ($isDefault ? '★ default' : '');
        $text[] = "UID: <span class='tg-spoiler'>" . htmlspecialchars($u['uid'] ?? '', ENT_QUOTES) . "</span>";
        $text[] = "created: $created";

        $data   = [];
        $data[] = [[
            'text'          => $this->i18n('show QR'),
            'callback_data' => "/qrCloakUser $hash",
        ]];
        if (!$isDefault) {
            $data[] = [[
                'text'          => $this->i18n('delete'),
                'callback_data' => "/delCloakUser $hash",
            ]];
        }
        $data[] = [[
            'text'          => $this->i18n('back'),
            'callback_data' => '/ckUsers',
        ]];

        $this->update($this->input['chat'], $this->input['message_id'], implode("\n", array_filter($text)), $data);
    }


