    public function importList($type)
    {
        $r = $this->send(
            $this->input['chat'],
            $this->t("@{$this->input['username']} отправьте файл экспорта:", "@{$this->input['username']} send the export file:"),
            $this->input['message_id'],
            reply: $this->t('отправьте файл экспорта:', 'send the export file:'),
        );
        $this->stashReply($r, [
            'start_message'  => $this->input['message_id'],
            'start_callback' => $this->input['callback_id'],
            'callback'       => 'importListFile',
            'args'           => [$type],
        ]);
    }

    // $message без значения по умолчанию: параметр со значением ПЕРЕД
    // обязательным PHP считает обязательным и с 8.0 пишет об этом deprecation
    // на каждый разбор файла. Вызов один — из reply() и всегда с обоими
    // аргументами ($message, $type), так что дефолт был декоративным.
    public function importListFile($message, $type)
    {
        $r = $this->request('getFile', ['file_id' => $this->input['file_id']]);
        $f = isset($r['result']['file_path']) ? @file_get_contents($this->file . $r['result']['file_path']) : false;
        if ($f === false || trim($f) === '') {
            $this->send($this->input['from'], $this->t('Файл пуст или недоступен. Существующий список сохранён.', 'The file is empty or unavailable. The existing list is kept.'));
            $this->backXtlsList($type);
            return;
        }
        if (!empty($f)) {
            // Инициализация обязательна: без неё файл, в котором не нашлось ни
            // одной валидной строки, оставлял $list неопределённым, и присвоение
            // ниже стирало весь список пользователя.
            $list   = [];
            $merged = 0; $invalid = 0;
            foreach (explode("\n", $f) as $v) {
                if (!empty($s = trim($v))) {
                    // Последняя колонка — состояние; внутри regexp/URL тоже
                    // встречается ';'. Старый export писал false пустой строкой.
                    $t = preg_match('~^(.*);([01]?)$~s', $s, $columns)
                        ? [$columns[1], $columns[2]] : [$s];
                    // Формат экспорта — «запись;1», но импортируют и простые
                    // списки доменов без второй колонки. Раньше отсутствующий
                    // $t[1] давал false, и весь импорт приезжал выключенным.
                    $on = (bool) ($t[1] ?? 1);
                    $key = $this->isRouteEntryList($type) ? $this->normalizeRouteEntry($t[0]) : trim($t[0]);
                    if (!$this->routeListEntryValid($type, $key)) { $invalid++; continue; }
                    if (in_array($type, ['white', 'deny'], true)) {
                        if ($on) $list[] = $key;
                    } else $list[$key] = $on;
                }
            }
            if ($this->isRouteEntryList($type)) {
                ['list' => $list, 'removed' => $merged] = $this->dedupeRouteList($list);
                ksort($list);
            }
            if (!$list) {
                $this->send($this->input['from'], $this->t('В файле нет корректных правил. Существующий список сохранён.', 'The file has no valid rules. The existing list is kept.'));
                $this->backXtlsList($type);
                return;
            }
            $this->changeRouteList($type, function (&$current) use ($list) { $current = $list; });
            if ($invalid) $this->send($this->input['from'], $this->t("Неверных записей пропущено: $invalid.", "Invalid entries skipped: $invalid."));
            if ($merged > 0) {
                $this->send($this->input['from'], $this->i18n('duplicates merged') . ": $merged");
            }
        }
        $this->backXtlsList($type);
    }

    public function timerClient(string $time, int $client, $page = 0, $inst = null)
    {
        return $this->withWireguardUpdate(fn() => $this->timerClientLocked($time, $client, $page, $inst), ($inst === null || !in_array((int) $inst, [0, 1], true) ? null : ((int) $inst === 1 ? 'wg1' : 'wg')));
    }

    private function timerClientLocked(string $time, int $client, $page = 0, $inst = null)
    {
        $this->promptInstWG($inst);
        $clients = $this->readClients();
        if (empty($clients[$client])) {
            return $this->menu('wg', $page);
        }
        if (!empty($clients[$client]['# off'])) {
            if ($this->switchClient($client) === false) return false;
            $clients = $this->readClients();
        }
        $server = $this->readConfig();
        if (empty($server['interface'])) {
            $this->wgConfUnavailable($this->t('срок действия не изменён', 'expiry unchanged'));
            return $this->menu('client', "{$client}_$page");
        }
        // Пир — по адресу (peerIndexByClient), а не перебором с прямым чтением
        // 'AllowedIPs': у выключенного пира ключ закомментирован, и старый
        // цикл сыпал «Undefined array key» на каждом таком соседе.
        $i = $this->peerIndexByClient($server, $clients[$client]);
        switch (true) {
            case preg_match('~^0$~', $time):
                unset($clients[$client]['interface']['## time']);
                if ($i !== null) {
                    unset($server['peers'][$i]['## time']);
                }
                break;
            default:
                // strtotime() на нераспознанном вводе отдаёт false, а date()
                // печатала из него 1970-01-01 — то есть срок в прошлом, и
                // shutdownClient вырубал пира в ближайшие 10 секунд. Такая
                // проверка есть в setTimerXr, сюда она не доехала.
                $ts = strtotime((string) $time);
                if ($ts === false) {
                    $this->send($this->input['chat'] ?? '', 'wrong format', $this->input['message_id'] ?? null);
                    return $this->menu('client', "{$client}_$page");
                }
                $date = date('Y-m-d H:i:s', $ts);
                $clients[$client]['interface']['## time'] = $date;
                if ($i !== null) {
                    $server['peers'][$i]['## time'] = $date;
                }
                break;
        }
        if (!$this->applyWgConfig($this->createConfig($server), $clients)) throw new RuntimeException($this->t('WireGuard: применение не подтверждено; cron повторит операцию', 'WireGuard: application is unconfirmed; cron will retry the operation'));
        $this->menu('client', "{$client}_$page");
    }

    // Шаги разнесены по двум процессам (scripts/start_service.sh): access —
    // сроки, лимиты, учёт и онлайн, только локальные операции; maintenance —
    // сетевые и медленные проверки. Раньше один цикл ждал, например, пробу
    // узлов выхода или загрузку .dat, и отключение по сроку и лимиту
    // откладывалось на всё это время. Общие файлы шаги меняют под withLock().
    public const CRON_ACCESS = [
        'shutdownClient', 'shutdownClientXr', 'checkResetXrayStats', 'xrayStatsUser', 'checkTrafficLimits',
        'syncXrayProtocolUsers', 'checkAccessPolicies', 'trackOnline', 'trackWgOnline', 'trackTelemtOnline', 'trackOvpnTraffic', 'retryIkev2Users',
        'retryTelemtApply',
    ];

    public int $cronPeriod = 10;

    protected function cronContinue(): bool
    {
        return true;
    }

    public function cron(string $group = 'all', ?string $maintenance = null)
    {
        $child = null;
        // cron.php — foreground-процесс service-контейнера. Любой неперехваченный
        // Throwable из шага ниже (часть из них без своего try/catch) уронил бы
        // весь процесс → контейнер уходит в рестарт-цикл, и на каждом рестарте
        // заново гоняется selfUpdate (импорт настроек, telegram-сообщения,
        // offWarp). Изолируем каждый шаг: сбой одного не должен останавливать
        // остальную периодику (expiry-shutdown, traffic limits, cert renewal,
        // backup) и не должен ронять демон.
        $steps = [
            'shutdownClient',
            'shutdownClientXr',
            'checkVersion',
            'checkBackup',
            'checkLogs',
            'checkResetXrayStats',
            'checkCert',
            'ensureHtpasswd',
            'ensureAdguardPassword',
            // Тоже в cron, а не только в selfUpdate(): миграция обязана
            // доехать даже если service.php оборвался раньше своей последней
            // строки. Идемпотентна и на «нечего менять» выходит сразу.
            'migrateDohClientIds',
            'ensureNginxPhpMultipartGuard',
            'reconcileManagedUpstreams',
            'autoAnalyzeLogs',
            'xrayStatsUser',
            'checkTrafficLimits',
            'syncXrayProtocolUsers',
            'checkAccessPolicies',
            'trackOnline',
            'trackWgOnline',
            'trackTelemtOnline',
            'trackOvpnTraffic',
            'retryIkev2Users',
            'retryTelemtApply',
            'rotateAmneziaCron',
            'refreshExtSubCache',
            'checkDatUpdates',
            'checkDiskSpace',
            'checkCpuLoad',
            'backfillSubTokens',
            'checkRelayHealth',
            'resolveRelayHosts',
            'ensureDefaultTemplates',
            'checkExitNodes',
            'checkManagedNodes',
            'checkXrayCore',
            'checkRealityMask',
            'warmGeoCache',
            'refreshMenuStatusCache',
            'refreshMenuVersionsCache',
        ];
        if ($group === 'access') {
            $steps = self::CRON_ACCESS;
        } elseif ($group === 'maintenance') {
            $steps = array_values(array_diff($steps, self::CRON_ACCESS));
        } elseif ($group !== 'all') {
            throw new InvalidArgumentException('cron group');
        }
        while ($this->cronContinue()) {
            // Надзор за maintenance: в образе нет pcntl, поэтому дочерний процесс
            // через proc_open; упал — поднимается на следующем проходе.
            if ($maintenance !== null && !($child && proc_get_status($child)['running'])) {
                if ($child) proc_close($child);
                $child = proc_open([PHP_BINARY, $maintenance, 'maintenance'],
                    [0 => ['file', '/dev/null', 'r'], 1 => STDOUT, 2 => STDERR], $pipes) ?: null;
                if (!$child) error_log('cron: maintenance process not started');
            }
            foreach ($steps as $step) {
                try {
                    $this->$step();
                } catch (\Throwable $e) {
                    error_log("cron[$step]: " . $e->getMessage());
                }
                // A node change waits for this loop to confirm it. Between the long
                // maintenance steps, poll running node jobs instead of once per pass.
                if ($group !== 'access') $this->managedNodeJobsTick();
            }
            sleep($this->cronPeriod);
        }
        if ($child) proc_close($child);
    }

    // Все счётчики xray одним вызовом `xray api statsquery` вместо 2+2N вызовов
    // `xray api stats -name ...`: при 50 клиентах прежний цикл поднимал 102
    // ssh-сессии каждую минуту, и каждый ответ разбирался выражением
    // json_decode(...)['stat']['value'] ?: 0 — то есть обращением к индексу у
    // null на любом отказе (xray лежит, api не поднят, счётчика ещё нет).
    // В лог сыпался warning, а наружу уходил неотличимый от правды ноль.
    // Побочно: имена счётчиков больше не идут в шелл, escapeshellarg не нужен.
    //
    // Возвращает карту «имя счётчика => байты». null — прочитать НЕ удалось;
    // это отличается от пустой карты, которая значит «xray жив, счётчиков ещё
    // нет» (штатное состояние простаивающего сервера сразу после рестарта).
    public function xrayStatCounters(): ?array
    {
        $raw = $this->ssh('xray api statsquery --server=127.0.0.1:8080 2>&1', 'xr');
        if ($this->sshFailed) {
            // ssh() уже записал причину — второй раз не дублируем.
            return null;
        }
        if (trim((string) $raw) === '') {
            error_log('xrayStatCounters: empty output from xray api statsquery');
            return null;
        }
        $j = json_decode($raw, true);
        if (!is_array($j)) {
            $head = trim($raw);
            // Имена счётчиков содержат email'ы клиентов, поэтому в лог уходит
            // только то, что заведомо НЕ обрывок ответа: текст ошибки самого
            // xray (api выключен, ядро без statsquery). Всё, что начинается
            // как JSON, — недочитанный/битый ответ, пишем один факт и размер.
            if ($head !== '' && ($head[0] === '{' || $head[0] === '[')) {
                error_log('xrayStatCounters: malformed JSON from statsquery (' . strlen($raw) . ' bytes)');
            } else {
                error_log('xrayStatCounters: ' . substr((string) strtok($head, "\n"), 0, 200));
            }
            return null;
        }
        $map = [];
        foreach (($j['stat'] ?? []) as $s) {
            if (!is_array($s) || !isset($s['name'])) {
                continue;
            }
            // protojson опускает поле value, когда счётчик равен нулю.
            $map[(string) $s['name']] = (int) ($s['value'] ?? 0);
        }
        return $map;
    }

    // Онлайн-IP от самого ядра: `xray api statsonlineiplist -all` (StatsService,
    // GetUsersStats). Ядро держит карту «email -> живые IP» и вычёркивает IP,
    // как только контекст соединения закрылся (app/dispatcher/default.go,
    // trackOnlineIP), — то есть это СОСТОЯНИЕ, а не история.
    //
    // Зачем в дополнение к разбору /logs/xray (trackOnline): лог фиксирует
    // МОМЕНТ подключения, а онлайном клиент считается 60 секунд после него. При
    // включённом SMUX все потоки идут в одном несущем коннекте — новых строк в
    // логе после первой почти нет, и полностью подключённый клиент через минуту
    // «уходил в офлайн». Ядро же видит живое соединение всё время, пока оно
    // живо. Плюс независимость от уровня логирования: с loglevel=none лог не
    // пишется вовсе, а карта ядра остаётся.
    //
    // Требует "statsUserOnline" в policy.levels (см. saveXray) — без него
    // команда штатно отдаёт пустой ответ.
    //
    // Возвращает карту «email => [ip => last_seen]». null — прочитать НЕ
    // удалось (контейнер лежит, api выключен, ядро без этой команды); пустой
    // массив — ядро ответило, живых соединений нет.
    public function xrayOnlineIps(): ?array
    {
        $raw = $this->ssh('xray api statsonlineiplist --server=127.0.0.1:8080 -all 2>&1', 'xr');
        if ($this->sshFailed) {
            // ssh() уже записал причину — второй раз не дублируем.
            return null;
        }
        $raw = trim((string) $raw);
        if ($raw === '') {
            error_log('xrayOnlineIps: empty output from statsonlineiplist');
            return null;
        }
        $j = json_decode($raw, true);
        if (!is_array($j)) {
            // Тот же приём, что в xrayStatCounters: в ответе лежат email'ы
            // клиентов, поэтому в лог уходит только заведомо не-JSON — текст
            // ошибки самого xray (нет команды, api не поднят).
            if ($raw[0] === '{' || $raw[0] === '[') {
                error_log('xrayOnlineIps: malformed JSON from statsonlineiplist (' . strlen($raw) . ' bytes)');
            } else {
                error_log('xrayOnlineIps: ' . substr((string) strtok($raw, "\n"), 0, 200));
            }
            return null;
        }
        $map = [];
        foreach (($j['users'] ?? []) as $u) {
            if (!is_array($u) || empty($u['email'])) {
                continue;
            }
            $ips = [];
            foreach (($u['ips'] ?? []) as $e) {
                if (!is_array($e) || empty($e['ip'])) {
                    continue;
                }
                // protojson отдаёт int64 строкой и опускает нулевые поля;
                // snake_case на случай ядра с EmitDefaults/иным маршалером.
                $ips[(string) $e['ip']] = (int) ($e['lastSeen'] ?? $e['last_seen'] ?? 0);
            }
            $map[(string) $u['email']] = $ips;
        }
        return $map;
    }

    public function xrayStatsUser()
    {
        if (empty($this->time_xray_stats) || time() - $this->time_xray_stats > 60) {
            $this->time_xray_stats = time();
            try {
                // Порядок блокировок xray → apply → xray-stats, как у restartXray()
                // (collectSession): с разделением cron перезапуск ядра из
                // maintenance иначе свернул бы сессию между чтением API и
                // записью. Снимок снимаем уже ПОД xray-lock: старый снимок
                // после свёртки повторно начислял весь трафик прежней сессии.
                // apply-lock также защищает от старых обработчиков меню,
                // которые вызывают restartXray без внешнего xray-lock.
                $this->withLock('xray', fn() => $this->withXrayApplyLock(function () {
                    $counters = $this->xrayStatCounters();
                    // Отказ API не обнуляет последний успешный снимок.
                    if ($counters !== null) {
                        $this->withXrayStatsLock(fn() => $this->xrayStatsApply($counters));
                    }
                }), 30);
            } catch (\Throwable $th) {
            }
        }
    }

    private function xrayStatsApply(array $counters): void
    {
        $x = $this->getXray();
        // Конфиг нечитаем — снимок отложим до следующего тика: без
        // списка клиентов users[] пришлось бы затирать пустым.
        if (!is_array($x)) {
            return;
        }
        $p = $this->getXrayStats();
        // Тег пользовательского inbound берём из конфига: он не обязан
        // быть 'vless_tls' (restore бэкапа, правка xray.json из webapp),
        // а захардкоженное имя давало тихий ноль без единого сообщения.
        $tag = (string) ($x['inbounds'][0]['tag'] ?? 'vless_tls');
        $session = [
            'download' => $counters["inbound>>>$tag>>>traffic>>>downlink"] ?? 0,
            'upload'   => $counters["inbound>>>$tag>>>traffic>>>uplink"] ?? 0,
        ];
        // session — АБСОЛЮТНЫЙ снимок счётчиков ядра, а они монотонно
        // растут и обнуляются только его рестартом. Свой рестарт
        // (restartXray) сворачивает session в global сам, а внешний
        // (docker restart xr, OOM, ребут хоста, start_xray.sh) до сих
        // пор просто терял накопленное: следующий тик записывал сюда
        // нули, и квоты начинали считать заново. Просевший счётчик —
        // это и есть признак чужого рестарта: сворачиваем прошлую
        // сессию (общую и по каждому клиенту) до применения снимка.
        if ($session['download'] < ($p['session']['download'] ?? 0)
            || $session['upload'] < ($p['session']['upload'] ?? 0)
        ) {
            $p = self::foldSession($p);
        }
        $p['session'] = $session;
        // Разбивка по inbound'ам, кроме служебного api. Нужна ради
        // 'wg-in' (socks :10808, через него наружу ходят WG/AWG-клиенты):
        // его трафик не попадает ни в session, ни в пользовательские
        // счётчики, т.е. до сих пор не был виден нигде.
        // session СМЫСЛА НЕ МЕНЯЕТ и остаётся только по inbounds[0]:
        // он копится в global через collectSession() и участвует в
        // квотах, подмешать туда wg-in задним числом нельзя.
        $p['inbounds'] = [];
        foreach (($x['inbounds'] ?? []) as $in) {
            $t = (string) ($in['tag'] ?? '');
            if ($t === '' || $t === 'api' || isset($p['inbounds'][$t])) {
                continue;
            }
            $p['inbounds'][$t] = [
                'download' => $counters["inbound>>>$t>>>traffic>>>downlink"] ?? 0,
                'upload'   => $counters["inbound>>>$t>>>traffic>>>uplink"] ?? 0,
            ];
        }
        // Трафик узлов выхода: копится так же, как у пользователей, —
        // чтобы перезапуск Xray при каждой правке узлов его не обнулял.
        $exits = [];
        $nodes = $this->exitNodes();
        foreach (array_keys($nodes) as $id) {
            $id = (string) $id;
            $name = 'outbound>>>' . self::EXIT_TAG . $id . '>>>traffic>>>';
            $warpName = 'outbound>>>' . self::EXIT_TAG . 'warp-' . $id . '>>>traffic>>>';
            $current = ['up' => (int) ($counters[$name . 'uplink'] ?? 0) + (int) ($counters[$warpName . 'uplink'] ?? 0),
                'down' => (int) ($counters[$name . 'downlink'] ?? 0) + (int) ($counters[$warpName . 'downlink'] ?? 0)];
            $previousExit = $p['exits'][$id] ?? [];
            $modes = $previousExit['modes'] ?? [];
            $zero = ['up' => 0, 'down' => 0];
            $measured = [];
            foreach (['node' => $name, 'warp' => $warpName] as $mode => $prefix) {
                foreach (['up' => 'uplink', 'down' => 'downlink'] as $dir => $key) {
                    $bytes = (int) ($counters[$prefix . $key] ?? 0);
                    $last = $modes['raw'][$mode][$dir] ?? ($previousExit ? $bytes : 0);
                    $measured[$mode][$dir] = $bytes;
                    $delta = $bytes < $last ? $bytes : $bytes - $last;
                    $modes[$mode][$dir] = ($modes[$mode][$dir] ?? 0) + $delta;
                    if (isset($previousExit['modes'])) {
                        if ($mode === 'node') $current[$dir] = $previousExit['session'][$dir] ?? 0;
                        $current[$dir] += $delta;
                    }
                }
            }
            $modes['raw'] = $measured;
            $modes['since'] ??= time();
            // Пробы узла идут и при нулевом трафике основного inbound.
            // Его нули не обнаружат внешний restart: проверяем также
            // сам выход. Если foldSession уже сработал, session = 0
            // и повторного начисления здесь не будет.
            if ($current['up'] < ($previousExit['session']['up'] ?? 0)
                || $current['down'] < ($previousExit['session']['down'] ?? 0)) {
                foreach (['up', 'down'] as $direction) {
                    $previousExit['global'][$direction] = ($previousExit['global'][$direction] ?? 0)
                        + max(0, ($previousExit['session'][$direction] ?? 0) - ($previousExit['base'][$direction] ?? 0));
                }
                $previousExit['base'] = ['up' => 0, 'down' => 0];
            }
            $exits[$id] = ['session' => $current, 'global' => $previousExit['global'] ?? ['up' => 0, 'down' => 0],
                'base' => $previousExit['base'] ?? $zero, 'since' => (int) ($previousExit['since'] ?? time()), 'modes' => $modes];
        }
        if ($exits) $p['exits'] = $exits;
        else unset($p['exits']);
        if (!empty($users = $x['inbounds'][0]['settings']['clients'] ?? [])) {
            $tmp = [];
            foreach ($users as $k => $v) {
                $email = (string) ($v['email'] ?? '');
                $tmp[$k] = [
                    'session' => [
                        'download' => $counters["user>>>$email>>>traffic>>>downlink"] ?? 0,
                        'upload'   => $counters["user>>>$email>>>traffic>>>uplink"] ?? 0,
                    ],
                    // ?? — у только что добавленного клиента записи в
                    // xraystats.json ещё нет, прежний код сыпал здесь
                    // «Undefined array key» на каждый цикл крона.
                    'global' => [
                        'download' => $p['users'][$k]['global']['download'] ?? 0,
                        'upload'   => $p['users'][$k]['global']['upload'] ?? 0,
                    ]
                ];
            }
            $p['users'] = $tmp;
        }
        $this->setXrayStats($p);
    }

    public function autoAnalyzeLogs()
    {
        try {
            $pac = $this->getPacConf();
            if (!empty($pac['autoscan'])) {
                require __DIR__ . '/config.php';
                if (!empty($c['admin']) && (empty($this->time3) || ((time() - $this->time3) > $pac['autoscan_timeout']))) {
                    $this->time3 = time();
                    $r = $this->analysisIp(return: 1);
                    if (!empty($r)) {
                        foreach ($r as $k => $v) {
                            foreach ($v as $i) {
                                $t[$i['title']][$k] = 1;
                            }
                        }
                        foreach ($t as $k => $v) {
                            $text .= "\n" . count($v) . " $k";
                        }
                        if (!empty($pac['autodeny'])) {
                            $this->denyIp(array_keys($r));
                            $ban = count(array_keys($r));
                            foreach (array_keys($r) as $v) {
                                $ips[] = [[
                                    'text'          => $v,
                                    'callback_data' => "/searchLogs $v",
                                ]];
                            }
                        }
                        if ($pac['silence'] == 0 || $pac['silence'] == 1) {
                            foreach ($c['admin'] as $k => $v) {
                                $this->send($v, $this->t("найдены подозрительные IP: $text", "suspicious ips found: $text") . ($ban ? "\nbanned:$ban" : ''), button: $ips ?: [[
                                    [
                                        'text'          => $this->i18n('analyze'),
                                        'callback_data' => '/analysisIp',
                                    ],
                                ]], disable_notification: $pac['silence'] ? true : false);
                            }
                        }
                    }
                }
            }
        } catch (Exception $e) {
            file_put_contents('/logs/php_error', $e->getMessage());
        }
    }

    /**
     * Момент последнего планового запуска расписания «$start / $period».
     *
     * Периоды в неделях/днях/часах — фиксированное число секунд, их считаем
     * делением. А вот «1 month»/«1 year» фиксированной длины НЕ имеют:
     * strtotime('1 month', 0) даёт ровно 31 день, поэтому расписание съезжало
     * с календаря (01.01, 01.02, 04.03, 01.04, 02.05, …). Такие шагаем
     * календарём — шагов не больше числа периодов с момента старта.
     *
     * @return int 0, если расписание ещё не наступило или период не разобран.
     */
    public static function lastScheduled(int $start, string $period, int $now): int
    {
        $step = strtotime($period, 0);
        if ($start <= 0 || $step === false || $step <= 0 || $now < $start) {
            return 0;
        }
        if (preg_match('~month|year~i', $period)) {
            $t = $start;
            while (($next = strtotime($period, $t)) !== false && $next > $t && $next <= $now) {
                $t = $next;
            }
            return $t;
        }
        return $start + (int) floor(($now - $start) / $step) * $step;
    }

    public function checkBackup()
    {
        try {
            // Выключенное расписание не должно спорить за lock с ручным
            // экспортом/восстановлением и выдавать ложную ошибку в cron.
            if (empty($this->getPacConf()['backup'])) return;
            $this->withBackupLock(fn() => $this->checkBackupSchedule());
        } catch (Throwable $error) {
            // Место отказа помогает отличить занятый lock от ошибки экспорта.
            // Текст исключения может содержать секреты и здесь не выводится.
            error_log('checkBackup: ' . get_class($error) . ' at ' . basename($error->getFile()) . ':' . $error->getLine());
        }
    }

    private function checkBackupSchedule()
    {
        $c = $this->getPacConf();
        if (!empty($c['backup'])) {
            $now = time();
            [$start, $period] = array_pad(explode('/', $c['backup']), 2, '');
            $lastScheduledBackup = self::lastScheduled((int) strtotime(trim($start)), trim($period), $now);

            if ($lastScheduledBackup > 0) {
                // Проверяем, делали ли уже бэкап в этом периоде
                $lastBackupTime = $c['last_backup_time'] ?? 0;

                // Если последний бэкап был сделан до начала текущего периода - делаем бэкап
                if ($lastBackupTime < $lastScheduledBackup) {
                    if ($this->pinBackup()) {
                        $this->pacConfUpdate(function (&$current) use ($c, $now) {
                            if (($current['backup'] ?? '') === $c['backup']) $current['last_backup_time'] = $now;
                        });
                    }
                }
            }
        }
    }

    public function checkResetXrayStats()
    {
        // Под блокировкой xray: сброс перестраивает xray.json и статистику
        // параллельно с maintenance (см. xrayStatsUser()).
        $this->withLock('xray', fn() => $this->checkResetXrayStatsLocked(), 30);
    }

    private function checkResetXrayStatsLocked(): void
    {
        $pac = $this->getPacConf();
        if (empty($pac['reset_monthly'])) return;
        $now = time(); $last = (int) ($pac['last_reset_xray_time'] ?? 0);
        $scheduled = strtotime('first day of this month midnight');
        if ($last > 0 && ($scheduled === false || $last >= $scheduled)) return;
        if ($last > 0) $this->resetXrStatsLocked(1);
        $this->pacConfUpdate(function (&$pac) use ($last, $now) {
            if (!empty($pac['reset_monthly']) && (int) ($pac['last_reset_xray_time'] ?? 0) === $last) $pac['last_reset_xray_time'] = $now;
        });
        if ($last > 0 && is_file(__DIR__ . '/config.php')) {
            require __DIR__ . '/config.php';
            foreach (($c['admin'] ?? []) as $admin) $this->send($admin, $this->t('vless: статистика сброшена', 'vless: reset stats'));
        }
    }

    public function checkLogs()
    {
        $clean = $this->pacConfUpdate(function (&$c) {
            if (empty($c['autocleanlogs'])) return false;
            $now = time();
            [$start, $period] = array_pad(explode('/', $c['autocleanlogs']), 2, '');
            $scheduled = self::lastScheduled((int) strtotime(trim($start)), trim($period), $now);
            if ($scheduled <= 0 || ($c['last_clean_logs_time'] ?? 0) >= $scheduled) return false;
            $c['last_clean_logs_time'] = $now;
            return true;
        });
        if ($clean) $this->cleanLog(true);
    }

    public function cleanQueue(): void
    {
        $r = $this->request('deleteWebhook', []);
        $r = $this->request('getUpdates', ['offset' => -1]);
    }

    public function pinAdmin($pin, $unpin = false)
    {
        require __DIR__ . '/config.php';
        if ($unpin) {
            return $this->unpin($c['admin'][0], $pin);
        } else {
            return $this->pin($c['admin'][0], $pin);
        }
    }

    public function pinBackup($file = false)
    {
        try { return $this->withBackupLock(fn() => $this->sendBackup($file)); }
        catch (Throwable $error) {
            error_log('pinBackup: ' . get_class($error));
            return false;
        }
    }

    private function sendBackup($file)
    {
        require __DIR__ . '/config.php';
        $bot  = preg_replace('~[\W]~iu', '_', $this->request('getMyName', [])['result']['name'] ?? 'VPNBot');
        $started = time();
        try { $json = $this->export(); }
        catch (Throwable $error) {
            error_log('pinBackup: ' . get_class($error) . ' at ' . basename($error->getFile()) . ':' . $error->getLine());
            return false;
        }
        if (!is_string($json) || !is_array(json_decode($json, true))) {
            return false;
        }
        // Облачный Bot API отправляет файлы до 50 МБ, но getFile скачивает
        // только до 20 МБ. Такая копия должна оставаться восстанавливаемой.
        if (strlen($json) > 20 * 1024 * 1024) {
            error_log('pinBackup: snapshot exceeds Telegram getFile limit');
            return false;
        }
        if (!empty($file)) {
            if (!$this->writePrivateKey($file, $json)) return false;
        }
        // Полный экспорт содержит ключи: отправляем из памяти, без временного
        // файла с обычными правами чтения в /logs.
        $sent = $this->sendFile($c['admin'][0], new CURLStringFile(
            $json, "{$bot}_export_" . date('d_m_Y_H_i') . '.json', 'application/json'
        ), $this->managedNodeBackupCaption($started));
        if (empty($sent['ok']) || !is_int($sent['result']['message_id'] ?? null)) return false;
        // Экспорт/Telegram могут занять секунды. Не возвращаем на диск старую
        // копию PAC поверх настроек, изменённых за это время.
        $pin = $sent['result']['message_id'];
        $previous = $this->pacConfUpdate(function (&$conf) use ($pin) {
            $previous = $conf['pinbackup'] ?? null;
            $conf['pinbackup'] = $pin;
            return $previous;
        });
        $pinned = $this->pinAdmin($pin);
        // Не теряем прежнее закрепление при отказе отправки или закрепления.
        if (!empty($pinned['ok']) && !empty($previous) && $previous !== $pin) {
            $this->pinAdmin($previous, 1);
        }
        return true;
    }

    public function checkVersion()
    {
        try {
            require __DIR__ . '/config.php';
            if (!empty($c['admin']) && (empty($this->time) || ((time() - $this->time) > 3600))) {
                $this->time = time();
                $current    = file_get_contents('/version');
                $b          = exec('git -C / rev-parse --abbrev-ref HEAD');
                // Сверяемся со СВОИМ репозиторием, а не с upstream: version
                // удалённой ветки читаем через git (fetch из /.git).
                exec('git -C / fetch -q 2>/dev/null');
                $last       = shell_exec('git -C / show ' . escapeshellarg("origin/$b:version") . ' 2>/dev/null');
                if (!empty($last) && $last != $this->last && $last != $current) {
                    $this->last = $last;
                    // По СОДЕРЖИМОМУ, а не по разнице числа строк. Прежняя
                    // формула считала «что нового» как
                    // count($last) - count($current) и предполагала, что записи
                    // только дописываются сверху. Отсюда два отказа:
                    //  - удалённая ветка короче локальной (переключились на
                    //    ветку с более коротким changelog, файл подрезали в
                    //    веб-редакторе — с этим репозиторием так и работают) →
                    //    третий аргумент array_slice отрицательный, а это
                    //    «убрать N с конца», то есть в $diff попадал почти весь
                    //    удалённый changelog: всем админам уходило «обновление»,
                    //    а при autoupdate бот откатывал сам себя;
                    //  - число строк совпало, содержимое разное → разница 0,
                    //    $diff пуст, и о реальном обновлении никто не узнавал,
                    //    причём $this->last уже перезаписан.
                    $diff = array_values(array_diff(
                        array_filter(array_map('trim', explode("\n", $last)), 'strlen'),
                        explode("\n", $current)
                    ));
                    $diff       = array_slice($diff, 0, 10);
                    if (!empty($diff)) {
                        $hash   = $this->getHashBot();
                        $domain = $this->getPacConf()['domain'] ?: $this->ip;
                        foreach ($c['admin'] as $k => $v) {
                            $this->send($v, implode("\n", $diff), 0, [
                                [
                                    [
                                        'text'    => 'changelog',
                                        'web_app' => ['url' => $this->changelogUrl()],
                                    ],
                                    [
                                        'text'          => $this->i18n('update bot'),
                                        'callback_data' => "/applyupdatebot",
                                    ],
                                ]
                            ]);
                        }
                        // Автообновление — только если удалённая ветка
                        // РЕАЛЬНО впереди. Отличие текста version от локального
                        // этого не доказывает: он отличается и при откате.
                        $ahead = (int) trim((string) shell_exec(
                            'git -C / rev-list --count HEAD..' . escapeshellarg("origin/$b") . ' 2>/dev/null'
                        ));
                        if ($ahead > 0 && $this->getPacConf()['autoupdate']) {
                            $this->input['chat'] = $this->input['from'] = $c['admin'][0];
                            $this->applyupdatebot();
                        }
                    }
                }
            }
        } catch (\Throwable $e) {
            // Раньше здесь стоял пустой catch (Exception): в PHP 8 TypeError и
            // прочие Error — это не Exception, то есть падение checkVersion
            // роняло весь шаг cron молча.
            error_log('checkVersion: ' . $e->getMessage());
        }
    }

    // Корень домена закрыт `auth_basic` и работает приманкой для активного
    // пробинга: без учётных данных nginx отдаёт 401 — ровно как любой сайт с
    // закрытой зоной. Но когда файла паролей НЕТ, на присланную пару
    // логин/пароль тот же nginx отвечает 403 и пишет в лог
    // `open() "…/.htpasswd" failed`, тогда как настоящий сайт отвечает 401
    // повторно. То есть отсутствие файла само выдаёт сервер любому, кто
    // подставит произвольные креденшелы, — а именно от этого страница и стоит.
    //
    // В образе файла нет и создать его некому: `nginx.conf` только ссылается на
    // путь. Поэтому заводим сами — на новой установке, после `make reset` и
    // вообще всякий раз, когда файл пропал.
    //
    // Пароль случайный и НИГДЕ не сохраняется: страница не должна пускать
    // внутрь, ей достаточно правдоподобно отказывать. Кому нужна веб-панель —
    // тот кладёт свой файл, и этот метод его не тронет.
    // Пароль админки AdGuard. В шаблоне config/AdGuardHome.yaml поле password
    // ПУСТОЕ, а сама админка проксируется наружу по /adguard<hash>/, где
    // «гейт» — cookie с публичным hash из ссылок подписки. То есть между
    // первым стартом контейнера и первым прогоном adguardSync() (его дёргает
    // только смена сертификата/домена или кнопка в меню) админка стояла вообще
    // без пароля: перенастройка DNS всех пользователей и чтение их query-лога.
    // Пароль генерирует adguardSync(); зовём его ровно один раз — когда пусто.
    public function ensureAdguardPassword(): bool
    {
        if (!is_file($this->adguard)) {
            return false;
        }
        $c = @yaml_parse_file($this->adguard);
        if (!is_array($c) || !empty($c['users'][0]['password'])) {
            return false;
        }
        error_log('ensureAdguardPassword: AdGuardHome без пароля — генерируем');
        $this->adguardSync();

        return true;
    }

    public function ensureHtpasswd(): bool
    {
        // Пустой файл считаем отсутствующим: nginx на нём отвечает 401, но
        // осмысленным он от этого не становится, а появиться мог только от
        // оборванной записи.
        if (is_file($this->htpasswd) && filesize($this->htpasswd) > 0) {
            return false;
        }
        $pw   = rtrim(strtr(base64_encode(random_bytes(48)), '+/', '-_'), '=');
        $hash = password_hash($pw, PASSWORD_BCRYPT);
        // bcrypt, а не apr1: PHP умеет его из коробки, а nginx на alpine
        // принимает (проверено на живом сервере — верный пароль проходит
        // авторизацию, неверный получает 401).
        if (!is_string($hash) || false === @file_put_contents($this->htpasswd, 'admin:' . $hash . "\n")) {
            error_log('ensureHtpasswd: ' . $this->htpasswd . ' not written');

            return false;
        }
        // Файл создаётся от root, а читает его воркер nginx (uid nginx). Без
        // прав на чтение всем nginx вернётся ровно к тому 403, от которого мы
        // уходим, — только теперь молча и с файлом на месте.
        @chmod($this->htpasswd, 0644);
        error_log('ensureHtpasswd: fake-page password file created');

        return true;
    }

    public function checkCert()
    {
        try {
            require __DIR__ . '/config.php';
            if (!empty($c['admin']) && date('H') == 12 && (empty($this->time2) || ((time() - $this->time2) > 4600))) {
                $this->time2 = time();
                $cert = $this->expireCert();
                if (!empty($cert) && $cert - 60 * 60 * 24 * 14 < time()) {
                    foreach ($c['admin'] as $k => $v) {
                        $this->send($v, "certificate expire: " . date('Y-m-d H:i:s', $cert));
                    }
                }
            }
        } catch (Exception $e) {
        }
    }

    public function getTime(int $seconds)
    {
        $seconds = ($seconds - time()) > 0 ? $seconds - time() : 0;
        $items   = [
            'Y' => [
                'diff' => 1970,
                'sign' => 'y',
            ],
            'm' => [
                'diff' => 1,
                'sign' => 'mon',
            ],
            'd' => [
                'diff' => 1,
                'sign' => 'd',
            ],
            'H' => [
                'diff' => 0,
                'sign' => 'h',
            ],
            'i' => [
                'diff' => 0,
                'sign' => 'min',
            ],
            's' => [
                'diff' => 0,
                'sign' => 's',
            ],
        ];
        $text = '';
        $i = 0;
        foreach ($items as $k => $v) {
            if (($t = gmdate($k, $seconds) - $v['diff']) > 0) {
                $text .= " $t{$v['sign']}";
                if (!empty($i)) {
                    break;
                }
                $i++;
            }
        }
        return trim($text) ?: '♾';
    }

    public function shutdownClient()
    {
        $previous = $this->wg ?? null;
        try {
            for ($instance = 0; $instance < 2; $instance++) {
                $this->wg = $instance;
                try {
                    if (!$this->retryWireguardApply()) continue;
                    $this->withWireguardUpdate(function () {
                        $clients = $this->readClients();
                        foreach (array_keys($clients) as $index) {
                            $clients = $this->readClients();
                            $client = $clients[$index] ?? [];
                            if (empty($client['interface']['## time']) || strtotime($client['interface']['## time']) >= time()) continue;
                            // Expiry is an idempotent revoke, never an enable toggle.
                            if (!empty($client['# off'])) {
                                unset($clients[$index]['interface']['## time']);
                                if ($this->saveClients($clients) === false) throw new RuntimeException('WireGuard expiry save failed');
                            } elseif ($this->switchClient($index) === false) {
                                break;
                            }
                        }
                    });
                } catch (Throwable $error) {
                    error_log('WireGuard expiry/apply is unconfirmed; retry next tick');
                }
            }
        } finally {
            if ($previous === null) unset($this->wg); else $this->wg = $previous;
        }
    }

    public function shutdownClientXr()
    {
        // Под блокировкой xray: с разделением cron (access/maintenance) этот
        // шаг идёт параллельно с узлами выхода и обработчиками Telegram, и
        // чтение-изменение-запись xray.json иначе теряло бы чужие правки.
        $this->withLock('xray', fn() => $this->shutdownClientXrLocked(), 30);
    }

    private function shutdownClientXrLocked(): void
    {
        try {
            $c = $this->getXray();
            foreach ($c['inbounds'][0]['settings']['clients'] as $k => $v) {
                // switchXr() — ТУМБЛЕР: на уже выключенном клиенте он
                // восстанавливает id из 'off' и снимает traffic_off. Без
                // проверки 'off' клиент, отключённый по исчерпанной квоте
                // (checkTrafficLimits ставит 'off', 'time' не трогает), после
                // наступления даты снова включался — со старой ссылкой.
                if (!empty($v['time']) && ($v['time'] < time()) && empty($v['off'])) {
                    $this->switchXrLocked($k, 1);
                }
            }
        } catch (Exception $e) {
        }
    }

    // Total bytes used by Xray client index $k (down+up, global+session) — same
    // figure userXr() shows. $st is getXrayStats().
    public function xrUserTraffic($st, $k)
    {
        $u = $st['users'][$k] ?? [];
        return ($u['global']['download'] ?? 0) + ($u['session']['download'] ?? 0)
             + ($u['global']['upload'] ?? 0) + ($u['session']['upload'] ?? 0);
    }

    // UUID v4 для vless-клиента. Раньше значение брали у ядра (`xray uuid`), и
    // при недоступном контейнере ssh() отдавал пустую строку: пустой id уезжал
    // в clients[] и сохранялся: ядро с таким конфигом не поднимается вовсе —
    // падал весь VLESS, причём в самых неудачных местах (отключение по квоте,
    // switchXr, добавление пользователя). Внешняя зависимость здесь не нужна:
    // `xray uuid` печатает обычный случайный UUID.
    public static function xrayUuid(): string
    {
        $b    = random_bytes(16);
        $b[6] = chr((ord($b[6]) & 0x0f) | 0x40); // версия 4
        $b[8] = chr((ord($b[8]) & 0x3f) | 0x80); // вариант RFC 4122
        $h    = bin2hex($b);
        return substr($h, 0, 8) . '-' . substr($h, 8, 4) . '-' . substr($h, 12, 4)
            . '-' . substr($h, 16, 4) . '-' . substr($h, 20, 12);
    }

    // Cron enforcement of per-client traffic quotas ($client['traffic'] = byte
    // limit, 0/unset = unlimited). Over-quota clients are disabled the same way
    // switchXr does (rotate id/password so the live connection drops) and tagged
    // 'traffic_off' so a stats reset can re-enable them. One restart for the batch.
    public function checkTrafficLimits()
    {
        // Под блокировкой xray — см. shutdownClientXr(). Уведомление — после.
        $disabled = $this->withLock('xray', fn() => $this->checkTrafficLimitsLocked(), 30, []);
        if (!empty($disabled)) {
            $this->notifyAdmins($this->t("vless: контроль общего лимита, отключены:\n", "vless: shared quota enforcement, disabled:\n") . implode("\n", $disabled));
        }
    }

    private function checkTrafficLimitsLocked(): array
    {
        $disabled = [];
        try {
            $x  = $this->getXray();
            $statsKnown = true;
            try { $st = $this->getXrayStats(); if (!is_array($st)) throw new RuntimeException('Xray usage unavailable'); }
            catch (Throwable $error) { $st = []; $statsKnown = false; }
            $disabled = [];
            foreach ($x['inbounds'][0]['settings']['clients'] as $k => $v) {
                $limit = (int) ($v['traffic'] ?? 0);
                if ($limit <= 0 || !empty($v['off'])) {
                    continue;
                }
                $known = $statsKnown; $exhausted = false;
                try { $exhausted = $this->xrUserTraffic($st, $k) + array_sum($this->xrayProtocolUsage($v)) >= $limit; }
                catch (Throwable $error) { $known = false; }
                if (!$known || $exhausted) {
                    $x['inbounds'][0]['settings']['clients'][$k]['off'] = $v['id'];
                    $x['inbounds'][0]['settings']['clients'][$k]['id']  = self::xrayUuid();
                    if (isset($v['password'])) {
                        $x['inbounds'][0]['settings']['clients'][$k]['off_pwd']  = $v['password'];
                        $x['inbounds'][0]['settings']['clients'][$k]['password'] = self::xrayUuid();
                    }
                    $x['inbounds'][0]['settings']['clients'][$k]['traffic_off'] = 1;
                    if (!$known) $x['inbounds'][0]['settings']['clients'][$k]['traffic_usage_unavailable'] = 1;
                    else unset($x['inbounds'][0]['settings']['clients'][$k]['traffic_usage_unavailable']);
                    $disabled[] = $v['email'] . (!$known ? $this->t(' (общий расход недоступен)', ' (shared usage unavailable)') : '');
                }
            }
            if (!empty($disabled) && $this->restartXray($x) === false) {
                $disabled = [];
            }
        } catch (\Throwable $e) {
            $disabled = [];
        }
        return $disabled;
    }

    // Re-enable clients that were auto-disabled by the traffic quota (called when
    // stats are reset, so a new period restores access). $only limits it to one
    // client index. Mutates and returns the xray config; caller persists it via
    // restartXray().
    public function reenableTrafficClients(array $x, $only = null): array
    {
        foreach ($x['inbounds'][0]['settings']['clients'] as $k => $v) {
            if (empty($v['traffic_off']) || (!empty($v['time']) && $v['time'] <= time())) {
                continue;
            }
            if ($only !== null && (string) $k !== (string) $only) {
                continue;
            }
            if (!empty($v['off'])) {
                $x['inbounds'][0]['settings']['clients'][$k]['id'] = $v['off'];
                if (isset($v['password'])) {
                    $x['inbounds'][0]['settings']['clients'][$k]['password'] = ($v['off_pwd'] ?? '') ?: $v['off'];
                    unset($x['inbounds'][0]['settings']['clients'][$k]['off_pwd']);
                }
                unset($x['inbounds'][0]['settings']['clients'][$k]['off']);
            }
            unset($x['inbounds'][0]['settings']['clients'][$k]['traffic_off'], $x['inbounds'][0]['settings']['clients'][$k]['traffic_usage_unavailable']);
        }
        return $x;
    }

    public function renameClient(string $name, int $client, $page = 0, $inst = null)
    {
        return $this->withWireguardUpdate(fn() => $this->renameClientLocked($name, $client, $page, $inst), ($inst === null || !in_array((int) $inst, [0, 1], true) ? null : ((int) $inst === 1 ? 'wg1' : 'wg')));
    }

    private function renameClientLocked(string $name, int $client, $page = 0, $inst = null)
    {
        $this->promptInstWG($inst);
        $name    = self::sanitizeConfValue($name);
        $clients = $this->readClients();
        if (empty($clients[$client])) {
            return $this->menu('wg', $page);
        }
        // Серверный конфиг читаем ДО записи clients.json: при недоступном
        // контейнере имя менялось локально, в wg0.conf оставалось старое, и
        // пользователю об этом не сообщалось вовсе.
        $server = $this->readConfig();
        if (empty($server['interface'])) {
            $this->wgConfUnavailable($this->t('имя не изменено', 'name unchanged'));
            return $this->menu('client', "{$client}_$page");
        }
        $clients[$client]['interface']['## name'] = $name;
        // peerIndexByClient понимает и выключенного пира ('# AllowedIPs'):
        // раньше переименование выключенного клиента меняло только
        // clients.json, а в wg0.conf оставалось старое имя, и оно
        // «возвращалось» при включении.
        $i = $this->peerIndexByClient($server, $clients[$client]);
        if ($i !== null) {
            $off = !isset($server['peers'][$i]['AllowedIPs']);
            $server['peers'][$i][$off ? '# ## name' : '## name'] = $name;
        }
        if (!$this->applyWgConfig($this->createConfig($server), $clients)) throw new RuntimeException($this->t('WireGuard: применение не подтверждено; cron повторит операцию', 'WireGuard: application is unconfirmed; cron will retry the operation'));
        $this->menu('client', "{$client}_$page");
    }

    public function readClients(): array
    {
        // is_file — на свежей установке clients1.json может ещё не быть, а
        // file_get_contents на отсутствующем файле сыпал warning в лог на
        // каждый рендер меню.
        $f = $this->getInstanceWG(1) ? $this->clients1 : $this->clients;
        return is_file($f) ? (json_decode(file_get_contents($f), true) ?: []) : [];
    }

    public function export()
    {
        return $this->withBackupLock(fn() => $this->exportBackup());
    }

    private function exportBackup()
    {
        // Снимки нод обновляются до чтения PAC; в конце состояние нод сверяется с
        // начальным. Операция ноды, завершившаяся посреди копирования, иначе
        // соединила бы в архиве прежний статус или профиль с новым snapshot.json.
        $this->managedNodeBackupRefresh();
        for ($attempt = 1; ; $attempt++) {
            $mark = $this->managedNodeBackupMark();
            $json = $this->exportBackupOnce();
            if ($this->managedNodeBackupMark() === $mark) return $json;
            if ($attempt >= 3) throw new RuntimeException($this->t('Нода изменилась во время резервного копирования. Повторите бэкап после завершения операции на ноде.',
                'A node changed during the backup. Retry the backup after the node operation finishes.'));
        }
    }

    private function exportBackupOnce()
    {
        foreach ([$this->xrayConf, $this->hwid, '/config/xray.stats', '/config/ckserver.json', '/config/ckusers.json'] as $path) {
            // После миграции экспорт читает HWID из SQLite. Старый JSON
            // остаётся для отката и не должен блокировать актуальную копию.
            if ($path === $this->hwid && $this->store() !== null) continue;
            if (is_file($path) && !is_array(json_decode((string) file_get_contents($path), true, 512, JSON_THROW_ON_ERROR))) {
                throw new RuntimeException($this->t('Повреждён файл конфигурации: ', 'Damaged configuration file: ') . basename($path));
            }
        }
        $wgModes = [];
        $wg = $this->backupWireGuard(0, $wgModes);
        $wg1 = $this->backupWireGuard(1, $wgModes);
        // Инстанс, выбранный для снятия дампа, не должен протекать в остаток
        // запроса (финальный menu(), getInstanceWG-рендеры) — как в import()
        // и shutdownClient/syncPortClients.
        unset($this->wg);
        $ocBackup = $this->withOcUsersSnapshot(fn(string $raw) => [
            'telemt' => $this->telemtBackupSnapshot(),
            'oc' => file_get_contents('/config/ocserv.conf'),
            'ocu' => $raw,
        ]);
        $telemtBackup = $ocBackup['telemt'];
        // Each mode belongs to its interface snapshot, not to a later PAC read.
        foreach ($wgModes as $key => $mode) {
            if ($mode['present']) $telemtBackup['pac'][$key] = $mode['value'];
            else unset($telemtBackup['pac'][$key]);
        }
        $ssl = false;
        if (is_file($this->protocolCertRoot . '/cert_private') !== is_file($this->protocolCertRoot . '/cert_public')) {
            throw new RuntimeException($this->t('Неполная TLS-пара', 'Incomplete TLS pair'));
        }
        if (is_file($this->protocolCertRoot . '/cert_private')) {
            $private = file_get_contents($this->protocolCertRoot . '/cert_private');
            $public = @file_get_contents($this->protocolCertRoot . '/cert_public');
            if (!is_string($private) || !is_string($public) || !self::certificatePairValid($public, $private)) {
                throw new RuntimeException($this->t('Не удалось сохранить полную TLS-пару', 'Could not save the full TLS pair'));
            }
            $ssl = ['private' => $private, 'public' => $public];
        }
        $xraySnapshot = $this->withLock('xray', fn() => $this->withXrayApplyLock(fn() => [$this->getXray(), $this->getXrayStats()]), 30);
        if (!is_array($xraySnapshot)) throw new RuntimeException('Could not lock Xray backup');
        $ssSnapshot = $this->withShadowsocksLock(function () {
            $server = $this->getSSConfig(); $local = $this->getSSLocalConfig();
            if (!is_array($server) || !is_array($local)) throw new RuntimeException('Shadowsocks backup configuration unavailable');
            $cloak = is_file('/config/ckserver.json') ? json_decode(file_get_contents('/config/ckserver.json'), true, 512, JSON_THROW_ON_ERROR) : null;
            $users = is_file('/config/ckusers.json') ? json_decode(file_get_contents('/config/ckusers.json'), true, 512, JSON_THROW_ON_ERROR) : null;
            return [$server, $local, $cloak, $users, $this->backupSimpleTlsFileLocked()];
        });
        $conf = [
            'wg'  => $wg,
            'wg1' => $wg1,
            'ad'  => yaml_parse_file($this->adguard),
            // acme_requested — пометка запроса к службе acme-window ЭТОГО сервера:
            // в копию не идёт, на другом сервере она ничего не значит.
            'pac' => $this->withoutPanelGrants(array_diff_key($telemtBackup['pac'], ['acme_requested' => true])),
            'hwid' => $this->getHwidStorage(),
            'ssl' => $ssl,
            'dnstt' => file_exists('/config/dnstt/server.key') ? [
                'private' => file_get_contents('/config/dnstt/server.key'),
                'public'  => file_get_contents('/config/dnstt/server.pub'),
                'ssh_private' => is_file('/config/dnstt/ssh_host_ed25519_key')
                    ? file_get_contents('/config/dnstt/ssh_host_ed25519_key') : '',
                'ssh_public' => is_file('/config/dnstt/ssh_host_ed25519_key.pub')
                    ? file_get_contents('/config/dnstt/ssh_host_ed25519_key.pub') : '',
            ] : false,
            'xray'          => $xraySnapshot[0],
            'hy'            => yaml_parse_file('/config/hysteria.yaml'),
            'hy_users'      => $this->hysteriaUsersStore()->snapshot(),
            'oc'            => $ocBackup['oc'],
            'ocu'           => $ocBackup['ocu'],
            'tt'            => file_exists('/config/trusttunnel/credentials.toml') ? file_get_contents('/config/trusttunnel/credentials.toml') : '',
            'ss'            => $ssSnapshot[0],
            'sl'            => $ssSnapshot[1],
            'cloak'         => $ssSnapshot[2],
            'ckusers'       => $ssSnapshot[3],
            'ovpn'          => $this->exportOvpnPki(),
            ...$this->ovpnBackupSections(),
            'ipsec'         => $this->exportIpsecPki(),
            'xraystats'     => $xraySnapshot[1],
            'managed_protocols' => $this->exportManagedProtocols(),
            'telemt_quota' => $telemtBackup['telemt_quota'],
            'extra_files' => array_diff_key($this->backupExtraFiles(false), ['stlsserver.json' => true]) + $ssSnapshot[4],
        ];
        foreach (['ad', 'hy', 'oc', 'ocu', 'tt'] as $key) {
            if ($conf[$key] === false) throw new RuntimeException($this->t('Не удалось прочитать раздел бэкапа: ', 'Could not read the backup section: ') . $key);
        }
        $this->validateBackup($conf);
        return json_encode($conf, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_THROW_ON_ERROR);
    }

    private function backupWireGuard(int $instance, array &$modes = []): array
    {
        $snapshot = $this->withWireguardLock(function () use ($instance, &$modes) {
            if ($this->hasWireguardPending()) throw new RuntimeException($this->t('WireGuard ожидает применения; повторите резервное копирование после подтверждения', 'WireGuard apply is pending; retry the backup after confirmation'));
            $snapshot = $this->backupWireGuardLocked($instance);
            $key = $instance ? 'wg1_amnezia' : 'amnezia';
            $pac = $this->getPacConf();
            $modes[$key] = ['present' => array_key_exists($key, $pac), 'value' => $pac[$key] ?? null];
            return $snapshot;
        }, $instance ? 'wg1' : 'wg', 120, false);
        if (!is_array($snapshot)) throw new RuntimeException($this->t('Не удалось заблокировать WireGuard для копирования', 'Could not lock WireGuard for the backup'));
        return $snapshot;
    }

    private function backupWireGuardLocked(int $instance): array
    {
        $clients = $instance ? $this->clients1 : $this->clients;
        $path = dirname($clients) . '/wg' . $instance . '.conf';
        $users = is_file($clients) ? json_decode((string) file_get_contents($clients), true, 512, JSON_THROW_ON_ERROR) : [];
        if (!is_array($users)) throw new RuntimeException($this->t('Некорректный список WireGuard', 'Invalid WireGuard list'));
        // Локальный bind-файл доступен и при выключенном контейнере.
        if (is_file($path)) {
            $body = file_get_contents($path);
            if ($body === false) throw new RuntimeException($this->t('Конфигурация WireGuard недоступна', 'The WireGuard configuration is unavailable'));
            $server = $this->parseWireGuardConfig($body);
        } else {
            $server = $this->readConfig();
            if ($this->sshFailed) throw new RuntimeException($this->t('Не удалось сохранить WireGuard', 'Could not save WireGuard'));
        }
        if ($users && empty($server['interface'])) throw new RuntimeException($this->t('Неполная конфигурация WireGuard', 'Incomplete WireGuard configuration'));
        return ['server' => $server, 'clients' => $users];
    }

    private function restoreBackupWireGuard(array $snapshot, int $switch, ?bool $mode = null): bool
    {
        $instance = $this->getInstanceWG() === 'wg1' ? 1 : 0;
        $service = $instance ? 'wg1' : 'wg';
        return (bool) $this->withWireguardLock(function () use ($snapshot, $switch, $instance, $service, $mode) {
            if ($this->hasWireguardPending()) return false;
            $clients = $instance ? $this->clients1 : $this->clients;
            $path = dirname($clients) . '/wg' . $instance . '.conf';
            $before = [];
            foreach ([$path, $clients] as $file) {
                if (is_link($file) || (file_exists($file) && !is_file($file))) return false;
                $before[$file] = is_file($file) ? file_get_contents($file) : null;
                if ($before[$file] === false) return false;
            }
            $body = $this->createConfig($snapshot['server']);
            $modeKey = $instance ? 'wg1_amnezia' : 'amnezia';
            $currentMode = !empty($this->getPacConf()[$modeKey]);
            $desiredMode = $mode ?? $currentMode;
            $wasAmnezia = $mode === null && $switch ? !$currentMode : $currentMode;
            if ($mode !== null) $switch = (int) ($wasAmnezia !== $desiredMode);
            $enabled = $this->protocolModuleEnabled($service);
            $filesStarted = false;
            try {
                if ($mode !== null && $switch) {
                    $this->pacConfUpdate(function (&$pac) use ($modeKey, $desiredMode) {
                        $pac[$modeKey] = (int) $desiredMode;
                    });
                }
                $filesStarted = true;
                // The server config is a file bind mount: retain its inode.
                $saved = $this->backupWriteInPlace($path, $body);
                if ($saved) $this->chmodSecret($path);
                if ($saved && $this->saveClients($snapshot['clients'] ?? []) !== false) {
                    if (!$enabled) return true;
                    if ($this->restartWG($body, $switch)) {
                        $this->iptablesWG();
                        if (!$this->sshFailed) return true;
                    }
                }
            } catch (Throwable $error) {
                // A write can fail after publishing its new inode. Compensate
                // both files regardless of which step reported the failure.
            }
            $restored = true;
            foreach ($filesStarted ? $before : [] as $file => $raw) {
                $ok = $raw === null ? (!file_exists($file) || @unlink($file))
                    : ($file === $path ? $this->backupWriteInPlace($file, $raw) : $this->writePrivateKey($file, $raw));
                if (!$ok) $restored = false;
            }
            if ($switch) {
                $modeRestored = $this->withLock('pac', function () use ($modeKey, $desiredMode, $wasAmnezia) {
                    try {
                        $pac = $this->getPacConf();
                        $currentMode = !empty($pac[$modeKey]);
                        // Отказ до rename уже оставил прежний режим.
                        if ($currentMode === $wasAmnezia) return true;
                        if ($currentMode !== $desiredMode) return false;
                        $pac[$modeKey] = (int) $wasAmnezia;
                        try { $this->setPacConf($pac); }
                        catch (Throwable $error) { /* Проверяем опубликованное значение ниже. */ }
                        // Возврат false/исключение после rename не означает,
                        // что откат не опубликован; до rename останется desired.
                        return !empty($this->getPacConf()[$modeKey]) === $wasAmnezia;
                    } catch (Throwable $error) { return false; }
                }, 0, false);
                if (!$modeRestored) $restored = false;
            }
            if ($restored && $filesStarted && $enabled && $before[$path] !== null) {
                $restored = $this->restartWG($before[$path], $switch);
                if ($restored) { $this->iptablesWG(); $restored = !$this->sshFailed; }
            }
            if (!$restored) throw new RuntimeException($this->t('Откат WireGuard не завершён; проверьте прежние файлы и интерфейс', 'WireGuard rollback did not finish; check the previous files and interface'), self::BACKUP_PARTIAL);
            return false;
        }, $service, 120, false);
    }

    // Только данные пользователя. Конфиги Nginx, скрипты, Docker, токен бота
    // и системные SSH-ключи из загруженного JSON не исполняются/не заменяются.
    public function backupExtraPaths(bool $includeRetired = true, ?array $nodes = null): array
    {
        $root = dirname($this->pac);
        $paths = [];
        foreach (['stlsserver.json', 'ss.acl', 'clash.json', 'sing.json', 'v2ray.json',
            'trusttunnel/hosts.toml', 'trusttunnel/rules.toml'] as $name) $paths[$name] = "$root/$name";
        foreach (['index.html', 'loading.css'] as $name) $paths['telemt/decoy/' . $name] = $this->telemtDecoyDir . '/' . $name;
        $paths['webapp/override.html'] = dirname($this->htpasswd) . '/override.html';
        $panel = getenv('PANEL_DIR') ?: "$root/panel";
        foreach (['password-display.key', 'password-display.json', 'initial_password.txt'] as $name) $paths['panel/' . $name] = "$panel/$name";
        $paths += $this->managedNodeBackupPaths($includeRetired, $nodes);
        return $paths;
    }

    private function backupExtraPath(string $name): string
    {
        $path = preg_match('~^nodes/(?:[a-f0-9]{8}/(?:key|key\.pub|endpoint\.json|snapshot\.json)|retired/[a-f0-9]{32}/(?:key|key\.pub))$~D', $name)
            ? $this->managedNodeRoot . '/' . substr($name, 6) : ($this->backupExtraPaths(false)[$name] ?? null);
        if ($path === null && preg_match('~^warp/(?:(?:clients/[a-zA-Z0-9_.-]{1,48}/)?wgcf-(?:account\.toml|profile\.conf)|masque/(?:device\.json|key\.pem|license\.sha256))$~D', $name)) {
            $path = $this->backupWarpRoot . '/' . substr($name, 5);
        }
        if ($path === null || str_contains($name, '..')) throw new RuntimeException($this->t('Посторонний файл в бэкапе', 'A foreign file in the backup'));
        for ($p = $path; $p !== dirname($p); $p = dirname($p)) {
            if (is_link($p)) throw new RuntimeException($this->t('Симлинк в пути бэкапа', 'A symlink in the backup path'));
        }
        return $path;
    }

    public function backupExtraFiles(bool $refresh = true): array
    {
        if ($refresh) $this->managedNodeBackupRefresh();
        $nodes = $this->managedNodes();
        $files = $this->withManagedNodeBackupLocks(array_keys($nodes), LOCK_SH, fn() => $this->backupExtraFilesLocked($nodes));
        return $files + $this->withShadowsocksLock(fn() => $this->backupSimpleTlsFileLocked());
    }

    // Caller holds the short Shadowsocks lock; never nest node locks here.
    private function backupSimpleTlsFileLocked(): array
    {
        $path = $this->backupExtraPath('stlsserver.json');
        if (!file_exists($path)) return [];
        if (!is_file($path) || filesize($path) > 4 * 1024 * 1024 || ($body = file_get_contents($path)) === false) {
            throw new RuntimeException('simple-tls backup configuration unavailable');
        }
        $files = ['stlsserver.json' => base64_encode($body)];
        $this->validateBackupExtraFiles($files);
        return $files;
    }

    private function backupExtraFilesLocked(array $nodes): array
    {
        $this->managedNodeBackupCheck($nodes);
        $paths = $this->backupExtraPaths(true, $nodes);
        unset($paths['stlsserver.json']);
        foreach (['wgcf-account.toml', 'wgcf-profile.conf', 'clients/*/wgcf-account.toml', 'clients/*/wgcf-profile.conf'] as $pattern) {
            foreach (glob($this->backupWarpRoot . '/' . $pattern) ?: [] as $path) {
                $paths['warp/' . substr($path, strlen($this->backupWarpRoot) + 1)] = $path;
            }
        }
        // Устройство WARP MASQUE: без него восстановленный сервер регистрирует
        // новое и занимает ещё одно из пяти мест ключа WARP+. Неподтверждённая
        // регистрация (.pending) в копию не идёт: её откатит warp_masque.sh.
        $masque = $this->backupWarpRoot . '/masque';
        if (is_file("$masque/device.json") && is_file("$masque/key.pem") && !file_exists("$masque/.pending")) {
            foreach (['device.json', 'key.pem', 'license.sha256'] as $name) $paths["warp/masque/$name"] = "$masque/$name";
        }
        $files = [];
        foreach ($paths as $name => $path) {
            $this->backupExtraPath($name);
            if (!file_exists($path)) continue;
            if (!is_file($path) || filesize($path) > 4 * 1024 * 1024 || ($body = file_get_contents($path)) === false) {
                throw new RuntimeException($this->t('Дополнительный файл недоступен для бэкапа', 'An additional file is unavailable for the backup'));
            }
            $files[$name] = base64_encode($body);
        }
        $this->validateBackupExtraFiles($files);
        return $files;
    }

    public function validateBackupExtraFiles(array $files): array
    {
        if (count($files) > 8192) throw new RuntimeException($this->t('Слишком много файлов в бэкапе', 'Too many files in the backup'));
        $decoded = []; $total = 0;
        foreach ($files as $name => $data) {
            if (!is_string($name)) throw new RuntimeException($this->t('Неверное имя файла бэкапа', 'Invalid backup file name'));
            $this->backupExtraPath($name);
            if (!is_string($data) || strlen($data) > 5600000 || ($body = base64_decode($data, true)) === false) {
                throw new RuntimeException($this->t('Некорректный файл бэкапа', 'Invalid backup file'));
            }
            $total += strlen($body);
            if ($total > 16 * 1024 * 1024) throw new RuntimeException($this->t('Слишком большой бэкап', 'The backup is too large'));
            if (str_ends_with($name, '.json') && !is_array(json_decode($body, true, 512, JSON_THROW_ON_ERROR))) {
                throw new RuntimeException($this->t('Некорректный JSON в бэкапе', 'Invalid JSON in the backup'));
            }
            if ($name === 'panel/password-display.key' && strlen($body) !== 32) throw new RuntimeException($this->t('Некорректный ключ хранилища пароля', 'Invalid password vault key'));
            $decoded[$name] = $body;
        }
        if (isset($decoded['warp/masque/device.json']) !== isset($decoded['warp/masque/key.pem'])) {
            throw new RuntimeException($this->t('Неполное устройство WARP MASQUE', 'Incomplete WARP MASQUE device'));
        }
        $retired = [];
        foreach ($decoded as $name => $body) {
            if (!str_starts_with($name, 'nodes/retired/')) continue;
            $retired[dirname($name)] = true;
            if ($body === '' || strlen($body) > 16384 || count($retired) > 256
                || !isset($decoded[dirname($name) . '/key'], $decoded[dirname($name) . '/key.pub'])) {
                throw new RuntimeException($this->t('Неполный или слишком большой архив ключей нод', 'Incomplete or oversized node key archive'));
            }
        }
        // Ключ файлом был только у прежнего формата копии пароля (теперь ключ
        // выводится из токена бота): старому бэкапу без шифротекста он ни к чему.
        if (isset($decoded['panel/password-display.key']) && !isset($decoded['panel/password-display.json'])) {
            throw new RuntimeException($this->t('Неполное хранилище пароля', 'Incomplete password vault'));
        }
        return $decoded;
    }

    public function restoreBackupExtraFiles(array $files): void
    {
        $decoded = $this->validateBackupExtraFiles($files);
        $stls = $decoded['stlsserver.json'] ?? null;
        unset($decoded['stlsserver.json']);
        $ids = [];
        foreach (array_keys($decoded) as $name) {
            if (preg_match('~^nodes/([a-f0-9]{8})/~D', $name, $match)) $ids[] = $match[1];
        }
        $this->withManagedNodeBackupLocks($ids, LOCK_EX, fn() => $this->restoreBackupExtraFilesLocked($decoded));
        // Standalone imports also apply STLS, after releasing every node lock.
        if ($stls !== null && !$this->restoreBackupSimpleTls($stls)) throw new RuntimeException('Could not restore simple-tls');
    }

    private function restoreBackupExtraFilesLocked(array $decoded): void
    {
        $before = [];
        $retiredBefore = [];
        foreach ($decoded as $name => $_) {
            $path = $this->backupExtraPath($name);
            if (str_starts_with($name, 'nodes/retired/')) {
                $directory = dirname($path);
                if (!array_key_exists($directory, $retiredBefore)) {
                    clearstatcache(true, $directory);
                    $retiredBefore[$directory] = is_dir($directory) ? filemtime($directory) : null;
                    if ($retiredBefore[$directory] === false) throw new RuntimeException('Could not read retired node age');
                }
            }
            $before[$path] = file_exists($path) ? [file_get_contents($path), fileperms($path) & 0777] : null;
            if ($before[$path] !== null && !is_string($before[$path][0])) throw new RuntimeException($this->t('Не удалось сохранить прежний файл', 'Could not save the previous file'));
        }
        // Формат бэкапа хранит пары от новых к старым без абсолютных дат.
        // На непустом хосте оставляем локальные пары впереди импортированных.
        $age = time();
        $archive = $this->managedNodeRoot . '/retired';
        if ($retiredBefore && is_dir($archive)) {
            foreach (new DirectoryIterator($archive) as $entry) {
                if (preg_match('~^[a-f0-9]{32}$~D', $entry->getFilename()) && !$entry->isLink() && $entry->isDir()
                    && !array_key_exists($entry->getPathname(), $retiredBefore)) $age = min($age, $entry->getMTime());
            }
        }
        $saveAge = static function (string $directory, int $timestamp): bool {
            if (!@touch($directory, $timestamp)) return false;
            clearstatcache(true, $directory);
            if (filemtime($directory) !== $timestamp) return false;
            $handle = @fopen($directory, 'r');
            if ($handle === false) return false;
            try { return fsync($handle); }
            finally { fclose($handle); }
        };
        $written = [];
        // Восстанавливается подтверждённое устройство MASQUE: отметка
        // незавершённой регистрации на этом сервере иначе откатила бы его.
        $pending = $this->backupWarpRoot . '/masque/.pending';
        $hadPending = isset($decoded['warp/masque/device.json']) && file_exists($pending);
        try {
            if ($hadPending && !@unlink($pending)) throw new RuntimeException($this->t('Не удалось восстановить дополнительный файл', 'Could not restore an additional file'));
            foreach ($decoded as $name => $body) {
                $path = $this->backupExtraPath($name);
                $mode = str_starts_with($name, 'warp/masque/') || str_starts_with($name, 'nodes/') ? 0700 : 0755;
                if (!is_dir(dirname($path)) && !@mkdir(dirname($path), $mode, true)) throw new RuntimeException($this->t('Не удалось создать каталог восстановления', 'Could not create the restore directory'));
                // Запись может отказать уже после rename (например, на fsync).
                $written[] = $path;
                if (!$this->writePrivateKey($path, $body)) throw new RuntimeException($this->t('Не удалось восстановить дополнительный файл', 'Could not restore an additional file'));
                if (str_ends_with($name, '.html') || str_ends_with($name, '.css')) {
                    if (!chmod($path, 0644)) throw new RuntimeException($this->t('Не удалось установить права страницы', 'Could not set the page permissions'));
                }
            }
            foreach ($retiredBefore as $directory => $_) {
                if (!$saveAge($directory, --$age)) throw new RuntimeException('Could not restore retired node age');
            }
        } catch (Throwable $error) {
            $complete = true;
            $changedRetired = [];
            foreach (array_reverse($written) as $path) {
                $directory = dirname($path);
                if (array_key_exists($directory, $retiredBefore)) $changedRetired[$directory] = $retiredBefore[$directory];
                $old = $before[$path];
                if ($old === null) $ok = !file_exists($path) || @unlink($path);
                else $ok = $this->writePrivateKey($path, $old[0]) && @chmod($path, $old[1]);
                if (!$ok) $complete = false;
            }
            foreach ($changedRetired as $directory => $previous) {
                $ok = $previous === null ? !is_dir($directory) || @rmdir($directory)
                    : is_dir($directory) && $saveAge($directory, $previous);
                if (!$ok) $complete = false;
            }
            if ($hadPending) @touch($pending);
            if (!$complete) throw new RuntimeException($this->t('Откат дополнительных файлов не завершён', 'The rollback of additional files did not finish'), previous: $error);
            throw $error;
        }
    }

    private function restoreBackupExtraServices(array $files): array
    {
        $failed = [];
        // В режиме MASQUE туннель WireGuard не поднимается: восстановленные
        // режим и устройство применяет сторож контейнера.
        if ((isset($files['warp/wgcf-profile.conf']) || isset($files['warp/masque/device.json'])) && $this->protocolModuleEnabled('wp') && $this->warpMode() === 'masque') {
            $this->warpKick();
        } elseif (isset($files['warp/wgcf-profile.conf']) && $this->protocolModuleEnabled('wp')) {
            if (!$this->withLock('warp-control', function () {
                if (!$this->warpCommand('wg-quick down /etc/warp/wgcf-profile.conf 2>/dev/null || true')) return false;
                return !empty($this->getPacConf()['warpoff']) || $this->warpCommand('{ sh /warp_fixup.sh && wg-quick up /etc/warp/wgcf-profile.conf; }');
            })) $failed[] = 'WARP';
        }
        if (isset($files['stlsserver.json'])) {
            $decoded = $this->validateBackupExtraFiles(['stlsserver.json' => $files['stlsserver.json']]);
            if (!$this->restoreBackupSimpleTls($decoded['stlsserver.json'])) $failed[] = 'simple-tls';
        }
        return $failed;
    }

    public function restoreBackupXray(array $config): bool
    {
        return $this->withLock('xray', fn() => $this->withXrayApplyLock(fn() => $this->restoreBackupXrayLocked($config)), 30, false) === true;
    }

    protected function restoreBackupXrayLocked(array $config): bool
    {
        // Наборы правил узлов выхода, как и .dat, в копию не входят: разбираем
        // их до сборки конфига, иначе их маршруты появились бы только с cron.
        foreach (array_keys($this->exitNodes()) as $id) $this->exitRefreshRulesets((string) $id);
        $core = $this->xrayCoreSelection();
        if (!$this->protocolModuleEnabled('xr')) {
            return $this->writeXrayJson(json_encode($config, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_THROW_ON_ERROR))
                && $this->writeCoreMarker($core);
        }
        $probe = $this->xrayCoreProbe(true);
        $old = $probe['selection'] ?? '';
        if (empty($probe['ok']) || !isset(self::XRAY_BINARIES[$old])) return false;
        if (!$this->validateXrayConfig($config, self::XRAY_BINARIES[$core])) return false;
        $before = $this->readXrayJson();
        $link = fn($selection) => trim($this->ssh('ln -sf ' . self::XRAY_BINARIES[$selection]
            . ' /usr/local/bin/xray && printf XRAY_LINK_OK', 'xr')) === 'XRAY_LINK_OK';
        if (!$link($core)) return false;
        $this->xrProbe = null;
        if ($this->writeCoreMarker($core) && $this->restartXray($config) && $this->xrayCoreStarted($core)) return true;
        $link($old);
        $this->writeCoreMarker($old);
        if ($before !== '') $this->writeXrayJson($before);
        $this->xrProbe = null;
        $this->ssh('pkill xray; XRAY_LOCATION_ASSET=/logs/geodata xray run -config /xray.json >>/logs/xray_stdout 2>&1 &', 'xr');
        return false;
    }

    private function restoreBackupCertificates(array $pair): bool
    {
        $before = [];
        foreach (['private', 'public'] as $part) {
            $path = $this->protocolCertRoot . '/cert_' . $part;
            $before[$part] = is_file($path) ? file_get_contents($path) : null;
            if ($before[$part] === false) return false;
        }
        foreach (['private', 'public'] as $part) {
            if ($this->writePrivateKey($this->protocolCertRoot . '/cert_' . $part, $pair[$part])) continue;
            foreach ($before as $oldPart => $body) {
                $path = $this->protocolCertRoot . '/cert_' . $oldPart;
                if ($body === null) $ok = !file_exists($path) || @unlink($path);
                else $ok = $this->writePrivateKey($path, $body);
                if (!$ok) error_log('importFile: TLS rollback failed');
            }
            return false;
        }
        return true;
    }

    public function backupHasTelemt(array $pac): bool
    {
        foreach ($pac as $key => $value) {
            if (str_starts_with((string) $key, 'telemt_')) {
                return true;
            }
        }
        return false;
    }

    /**
     * Бэкап, снятый до появления пароля веб-панели (или собранный вручную для
     * теста), не содержит panelpswd — importFile() ниже заменяет pac.json
     * ЦЕЛИКОМ, и такой restore молча стирал бы текущий пароль панели.
     * Panel::authed() требует непустой хеш на самом первом шаге, поэтому
     * пропажа поля разом обнуляла бы ВСЕ открытые сессии панели, а следующий
     * логин с верным паролем отвечал бы «неверный пароль» — пароля-то больше
     * нет. Текущий хеш переживает restore, если сам бэкап не принёс свой.
     */
    public function preservePanelPswd(array $incoming, array $current): array
    {
        if (empty($incoming['panelpswd']) && !empty($current['panelpswd'])) {
            $incoming['panelpswd'] = $current['panelpswd'];
        }

        return $incoming;
    }

    private function withoutPanelGrants(array $pac): array
    {
        unset($pac['adg_panel_epoch'], $pac['adg_browser_epoch']);
        foreach (array_keys((array) ($pac['managed_nodes'] ?? [])) as $id) {
            if (is_array($pac['managed_nodes'][$id])) unset($pac['managed_nodes'][$id]['adguard_panel']);
        }
        return $pac;
    }

    // OpenConnect восстанавливается отдельной согласованной парой ниже;
    // ранняя замена PAC не должна менять пароль раньше passwd-файла.
    // Режимы WG публикуются отдельно под lock нужного интерфейса.
    public function preserveBackupSettings(array $incoming, array $current): array
    {
        $incoming = $this->preservePanelPswd($incoming, $current);
        // Restoring a backup never reinstates invitations or web sessions.
        $incoming = $this->withoutPanelGrants($incoming);
        $incoming['adg_panel_epoch'] = bin2hex(random_bytes(16));
        if (!empty($current['adg_panel_closed'])) $incoming['adg_panel_closed'] = true;
        foreach ([self::OC_USERS, 'ocserv', 'amnezia', 'wg1_amnezia'] as $key) {
            if (array_key_exists($key, $current)) $incoming[$key] = $current[$key];
            else unset($incoming[$key]);
        }
        return $incoming;
    }

    public function import()
    {
        $r = $this->send(
            $this->input['chat'],
            $this->t("@{$this->input['username']} отправьте файл экспорта:", "@{$this->input['username']} send the export file:"),
            $this->input['message_id'],
            reply: $this->t('отправьте файл экспорта:', 'send the export file:'),
        );
        $this->stashReply($r, [
            'start_message'  => $this->input['message_id'],
            'start_callback' => $this->input['callback_id'],
            'callback'       => 'importFile',
            'args'           => [],
        ]);
    }

    protected function backupImportError(string $stage, bool $local, ?Throwable $error = null): bool
    {
        // Сообщение исключения может содержать URL с токеном или секрет из
        // файла. Сохраняем только этап, класс и место ошибки.
        error_log('importFile: stage=' . $stage . ($error ? ' ' . get_class($error)
            . ' at ' . basename($error->getFile()) . ':' . $error->getLine() : ''));
        if (!$local) {
            $this->send($this->input['chat'], '❌ ' . $this->i18n('backup restore interrupted')
                . "\n" . $this->i18n('backup stage ' . $stage) . "\n" . $this->i18n('try again'));
        }
        return false;
    }

    public function importFile($file = false)
    {
        // $file приезжает ПЕРВЫМ аргументом из reply(), а туда всегда идёт
        // текст сообщения пользователя. То есть на промпт «send the export
        // file:» можно было ответить не документом, а строкой — и получить
        // file_get_contents() по произвольному пути или URL (allow_url_fopen в
        // php-контейнере включён, им же ходят upstream() и importIps()).
        // Запрос уходил изнутри docker-сети от root, а валидный JSON оттуда
        // становился конфигом бота. Локальный путь нужен ровно одному
        // вызывающему — selfUpdate() с константой $this->update.
        if (!empty($file) && $file !== $this->update) {
            $file = false;
            return $this->backupImportError('file', false);
        }
        try { return $this->withBackupLock(fn() => $this->restoreBackup($file)); }
        catch (Throwable $error) { return $this->backupImportError('apply', !empty($file), $error); }
        finally { unset($this->wg); }
    }

    private function restoreBackup($file): bool
    {
        if (!empty($file)) {
            $raw = $this->backupReadFile($file);
        } else {
            if (empty($this->input['file_id'])) return $this->backupImportError('file', false);
            $r = $this->request('getFile', ['file_id' => $this->input['file_id']]);
            if (empty($r['ok']) || !is_string($r['result']['file_path'] ?? null)) return $this->backupImportError('file', false);
            // URL содержит токен бота: предупреждение PHP не должно попасть в лог.
            if (($r['result']['file_size'] ?? 0) > self::BACKUP_MAX_BYTES) return $this->backupImportError('file', false);
            $raw = @file_get_contents($this->file . $r['result']['file_path'], false, null, 0, self::BACKUP_MAX_BYTES + 1);
        }
        if (!is_string($raw) || strlen($raw) > self::BACKUP_MAX_BYTES) return $this->backupImportError('file', !empty($file));
        $json = json_decode($raw, true, 128);
        unset($raw);
        if (empty($json) || !is_array($json) || !array_intersect(array_keys($json), self::BACKUP_SECTIONS)) {
            return $this->backupImportError('file', !empty($file));
        } else {
            try { $this->validateBackup($json); }
            catch (Throwable $error) { return $this->backupImportError('file', !empty($file), $error); }
            foreach (['pac', 'wg', 'wg1', 'ad', 'hwid', 'ssl', 'dnstt', 'xray', 'hy', 'hy_users',
                'ss', 'sl', 'cloak', 'ckusers', 'ovpn', 'ipsec', 'xraystats', 'managed_protocols', 'extra_files'] as $key) {
                if (isset($json[$key]) && $json[$key] !== false && !is_array($json[$key])) {
                    return $this->backupImportError('file', !empty($file));
                }
            }
            $ok = true;
            $xrayApplied = true;
            $out = [];
            $failed = function (string $protocol, ?string $detail = null) use (&$ok, &$out): void {
                $ok = false;
                $out[] = '❌ ' . $protocol . ': ' . ($detail ?? $this->i18n('backup protocol failed'));
                error_log('importFile: apply failed: ' . $protocol);
            };
            $restoreWg = function (array $snapshot, ?bool $mode, string $label) use ($failed): void {
                try {
                    if (!$this->restoreBackupWireGuard($snapshot, 0, $mode)) $failed($label);
                } catch (Throwable $error) {
                    if ($error->getCode() !== self::BACKUP_PARTIAL) throw $error;
                    $failed($label, $this->t('Откат не завершён. Проверьте прежние файлы и состояние интерфейса.', 'Rollback did not finish. Check the previous files and interface state.'));
                }
            };
            if (array_key_exists('extra_files', $json)) $this->validateBackupExtraFiles($json['extra_files']);
            if (!empty($json['ssl']) && (!is_string($json['ssl']['public'] ?? null)
                || !is_string($json['ssl']['private'] ?? null)
                || !self::certificatePairValid($json['ssl']['public'], $json['ssl']['private']))) {
                return $this->backupImportError('certificates', !empty($file));
            }
            foreach (['wg', 'wg1'] as $key) {
                if (!empty($json[$key]['clients']) && empty($json[$key]['server']['interface'])) {
                    return $this->backupImportError('file', !empty($file));
                }
            }
            try {
                $telemtLimits = $this->telemtLimitsOf($json['pac'] ?? []);
                if (array_key_exists('telemt_quota', $json)) $this->telemtValidateQuotaState($json['telemt_quota'], $json['pac'] ?? []);
                elseif (array_filter($telemtLimits, static fn($row) => !empty($row['quota']))) return $this->backupImportError('telemt', !empty($file));
            } catch (Throwable $error) { return $this->backupImportError('telemt', !empty($file), $error); }
            if (array_key_exists('tt', $json) && !is_string($json['tt'])) return $this->backupImportError('trusttunnel', !empty($file));
            if (array_key_exists('hy_users', $json)) {
                try { HysteriaUsers::validateSnapshot($json['hy_users']); }
                catch (Throwable $e) { return $this->backupImportError('hysteria', !empty($file), $e); }
            }
            $this->preflightBackupWireguard($json);
            $modulesBefore = $this->protocolModulesSnapshot();
            if (array_key_exists('managed_protocols', $json)) {
                try { $this->importManagedProtocols($json['managed_protocols'], false); }
                catch (Throwable $e) { return $this->backupImportError('protocols', !empty($file), $e); }
            } else {
                try { $this->restoreLegacyModules($json); }
                catch (Throwable $e) { return $this->backupImportError('protocols', !empty($file), $e); }
            }
            if (!$this->waitProtocolModulesApplied($modulesBefore)) {
                foreach ($this->backupModuleFailures ?: ['Protocol modules'] as $service) $failed($service);
            }
            // STLS must wait for certificates and SS/Cloak restore, then use
            // its own stop/write/apply lock in restoreBackupExtraServices.
            if (array_key_exists('extra_files', $json)) $this->restoreBackupExtraFiles(array_diff_key($json['extra_files'], ['stlsserver.json' => true]));
            // certs
            if (!empty($json['ssl'])) {
                $out[] = 'update certificates';
                $this->update($this->input['chat'], $this->input['message_id'], implode("\n", $out));
                if (!$this->restoreBackupCertificates($json['ssl'])) {
                    return $this->backupImportError('certificates', !empty($file));
                }
            }
            // pac
            if (!empty($json['pac'])) {
                $out[] = 'update pac';
                $this->update($this->input['chat'], $this->input['message_id'], implode("\n", $out));
                // Режимы WG сохраняются до восстановления соответствующего
                // интерфейса под его lock; pending может появиться после preflight.
                if ($this->backupHasTelemt($json['pac'])) {
                    $this->telemtQuotaRestore($json['telemt_quota'] ?? null, $json['pac']);
                } else {
                    $this->pacConfUpdate(function (&$current) use ($json) {
                        $current = $this->preserveBackupSettings($json['pac'], $current);
                    });
                }
                $out[] = 'update naiveproxy';
                $this->update($this->input['chat'], $this->input['message_id'], implode("\n", $out));
                if (!$this->restartNaive() && self::naiveReady($json['pac'])) $failed('NaiveProxy');
                $this->pacUpdate('1');
            }
            // wg
            if (!empty($json['wg']['server'])) {
                $out[] = 'update wireguard';
                $this->update($this->input['chat'], $this->input['message_id'], implode("\n", $out));
                $this->wg = 0;
                $restoreWg($json['wg'], isset($json['pac']) ? !empty($json['pac']['amnezia']) : null, 'WireGuard');
            }
            // wg1
            if (!empty($json['wg1']['server'])) {
                $out[] = 'update wireguard 1';
                $this->update($this->input['chat'], $this->input['message_id'], implode("\n", $out));
                $this->wg = 1;
                $restoreWg($json['wg1'], isset($json['pac']) ? !empty($json['pac']['wg1_amnezia']) : null, 'WireGuard 1');
            }
            // выбранный для restore инстанс не должен протекать в остаток
            // запроса (финальный menu(), getInstanceWG-рендеры) — как в
            // shutdownClient/syncPortClients
            unset($this->wg);
            // ad
            if (!empty($json['ad'])) {
                $out[] = 'update adguard';
                $this->update($this->input['chat'], $this->input['message_id'], implode("\n", $out));
                $this->stopAd();
                if ($this->protocolModuleEnabled('ad')) {
                    // AdGuard дописывает YAML при SIGTERM. Ждём завершения,
                    // иначе старый процесс может затереть восстановленный файл.
                    $stopped = $this->ssh('i=0; while test -s /opt/adguardhome/pid && test "$(readlink /proc/$(cat /opt/adguardhome/pid)/exe)" = /opt/adguardhome/AdGuardHome; do '
                        . '[ "$i" -lt 50 ] || exit 1; sleep 0.2; i=$((i+1)); done; printf VPNBOT_AD_STOPPED', 'ad');
                    if (trim($stopped) !== 'VPNBOT_AD_STOPPED') throw new RuntimeException($this->t('Не удалось остановить AdGuard перед восстановлением', 'Could not stop AdGuard before the restore'));
                }
                try {
                    if (!$this->backupWriteInPlace($this->adguard, yaml_emit($json['ad']))) throw new RuntimeException($this->t('Не удалось восстановить AdGuard', 'Could not restore AdGuard'));
                } finally { $this->startAd(); }
            }
            // SS sections may be absent in legacy backups. If both exist,
            // their snapshot and apply share the same Shadowsocks transaction.
            $ssSections = [];
            foreach (['ss', 'sl'] as $section) if (!empty($json[$section])) $ssSections[$section] = $json[$section];
            if ($ssSections) {
                $out[] = 'update shadowsocks';
                $this->update($this->input['chat'], $this->input['message_id'], implode("\n", $out));
                if (!$this->restoreBackupShadowsocks($ssSections)) $failed('Shadowsocks');
            }
            // hwid
            if (array_key_exists('hwid', $json)) {
                $out[] = 'update hwid devices';
                $this->update($this->input['chat'], $this->input['message_id'], implode("\n", $out));
                if (!$this->setHwidStorage($json['hwid'])) throw new RuntimeException($this->t('Не удалось восстановить HWID', 'Could not restore HWID'));
            }
            // xray
            if (!empty($json['xray'])) {
                $out[] = 'update xray';
                $this->update($this->input['chat'], $this->input['message_id'], implode("\n", $out));
                // Сами .dat в бэкап не входят (перекачиваемые по URL из datlist), а
                // восстановленный конфиг может ссылаться на ext:. Докачиваем файлы и
                // только затем проверяем новый конфиг ядром.
                $datNeeded = $this->datSourcesPresent($json['pac'] ?? []);
                if ($datNeeded) {
                    $out[] = 'update dat';
                    $this->update($this->input['chat'], $this->input['message_id'], implode("\n", $out));
                    if ($this->datSync(true)) $failed('DAT');
                }
                if (!$this->restoreBackupXraySnapshot($json['xray'], $json['xraystats'] ?? null)) {
                    $xrayApplied = false;
                    $ok = false;
                    $out[] = '❌ xray: configuration rejected; previous configuration preserved';
                    $this->update($this->input['chat'], $this->input['message_id'], implode("\n", $out));
                } elseif ($datNeeded) {
                    $this->xrayUpdateRules();
                }
                $this->adguardXrayClients();
                $pac = $json['pac'] ?? $this->getPacConf();
                if ($this->setUpstreamDomain(($pac['transport'] ?? '') !== 'Reality' ? 't' : ($pac['reality']['domain'] ?? $json['xray']['inbounds'][0]['streamSettings']['realitySettings']['serverNames'][0] ?? '')) === false) $failed('NGINX Xray');
            }
            // xraystats
            // Индексы счётчиков относятся к пользователям снимка. При отказе
            // Xray остаётся прежний список: его расход менять нельзя.
            if (array_key_exists('xraystats', $json) && empty($json['xray']) && $xrayApplied) {
                $out[] = 'update xray stats';
                $this->update($this->input['chat'], $this->input['message_id'], implode("\n", $out));
                if (!$this->withLock('xray', fn() => $this->withXrayApplyLock(fn() => $this->setXrayStats($json['xraystats'])), 30, false)) $failed('Xray statistics');
            }
            // ocserv
            if (!empty($json['oc'])) {
                $out[] = 'update ocserv';
                $this->update($this->input['chat'], $this->input['message_id'], implode("\n", $out));
                if (array_key_exists('ocu', $json)) {
                    if (!$this->restoreOcPasswordPair($json['ocu'], $json['pac'] ?? $this->getPacConf())) throw new RuntimeException($this->t('Не удалось восстановить пользователей OpenConnect', 'Could not restore OpenConnect users'));
                    $this->syncOcUsers();
                }
                if ($this->restartOcserv($json['oc']) === false) $failed('OpenConnect');
            }
            // hysteria
            if (!empty($json['hy'])) {
                $out[] = 'update hysteria';
                $this->update($this->input['chat'], $this->input['message_id'], implode("\n", $out));
                if (!$this->writePrivateKey($this->hysteriaConf, yaml_emit($json['hy']))) {
                    throw new RuntimeException($this->t('Не удалось восстановить конфигурацию Hysteria', 'Could not restore the Hysteria configuration'));
                }
                if (!$this->restartHysteria()) $failed('Hysteria');
            }
            if (array_key_exists('hy_users', $json)) {
                $this->hysteriaUsersStore()->restore($json['hy_users']);
            } elseif (!empty($json['hy']) && $this->protocolModuleEnabled('hy') && is_file($this->hysteriaUsersRoot . '/users.json')) {
                // Новая ревизия позволяет отличить применение YAML от старого
                // успешного статуса supervisor при импорте старого формата.
                $this->hysteriaUsersStore()->change(static function (&$state) {});
            }
            // trusttunnel
            if (array_key_exists('tt', $json)) {
                $out[] = 'update trusttunnel';
                $this->update($this->input['chat'], $this->input['message_id'], implode("\n", $out));
                $restored = $this->withLock('trusttunnel', function () use ($json) {
                    $paths = $this->ttPaths();
                    if (!is_dir($paths['dir']) && !@mkdir($paths['dir'], 0700, true)) return false;
                    if (!$this->writePrivateKey($paths['cred'], $json['tt'])) return false;
                    return true;
                });
                if (!$restored || $this->restartTt() === false) $failed('TrustTunnel');
            }
            // cloak
            if (!empty($json['cloak'])) {
                $out[] = 'update cloak';
                $this->update($this->input['chat'], $this->input['message_id'], implode("\n", $out));
                $this->withShadowsocksLock(function () use ($json, $failed) {
                    if (!$this->writePrivateKey(
                        '/config/ckserver.json',
                        json_encode($json['cloak'], JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES)
                    )) throw new RuntimeException($this->t('Не удалось восстановить Cloak', 'Could not restore Cloak'));
                    // Восстанавливаем side-store с именами; если в бэкапе нет
                    // (старый формат) — getCloakUsers() забутстрапит из BypassUID.
                    if (!empty($json['ckusers']) && is_array($json['ckusers'])) {
                        if (!$this->writePrivateKey('/config/ckusers.json', json_encode(array_values($json['ckusers']), JSON_THROW_ON_ERROR))) throw new RuntimeException($this->t('Не удалось восстановить пользователей Cloak', 'Could not restore Cloak users'));
                    } else {
                        if (file_exists('/config/ckusers.json') && !unlink('/config/ckusers.json')) throw new RuntimeException($this->t('Не удалось обновить пользователей Cloak', 'Could not update Cloak users'));
                    }
                    if ($this->protocolModuleEnabled('ss')) {
                        $action = !empty($json['cloak']['Enabled']) ? 'restart' : 'stop';
                        if (!$this->controlContainerService('ss', 'ck-server', $action)) $failed('Cloak');
                    }
                });
            }
            // openvpn (PKI + server.conf + ccd, восстановленные из inline-base64)
            if (!empty($json['ovpn']) && is_array($json['ovpn'])) {
                $out[] = 'update openvpn';
                $this->update($this->input['chat'], $this->input['message_id'], implode("\n", $out));
                if ($this->importOvpnPki($json['ovpn'])) {
                    $this->restoreOvpnBackupSections($json);
                    $this->restartOvpnIfEnabled();
                } else {
                    $ok = false;
                    // Причина конкретная: «снимок отвергнут, PKI не тронут» и
                    // «перенос оборвался, PKI смешанный» требуют РАЗНЫХ действий
                    // от админа, а прежний общий текст их не различал.
                    $out[] = '❌ openvpn: ' . ($this->ovpnRestoreError ?: $this->t('снимок не восстановлен', 'snapshot not restored'));
                    if ($this->ovpnRestorePartial) {
                        // Демон продолжает работать со смесью старого и нового
                        // PKI — рестарт заставит его перечитать то, что легло.
                        $this->restartOvpnIfEnabled();
                    }
                    $this->update($this->input['chat'], $this->input['message_id'], implode("\n", $out));
                }
            }
            // ipsec (PSK + CA/server cert + chap-secrets + ikev2-юзеры)
            if (!empty($json['ipsec']) && is_array($json['ipsec'])) {
                $out[] = 'update ipsec';
                $this->update($this->input['chat'], $this->input['message_id'], implode("\n", $out));
                if ($this->importIpsecPki($json['ipsec'])) {
                    if ($this->restartIpsec() === false) $failed('IPsec');
                } else {
                    $ok = false;
                    $out[] = '❌ ipsec: invalid snapshot or write failed';
                    $this->update($this->input['chat'], $this->input['message_id'], implode("\n", $out));
                }
            }
            if (array_key_exists('pac', $json)) {
                $domain = $json['pac']['domain'] ?? '';
                if ($this->setUpstreamDomainOcserv($domain) === false) $failed('NGINX OpenConnect');
                if ($this->setUpstreamDomainNaive($domain) === false) $failed('NGINX NaiveProxy');
            }
            // dnstt
            if (!empty($json['dnstt'])) {
                $out[] = 'update dnstt certificates';
                $this->update($this->input['chat'], $this->input['message_id'], implode("\n", $out));
                $keys = ['server.key' => $json['dnstt']['private'], 'server.pub' => $json['dnstt']['public']];
                if (!empty($json['dnstt']['ssh_private']) && !empty($json['dnstt']['ssh_public'])) {
                    $keys['ssh_host_ed25519_key'] = $json['dnstt']['ssh_private'];
                    $keys['ssh_host_ed25519_key.pub'] = $json['dnstt']['ssh_public'];
                }
                $this->restoreBackupTree($keys, '/config/dnstt');
            }
            if (array_key_exists('pac', $json) || !empty($json['dnstt'])) {
                // Настройки и ключи уже восстановлены. Без reload демон
                // продолжал принимать старый пароль/ключ до перезапуска.
                if (!$this->dnsttStart()) $failed('DNSTT');
            }
            if (isset($json['extra_files'])) {
                foreach ($this->restoreBackupExtraServices($json['extra_files']) as $protocol) $failed($protocol);
            }
            if (isset($json['managed_protocols'])) {
                // Домен PAC и маршруты остальных сервисов уже восстановлены.
                // Иначе валидный SNI из снимка может конфликтовать со СТАРЫМ
                // основным доменом и оборвать восстановление на новом сервере.
                try { $this->syncManagedUpstreams(); }
                catch (Throwable $error) { $failed('NGINX AnyTLS'); }
            }
            foreach ($this->verifyBackupServices($json) as $protocol) $failed($protocol);
            // nginx
            $out[] = $this->i18n('reset nginx');
            $this->update($this->input['chat'], $this->input['message_id'], implode("\n", $out));

            if ($this->cloakNginx() === false) $failed('NGINX');

            $out[] = $this->i18n($ok ? 'backup restore completed' : 'backup restore incomplete');
            $this->update($this->input['chat'], $this->input['message_id'], implode("\n", $out));
            $this->language = $this->getPacConf()['language'] ?: 'en';
        Lang::$en = $this->language === 'en';
            $this->limit    = $this->getPacConf()['limitpage'] ?: 5;
            if (empty($file) && $ok) {
                sleep(3);
                $this->menu();
            }
            return $ok;
        }
    }

    public function dw($u, $t)
    {
        $pac = $this->getPacConf();
        $c   = $this->getXray()['inbounds'][0]['settings']['clients'][$u] ?? null;
        if ($c === null) {
            // Stale callback (client deleted/re-indexed): fall back to the list
            // instead of running on null fields, as userXr() already does.
            $this->xray();

            return;
        }
        if ($t === 'uri') {
            $link = $this->linkXray($u);
            if ($link === '') {
                $this->answer($this->input['callback_id'], $this->i18n('vless encryption unavailable'), true);
                return;
            }
            $this->protocolOutput = true;
            try {
                return $this->sendFile($this->input['chat'], new CURLStringFile(
                    $link, self::safeFileName($c['email'], 'client') . '_uri.txt', 'text/plain'
                ));
            } finally { $this->protocolOutput = false; }
        }
        // subtoken (sidOf), не id: с pac.subtoken_strict=1 findClientBySid()
        // подбором по credential'у не резолвит вообще ничего — subscription()
        // молча отдаёт '', и кнопка "⬇️" присылала пустой файл вместо конфига.
        $_GET['s']              = $this->sidOf($c);
        $_GET['t']              = $t;
        $_SERVER['SERVER_NAME'] = $this->getDomain($pac['transport'] != 'Reality');
        $conf                   = $this->subscription(1);
        if ($conf === '') {
            $error = $this->subscriptionCompatibilityError($this->getXray(), $pac, $t);
            $this->answer($this->input['callback_id'], $this->i18n($error ?: 'vless encryption unavailable'), true);
            return;
        }
        $this->protocolOutput = true;
        try {
            $this->sendFile($this->input['chat'], new CURLStringFile($conf, $c['email'] . ($t == 'cl' ? '_mihomo.yaml' : ($t == 'clj' ? '_mihomo.json' : ($t == 'si' ? '_singbox.json' : '_v2ray.json')))));
        } finally { $this->protocolOutput = false; }
    }

    public function downloadPeer($client)
    {
        $cl      = $client;
        $clients = $this->readClients();
        // Индекс приходит из кнопки, а список мог переиндексироваться
        // (deleteClient) — тот же guard, что у соседей по меню клиента.
        if (empty($clients[$client])) {
            return $this->menu('wg', 0);
        }
        $client = $clients[$client];
        $name   = $this->getName($client['interface']);
        $code   = $this->createConfig($client);
        $this->upload(preg_replace(['~\s+~', '~\(|\)~'], ['_', ''], $name) . ".conf", $code);
        if (!empty(($this->getPacConf()['blinkmenu'] ?? false))) {
            $this->delete($this->input['chat'], $this->input['message_id']);
            $this->input['message_id'] = $this->send($this->input['chat'], '.')['result']['message_id'];
            $this->menu('client', "{$cl}_0");
        }
    }

    public function switchClient($client)
    {
        return $this->withWireguardUpdate(fn() => $this->switchClientLocked($client), null);
    }

    private function switchClientLocked($client)
    {
        $clients = $this->readClients();
        if (empty($clients[$client])) return false;
        $server = $this->readConfig();
        if (empty($server['interface'])) return false;
        $peer = $this->peerIndexByClient($server, $clients[$client]);
        $off = empty($clients[$client]['# off']);
        if ($off) $clients[$client]['# off'] = 1; else unset($clients[$client]['# off']);
        unset($clients[$client]['interface']['## time']);
        if ($peer !== null) {
            $updated = [];
            foreach ($server['peers'][$peer] as $key => $value) {
                $key = str_starts_with($key, '# ') ? substr($key, 2) : $key;
                if ($key === '## time') continue;
                $updated[$off ? '# ' . $key : $key] = $value;
            }
            $server['peers'][$peer] = $updated;
        }
        $ok = $this->applyWgConfig($this->createConfig($server), $clients);
        if (!$ok && isset($this->input['chat'])) $this->wgConfUnavailable($this->t('применение не подтверждено; cron повторит операцию', 'application is unconfirmed; cron will retry the operation'));
        return $ok;
    }

    // ── AmneziaWG: чистые хелперы (без ssh/pac.json, покрыты awg3_test.php) ───

    // Имена ключей [Interface] по версии протокола: 0 — все, 1|2|3 — срез.
    // Спред в const-выражениях не используем: прод крутится на PHP 8.1.
    public static function awgKeyNames(int $ver = 0): array
    {
        switch ($ver) {
            case 1:
                return self::AWG_KEYS_1;
            case 2:
                return self::AWG_KEYS_2;
            case 3:
                return self::AWG_KEYS_3;
            case 4:
                return self::AWG_KEYS_31;
            default:
                return array_merge(self::AWG_KEYS_1, self::AWG_KEYS_2, self::AWG_KEYS_3, self::AWG_KEYS_31);
        }
    }

    // Валидатор range-значений AWG 3.0. Формат ровно тот, что понимает
    // u16_range_from_string() из amneziawg-tools: «N» либо «LO-HI» при HI >= LO.
    // Ни «off», ни пустая строка, ни пробелы вокруг дефиса не принимаются —
    // strtoul() упрётся в первый нецифровой символ и вернёт ошибку, а конфиг с
    // такой строкой не применится целиком. Возвращает '' при успехе.
    public static function validateAwgRange(string $s, int $min = 0, int $max = 65535): string
    {
        if (!preg_match('~^(\d{1,5})(?:-(\d{1,5}))?$~', $s, $m)) {
            return Lang::t('формат: N или LO-HI (только цифры и один дефис, без пробелов)', 'format: N or LO-HI (digits and one hyphen only, no spaces)');
        }
        $lo = (int) $m[1];
        $hi = isset($m[2]) ? (int) $m[2] : $lo;
        if ($hi < $lo) {
            return Lang::t("верхняя граница ($hi) меньше нижней ($lo)", "the upper bound ($hi) is less than the lower one ($lo)");
        }
        if ($lo < $min || $hi > $max) {
            return Lang::t("значения допустимы в пределах $min..$max", "values are allowed within $min..$max");
        }
        return '';
    }

    // [lo, hi] из уже валидной range-строки. Для кросс-проверок между полями.
    public static function awgRangeBounds(string $s): array
    {
        [$lo, $hi] = array_pad(explode('-', $s, 2), 2, null);
        $lo = (int) $lo;
        return [$lo, $hi === null ? $lo : (int) $hi];
    }

    // Версия протокола выводится ИЗ НАБОРА КЛЮЧЕЙ, а не хранится отдельно:
    // так она не может разойтись с тем, что реально лежит в wg0.conf.
    public static function amneziaProtoVer($keys): int
    {
        $keys = is_array($keys) ? $keys : [];
        foreach (self::AWG_KEYS_3 as $k) {
            if (isset($keys[$k]) && $keys[$k] !== '') {
                return 3;
            }
        }
        return isset($keys['I1']) && $keys['I1'] !== '' ? 2 : 1;
    }

    // Инвариант amneziawg-go: при непустом HeaderProtectionKey каждый из S1..S4
    // обязан быть >= 12, иначе setconf отвергает конфиг и интерфейс не встаёт.
    public static function awgHeaderProtectionOk($keys): bool
    {
        $keys = is_array($keys) ? $keys : [];
        if (empty($keys['HeaderProtectionKey'])) {
            return true;
        }
        foreach (['S1', 'S2', 'S3', 'S4'] as $k) {
            if (!isset($keys[$k]) || (int) $keys[$k] < self::AWG_HPK_MIN_S) {
                return false;
            }
        }
        return true;
    }

    // Размеры пакетов всех четырёх типов различны? Проверяются только те S,
    // которые в наборе есть: у 1.x нет S3/S4, и тогда правило вырождается в
    // «S2 !== S1 + 56» — ровно тот инвариант, что был здесь до 3.0.
    public static function awgPacketSizesOk($keys): bool
    {
        $keys  = is_array($keys) ? $keys : [];
        $sizes = [];
        foreach (self::AWG_PACKET_BASE as $k => $base) {
            if (isset($keys[$k]) && $keys[$k] !== '') {
                $sizes[] = $base + (int) $keys[$k];
            }
        }
        return count($sizes) === count(array_unique($sizes));
    }

    // Поднимает S1..S4 до порога header protection, сохраняя инварианты
    // паддингов: S1 !== S2 и различающиеся размеры пакетов на проводе
    // (awgPacketSizesOk) — иначе два типа пакетов становятся одного размера и
    // их легко скоррелировать, а официальный клиент такой набор не сохранит.
    public static function enforceHeaderProtection($keys): array
    {
        $keys = is_array($keys) ? $keys : [];
        $min  = self::AWG_HPK_MIN_S;
        // Верхние границы подбора те же, что у шаблонов 2.0/3.0. Уже заданные
        // значения выше границы не срезаем — они могли прийти из ручной правки.
        $max  = ['S1' => 64, 'S2' => 64, 'S3' => 64, 'S4' => 32];
        foreach (array_keys($max) as $k) {
            $keys[$k] = max($min, (int) ($keys[$k] ?? 0));
        }
        // S1 держим неизменным (он же init-пакет — самый заметный), пере-роллим
        // остальные, пока набор не станет валидным.
        $tries = 0;
        while (($keys['S1'] === $keys['S2'] || !self::awgPacketSizesOk($keys)) && $tries++ < 200) {
            foreach (['S2', 'S3', 'S4'] as $k) {
                $keys[$k] = random_int($min, $max[$k]);
            }
        }
        return $keys;
    }

    // Срез набора до того, что РЕАЛЬНО уезжает в wg0.conf. Чистая функция —
    // единственный источник правды и для серверного конфига
    // (amneziaKeysEffective), и для клиентских подписок: раньше mihomo получал
    // сырой набор из pac.json и мог объявить header protection, которого на
    // сервере нет (старые tools режут весь блок 3.0, S1..S4 < 12 режет HPK).
    // Клиент при этом поднимает v3-устройство и молча не проходит handshake.
    //
    // $supports3: true — 3.0 есть, false — заведомо нет, null — неизвестно.
    // При null НЕ режем: моргнувший ssh не повод выкинуть рабочий блок из
    // конфигов всех клиентов. $supports31 — тот же принцип, но для полей AWG_KEYS_31
    // (независимый порог версии, см. комментарий у AWG_KEYS_31).
    public static function amneziaKeysUsable($keys, ?bool $supports3, ?bool $supports31 = null): array
    {
        if (!is_array($keys)) {
            return [];
        }
        if ($supports3 === false) {
            foreach (self::AWG_KEYS_3 as $j) {
                unset($keys[$j]);
            }
        }
        if ($supports31 === false) {
            foreach (self::AWG_KEYS_31 as $j) {
                unset($keys[$j]);
            }
        }
        if (!self::awgHeaderProtectionOk($keys)) {
            unset($keys['HeaderProtectionKey']);
        }
        // Do not silently rewrite existing client exports: the live server
        // keeps its old value until an explicit, coordinated AWG change.
        return $keys;
    }

    public static function awgRandomTrailersSafe(array $keys): bool
    {
        // Upstream amneziawg-go#186: broad H1-H3 can claim transport data.
        foreach (['H1','H2','H3'] as $name) {
            if (isset($keys[$name]) && count(array_unique(explode('-', (string) $keys[$name]))) > 1) return false;
        }
        return true;
    }

    // Дефолты amneziawg-go (device/constants.go) для полей, которые не заданы:
    // пустое значение = «использовать встроенный», а не «ноль».
    public const AWG3_DEFAULTS = [
        'RekeyAfterTime'   => 120,
        'RejectAfterTime'  => 180,
        'RekeyTimeout'     => 5,
        'KeepaliveTimeout' => 10,
    ];

    // Связки между таймингами, которые amneziawg НЕ проверяет сам: конфиг
    // синтаксически корректен, setconf его принимает, awgApplyGuarded ничего не
    // замечает, а туннель после этого рвётся. Сравниваем худший случай:
    // верх Rekey против низа Reject. Возвращает '' при отсутствии конфликта.
    public static function awgTimingConflict($keys): string
    {
        $keys = is_array($keys) ? $keys : [];
        $val  = function (string $k) use ($keys) {
            $v = (string) ($keys[$k] ?? '');
            return $v === '' ? (string) self::AWG3_DEFAULTS[$k] : $v;
        };
        [, $rekeyHi]  = self::awgRangeBounds($val('RekeyAfterTime'));
        [$rejectLo, ] = self::awgRangeBounds($val('RejectAfterTime'));
        // 1. Сессия обязана жить дольше, чем срок до рекея: иначе пир
        // выбрасывает ключи раньше, чем успевает передоговориться
        // (timers.go: keyRefreshTimeoutSending против keychainExpireTime).
        if ($rejectLo <= $rekeyHi) {
            return Lang::t("RejectAfterTime ($rejectLo) должен быть больше верхней границы RekeyAfterTime ($rekeyHi), ", "RejectAfterTime ($rejectLo) must be greater than the RekeyAfterTime upper bound ($rekeyHi), ")
                . Lang::t('иначе пир отбросит сессию раньше, чем попробует рекей', 'otherwise the peer drops the session before it tries to rekey');
        }
        // 2. Принимающая сторона рекеит через
        // max(0, RejectAfterTime - KeepaliveTimeout.lo - RekeyTimeout.lo)
        // (timers.go: keyRefreshTimeoutReceiving). Если вычитаемое дотягивается
        // до RejectAfterTime, окно схлопывается в ноль и ответчик уходит в
        // handshake на каждом принятом пакете.
        [$kaLo, ]  = self::awgRangeBounds($val('KeepaliveTimeout'));
        [$rktLo, ] = self::awgRangeBounds($val('RekeyTimeout'));
        if ($rejectLo <= $kaLo + $rktLo) {
            return Lang::t("RejectAfterTime ($rejectLo) должен быть больше KeepaliveTimeout ($kaLo) + RekeyTimeout ($rktLo), ", "RejectAfterTime ($rejectLo) must be greater than KeepaliveTimeout ($kaLo) + RekeyTimeout ($rktLo), ")
                . Lang::t('иначе принимающая сторона уходит в рекей на каждом пакете', 'otherwise the receiving side rekeys on every packet');
        }
        return '';
    }

    // H1..H4 в форму 1.x: одиночные ненулевые различающиеся uint32.
    // Диапазон «LO-HI» — это фича 2.0, и клиент/ядро 1.x его не разберёт;
    // без этой конвертации понижение до classic_1 снимало I1-I5 и S3/S4, но
    // оставляло заголовки в 2.0-синтаксисе, т.е. «совместимый со старыми
    // клиентами» профиль на старом клиенте всё равно не поднимался.
    // Берём нижнюю границу: диапазоны генератора не пересекаются, значит и
    // нижние границы различны, а набор меняется минимально.
    public static function awgHeadersToV1($keys): array
    {
        $keys = is_array($keys) ? $keys : [];
        $seen = [];
        foreach (['H1', 'H2', 'H3', 'H4'] as $h) {
            if (!isset($keys[$h]) || $keys[$h] === '') {
                continue;
            }
            $v = self::awgRangeBounds((string) $keys[$h])[0];
            // Ноль запрещён (это «поле не задано»), дубль сделал бы два типа
            // пакетов неразличимыми — в обоих случаях берём свободное значение.
            while ($v <= 0 || in_array($v, $seen, true)) {
                $v = random_int(1, 4_294_967_295);
            }
            $seen[]   = $v;
            $keys[$h] = $v;
        }
        return $keys;
    }

    // Имя параметра в wg0.conf → имя поля в amnezia-wg-option у mihomo.
    // Отдельная карта нужна, потому что для 3.0-полей регистронезависимого
    // совпадения НЕ хватает: декодер mihomo (common/structure) сверяет ключи
    // через EqualFold, предварительно заменив «_» на «-», поэтому «Jc»→«jc»
    // совпадает, а «HeaderProtectionKey»→«header-protection-key» — нет.
    public const MIHOMO_AWG3_KEYS = [
        'HeaderProtectionKey'    => 'header-protection-key',
        'ContentPaddingAddition' => 'content-padding-addition',
        'RekeyAfterTime'         => 'rekey-after-time',
        'RekeyTimeout'           => 'rekey-timeout',
        'RejectAfterTime'        => 'reject-after-time',
        'KeepaliveTimeout'       => 'keepalive-timeout',
        'MaxHandshakeAttempts'   => 'max-handshake-attempts',
    ];
    // AWG 3.1 (mihomo >= v1.19.30, "feat: support AmneziaWG v3.1"). В отличие от полей
    // 3.0 выше — настоящий Go bool (proxy:"random-trailers,omitempty"), не строка/число,
    // поэтому сериализуются отдельной веткой в amneziaKeysForMihomo() (PHP bool, ключ
    // эмитится только при 'on' — аналог omitempty), а не общим циклом с (string)-кастом.
    public const MIHOMO_AWG31_KEYS = [
        'RandomTrailers' => 'random-trailers',
        'DisableCookies' => 'disable-cookies',
    ];

    // Whitelist для mihomo (amnezia-wg-option): отдаём только те поля, которые
    // mihomo действительно знает. Именно whitelist, а не blacklist — иначе
    // следующий добавленный сюда параметр молча утечёт в клиентский YAML.
    //
    // $awg3 включает блок 3.0. Он же требует `version: 3` — только по этому
    // полю mihomo выбирает v3-реализацию устройства (adapter/outbound/
    // wireguard.go: «Only version 3 uses the v3 implementation»).
    // Ключ header-protection-key mihomo принимает в base64 и сам переводит в
    // hex, т.е. значение отдаём ровно тем же, что лежит в wg0.conf.
    //
    // NB: H1-H4 в формате 2.0 («MIN-MAX») mihomo понимает начиная с той же
    // сборки, что и 3.0; на старых сборках h1-h4 разбирались только как uint32.
    public static function amneziaKeysForMihomo($keys, bool $awg3 = false): array
    {
        if (!is_array($keys)) {
            return [];
        }
        $out = [];
        foreach (array_merge(self::AWG_KEYS_1, self::AWG_KEYS_2) as $k) {
            if (isset($keys[$k])) {
                $out[$k] = $keys[$k];
            }
        }
        if (!$awg3 || self::amneziaProtoVer($keys) !== 3) {
            return $out;
        }
        $out['version'] = 3;
        foreach (self::MIHOMO_AWG3_KEYS as $k => $mk) {
            if (isset($keys[$k]) && $keys[$k] !== '') {
                $out[$mk] = (string) $keys[$k];
            }
        }
        foreach (self::MIHOMO_AWG31_KEYS as $k => $mk) {
            if (($keys[$k] ?? '') === 'on') {
                $out[$mk] = true;
            }
        }
        return $out;
    }

    // mihomo объявляет persistent-keepalive целым числом, диапазон «20-30» он не
    // разберёт. Отдаём нижнюю границу — поведение как у клиента, не знающего
    // про рандомизацию.
    public static function keepaliveInt($v): int
    {
        return self::awgRangeBounds((string) $v)[0] ?: 20;
    }

    // Короткий отпечаток секрета для сверки сервер↔клиент без его раскрытия.
    public static function awgKeyFingerprint($v): string
    {
        return '#' . substr(sha1((string) $v), 0, 8);
    }

    // Рендер набора ключей для <code>-блока. HeaderProtectionKey при $mask
    // заменяется отпечатком: полный ключ иначе оседает в истории чата, откуда
    // его уже не отозвать.
    public static function amneziaKeysReport($keys, bool $mask = true, array $only = []): string
    {
        $keys  = is_array($keys) ? $keys : [];
        $lines = [];
        foreach ($keys as $k => $v) {
            if ($only && !in_array($k, $only, true)) {
                continue;
            }
            if ($mask && $k === 'HeaderProtectionKey') {
                $v = 'set ' . self::awgKeyFingerprint($v);
            }
            $lines[] = htmlspecialchars((string) $k, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8')
                . ': ' . htmlspecialchars((string) $v, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
        }
        return implode("\n", $lines);
    }

    public function resetAmnezia($page = 0) {
        $this->switchAmnezia($page, 1);
    }

    // Историческая кнопка «reduce to 1» — теперь просто понижение версии.
    public function reduceAmnezia($page = 0) {
        $this->setAmneziaProto(1, $page);
    }

    public const AMNEZIA_TEMPLATE_LABELS = [
        'standard_2'   => 'Standard 2.0',
        'aggressive_2' => 'Aggressive 2.0',
        'mobile_2'     => 'Mobile 2.0',
        'classic_1'    => 'Classic 1.x',
        'standard_3'   => 'Standard 3.0',
        'aggressive_3' => 'Aggressive 3.0',
        'mobile_3'     => 'Mobile 3.0',
    ];

    public const AMNEZIA_TEMPLATE_DESCS = [
        'standard_2'   => ['ru' => 'балансир: умеренные junk-пакеты и I1–I5', 'en' => 'balanced: moderate junk packets and I1–I5'],
        'aggressive_2' => ['ru' => 'против GFW-класса DPI; +10–15% трафика', 'en' => 'against GFW-class DPI; +10–15% traffic'],
        'mobile_2'     => ['ru' => 'мелкие junk, экономит батарею и трафик', 'en' => 'small junk, saves battery and traffic'],
        'classic_1'    => ['ru' => 'без 2.0-полей, совместимо со старыми клиентами', 'en' => 'no 2.0 fields, compatible with old clients'],
        'standard_3'   => ['ru' => 'балансир + header protection и рандомные тайминги', 'en' => 'balanced + header protection and random timings'],
        'aggressive_3' => ['ru' => 'максимум обфускации 3.0; +10–15% трафика', 'en' => 'maximum 3.0 obfuscation; +10–15% traffic'],
        'mobile_3'     => ['ru' => 'мелкие junk, редкий рекей — экономит батарею', 'en' => 'small junk, rare rekey; saves battery'],
    ];

    public function applyAmneziaTemplate($template, $page = 0)
    {
        return $this->withWireguardUpdate(fn() => $this->applyAmneziaTemplateLocked($template, $page), null);
    }

    private function applyAmneziaTemplateLocked($template, $page = 0)
    {
        if (!isset(self::AMNEZIA_TEMPLATE_LABELS[$template])) {
            return $this->menu('wg', $page);
        }
        $is3 = substr($template, -2) === '_3';
        if ($is3 && $this->awgSupports3() !== true) {
            $this->answer($this->input['callback_id'] ?? null, $this->awg3UnsupportedText(), true);
            return $this->menu('wg', $page);
        }
        $prefix = $this->getInstanceWG(1);
        $mutate = function () use ($template, $prefix, $is3) {
            $this->pacConfUpdate(function (&$c) use ($template, $prefix, $is3) {
                $c[$prefix . 'amnezia']      = 1;
                $c[$prefix . 'amnezia_tpl']  = $template;
                $c[$prefix . 'amnezia_keys'] = $this->generateAmneziaKeys(
                    $template,
                    $is3 ? fn() => $this->genHeaderProtectionKey() : null
                );
                // Сбросить ротационный таймер: ручная смена шаблона = свежая генерация
                // I1-I5, нет смысла дёргать ротацию повторно через несколько часов.
                if ((int) ($c[$prefix . 'amnezia_rotation_period'] ?? 0) > 0) {
                    $c[$prefix . 'amnezia_last_rotation'] = time();
                }
                // Диапазонный PersistentKeepalive — фича 3.0: на 2.0-шаблоне он не
                // разберётся, а раньше оставался от прежнего набора и уезжал в
                // клиентские конфиги. Так же поступают setAmneziaProto и resetAwg3.
                if (!$is3) {
                    unset($c[$prefix . 'amnezia_keepalive']);
                }
            });
        };
        // 3.0-шаблон способен получить отказ от setconf (например, если в
        // контейнере вдруг оказались старые tools) — применяем с откатом.
        if ($is3) {
            $this->awgApplyGuarded($page, $mutate);
            return;
        }
        $mutate();
        $this->switchAmnezia($page, false, false, 1);
    }

    public function amneziaTemplates($page = 0)
    {
        $prefix  = $this->getInstanceWG(1);
        $current = $this->getPacConf()[$prefix . 'amnezia_tpl'] ?? '';
        // Профили показываем только для текущей версии протокола: смена версии
        // живёт в отдельном меню (amneziaProtoMenu), иначе список из семи
        // пунктов не даёт понять, что именно переключаешь.
        $ver     = self::amneziaProtoVer($this->getPacConf()[$prefix . 'amnezia_keys'] ?? []);
        $labels  = [];
        foreach (self::amneziaTemplateList($ver) as $k) {
            $labels[$k] = self::AMNEZIA_TEMPLATE_LABELS[$k];
        }
        $descs = self::AMNEZIA_TEMPLATE_DESCS;
        $inst = $this->wgNum();
        $text = ['Menu -> Wireguard -> amnezia templates (' . $this->amneziaProtoLabel($ver) . ')', ''];
        foreach ($labels as $k => $label) {
            $mark = ($k === $current) ? '• ' : '';
            $text[] = "$mark<b>$label</b> — " . $descs[$k][$this->language === 'en' ? 'en' : 'ru'];
        }
        $data = [];
        foreach ($labels as $k => $label) {
            $data[] = [[
                'text'          => (($k === $current) ? '• ' : '') . $label,
                'callback_data' => "/amneziaTemplate $k $inst $page",
            ]];
        }
        $data[] = [[
            'text'          => $this->i18n('back'),
            'callback_data' => "/menu wg $inst $page",
        ]];
        $this->update(
            $this->input['chat'],
            $this->input['message_id'],
            implode("\n", $text),
            $data,
        );
    }

    // ── Версия протокола: выбор и применение ─────────────────────────────────

    public function amneziaProtoLabel(int $ver): string
    {
        return [1 => '1.x', 2 => '2.0', 3 => '3.0'][$ver] ?? '1.x';
    }

    public function awg3UnsupportedText(): string
    {
        $v = $this->awgToolsVersion();
        return $this->t('AWG 3.0 недоступен: в контейнере amneziawg-tools ', 'AWG 3.0 is unavailable: amneziawg-tools in the container ')
            . ($v === null ? $this->t('(версия неизвестна, контейнер не отвечает)', '(version unknown, the container does not respond)') : $v)
            . $this->t(', нужна ≥ 3.0 — пересоберите wg-контейнер', ', ≥ 3.0 is needed; rebuild the wg container');
    }

    public function awg31UnsupportedText(): string
    {
        $v = $this->awgToolsVersion();
        return $this->t('AWG 3.1 недоступен: в контейнере amneziawg-tools ', 'AWG 3.1 is unavailable: amneziawg-tools in the container ')
            . ($v === null ? $this->t('(версия неизвестна, контейнер не отвечает)', '(version unknown, the container does not respond)') : $v)
            . $this->t(', нужна ≥ 3.1 — пересоберите wg-контейнер', ', ≥ 3.1 is needed; rebuild the wg container');
    }

    public function amneziaProtoMenu($page = 0)
    {
        $prefix = $this->getInstanceWG(1);
        $keys   = $this->getPacConf()[$prefix . 'amnezia_keys'] ?? [];
        $cur    = self::amneziaProtoVer($keys);
        $sup3   = $this->awgSupports3();
        $inst   = $this->wgNum();

        $text = [
            $this->t('Menu -> Wireguard -> версия протокола amnezia', 'Menu -> Wireguard -> amnezia protocol version'),
            '',
            $this->t('<b>1.x</b> — Jc/Jmin/Jmax, S1-S2, H1-H4. Понимают все клиенты.', '<b>1.x</b>: Jc/Jmin/Jmax, S1-S2, H1-H4. All clients understand it.'),
            $this->t('<b>2.0</b> — плюс S3/S4 и сигнатурные пакеты I1-I5.', '<b>2.0</b>: plus S3/S4 and the I1-I5 signature packets.'),
            $this->t('<b>3.0</b> — плюс header protection, рандомизированный паддинг и тайминги.', '<b>3.0</b>: plus header protection, randomised padding and timings.'),
            '',
            $this->t('Смена версии не перегенерирует уже подобранные поля — только добавляет или снимает те, которых нет в целевой версии.', 'Changing the version does not regenerate fields already chosen; it only adds or removes those absent in the target version.'),
            '',
            $this->t('⚠️ После смены версии клиентам нужно перекачать конфиги, иначе связь пропадёт.', '⚠️ After changing the version clients must download their configs again, otherwise the connection is lost.'),
        ];
        if ($sup3 !== true) {
            $text[] = '';
            $text[] = '⛔ ' . htmlspecialchars($this->awg3UnsupportedText(), ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
        }

        $data = [];
        foreach ([1, 2, 3] as $v) {
            $mark  = $v === $cur ? '• ' : '';
            $badge = ($v === 3 && $sup3 !== true) ? ' ⛔' : '';
            $data[] = [[
                'text'          => $mark . $this->amneziaProtoLabel($v) . $badge,
                'callback_data' => "/setAmneziaProto $v $inst $page",
            ]];
        }
        $data[] = [[
            'text'          => $this->i18n('back'),
            'callback_data' => "/menu wg $inst $page",
        ]];
        $this->update(
            $this->input['chat'],
            $this->input['message_id'],
            implode("\n", $text),
            $data,
        );
    }

    // Понижение/повышение версии БЕЗ перегенерации всего набора: S1/S2/H1-H4/Jc
    // и PSK сохраняются, меняется только состав полей. Полная перегенерация —
    // это отдельное действие (templates / reset obf-keys).
    public function setAmneziaProto($ver, $page = 0)
    {
        return $this->withWireguardUpdate(fn() => $this->setAmneziaProtoLocked($ver, $page), null);
    }

    private function setAmneziaProtoLocked($ver, $page = 0)
    {
        $ver    = (int) $ver;
        $prefix = $this->getInstanceWG(1);
        if (!in_array($ver, [1, 2, 3], true)) {
            return $this->menu('wg', $page);
        }
        if ($ver === 3 && $this->awgSupports3() !== true) {
            $this->answer($this->input['callback_id'] ?? null, $this->awg3UnsupportedText(), true);
            return $this->menu('wg', $page);
        }

        $mutate = function () use ($ver, $prefix) {
            $this->pacConfUpdate(function (&$c) use ($ver, $prefix) {
                $tpl = $c[$prefix . 'amnezia_tpl'] ?? 'standard_2';
                // Профиль внутри версии сохраняем (standard→standard и т.д.).
                $tpl_new = self::awgTemplateForVer($tpl, $ver);
                $keys = is_array($c[$prefix . 'amnezia_keys'] ?? null) ? $c[$prefix . 'amnezia_keys'] : [];
                $keys = $this->amneziaKeysForVersion($keys, $ver, $tpl_new, fn() => $this->genHeaderProtectionKey());
                if ($ver < 3) unset($c[$prefix . 'amnezia_keepalive']);

                $c[$prefix . 'amnezia']      = 1;
                $c[$prefix . 'amnezia_tpl']  = $tpl_new;
                $c[$prefix . 'amnezia_keys'] = $keys;
            });
        };

        if ($ver === 3) {
            $this->awgApplyGuarded($page, $mutate);
            return;
        }
        $mutate();
        $this->switchAmnezia($page, false, false, 1);
    }

    /** Shared version migration for the full bot and managed nodes. */
    public function amneziaKeysForVersion(array $keys, int $ver, string $template, ?callable $hpk = null): array
    {
        if (!in_array($ver,[1,2,3],true)) throw new InvalidArgumentException('Invalid Amnezia version');
        $template=self::awgTemplateForVer($template,$ver);
        if (!$keys) $keys=$this->generateAmneziaKeys($template,$hpk);
        for ($v=$ver+1;$v<=3;$v++) foreach(self::awgKeyNames($v) as $name) unset($keys[$name]);
        if ($ver<3) foreach(self::AWG_KEYS_31 as $name) unset($keys[$name]);
        if ($ver>=2) {
            $fresh=$this->generateAmneziaKeys($template,$hpk);
            for ($v=2;$v<=$ver;$v++) foreach(self::awgKeyNames($v) as $name) {
                if (!isset($keys[$name]) && isset($fresh[$name])) $keys[$name]=$fresh[$name];
            }
        }
        if ($ver===3) $keys=self::enforceHeaderProtection($keys);
        if ($ver===1) $keys=self::awgHeadersToV1($keys);
        return $keys;
    }

    // ── Подменю AWG 3.0 ──────────────────────────────────────────────────────

    public function awg3Menu($page = 0)
    {
        $prefix = $this->getInstanceWG(1);
        $c      = $this->getPacConf();
        $keys   = is_array($c[$prefix . 'amnezia_keys'] ?? null) ? $c[$prefix . 'amnezia_keys'] : [];
        $sup3   = $this->awgSupports3();
        $sup31  = $this->awgSupports31();
        $inst   = $this->wgNum();
        $hpk    = (string) ($keys['HeaderProtectionKey'] ?? '');
        $rt     = (string) ($keys['RandomTrailers'] ?? 'off');
        $dc     = (string) ($keys['DisableCookies'] ?? 'off');

        $text = [
            'Menu -> Wireguard -> AWG 3.0',
            '',
            'amneziawg-tools: <code>' . htmlspecialchars((string) ($this->awgToolsVersion() ?? '—'), ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8') . '</code>'
                . ($sup3 === true ? ' ✅' : ($sup3 === false ? $this->t(' ⛔ нужна ≥ 3.0', ' ⛔ ≥ 3.0 is needed') : $this->t(' ⚠️ контейнер не отвечает', ' ⚠️ the container does not respond'))),
            'AWG 3.1 (RandomTrailers/DisableCookies): '
                . ($sup31 === true ? '✅' : ($sup31 === false ? $this->t('⛔ нужна ≥ 3.1', '⛔ ≥ 3.1 is needed') : $this->t('⚠️ контейнер не отвечает', '⚠️ the container does not respond'))),
            '',
        ];
        $report = self::amneziaKeysReport($keys, true, array_merge(self::AWG_KEYS_3, self::AWG_KEYS_31));
        $text[] = '<code>' . ($report !== '' ? $report : $this->t('3.0-поля не заданы', '3.0 fields are not set')) . '</code>';
        $text[] = 'PersistentKeepalive: <code>' . htmlspecialchars((string) $this->awgKeepalive(), ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8') . '</code>';
        $text[] = '';
        $text[] = $this->t('⚠️ Любое изменение здесь ломает уже розданные конфиги: клиентам нужно перекачать их заново. Header protection дополнительно требует S1–S4 ≥ ', '⚠️ Any change here breaks the configs already handed out: clients must download them again. Header protection also requires S1–S4 ≥ ') . self::AWG_HPK_MIN_S . '.';
        if ($dc === 'on') $text[] = $this->t('⚠️ DisableCookies отключает штатную защиту WireGuard от флуда подключений.', '⚠️ DisableCookies disables the standard WireGuard protection against connection floods.');
        if ($rt === 'on' && !self::awgRandomTrailersSafe($keys)) $text[] = $this->t(
            '⚠️ RandomTrailers с диапазонами H1–H3 может терять пакеты. Отключите RandomTrailers этой кнопкой и обновите конфиги клиентов. До применения экспорты сохраняют текущий режим сервера.',
            '⚠️ RandomTrailers with H1–H3 ranges can drop packets. Disable it here and refresh client profiles. Until applied, exports preserve the current server mode.');

        $data = [
            [
                [
                    'text'          => 'HPK: ' . ($hpk !== '' ? 'on ' . self::awgKeyFingerprint($hpk) : 'off'),
                    'callback_data' => "/awg3hpk $inst $page",
                ],
            ],
        ];
        if ($hpk !== '') {
            $data[] = [
                ['text' => 'regen HPK', 'callback_data' => "/awg3hpkGen $inst $page"],
                ['text' => 'show HPK',  'callback_data' => "/awg3hpkShow $inst $page"],
            ];
        }
        $data[] = [
            ['text' => 'RandomTrailers: ' . $rt, 'callback_data' => "/awg3rt $inst $page"],
            ['text' => 'DisableCookies: ' . $dc,  'callback_data' => "/awg3dc $inst $page"],
        ];
        $row = [];
        foreach (self::AWG3_FIELDS as $tok => [$key, , , ]) {
            $cur = $key === 'PersistentKeepalive'
                ? (string) $this->awgKeepalive()
                : (string) ($keys[$key] ?? '—');
            $row[] = [
                'text'          => self::awg3FieldShort($tok) . ": $cur",
                'callback_data' => "/awg3set $tok $inst $page",
            ];
            if (count($row) === 2) {
                $data[] = $row;
                $row = [];
            }
        }
        if ($row) {
            $data[] = $row;
        }
        $data[] = [
            [
                'text'          => 'mihomo awg3: ' . (!empty($c['mihomo_awg3']) ? 'on' : 'off'),
                'callback_data' => "/awg3mihomo $inst $page",
            ],
        ];
        $data[] = [
            ['text' => 'reset 3.0',     'callback_data' => "/awg3reset $inst $page"],
            ['text' => 'recheck tools', 'callback_data' => "/awgVerRefresh $inst $page"],
        ];
        $data[] = $this->menuHelpButton('awg', $inst . '_' . $page);
        $data[] = [[
            'text'          => $this->i18n('back'),
            'callback_data' => "/menu wg $inst $page",
        ]];

        $this->update(
            $this->input['chat'],
            $this->input['message_id'],
            implode("\n", $text),
            $data,
        );
    }

    // Короткая подпись кнопки: полное имя параметра не влезает в ряд из двух.
    public static function awg3FieldShort(string $tok): string
    {
        return [
            'pad' => 'padding',
            'rka' => 'rekey after',
            'rkt' => 'rekey timeout',
            'rja' => 'reject after',
            'kat' => 'keepalive t/o',
            'mha' => 'max handshake',
            'pka' => 'keepalive',
        ][$tok] ?? $tok;
    }

    public function toggleHeaderProtection($page = 0)
    {
        return $this->withWireguardUpdate(fn() => $this->toggleHeaderProtectionLocked($page), null);
    }

    private function toggleHeaderProtectionLocked($page = 0)
    {
        $prefix = $this->getInstanceWG(1);
        $c      = $this->getPacConf();
        $keys   = is_array($c[$prefix . 'amnezia_keys'] ?? null) ? $c[$prefix . 'amnezia_keys'] : [];

        if (!empty($keys['HeaderProtectionKey'])) {
            $this->awgApplyGuarded($page, function () use ($prefix) {
                $this->pacConfUpdate(function (&$c) use ($prefix) { unset($c[$prefix . 'amnezia_keys']['HeaderProtectionKey']); });
            });
            return;
        }

        if ($this->awgSupports3() !== true) {
            $this->answer($this->input['callback_id'] ?? null, $this->awg3UnsupportedText(), true);
            return $this->menu('wg', $page);
        }
        // Header protection использует S1-S4 как nonce, поэтому паддинги обязаны
        // существовать и быть >= 12. Набор 1.x их просто не содержит.
        if (!isset($keys['S3'], $keys['S4'])) {
            $this->answer($this->input['callback_id'] ?? null, $this->t('сначала переключитесь на 2.0 или 3.0: header protection требует S3/S4', 'switch to 2.0 or 3.0 first: header protection needs S3/S4'), true);
            return $this->menu('wg', $page);
        }

        $this->awgApplyGuarded($page, function () use ($prefix) {
            $this->pacConfUpdate(function (&$c) use ($prefix) {
                $keys = is_array($c[$prefix . 'amnezia_keys'] ?? null) ? $c[$prefix . 'amnezia_keys'] : [];
                $keys['HeaderProtectionKey'] = $this->genHeaderProtectionKey();
                $c[$prefix . 'amnezia_keys'] = self::enforceHeaderProtection($keys);
            });
        });
    }

    public function regenHeaderProtection($page = 0)
    {
        return $this->withWireguardUpdate(fn() => $this->regenHeaderProtectionLocked($page), null);
    }

    private function regenHeaderProtectionLocked($page = 0)
    {
        $prefix = $this->getInstanceWG(1);
        $c      = $this->getPacConf();
        if (empty($c[$prefix . 'amnezia_keys']['HeaderProtectionKey'])) {
            return $this->menu('wg', $page);
        }
        $this->awgApplyGuarded($page, function () use ($prefix) {
            $this->pacConfUpdate(function (&$c) use ($prefix) {
                $c[$prefix . 'amnezia_keys']['HeaderProtectionKey'] = $this->genHeaderProtectionKey();
            });
        });
    }

    // Полное значение отдаём alert-попапом: в отличие от сообщения, оно не
    // остаётся в истории чата и не попадает в бэкапы переписки.
    public function showHeaderProtectionKey($page = 0)
    {
        $prefix = $this->getInstanceWG(1);
        $hpk    = (string) ($this->getPacConf()[$prefix . 'amnezia_keys']['HeaderProtectionKey'] ?? '');
        $this->answer($this->input['callback_id'] ?? null, $hpk !== '' ? $hpk : $this->t('HeaderProtectionKey не задан', 'HeaderProtectionKey is not set'), true);
    }

    public function resetAwg3($page = 0)
    {
        return $this->withWireguardUpdate(fn() => $this->resetAwg3Locked($page), null);
    }

    private function resetAwg3Locked($page = 0)
    {
        $prefix = $this->getInstanceWG(1);
        $this->awgApplyGuarded($page, function () use ($prefix) {
            $this->pacConfUpdate(function (&$c) use ($prefix) {
                foreach (array_merge(self::AWG_KEYS_3, self::AWG_KEYS_31) as $k) {
                    unset($c[$prefix . 'amnezia_keys'][$k]);
                }
                unset($c[$prefix . 'amnezia_keepalive']);
                // Шаблон обязан уехать вместе с полями: AWG_ROTATE_KEYS содержит
                // весь блок 3.0, и ближайшая ротация по оставшемуся *_3 вернула бы
                // его целиком — вместе с header protection, который только что сняли.
                $tpl = (string) ($c[$prefix . 'amnezia_tpl'] ?? '');
                if (substr($tpl, -2) === '_3') {
                    $c[$prefix . 'amnezia_tpl'] = self::awgTemplateForVer($tpl, 2);
                }
            });
        });
    }

    // RandomTrailers/DisableCookies (AWG 3.1) — простые on/off без предусловий вида S1-S4
    // (в отличие от HeaderProtectionKey они не завязаны на паддинги). Доступны только на
    // шаблоне 3.0 (живут в том же amnezia_keys, что и остальные AWG_KEYS_3/31-поля) и при
    // подтверждённой поддержке tools >= 3.1 — при включении. Выключить (заведомо безопасная
    // операция) можно всегда, чтобы застрявший на 'on' тумблер не блокировался версией.
    public function toggleRandomTrailers($page = 0)
    {
        return $this->withWireguardUpdate(fn() => $this->toggleRandomTrailersLocked($page), null);
    }

    private function toggleRandomTrailersLocked($page = 0)
    {
        $prefix = $this->getInstanceWG(1);
        $c      = $this->getPacConf();
        $keys   = is_array($c[$prefix . 'amnezia_keys'] ?? null) ? $c[$prefix . 'amnezia_keys'] : [];
        $cur    = (string) ($keys['RandomTrailers'] ?? 'off');

        if ($cur !== 'on' && $this->awgSupports31() !== true) {
            $this->answer($this->input['callback_id'] ?? null, $this->awg31UnsupportedText(), true);
            return $this->menu('wg', $page);
        }
        if ($cur !== 'on' && self::amneziaProtoVer($keys) !== 3) {
            $this->answer($this->input['callback_id'] ?? null, $this->t('сначала переключитесь на шаблон 3.0', 'switch to a 3.0 template first'), true);
            return $this->menu('wg', $page);
        }

        if ($cur !== 'on' && !self::awgRandomTrailersSafe($keys)) {
            $this->answer($this->input['callback_id'] ?? null, $this->t('RandomTrailers требует фиксированных H1–H3: диапазоны вызывают потерю пакетов в текущем AWG.', 'RandomTrailers requires fixed H1–H3: ranges cause packet loss in the current AWG.'), true);
            return $this->menu('wg', $page);
        }

        $this->awgApplyGuarded($page, function () use ($prefix, $cur) {
            $this->pacConfUpdate(function (&$c) use ($prefix, $cur) {
                $keys = is_array($c[$prefix . 'amnezia_keys'] ?? null) ? $c[$prefix . 'amnezia_keys'] : [];
                $keys['RandomTrailers'] = $cur === 'on' ? 'off' : 'on';
                $c[$prefix . 'amnezia_keys'] = $keys;
            });
        });
    }

    public function toggleDisableCookies($page = 0)
    {
        return $this->withWireguardUpdate(fn() => $this->toggleDisableCookiesLocked($page), null);
    }

    private function toggleDisableCookiesLocked($page = 0)
    {
        $prefix = $this->getInstanceWG(1);
        $c      = $this->getPacConf();
        $keys   = is_array($c[$prefix . 'amnezia_keys'] ?? null) ? $c[$prefix . 'amnezia_keys'] : [];
        $cur    = (string) ($keys['DisableCookies'] ?? 'off');

        if ($cur !== 'on' && $this->awgSupports31() !== true) {
            $this->answer($this->input['callback_id'] ?? null, $this->awg31UnsupportedText(), true);
            return $this->menu('wg', $page);
        }
        if ($cur !== 'on' && self::amneziaProtoVer($keys) !== 3) {
            $this->answer($this->input['callback_id'] ?? null, $this->t('сначала переключитесь на шаблон 3.0', 'switch to a 3.0 template first'), true);
            return $this->menu('wg', $page);
        }

        $this->awgApplyGuarded($page, function () use ($prefix, $cur) {
            $this->pacConfUpdate(function (&$c) use ($prefix, $cur) {
                $keys = is_array($c[$prefix . 'amnezia_keys'] ?? null) ? $c[$prefix . 'amnezia_keys'] : [];
                $keys['DisableCookies'] = $cur === 'on' ? 'off' : 'on';
                $c[$prefix . 'amnezia_keys'] = $keys;
            });
        });
    }

    // Перечитать версию amneziawg-tools в обход часового кеша в pac.json.
    // Нужна после пересборки wg-контейнера: до неё меню продолжало бы показывать
    // старую версию и держать 3.0 заблокированным.
    public function awgVerRefresh($page = 0)
    {
        $v = $this->awgToolsVersion(true);
        // Тост обязателен. awg3Menu() перерисовывает то же самое сообщение, а
        // когда версия не изменилась (обычный случай), текст и клавиатура выходят
        // байт-в-байт прежними — Telegram на такой editMessageText отвечает
        // «message is not modified» и не меняет ничего. Без этой строки кнопка
        // выглядела полностью мёртвой, хотя ssh-опрос выполнялся. Тот же приём,
        // что в refreshMain().
        if (!empty($this->input['callback_id'])) {
            $this->answer(
                $this->input['callback_id'],
                '🔄 amneziawg-tools: ' . ($v ?? $this->t('контейнер не отвечает', 'the container does not respond')),
            );
        }
        $this->awg3Menu($page);
    }

    // Флаг глобальный, а не по инстансу: он описывает возможности КЛИЕНТСКОГО
    // приложения подписчика, а не сервера. Рестарт wg не нужен — меняется
    // только то, что отдаётся в подписке.
    public function toggleMihomoAwg3($page = 0)
    {
        $this->pacConfUpdate(function (&$c) {
            $c['mihomo_awg3'] = empty($c['mihomo_awg3']) ? 1 : 0;
        });
        $this->awg3Menu($page);
    }

    public function setAwg3Field($tok, $page = 0)
    {
        if (!isset(self::AWG3_FIELDS[$tok])) {
            return $this->menu('wg', $page);
        }
        [$key, $min, $max, $hint] = self::AWG3_FIELDS[$tok];
        $hint = $hint[$this->language === 'en' ? 'en' : 'ru'];
        $prefix = $this->getInstanceWG(1);
        $cur    = $key === 'PersistentKeepalive'
            ? (string) $this->awgKeepalive()
            : (string) ($this->getPacConf()[$prefix . 'amnezia_keys'][$key] ?? '—');

        $r = $this->send(
            $this->input['chat'],
            $this->t("@{$this->input['username']} введите значение <b>$key</b> — число или диапазон <code>LO-HI</code> ($hint).\n\n", "@{$this->input['username']} enter the <b>$key</b> value: a number or a range <code>LO-HI</code> ($hint).\n\n")
            . $this->t("Текущее: <code>", "Current: <code>") . htmlspecialchars($cur, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8') . "</code>\n"
            . $this->t("Допустимо: $min..$max. <code>0</code> — вернуть значение по умолчанию.\n\n", "Allowed: $min..$max. <code>0</code> restores the default.\n\n")
            . $this->t("Диапазон пишется без пробелов (<code>110-130</code>): amneziawg отвергает конфиг целиком при любой ошибке разбора.\n", "Write the range without spaces (<code>110-130</code>): amneziawg rejects the whole config on any parse error.\n")
            . $this->t("После изменения клиентам нужно перекачать конфиги.", "After a change clients must download their configs again."),
            $this->input['message_id'],
            reply: $this->t("введите $key", "enter $key"),
        );
        $this->stashReply($r, [
            'start_message'  => $this->input['message_id'],
            'start_callback' => $this->input['callback_id'],
            'callback'       => 'setAwg3FieldValue',
            // Инстанс в stash — ответ придёт отдельным запросом, где глобальный
            // wg_instance мог смениться другим меню/устройством.
            'args'           => [$tok, $this->wgNum(), $page],
        ]);
    }

    // Легаси-защиты вида «args=[$page]» здесь нет намеренно: колбэк новый,
    // стэшей старого формата для него не существует.
    public function setAwg3FieldValue($text, $tok = '', $inst = 0, $page = 0)
    {
        return $this->withWireguardUpdate(fn() => $this->setAwg3FieldValueLocked($text, $tok, $inst, $page), in_array((int) $inst, [0, 1], true) ? ((int) $inst ? 'wg1' : 'wg') : null);
    }

    private function setAwg3FieldValueLocked($text, $tok = '', $inst = 0, $page = 0)
    {
        if (!isset(self::AWG3_FIELDS[$tok])) {
            return $this->menu('wg', $page);
        }
        $this->selectWG($inst);
        [$key, $min, $max] = self::AWG3_FIELDS[$tok];
        $prefix = $this->getInstanceWG(1);
        $text   = trim($text);

        $reset = $text === '' || $text === '0' || $text === '-';

        if (!$reset && ($err = self::validateAwgRange($text, $min, $max))) {
            $this->update($this->input['chat'], $this->input['message_id'], "$key: $err");
            sleep(3);
            $this->menu('wg', $page);
            return;
        }

        // Кросс-проверка таймингов: по отдельности значения валидны, а вместе
        // рвут туннель — и сброс в дефолт тоже способен создать конфликт
        // (снятый RejectAfterTime = 180 против выставленного RekeyAfterTime).
        // Поэтому проверяем ИТОГОВЫЙ набор, а не введённую строку.
        if (in_array($key, ['RekeyAfterTime', 'RejectAfterTime', 'RekeyTimeout', 'KeepaliveTimeout'], true)) {
            $next = $this->getPacConf()[$prefix . 'amnezia_keys'] ?? [];
            $next = is_array($next) ? $next : [];
            if ($reset) {
                unset($next[$key]);
            } else {
                $next[$key] = $text;
            }
            if ($err = self::awgTimingConflict($next)) {
                $this->update($this->input['chat'], $this->input['message_id'], $err);
                sleep(3);
                $this->menu('wg', $page);
                return;
            }
        }

        if ($reset) {
            $this->awgApplyGuarded($page, function () use ($prefix, $key) {
                $this->pacConfUpdate(function (&$c) use ($prefix, $key) {
                    if ($key === 'PersistentKeepalive') unset($c[$prefix . 'amnezia_keepalive']);
                    else unset($c[$prefix . 'amnezia_keys'][$key]);
                });
            });
            return;
        }

        // Диапазонный PersistentKeepalive — тоже фича 3.0: старые tools не
        // разберут «20-30» и на клиенте, и на сервере.
        if ($this->awgSupports3() !== true) {
            $this->update($this->input['chat'], $this->input['message_id'], $this->awg3UnsupportedText());
            sleep(3);
            $this->menu('wg', $page);
            return;
        }

        $this->awgApplyGuarded($page, function () use ($prefix, $key, $text) {
            $this->pacConfUpdate(function (&$c) use ($prefix, $key, $text) {
                if ($key === 'PersistentKeepalive') {
                    $c[$prefix . 'amnezia_keepalive'] = $text;
                } else {
                    $c[$prefix . 'amnezia_keys'][$key] = $text;
                }
            });
        });
    }

    // Validates a CPS string for AmneziaWG 2.0 I1-I5 fields.
    // Принимаются только теги, которые бот умеет строить осмысленно:
    // <b 0xHEX>, <r N>, <rc N>, <rd N>, <t>. Парсер amneziawg-go (device/obf.go,
    // obfBuilders) знает ещё d/ds/dz — они подставляют данные самого пакета и для
    // отдельного сигнатурного пакета смысла не имеют, поэтому здесь их нет.
    //
    // Критическое правило: число hex-символов в <b 0x..> обязано быть ЧЁТНЫМ.
    // Источник — device/obf_bytes.go: `strings.TrimPrefix(val, "0x")`, затем
    // `len(val)%2 != 0 → errors.New("odd amount of symbols")`, и только потом
    // hex.DecodeString. Нечётная строка роняет РАЗБОР ВСЕГО конфига: у клиента
    // AmneziaVPN это выглядит как «wgTurnOn вернул -1» без указания причины
    // (habr.com/ru/companies/amnezia/articles/1014636 — тред ku4in ↔ AmneziaLover,
    // после него в самой статье поправили пример).
    // ВАЖНО: считаются ВСЕ символы, включая ведущие нули — `0c7000000010` это
    // 12 символов, то есть валидные 6 байт. В том же треде представитель Amnezia
    // ответил, что «значащих символов всё ещё нечётное количество», но код так не
    // считает: TrimPrefix убирает ровно префикс «0x», а дальше идёт голый len().
    // Минимального размера у сигнатурного пакета нет вовсе — send.go выделяет
    // ровно `ipacket.ObfuscatedLen(0)` байт и шлёт как есть; рекомендация «≥100
    // байт» из статьи — про правдоподобие имитации, а не про требование парсера.
    //
    // Future-work (предложения для upstream amneziawg-go — пока НЕ существуют):
    //   <ra N>  — N случайных букв a-zA-Z (для User-Agent, hostname-частей)
    //   <rh N>  — N символов hostname-charset a-zA-Z0-9- (DNS-labels, SNI)
    //   <ru N>  — N байт UTF-8 (теоретически для SNI с IDN-доменами,
    //             хотя на практике IDN на wire — это уже Punycode-ASCII).
    // Сейчас обходимся литералами через <b 0xHEX> (см. HTTP/1.1 пресет:
    // "Host: cloudflare.com" целиком захардкожен). Если эти токены появятся
    // upstream — нужно (1) добавить альтернативы в regex ниже, (2) добавить
    // строки в cheatsheet setAmneziaI1, (3) при желании — pres-helpers
    // типа cpsHTTPGet($host_random_len, ...).
    public function validateCPSLine($s)
    {
        $s = trim($s);
        if ($s === '') {
            return 'empty';
        }
        if (!preg_match('~^(?:<b 0x[0-9a-fA-F]+>|<r \d+>|<rc \d+>|<rd \d+>|<t>)+$~', $s)) {
            return 'bad syntax — allowed tokens: &lt;b 0xHEX&gt;, &lt;r N&gt;, &lt;rc N&gt;, &lt;rd N&gt;, &lt;t&gt; (no spaces between tokens)';
        }
        if (preg_match_all('~<b 0x([0-9a-fA-F]+)>~', $s, $m)) {
            foreach ($m[1] as $hex) {
                if (strlen($hex) % 2 !== 0) {
                    return "hex in &lt;b 0x$hex&gt; has odd length — must be even (whole bytes)";
                }
            }
        }
        // Официальный потолок длины у <r|rc|rd N> — 1000
        // (docs.amnezia.org/documentation/amnezia-wg, таблица Tag Types).
        // amneziawg-go его не проверяет (obf_rand.go — просто Atoi), поэтому
        // слишком длинный тег даёт не отказ конфига, а junk-пакет, который
        // упрётся в MTU: сигнатурный пакет уйдёт обрезанным или не уйдёт вовсе.
        // Генератор шаблонов сюда не упирается (максимум 250), а вот ручной
        // ввод — вполне.
        if (preg_match_all('~<(r|rc|rd) (\d+)>~', $s, $m, PREG_SET_ORDER)) {
            foreach ($m as [, $tag, $len]) {
                if ((int) $len > self::CPS_MAX_LEN) {
                    return "N in &lt;$tag $len&gt; exceeds " . self::CPS_MAX_LEN . ' — official limit for &lt;r&gt;/&lt;rc&gt;/&lt;rd&gt;';
                }
            }
        }
        return '';
    }

    // CPS-builders с согласованными полями длины. Возвращают строку CPS, у которой
    // ВСЕ внутренние length-поля корректно соответствуют реальному размеру пакета.
    // Это глубже обманывает DPI: первый pass-парсер не отбрасывает пакет как
    // "битый" из-за рассогласования length-fields. target = желаемый итоговый
    // размер пакета I1 в байтах (≥100).

    // TLS 1.2/1.3 ClientHello (RFC 5246 / 8446). Структура wire-формата идентична,
    // отличаются только расширения (которые в нашем junk-пакете отсутствуют).
    // Layout: record_hdr(5) + handshake_hdr(4) + legacy_version(2) + random(32) + tail.
    // Min target = 43 (всё структурное без payload); рекомендуется ≥100 (амнезия 2.0).
    public function cpsTLS(int $target): string
    {
        if ($target < 43) {
            throw new InvalidArgumentException("cpsTLS: target=$target < 43 minimum");
        }
        $rec_len = $target - 5;
        $hs_len  = $target - 9;
        $hex = sprintf('160301%04x01%06x0303', $rec_len, $hs_len);
        $pad = $target - 43;
        return "<b 0x$hex><r 32><r $pad>";
    }

    // DTLS 1.2 ClientHello (RFC 6347). Отличается от TLS дополнительными
    // полями в record/handshake-заголовках (epoch+seq, message_seq+frag_off+frag_len).
    // Layout: record_hdr(13) + handshake_hdr(12) + inner_version(2) + random(32) + tail.
    // Min target = 59.
    public function cpsDTLS(int $target): string
    {
        if ($target < 59) {
            throw new InvalidArgumentException("cpsDTLS: target=$target < 59 minimum");
        }
        $rec_len  = $target - 13;
        $hs_len   = $target - 25;
        $hex = sprintf(
            '16fefd0000000000000000%04x01%06x0000000000%06xfefd',
            $rec_len, $hs_len, $hs_len,
        );
        $pad = $target - 59;
        return "<b 0x$hex><r 32><r $pad>";
    }

    // STUN Binding Request (RFC 5389 / RFC 8489), ICE connectivity check.
    // Layout: type(2) + length(2) + magic(4) + tx_id(12) + attrs.
    //
    // Прежняя версия добивала attribute-секцию сплошным <r N>. Длина в
    // заголовке при этом сходилась, но сама секция — это TLV-поток, и любой
    // настоящий разборщик (Wireshark, RFC 5389 §15) читает первые два байта
    // как тип атрибута, следующие два как его длину и уходит по мусорному
    // смещению: пакет помечается malformed на первом же атрибуте. Здесь
    // собран реальный набор атрибутов ICE-проверки, а <r> стоит ровно там,
    // где у настоящего клиента тоже случайные байты.
    //
    // FINGERPRINT (0x8028) сознательно НЕ добавляем: его значение —
    // CRC32 всего сообщения XOR 0x5354554e, а сообщение содержит теги <r>,
    // раскрываемые на стороне клиента при отправке. Посчитать CRC заранее
    // невозможно, а неверный FINGERPRINT разборщик отмечает явной ошибкой —
    // это хуже, чем его отсутствие (атрибут опциональный).
    // MESSAGE-INTEGRITY, наоборот, оставляем: это HMAC-SHA1 на пароле ICE,
    // проверить его без пароля нельзя, поэтому 20 случайных байт неотличимы.
    public function cpsSTUN(): string
    {
        // [тип, CPS значения, длина значения, байт паддинга до кратности 4].
        // Длина в TLV — это длина ЗНАЧЕНИЯ без паддинга (RFC 5389 §15),
        // а в общую длину сообщения паддинг входит.
        $attrs = [
            // USERNAME: "ufrag:ufrag" — 9 байт значения, 3 байта паддинга.
            ['0006', '<rc 4><b 0x3a><rc 4>', 9, 3],
            // PRIORITY: типовой приоритет host-кандидата (2130706431).
            ['0024', '<b 0x7effffff>', 4, 0],
            // ICE-CONTROLLING: 8-байтный tiebreaker, у клиента тоже случайный.
            ['802a', '<r 8>', 8, 0],
            // MESSAGE-INTEGRITY: HMAC-SHA1, обязан идти последним (RFC 5389 §15.4).
            ['0008', '<r 20>', 20, 0],
        ];
        $body = '';
        $len  = 0;
        foreach ($attrs as [$type, $value, $vlen, $pad]) {
            $body .= "<b 0x$type" . sprintf('%04x', $vlen) . '>' . $value
                   . ($pad > 0 ? '<b 0x' . str_repeat('00', $pad) . '>' : '');
            $len  += 4 + $vlen + $pad;
        }
        $hdr = sprintf('0001%04x2112a442', $len);
        return $this->cpsJoin("<b 0x$hdr><r 12>" . $body);
    }

    // Схлопывает соседние <b 0x..> в один тег. Отдельные билдеры собирают
    // пакет по полям, и без склейки в строке остаются куски вида
    // «<b 0x000000><b 0x00240004>» — валидные, но нечитаемые, а главное
    // маскирующие ошибку чётности: два нечётных куска рядом дают чётную сумму
    // байт, но каждый по отдельности уронит разбор конфига у клиента.
    public function cpsJoin(string $s): string
    {
        return preg_replace_callback(
            '~(?:<b 0x[0-9a-fA-F]+>){2,}~',
            fn ($m) => '<b 0x' . implode('', preg_split('~<b 0x|>~', $m[0], -1, PREG_SPLIT_NO_EMPTY)) . '>',
            $s
        ) ?? $s;
    }

    // NTPv4 client request (RFC 5905 §7.3). Пакет клиента — РОВНО 48 байт:
    // всё, что длиннее, для ntpd/chrony это extension fields, и отсутствие у
    // них корректных заголовков видно разборщику сразу. Прежний пресет добивал
    // 16 байт литерала случайными <r 100>, то есть отправлял 116-байтный
    // «NTP» — размер, которого у клиентского запроса не бывает.
    // Заполнено только поле Transmit Timestamp: так делает и настоящий клиент,
    // а рандом в нём штатен (многие реализации кладут туда nonce).
    public function cpsNTP(): string
    {
        // LI=0, VN=4, Mode=3 (client) | stratum=0 | poll=6 | precision=-20
        // + rootdelay(4) + rootdisp(4) + refid(4) + ref/orig/recv ts (8*3)
        $hex = '230006ec' . str_repeat('00', 12) . str_repeat('00', 24);
        return "<b 0x$hex><r 8>";
    }

    // HTTP/2 connection preface (RFC 7540 §3.5) + SETTINGS frame (тип 0x04).
    // RFC 7540 §6.5: "A SETTINGS frame ... A SETTINGS frame whose length is not
    // a multiple of 6 octets MUST be treated as a connection error". Поэтому
    // target должен удовлетворять (target - 33) % 6 == 0, т.е. target ∈ {33,39,45,...,123,129,...}.
    // Layout: preface(24) + frame_hdr(9) + payload(target-33).
    public function cpsHTTP2(int $target): string
    {
        if ($target < 33) {
            throw new InvalidArgumentException("cpsHTTP2: target=$target < 33 minimum");
        }
        if (($target - 33) % 6 !== 0) {
            throw new InvalidArgumentException(
                "cpsHTTP2: target=$target — frame body " . ($target - 33) . " not multiple of 6 (RFC 7540 §6.5)"
            );
        }
        $body = $target - 33;
        $hex  = '505249202a20485454502f322e300d0a0d0a534d0d0a0d0a'
              . sprintf('%06x040000000000', $body);
        return "<b 0x$hex><r $body>";
    }

    // Стандартный DNS-ответ на A-запрос (RFC 1035), пригодный для I1-junk.
    // tx_id рандомизируется per-session через <r 2>; всё остальное — литералы:
    // header (flags=0x8180 response+RA, qd=1 an=1) + question (name+A+IN) +
    // answer (compressed name pointer 0xc00c + A + IN + TTL + rdlen + IPv4).
    public function cpsDNSResponseA(string $domain, string $ipv4, int $target): string
    {
        $name_hex = '';
        foreach (explode('.', $domain) as $part) {
            if (strlen($part) > 63) {
                throw new InvalidArgumentException("cpsDNSResponseA: label '$part' >63 bytes (RFC 1035 §2.3.4)");
            }
            $name_hex .= sprintf('%02x', strlen($part)) . bin2hex($part);
        }
        $name_hex .= '00';
        $ip_hex = '';
        foreach (explode('.', $ipv4) as $oct) {
            $n = (int) $oct;
            if ($n < 0 || $n > 255) {
                throw new InvalidArgumentException("cpsDNSResponseA: octet $oct out of range");
            }
            $ip_hex .= sprintf('%02x', $n);
        }
        $literal  = '81800001000100000000';
        $literal .= $name_hex . '00010001';
        $literal .= 'c00c00010001000001230004' . $ip_hex;
        $pad = $target - 2 - strlen($literal) / 2;
        if ($pad < 0) {
            throw new InvalidArgumentException("cpsDNSResponseA: target=$target too small for '$domain'");
        }
        return "<r 2><b 0x$literal><r $pad>";
    }

    // ── QUIC (RFC 9000 / RFC 9001) ─────────────────────────────────────────

    // Variable-length integer, RFC 9000 §16. Два старших бита кодируют длину:
    // 00=1 байт, 01=2, 10=4, 11=8. §16 прямо разрешает НЕминимальную запись
    // («values do not need to be encoded on the minimum number of bytes»),
    // чем мы и пользуемся: поле Length всегда пишем 2-байтной формой, иначе
    // его размер зависел бы от значения и ломал арифметику пакета.
    public static function quicVarint(int $v): string
    {
        if ($v < 0) {
            throw new InvalidArgumentException("quicVarint: negative value $v");
        }
        if ($v <= 63) {
            return chr($v);
        }
        if ($v <= 16383) {
            return pack('n', 0x4000 | $v);
        }
        if ($v <= 1073741823) {
            return pack('N', 0x80000000 | $v);
        }
        throw new InvalidArgumentException("quicVarint: $v exceeds 4-byte form");
    }

    // Один transport parameter: id, длина значения и само значение (RFC 9000
    // §18). Длину берём из строки, а не проставляем руками, — ровно на этом
    // расходились объявленный 1 байт и двухбайтовый varint значения 100.
    public static function quicTp(int $id, string $value): string
    {
        return self::quicVarint($id) . self::quicVarint(strlen($value)) . $value;
    }

    // Структурно корректный клиентский Initial-пакет БЕЗ шифрования.
    //
    // Прежние два пресета QUIC («<b 0xc700000001><r 8>…») клали случайный байт
    // на место поля Destination Connection ID Length. RFC 9000 §17.2 разрешает
    // длину CID не больше 20, то есть 236 значений из 256 — сразу malformed,
    // а в остальных случаях по битому смещению разъезжаются SCID, Token и
    // Length. Здесь все поля длин прибиты, а <r> стоит там, где у настоящего
    // клиента тоже случайные байты: сами Connection ID, номер пакета и тело
    // (в реальном QUIC оно зашифровано, то есть неотличимо от случайного).
    //
    // Дальше диссектора со СВОИМ QUIC-расшифровщиком (он выводит ключи из
    // DCID и проверяет AEAD-тег) этот пакет не пройдёт — для такого случая
    // есть cpsQUICInitial(). Зато здесь каждое соединение шлёт разные байты,
    // а не один и тот же вечный пакет.
    public function cpsQUIC(int $target = 1200): string
    {
        // 6 (флаги+версия+DCID len) + 8 DCID + 1 SCID len + 8 SCID
        // + 1 Token len + 2 Length + 4 Packet Number.
        $overhead = 30;
        // Sample для header protection берётся с pn_offset+4 и равен 16 байтам,
        // поэтому тело короче 16 байт в природе не встречается (RFC 9001 §5.4.2).
        if ($target < $overhead + 16) {
            throw new InvalidArgumentException("cpsQUIC: target=$target < " . ($overhead + 16) . ' minimum');
        }
        $payload = $target - $overhead;
        $len     = 4 + $payload;
        if ($len > 16383) {
            throw new InvalidArgumentException("cpsQUIC: target=$target too large for 2-byte Length varint");
        }
        // Тело режем на куски: официальный потолок N у <r> — CPS_MAX_LEN.
        $body = '';
        for ($left = $payload; $left > 0; $left -= self::CPS_MAX_LEN) {
            $body .= '<r ' . min($left, self::CPS_MAX_LEN) . '>';
        }
        return $this->cpsJoin(
            // c3 = long header, fixed bit, тип Initial, PN len 4 байта
            '<b 0xc30000000108>' . '<r 8>'          // версия 1, DCID len 8, DCID
            . '<b 0x08>' . '<r 8>'                  // SCID len 8, SCID
            . '<b 0x00' . bin2hex(self::quicVarint2($len)) . '>'  // Token len 0, Length
            . '<r 4>'                               // Packet Number
            . $body
        );
    }

    // Length в Initial обязан быть предсказуемого размера — всегда 2 байта.
    private static function quicVarint2(int $v): string
    {
        if ($v > 16383) {
            throw new InvalidArgumentException("quicVarint2: $v exceeds 2-byte form");
        }
        return pack('n', 0x4000 | $v);
    }

    // HKDF-Expand, RFC 5869 §2.3. Штатный hash_hkdf() делает Extract+Expand
    // одним вызовом, а TLS 1.3 и QUIC требуют Expand ОТДЕЛЬНО, поверх уже
    // готового PRK — поэтому цикл здесь свой.
    private static function hkdfExpand(string $prk, string $info, int $len): string
    {
        $out = '';
        $t   = '';
        for ($i = 1; strlen($out) < $len; $i++) {
            $t    = hash_hmac('sha256', $t . $info . chr($i), $prk, true);
            $out .= $t;
        }
        return substr($out, 0, $len);
    }

    // HKDF-Expand-Label, RFC 8446 §7.1 (его же использует RFC 9001).
    private static function hkdfExpandLabel(string $secret, string $label, string $ctx, int $len): string
    {
        $l    = 'tls13 ' . $label;
        $info = pack('n', $len) . chr(strlen($l)) . $l . chr(strlen($ctx)) . $ctx;
        return self::hkdfExpand($secret, $info, $len);
    }

    // Ключи защиты клиентского Initial, RFC 9001 §5.2. Выводятся ИЗ DCID —
    // никаких секретов не нужно, ровно поэтому Wireshark умеет расшифровывать
    // чужие Initial-пакеты, и ровно поэтому подделка обязана быть настоящей.
    private static function quicInitialKeys(string $dcid): array
    {
        $salt    = hex2bin('38762cf7f55934b34d179ae6a4c80cadccbb7f0a'); // initial_salt, QUIC v1
        $initial = hash_hmac('sha256', $dcid, $salt, true);             // HKDF-Extract
        $client  = self::hkdfExpandLabel($initial, 'client in', '', 32);
        return [
            self::hkdfExpandLabel($client, 'quic key', '', 16),
            self::hkdfExpandLabel($client, 'quic iv', '', 12),
            self::hkdfExpandLabel($client, 'quic hp', '', 16),
        ];
    }

    private static function tlsExt(int $type, string $data): string
    {
        return pack('n', $type) . pack('n', strlen($data)) . $data;
    }

    // TLS 1.3 ClientHello для QUIC (RFC 8446 §4.1.2 + RFC 9001 §8).
    // legacy_session_id обязан быть пустым — RFC 9001 §8.4, сервер обязан
    // отбросить Initial с непустым session_id.
    private function quicClientHello(string $sni, string $scid): string
    {
        $ext  = self::tlsExt(0x0000, pack('n', strlen($sni) + 3) . "\x00" . pack('n', strlen($sni)) . $sni);
        $ext .= self::tlsExt(0x000a, pack('n', 2) . "\x00\x1d");        // supported_groups: x25519
        $ext .= self::tlsExt(0x0010, pack('n', 3) . "\x02" . 'h3');     // ALPN: h3
        $sigs = "\x04\x03\x08\x04\x04\x01\x05\x03\x08\x05\x05\x01\x08\x06\x06\x01";
        $ext .= self::tlsExt(0x000d, pack('n', strlen($sigs)) . $sigs); // signature_algorithms
        $ks   = "\x00\x1d" . pack('n', 32) . random_bytes(32);          // key_share: x25519
        $ext .= self::tlsExt(0x0033, pack('n', strlen($ks)) . $ks);
        $ext .= self::tlsExt(0x002b, "\x02\x03\x04");                   // supported_versions: TLS 1.3
        // quic_transport_parameters (RFC 9001 §8.2): id/len/value, всё varint.
        // Длину считает quicTp() — вручную она разъезжалась со значением: у
        // initial_max_streams_bidi было объявлено 1 байт, а quicVarint(100)
        // занимает 2 (100 > 63). Парсер сервера уезжал на этом же байте,
        // initial_source_connection_id (0x0f) в пакете не находился, и по
        // RFC 9000 §7.3 соединение обязано закрыться с TRANSPORT_PARAMETER_ERROR.
        $tp   = self::quicTp(0x01, self::quicVarint(30000))    // max_idle_timeout
              . self::quicTp(0x04, self::quicVarint(1048576))  // initial_max_data
              . self::quicTp(0x08, self::quicVarint(100))      // initial_max_streams_bidi
              . self::quicTp(0x0f, $scid);                     // initial_source_connection_id
        $ext .= self::tlsExt(0x0039, $tp);

        $body = "\x03\x03" . random_bytes(32)                  // legacy_version + random
              . "\x00"                                          // legacy_session_id: пусто
              . pack('n', 6) . "\x13\x01\x13\x02\x13\x03"       // TLS_AES_128_GCM / AES_256_GCM / CHACHA20
              . "\x01\x00"                                      // legacy_compression_methods
              . pack('n', strlen($ext)) . $ext;
        return "\x01" . substr(pack('N', strlen($body)), 1) . $body;
    }

    // НАСТОЯЩИЙ клиентский Initial: ClientHello в CRYPTO-фрейме, AES-128-GCM
    // и header protection по RFC 9001. Такой пакет Wireshark расшифровывает и
    // разбирает как обычный QUIC — включая SNI внутри.
    //
    // РАЗМЕН, о котором надо помнить: AEAD-тег покрывает весь пакет, поэтому
    // внутрь нельзя вставить ни одного <r> — вся 1200-байтная строка уходит
    // одним статическим <b 0xHEX>, и КАЖДЫЙ хендшейк шлёт побайтово один и тот
    // же пакет. Настоящий клиент меняет DCID и key_share на каждое соединение,
    // так что бесконечный повтор одного Initial — сам по себе аномалия.
    // Компенсируется ротацией (rotate: every Nd) и кнопкой перегенерации.
    // Если это неприемлемо — берите cpsQUIC(): он структурно валиден и
    // случаен на каждом пакете, но не переживёт расшифровку.
    public function cpsQUICInitial(string $sni = 'www.cloudflare.com'): string
    {
        if (!preg_match('~^(?=.{4,253}$)([a-z0-9](?:[a-z0-9-]*[a-z0-9])?\.)+[a-z]{2,}$~i', $sni)) {
            throw new InvalidArgumentException("cpsQUICInitial: bad SNI '$sni'");
        }
        $dcid = random_bytes(8);
        $scid = random_bytes(8);
        $pnB  = pack('N', 0);                       // Packet Number 0, длина 4

        $ch     = $this->quicClientHello($sni, $scid);
        $crypto = "\x06" . self::quicVarint(0) . self::quicVarint(strlen($ch)) . $ch;

        // RFC 9000 §14.1: датаграмму с клиентским Initial доводят до 1200 байт,
        // иначе сервер ОБЯЗАН её отбросить — короткий Initial сам по себе метка.
        // Добиваем PADDING-фреймами (0x00).
        $total = 1200;
        $ptLen = $total - 24 - 2 - 4 - 16;          // header + Length + PN + GCM tag
        if (strlen($crypto) > $ptLen) {
            throw new InvalidArgumentException('cpsQUICInitial: ClientHello does not fit into a 1200-byte Initial');
        }
        $pt  = $crypto . str_repeat("\x00", $ptLen - strlen($crypto));
        $hdr = "\xc3\x00\x00\x00\x01"
             . chr(strlen($dcid)) . $dcid
             . chr(strlen($scid)) . $scid
             . "\x00"
             . self::quicVarint2(4 + $ptLen + 16)
             . $pnB;

        [$key, $iv, $hp] = self::quicInitialKeys($dcid);
        // nonce = iv XOR номер пакета, выровненный вправо (RFC 9001 §5.3).
        $nonce = $iv ^ (str_repeat("\x00", strlen($iv) - strlen($pnB)) . $pnB);

        $tag = '';
        $ct  = openssl_encrypt($pt, 'aes-128-gcm', $key, OPENSSL_RAW_DATA, $nonce, $tag, $hdr, 16);
        if ($ct === false) {
            throw new RuntimeException('cpsQUICInitial: AES-128-GCM failed');
        }
        $ct .= $tag;

        // Header protection, RFC 9001 §5.4.3: маска — AES-ECB от 16 байт тела,
        // начиная с pn_offset+4 (то есть с самого начала шифротекста).
        $mask = openssl_encrypt(substr($ct, 0, 16), 'aes-128-ecb', $hp, OPENSSL_RAW_DATA | OPENSSL_ZERO_PADDING);
        if ($mask === false) {
            throw new RuntimeException('cpsQUICInitial: AES-128-ECB failed');
        }
        // У long header маскируются 4 младших бита первого байта.
        $hdr[0] = chr(ord($hdr[0]) ^ (ord($mask[0]) & 0x0f));
        $pnOff  = strlen($hdr) - 4;
        for ($i = 0; $i < 4; $i++) {
            $hdr[$pnOff + $i] = chr(ord($hdr[$pnOff + $i]) ^ ord($mask[1 + $i]));
        }
        return '<b 0x' . bin2hex($hdr . $ct) . '>';
    }

    // ── BitTorrent DHT / uTP ───────────────────────────────────────────────

    // DHT KRPC-запрос, BEP 5. Bencode самоописателен, полей длины нет вообще —
    // поэтому случайные части (20-байтный node id, 2-байтный transaction id,
    // 20-байтный target) вставляются тегами <r> без единого согласования.
    // Ключи словаря идут в лексикографическом порядке, как требует bencode.
    //
    // Размер намеренно НЕ добивается до рекомендуемых ≥100 байт: настоящий
    // ping — это ровно 56 байт, а find_node 91, и любой довесок сделал бы
    // пакет менее правдоподобным, а не более. Рекомендация из статьи Amnezia
    // про правдоподобие имитации, и здесь она работает наоборот.
    public function cpsDHT(bool $findNode = false): string
    {
        $h = fn (string $s) => '<b 0x' . bin2hex($s) . '>';
        if ($findNode) {
            return $h('d1:ad2:id20:') . '<r 20>' . $h('6:target20:') . '<r 20>'
                 . $h('e1:q9:find_node1:t2:') . '<r 2>' . $h('1:y1:qe');
        }
        return $h('d1:ad2:id20:') . '<r 20>' . $h('e1:q4:ping1:t2:') . '<r 2>' . $h('1:y1:qe');
    }

    // uTP ST_SYN, BEP 29. Заголовок ровно 20 байт, полей длины нет.
    // <r> — connection_id, timestamp_microseconds и seq_nr: у настоящего
    // клиента все три тоже непредсказуемы. timestamp_difference на SYN равен
    // нулю (отвечать ещё некому), ack_nr тоже.
    public function cpsUTP(): string
    {
        // 0x41 = type ST_SYN (4) в старших 4 битах | версия 1; extension 0x00.
        return $this->cpsJoin(
            '<b 0x4100><r 2><r 4>'
            . '<b 0x00000000>'   // timestamp_difference_microseconds
            . '<b 0x00100000>'   // wnd_size = 1 MiB
            . '<r 2>'            // seq_nr
            . '<b 0x0000>'       // ack_nr
        );
    }

    // Tap-to-copy CPS presets, сгруппированные по протоколу. Вынесены из
    // setAmneziaI1() отдельным методом, чтобы tests/cps_presets_test.php мог
    // разобрать КАЖДЫЙ пресет как бинарный пакет и сверить поля длин: два
    // прежних QUIC-пресета годами лежали здесь сломанными именно потому, что
    // проверить их было нечем.
    //
    // Стартовые байты имитируют реальный протокол, теги <r>/<rc> стоят там,
    // где у настоящего клиента тоже непредсказуемые данные (Random, tx_id,
    // Connection ID, node id) — а не просто добивают длину.
    // Hex внутри <b 0x..> всегда чётной длины (целые байты). Без пробелов.
    // Источники структуры заголовков:
    //   QUIC — RFC 9000 §17.2, RFC 9001 (шифрование Initial)
    //   DNS  — RFC 1035; mDNS — RFC 6762
    //   TLS  — RFC 5246 (1.2) / RFC 8446 (1.3); DTLS — RFC 6347
    //   HTTP — RFC 7230 (1.1) / RFC 7540 (2)
    //   STUN — RFC 5389 (magic cookie 0x2112A442)
    //   NTP  — RFC 5905 §7.3 (mode 3 client, первый байт 0x23)
    //   BitTorrent — BEP 5 (DHT KRPC), BEP 29 (uTP)
    public function cpsPresets(): array
    {
        return [
            'QUIC (UDP/443)' => [
                $this->t('Initial v1, связные DCID/SCID/Length (RFC 9000 §17.2)', 'Initial v1, linked DCID/SCID/Length (RFC 9000 §17.2)')
                    => $this->cpsQUIC(1200),
            ],
            'DNS / mDNS (UDP/53)' => [
                $this->t('RU: Yandex DNS-ответ (yabs.yandex.ru)', 'RU: Yandex DNS answer (yabs.yandex.ru)')
                    => '<b 0x8580000100010000000004796162730679616e6465780272750000010001c00c000100010001c00c000100010000026d000457fa27d1><r 50>',
                $this->t('RU: Yandex DNS-ответ (widget.tickets.kinopoisk + Afisha)', 'RU: Yandex DNS answer (widget.tickets.kinopoisk + Afisha)')
                    => '<b >',
                $this->t('Global: Cloudflare A-ответ (cloudflare.com → 104.16.132.229)', 'Global: Cloudflare A answer (cloudflare.com → 104.16.132.229)')
                    => $this->cpsDNSResponseA('cloudflare.com', '104.16.132.229', 120),
                $this->t('Global: Google A-ответ (google.com → 142.250.80.46)', 'Global: Google A answer (google.com → 142.250.80.46)')
                    => $this->cpsDNSResponseA('google.com', '142.250.80.46', 120),
                $this->t('Global: A-запрос www.google.com (recursion desired)', 'Global: A query www.google.com (recursion desired)')
                    => '<r 2><b 0x012000010000000000000377777706676f6f676c6503636f6d0000010001><r 80>',
                $this->t('Global: A-запрос cloudflare.com (recursion desired)', 'Global: A query cloudflare.com (recursion desired)')
                    => '<r 2><b 0x012000010000000000000a636c6f7564666c61726503636f6d0000010001><r 80>',
                $this->t('Global: mDNS-запрос _services._dns-sd._udp.local', 'Global: mDNS query _services._dns-sd._udp.local')
                    => '<b 0x000000000001000000000000095f7365727669636573075f646e732d7364045f756470056c6f63616c00000c0001><r 80>',
            ],
            'TLS / DTLS' => [
                'TLS 1.2/1.3 ClientHello (consistent length fields)'
                    => $this->cpsTLS(120),
                'DTLS 1.2 ClientHello (consistent length fields, RFC 6347)'
                    => $this->cpsDTLS(120),
            ],
            'HTTP' => [
                'HTTP/2 preface + SETTINGS frame (consistent frame_len)'
                    => $this->cpsHTTP2(123),
                $this->t('HTTP/1.1 GET / с Host: cloudflare.com', 'HTTP/1.1 GET / with Host: cloudflare.com')
                    => '<b 0x474554202f20485454502f312e310d0a486f73743a20636c6f7564666c6172652e636f6d0d0a4163636570743a202a2f2a0d0a0d0a><r 70>',
            ],
            'WebRTC / NTP (UDP)' => [
                $this->t('STUN Binding Request, ICE-атрибуты TLV (RFC 5389)', 'STUN Binding Request, ICE TLV attributes (RFC 5389)')
                    => $this->cpsSTUN(),
                $this->t('NTPv4 client request, ровно 48 байт (RFC 5905 §7.3)', 'NTPv4 client request, exactly 48 bytes (RFC 5905 §7.3)')
                    => $this->cpsNTP(),
            ],
            'BitTorrent (UDP)' => [
                $this->t('DHT ping, 56 байт (BEP 5)', 'DHT ping, 56 bytes (BEP 5)')
                    => $this->cpsDHT(),
                $this->t('DHT find_node, 92 байта (BEP 5)', 'DHT find_node, 92 bytes (BEP 5)')
                    => $this->cpsDHT(true),
                $this->t('uTP ST_SYN, 20 байт (BEP 29)', 'uTP ST_SYN, 20 bytes (BEP 29)')
                    => $this->cpsUTP(),
            ],
            $this->t('Прочее', 'Other') => [
                $this->t('Лёгкий профиль (минимальный валидный 2.0)', 'Light profile (minimal valid 2.0)')
                    => '<b 0xc000000001><r 100>',
            ],
        ];
    }

    public function setAmneziaI1($page = 0)
    {
        $c       = $this->getPacConf();
        $cur     = $c[$this->getInstanceWG(1) . 'amnezia_keys']['I1'] ?? '—';
        $presets = $this->cpsPresets();
        $lines   = [
            $this->t("@{$this->input['username']} введите строку I1 (CPS) или 0 — отключить цепочку 2.0.", "@{$this->input['username']} enter the I1 (CPS) string, or 0 to disable the 2.0 chain."),
            '',
            $this->t('Текущее: <code>', 'Current: <code>') . htmlspecialchars($cur) . '</code>',
            '',
            $this->t('Правила: hex в &lt;b 0x..&gt; — чётное число символов (целые байты). Без пробелов между токенами.', 'Rules: hex in &lt;b 0x..&gt; needs an even number of characters (whole bytes). No spaces between tokens.'),
            '',
            $this->t('Про размер: рекомендация «≥100 байт» — про правдоподобие, а не требование парсера. Для имитации конкретного протокола ВЕРНЕЕ совпасть с его настоящим размером: клиентский NTP — ровно 48 байт, DHT ping — 56, uTP SYN — 20, и добивка сделала бы их подозрительнее, а не незаметнее.', 'About size: the "≥100 bytes" advice is about plausibility, not a parser requirement. To imitate a specific protocol it is MORE accurate to match its real size: a client NTP packet is exactly 48 bytes, DHT ping 56, uTP SYN 20, and padding would make them more suspicious, not less.'),
            '',
            $this->t('Кнопка «QUIC Initial» в меню генерирует и сразу ставит настоящий шифрованный Initial (RFC 9001): 1200 байт, расшифровывается Wireshark как обычный QUIC. Платой идёт статичность — AEAD-тег покрывает пакет целиком, поэтому теги &lt;r&gt; внутрь не вставить и все хендшейки шлют один и тот же пакет. Держите включённой авто-ротацию либо берите пресет QUIC из списка ниже — он случаен на каждом пакете, но расшифровку не переживёт.', 'The QUIC Initial button in the menu generates and immediately sets a real encrypted Initial (RFC 9001): 1200 bytes that Wireshark decrypts as ordinary QUIC. The price is that it is static: the AEAD tag covers the whole packet, so &lt;r&gt; tags cannot go inside and every handshake sends the same packet. Keep auto-rotation on, or take the QUIC preset from the list below: it is random on every packet but does not survive decryption.'),
            '',
            $this->t('Токены CPS:', 'CPS tokens:'),
            $this->t('<code>&lt;b 0xHEX&gt;</code> — литерал-байты, для заголовков протоколов', '<code>&lt;b 0xHEX&gt;</code>: literal bytes, for protocol headers'),
            $this->t('<code>&lt;r N&gt;</code>     — N случайных байт, для CID/padding/IP/random fields', '<code>&lt;r N&gt;</code>     : N random bytes, for CID/padding/IP/random fields'),
            $this->t('<code>&lt;rc N&gt;</code>    — N случайных printable-ASCII (буквы+цифры+пунктуация)', '<code>&lt;rc N&gt;</code>    : N random printable ASCII (letters, digits, punctuation)'),
            $this->t('<code>&lt;rd N&gt;</code>    — N случайных ASCII-цифр (0-9), для числовых ID', '<code>&lt;rd N&gt;</code>    : N random ASCII digits (0-9), for numeric IDs'),
            $this->t('<code>&lt;t&gt;</code>       — 4-байтный UNIX-timestamp', '<code>&lt;t&gt;</code>       : a 4-byte UNIX timestamp'),
            '',
            $this->t('I1 пишется одинаково в server и client (требование протокола: обе стороны должны консьюмить тот же junk-паттерн). Для разнообразия fingerprint\'а во времени включите авто-ротацию: rotate: every Nd.', 'I1 is written the same on the server and the client (a protocol requirement: both sides must consume the same junk pattern). To vary the fingerprint over time, enable auto-rotation: rotate: every Nd.'),
        ];

        // Пресеты уезжают ОТДЕЛЬНЫМИ сообщениями, а не в одном со шпаргалкой:
        // у Telegram потолок 4096 символов на sendMessage, и общий текст упёрся
        // в него ещё до появления DHT/uTP (3648 из 4096). Одно длинное hex-тело
        // вроде яндексового DNS-ответа — это сразу ~270 символов, поэтому режем
        // по секциям с запасом, а не «когда-нибудь потом».
        $chunks = [];
        $cur    = [$this->t('Готовые примеры (нажмите на строку — скопируется):', 'Ready examples (tap a line to copy it):')];
        $curLen = mb_strlen($cur[0]);
        foreach ($presets as $section => $items) {
            $block = ['', "<b>— $section —</b>"];
            foreach ($items as $label => $val) {
                $block[] = "• $label";
                $block[] = '<code>' . htmlspecialchars($val) . '</code>';
            }
            $blockLen = mb_strlen(implode("\n", $block)) + 1;
            // 3800, а не 4096: запас на служебную обвязку и на то, что счёт у
            // Telegram идёт по UTF-16, а не по символам PHP.
            if ($curLen + $blockLen > 3800 && count($cur) > 1) {
                $chunks[] = implode("\n", $cur);
                $cur      = [];
                $curLen   = 0;
            }
            $cur    = array_merge($cur, $block);
            $curLen += $blockLen;
        }
        $chunks[] = implode("\n", $cur);
        foreach ($chunks as $chunk) {
            $this->send($this->input['chat'], $chunk, $this->input['message_id']);
        }

        // Промпт с ForceReply шлём ПОСЛЕДНИМ: ответ пользователя должен
        // прицепиться именно к нему, иначе stash не найдёт свой message_id.
        $r = $this->send(
            $this->input['chat'],
            implode("\n", $lines),
            $this->input['message_id'],
            reply: $this->t('введите I1 или 0', 'enter I1 or 0'),
        );
        $this->stashReply($r, [
            'start_message'  => $this->input['message_id'],
            'start_callback' => $this->input['callback_id'],
            'callback'       => 'setAmneziaI1Value',
            // Инстанс кладём в stash: ответ придёт отдельным запросом, где
            // глобальный wg_instance мог смениться другим меню/устройством.
            'args'           => [$this->wgNum(), $page],
        ]);
    }

    public function setAmneziaI1Value($text, $inst = 0, $page = 0)
    {
        return $this->withWireguardUpdate(fn() => $this->setAmneziaI1ValueLocked($text, $inst, $page), in_array((int) $inst, [0, 1], true) ? ((int) $inst ? 'wg1' : 'wg') : null);
    }

    private function setAmneziaI1ValueLocked($text, $inst = 0, $page = 0)
    {
        // Стэш, созданный до деплоя, нёс args=[$page]: старая страница
        // приходит в $inst. Значение вне 0/1 — легаси-страница: возвращаем её
        // в $page и берём текущий глобальный инстанс (прежнее поведение).
        if ((int) $inst !== 0 && (int) $inst !== 1) {
            $page = (int) $inst;
            $inst = $this->wgNum();
        }
        $this->selectWG($inst);
        $text   = trim($text);
        $prefix = $this->getInstanceWG(1);
        $k      = $prefix . 'amnezia_keys';

        if ($text === '0' || $text === '') {
            $changed = $this->pacConfUpdate(function (&$c) use ($k) {
                if (empty($c[$k])) return false;
                unset($c[$k]['I1']);
                return true;
            });
            if ($changed) {
                $this->switchAmnezia($page, false, false, 1);
                return;
            }
            $this->menu('wg', $page);
            return;
        }

        $err = $this->validateCPSLine($text);
        if ($err) {
            $this->update($this->input['chat'], $this->input['message_id'], "I1: $err");
            sleep(3);
            $this->menu('wg', $page);
            return;
        }

        $this->pacConfUpdate(function (&$c) use ($k, $prefix, $text) {
            if (empty($c[$k])) $c[$k] = $this->generateAmneziaKeys($c[$prefix . 'amnezia_tpl'] ?? 'standard_2');
            $c[$k]['I1'] = $text;
            $c[$prefix . 'amnezia'] = 1;
        });
        $this->switchAmnezia($page, false, false, 1);
    }

    // Генерирует НАСТОЯЩИЙ шифрованный QUIC Initial и сразу ставит его в I1.
    // Отдельной кнопкой, а не строкой в шпаргалке пресетов: 1200-байтный пакет
    // — это 2400 hex-символов, а сообщение со шпаргалкой само по себе ~2.5 КБ,
    // вместе они вышли бы за лимит Telegram в 4096 символов. Копировать такую
    // строку руками тоже незачем — применяем на месте, через тот же путь,
    // что и ручной ввод (валидация + switchAmnezia).
    //
    // SNI берём из списка заведомо популярных хостов, а НЕ из своего домена:
    // собственный reality/fake-домен в junk-пакете дал бы наблюдателю прямую
    // связку «этот junk ↔ этот сервер».
    public function genQuicInitial($inst = 0, $page = 0)
    {
        $hosts = ['www.cloudflare.com', 'www.google.com', 'www.youtube.com', 'www.microsoft.com'];
        try {
            $cps = $this->cpsQUICInitial($hosts[random_int(0, count($hosts) - 1)]);
        } catch (\Throwable $e) {
            $this->update($this->input['chat'], $this->input['message_id'], 'QUIC Initial: ' . $e->getMessage());
            sleep(3);
            $this->menu('wg', $page);
            return;
        }
        // Предупреждаем ДО применения: 2406 символов в I1 раздувают клиентский
        // конфиг за потолок ёмкости QR (2953 байта), и «show QR» для AWG
        // начнёт отдавать .conf файлом вместо картинки. Это не поломка —
        // sendQr() деградирует осознанно, — но поведение меняется заметно.
        $this->send(
            $this->input['chat'],
            'QUIC Initial: ' . strlen($cps) . $this->t(" символов в I1.\n", " characters in I1.\n")
            . $this->t('Клиентский конфиг с ним не помещается в QR — «show QR» для AWG будет отдавать .conf файлом.', 'A client config with it does not fit in a QR code; show QR for AWG will send a .conf file.')
        );
        $this->setAmneziaI1Value($cps, $inst, $page);
    }

    public function switchAmnezia($page = 0, $reset = false, $reduce = false, $apply = false, $silent = false)
    {
        return $this->withWireguardUpdate(fn() => $this->switchAmneziaLocked($page, $reset, $reduce, $apply, $silent), null);
    }

    private function switchAmneziaLocked($page = 0, $reset = false, $reduce = false, $apply = false, $silent = false)
    {
        // Серверный конфиг читаем ДО любых записей: readConfig() штатно отдаёт
        // null при недоступном контейнере, а ниже $wg['interface'][$j] = $i
        // авто-вивифицировал бы null и createConfig(null) дал заглушку из одной
        // секции [Interface] — без PrivateKey, ListenPort и без единого пира.
        // Если ssh к моменту записи успевал восстановиться, эта заглушка
        // уезжала в wg0.conf. Заодно не даём разъехаться pac.json/clients.json
        // с сервером: до успешного чтения не меняем ничего.
        $wg = $this->readConfig();
        if (empty($wg['interface'])) {
            if (empty($silent)) {
                $this->send(
                    $this->input['chat'] ?? '',
                    $this->t('wireguard: конфиг недоступен (контейнер не отвечает), amnezia не переключена', 'wireguard: the config is unavailable (the container does not respond), amnezia not switched'),
                    $this->input['message_id'] ?? null,
                );
            }
            return;
        }
        [$orig, $c, $amnezia] = $this->pacConfUpdate(function (&$c) use ($reset, $reduce, $apply) {
            $orig = $c;
            switch (true) {
                case !empty($reset):
                    $amnezia = 1;
                    unset($c[$this->getInstanceWG(1) . 'amnezia_keys']);
                    unset($c[$this->getInstanceWG(1) . 'presharedkey']);
                    unset($c[$this->getInstanceWG(1) . 'amnezia_keepalive']);
                    break;
                case !empty($reduce):
                    // Понижение до 1.x: снимаем 2.0-, 3.0- и 3.1-поля. Оставить
                    // HeaderProtectionKey без S3/S4 нельзя — конфиг был бы отвергнут.
                    // AWG_KEYS_31 сюда же: тумблеры RandomTrailers/DisableCookies
                    // включаются только при amneziaProtoVer() === 3 (см. toggleRandomTrailers/
                    // toggleDisableCookies) — оставшись висеть на «1.x»-наборе, они бы
                    // нарушили этот инвариант и продолжали молча уезжать в wg0.conf.
                    $amnezia = 1;
                    foreach (array_merge(self::AWG_KEYS_2, self::AWG_KEYS_3, self::AWG_KEYS_31) as $j) {
                        unset($c[$this->getInstanceWG(1) . 'amnezia_keys'][$j]);
                    }
                    break;
                case !empty($apply):
                    // Caller (applyAmneziaTemplate) has already set keys + amnezia=1.
                    $amnezia = 1;
                    break;

                default:
                    $amnezia = $c[$this->getInstanceWG(1) . 'amnezia'] = ($c[$this->getInstanceWG(1) . 'amnezia'] ?? false) ? 0 : 1;
                    break;
            }
            return [$orig, $c, $amnezia];
        });

        // presharedKey() отдаёт '' только когда контейнер не ответил (см. там же).
        // Писать конфиги с пустым PresharedKey нельзя, а pac.json к этому моменту
        // уже переключён — откатываем его к исходному снимку, иначе меню показывало
        // бы amnezia включённой при неизменившихся конфигах.
        $pk = $this->presharedKey();
        if (!empty($amnezia) && $pk === '') {
            $prefix = $this->getInstanceWG(1);
            if (!$this->restorePacFields($orig, $c, array_map(fn($key) => $prefix . $key, ['amnezia', 'amnezia_keys', 'presharedkey', 'amnezia_keepalive']))) throw new RuntimeException($this->t('Настройки изменились; восстановление предыдущего состояния не подтверждено', 'Settings changed; restoration of the previous state is unconfirmed'));
            if (empty($silent)) {
                $this->send(
                    $this->input['chat'] ?? '',
                    $this->t('wireguard: не удалось получить presharedkey (контейнер не отвечает), amnezia не переключена', 'wireguard: could not get the presharedkey (the container does not respond), amnezia not switched'),
                    $this->input['message_id'] ?? null,
                );
            }
            return;
        }
        $ak = $this->amneziaKeysEffective();
        // Списки чистки — из awgKeyNames(), а не перечислением: иначе каждый
        // новый параметр протокола пришлось бы дописывать в двух местах, и
        // забытый ключ остался бы в конфиге «хвостом» от прошлой версии.
        $strip   = self::awgKeyNames();
        $keepal  = $this->awgKeepalive();
        $clients = $this->readClients();
        foreach ($clients as $k => $v) {
            unset($clients[$k]['peers'][0]['PresharedKey']);
            foreach ($strip as $j) {
                unset($clients[$k]['interface'][$j]);
            }
            if (!empty($amnezia)) {
                $clients[$k]['peers'][0]['PresharedKey'] = $pk;
                foreach ($ak as $j => $i) {
                    $clients[$k]['interface'][$j] = $i;
                }
            }
            // PersistentKeepalive живёт в [Peer] и потому не входит в набор
            // amnezia_keys; при выключенной амнезии возвращаем фиксированные 20.
            if (isset($clients[$k]['peers'][0]['PersistentKeepalive'])) {
                $clients[$k]['peers'][0]['PersistentKeepalive'] = !empty($amnezia) ? $keepal : 20;
            }
        }
        $this->saveClients($clients);

        foreach ($strip as $j) {
            unset($wg['interface'][$j]);
        }
        if (!empty($amnezia)) {
            foreach ($ak as $j => $i) {
                $wg['interface'][$j] = $i;
            }
        }

        foreach ($wg['peers'] ?? [] as $k => $v) {
            if (!empty($amnezia)) {
                $wg['peers'][$k]['PresharedKey'] = $pk;
            } else {
                unset($wg['peers'][$k]['PresharedKey']);
            }
        }
        $this->restartWG($this->createConfig($wg), !$reset && !$reduce && !$apply);
        if (!$silent) {
            $this->menu('wg', $page);
        }
    }

    // ── Массовая ротация ключей клиентов (WG/AWG) ─────────────────────────────
    //
    // Сервер сам себе ничего не меняет: ротируются только клиентские
    // PrivateKey/PublicKey (+ общий на инстанс PresharedKey у amnezia). Ключ
    // самого сервера ([Interface] PrivateKey в живом wg0.conf, ставится один
    // раз start_wg.sh при первом старте контейнера) не трогается никогда —
    // его ротация разом сломала бы ВСЕ уже выданные конфиги (в каждом зашит
    // текущий публичный ключ сервера), а не только клиентские.
    //
    // Сопоставление clients[] ↔ серверных peers[] — по адресу
    // (peerIndexByClient), а не по общему индексу, как делает switchAmnezia():
    // там цена ошибки ниже (не тот клиент не получит PSK/junk), здесь —
    // выше (не тот клиент получил бы чужой публичный ключ на сервере, тихая
    // и трудно диагностируемая поломка). Клиент без пира на сервере
    // пропускается целиком — новый локальный ключ ему тоже не пишем: иначе
    // он указывал бы на пира, которого на сервере нет вовсе, что хуже, чем
    // оставить как было.

    // Чистая функция, без ssh/сети — юнит-тестируется напрямую. $keyPairs —
    // список ['priv', 'pub'] в порядке $clients; $psk — новый общий
    // presharedkey инстанса (amnezia) либо null (обычный WG — поле
    // PresharedKey нигде не создаётся и не трогается).
    public function applyRotatedPeerKeys(array $clients, ?array $conf, array $keyPairs, ?string $psk): array
    {
        $rotated = 0;
        $skipped = 0;
        $oldToNew = [];
        foreach ($clients as $k => $client) {
            $pair = array_shift($keyPairs);
            if ($pair === null) {
                $skipped++;
                continue;
            }
            [$priv, $pub] = $pair;
            $i = $this->peerIndexByClient($conf, $client);
            if ($i === null) {
                $skipped++;
                continue;
            }
            $old = (string) ($client['interface']['PrivateKey'] ?? '');
            $clients[$k]['interface']['PrivateKey'] = $priv;
            if ($old !== '') {
                $oldToNew[$old] = $priv;
            }
            // Выключенный пир хранит поля с префиксом "# " (switchClient()) —
            // пишем под тем же префиксом, что уже есть, никогда не заводя
            // одновременно и PublicKey, и # PublicKey (иначе createConfig()
            // теряет заголовок секции — она решает [Peer]/# [Peer] по
            // наличию именно # PublicKey). disabled — по PublicKey, единому
            // источнику правды: у PresharedKey поля может не быть вовсе
            // (амнезию включили позже, пир создан ещё как plain WG), и
            // проверка "уже есть # PresharedKey" в этом случае завела бы
            // несогласованную смесь # PublicKey + голый PresharedKey.
            $disabled = array_key_exists('# PublicKey', $conf['peers'][$i]);
            $conf['peers'][$i][$disabled ? '# PublicKey' : 'PublicKey'] = $pub;
            if ($psk !== null) {
                $clients[$k]['peers'][0]['PresharedKey'] = $psk;
                $conf['peers'][$i][$disabled ? '# PresharedKey' : 'PresharedKey'] = $psk;
            }
            $rotated++;
        }

        return ['clients' => $clients, 'conf' => $conf, 'rotated' => $rotated, 'skipped' => $skipped, 'oldToNew' => $oldToNew];
    }

    // Чистая функция: WG-клиент привязывается к VLESS-клиенту по значению
    // (setVlessLink()/unsetVlessLink() кладут сырой PrivateKey WG-клиента в
    // xray.json.inbounds[0].settings.clients[$i]['awg']) — после ротации это
    // значение протухает молча (тумблер "vless: on/off" покажет "off", хотя
    // связь технически осталась, а комбо-подписка AWG+VLESS тихо потеряет
    // AWG-часть). Переписываем совпавшие awg-поля на новый ключ тем же
    // сравнением, что уже использует setVlessLink().
    public function remapVlessAwgLinks(array $xr, array $oldToNew): array
    {
        if (!$oldToNew || empty($xr['inbounds'][0]['settings']['clients'])) {
            return $xr;
        }
        foreach ($xr['inbounds'][0]['settings']['clients'] as $i => $c) {
            if (!empty($c['awg']) && isset($oldToNew[$c['awg']])) {
                $xr['inbounds'][0]['settings']['clients'][$i]['awg'] = $oldToNew[$c['awg']];
            }
        }

        return $xr;
    }

    public function rotateAllPeerKeys($page, $confirm = false)
    {
        $service = $this->getInstanceWG();
        $mapping = $this->withWireguardUpdate(fn() => $this->rotateAllPeerKeysLocked($page, $confirm));
        if (!is_array($mapping)) return $mapping;
        if (!$this->completeWireguardRemap($service)) throw new RuntimeException($this->t('WireGuard: обновление привязок не подтверждено', 'WireGuard: link update is unconfirmed'));
        $this->menu('wg', $page);
    }

    private function rotateAllPeerKeysLocked($page, $confirm = false)
    {
        if (!$confirm) {
            $text = 'Menu -> ' . $this->i18n('wg_title') . "\n⚠ " . $this->i18n('confirm rotate peer keys');
            $inst = $this->wgNum();
            $data = [
                [['text' => '❌ ' . $this->i18n('rotate all peer keys'), 'callback_data' => "/rotateAllPeerKeys $inst $page confirm"]],
                [['text' => $this->i18n('cancel'), 'callback_data' => "/menu wg $page"]],
            ];

            return $this->update($this->input['chat'], $this->input['message_id'], $text, $data);
        }

        $clients = $this->readClients();
        if (!$clients) {
            return $this->menu('wg', $page);
        }
        $conf = $this->readConfig();
        if (empty($conf['interface']['Address'])) {
            $this->wgConfUnavailable($this->t('ключи клиентов не изменены', 'client keys unchanged'));

            return;
        }

        $amnezia = $this->getPacConf()[$this->getInstanceWG(1) . 'amnezia'] ?? false;
        $psk     = null;
        if ($amnezia) {
            // unset кэша заставляет presharedKey() сгенерировать новый — тот
            // же приём, что switchAmnezia($reset=true).
            $this->pacConfUpdate(function (&$p) { unset($p[$this->getInstanceWG(1) . 'presharedkey']); });
            $psk = $this->presharedKey();
            if ($psk === '') {
                $this->wgConfUnavailable($this->t('не удалось получить presharedkey (контейнер недоступен), ключи не изменены', 'could not get the presharedkey (the container is unavailable), keys unchanged'));

                return;
            }
        }

        // Один ssh()-вызов на весь батч (цикл — на стороне контейнера), а не
        // 2-3 вызова НА КЛИЕНТА: ssh() каждый раз поднимает новое соединение
        // с нуля, и на сотнях клиентов наивный цикл упёрся бы в таймаут.
        $n      = count($clients);
        $wgType = $this->getWGType();
        $genCmd = "i=0; while [ \$i -lt $n ]; do PRIV=\$($wgType genkey); "
                . "PUB=\$(echo \"\$PRIV\" | $wgType pubkey); echo \"\$PRIV \$PUB\"; i=\$((i+1)); done";
        $out    = trim($this->ssh($genCmd, $this->getInstanceWG()));
        $lines  = $out !== '' ? preg_split('~\R~', $out, -1, PREG_SPLIT_NO_EMPTY) : [];
        $pairs  = [];
        foreach ($lines as $line) {
            [$priv, $pub] = array_pad(explode(' ', trim($line), 2), 2, '');
            if (preg_match('~^[A-Za-z0-9+/]{43}=$~', $priv) && preg_match('~^[A-Za-z0-9+/]{43}=$~', $pub)) {
                $pairs[] = [$priv, $pub];
            }
        }
        if ($this->sshFailed || count($pairs) !== $n) {
            $this->wgConfUnavailable($this->t('не удалось сгенерировать ключи для всех клиентов (контейнер недоступен), ничего не изменено', 'could not generate keys for all clients (the container is unavailable), nothing changed'));

            return;
        }

        $r = $this->applyRotatedPeerKeys($clients, $conf, $pairs, $psk);


        if (!$this->applyWgConfig($this->createConfig($r['conf']), $r['clients'], false, $r['oldToNew'])) throw new RuntimeException($this->t('WireGuard: ротация не подтверждена; cron повторит операцию', 'WireGuard: rotation is unconfirmed; cron will retry the operation'));

        $this->answer(
            $this->input['callback_id'] ?? '',
            "🔄 rotated {$r['rotated']}/" . count($clients) . ($r['skipped'] ? ", skipped {$r['skipped']}" : '')
        );
        return $r['oldToNew'];
    }

    // Поднялся ли интерфейс. `awg show wg0` печатает «interface: wg0» только для
    // существующего устройства; при отвергнутом конфиге awg-quick падает на
    // setconf и устройства нет вовсе.
    public function awgLinkUp(): bool
    {
        $out = (string) $this->ssh("{$this->getWGType()} show wg0", $this->getInstanceWG());
        if ($this->sshFailed) {
            // Контейнер недоступен — про интерфейс ничего не известно. Считаем
            // «поднят», чтобы не откатывать корректную правку из-за сбоя ssh.
            return true;
        }
        return (bool) preg_match('~^interface:~m', $out);
    }

    // Применение изменений, которые способны сделать конфиг невалидным
    // (3.0-поля, header protection, ручные диапазоны). amneziawg-tools отвергают
    // весь файл целиком при любой ошибке, а restartWG() успех `up` не проверяет —
    // поэтому: снимок → правка → применение → проверка линка → при неудаче откат.
    //
    // Снимок ограничен amnezia-ключами инстанса, а не всем pac.json: параллельный
    // воркер (cron, другой чат) мог тем временем поменять несвязанные поля, и
    // восстановление целого файла затёрло бы его работу.
    public function awgApplyGuarded(int $page, callable $mutate, bool $silent = false): bool
    {
        return $this->withWireguardUpdate(fn() => $this->awgApplyGuardedLocked($page, $mutate, $silent), null);
    }

    private function awgApplyGuardedLocked(int $page, callable $mutate, bool $silent = false): bool
    {
        $prefix = $this->getInstanceWG(1);
        $snapKeys = [
            $prefix . 'amnezia_keys',
            $prefix . 'amnezia_tpl',
            $prefix . 'amnezia_keepalive',
            $prefix . 'amnezia',
            // Отметку ротации тоже: её ставит $mutate (см. rotateAmneziaKeys), и
            // без отката неудачный setconf оставлял ключи прежними, а таймер —
            // сдвинутым, то есть следующая попытка откладывалась на весь период.
            $prefix . 'amnezia_last_rotation',
        ];
        $before = $this->getPacConf();

        $mutate();
        $expected = $this->getPacConf();
        $this->switchAmnezia($page, false, false, 1, true);

        if ($this->awgLinkUp()) {
            if (!$silent) {
                $this->menu('wg', $page);
            }
            return true;
        }

        if (!$this->restorePacFields($before, $expected, $snapKeys)) throw new RuntimeException($this->t('Настройки Amnezia изменились; откат отменён', 'Amnezia settings changed; rollback cancelled'));
        $this->switchAmnezia($page, false, false, 1, true);
        if (!$silent) {
            // Не alert-попапом: сюда приходят и нажатия кнопок, и ответы на
            // промпты, а в reply() callback_id подменён на message_id меню —
            // answerCallbackQuery по нему молча ничего не покажет.
            $this->update($this->input['chat'], $this->input['message_id'], $this->t('amneziawg отверг конфиг — изменения откачены', 'amneziawg rejected the config; changes rolled back'));
            sleep(3);
            $this->menu('wg', $page);
        }
        return false;
    }

    // Ротация полей из AWG_ROTATE_KEYS (генерация заново по текущему шаблону):
    // I1-I5, S3-S4 и весь блок 3.0, включая HeaderProtectionKey.
    // S1/S2/H1-H4/Jc/Jmin/Jmax и PSK сохраняются — они влияют на совместимость
    // handshake между сервером и клиентами. После ротации клиентам ОБЯЗАТЕЛЬНО
    // нужно перекачать конфиги: рассинхрон HeaderProtectionKey рвёт связь молча.
    public function rotateAmneziaJunk($silent = false, $page = 0)
    {
        return $this->withWireguardUpdate(fn() => $this->rotateAmneziaJunkLocked($silent, $page), null);
    }

    private function rotateAmneziaJunkLocked($silent = false, $page = 0)
    {
        $c = $this->getPacConf();
        $prefix = $this->getInstanceWG(1);
        if (empty($c[$prefix . 'amnezia'])) {
            if (!$silent) {
                $this->menu('wg', $page);
            }
            return;
        }
        $tpl = $c[$prefix . 'amnezia_tpl'] ?? 'standard_2';
        // classic_1 — это 1.x-режим без I1-I5/S3-S4. Ротировать нечего, но
        // обновим last_rotation чтобы maybeRotate не дёргался каждый менеджмент.
        if ($tpl === 'classic_1') {
            $this->pacConfUpdate(function (&$c) use ($prefix) { $c[$prefix . 'amnezia_last_rotation'] = time(); });
            if (!$silent) {
                $this->menu('wg', $page);
            }
            return;
        }
        // Defensive: гарантировать наличие полного набора ключей перед частичной
        // ротацией. Закрывает race-окно между resetAmnezia и завершением
        // switchAmnezia (когда amnezia_keys могут быть пусты, но amnezia=1).
        if (empty($c[$prefix . 'amnezia_keys'])) {
            $this->amneziaKeys();
            $c = $this->getPacConf();
        }
        $has3 = self::amneziaProtoVer($c[$prefix . 'amnezia_keys'] ?? []) === 3;
        // Ротируем по шаблону ТЕКУЩЕЙ версии набора, а не по записанному tpl —
        // в обе стороны. Вверх: header protection можно включить кнопкой поверх
        // набора 2.0, и шаблон *_2 не сгенерировал бы 3.0-поля, ротация просто
        // стёрла бы их. Вниз: набор без блока 3.0 при шаблоне *_3 получил бы
        // его обратно, причём мимо awgApplyGuarded (ветка $has3 ниже).
        if ($has3 !== (substr($tpl, -2) === '_3')) {
            $tpl = self::awgTemplateForVer($tpl, $has3 ? 3 : 2);
        }
        $mutate = function () use ($prefix, $tpl) {
            $this->pacConfUpdate(function (&$c) use ($prefix, $tpl) {
                $new = $this->generateAmneziaKeys($tpl, fn() => $this->genHeaderProtectionKey());
                foreach (self::AWG_ROTATE_KEYS as $k) {
                    if (isset($new[$k])) {
                        $c[$prefix . 'amnezia_keys'][$k] = $new[$k];
                    } else {
                        unset($c[$prefix . 'amnezia_keys'][$k]);
                    }
                }
                // Свежие S3/S4 из 2.0-шаблона могут выпасть меньше 12 — при живом
                // header protection это тихо уронит интерфейс после ротации.
                if (!empty($c[$prefix . 'amnezia_keys']['HeaderProtectionKey'])) {
                    $c[$prefix . 'amnezia_keys'] = self::enforceHeaderProtection($c[$prefix . 'amnezia_keys']);
                }
                $c[$prefix . 'amnezia_last_rotation'] = time();
            });
        };
        if ($has3) {
            $this->awgApplyGuarded($page, $mutate, $silent);
            return;
        }
        $mutate();
        $this->switchAmnezia($page, false, false, 1, $silent);
    }

    // Ленивая проверка таймера ротации. Вызывается из statusWg при открытии
    // wg-меню. Если ротация настроена и срок истёк — silent-перегенерация.
    public function maybeRotateAmnezia()
    {
        $c = $this->getPacConf();
        $prefix = $this->getInstanceWG(1);
        if (empty($c[$prefix . 'amnezia'])) {
            return;
        }
        $period_days = (int) ($c[$prefix . 'amnezia_rotation_period'] ?? 0);
        if ($period_days <= 0) {
            return;
        }
        $last = (int) ($c[$prefix . 'amnezia_last_rotation'] ?? 0);
        if (time() < $last + $period_days * 86400) {
            return;
        }
        // Набор 3.0 вслепую не ротируем: без ответа от контейнера непонятно,
        // переживёт ли новый конфиг setconf, а откатывать будет уже нечем.
        if (self::amneziaProtoVer($c[$prefix . 'amnezia_keys'] ?? []) === 3 && $this->awgSupports3() === null) {
            return;
        }
        $this->rotateAmneziaJunk(true);
    }

    // Шаг cron: maybeRotateAmnezia() исторически дёргался только из statusWg(),
    // то есть ротация случалась ровно тогда, когда админ открывал меню этого
    // инстанса. У второго инстанса меню могут не открывать месяцами — кнопка
    // обещала «rotate: every Nd», а ключи не менялись вовсе. Обходим оба
    // инстанса, как trackWgOnline; сам maybeRotateAmnezia уже проверяет период,
    // включённость amnezia и доступность tools для набора 3.0.
    public function rotateAmneziaCron(): void
    {
        $saved = $this->wg ?? 0;
        foreach ([0, 1] as $inst) {
            try {
                $this->wg = $inst;
                $this->maybeRotateAmnezia();
            } catch (\Throwable $e) {
                error_log('rotateAmneziaCron[' . $inst . ']: ' . $e->getMessage());
            }
        }
        $this->wg = $saved;
    }

    public function setAmneziaRotation($page = 0)
    {
        $c = $this->getPacConf();
        $prefix = $this->getInstanceWG(1);
        $cur = (int) ($c[$prefix . 'amnezia_rotation_period'] ?? 0);
        $last = (int) ($c[$prefix . 'amnezia_last_rotation'] ?? 0);
        $last_str = $last ? date('Y-m-d H:i', $last) : '—';
        $r = $this->send(
            $this->input['chat'],
            $this->t("@{$this->input['username']} введите период авто-ротации junk-полей в днях (0 — выкл).\n\n", "@{$this->input['username']} enter the junk field auto-rotation period in days (0 to disable).\n\n")
            . $this->t("Текущий период: <code>", "Current period: <code>") . ($cur ?: $this->t('выкл', 'off')) . "</code>\n"
            . $this->t("Последняя ротация: <code>$last_str</code>\n\n", "Last rotation: <code>$last_str</code>\n\n")
            . $this->t("Ротируются I1-I5, S3-S4 и весь блок 3.0, включая HeaderProtectionKey. S1/S2/H1-H4/Jc/PSK сохраняются.\n\n", "I1-I5, S3-S4 and the whole 3.0 block, including HeaderProtectionKey, are rotated. S1/S2/H1-H4/Jc/PSK are kept.\n\n")
            . $this->t("⚠️ На наборе 3.0 после каждой ротации клиенты ОБЯЗАНЫ перекачать конфиги: старый HeaderProtectionKey перестанет подходить, и связь пропадёт без сообщения об ошибке.", "⚠️ With a 3.0 set, clients MUST download their configs again after every rotation: the old HeaderProtectionKey stops fitting and the connection drops without an error message."),
            $this->input['message_id'],
            reply: $this->t('введите N или 0', 'enter N or 0'),
        );
        $this->stashReply($r, [
            'start_message'  => $this->input['message_id'],
            'start_callback' => $this->input['callback_id'],
            'callback'       => 'setAmneziaRotationValue',
            // Инстанс в stash — по той же причине, что и в setAmneziaI1.
            'args'           => [$this->wgNum(), $page],
        ]);
    }

    public function setAmneziaRotationValue($text, $inst = 0, $page = 0)
    {
        return $this->withWireguardUpdate(fn() => $this->setAmneziaRotationValueLocked($text, $inst, $page), in_array((int) $inst, [0, 1], true) ? ((int) $inst ? 'wg1' : 'wg') : null);
    }

    private function setAmneziaRotationValueLocked($text, $inst = 0, $page = 0)
    {
        // Легаси-стэш args=[$page] — та же миграционная защита, что и в
        // setAmneziaI1Value.
        if ((int) $inst !== 0 && (int) $inst !== 1) {
            $page = (int) $inst;
            $inst = $this->wgNum();
        }
        $this->selectWG($inst);
        $text = trim($text);
        if (!preg_match('~^\d+$~', $text)) {
            $this->update($this->input['chat'], $this->input['message_id'], $this->t('rotation: введите целое число дней или 0', 'rotation: enter a whole number of days or 0'));
            sleep(3);
            $this->menu('wg', $page);
            return;
        }
        $days = min((int) $text, 365);
        $this->pacConfUpdate(function (&$c) use ($days) {
            $prefix = $this->getInstanceWG(1);
            $c[$prefix . 'amnezia_rotation_period'] = $days;
            if ($days > 0 && empty($c[$prefix . 'amnezia_last_rotation'])) {
                $c[$prefix . 'amnezia_last_rotation'] = time();
            }
        });
        $this->menu('wg', $page);
    }

    public function switchTorrent($page = 0, $restart = false)
    {
        return $this->withWireguardUpdate(fn() => $this->switchTorrentLocked($page, $restart), null);
    }

    private function switchTorrentLocked($page = 0, $restart = false)
    {
        $c = $this->pacConfUpdate(function (&$c) {
            // !empty — на свежей установке (pac.json = {}) ключа ещё нет, и первое
            // же нажатие тумблера сыпало «Undefined array key»; в iptablesWG()
            // фолбэк для этих же ключей давно есть.
            $c[$this->getInstanceWG(1) . 'blocktorrent'] = !empty($c[$this->getInstanceWG(1) . 'blocktorrent']) ? 0 : 1;
            return $c;
        });
        $this->iptablesWG();
        $on = !empty($c[$this->getInstanceWG(1) . 'blocktorrent']);
        $note = $on && !$this->wgTorrentRulesReady() ? 'torrent wg incomplete' : ($on ? 'torrent wg on' : 'torrent wg off');
        $this->answer($this->input['callback_id'], $this->i18n($note), true);
        $this->menu('wg', $page);
    }

    public function wgTorrentRulesReady(): bool
    {
        // Проверяем реально установленные правила, включая после смены ядра.
        // -C у ipp2p бывает ненадёжен; awk нормализует пробелы вывода -S.
        $out = $this->ssh('iptables -S | awk \'NF == 9 && $1 == "-A" && ($2 == "FORWARD" || $2 == "OUTPUT") && $3 == "-p" && ($4 == "tcp" || $4 == "udp") && $5 == "-m" && $6 == "ipp2p" && $7 == "--bit" && $8 == "-j" && $9 == "DROP" { have[$2 " " $4]=1 } END { if (length(have) == 4) print "VPNBOT_TORRENT_READY" }\'', $this->getInstanceWG());
        return !$this->sshFailed && trim((string) $out) === 'VPNBOT_TORRENT_READY';
    }

    public function switchEndpoint($page = 0)
    {
        return $this->withWireguardUpdate(fn() => $this->switchEndpointLocked($page), null);
    }

    private function switchEndpointLocked($page = 0)
    {
        $this->pacConfUpdate(function (&$c) {
            $c[$this->getInstanceWG(1) . 'endpoint'] = $c[$this->getInstanceWG(1) . 'endpoint'] ? 0 : 1;
        });
        $this->menu('wg', $page);
    }

    // Выбор relay для wg/awg-конфигов инстанса: «напрямую» + relay с заданным
    // awg_address (общий стор relay xray). Выбор постоянный (pacconf
    // '{inst}relay') и действует на ВСЕ генерируемые конфиги/QR/download этого
    // инстанса — у wg нет подписок, конфиг статичен, поэтому per-client выбора
    // (как relay-подписки vless) здесь нет. Инстанс — из карты сообщения
    // (wg_msg), как у соседних кнопок wg-меню без инстанса в callback_data.
    public function wgRelayMenu($page = 0)
    {
        $c      = $this->getPacConf();
        $relays = array_filter($c['relays'] ?? [], fn($e) => !empty($e['awg_address']));
        $cur    = (string) ($c[$this->getInstanceWG(1) . 'relay'] ?? '');
        if (empty($relays) && $cur === '') {
            return $this->menu('wg', $page);
        }
        $text[] = "Menu -> " . $this->getTitleWG() . " -> " . $this->i18n('relay');
        $text[] = $this->i18n('wg relay hint');

        $data[] = [
            [
                'text'          => ($this->wgRelay() === null ? '✅ ' : '') . $this->i18n('direct'),
                'callback_data' => $this->cbWG("/setWgRelay $page"),
            ],
        ];
        foreach ($relays as $name => $r) {
            // Имя из одних цифр JSON-декодер делает int-ключом — приводим.
            // Статуса нет: WireGuard — UDP, а проба relay стучит по TCP в
            // адрес VLESS и про этот канал ничего не говорит.
            $name   = (string) $name;
            $data[] = [
                [
                    'text'          => ($cur === $name ? '✅ ' : '') . "🔗 $name: {$r['awg_address']}",
                    'callback_data' => $this->cbWG("/setWgRelay $page $name"),
                ],
            ];
        }
        $data[] = [
            [
                'text'          => $this->i18n('back'),
                'callback_data' => "/menu wg {$this->wgNum()} $page",
            ],
        ];
        $this->update(
            $this->input['chat'],
            $this->input['message_id'],
            implode("\n", $text),
            $data,
        );
    }

    // Пустое/неизвестное имя и relay без awg_address снимают выбор (direct):
    // так же лечится и устаревшая запись после удаления relay.
    public function setWgRelay($page = 0, $name = '')
    {
        return $this->withWireguardUpdate(fn() => $this->setWgRelayLocked($page, $name), null);
    }

    private function setWgRelayLocked($page = 0, $name = '')
    {
        $this->pacConfUpdate(function (&$c) use ($name) {
            $key = $this->getInstanceWG(1) . 'relay';
            $r   = $c['relays'][$name] ?? null;
            if ($name === '' || !is_array($r) || empty($r['awg_address'])) {
                unset($c[$key]);
            } else {
                $c[$key] = $name;
            }
        });
        $this->wgRelayMenu($page);
    }

    // Ключи exchange/blocktorrent — per-instance ('' / 'wg1_'), как их пишут
    // switchExchange/switchTorrent и как их читает start_wg.sh при старте
    // контейнера. Беспрефиксное чтение накатывало на wg1 правила wg: тумблеры
    // в меню wg1 не применялись вовсе, хотя ответ бота показывал новое
    // значение. То же било по restore — import() зовёт iptablesWG() для обоих.
    public function iptablesWG()
    {
        $c      = $this->getPacConf();
        $prefix = $this->getInstanceWG(1);
        $inst   = $this->getInstanceWG();
        $this->ssh('iptables -F', $inst);
        // `iptables -F` сносит ВСЮ таблицу filter, включая FORWARD-правила для
        // tun0, которые ставит start_wg.sh при старте контейнера. Бот их не
        // восстанавливал, поэтому после любого тумблера torrent/exchange (и
        // после import()) они пропадали до пересоздания контейнера. Спасала
        // только политика `-P FORWARD ACCEPT` — при DROP туннель лёг бы, и
        // причина зависела бы от того, дёргали ли меню после старта.
        //
        // -C || -A — идемпотентно: сразу после -F таблица пуста, но метод
        // зовётся и из import() несколько раз подряд.
        //
        // Порядок не важен: tun0 идёт через -A (в хвост), а block_*.sh — через
        // -I (в голову), поэтому фильтры торрента в любом случае проверяются
        // раньше, чем ACCEPT для tun0, и не обходятся им.
        foreach (['-i', '-o'] as $dir) {
            $rule = "FORWARD $dir tun0 -j ACCEPT";
            $this->ssh("iptables -C $rule 2>/dev/null || iptables -A $rule", $inst);
        }
        // Порядок torrent → exchange — как в start_wg.sh, чтобы оба пути
        // приводили таблицу к одинаковому виду.
        // ?? false — на свежей установке pac.json = {} и ключей нет: без
        // фолбэка каждый вызов сыпал «Undefined array key» (ср. getWGType).
        if ($c[$prefix . 'blocktorrent'] ?? false) {
            $this->ssh('bash /block_torrent.sh', $inst);
        }
        if ($c[$prefix . 'exchange'] ?? false) {
            $this->ssh('bash /block_exchange.sh', $inst);
        }
    }
    public function switchExchange($page)
    {
        return $this->withWireguardUpdate(fn() => $this->switchExchangeLocked($page), null);
    }

    private function switchExchangeLocked($page)
    {
        $c = $this->pacConfUpdate(function (&$c) {
            $c[$this->getInstanceWG(1) . 'exchange'] = !empty($c[$this->getInstanceWG(1) . 'exchange']) ? 0 : 1;
            return $c;
        });
        $this->iptablesWG();
        $this->answer($this->input['callback_id'], $this->t('обмен между пользователями ', 'traffic between users ') . ($c[$this->getInstanceWG(1) . 'exchange'] ? $this->t('заблокирован', 'blocked') : $this->t('разблокирован', 'unblocked')), true);
        $this->menu('wg', $page);
    }

    public function blinkmenuswitch()
    {
        $this->pacConfUpdate(function (&$c) {
            $c['blinkmenu'] = !empty($c['blinkmenu']) ? 0 : 1;
        });
        $this->menu('config');
    }

    // Потолок ёмкости QR-кода: version 40, EC level L, бинарный режим.
    // Выше него qrencode просто отказывается кодировать вход.
    public const QR_MAX_BYTES = 2953;

    public function sendQr($name, $code, $title = false)
    {
        $qr      = preg_replace(['~\s+~', '~\(~', '~\)~'], ['_'], $name);
        // $name — сырое имя пира: «../../config/xray» уводил запись и unlink()
        // за пределы /qr. Оставляем только безопасные для имени файла символы.
        $qr      = self::safeFileName($qr, 'qr');
        $code    = (string) $code;
        $caption = (string) ($title ?: $name);
        // Слишком длинный вход qrencode не кодирует ВООБЩЕ: png не создаётся,
        // sendPhoto уходит с несуществующим путём, а unlink() сыпет warning'ом,
        // и пользователь видит просто молчание. Достижимо это стало с
        // шифрованным QUIC Initial в I1 — один этот параметр занимает 2406
        // символов, и awg-конфиг с ним в QR не влезает ни при каком раскладе.
        // Отдаём файлом: конфиг всё равно импортируется и так.
        if (strlen($code) > self::QR_MAX_BYTES) {
            $this->upload("$qr.conf", $code);
            $this->send(
                $this->input['chat'],
                htmlspecialchars($caption) . ' — ' . strlen($code) . $this->t(' байт, в QR не помещается (потолок ', ' bytes, does not fit in a QR code (limit ')
                . self::QR_MAX_BYTES . $this->t('). Отправлено файлом.', '). Sent as a file.')
            );
            return;
        }
        $qr_file = __DIR__ . "/qr/$qr.png";
        exec('qrencode -t png -o ' . escapeshellarg($qr_file) . ' ' . escapeshellarg($code), $out, $rc);
        // qrPeer() зовёт sendQr дважды подряд с ОДНИМ именем (короткая ссылка
        // и полный конфиг) — то есть по одному и тому же пути. Без сброса
        // stat-кэша второй вызов мог бы прочитать размер от первого.
        clearstatcache(true, $qr_file);
        // Отдельно от лимита: qrencode может не отработать и по другой причине
        // (нет бинаря, нет прав на /qr). Без этой проверки отказ выглядел бы
        // так же — тишиной.
        if ($rc !== 0 || !is_file($qr_file) || filesize($qr_file) === 0) {
            @unlink($qr_file);
            $this->upload("$qr.conf", $code);
            $this->send(
                $this->input['chat'],
                htmlspecialchars($caption) . $this->t(' — QR не сгенерировался (qrencode rc=', ': the QR code was not generated (qrencode rc=') . (int) $rc . $this->t('). Отправлено файлом.', '). Sent as a file.')
            );
            return;
        }
        $this->sendPhoto(
            $this->input['chat'],
            curl_file_create($qr_file),
            $caption
        );
        unlink($qr_file);
    }

    public function qrPeer($client)
    {
        $cl      = $client;
        $client  = $this->readClients()[$client];
        $name    = $this->getName($client['interface']);
        // Подпись уходит в sendPhoto с parse_mode=html — имя надо экранировать,
        // иначе фото с именем вида «Home <PC>» не отправляется (Telegram 400).
        $cap     = htmlspecialchars($name);
        if ($this->getWGType() == 'awg') {
            $this->sendQr($name, preg_replace('/^vpn:\/\//', '', $this->getAmneziaShortLink($client)), "$cap for AmneziaVPN");
            $this->sendQr($name, $this->createConfig($client), "$cap for AmneziaWG");
        } else {
            $this->sendQr($name, $this->createConfig($client), "$cap for Wireguard");
        }
        if (($this->getPacConf()['blinkmenu'] ?? false)) {
            $this->delete($this->input['chat'], $this->input['message_id']);
            $this->input['message_id'] = $this->send($this->input['chat'], '.')['result']['message_id'];
            $this->menu('client', "{$cl}_0");
        }
    }

    public function qrSS()
    {
        $ss_link = $this->buildSSLink($this->getHashBot());
        $qr_file = __DIR__ . "/qr/shadowsocks.png";
        exec('qrencode -t png -o ' . escapeshellarg($qr_file) . ' ' . escapeshellarg($ss_link));
        $r = $this->sendPhoto(
            $this->input['chat'],
            curl_file_create($qr_file),
            "<code>$ss_link</code>"
        );
        unlink($qr_file);
        if (($this->getPacConf()['blinkmenu'] ?? false)) {
            $this->delete($this->input['chat'], $this->input['message_id']);
            $this->input['message_id'] = $this->send($this->input['chat'], '.')['result']['message_id'];
            $this->menu('ss');
        }
    }

    public function qrXray($i, $s = false)
    {
        $link    = $this->linkXray($i, $s);
        $qr_file = __DIR__ . "/qr/xray.png";
        exec('qrencode -t png -o ' . escapeshellarg($qr_file) . ' ' . escapeshellarg($link));
        $r = $this->sendPhoto(
            $this->input['chat'],
            curl_file_create($qr_file),
            "<code>$link</code>"
        );
        unlink($qr_file);
        if (($this->getPacConf()['blinkmenu'] ?? false)) {
            $this->delete($this->input['chat'], $this->input['message_id']);
            $this->input['message_id'] = $this->send($this->input['chat'], '.')['result']['message_id'];
            $this->xray();
        }
    }

    // Имя файла для временной выдачи в чат. Один санитайзер на все пути:
    // sendQr() чистил имя жёстко, а upload() строил "/logs/$name" простой
    // конкатенацией, хотя получал ту же строку — имя пира, то есть сырой ввод
    // (renameClient пропускает его через sanitizeConfValue, а та режет лишь
    // \r \n [ ]). Пир с именем «../config/nginx» превращал «скачать конфиг» в
    // file_put_contents('/logs/../config/nginx.conf') + unlink() того же пути:
    // конфиг фронтового nginx сначала затирался, потом удалялся, и внешний 443
    // не поднимался при ближайшем рестарте. php-контейнер работает от root,
    // ./config смонтирован на запись — под удар попадал любой *.conf сборки.
    public static function safeFileName($name, string $fallback = 'file'): string
    {
        $name = preg_replace('~[^\w.-]~u', '_', (string) $name);
        return trim(str_replace('..', '_', (string) $name), '.') ?: $fallback;
    }

    public function upload($name, $code, $chat = false)
    {
        $path = '/logs/' . self::safeFileName($name);
        file_put_contents($path, $code);
        $r = $this->sendFile(
            $chat ?: $this->input['chat'],
            curl_file_create($path),
        );
        unlink($path);
        return $r;
    }

    public function proxy()
    {
        $proxy = trim($this->ssh("getent hosts proxy | awk '{ print $1 }'"));
        $this->createPeer("$proxy/32", 'proxy');
    }

    public function addSubnets($page = 0)
    {
        $this->createPeer(implode(',', $this->getPacConf()['subnets']), 'list');
    }

    // change_server_ip() удалён (аудит 2026-08-18): не вызывался ниоткуда —
    // ни из кода, ни по имени из строки (reply()/cron зовут методы по имени,
    // поэтому проверялось и это). Смена адреса инстанса идёт через reset_wg.sh.

    public function reply()
    {
        // Не используем загруженную в session() копию: параллельный повтор
        // webhook мог получить ту же копию до того, как первый воркер закончил
        // callback. takeReply() перечитывает state под локом и сразу удаляет.
        $state = $this->takeReply($this->input['reply']);
        if (!empty($state)) {
            $callback = $state['callback'];
            // A prompt may have been sent by the previous version before the deployment.
            if ($callback === 'setTimerXr' || $callback === 'saveTrafficXr') {
                $state['args'][] = $callback === 'setTimerXr' ? 'expires' : 'quota';
                $callback = 'previewXrayEdit';
            }
            $this->delete($this->input['chat'], $this->input['reply']);
            // Документ с бэкапом остаётся у администратора, в том числе при
            // отказе проверки или обрыве восстановления.
            if ($callback !== 'importFile') $this->delete($this->input['chat'], $this->input['message_id']);
            $this->protocolReturnMain = !empty($state['protocol_main'])
                && in_array($callback, ['protocolReply', 'protocolOptionReply', 'protocolRelayReply'], true);
            $this->protocolRelayOrigin = $state['protocol_relay'] ?? [];
            $this->managedNodeNavigation = $state['managed_node_navigation'] ?? [];
            // Только message_id: раньше сюда же присваивался callback_id, но
            // ответ на force_reply — это ОБЫЧНОЕ сообщение, никакого
            // callback_query у него нет. В качестве query id уходил message_id,
            // и answer() ниже (а следом и callbackCheck) гарантированно
            // получали «400 query ID is invalid» на каждый ответ на промпт
            // (rename, DNS, MTU…). Сам answer() тоже убран — отвечать не на что.
            $this->input['message_id'] = $state['start_message'];
            // message_id уже указывает на сообщение меню — ответ на промпт
            // (DNS, MTU, имя пира…) применяется к инстансу этого меню.
            if (($mi = $this->getWgMsg()) !== null) {
                $this->wg = (int) $mi;
            }
            // menu() внутри callback должен редактировать start_message.
            // finally обязателен для long-polling: один Bot обслуживает там
            // несколько апдейтов подряд, и флаг не должен утечь в следующий.
            $this->replyMenuEdit = true;
            $previousSource = $this->xrayActionSource;
            if (in_array($callback, ['previewXrayEdit', 'setTimerXr', 'setXrPwd', 'renXrUs', 'saveTrafficXr', 'saveHwidUserLimit', 'extAddSave', 'extRenameSave'], true)) $this->xrayActionSource = (string) ($state['xray_source'] ?? '');
            try {
                $this->{$callback}($this->input['message'], ...$state['args']);
            } catch (Throwable $e) {
                // takeReply() забирает state ДО вызова (иначе повтор webhook
                // выполнит действие дважды), а prompt и ответ уже удалены —
                // повторить нечего. Значит падение обработчика обязано быть
                // видимым: молча потерянный ввод выглядит как «бот съел
                // сообщение и ничего не сделал».
                error_log("reply($callback): " . $e->getMessage());
                $this->send(
                    $this->input['chat'],
                    '❌ ' . $this->i18n('error') . ': ' . htmlspecialchars($e->getMessage(), ENT_QUOTES)
                        . "\n" . $this->i18n('try again')
                );
                $this->menu();
            } finally {
                $this->xrayActionSource = $previousSource;
                $this->replyMenuEdit = false;
                $this->protocolReturnMain = false;
                $this->protocolRelayOrigin = [];
                $this->managedNodeNavigation = [];
            }
        }
    }

    public function addNipdomain()
    {
        $this->addDomain(str_replace('.', '-', $this->ip) . '.nip.io');
    }

    // Регулярка домена — общая с addDomainAlias(): значение уходит в exec
    // (certbot) и в server_name nginx.
    public const DOMAIN_RE = '~^(?=.{4,253}$)([a-z0-9](?:[a-z0-9-]*[a-z0-9])?\.)+[a-z]{2,}$~i';

    public function addDomain($domain, $nomenu = false)
    {
        $domain = trim((string) $domain);
        if (!empty($domain)) {
            // idnAscii() (в отличие от голого idn_to_ascii) не падает на пустой
            // строке и отдаёт false, если intl недоступен. Раньше проверки не
            // было вовсе: невалидное имя давало в pac.json «"domain": false», а
            // потом уезжало в server_name через cloakNginx().
            $ascii = $this->idnAscii($domain);
            $ascii = $ascii === false ? $domain : $ascii;
            if (!preg_match(self::DOMAIN_RE, $ascii)) {
                $this->send($this->input['chat'] ?? '', $this->t("$domain: неверный формат домена", "$domain - wrong domain format"), $this->input['message_id'] ?? null);
                return empty($nomenu) ? $this->menu('config') : null;
            }
            $this->pacConfUpdate(function (&$conf) use ($ascii) {
                $conf['domain'] = $ascii;
            });
            $this->chocdomain($ascii);
            $this->syncManagedSelfHosts();
            $this->reconcileManagedUpstreams();
            $this->setUpstreamDomainOcserv($ascii);
            $this->setUpstreamDomainNaive($ascii);
            $this->cloakNginx();
            $this->telemtWebSync();
        }
        if (empty($nomenu)) {
            sleep(3);
            $this->menu('config');
        }
    }

    // ── Алиасы домена ────────────────────────────────────────────────────
    // Дополнительные домены того же сервера: попадают в SAN LE-серта и в
    // server_name nginx. SNI-роутинг upstream не трогаем — неизвестные хосты
    // и так падают в `default other`. Подписки продолжают выдаваться на
    // основном домене; oc/np/adguard-субдомены — только у основного.
    public function domainAliasPrompt()
    {
        $r = $this->send(
            $this->input['chat'],
            $this->t("@{$this->input['username']} отправьте домен-алиас (дополнительный SAN, маршрутизируется как основной)", "@{$this->input['username']} send alias domain (extra SAN, routed same as main)"),
            $this->input['message_id'],
            reply: $this->t('отправьте домен-алиас', 'send alias domain'),
        );
        $this->stashReply($r, [
            'start_message'  => $this->input['message_id'],
            'start_callback' => $this->input['callback_id'],
            'callback'       => 'addDomainAlias',
            'args'           => [],
        ]);
    }

    public function addDomainAlias($domain)
    {
        $domain = (string) idn_to_ascii(trim((string) $domain));
        // Домен уходит в exec (certbot) и в nginx.conf — принимаем только
        // безопасный синтаксис hostname, никаких shell-метасимволов.
        if (!preg_match(self::DOMAIN_RE, $domain)) {
            $this->send($this->input['chat'], $this->t("$domain: неверный формат домена", "$domain - wrong domain format"), $this->input['message_id']);
            $this->menu('config');
            return;
        }
        $added = $this->pacConfUpdate(function (&$conf) use ($domain) {
            if ($domain === ($conf['domain'] ?? '') || in_array($domain, $conf['domain_aliases'] ?? [], true)) return false;
            $conf['domain_aliases'][] = $domain;
            return true;
        });
        if (!$added) return $this->menu('config');
        // nginx начинает принимать алиас сразу; серт — после «renew SSL».
        $this->cloakNginx();
        $this->send($this->input['chat'], $this->t("алиас добавлен; нажмите «обновить SSL», чтобы он попал в сертификат", "alias added — press «renew SSL» to include it in the certificate"), $this->input['message_id']);
        $this->menu('config');
    }

    public function delDomainAlias($i)
    {
        $this->pacConfUpdate(function (&$conf) use ($i) {
            $aliases = array_values($conf['domain_aliases'] ?? []);
            unset($aliases[(int) $i]);
            $aliases = array_values($aliases);
            if ($aliases) {
                $conf['domain_aliases'] = $aliases;
            } else {
                unset($conf['domain_aliases']);
            }
        });
        $this->cloakNginx();
        $this->menu('config');
    }

    // Домены, на которых бот обещает DNS-эндпоинты AdGuardHome (DoH/DoT):
    // главный плюс алиасы. Оба обслуживаются ОДНИМ server-блоком nginx
    // (cloakNginx кладёт алиасы в server_name) и покрываются одним сертом
    // после «renew SSL», поэтому список для вывода в меню и для подписки
    // общий. Формат каждого алиаса уже провалидирован в addDomainAlias().
    public function dnsDomains($conf = null): array
    {
        $conf    = is_array($conf) ? $conf : $this->getPacConf();
        $domains = array_merge(
            [(string) ($conf['domain'] ?? '')],
            array_values($conf['domain_aliases'] ?? [])
        );
        $domains = array_filter(
            array_map(fn ($d) => trim((string) $d), $domains),
            fn ($d) => $d !== ''
        );
        return array_values(array_unique($domains));
    }

    public function sslip(bool $initialSetup = false)
    {
        require __DIR__ . '/config.php';
        $ip = getenv('IP');
        $r  = $this->send($c['admin'][0], "start $ip");

        $this->input['chat']        = $c['admin'][0];
        $this->input['message_id']  = $r['result']['message_id'] ?? null;
        $this->input['callback_id'] = false;
