    // comment() удалён (аудит 2026-08-18): парный uncomment() жив и
    // используется в cloakNginx(), а сам comment() не вызывался ниоткуда.

    public function uncomment($text, $tag)
    {
        $text = explode("\n", $text);
        foreach ($text as $k => $v) {
            if (preg_match("~#-$tag~", $v)) {
                $text[$k] = "##$tag";
                continue;
            }
            $text[$k] = preg_replace('~#~', '', $v, 1);
        }
        return implode("\n", $text);
    }

    public function deleteSSL($notmenu = false)
    {
        $this->withBackupLock(function () {
            foreach (['cert_private', 'cert_public'] as $name) {
                $file = $this->protocolCertRoot . '/' . $name;
                if ((file_exists($file) || is_link($file)) && !@unlink($file)) {
                    throw new RuntimeException($this->t('Не удалось удалить сертификат', 'Could not remove the certificate'));
                }
            }
            $this->pacConfUpdate(function (&$conf) {
                unset($conf['letsencrypt'], $conf['acme_requested']);
            });
            $this->adguardSync();
            $this->cloakNginx();
            $this->telemtWebSync();
        }, $this->acmeInstallLockWait);
        if (!$notmenu) {
            $this->menu('config');
        }
    }

    public function updateUnitInitConfig()
    {
        $unit = $this->controlUnit('config');
        file_put_contents('/config/unit.json', $unit);
    }

    public function setSSL($name)
    {
        $conf = $this->getPacConf();
        $bundle = '';
        $installed = null;
        switch ($name) {
            case 'letsencrypt':
                try {
                    $this->letsencryptNames($conf);
                } catch (InvalidArgumentException $e) {
                    $this->send($this->input['chat'], $e->getMessage());
                    return $this->menu('config');
                }
                // Порт 80 закрыт firewall: выпуск ведёт служба хоста acme-window,
                // она откроет порт только на время проверки (см. BotAcme).
                if ($this->acmeAgent() && ($target = $this->acmeSelfTarget())) {
                    // Перечитываем: letsencryptNames() мог дописать хеши поддоменов.
                    $this->pacConfUpdate(function (&$conf) { $conf['acme_requested'] = time(); });
                    if (!$this->acmeRequest('renew', $target)) {
                        $this->send($this->input['chat'], '❌ ' . $this->t('запрос службе хоста не записан', 'the request to the host service was not written'));
                        return $this->menu('config');
                    }
                    $this->send($this->input['chat'], '⏳ ' . $this->t(
                        'Запрос передан службе хоста: она откроет порт 80 на время проверки и пришлёт результат отдельным сообщением.',
                        'The request is passed to the host service: it opens port 80 for the check and sends the result as a separate message.'
                    ));
                    return $this->menu('config');
                }
                $out   = ['Install certificate:'];
                $this->update($this->input['chat'], $this->input['message_id'], implode("\n", $out));
                [$conf, $names, $expectedState] = $this->withBackupLock(function () {
                    $conf = $this->getPacConf();
                    $names = $this->letsencryptNames($conf);
                    $conf = $this->getPacConf(); // генерация поддоменов могла дописать настройки
                    return [$conf, $names, ['mode' => $conf['letsencrypt'] ?? '',
                        'certificate' => @hash_file('sha256', $this->protocolCertRoot . '/cert_public') ?: '']];
                }, $this->acmeInstallLockWait);
                [$code, $certbot] = $this->issueLetsencrypt($conf);
                $out = array_merge($out, $certbot);
                if ($code > 0) {
                    $this->send($this->input['chat'], "ERROR\n" . implode("\n", $out));
                    return $this->menu('config');
                }
                $out[] = 'Generate bundle';
                $this->update($this->input['chat'], $this->input['message_id'], implode("\n", $out));
                $installed = $this->installLetsencrypt($conf['domain'], $names, $expectedState);
                break;
            case 'self':
                [$conf, $previousCertificate] = $this->withBackupLock(fn () => [$this->getPacConf(),
                    @hash_file('sha256', $this->protocolCertRoot . '/cert_public') ?: ''], $this->acmeInstallLockWait);
                $r      = $this->request('getFile', ['file_id' => $this->input['file_id']]);
                $path = $r['result']['file_path'] ?? null;
                // URL скачивания содержит токен бота: ошибка сети не должна
                // выводить его в PHP warning. Пользователю — общий отказ ниже.
                $bundle = is_string($path) && $path !== '' ? (string) @file_get_contents($this->file . $path) : '';
                $installed = $this->withBackupLock(function () use ($bundle, $conf, $previousCertificate) {
                    $current = $this->getPacConf();
                    foreach (['domain', 'domain_aliases', 'letsencrypt'] as $field) {
                        if (($current[$field] ?? null) !== ($conf[$field] ?? null)) return false;
                    }
                    if ((@hash_file('sha256', $this->protocolCertRoot . '/cert_public') ?: '') !== $previousCertificate) return false;
                    $current['letsencrypt'] = 'self';
                    unset($current['acme_requested']);
                    return $this->applyCertificateBundle($bundle, $current);
                }, $this->acmeInstallLockWait);
                break;
        }
        if (!($installed ?? $this->applyCertificateBundle($bundle, $conf))) {
            $this->update($this->input['chat'], $this->input['message_id'], $this->t(
                'Не удалось установить сертификат: проверьте ключ, цепочку сертификатов и доступность файлов',
                'Could not install the certificate: check the key, certificate chain and file access'));
        }
        sleep(3);
        $this->menu('config');
    }

    public function controlUnit($url, $method = 'GET', $json = false, $bundle = false)
    {
        $ch = curl_init();
        $opt = [
            CURLOPT_CUSTOMREQUEST    => $method,
            CURLOPT_URL              => "http://localhost/$url",
            CURLOPT_RETURNTRANSFER   => 1,
            CURLOPT_UNIX_SOCKET_PATH => '/var/run/control.unit.sock',
            CURLOPT_TIMEOUT          => 10,
        ];
        if ($json) {
            $opt[CURLOPT_POSTFIELDS] = $json;
        }
        if ($bundle) {
            $opt[CURLOPT_POSTFIELDS] = ['file' => new CURLStringFile($bundle, 'bundle.pem', 'text/plain')];
        }
        curl_setopt_array($ch, $opt);
        $r = curl_exec($ch);
        return $r ?: 'lost connect to unit';
    }

    public function delDomain()
    {
        $this->deleteSSL(1);
        $this->pacConfUpdate(function (&$conf) {
            unset($conf['domain']);
            // Алиасы без основного домена не имеют смысла (серт удалён).
            unset($conf['domain_aliases']);
        });
        $this->setUpstreamDomainOcserv('');
        // Сброс SNI-маршрутов naive (основной поддомен + адреса relay): серт
        // удалён, а строки в map пережили бы удаление домена.
        $this->setUpstreamDomainNaive('');
        $this->chocdomain('');
        $this->adguardSync();
        $this->cloakNginx();
        $this->menu('config');
    }

