    public function setAdKey($key)
    {
        if (!$this->adguardPrivateChat()) return $this->menu('adguard');
        $key = strtolower(trim((string) $key));
        if ($key === '-') {
            $key = ''; // «-» убирает ClientID
        }
        if ($key !== '' && !self::adguardClientIdValid($key)) {
            $this->send($this->input['from'], $this->t('ClientID не принят: строчные латинские буквы, цифры и дефис, до 63 символов. «-» — убрать ClientID.', 'ClientID rejected: lowercase Latin letters, digits and hyphens, up to 63 characters. "-" removes the ClientID.'));
            return $this->menu('adguard');
        }
        $old = (string) (($this->getPacConf() ?: [])['adguardkey'] ?? '');
        $this->pacConfUpdate(function (&$c) use ($key) {
            $c['adguardkey'] = $key;
        });
        // Список разрешённых уже ведётся — меняем в нём прежний ClientID на
        // новый сразу: иначе новый адрес DoH/DoT из меню не работал бы до
        // ручного «заполнить».
        $conf = $this->adguardConf();
        $list = $conf['dns']['allowed_clients'] ?? [];
        if ($old !== $key && is_array($list) && $list) {
            $next = array_values(array_filter($list, static fn($v) => (string) $v !== $old || $old === ''));
            if ($key !== '' && !in_array($key, $next, true)) {
                $next[] = $key;
            }
            if ($next !== array_values($list)) {
                $conf['dns']['allowed_clients'] = $next;
                $this->stopAd();
                $this->adguardWrite($conf);
                $this->startAd();
            }
        }
        $this->menu('adguard');
    }

    // Владелец — первый в списке администраторов: его назначает первое
    // обращение к ничейному боту (auth()) или `php panel.php admin <id>`.
    // Состав администраторов меняет только он. Остальным достаточно было
    // добавить свой второй аккаунт или удалить владельца, чтобы закрепиться
    // либо отобрать бота: любой администратор выгружает xray.json и ключи.
    // В панели личность не подтверждена Telegram — общий пароль даёт войти от
    // имени любого администратора, включая владельца, — поэтому оттуда состав
    // не меняется вовсе.
    public function isOwner(): bool
    {
        $from = $this->input['from'] ?? null;
        // Только целое или строка из цифр: (int) '100abc' и (int) 100.9 дают 100.
        // preg_match, а не ctype_digit: расширения ctype в образе php нет.
        if ($this->transport || !(is_int($from) || (is_string($from) && preg_match('/^\d+$/D', $from))) || (int) $from <= 0) {
            return false;
        }
        $file = __DIR__ . '/config.php';
        if (function_exists('opcache_invalidate')) {
            opcache_invalidate($file);
        }
        require $file;
        $admins = array_values((array) ($c['admin'] ?? []));

        return $admins !== [] && (int) $admins[0] === (int) $from;
    }

    // Кто управляет ботом: ID администраторов для меню настроек, первым —
    // владелец. Видят все администраторы, менять состав может только владелец.
    public function adminListLines(): array
    {
        $file = __DIR__ . '/config.php';
        if (function_exists('opcache_invalidate')) {
            opcache_invalidate($file);
        }
        require $file;
        $from  = $this->transport ? null : ($this->input['from'] ?? null);
        $lines = [$this->t('Администраторы бота (ID Telegram):', 'Bot administrators (Telegram ID):')];
        foreach (array_values((array) ($c['admin'] ?? [])) as $n => $id) {
            if (!is_int($id) && !(is_string($id) && preg_match('/^-?\d+$/D', $id))) {
                continue;
            }
            $marks = [];
            if ($n === 0) {
                $marks[] = $this->t('владелец', 'owner');
            }
            if ($from !== null && (string) $from === (string) $id) {
                $marks[] = $this->t('вы', 'you');
            }
            $lines[] = "<code>$id</code>" . ($marks ? ' — ' . implode(', ', $marks) : '');
        }
        if (count($lines) === 1) {
            $lines[] = $this->t('не заданы — бот никому не принадлежит (php panel.php admin &lt;id&gt;)', 'none: the bot belongs to nobody (php panel.php admin &lt;id&gt;)');
        }
        return $lines;
    }

