    // Отдельный relay-адрес для naiveproxy (по образцу hy_address): только
    // relay с np_address попадают в выбор меню NaiveProxy. В отличие от
    // остальных каналов адрес обязан быть доменом из сертификата origin —
    // клиент naive берёт SNI из хоста ссылки и проверяет по нему сертификат
    // (см. i18n 'naive relay hint'). 0 сносит поле.
    public function setRelayNpAddress($text, $name = '')
    {
        $name = (string) $name;
        $addr = trim((string) $text);
        if (!$this->relayClearInput($addr) && !$this->isHostOrIp($addr)) {
            $this->relayAddressError('np', $name, $addr);
            return;
        }
        $addr   = $this->relayClearInput($addr) ? '' : $addr;
        $exists = $this->pacConfUpdate(function (&$c) use ($name, $addr) {
            if (!isset($c['relays'][$name]) || !is_array($c['relays'][$name])) {
                return false;
            }
            if ($addr === '') {
                unset($c['relays'][$name]['np_address']);
            } else {
                $c['relays'][$name]['np_address'] = $addr;
            }
            return true;
        });
        if (!$exists) {
            $this->relayMenu();
            return;
        }
        $c = $this->getPacConf();
        // SNI-маршрут upstream-nginx: без строки в map трафик relay уедет в
        // cloak вместо caddy (см. naiveSniHosts). Домена нет — и маршрута нет,
        // naive без серта всё равно не работает.
        $domain = (string) ($c['domain'] ?? '');
        $this->setUpstreamDomainNaive($domain);
        // Адрес принят, но в map не попал (голый IP / основной домен) — молча
        // отдать нерабочую ссылку хуже, чем сказать об этом сразу.
        $notice = '';
        if ($addr !== ''
            && !in_array($addr, self::naiveSniHosts($this->getHashSubdomain('np'), $domain, $c), true)
        ) {
            $notice = '⚠️ ' . $this->i18n('naive relay sni skipped');
        }
        $this->relayChannel('np', $name, $notice);
    }

    public function relayNpPortPrompt($name)
    {
        $r = $this->send(
            $this->input['chat'],
            "@{$this->input['username']} " . $this->i18n('enter relay np port'),
            $this->input['message_id'],
            reply: $this->i18n('enter relay np port'),
        );
        $this->stashReply($r, [
            'start_message' => $this->input['message_id'],
            'callback'      => 'setRelayNpPort',
            'args'          => [$name],
        ]);
    }

    // Порт relay для naive: у origin он всегда 443, поэтому карта портов не
    // нужна — либо порт задан явно, либо в ссылке его нет вовсе. 0 — очистка.
    public function setRelayNpPort($text, $name = '')
    {
        $name = (string) $name;
        $p    = self::relayPortInput($text);
        if ($p === '' && !$this->relayClearInput($text)) {
            $this->relayPortError('np', $name);
            return;
        }
        $this->relaySetField('np', $name, function (&$r) use ($p) {
            if ($p === '') {
                unset($r['np_port']);
            } else {
                $r['np_port'] = $p;
            }
        });
    }

    // Удаление — с подтверждением: у relay могут быть пользователи, которые
    // обновляют через него подписку, и выбор в меню WireGuard.
    public function relayDel($name)
    {
        $name = (string) $name;
        $p    = $this->getPacConf();
        if (!isset($p['relays'][$name])) {
            $this->relayMenu();
            return;
        }
        $wg = [];
        foreach (['' => 'WireGuard / AWG 1', 'wg1_' => 'WireGuard / AWG 2'] as $prefix => $label) {
            if ((string) ($p[$prefix . 'relay'] ?? '') === $name) {
                $wg[] = $label;
            }
        }
        $text[] = "Menu -> " . self::esc($this->protocolRelayOrigin['label'] ?? $this->i18n('xray')) . " -> " . $this->i18n('relay')
            . ' -> <b>' . self::esc($name) . '</b>';
        $text[] = $this->t('Удалить relay? После удаления:', 'Delete the relay? After deletion:');
        $text[] = $this->t(
            '• relay-подписки через него перестанут обновляться: сервер ответит «Relay not found», клиенту нужна новая подписка;',
            '• relay subscriptions through it stop refreshing: the server answers "Relay not found", the client needs a new subscription;');
        $text[] = $this->t(
            '• он исчезнет из «relay одной подпиской» и из выбора в меню WireGuard, Hysteria, NaiveProxy и протоколов-модулей;',
            '• it disappears from "relays in one sub" and from the choice in the WireGuard, Hysteria, NaiveProxy and module protocol menus;');
        $text[] = $this->t(
            '• уже выданные ссылки и конфиги с его адресом продолжат вести на relay, пока он пересылает трафик.',
            '• links and configs already issued with its address keep leading to the relay while it forwards traffic.');
        if ($wg) {
            $text[] = $this->t('Сейчас выбран в: ', 'Currently selected in: ') . implode(', ', $wg)
                . $this->t(' — выдача вернётся к прямому адресу сервера.', ' — issuing returns to the direct server address.');
        }
        $data = [
            [['text' => '🗑 ' . $this->t('Да, удалить', 'Yes, delete'), 'callback_data' => "/relayDelOk $name"]],
            [['text' => $this->i18n('back'), 'callback_data' => "/relayEdit $name"]],
        ];
        $this->update($this->input['chat'], $this->input['message_id'], implode("\n", $text), $data);
    }

    public function relayDelOk($name)
    {
        $name = (string) $name;
        // Адрес naive-канала жил ещё и в SNI-map upstream-nginx — оставить там
        // хост удалённого relay значит и дальше отдавать его трафик в caddy.
        $hadNp = $this->pacConfUpdate(function (&$c) use ($name) {
            if (!isset($c['relays'][$name])) {
                return null;
            }
            $hadNp = !empty($c['relays'][$name]['np_address']);
            unset($c['relays'][$name]);
            if (empty($c['relays'])) {
                unset($c['relays']);
            }
            // Выбор relay в меню WireGuard хранится по имени: снимаем его, чтобы
            // relay с тем же именем, созданный позже, не подхватился молча.
            foreach (['relay', 'wg1_relay'] as $key) {
                if ((string) ($c[$key] ?? '') === $name) {
                    unset($c[$key]);
                }
            }
            return $hadNp;
        });
        if ($hadNp) {
            $this->setUpstreamDomainNaive((string) ($this->getPacConf()['domain'] ?? ''));
        }
        $this->relayMenu($hadNp === null ? '' : '🗑 ' . $this->t('Relay удалён: ', 'Relay deleted: ') . '<code>' . self::esc($name) . '</code>');
    }

    // Ввод-«очистка» для полей relay (адреса и маппинги, включая telemt):
    // '0' или пустая строка. Telegram не даёт отправить пустое сообщение
    // реплаем, поэтому единый явный сентинел — 0.
    public static function relayClearInput($text): bool
    {
        return in_array(trim((string) $text), ['', '0'], true);
    }

    // Ввод «порт relay» → нормализованная строка порта или '' (= очистить).
    // Мусор и порт вне 1..65535 трактуем как очистку: у поля нет «ошибочного»
    // состояния — либо валидный порт, либо его нет. '0' здесь и сентинел
    // очистки, и невалидный порт, так что отдельная ветка не нужна.
    public static function relayPortInput($text): string
    {
        $v = trim((string) $text);
        if (!preg_match('~^\d{1,5}$~', $v)) {
            return '';
        }
        $n = (int) $v;
        return ($n >= 1 && $n <= 65535) ? (string) $n : '';
    }

    // Порт relay для канала $ch ('' — vless/telemt, 'awg_', 'hy_', 'np_').
    // Приоритет: явный <ch>port (одно число на весь канал) → <ch>portmap по
    // порту origin → порт origin как есть.
    public static function relayPort($relay, $port, $ch = ''): string
    {
        if (!is_array($relay)) {
            return (string) $port;
        }
        if (($p = self::relayPortInput($relay[$ch . 'port'] ?? '')) !== '') {
            return $p;
        }
        $map = $relay[$ch . 'portmap'] ?? [];
        return (string) (is_array($map) ? ($map[(string) $port] ?? $port) : $port);
    }

    // Строгий разбор карты портов из ввода админа: null, если хоть одна пара
    // не «порт:порт» в 1..65535 — ошибка ввода не должна молча стирать карту
    // или класть в ссылку порт 0/70000.
    public static function relayPortMapInput($text): ?array
    {
        $map = [];
        foreach (explode(',', (string) $text) as $pair) {
            $pair = trim($pair);
            if ($pair === '') {
                continue;
            }
            if (!preg_match('~^(\d{1,5})\s*:\s*(\d{1,5})$~D', $pair, $m)) {
                return null;
            }
            $src = self::relayPortInput($m[1]);
            $dst = self::relayPortInput($m[2]);
            if ($src === '' || $dst === '') {
                return null;
            }
            $map[$src] = $dst;
        }
        return $map ?: null;
    }

    // Parse a 'src:dst,src:dst' port map (real port -> relay port). Both sides
    // must be numeric; empty/blank segments are skipped. Mirrors _parse_port_map
    // in the relay's sub_proxy.py. Invalid pairs are silently dropped here (the
    // bot has no fail-fast restart loop to protect against).
    public function parseRelayPortMap($text)
    {
        $map = [];
        foreach (explode(',', (string) $text) as $pair) {
            $pair = trim($pair);
            if ($pair === '') {
                continue;
            }
            $parts = explode(':', $pair);
            if (count($parts) != 2) {
                continue;
            }
            $src = trim($parts[0]);
            $dst = trim($parts[1]);
            if (!preg_match('~^\d+$~', $src) || !preg_match('~^\d+$~', $dst)) {
                continue;
            }
            $map[$src] = $dst;
        }
        return $map;
    }

    // Swap only the endpoint address+port of the main outbound to the named
    // relay; SNI/serverName/host and DNS domain are left untouched (TLS still
    // terminates on origin via the relay's DNAT). $type is $_GET['t'] (s|si|cl),
    // $index the main outbound/proxy index already resolved in subscription().
    public function applyRelay(&$c, $type, $index, $relay)
    {
        if (empty($relay['address'])) {
            return;
        }
        $map  = $relay['portmap'] ?? [];
        $addr = $relay['address'];
        $port = function ($cur) use ($map) {
            $cur = (string) $cur;
            return isset($map[$cur]) ? (int) $map[$cur] : (int) $cur;
        };

        switch ($type) {
            case 's':
                $ob = &$c['outbounds'][$index]['settings'];
                if (isset($ob['vnext'][0])) {
                    $ob['vnext'][0]['address'] = $addr;
                    if (isset($ob['vnext'][0]['port'])) {
                        $ob['vnext'][0]['port'] = $port($ob['vnext'][0]['port']);
                    }
                } elseif (isset($ob['servers'][0])) {
                    $ob['servers'][0]['address'] = $addr;
                    if (isset($ob['servers'][0]['port'])) {
                        $ob['servers'][0]['port'] = $port($ob['servers'][0]['port']);
                    }
                }
                unset($ob);
                break;
            case 'si':
                $c['outbounds'][$index]['server'] = $addr;
                if (isset($c['outbounds'][$index]['server_port'])) {
                    $c['outbounds'][$index]['server_port'] = $port($c['outbounds'][$index]['server_port']);
                }
                break;
            case 'cl':
                $c['proxies'][$index]['server'] = $addr;
                if (isset($c['proxies'][$index]['port'])) {
                    $c['proxies'][$index]['port'] = $port($c['proxies'][$index]['port']);
                }
                break;
        }
    }

    // Swap the endpoint of the embedded wireguard/awg sub-proxy (named 'awg' in
    // the mihomo config) to the relay's separate WG/AWG endpoint. Independent of
    // applyRelay: the main proxy and the awg proxy can sit behind different
    // relays/ports. No-op unless the relay has awg_address set and an 'awg' proxy
    // exists (mihomo/'cl' configs only). Covers both plain WG and AmneziaWG —
    // they are the same wireguard proxy, differing only by amnezia-wg-option.
    public function applyAwgRelay(&$c, $relay)
    {
        if (empty($relay['awg_address']) || empty($c['proxies']) || !is_array($c['proxies'])) {
            return;
        }
        $map = $relay['awg_portmap'] ?? [];
        foreach ($c['proxies'] as $k => $p) {
            if (($p['name'] ?? '') !== 'awg' || ($p['type'] ?? '') !== 'wireguard') {
                continue;
            }
            $c['proxies'][$k]['server'] = $relay['awg_address'];
            if (isset($c['proxies'][$k]['port'])) {
                $cur = (string) $c['proxies'][$k]['port'];
                $c['proxies'][$k]['port'] = isset($map[$cur]) ? (int) $map[$cur] : (int) $cur;
            }
        }
    }

    public function setSubdomain($text)
    {
        $this->pacConfUpdate(function (&$c) use ($text) {
            if (empty($text)) {
                unset($c['subdomain']);
            } else {
                $c['subdomain'] = array_filter(explode(',', $text), fn($e) => !empty(trim($e)));
            }
        });
        $this->menu('config');
    }

    public function enterPage()
    {
        $r = $this->send(
            $this->input['chat'],
            $this->t("@{$this->input['username']} введите число записей на странице", "@{$this->input['username']} enter limit on page"),
            $this->input['message_id'],
            reply: $this->t('введите число записей на странице', 'enter limit on page'),
        );
        $this->stashReply($r, [
            'start_message' => $this->input['message_id'],
            'callback'      => 'setPage',
            'args'          => [],
        ]);
    }

    public function setPage($text) {
        // Границы обязательны: значение уходит в $this->limit, а тот делит и
        // режет списки. Отрицательное (фолбэк `?: 5` отсекал только ноль)
        // давало отрицательное число страниц и array_slice с отрицательной
        // длиной — списки в меню оказывались пустыми. Верхний предел — чтобы
        // страница не выходила за лимит сообщения Telegram.
        $n = (int) $text;
        if ($n < 1 || $n > 50) {
            $this->send($this->input['chat'] ?? '', $this->t('размер страницы: число от 1 до 50', 'page size: a number from 1 to 50'), $this->input['message_id'] ?? null);
            return $this->menu('config');
        }
        $this->pacConfUpdate(function (&$c) use ($n) { $c['limitpage'] = $n; });
        $this->menu('config');
    }

    public function addAdmin($id)
    {
        // Проверка и здесь, а не только у кнопки: это обработчик ответа на
        // приглашение, и ответить на него может не тот, кто его вызвал.
        if (!$this->isOwner()) {
            return $this->denyAdminChange();
        }
        $file = __DIR__ . '/config.php';
        require $file;
        // $id — сырой текст ответа на промпт. Раньше он клался в config.php как
        // есть, и в списке админов оказывалась строка, из-за чего сравнения
        // приходилось делать нестрогими. Telegram id — положительное целое.
        $id = (int) trim((string) $id);
        if ($id <= 0) {
            $this->send($this->input['chat'], 'wrong id', $this->input['message_id']);

            return $this->menu('config');
        }
        if (in_array($id, array_map('intval', (array) ($c['admin'] ?? [])), true)) {
            return $this->menu('config');
        }
        $c['admin'][] = $id;
        file_put_contents($file, "<?php\n\n\$c = " . var_export($c, true) . ";\n");
        $this->menu('config');
    }

    public function delAdmin($id)
    {
        if (!$this->isOwner()) {
            return $this->denyAdminChange();
        }
        $file = __DIR__ . '/config.php';
        require $file;
        // Тот же класс, что в allowIp, но цена выше: при промахе
        // array_search удалялся admin[0] — ГЛАВНЫЙ администратор, получатель
        // pinBackup, checkVersion и всех уведомлений. Достижимо кнопкой из
        // устаревшего меню и двойным кликом.
        // Строго и по int — как и auth(): нестрогий поиск по разнотипному
        // списку легко попадал не в ту запись.
        $i = array_search((int) $id, array_map('intval', (array) ($c['admin'] ?? [])), true);
        if ($i === false) {
            return $this->menu('config');
        }
        // Последнего админа удалять нельзя. auth() при пустом admin работает по
        // схеме trust-on-first-use и назначает админом автора СЛЕДУЮЩЕГО
        // апдейта — кто бы это ни был. Юзернейм бота публичен, он отвечает на
        // /start, так что «ничейный» бот захватывается одним сообщением:
        // это выгрузка xray.json со всеми uuid и subtoken'ами, выпуск
        // сертификатов, правка маршрутов и nginx-конфигов. Кнопки «delete» в
        // меню идут подряд и подтверждения не имеют — хватало промаха пальцем.
        if (count((array) $c['admin']) <= 1) {
            $this->answer($this->input['callback_id'], $this->t('нельзя удалить последнего администратора', 'cannot remove the last admin'), true);
            return $this->menu('config');
        }
        // Владелец себя не удаляет: владельцем молча стал бы следующий в списке.
        if ($i === 0) {
            $this->answer($this->input['callback_id'], $this->t('нельзя удалить владельца', 'cannot remove the owner'), true);
            return $this->menu('config');
        }
        unset($c['admin'][$i]);
        $c['admin'] = array_values($c['admin']);
        file_put_contents($file, "<?php\n\n\$c = " . var_export($c, true) . ";\n");
        $this->menu('config');
    }

    public function chpsswd($pass)
    {
        if (!$this->adguardPrivateChat()) return $this->menu('adguard');
        $pass = trim((string) $pass);
        if (!self::adguardPasswordValid($pass)) {
            $this->send($this->input['from'], $this->t('Пароль не принят: от 8 до 72 символов (в байтах), без переводов строк.', 'Password rejected: 8 to 72 characters (in bytes), without line breaks.'));
            return $this->menu('adguard');
        }
        if (($c = $this->adguardConf()) === null) {
            $this->send($this->input['from'], $this->t('AdGuardHome.yaml не читается — пароль не изменён.', 'AdGuardHome.yaml cannot be read; the password is unchanged.'));
            return $this->menu('adguard');
        }
        $out[] = 'Restart Adguard Home';
        $this->update($this->input['chat'], $this->input['message_id'], implode("\n", $out));
        try {
            $out[] = $this->stopAd();
            $this->update($this->input['chat'], $this->input['message_id'], implode("\n", $out));
            $c['users'][0]['password'] = self::adguardPasswordHash($pass);
            // Сначала конфиг AdGuard, потом pac.json: при отказе записи бот
            // продолжает показывать пароль, с которым панель действительно пускает.
            if ($this->adguardWrite($c)) {
                $this->pacConfUpdate(function (&$p) use ($pass) {
                    $p['adpswd'] = $pass;
                    $p['adg_panel_epoch'] = bin2hex(random_bytes(16));
                });
            } else {
                $this->send($this->input['from'], $this->t('Не удалось записать AdGuardHome.yaml — пароль не изменён.', 'Could not write AdGuardHome.yaml; the password is unchanged.'));
            }
            $out[] = $this->startAd();
            $this->update($this->input['chat'], $this->input['message_id'], implode("\n", $out));
            sleep(3);
        } finally {
            // A failed restart must not leave the buttonless "Restart Adguard Home" screen.
            $this->menu('adguard');
        }
    }

    public function adguardreset(bool $confirmed = false)
    {
        // Сброс стирает фильтры, клиентов, апстримы и список разрешённых (с
        // опубликованным DoT резолвер после этого открыт всем) — одно
        // случайное нажатие не должно этого делать.
        if (!$confirmed) {
            $this->update($this->input['chat'], $this->input['message_id'], $this->i18n('adg reset confirm'), [
                [['text' => '⚠️ ' . $this->i18n('reset settings'), 'callback_data' => '/adguardreset yes']],
                [['text' => $this->i18n('back'), 'callback_data' => '/menu adguard']],
            ]);
            return;
        }
        $out[] = 'Restart Adguard Home';
        $this->update($this->input['chat'], $this->input['message_id'], implode("\n", $out));
        exec('git -C / checkout config/AdGuardHome.yaml');
        $this->adguardSync();
        $this->cloakNginx();
        sleep(3);
        $this->menu('adguard');
    }

    // ── Настройки AdGuard через его API: без перезапуска и разрыва DNS ─────
    public const ADG_RATE_LIMITS = [0, 20, 100, 300, 500, 700, 900, 1100];
    public const ADG_RETENTION_DAYS = [0, 1, 7, 30, 90];
    public const ADG_UPSTREAM_MODES = ['lb' => 'load_balance', 'parallel' => 'parallel', 'fastest' => 'fastest_addr'];

    // Срок хранения из ответа API (миллисекунды) в днях; 0 — выключено.
    public static function adgRetentionDays(?array $config): int
    {
        return empty($config['enabled']) ? 0 : (int) round((int) ($config['interval'] ?? 0) / 86400000);
    }

    public function adgSettings(string $pick = '')
    {
        $path = 'Menu -> AdGuard -> ' . $this->i18n('adg settings');
        $back = [['text' => $this->i18n('back'), 'callback_data' => $pick === '' ? '/menu adguard' : '/adgSettings']];
        $status = $this->adguardApi('GET', 'status', null, 4);
        $dns    = $status === null ? null : $this->adguardApi('GET', 'dns_info', null, 4);
        if ($status === null || $dns === null) {
            $this->update($this->input['chat'], $this->input['message_id'],
                "$path\n\n⚠️ " . $this->i18n('adg not responding') . ': ' . self::esc($this->adguardApiError), [$back]);
            return;
        }
        $qlog  = self::adgRetentionDays($this->adguardApi('GET', 'querylog/config', null, 4));
        $stats = self::adgRetentionDays($this->adguardApi('GET', 'stats/config', null, 4));
        $days  = fn(int $d) => $d === 0 ? $this->i18n('off') : $d . ' ' . $this->i18n('adg days');
        $rate  = (int) ($dns['ratelimit'] ?? 0);
        $mark  = fn(bool $on) => $on ? '✅ ' : '';
        // Подменю выбора значения.
        if ($pick !== '') {
            [$title, $current, $values, $label] = match ($pick) {
                'rate'  => [$this->i18n('adg rate limit'), $rate, self::ADG_RATE_LIMITS,
                    fn(int $v) => $v === 0 ? $this->i18n('off') : "$v/s"],
                'qlog'  => [$this->i18n('adg query log'), $qlog, self::ADG_RETENTION_DAYS, $days],
                default => [$this->i18n('adg stats keep'), $stats, self::ADG_RETENTION_DAYS, $days],
            };
            $data = [];
            foreach (array_chunk($values, 4) as $chunk) {
                $data[] = array_map(fn(int $v) => ['text' => $mark($v === $current) . $label($v), 'callback_data' => "/adgSet $pick $v"], $chunk);
            }
            $data[] = $this->menuHelpButton('adguard', $pick);
            $data[] = $back;
            $this->update($this->input['chat'], $this->input['message_id'],
                "$path -> $title\n\n" . $this->i18n("adg hint $pick"), $data);
            return;
        }
        $protection = !empty($status['protection_enabled']);
        $paused     = (int) ($status['protection_disabled_duration'] ?? 0);
        $safe       = $this->adguardApi('GET', 'safesearch/status', null, 4);
        $anon       = !empty($this->adguardApi('GET', 'querylog/config', null, 4)['anonymize_client_ip']);
        $mode       = array_search((string) ($dns['upstream_mode'] ?? '') ?: 'load_balance', self::ADG_UPSTREAM_MODES, true) ?: 'lb';
        $onoff      = fn(bool $on) => $this->i18n($on ? 'on' : 'off');
        $data = [
            [['text' => '🛡 ' . $this->i18n('adg protection') . ': ' . $onoff($protection)
                . (!$protection && $paused > 0 ? ' (' . (int) ceil($paused / 60000) . ' min)' : ''),
                'callback_data' => '/adgSet protection ' . ($protection ? 'off' : 'on')]],
            [
                ['text' => '⏸ 10 min', 'callback_data' => '/adgSet protection 10'],
                ['text' => '⏸ 60 min', 'callback_data' => '/adgSet protection 60'],
            ],
            [['text' => $this->i18n('adg safe search') . ': ' . $onoff(!empty($safe['enabled'])),
                'callback_data' => '/adgSet safesearch ' . (!empty($safe['enabled']) ? 'off' : 'on')]],
            [['text' => $this->i18n('adg rate limit') . ': ' . ($rate === 0 ? $this->i18n('off') : "$rate/s"), 'callback_data' => '/adgSettings rate']],
        ];
        $row = [];
        foreach (array_keys(self::ADG_UPSTREAM_MODES) as $key) {
            $row[] = ['text' => $mark($key === $mode) . $this->i18n("adg mode $key"), 'callback_data' => "/adgSet mode $key"];
        }
        $data[] = $row;
        $data[] = [
            ['text' => $this->i18n('adg query log') . ': ' . $days($qlog), 'callback_data' => '/adgSettings qlog'],
            ['text' => $this->i18n('adg stats keep') . ': ' . $days($stats), 'callback_data' => '/adgSettings stats'],
        ];
        $data[] = [['text' => $this->i18n('adg hide ip') . ': ' . $onoff($anon), 'callback_data' => '/adgSet anon ' . ($anon ? 'off' : 'on')]];
        $data[] = $this->menuHelpButton('adguard', 'settings');
        $data[] = $back;
        $this->update($this->input['chat'], $this->input['message_id'], "$path\n\n" . $this->i18n('adg settings hint'), $data);
    }

    // Одна настройка. Значения сверяются со списками допустимых: в API уходит
    // только то, что предлагает меню.
    public function adgSet(string $key, string $value)
    {
        $ok   = null;
        $pick = '';
        switch ($key) {
            case 'protection':
                if (in_array($value, ['on', 'off'], true)) {
                    $ok = $this->adguardApi('POST', 'protection', ['enabled' => $value === 'on', 'duration' => 0]);
                } elseif (in_array($value, ['10', '60'], true)) {
                    $ok = $this->adguardApi('POST', 'protection', ['enabled' => false, 'duration' => (int) $value * 60000]);
                }
                break;
            case 'safesearch':
                if (in_array($value, ['on', 'off'], true)) {
                    $current = $this->adguardApi('GET', 'safesearch/status') ?? [];
                    // Перечень поисковиков берём у самого AdGuard: он растёт от версии к версии.
                    $services = array_fill_keys(array_keys(array_diff_key($current, ['enabled' => 1])), true)
                        ?: array_fill_keys(['bing', 'duckduckgo', 'ecosia', 'google', 'pixabay', 'yandex', 'youtube'], true);
                    $ok = $this->adguardApi('PUT', 'safesearch/settings', ['enabled' => $value === 'on'] + $services);
                }
                break;
            case 'rate':
                $pick = 'rate';
                if (preg_match('~^\d{1,5}$~D', $value) && in_array((int) $value, self::ADG_RATE_LIMITS, true)) {
                    $ok = $this->adguardApi('POST', 'dns_config', ['ratelimit' => (int) $value]);
                }
                break;
            case 'mode':
                if (isset(self::ADG_UPSTREAM_MODES[$value])) {
                    $ok = $this->adguardApi('POST', 'dns_config', ['upstream_mode' => self::ADG_UPSTREAM_MODES[$value]]);
                }
                break;
            case 'qlog':
            case 'stats':
                $pick = $key;
                if (preg_match('~^\d{1,5}$~D', $value) && in_array((int) $value, self::ADG_RETENTION_DAYS, true)) {
                    $path    = $key === 'qlog' ? 'querylog/config' : 'stats/config';
                    $current = $this->adguardApi('GET', $path);
                    if ($current !== null) {
                        $days = (int) $value;
                        // Выключение срок не трогает: AdGuard не принимает интервал короче часа.
                        $body = ['enabled' => $days > 0, 'interval' => $days > 0 ? $days * 86400000 : (int) ($current['interval'] ?? 86400000),
                            'ignored' => array_values((array) ($current['ignored'] ?? []))];
                        if ($key === 'qlog') {
                            $body['anonymize_client_ip'] = !empty($current['anonymize_client_ip']);
                        }
                        $ok = $this->adguardApi('PUT', "$path/update", $body);
                    }
                }
                break;
            case 'anon':
                if (in_array($value, ['on', 'off'], true) && ($current = $this->adguardApi('GET', 'querylog/config')) !== null) {
                    $ok = $this->adguardApi('PUT', 'querylog/config/update', ['enabled' => !empty($current['enabled']),
                        'interval' => (int) ($current['interval'] ?? 86400000), 'ignored' => array_values((array) ($current['ignored'] ?? [])),
                        'anonymize_client_ip' => $value === 'on']);
                }
                break;
        }
        if ($ok === null) {
            $this->send($this->input['from'], '⚠️ ' . $this->i18n('adg not applied') . ': ' . self::esc($this->adguardApiError ?: 'bad value'));
        }
        $this->adgSettings($ok === null ? '' : $pick);
    }

    // Сводка за период хранения статистики: сколько запросов, сколько
    // заблокировано, кто и куда ходит чаще всего.
    public function adgStats()
    {
        if (!$this->adguardPrivateChat()) return $this->menu('adguard');
        $path = 'Menu -> AdGuard -> ' . $this->i18n('adg statistics');
        $back = [[['text' => '🔄 ' . $this->i18n('refresh'), 'callback_data' => '/adgStats']],
            $this->menuHelpButton('adguard', 'statistics'),
            [['text' => $this->i18n('back'), 'callback_data' => '/menu adguard']]];
        $stats = $this->adguardApi('GET', 'stats', null, 6);
        if ($stats === null) {
            $this->update($this->input['chat'], $this->input['message_id'],
                "$path\n\n⚠️ " . $this->i18n('adg not responding') . ': ' . self::esc($this->adguardApiError), $back);
            return;
        }
        // Идентификатор из DoH-адреса → имя пользователя.
        $names = [];
        foreach ((array) (($this->getXray() ?: [])['inbounds'][0]['settings']['clients'] ?? []) as $client) {
            $names[$this->dohClientId((string) ($client['id'] ?? ''))] = (string) ($client['email'] ?? '');
        }
        $total   = (int) ($stats['num_dns_queries'] ?? 0);
        $blocked = (int) ($stats['num_blocked_filtering'] ?? 0);
        $units   = count((array) ($stats['dns_queries'] ?? [])) . ' ' . (($stats['time_units'] ?? '') === 'days' ? 'd' : 'h');
        $text    = [$path, '', $this->i18n('adg period') . ": $units, " . date('Y-m-d H:i'),
            $this->i18n('adg queries') . ": $total",
            $this->i18n('adg blocked') . ": $blocked" . ($total > 0 ? ' (' . round($blocked / $total * 100, 1) . '%)' : ''),
            $this->i18n('adg avg time') . ': ' . round((float) ($stats['avg_processing_time'] ?? 0) * 1000, 1) . ' ms'];
        $top = function (string $title, array $rows, bool $clients = false) use (&$text, $names) {
            $lines = [];
            foreach (array_slice($rows, 0, 5) as $row) {
                foreach ((array) $row as $name => $count) {
                    $name    = (string) $name;
                    $shown   = $clients && ($names[$name] ?? '') !== '' ? $names[$name] : $name;
                    $lines[] = ' ' . (int) $count . ' — <code>' . self::esc(mb_strimwidth($shown, 0, 60, '…')) . '</code>';
                }
            }
            if ($lines) {
                $text[] = '';
                $text[] = "<b>$title</b>";
                $text   = array_merge($text, $lines);
            }
        };
        $top($this->i18n('adg top blocked'), (array) ($stats['top_blocked_domains'] ?? []));
        $top($this->i18n('adg top domains'), (array) ($stats['top_queried_domains'] ?? []));
        $top($this->i18n('adg top clients'), (array) ($stats['top_clients'] ?? []), true);
        $this->update($this->input['chat'], $this->input['message_id'], implode("\n", $text), $back);
    }

    public function guidv4($data = null) {
        // Generate 16 bytes (128 bits) of random data or use the data passed into the function.
        $data = $data ?? random_bytes(16);
        assert(strlen($data) == 16);

        // Set version to 0100
        $data[6] = chr(ord($data[6]) & 0x0f | 0x40);
        // Set bits 6-7 to 10
        $data[8] = chr(ord($data[8]) & 0x3f | 0x80);

        // Output the 36 character UUID.
        return vsprintf('%s%s-%s-%s-%s-%s%s%s', str_split(bin2hex($data), 4));
    }

    // Записи клиентов AdGuard для пользователей Xray: имя в журнале запросов
    // и личная политика. Вызывается на каждое добавление, удаление и
    // переименование пользователя.
    public function adguardXrayClients()
    {
        $xr = $this->getXray();
        $ad = $this->adguardConf();
        // Нечитаемый xray.json или AdGuardHome.yaml — ничего не трогаем:
        // раньше здесь писался конфиг из одного раздела clients.
        if (!is_array($xr) || $ad === null) {
            return;
        }
        $before = $ad;
        $next   = self::adguardMergeClients(
            (array) ($ad['clients']['persistent'] ?? []),
            (array) ($xr['inbounds'][0]['settings']['clients'] ?? []),
            fn(string $uid) => $this->dohClientId($uid),
            date_default_timezone_get(),
        );
        $ad['clients']['persistent'] = $next;
        // Список разрешённых ведётся (не пуст) — держим в нём ровно
        // действующих пользователей. Раньше новый пользователь в список не
        // попадал: его DNS молча отклонялся до ручного «заполнить», а
        // идентификатор удалённого оставался пропуском навсегда.
        $allowed = $ad['dns']['allowed_clients'] ?? null;
        if (is_array($allowed) && $allowed) {
            $ids = [];
            foreach ($next as $client) {
                foreach ((array) ($client['ids'] ?? []) as $id) {
                    if (self::adguardBotClientId((string) $id)) {
                        $ids[(string) $id] = true;
                    }
                }
            }
            $list = array_values(array_filter(array_map('strval', $allowed),
                static fn($v) => !self::adguardBotClientId($v) || isset($ids[$v])));
            foreach (array_keys($ids) as $id) {
                if (!in_array($id, $list, true)) {
                    $list[] = $id;
                }
            }
            // В AdGuard пустой список означает доступ всем. После удаления
            // последнего управляемого клиента сохраняем закрытый режим;
            // явно открытый администратором список сюда не попадает.
            $ad['dns']['allowed_clients'] = $list ?: ['127.0.0.1/32', '::1/128'];
        }
        // Ничего не изменилось — AdGuard не перезапускаем: каждый перезапуск
        // это секунды без DNS у всех пользователей.
        if ($ad == $before) {
            return;
        }
        $this->stopAd();
        try {
            if (!$this->adguardWrite($ad)) {
                throw new RuntimeException($this->t('Не удалось сохранить клиентов DNS', 'Could not save DNS clients'));
            }
        } finally {
            $this->startAd();
        }
    }

    // Идентификатор, который выдаёт бот (dohClientId): «doh-» и 16 hex.
    public static function adguardBotClientId(string $id): bool
    {
        return (bool) preg_match('~^doh-[0-9a-f]{16}$~D', $id);
    }

    // Сводит записи клиентов AdGuard с пользователями Xray, сохраняя всё,
    // что администратор настроил в панели: личные фильтры, блокировку
    // сервисов, апстримы пользователя и клиентов, заведённых вручную.
    // Прежде список пересобирался с нуля на каждое изменение пользователя.
    public static function adguardMergeClients(array $existing, array $xrayClients, callable $dohId, string $timezone): array
    {
        $byUid = [];
        foreach ($existing as $client) {
            if (is_array($client) && isset($client['uid'])) {
                $byUid[(string) $client['uid']] = $client;
            }
        }
        $result = [];
        $names  = [];
        $uids   = [];
        foreach ($xrayClients as $v) {
            $uid = (string) ($v['id'] ?? '');
            if ($uid === '' || isset($uids[$uid])) {
                continue;
            }
            $uids[$uid] = true;
            $client = $byUid[$uid] ?? [
                'safe_search' => [
                    'enabled'    => true,
                    'bing'       => true,
                    'duckduckgo' => true,
                    'google'     => true,
                    'pixabay'    => true,
                    'yandex'     => true,
                    'youtube'    => true,
                ],
                'blocked_services' => [
                    'schedule' => ['time_zone' => $timezone],
                    'ids'      => [],
                ],
                'tags'                        => [],
                'upstreams'                   => [],
                'upstreams_cache_size'        => 0,
                'upstreams_cache_enabled'     => false,
                'use_global_settings'         => true,
                'filtering_enabled'           => false,
                'parental_enabled'            => false,
                'safebrowsing_enabled'        => false,
                'use_global_blocked_services' => true,
                'ignore_querylog'             => false,
                'ignore_statistics'           => false,
            ];
            $client['name'] = (string) ($v['email'] ?? $uid);
            // Производный id, а не uuid: именно он приходит от клиента
            // последним сегментом DoH-пути, и по нему AdGuard сопоставляет
            // per-client политику (см. dohClientId и adgFillAllowedClients).
            // Свои дополнительные идентификаторы записи (IP, MAC) остаются.
            $extra = array_values(array_filter(array_map('strval', (array) ($client['ids'] ?? [])),
                static fn($id) => !self::adguardBotClientId($id)));
            $client['ids'] = array_values(array_unique(array_merge([$dohId($uid)], $extra)));
            // uid — ВНУТРЕННИЙ идентификатор AdGuard, и он обязан быть
            // настоящим UUID: на 16-hex значении парсер конфига падает
            // («invalid UUID length: 16»), AdGuardHome не поднимается
            // вовсе и DNS всей установки ложится. Проверено на рабочем сервере
            // 2026-08-18.
            $client['uid'] = $uid;
            $names[$client['name']] = true;
            $result[] = $client;
        }
        // Клиенты, заведённые в панели вручную: не наши (нет выданного ботом
        // id) и не занимают имя пользователя — имена в AdGuard уникальны.
        foreach ($existing as $client) {
            if (!is_array($client) || isset($uids[(string) ($client['uid'] ?? '')])) {
                continue;
            }
            // Запись удалённого пользователя узнаём по идентификатору: нынешний
            // «doh-…», а у записей прежних версий — 16 hex, его же вид EUI-64
            // или сам UUID. Запись вовсе без идентификаторов AdGuard не примет.
            $ids  = array_map('strval', (array) ($client['ids'] ?? []));
            $ours = preg_grep('~^(?:doh-[0-9a-f]{16}|[0-9a-f]{16}|(?:[0-9a-f]{2}:){7}[0-9a-f]{2}|[0-9a-f]{8}(?:-[0-9a-f]{4}){3}-[0-9a-f]{12})$~i', $ids);
            $name = (string) ($client['name'] ?? '');
            if (!$ids || $ours || $name === '' || isset($names[$name])) {
                continue;
            }
            $names[$name] = true;
            $result[] = $client;
        }
        return $result;
    }

