    public function dnscheck($dns)
    {
        // $dns — до трёх токенов (домен [сервер [ip]]); экранируем каждый,
        // сохраняя разбиение на аргументы, иначе shell-инъекция через ответ.
        $safe = implode(' ', array_map('escapeshellarg', preg_split('~\s+~', trim($dns)) ?: []));
        exec("JSON=1 dnslookup $safe", $out, $code);
        if ($code) {
            $this->update($this->input['chat'], $this->input['message_id'], implode("\n", $out), mode: false);
        } else {
            $this->send($this->input['chat'], "JSON=1 dnslookup $dns\n" . implode("\n", $out), mode: false);
        }
        sleep(3);
        $this->menu('adguard');
    }

    public function addupstream()
    {
        $r = $this->send(
            $this->input['chat'],
            $this->t("@{$this->input['username']} введите адрес апстрима", "@{$this->input['username']} enter address upstream"),
            $this->input['message_id'],
            reply: $this->t('введите адрес апстрима', 'enter address upstream'),
        );
        $this->stashReply($r, [
            'start_message' => $this->input['message_id'],
            'callback'      => 'upstream',
            'args'          => [],
        ]);
    }

    // Запись апстрима, как её понимает AdGuardHome: адрес (tcp/tls/https/
    // h3/quic/sdns, голый IP, «домен/IP:порт») и необязательная привязка к
    // доменам «[/домен/домен2/]адрес». «#» вместо адреса — «для этих доменов
    // брать общие апстримы».
    public static function adguardUpstreamValid(string $url): bool
    {
        if (!preg_match('~^(?:\[/[a-z0-9._*\-/]+/\])?(\S+)$~i', $url, $m) || preg_match('~[\x00-\x20"\'<>\\\\]~', $url)) {
            return false;
        }
        $addr = $m[1];
        if ($addr === '#') {
            return $m[0] !== '#'; // «#» допустим только с привязкой к доменам
        }
        return (bool) preg_match('~^(tcp|udp|tls|https|quic|sdns|h3)://[^\s/]\S*$~i', $addr)
            || filter_var($addr, FILTER_VALIDATE_IP) !== false
            || (bool) preg_match('~^\[?[a-zA-Z0-9:.\-]+]?(:\d{1,5})?$~', $addr);
    }

    // Проба апстрима самим AdGuardHome. '' — отвечает либо проверить нечем
    // (AdGuard не запущен); иначе причина отказа.
    public function adguardUpstreamProbe(string $url): string
    {
        $r = $this->adguardApi('POST', 'test_upstream_dns',
            ['upstream_dns' => [$url], 'bootstrap_dns' => [], 'fallback_dns' => [], 'private_upstream' => []], 25);
        if ($r === null) {
            // 4xx — AdGuard запись разобрал и отверг; нет ответа — не судим.
            return str_starts_with($this->adguardApiError, 'http 4') ? $this->adguardApiError : '';
        }
        foreach ($r as $result) {
            // «WARNING: …» AdGuard ставит апстриму для отдельных доменов,
            // который не знает проверочного имени: для внутреннего DNS это
            // нормально, отказом не считаем.
            if ((string) $result !== 'OK' && !str_starts_with((string) $result, 'WARNING')) {
                return mb_substr((string) $result, 0, 200);
            }
        }
        return '';
    }

    public function upstream($url)
    {
        // AdGuard — резолвер для ВСЕХ клиентов установки, и с нераспознанным
        // апстримом он не стартует. Ошибку при этом никто не увидит: startAd()
        // фоновый. То есть одна опечатка в промпте «enter url» роняла DNS всей
        // сборки. Принимаем ровно то, что понимает сам AdGuard.
        $url = trim((string) $url);
        if (!self::adguardUpstreamValid($url)) {
            $this->send($this->input['chat'], self::esc($url) . $this->t(': неверный формат апстрима', ' - wrong upstream format'), $this->input['message_id']);

            return $this->menu('adguard');
        }
        if (($c = $this->adguardConf()) === null) {
            $this->send($this->input['from'], $this->t('AdGuardHome.yaml не читается — апстрим не добавлен.', 'AdGuardHome.yaml cannot be read; the upstream is not added.'));
            return $this->menu('adguard');
        }
        if (in_array($url, array_map('strval', (array) ($c['dns']['upstream_dns'] ?? [])), true)) {
            $this->send($this->input['from'], self::esc($url) . $this->t(' — такой апстрим уже есть.', ': this upstream already exists.'));
            return $this->menu('adguard');
        }
        // Нерабочий адрес раньше принимался молча: при единственном апстриме
        // это DNS без ответов, при нескольких — задержки на каждом запросе.
        if (($why = $this->adguardUpstreamProbe($url)) !== '') {
            $this->send($this->input['from'], $this->t('Апстрим не добавлен, проверка не прошла: ', 'Upstream not added, the check failed: ') . self::esc("$url — $why"));
            return $this->menu('adguard');
        }
        $out[] = 'Restart Adguard Home';
        $this->update($this->input['chat'], $this->input['message_id'], implode("\n", $out));
        try {
            $out[] = $this->stopAd();
            $this->update($this->input['chat'], $this->input['message_id'], implode("\n", $out));
            $c['dns']['upstream_dns'][] = $url;
            $this->adguardWrite($c);
            $out[] = $this->startAd();
            $this->update($this->input['chat'], $this->input['message_id'], implode("\n", $out));
            sleep(3);
        } finally {
            // A failed restart must not leave the buttonless "Restart Adguard Home" screen.
            $this->menu('adguard');
        }
    }

    public function delupstream($k)
    {
        $c = $this->adguardConf();
        // Номер из старого сообщения мог устареть — удаляем только то, что есть.
        if ($c === null || !isset($c['dns']['upstream_dns'][(int) $k])) {
            return $this->menu('adguard');
        }
        $out[] = 'Restart Adguard Home';
        $this->update($this->input['chat'], $this->input['message_id'], implode("\n", $out));
        try {
            $this->stopAd();
            unset($c['dns']['upstream_dns'][(int) $k]);
            $c['dns']['upstream_dns'] = array_values($c['dns']['upstream_dns']);
            $this->adguardWrite($c);
            $this->startAd();
        } finally {
            // A failed restart must not leave the buttonless "Restart Adguard Home" screen.
            $this->menu('adguard');
        }
    }

    public function startAd()
    {
        return $this->controlAd('start', 'VPNBOT_AD_STARTED');
    }

    public function stopAd()
    {
        return $this->controlAd('stop', 'VPNBOT_AD_STOPPED');
    }

    private function controlAd(string $action, string $marker): string
    {
        if (!$this->protocolModuleEnabled('ad')) return '';
        $script = file_get_contents(__DIR__ . '/adguard_control.sh');
        // Синхронно: запись YAML и следующий запуск допустимы лишь после
        // завершения старого процесса, а не после отправки ему SIGTERM.
        $result = $this->ssh('sh -c ' . escapeshellarg($script) . ' -- ' . $action, 'ad');
        if ($this->sshFailed || trim($result) !== $marker) {
            throw new RuntimeException($this->t('Не удалось остановить или запустить AdGuard', 'Could not stop or start AdGuard'));
        }
        return '';
    }

    public function selfsslInstall()
    {
        $this->setSSL('self');
    }

    public function include($type)
    {
        switch ($type) {
            case 'rulessetlist':
                $r = $this->send(
                    $this->input['chat'],
                    $this->t("@{$this->input['username']} <b>outbound[:behavior]:интервал:URL</b>\n", "@{$this->input['username']} <b>outbound[:behavior]:interval:URL</b>\n")
                        . "<code>proxy:1d:https://example.org/list.srs</code>\n"
                        . $this->t("Каждый источник — с новой строки. Число — секунды; 1h — час, 1d — сутки.\n", "Each source on its own line. A number means seconds; 1h is an hour, 1d a day.\n")
                        . "sing-box: .srs/.json. Mihomo: .yaml/.yml/.txt/.mrs. "
                        . $this->t("Для MRS укажите behavior: domain или ipcidr.\n", "For MRS set behavior: domain or ipcidr.\n")
                        . $this->t("block/reject — блокировать; direct — напрямую; proxy — VPN.\n", "block/reject: block; direct: direct; proxy: VPN.\n")
                        . $this->t("Для Mihomo лучше MRS/YAML: ошибочный TXT может стать пустым списком.\n", "For Mihomo MRS/YAML is better: a malformed TXT may become an empty list.\n")
                        . $this->t("Ссылку https бот проверит сразу и предупредит, если по ней не rule-set.", "The bot checks an https link right away and warns if it is not a rule-set."),
                    $this->input['message_id'],
                    reply: 'outbound[:behavior]:time:URL',
                );
                break;

            case 'datlist':
                // Реестр внешних xray .dat: "name.dat:URL" (по одной на строку).
                $r = $this->send(
                    $this->input['chat'],
                    $this->t("@{$this->input['username']} <b>name.dat:URL</b> — ссылка на xray .dat ", "@{$this->input['username']} <b>name.dat:URL</b>: a link to an xray .dat ")
                        . $this->t("(geosite/geoip-формат). Пример:\n", "(geosite/geoip format). Example:\n")
                        . "<code>dlc.dat:https://github.com/v2fly/domain-list-community/releases/latest/download/dlc.dat</code>\n"
                        . $this->t("Несколько источников — по одному на строку.\n", "Several sources: one per line.\n")
                        . $this->t("Затем в block/warp ссылайтесь: <code>ext:dlc.dat:github</code> ", "Then refer to it in block/warp: <code>ext:dlc.dat:github</code> ")
                        . $this->t("(домены) или <code>extip:zkeenip.dat:akamai</code> (IP).", "(domains) or <code>extip:zkeenip.dat:akamai</code> (IP)."),
                    $this->input['message_id'],
                    reply: 'name.dat:URL',
                );
                break;

            case 'subnetlist':
                // Список IP-подсетей (идёт прямо в ip-поля) — доменные префиксы не применяются.
                $r = $this->send(
                    $this->input['chat'],
                    $this->t("@{$this->input['username']} список IP-подсетей: <b>IPv4/IPv6[/cidr]</b>, ", "@{$this->input['username']} a list of IP subnets: <b>IPv4/IPv6[/cidr]</b>, ")
                        . $this->t("напр. <code>10.0.0.0/24</code>, <code>2001:db8::/32</code>.\n\n", "e.g. <code>10.0.0.0/24</code>, <code>2001:db8::/32</code>.\n\n")
                        . $this->t("<b>Как вводить:</b> в столбик (по одной на строку) или в строку ", "<b>How to enter:</b> one per line, or on one line ")
                        . $this->t("через запятую либо пробел: <code>10.0.0.0/24, 2001:db8::/32</code>.", "separated by commas or spaces: <code>10.0.0.0/24, 2001:db8::/32</code>."),
                    $this->input['message_id'],
                    reply: $this->t('перечислите через запятую', 'list separated by commas'),
                );
                break;

            default:
                // Для доменных списков подсказываем xray-совместимые префиксы
                // маршрутизации. Префиксы обёрнуты в <code> — в Telegram их можно
                // скопировать одним тапом. Каждая запись — с новой строки или через
                // запятую (regexp: не режется по запятой — regex может содержать запятые).
                $hint = in_array($type, ['includelist', 'blocklist', 'warplist'])
                    ? $this->t("\n\n<b>Префиксы</b> (нажмите на слово, чтобы скопировать):\n", "\n\n<b>Prefixes</b> (tap a word to copy it):\n")
                        . $this->t("<code>domain:</code> — домен и все его поддомены, напр. domain:vk.com\n", "<code>domain:</code>: a domain and all its subdomains, e.g. domain:vk.com\n")
                        . $this->t("<code>full:</code> — точное совпадение домена, напр. full:example.com\n", "<code>full:</code>: an exact domain match, e.g. full:example.com\n")
                        . $this->t("<code>keyword:</code> — совпадение по подстроке, напр. keyword:reddit\n", "<code>keyword:</code>: a substring match, e.g. keyword:reddit\n")
                        . $this->t("<code>regexp:</code> — регулярное выражение, напр. regexp:.*\\.ru\$\n", "<code>regexp:</code>: a regular expression, e.g. regexp:.*\\.ru\$\n")
                        . $this->t("без префикса — домен-суффикс; IPv4/IPv6[/cidr] — как есть.\n\n", "no prefix: a domain suffix; IPv4/IPv6[/cidr]: as is.\n\n")
                        . $this->t("<b>Как вводить:</b> в столбик (по одной записи на строку) ", "<b>How to enter:</b> one entry per line ")
                        . $this->t("или в строку через запятую либо пробел, напр. ", "or on one line separated by commas or spaces, e.g. ")
                        . $this->t("<code>domain:vk.com, keyword:reddit</code> или <code>vk.com youtube.com</code>\n", "<code>domain:vk.com, keyword:reddit</code> or <code>vk.com youtube.com</code>\n")
                        . $this->t("Записи <code>regexp:</code> — каждую с новой строки ", "Put each <code>regexp:</code> entry on its own line ")
                        . $this->t("(regex может содержать запятые и пробелы).", "(a regex may contain commas and spaces).")
                    : '';
                // ext:/extip: — только для block/warp (применяются на сервере;
                // на клиенте .dat нет). Сначала .dat добавляется в routes → dat.
                if (in_array($type, ['blocklist', 'warplist'])) {
                    $hint .= $this->t("\n\n<b>Внешние .dat</b> (только на сервере):\n", "\n\n<b>External .dat</b> (server only):\n")
                        . $this->t("<code>ext:</code> — категория доменов из .dat, напр. ext:dlc.dat:github\n", "<code>ext:</code>: a domain category from a .dat, e.g. ext:dlc.dat:github\n")
                        . $this->t("<code>extip:</code> — категория IP из .dat, напр. extip:zkeenip.dat:akamai\n", "<code>extip:</code>: an IP category from a .dat, e.g. extip:zkeenip.dat:akamai\n")
                        . $this->t("Сначала добавьте .dat в routes → dat.", "Add the .dat in routes → dat first.");
                }
                // Имя процесса может содержать пробел («Google Chrome Helper»),
                // имя пакета Android — нет: для пакетов пробел разделяет записи.
                if (in_array($type, ['processlist', 'tunprocess'], true)) {
                    $hint .= $this->t("\n\n<b>Как вводить:</b> в столбик или в строку через запятую. ", "\n\n<b>How to enter:</b> one per line or on one line separated by commas. ")
                        . $this->t("Пробел — часть имени процесса, записи он не разделяет.", "A space is part of a process name and does not separate entries.");
                } elseif (in_array($type, ['packagelist', 'tunpackage'], true)) {
                    $hint .= $this->t("\n\n<b>Как вводить:</b> в столбик или в строку через запятую либо пробел, ", "\n\n<b>How to enter:</b> one per line or on one line separated by commas or spaces, ")
                        . $this->t("напр. <code>org.telegram.messenger com.example.app</code>", "e.g. <code>org.telegram.messenger com.example.app</code>");
                }
                $r = $this->send(
                    $this->input['chat'],
                    $this->t("@{$this->input['username']} перечислите через запятую$hint", "@{$this->input['username']} list separated by commas$hint"),
                    $this->input['message_id'],
                    reply: $this->t('перечислите через запятую', 'list separated by commas'),
                );
                break;
        }
        $this->stashReply($r, [
            'start_message' => $this->input['message_id'],
            'callback'      => 'addInclude',
            'args'          => [$type],
        ]);
    }

    public function addInclude(string $domains, $type)
    {
        if ($type === 'datlist') { $this->addDat($domains); return; }
        $entries = $type === 'rulessetlist'
            ? array_filter(array_map('trim', preg_split('~\r\n|\r|\n~', $domains)))
            : $this->splitRouteInput($domains, !in_array($type, ['processlist', 'tunprocess'], true));
        $lastKey = null; $dups = 0; $merged = 0; $invalid = 0; $added = []; $rejected = []; $off = [];
        if ($entries) {
            $this->changeRouteList($type, function (&$list) use ($entries, $type, &$lastKey, &$dups, &$merged, &$invalid, &$added, &$rejected, &$off) {
                $seen = []; $added = []; $rejected = []; $off = []; $invalid = 0; $dups = 0;
                if ($this->isRouteEntryList($type)) {
                    foreach (array_keys($list) as $key) {
                        if (($canon = $this->routeEntryCanonKey((string) $key)) !== '') $seen[$canon] = $key;
                    }
                }
                foreach ($entries as $entry) {
                    if (in_array($type, ['white', 'deny'], true)) {
                        if (self::ipOrCidr($entry)) $list[] = $entry;
                        else { $invalid++; $rejected[] = $entry; }
                        continue;
                    }
                    $key = $this->isRouteEntryList($type) ? $this->normalizeRouteEntry($entry) : trim($entry);
                    if (!$this->routeListEntryValid($type, $key)) { $invalid++; $rejected[] = $entry; continue; }
                    $canon = $this->isRouteEntryList($type) ? $this->routeEntryCanonKey($key) : '';
                    $lastKey = $seen[$canon] ?? $key;
                    if (($canon !== '' && isset($seen[$canon])) || array_key_exists($key, $list)) {
                        $dups++;
                        // Запись уже есть, но выключена: повторный ввод её не
                        // включает (как и в остальных списках), и без подсказки
                        // это выглядело как «добавил, а не работает».
                        if (($list[$lastKey] ?? true) === false) $off[(string) $lastKey] = true;
                        continue;
                    }
                    $list[$key] = true;
                    $added[] = $key;
                }
                if (in_array($type, ['white', 'deny'], true)) $list = array_values(array_unique($list));
                elseif ($this->isRouteEntryList($type)) ['list' => $list, 'removed' => $merged] = $this->dedupeRouteList($list);
                ksort($list);
            });
        }
        if ($dups) $this->send($this->input['from'], $this->i18n('duplicates skipped') . ": $dups");
        if ($merged) $this->send($this->input['from'], $this->i18n('duplicates merged') . ": $merged");
        if ($off) $this->send($this->input['from'], $this->t("Уже есть в списке, но выключены — включите кнопкой записи:\n", "Already in the list but disabled; enable them with the entry button:\n")
            . implode("\n", array_map(fn($e) => '<code>' . self::esc(mb_strimwidth((string) $e, 0, 80, '…')) . '</code>', array_slice(array_keys($off), 0, 5))));
        // Называем сами записи: по одному числу не понять, что именно не принято.
        if ($invalid) $this->send($this->input['from'], $this->t("Неверных записей пропущено: $invalid. Формат и примеры — routes → Справка.\n", "Invalid entries skipped: $invalid. Format and examples: routes → Help.\n")
            . implode("\n", array_map(fn($e) => '<code>' . self::esc(mb_strimwidth((string) $e, 0, 80, '…')) . '</code>', array_slice($rejected, 0, 5)))
            . ($invalid > 5 ? "\n…" : ''));
        // Недоступный или подменённый источник не просто «не сработает»:
        // sing-box без кеша отказывается запускаться, пока не скачает каждый
        // rule-set профиля. Запись не отклоняем — у клиента сеть другая, — но
        // предупреждаем сразу, а не когда у пользователей перестанет
        // подниматься VPN.
        if ($type === 'rulessetlist') {
            $problems = [];
            foreach (array_slice($added, 0, 5) as $key) {
                $url = self::parseRuleSetKey((string) $key)['url'] ?? '';
                if ($url !== '' && ($why = $this->ruleSetProbe($url)) !== '') $problems[] = self::esc("$url — $why");
            }
            if ($problems) $this->send($this->input['from'], $this->t("⚠️ rule-set не прошёл проверку с сервера. Если источник недоступен и клиентам, ", "⚠️ The rule-set failed the check from the server. If the source is unavailable to clients too, ")
                . $this->t("sing-box с таким профилем не запустится, Mihomo останется без этих правил:\n", "sing-box with this profile will not start, and Mihomo will stay without these rules:\n") . implode("\n", $problems));
        }
        $keys = array_keys($this->getPacConf()[$type] ?? []);
        $index = array_search($lastKey, $keys, true);
        $page = $index === false ? 0 : (int) floor($index / $this->limit);
        $this->backXtlsList($type, $page);
    }

    public function backXtlsList($type, $page = 0)
    {
        switch ($type) {
            case 'includelist':
                // ?? — ключа нет, пока пользователь не тронул proxy-список;
                // строкой ниже он и так читается через !empty().
                $this->pacUpdate($_SESSION['proxylistentry'] ?? null);
                if (!empty($_SESSION['proxylistentry'])) {
                    $this->xtlsproxy($page);
                }
                break;
            case 'blocklist':
                $this->xtlsblock($page);
                break;
            case 'warplist':
                $this->xtlswarp($page);
                break;
            case 'datlist':
                $this->xtlsdat($page);
                break;
            case 'processlist':
                $this->xtlsprocess($page);
                break;
            case 'packagelist':
                $this->xtlsapp($page);
                break;
            case 'subnetlist':
                $this->xtlssubnet($page);
                break;
            case 'rulessetlist':
                $this->xtlsrulesset($page);
                break;
            case 'tunprocess':
                $this->tunprocess($page);
                break;
            case 'tunpackage':
                $this->tunpackage($page);
                break;
            case 'white':
            case 'deny':
                $this->syncDeny();
                $this->denyList($page, $type == 'white' ? 1 : 0);
                break;
        }
    }

    /**
     * Классифицирует запись маршрутизации из pac-списка по xray-совместимому
     * префиксу. Поддерживаются regexp:/keyword:/full:/domain:; ext:/extip: —
     * ссылка на категорию внешнего xray .dat (ext = домен-dat, extip = ip-dat);
     * geosite:/geoip: — категория из штатных geosite.dat/geoip.dat ядра;
     * голая запись — suffix (домен + поддомены), IPv4[/cidr] и IPv6[/cidr] — ip.
     *
     * @return array{kind:string,value:string}
     *         kind ∈ regexp|keyword|full|domain|ext|extip|geosite|geoip|suffix|ip
     */
    public function classifyRouteEntry(string $e): array
    {
        $e = trim($e);
        // ext:/extip: — ссылка на внешний xray .dat (значение = "file.dat:tag").
        // Матчим ПЕРВЫМ: value содержит двоеточие, иначе его перехватит IPv6-ветка.
        if (preg_match('~^(ext|extip):(.*)$~is', $e, $m)) {
            return ['kind' => strtolower($m[1]), 'value' => $m[2]];
        }
        // geosite:/geoip: — встроенные категории ядра. Без этой ветки geoip:cn
        // классифицировался как suffix и уезжал в поле domain[], где xray его не
        // принимает: конфиг отвергается и ядро не стартует.
        //
        // Значение (.*), а не (.+), как и у остальных префиксов: с (.+) запись
        // "geosite:" без категории не матчилась здесь, проваливалась мимо всех
        // веток и возвращалась как suffix со значением "geosite:" — то есть
        // считалась ВАЛИДНЫМ доменом и уезжала в конфиги как domain:geosite:
        // (xray) и domain_suffix "geosite:" (sing-box). С (.*) пустая категория
        // даёт value='' и отсеивается routeEntryUsable, как пустой keyword:.
        if (preg_match('~^(geosite|geoip):(.*)$~is', $e, $m)) {
            return ['kind' => strtolower($m[1]), 'value' => $m[2]];
        }
        // Флаг s: regex-значение теоретически может содержать перевод строки.
        if (preg_match('~^(regexp|keyword|full|domain):(.*)$~is', $e, $m)) {
            $kind  = strtolower($m[1]);
            $value = $m[2];
            // Частый кейс: regexp копируют из JSON-списка, где обратный слэш
            // экранирован (\\.  \\w  \\-). Доменные имена не содержат литеральных
            // бэкслэшей, поэтому схлопываем \\ -> \ — иначе паттерн вида .*\\.ru$
            // в RE2 требует литеральный бэкслэш и не матчит ни один домен.
            if ($kind === 'regexp') {
                $value = str_replace('\\\\', '\\', $value);
            }
            return ['kind' => $kind, 'value' => $value];
        }
        // IPv4[/cidr]: форму мало проверить регекспом — октеты и длину префикса
        // надо валидировать по значению. Прежде сюда проходили 999.1.1.1 и
        // 1.2.3.4/64: такая запись уезжала в ip[], xray её не разбирал и ядро
        // не стартовало — одна опечатка в block-списке роняла весь VPN.
        if (preg_match('~^(\d{1,3}(?:\.\d{1,3}){3})(?:/(\d{1,2}))?$~', $e, $m4)) {
            if (
                filter_var($m4[1], FILTER_VALIDATE_IP, FILTER_FLAG_IPV4) !== false
                && (!isset($m4[2]) || $m4[2] === '' || (int) $m4[2] <= 32)
            ) {
                return ['kind' => 'ip', 'value' => $e];
            }
            // Битый IPv4 доменом быть тоже не может — пусть отсеется как невалидная
            // запись (routeEntryUsable), а не станет doменным суффиксом.
            return ['kind' => 'ip', 'value' => ''];
        }
        // IPv6[/cidr]: регексом надёжно не описать — валидируем адрес через
        // filter_var, отделив опциональный /prefix. Двоеточие в записи —
        // необходимое условие IPv6 (домены/keyword его в этой позиции не имеют).
        if (str_contains($e, ':')) {
            $addr = $e;
            $suffix = '';
            if (preg_match('~^(.+)/(\d{1,3})$~', $e, $mm)) {
                $addr   = $mm[1];
                $suffix = '/' . $mm[2];
                if ((int) $mm[2] > 128) {
                    return ['kind' => 'ip', 'value' => ''];
                }
            }
            if (filter_var($addr, FILTER_VALIDATE_IP, FILTER_FLAG_IPV6) !== false) {
                return ['kind' => 'ip', 'value' => $addr . $suffix];
            }
        }
        return ['kind' => 'suffix', 'value' => $e];
    }

    /**
     * Строит элемент xray-поля "domain" из классифицированной записи либо null,
     * если это IP (его место в поле "ip"). У xray нет префикса keyword: — голая
     * строка в поле domain уже трактуется как substring/keyword-совпадение.
     *
     * Голая запись списка (kind=suffix) отдаётся ИМЕННО как "domain:", а не
     * голой строкой: голая строка в xray — это подстрока, то есть "vk.com"
     * матчит и "myvk.community.org". sing-box (createSrs) и mihomo
     * (clashRules) кладут такую запись в domain_suffix/DOMAIN-SUFFIX, то есть
     * трактуют её как суффикс, — и пользователь, добавивший домен в block,
     * ожидает именно суффикс. Раньше три ядра расходились на одном и том же
     * списке; для keyword: сохраняем совместимую с прежними ядрами голую строку.
     */
    public function xrayDomainToken(array $c): ?string
    {
        switch ($c['kind']) {
            case 'ip':
            case 'extip': // ext ip-dat — его место в поле "ip", не "domain"
            case 'geoip': // встроенная geoip-категория — тоже только в "ip"
                return null;
            case 'keyword': // голая строка совместима и с прежними Xray
                return mb_strtolower($c['value']);
            case 'suffix':
            case 'domain':
                return 'domain:' . $this->hostCanon($c['value']);
            case 'full':
                return 'full:' . $this->hostCanon($c['value']);
            case 'ext': // ext домен-dat: xray принимает "ext:file.dat:tag" в domain[]
                return 'ext:' . $this->extAssetRef($c['value']);
            default: // regexp, full, domain, geosite — xray понимает эти префиксы нативно
                return "{$c['kind']}:{$c['value']}";
        }
    }

    /**
     * Разбирает токен ИЗ ГОТОВОГО xray-конфига (routing.rules[].domain), а не
     * запись pac-списка. Отличие ровно одно, но принципиальное: голая строка в
     * xray означает совпадение по подстроке, то есть keyword, — тогда как в
     * pac-списке голая запись означает суффикс домена.
     *
     * Нужно там, где конфиг перечитывается сам из себя (клиентская пересборка
     * при t=s): без этого keyword-запись без явного префикса на
     * втором проходе классифицировалась бы как suffix и уезжала в конфиг уже
     * как "domain:" — молча меняя правило с подстроки на суффикс.
     */
    public function classifyXrayToken(string $token): array
    {
        $c = $this->classifyRouteEntry($token);
        if ($c['kind'] === 'suffix') {
            $c['kind'] = 'keyword';
        }
        return $c;
    }

    /**
     * Валиден ли ext-указатель "file.dat:tag" для xray. Тег обязателен: xray
     * принимает только форму ext:<файл>:<категория>, а запись без тега (ext:dlc.dat)
     * или с пустым тегом (ext:dlc.dat:) отвергается на разборе конфига — ядро
     * не стартует вовсе. Достижимо обычной опечаткой в block/warp-списке.
     */
    public function extRefValid(string $value): bool
    {
        [$file, $tag] = array_pad(explode(':', $value, 2), 2, null);
        return trim((string) $file) !== '' && trim((string) $tag) !== '';
    }

    /**
     * Пригодна ли классифицированная запись для выдачи в конфиг любого ядра.
     *
     * Отсеивает записи с пустым значением. Это не косметика: опечатка вида
     * "keyword:" отдельной строкой давала пустой токен в xray-поле domain[], где
     * голая строка означает совпадение по подстроке — а пустая подстрока входит
     * в ЛЮБОЙ домен. Весь block-список превращался в «блокировать всё».
     * Симметрично, пустой suffix/regexp/domain и битый IP (classifyRouteEntry
     * отдаёт для них value='') конфиг только ломают.
     */
    public function routeEntryUsable(array $c): bool
    {
        if (in_array($c['kind'], ['suffix', 'domain', 'full'], true)) {
            $host = $this->hostCanon($c['value']);
            return strlen($host) <= 253 && (bool) preg_match('~^[a-z0-9_](?:[a-z0-9_.-]*[a-z0-9_])?$~i', $host)
                && !str_contains($host, '..');
        }
        if (in_array($c['kind'], ['ext', 'extip'], true)) {
            return $this->extRefValid($c['value']);
        }
        return trim((string) $c['value']) !== '';
    }

    public function routeListEntryValid(string $type, string $entry): bool
    {
        if ($type === 'subnetlist') return self::ipOrCidr($entry);
        if (in_array($type, ['white', 'deny'], true)) return self::ipOrCidr($entry);
        if ($type === 'datlist') return preg_match('~^[\w.\-]+\.dat:(https://[^\s]+)$~i', $entry, $m)
            && filter_var($m[1], FILTER_VALIDATE_URL) !== false;
        if ($type === 'rulessetlist') {
            $parsed = self::parseRuleSetKey($entry);
            if ($parsed === null) return false;
            $format = self::ruleSetFormat($parsed['url']);
            return in_array($format, ['srs', 'json', 'yaml', 'yml', 'txt', 'mrs'], true)
                && ($format !== 'mrs' || $parsed['behavior'] !== 'classical');
        }
        if ($this->isRouteEntryList($type)) return $this->routeEntryUsable($this->classifyRouteEntry($entry));
        return trim($entry) !== '' && !preg_match('~[\x00-\x1f]~', $entry);
    }

    public function validateRouteRegexes(array $patterns): bool
    {
        if (!$patterns) return true;
        $file = tempnam(sys_get_temp_dir(), 'route-check-');
        if ($file === false) return false;
        try {
            $config = ['route' => ['rules' => [['domain_regex' => array_values(array_unique($patterns)), 'action' => 'reject']]]];
            if (file_put_contents($file, json_encode($config)) === false) return false;
            // rule-set compile лишь упаковывает regexp, не проверяя RE2.
            // check создаёт маршрутизатор, но не запускает сетевые службы.
            exec('timeout 10 sing-box check -c ' . escapeshellarg($file) . ' >/dev/null 2>&1', $output, $status);
            return $status === 0;
        } finally { @unlink($file); }
    }

    // Все изменения списка читают актуальное состояние под общим PAC-локом.
    // Серверные списки дополнительно держат xray-лок в принятом порядке.
    public function changeRouteList(string $type, callable $edit): bool
    {
        if (!in_array($type, ['blocklist', 'warplist', 'includelist', 'subnetlist', 'rulessetlist', 'datlist',
            'packagelist', 'processlist', 'tunpackage', 'tunprocess', 'white', 'deny'], true)) return false;
        $server = in_array($type, ['blocklist', 'warplist', 'datlist'], true);
        $apply = function () use ($type, $edit, $server) {
            return $this->withLock('pac', function () use ($type, $edit, $server) {
                $before = $this->getPacConf();
                $list = $before[$type] ?? [];
                $edit($list);
                if ($list === ($before[$type] ?? null)) return true;
                $patterns = [];
                if ($this->isRouteEntryList($type)) {
                    foreach ($list as $entry => $on) {
                        if (!$on) continue;
                        $c = $this->classifyRouteEntry((string) $entry);
                        if ($c['kind'] === 'regexp') $patterns[] = $c['value'];
                    }
                }
                if (!$this->validateRouteRegexes($patterns)) {
                    $this->send($this->input['from'], $this->t('Правила не сохранены: ошибка проверки регулярного выражения RE2. Проверьте regexp и повторите.', 'Rules not saved: RE2 regular expression check error. Check regexp and retry.'));
                    return false;
                }
                $conf = $before; $conf[$type] = $list;
                if (!$this->setPacConf($conf)) {
                    $this->send($this->input['from'], $this->t('Не удалось сохранить правила.', 'Could not save the rules.'));
                    return false;
                }
                if ($server) {
                    // datSync удаляет выключенные assets. Сохраняем их inode,
                    // чтобы отказ Xray не оставил прежний конфиг без файлов.
                    $backups = []; $errors = [];
                    if ($type === 'datlist') foreach (glob($this->datDir() . '/*') ?: [] as $file) {
                        if (!is_file($file) || preg_match('~\.\d+\.[0-9a-f]+$~', $file)) continue;
                        $copy = $file . '.' . getmypid() . '.' . uniqid();
                        if (!@link($file, $copy)) { $errors[] = 'asset backup failed'; break; }
                        $backups[$file] = $copy;
                    }
                    $snapshot = $type === 'datlist' && !$errors;
                    if (!$errors) $errors = $this->datSync();
                    foreach (array_keys(array_filter($list)) as $entry) {
                        if ($type === 'datlist' || !empty($before[$type][$entry])) continue;
                        $c = $this->classifyRouteEntry((string) $entry);
                        if (in_array($c['kind'], ['ext', 'extip'], true) && !$this->datFileReady($c['value'])) {
                            $errors[] = $this->t('нет файла ', 'no file ') . $this->datResolve(explode(':', (string) $c['value'], 2)[0])
                                . $this->t(' — сначала добавьте его в routes → dat', ': add it in routes → dat first');
                        } elseif (($missing = $this->datCategoryError($c)) !== null) {
                            $errors[] = $missing;
                        }
                    }
                    if ($errors || $this->xrayUpdateRulesLocked($before) === false) {
                        $restored = true;
                        foreach ($backups as $file => $copy) {
                            if (!@rename($copy, $file)) $restored = false;
                            // Файл не менялся — копия и он один и тот же inode, и
                            // rename() тогда ничего не делает: копия оставалась в
                            // каталоге навсегда, по одной на каждый отказ.
                            clearstatcache(true, $copy);
                            if (is_file($file) && file_exists($copy)) @unlink($copy);
                        }
                        // Файлы, появившиеся за неудачную попытку (скачанный .dat
                        // отвергнутого источника, его отметка об отказе), в
                        // прежнем списке не значатся — убираем их сразу, а не при
                        // следующей удачной синхронизации.
                        if ($snapshot) foreach (glob($this->datDir() . '/*') ?: [] as $file) {
                            if (is_file($file) && !isset($backups[$file]) && !preg_match('~\.\d+\.[0-9a-f]+$~', $file)) @unlink($file);
                        }
                        $restored = $this->setPacConf($before) && $restored;
                        // Причина по каждому файлу: раньше http 404, занятое имя и
                        // отсутствующая категория сводились к одной общей фразе.
                        $why = $errors ? "\n" . implode("\n", $this->datErrorLines($errors)) : '';
                        $this->send($this->input['from'], ($restored
                            ? $this->t('Правила не применены. Проверьте .dat, категории и доступность Xray. Предыдущий список сохранён.', 'Rules not applied. Check .dat, categories and Xray availability. The previous list is kept.')
                            : $this->t('Xray не принял правила; не удалось полностью восстановить список и .dat. Проверьте доступность файлов.', 'Xray did not accept the rules; the list and .dat could not be fully restored. Check that the files are available.')) . $why);
                        return false;
                    }
                    foreach ($backups as $copy) @unlink($copy);
                    // Источник выключен или удалён, а правила на него остались:
                    // без файла они в конфиг не попадают — говорим об этом.
                    if ($type === 'datlist') {
                        $left = [];
                        foreach (array_diff($this->datEnabledNames($before), $this->datEnabledNames($conf)) as $gone) {
                            if (($n = $this->datRefCount($conf, $gone)) > 0) $left[] = self::esc("$gone — $n");
                        }
                        if ($left) $this->send($this->input['from'],
                            $this->t("⚠️ На отключённый .dat ссылаются включённые правила block/WARP — они больше не действуют:\n", "⚠️ Enabled block/WARP rules refer to a disabled .dat; they no longer apply:\n")
                            . implode("\n", $left));
                    }
                }
                return true;
            });
        };
        return $server ? $this->withLock('xray', $apply) : $apply();
    }

    /**
     * Раскладывает pac-список (ключ=>bool) на xray-поля domain/ip с учётом
     * префиксов маршрутизации.
     *
     * @return array{domain:array,ip:array}
     */
    public function listToXrayRules(array $list, bool $requireAssets = true): array
    {
        $domain = $ip = [];
        foreach (array_keys(array_filter($list)) as $e) {
            $c = $this->classifyRouteEntry($e);
            // Пустое значение префикса / битый IP — конфиг сломается или, хуже,
            // пустой keyword совпадёт со всеми доменами. Отсекаем до раскладки.
            if (!$this->routeEntryUsable($c)) {
                continue;
            }
            // ext:/extip: ссылаются на внешний .dat — не пишем ссылку в серверный
            // конфиг, пока файл не скачан, иначе xray упадёт на отсутствующем asset.
            if ($requireAssets && in_array($c['kind'], ['ext', 'extip'], true) && !$this->datFileReady($c['value'])) {
                continue;
            }
            // geosite:/geoip: — те же asset-файлы, только с фиксированными
            // именами: образ xray их не содержит (xray.dockerfile их удаляет), а
            // XRAY_LOCATION_ASSET указывает на /logs/geodata с одними лишь
            // скачанными datlist-файлами. Без этой проверки запись
            // «geosite:category-ads-all» уезжала в конфиг, ядро падало на
            // «failed to load geosite», а запись оставалась в pac.json — каждый
            // рестарт писал тот же конфиг, самовосстановления не было.
            if ($requireAssets && in_array($c['kind'], ['geosite', 'geoip'], true)
                && !$this->datFileReady(self::CORE_DAT[$c['kind']])
            ) {
                continue;
            }
            if ($c['kind'] == 'ip') {
                $ip[] = $this->ipCanon($c['value']);
            } elseif ($c['kind'] == 'extip') {
                $ip[] = 'ext:' . $this->extAssetRef($c['value']); // ext ip-dat в поле ip[]
            } elseif ($c['kind'] == 'geoip') {
                $ip[] = "geoip:{$c['value']}"; // встроенная категория — поле ip[]
            } else {
                $domain[] = $this->xrayDomainToken($c);
            }
        }
        // Разные по написанию, но одинаковые по смыслу записи (1.2.3.4 и
        // 1.2.3.4/32, vk.com и domain:vk.com) дают здесь один и тот же токен —
        // в конфиг он должен попасть однажды.
        return [
            'domain' => array_values(array_unique($domain)),
            'ip'     => array_values(array_unique($ip)),
        ];
    }

    // PAC-список означает ИЛИ доменов/IP. Готовые правила шаблона имеют
    // собственный порядок и AND-условия: их нельзя группировать по outbound.
    public function xrayRouteLists(array $rules, array $pac): array
    {
        $lists = ['~pac~' => 'includelist', '~block~' => 'blocklist', '~warp~' => 'warplist', '~subnet~' => 'subnetlist'];
        $result = [];
        foreach ($rules as $rule) {
            $variants = [$rule];
            foreach (['domain', 'ip'] as $field) {
                $token = $rule[$field] ?? null;
                if (!is_string($token) || !isset($lists[$token])) continue;
                $buckets = ['domain' => [], 'ip' => []];
                foreach (array_keys(array_filter($pac[$lists[$token]] ?? [])) as $entry) {
                    $c = $this->classifyRouteEntry((string) $entry);
                    if (!$this->routeEntryUsable($c) || in_array($c['kind'], ['ext', 'extip'], true)) continue;
                    if ($c['kind'] === 'ip') $buckets['ip'][] = $this->ipCanon($c['value']);
                    elseif ($c['kind'] === 'geoip') $buckets['ip'][] = 'geoip:' . $c['value'];
                    else $buckets['domain'][] = $this->xrayDomainToken($c);
                }
                $next = [];
                foreach ($variants as $variant) {
                    unset($variant[$field]);
                    foreach ($buckets as $target => $values) {
                        // Явное условие второго поля не расширяем: оно задаёт
                        // пересечение, а не ещё один элемент PAC-списка.
                        if (!$values || ($target !== $field && isset($variant[$target]))) continue;
                        $next[] = $variant + [$target => array_values(array_unique($values))];
                    }
                }
                $variants = $next;
            }
            foreach ($variants as $variant) {
                foreach (['domain', 'ip'] as $field) if (isset($variant[$field]) && !$variant[$field]) unset($variant[$field]);
                $conditions = array_diff_key($variant, array_flip(['type', 'outboundTag', 'balancerTag', 'ruleTag']));
                if (array_filter($conditions)) $result[] = $variant;
            }
        }
        return $result;
    }

    /**
     * Канонический вид IP-записи: одинаковые адреса, записанные по-разному,
     * дают одну строку. IPv6 сжимается и опускается в нижний регистр
     * (2001:0DB8:0000::1 -> 2001:db8::1), host-маска (/32 у IPv4, /128 у IPv6)
     * отбрасывается — 1.2.3.4 и 1.2.3.4/32 это один и тот же одиночный адрес.
     *
     * Сеть НЕ пересчитывается: 1.2.3.4/24 остаётся как введено, а не
     * превращается в 1.2.3.0/24. Привести её «правильно» значило бы молча
     * поменять смысл записи за пользователя.
     */
    public function ipCanon(string $ip): string
    {
        $ip     = trim($ip);
        $prefix = null;
        if (preg_match('~^(.+)/(\d{1,3})$~', $ip, $m)) {
            $ip     = $m[1];
            $prefix = (int) $m[2];
        }
        if (str_contains($ip, ':') && ($bin = @inet_pton($ip)) !== false) {
            $ip = inet_ntop($bin);
        }
        $host = str_contains($ip, ':') ? 128 : 32;
        if ($prefix === null || $prefix === $host) {
            return $ip;
        }
        return "$ip/$prefix";
    }

    /**
     * Дописывает host-маску к «голому» IP для форматов, требующих обязательный
     * CIDR (sing-box ip_cidr, mihomo IP-CIDR/IP-CIDR6). Уже указанный /prefix не
     * трогаем. IPv6 -> /128, IPv4 -> /32.
     *
     * Адресная часть проходит через ipCanon, иначе 1.2.3.4 и 1.2.3.4/32 дают
     * два разных элемента ip_cidr, и array_unique их не схлопнет.
     */
    public function ipWithCidr(string $ip): string
    {
        $ip = $this->ipCanon($ip);
        if (str_contains($ip, '/')) {
            return $ip;
        }
        return $ip . (str_contains($ip, ':') ? '/128' : '/32');
    }

    /**
     * Канонический вид hostname для сравнения: punycode + нижний регистр,
     * завершающая точка отброшена (vk.com. — та же зона, что vk.com).
     *
     * Точку режем ДО idn_to_ascii: пустая последняя метка нарушает IDNA, и
     * функция вернула бы false на совершенно нормальном имени.
     */
    public function hostCanon(string $host): string
    {
        $host = rtrim(trim($host), '.');
        // Сюда ходит и отрисовка меню списка (кнопка «схлопнуть дубли»), а intl
        // есть не в каждой сборке php: без него обходимся без punycode —
        // unicode-домены схлопнутся лишь при точном совпадении, — но меню
        // обязано открыться. Симметрично routeEntryLabel(), которая по той же
        // причине не полагается на idn_to_utf8() безусловно.
        $a = $this->idnAscii($host);
        return mb_strtolower($a === false ? $host : $a);
    }

    /**
     * Ключ, по которому две записи маршрутизации считаются одной и той же.
     * НЕ хранится и НЕ показывается: в списке остаётся форма пользователя
     * (её же показывает routeEntryLabel), канон нужен только для сравнения —
     * поэтому старые записи в pac.json не нуждаются в миграции.
     *
     * Одинаковыми считаются:
     *   vk.com == domain:vk.com == VK.com == vk.com.   (после выравнивания
     *       xray голая запись и domain: означают один и тот же суффикс)
     *   1.2.3.4 == 1.2.3.4/32 ; 2001:DB8::1 == 2001:db8::1
     *   keyword:Reddit == keyword:reddit ; geoip:CN == geoip:cn
     * Разными остаются full: и domain: (exact-match против суффикса) и любые
     * два regexp:, отличающиеся регистром — RE2 регистрозависим, regexp:VK и
     * regexp:vk матчат разное.
     *
     * Пустая строка означает «канона нет» (пустой префикс, битый IP): такие
     * записи схлопывать не с чем, их отсеивает routeEntryUsable на выдаче.
     */
    public function routeEntryCanonKey(string $e): string
    {
        $c = $this->classifyRouteEntry($e);
        if (!$this->routeEntryUsable($c)) {
            return '';
        }
        $v = trim($c['value']);
        switch ($c['kind']) {
            case 'ip':
                return 'i:' . $this->ipCanon($v);
            case 'regexp':
                return 'r:' . $v;
            case 'keyword':
                return 'k:' . mb_strtolower($v);
            case 'geosite':
                return 'gs:' . mb_strtolower($v);
            case 'geoip':
                return 'gi:' . mb_strtolower($v);
            // ext:/extip: — ссылка file.dat:tag; xray сам приводит категорию к
            // нижнему регистру при чтении .dat, так что регистр тега не значим.
            case 'ext':
            case 'extip':
                [$file, $tag] = explode(':', $this->extAssetRef($v), 2);
                return ($c['kind'] === 'ext' ? 'x:' : 'xi:') . $file . ':' . mb_strtolower($tag);
            case 'full':
                return 'f:' . $this->hostCanon($v);
            default: // domain и голая запись (suffix) — один и тот же суффикс
                return 'd:' . $this->hostCanon($v);
        }
    }

    /**
     * Списки маршрутизации, записи которых сравнимы по смыслу
     * (routeEntryCanonKey). Остальные списки хранят не хосты, а URL правил и
     * имена процессов/пакетов — доменный канон к ним неприменим.
     */
    public const ROUTE_ENTRY_LISTS = ['blocklist', 'warplist', 'includelist', 'subnetlist'];

    public function isRouteEntryList(string $type): bool
    {
        return in_array($type, self::ROUTE_ENTRY_LISTS, true);
    }

    /**
     * Схлопывает семантические дубли в pac-списке (ключ => вкл/выкл).
     *
     * Победителем остаётся более явная форма (domain:vk.com берёт верх над
     * vk.com): явный префикс читается одинаково всеми тремя ядрами. Состояние
     * объединяется по ИЛИ — включённая копия не должна пропасть из-за
     * выключенного дубля.
     *
     * @return array{list:array,removed:int}
     */
    public function dedupeRouteList(array $list): array
    {
        $winner = []; // канон => ключ, оставленный в списке
        $out     = [];
        $removed = 0;
        foreach ($list as $k => $on) {
            $k     = (string) $k;
            $canon = $this->routeEntryCanonKey($k);
            if ($canon === '') {
                $out[$k] = $on; // канона нет — сравнивать не с чем
                continue;
            }
            if (!isset($winner[$canon])) {
                $winner[$canon] = $k;
                $out[$k]        = (bool) $on;
                continue;
            }
            $removed++;
            $prev = $winner[$canon];
            $on   = ((bool) $on) || $out[$prev];
            if ($this->routeEntryExplicit($k) && !$this->routeEntryExplicit($prev)) {
                unset($out[$prev]);
                $winner[$canon] = $k;
                $out[$k]        = $on;
            } else {
                $out[$prev] = $on;
            }
        }
        return ['list' => $out, 'removed' => $removed];
    }

    /**
     * Записана ли запись с явным префиксом (domain:/full:/keyword:/…), а не
     * голым хостом. Используется при выборе победителя среди дублей.
     */
    public function routeEntryExplicit(string $e): bool
    {
        return $this->classifyRouteEntry($e)['kind'] !== 'suffix';
    }

    /**
     * Нормализует запись маршрутизации перед сохранением в pac-список:
     * hostname-часть прогоняется через idn_to_ascii (punycode), префикс
     * сохраняется. Значения regexp:/keyword: не нормализуются (это regex/подстрока).
     */
    /**
     * idn_to_ascii, безопасный к пустой строке и к отсутствию intl.
     *
     * В PHP 8 idn_to_ascii('') бросает ValueError («must not be empty»), а не
     * возвращает false — то есть запись «domain:» или «full:» без значения
     * роняла ФАТАЛОМ весь обработчик сообщения: бот молча переставал отвечать
     * на добавление в список. В контейнере intl загружен, поэтому вылезало
     * только в бою; в тестах, где idn_to_ascii подменяют полифиллом, — нет.
     *
     * Пустое значение здесь законно: classifyRouteEntry отдаёт value='' для
     * префикса без содержимого, а отсеивает такие записи routeEntryUsable
     * ПОСЛЕ нормализации.
     */
    public function idnAscii(string $host)
    {
        if ('' === trim($host) || !function_exists('idn_to_ascii')) {
            return false; // вызывающий подставит исходное значение
        }

        return idn_to_ascii($host);
    }

    /**
     * Обратная сторона idnAscii() — для показа записи пользователю.
     *
     * Опаснее, чем кажется: routeEntryLabel() зовут на КАЖДУЮ кнопку меню
     * списка, и записи «domain:»/«full:» без значения в старых списках уже
     * лежат (до правки addInclude они туда проходили). ValueError из
     * idn_to_utf8('') валил бы не добавление, а само открытие меню block/warp.
     */
    public function idnUtf8(string $host)
    {
        if ('' === trim($host) || !function_exists('idn_to_utf8')) {
            return false;
        }

        return idn_to_utf8($host);
    }

    public function normalizeRouteEntry(string $e): string
    {
        $c = $this->classifyRouteEntry($e);
        switch ($c['kind']) {
            case 'regexp':
            case 'keyword':
            case 'ext':   // ext:/extip: — ссылка на .dat (file.dat:tag), не hostname
            case 'extip':
            case 'geosite': // категория ядра, а не доменное имя — punycode неприменим
            case 'geoip':
                return "{$c['kind']}:{$c['value']}";
            case 'ip':
                return $c['value'];
            case 'full':
            case 'domain':
                $v = $this->idnAscii($c['value']);
                return "{$c['kind']}:" . ($v === false ? $c['value'] : $v);
            default: // suffix
                $v = $this->idnAscii($c['value']);
                return $v === false ? $c['value'] : $v;
        }
    }

    /**
     * Разбивает пользовательский ввод списка на записи: по переводам строк, затем
     * по запятым и пробелам — КРОМЕ записи regexp:, которая забирает остаток
     * строки (regex может содержать и запятые, напр. a{1,3}, и пробелы). Пустые
     * записи отбрасываются.
     *
     * Пробел — разделитель наравне с запятой: в домене, адресе и имени пакета
     * его быть не может. Раньше «vk.com youtube.com» одной строкой отклонялось
     * целиком как одна неверная запись, а в списке package сохранялось одной
     * записью, которая не совпадает ни с чем. $spaces = false — для списков,
     * где пробел бывает частью значения (имя процесса: «Google Chrome Helper»).
     */
    public function splitRouteInput(string $input, bool $spaces = true): array
    {
        $out = [];
        foreach (preg_split('~\r\n|\r|\n~', $input) as $line) {
            $line = trim($line);
            if ($line === '') {
                continue;
            }
            if (preg_match('~^regexp:~i', $line)) {
                $out[] = $line;
                continue;
            }
            $parts = explode(',', $line);
            foreach ($parts as $i => $part) {
                // regexp: поглощает остаток строки — regex может содержать запятые.
                if (preg_match('~^\s*regexp:~i', $part)) {
                    $rest = trim(implode(',', array_slice($parts, $i)));
                    if ($rest !== '') {
                        $out[] = $rest;
                    }
                    break;
                }
                $part = trim($part);
                if ($part === '') {
                    continue;
                }
                if (!$spaces) {
                    $out[] = $part;
                    continue;
                }
                $words = preg_split('~\s+~u', $part);
                foreach ($words as $j => $word) {
                    // regexp: после пробела тоже забирает остаток — вместе с
                    // хвостом строки за следующими запятыми.
                    if (preg_match('~^regexp:~i', $word)) {
                        $rest = trim(implode(' ', array_slice($words, $j)) . (isset($parts[$i + 1]) ? ',' . implode(',', array_slice($parts, $i + 1)) : ''));
                        $out[] = $rest;
                        break 2;
                    }
                    $out[] = $word;
                }
            }
        }
        return $out;
    }

    /**
     * Человекочитаемая подпись записи маршрутизации для кнопок меню: punycode
     * разворачивается обратно в unicode, но ТОЛЬКО в hostname-части — префикс
     * сохраняется как есть.
     *
     * Раньше в idn_to_utf8() уезжала вся строка целиком, включая префикс. Для
     * regexp:/keyword:/ext: это не доменное имя, и IDNA возвращает false, как
     * только строка нарушает его ограничения — например, метка длиннее 63
     * символов (обычный regexp без точек), — а false приводится к '' и Telegram
     * отклоняет ВСЁ сообщение (текст кнопки не может быть пустым): меню
     * block/warp переставало открываться. Симметрично normalizeRouteEntry(),
     * которая на записи уже применяет префикс-осведомлённый idn_to_ascii().
     */
    public function routeEntryLabel(string $e): string
    {
        $c = $this->classifyRouteEntry($e);
        switch ($c['kind']) {
            case 'regexp':
            case 'keyword':
            case 'ext':
            case 'extip':
            case 'geosite':
            case 'geoip':
            case 'ip':
                return $e;
            case 'full':
            case 'domain':
                $v = $this->idnUtf8($c['value']);
                return "{$c['kind']}:" . ($v === false ? $c['value'] : $v);
            default: // suffix
                $v = $this->idnUtf8($c['value']);
                return $v === false ? $e : $v;
        }
    }

    public function xrayUpdateRules(?array $previousPac = null)
    {
        $entered = false;
        $result = $this->withLock('xray', function () use ($previousPac, &$entered) {
            $entered = true;
            return $this->xrayUpdateRulesLocked($previousPac);
        });
        if (!$entered) throw new RuntimeException($this->t('Не удалось заблокировать Xray', 'Could not lock Xray'));
        return $result;
    }

    protected function xrayUpdateRulesLocked(?array $previousPac = null)
    {
        $c  = $this->getPacConf();
        $xr = $this->getXray();
        // Конфиг нечитаем — правила не трогаем: собранный «с нуля» xr уехал бы
        // в restartXray() без inbounds, то есть без единого клиента.
        if (!is_array($xr)) {
            error_log('xrayUpdateRules: xray.json unreadable, rules left as is');
            return false;
        }
        // Свои три аутбаунда обновляем НА МЕСТЕ, чужие оставляем: раньше
        // outbounds перезаписывались целиком на каждое изменение block/warp-
        // списка, и добавленный админом через webapp аутбаунд молча исчезал —
        // а правила с его тегом оставались висячими (xray их просто игнорирует,
        // трафик уходил в первый аутбаунд).
        $own = [
            'direct' => [
                "protocol" => "freedom",
                "tag"      => "direct",
            ],
            'block' => [
                "protocol" => "blackhole",
                "tag"      => "block",
            ],
            'warp' => [
                "protocol" => "socks",
                "tag"      => "warp",
                "settings" => [
                    'servers' => [
                        [
                            "address" => "10.10.0.13",
                            "port"    => 1080,
                        ],
                    ],
                ],
            ],
        ];
        $outbounds = [];
        foreach (($xr['outbounds'] ?? []) as $ob) {
            $tag = (string) ($ob['tag'] ?? '');
            if (isset($own[$tag])) {
                $outbounds[] = $own[$tag];
                unset($own[$tag]);
                continue;
            }
            $outbounds[] = $ob;
        }
        // Порядок важен: первый аутбаунд в xray — дефолтный маршрут, поэтому
        // недостающие свои дописываем в конец, а не в начало.
        $xr['outbounds'] = array_merge($outbounds, array_values($own));
        $legacyRules = [];
        foreach (['block' => 'blocklist', 'warp' => 'warplist'] as $tag => $list) {
            foreach ($this->listToXrayRules(($previousPac ?? $c)[$list] ?? [], false) as $field => $values) {
                if ($values) $legacyRules[] = ['type' => 'field', 'outboundTag' => $tag, $field => $values];
            }
        }
        $customRules = array_values(array_filter($xr['routing']['rules'] ?? [], static function ($rule) use ($legacyRules) {
            if (str_starts_with((string) ($rule['ruleTag'] ?? ''), 'vpnbot:routes:')) return false;
            // Старые правила без меток узнаём по прежнему PAC-списку.
            // Чужое простое block/warp-правило тоже должно сохраниться.
            foreach ($legacyRules as $legacy) if ($rule == $legacy) return false;
            return true;
        }));
        $rules = [];
        // block/warp: раскладываем каждый список на xray domain/ip с учётом
        // префиксов маршрутизации (regexp:/keyword:/full:/domain:).
        foreach (['block' => 'blocklist', 'warp' => 'warplist'] as $tag => $list) {
            if (empty($c[$list]) || empty(array_filter($c[$list]))) {
                continue;
            }
            $x = $this->listToXrayRules($c[$list]);
            if (!empty($x['domain'])) {
                $rules[] = [
                    "type"        => "field",
                    "outboundTag" => $tag,
                    "ruleTag"     => "vpnbot:routes:$tag:domain",
                    "domain"      => $x['domain'],
                ];
            }
            if (!empty($x['ip'])) {
                $rules[] = [
                    "type"        => "field",
                    "outboundTag" => $tag,
                    "ruleTag"     => "vpnbot:routes:$tag:ip",
                    "ip"          => $x['ip'],
                ];
            }
        }
        $xr['routing']['rules'] = array_merge($rules, $customRules);
        return $this->restartXray($xr);
    }

    // ── Внешние xray .dat (реестр datlist) ──────────────────────────────────
    // Реестр ссылок на geosite/geoip-совместимые .dat: запись "name.dat:https://url"
    // (ключ=>bool). Бот качает файлы в общий каталог /logs/geodata (виден и php, и
    // контейнеру xr), а правила block/warp ссылаются на них через ext:/extip:.
    // Asset-путь ядру задаётся автоматически при старте xray (restartXray +
    // start_xray.sh: XRAY_LOCATION_ASSET=/logs/geodata) — ручных шагов не нужно.

    // Встроенные категории ядра (geosite:/geoip:) живут в файлах с фиксированными
    // именами. Образ xray их не содержит — xray.dockerfile удаляет geoip.dat и
    // geosite.dat, а XRAY_LOCATION_ASSET указан на общий /logs/geodata, — поэтому
    // бот качает их сам, как обычные записи реестра datlist, но по фиксированным
    // ссылкам и не показывая их в списке: пользователь про них не знает, он
    // просто пишет «geosite:category-ads-all».
    public const CORE_DAT = [
        'geosite' => 'geosite.dat',
        'geoip'   => 'geoip.dat',
    ];
    public const CORE_DAT_URL = [
        'geosite.dat' => 'https://github.com/v2fly/domain-list-community/releases/latest/download/dlc.dat',
        'geoip.dat'   => 'https://github.com/v2fly/geoip/releases/latest/download/geoip.dat',
    ];

    public function datDir(): string
    {
        return '/logs/geodata';
    }

    public function datPath(string $name): string
    {
        return $this->datDir() . '/' . basename($name);
    }

    // Какие из встроенных .dat нужны прямо сейчас: файл требуется, только если
    // хотя бы одна включённая запись списков маршрутизации написана как
    // geosite:/geoip:. Пока таких записей нет, ничего не качаем.
    public function coreDatNeeded(array $conf): array
    {
        $need = [];
        $entries = [];
        foreach (self::ROUTE_ENTRY_LISTS as $list) $entries = array_merge($entries, array_keys(array_filter($conf[$list] ?? [])));
        // Маршруты узлов выхода пишутся теми же записями: geosite:/geoip: в них
        // тоже требуют встроенных .dat.
        foreach ($this->exitNodes($conf) as $node) $entries = array_merge($entries, array_keys(array_filter($node['routes'])));
        foreach ($entries as $e) {
            $kind = $this->classifyRouteEntry((string) $e)['kind'];
            if (isset(self::CORE_DAT[$kind])) {
                $need[self::CORE_DAT[$kind]] = true;
            }
        }
        return array_keys($need);
    }

    // Готов ли .dat для ext-значения "file.dat:tag" (файл уже скачан на сервере).
    public function datFileReady(string $value): bool
    {
        $file = $this->datResolve(explode(':', $value, 2)[0]);
        return $file !== '' && is_file($this->datPath($file));
    }

    // Имя файла из ext-ссылки, как оно лежит на диске. Реестр хранит имена в
    // нижнем регистре, а в правиле их пишут и как «Foo.DAT»: ядро ищет файл
    // по точному имени, поэтому при расхождении берём существующий вариант.
    public function datResolve(string $file): string
    {
        $file = basename($file);
        if ($file !== '' && !is_file($this->datPath($file)) && is_file($this->datPath(strtolower($file)))) {
            return strtolower($file);
        }
        return $file;
    }

    // Нормализует ext-значение "file.dat:tag" в токен для xray: file-часть → basename
    // (защита от путей вне asset-каталога и согласованность с datFileReady/datPath).
    public function extAssetRef(string $value): string
    {
        [$file, $tag] = array_pad(explode(':', $value, 2), 2, null);
        $ref = $this->datResolve((string) $file);
        return $tag === null ? $ref : "$ref:$tag";
    }

    // Скачивание .dat по URL с тем же SSRF-guard (safeExtUrlIps) и ручным обходом
    // редиректов, что и doFetchExtSub, но без декодирования тела и с бОльшим лимитом
    // (.dat бывают в несколько МБ). $validators (etag/last_modified) включают
    // условный GET: если ресурс не изменился, сервер отвечает 304 без тела.
    // Возвращает ['ok'=>bool,'file'=>путь к телу,'etag'=>...,'last_modified'=>...,
    // 'not_modified'=>bool,'err'=>...].
    //
    // Тело пишется сразу во временный файл каталога .dat, а не копится в
    // памяти: geosite.dat на 30+ МБ при лимите PHP в 128 МБ обрывал процесс
    // фатальной ошибкой (строка растёт удвоением), а в cron это падение
    // всего демона. Имя файла — с тем же хвостом «.<pid>.<uniqid>», что у
    // прочих временных файлов каталога: уборка осиротевших его не трогает.
    public function datFetchRaw(string $url, array $validators = []): array
    {
        $dir = $this->datDir();
        if (!is_dir($dir)) {
            @mkdir($dir, 0755, true);
        }
        // 256 МиБ: geosite.dat сборки runetfreedom весит 74 МБ и в прежние
        // 64 МиБ не проходил («response too large»). Оборванную передачу
        // повторяем один раз — на больших файлах разрыв не редкость, а
        // следующая плановая попытка только через час.
        for ($try = 0; ; $try++) {
            $r = $this->datHttpGet($url, $validators, 256 << 20, 600, $dir . '/fetch.' . getmypid() . '.' . uniqid());
            if (!empty($r['ok']) || $try >= 1 || !str_starts_with((string) ($r['err'] ?? ''), 'transfer failed')) {
                return $r;
            }
        }
    }

    // $sink — файл для тела; без него (малые ответы вроде файла суммы) тело
    // возвращается строкой в 'body'.
    public function datHttpGet(string $url, array $validators, int $max, int $timeout, ?string $sink = null): array
    {
        $r = $this->datHttpRequest($url, $validators, $max, $timeout, $sink);
        if ($sink !== null && !isset($r['file'])) {
            @unlink($sink);
        }
        return $r;
    }

    private function datHttpRequest(string $url, array $validators, int $max, int $timeout, ?string $sink): array
    {
        $reqHeaders = [];
        if (!empty($validators['etag'])) {
            $reqHeaders[] = 'If-None-Match: ' . $validators['etag'];
        }
        if (!empty($validators['last_modified'])) {
            $reqHeaders[] = 'If-Modified-Since: ' . $validators['last_modified'];
        }
        for ($redir = 0; $redir < 5; $redir++) {
            $ips = $this->safeExtUrlIps($url);
            if ($ips === []) {
                return ['ok' => false, 'err' => 'blocked: non-https or private/unresolvable host'];
            }
            $p       = parse_url($url);
            $port    = (int) ($p['port'] ?? 443);
            $resolve = $this->curlResolveEntries($p['host'], $port, $ips);
            $buf      = '';
            $size     = 0;
            $out      = null;
            if ($sink !== null && ($out = @fopen($sink, 'wb')) === false) {
                return ['ok' => false, 'err' => 'write failed'];
            }
            $location = '';
            $etag     = '';
            $lastMod  = '';
            $ch       = curl_init();
            curl_setopt_array($ch, [
                CURLOPT_URL             => $url,
                CURLOPT_RESOLVE         => $resolve,
                CURLOPT_HTTPHEADER      => $reqHeaders,
                // Прокси из окружения сам разрешает имена и обходит адреса,
                // проверенные safeExtUrlIps: соединяемся только напрямую.
                CURLOPT_PROXY           => '',
                CURLOPT_CONNECTTIMEOUT  => 10,
                // geoip.dat весит десятки мегабайт: общий предел щедрый, а
                // зависшую передачу обрывает порог скорости.
                CURLOPT_TIMEOUT         => $timeout,
                CURLOPT_LOW_SPEED_LIMIT => 1024,
                CURLOPT_LOW_SPEED_TIME  => 30,
                CURLOPT_FOLLOWLOCATION  => false,
                CURLOPT_USERAGENT       => 'vpnbot',
                CURLOPT_PROTOCOLS       => CURLPROTO_HTTPS,
                CURLOPT_REDIR_PROTOCOLS => CURLPROTO_HTTPS,
                // Прозрачно распаковываем gzip/deflate/br: .dat — бинарь, нужен
                // сырой, а зеркало может отдать со сжатием (иначе файл битый).
                CURLOPT_ENCODING        => '',
                CURLOPT_WRITEFUNCTION   => function ($ch, $chunk) use (&$buf, &$size, $out, $max) {
                    $size += strlen($chunk);
                    if ($size > $max) {
                        return 0;
                    }
                    if ($out === null) {
                        $buf .= $chunk;
                        return strlen($chunk);
                    }
                    return (int) fwrite($out, $chunk); // меньше длины — curl прервёт передачу
                },
                CURLOPT_HEADERFUNCTION  => function ($ch, $header) use (&$location, &$etag, &$lastMod) {
                    if (stripos($header, 'location:') === 0) {
                        $location = trim(substr($header, strlen('location:')));
                    } elseif (stripos($header, 'etag:') === 0) {
                        $etag = trim(substr($header, strlen('etag:')));
                    } elseif (stripos($header, 'last-modified:') === 0) {
                        $lastMod = trim(substr($header, strlen('last-modified:')));
                    }
                    return strlen($header);
                },
            ]);
            curl_exec($ch);
            $code  = (int) curl_getinfo($ch, CURLINFO_HTTP_CODE);
            $errno = curl_errno($ch);
            if ($out !== null && !fclose($out)) {
                return ['ok' => false, 'err' => 'write failed'];
            }

            if ($size > $max) {
                return ['ok' => false, 'err' => 'response too large'];
            }
            // Передача оборвалась (таймаут, разрыв), а код ответа уже 200:
            // без этой проверки обрезанное тело считалось удачной загрузкой.
            if ($errno !== 0) {
                return ['ok' => false, 'err' => 'transfer failed: ' . (curl_strerror($errno) ?: "curl $errno")];
            }
            // 304 Not Modified: ресурс не менялся, тело не передавалось.
            if ($code === 304) {
                return ['ok' => true, 'not_modified' => true];
            }
            if ($code >= 300 && $code < 400 && $location !== '') {
                if (!preg_match('~^https://~i', $location)) {
                    return ['ok' => false, 'err' => 'unsafe redirect target'];
                }
                $url = $location;
                continue;
            }
            if ($code < 200 || $code >= 300) {
                return ['ok' => false, 'err' => $code ? "http $code" : 'connection/timeout error'];
            }
            if ($size === 0) {
                return ['ok' => false, 'err' => 'empty body'];
            }
            return ['ok' => true, 'etag' => $etag, 'last_modified' => $lastMod]
                + ($sink !== null ? ['file' => $sink] : ['body' => $buf]);
        }
        return ['ok' => false, 'err' => 'too many redirects'];
    }

    // Путь sidecar-файла с HTTP-валидаторами (etag/last_modified/sha) рядом с .dat.
    public function datMetaPath(string $name): string
    {
        return $this->datPath($name) . '.meta';
    }

    public function datReadMeta(string $name): array
    {
        $f = $this->datMetaPath($name);
        if (!is_file($f)) {
            return [];
        }
        $m = json_decode((string) @file_get_contents($f), true);
        return is_array($m) ? $m : [];
    }

    public function datWriteMeta(string $name, array $meta): void
    {
        $f   = $this->datMetaPath($name);
        $tmp = $f . '.' . getmypid() . '.' . uniqid();
        if (file_put_contents($tmp, json_encode($meta)) !== false) {
            @rename($tmp, $f);
        } else {
            @unlink($tmp);
        }
    }

    // Качает один .dat и атомарно (temp+rename) кладёт в /logs/geodata. '' — успех.
    // $changed сообщает планировщику, надо ли перезагрузить xray. Итог попытки
    // (время и причина отказа) пишется в sidecar — его показывает меню dat.
    public function datDownload(string $name, string $url, ?bool &$changed = null): string
    {
        $err  = $this->datDownloadFile($name, $url, $changed);
        $meta = $this->datReadMeta($name);
        $meta['checked_at'] = time();
        $meta['error']      = $err;
        $this->datWriteMeta($name, $meta);
        return $err;
    }

    // Условный GET: если файл уже есть, шлём сохранённые etag/last_modified —
    // при 304 тело не качается вовсе (экономия трафика на больших .dat при
    // частом расписании).
    public function datDownloadFile(string $name, string $url, ?bool &$changed = null): string
    {
        $changed = false;
        $dest    = $this->datPath($name);
        $exists  = is_file($dest);
        // Валидаторы шлём только когда файл на месте: иначе 304 оставил бы нас
        // без файла. Нет файла → полная загрузка.
        $meta = $exists ? $this->datReadMeta($name) : [];
        // ...и только если он скачан с ЭТОГО же URL. Иначе ETag от прежнего
        // источника ушёл бы новому: совпадение (или слабый валидатор вроде
        // W/"0") дало бы 304, и мы бы вечно держали файл от старой ссылки.
        if (($meta['url'] ?? $url) !== $url) {
            $meta = [];
        }
        $r = $this->datFetchRaw($url, $meta);
        if (empty($r['ok'])) {
            return $r['err'] ?? 'fetch failed';
        }
        if (!empty($r['not_modified'])) {
            return ''; // сервер подтвердил 304 — файл актуален, тело не качали
        }
        $tmp = null;
        try {
            if (($tmp = $this->datBodyFile($dest, $r)) === null) {
                return 'write failed';
            }
            $newSha = (string) hash_file('sha256', $tmp);
            $oldSha = '';
            if ($exists) {
                $oldSha = (string) ($meta['sha'] ?? '');
                if ($oldSha === '') {
                    $h = @hash_file('sha256', $dest);
                    $oldSha = is_string($h) ? $h : '';
                }
            }
            $same = $oldSha !== '' && hash_equals($oldSha, $newSha);
            // Байты те же — сумма уже сверена при прошлой загрузке этого файла.
            $verified = $same && !empty($meta['verified']);
            if (!$same) {
                $sum = $this->datFetchSum($url);
                if ($sum !== null && !hash_equals($sum, $newSha)) {
                    // Выпуск мог смениться между запросом файла и запросом суммы:
                    // один повтор обоих, и только потом отказ.
                    @unlink($tmp);
                    $tmp = null;
                    $r   = $this->datFetchRaw($url);
                    if (empty($r['ok']) || !empty($r['not_modified'])) {
                        return $r['err'] ?? 'fetch failed';
                    }
                    if (($tmp = $this->datBodyFile($dest, $r)) === null) {
                        return 'write failed';
                    }
                    $newSha = (string) hash_file('sha256', $tmp);
                    $sum    = $this->datFetchSum($url);
                    if ($sum !== null && !hash_equals($sum, $newSha)) {
                        return $this->t('sha256 не совпала с опубликованной; прежний файл сохранён', 'sha256 does not match the published one; the previous file is kept');
                    }
                }
                $verified = $sum !== null;
            }
            $newMeta = [
                'etag'          => (string) ($r['etag'] ?? ''),
                'last_modified' => (string) ($r['last_modified'] ?? ''),
                'sha'           => $newSha,
                // Источник, из которого лежащий на диске файл реально скачан:
                // datSync() по нему понимает, что URL в реестре сменили.
                'url'           => $url,
                // true — сумма сверена с опубликованным рядом .sha256sum.
                'verified'      => $verified,
            ];
            // Тело пришло (200), но байты те же (сервер не поддержал 304) — только
            // освежаем валидаторы, файл и xray не трогаем.
            if ($same) {
                $this->datWriteMeta($name, $newMeta);
                return '';
            }
            // Страница ошибки или архив вместо .dat: раньше такой файл ложился на
            // диск, если на него ещё не ссылалось ни одно правило, и отказ
            // всплывал позже — при добавлении ext:-записи.
            if ($this->datParseCategories($tmp) === null) {
                return $this->t('не похоже на .dat (нужен формат geosite/geoip); прежний файл сохранён', 'does not look like a .dat (geosite/geoip format is needed); the previous file is kept');
            }
            if (!$this->validateDatReplacement($name, basename($tmp))) {
                return $this->t('Xray отклонил .dat; прежний файл сохранён', 'Xray rejected the .dat; the previous file is kept');
            }
            if (!rename($tmp, $dest)) {
                return 'rename failed';
            }
            $tmp = null;
            $this->datWriteMeta($name, $newMeta);
            $changed = true;
            return '';
        } finally {
            if ($tmp !== null) {
                @unlink($tmp);
            }
        }
    }

    // Тело ответа datFetchRaw() как файл в каталоге .dat: готовый 'file' либо
    // строка 'body', записанная во временный файл. null — записать не удалось.
    public function datBodyFile(string $dest, array $r): ?string
    {
        if (isset($r['file'])) {
            return is_file($r['file']) ? $r['file'] : null;
        }
        $dir = dirname($dest);
        if (!is_dir($dir)) {
            @mkdir($dir, 0755, true);
        }
        $tmp = $dest . '.' . getmypid() . '.' . uniqid();
        if (!isset($r['body']) || file_put_contents($tmp, $r['body']) === false) {
            @unlink($tmp);
            return null;
        }
        return $tmp;
    }

    // Сумма из файла <URL>.sha256sum, который выпуски v2fly, Loyalsoldier и
    // runetfreedom кладут рядом с .dat. null — суммы нет (источник её не
    // публикует или запрос не удался): тогда файл принимается без сверки.
    public function datFetchSum(string $url): ?string
    {
        $path = (string) parse_url($url, PHP_URL_PATH);
        if (!preg_match('~\.dat$~i', $path) || preg_match('~[?#]~', $url)) {
            return null;
        }
        $r = $this->datHttpGet($url . '.sha256sum', [], 4096, 20);
        if (empty($r['ok']) || !preg_match('~^\s*([0-9a-f]{64})(?:\s|$)~i', (string) ($r['body'] ?? ''), $m)) {
            return null;
        }
        return strtolower($m[1]);
    }

    private static function pbVarint(string $buf, int &$i): ?int
    {
        $value = 0;
        for ($shift = 0; $shift < 35; $shift += 7) {
            if (!isset($buf[$i])) {
                return null;
            }
            $byte = ord($buf[$i++]);
            $value |= ($byte & 0x7f) << $shift;
            if ($byte < 0x80) {
                return $value;
            }
        }
        return null;
    }

    // Категории внутри .dat (нижний регистр). Файл — protobuf GeoSiteList или
    // GeoIPList: подряд идущие записи поля 1, у каждой первым полем код
    // категории. Читаются только заголовки записей, тела пропускаются: geoip.dat
    // весит десятки мегабайт. null — файл не этого формата.
    public function datParseCategories(string $path, ?array &$types = null): ?array
    {
        $types = [];
        $size = (int) @filesize($path);
        $fh   = $size > 0 ? @fopen($path, 'rb') : false;
        if ($fh === false) {
            return null;
        }
        try {
            $cats = [];
            $pos  = 0;
            while ($pos < $size) {
                if (fseek($fh, $pos) !== 0) {
                    return null;
                }
                $head = (string) fread($fh, 320);
                if (($head[0] ?? '') !== "\x0a") {
                    return null;
                }
                $i   = 1;
                $len = self::pbVarint($head, $i);
                if ($len === null || $pos + $i + $len > $size) {
                    return null;
                }
                $next = $pos + $i + $len;
                if ($len > 0 && ($head[$i] ?? '') === "\x0a") {
                    $i++;
                    $l = self::pbVarint($head, $i);
                    if ($l === null || $l > 255 || $l > $len) {
                        return null;
                    }
                    $code = substr($head, $i, $l);
                    if (strlen($code) !== $l || !preg_match('~^[\x21-\x7e]+$~D', $code)) {
                        return null;
                    }
                    $cats[strtolower($code)] = true;
                    // GeoSite и GeoIP имеют одинаковую оболочку, но разный
                    // wire type полей первого Domain/CIDR. Ядро может принять
                    // чужой тип как пустой набор: одной run -test недостаточно.
                    // Читаем только заголовок первого элемента, без загрузки
                    // многомегабайтного тела категории. Неизвестное проверит ядро.
                    $i += $l;
                    if (($head[$i] ?? '') === "\x12" && $pos + $i < $next) {
                        $i++;
                        $itemLength = self::pbVarint($head, $i);
                        if ($itemLength !== null && $itemLength > 0 && $pos + $i + $itemLength <= $next) {
                            $wire = ord($head[$i] ?? "\x00");
                            $types[strtolower($code)] = match ($wire) {
                                0x08, 0x12 => 'domain', 0x0a, 0x10 => 'ip', default => null,
                            };
                        }
                    }
                }
                $pos = $next;
            }
            return $cats ? array_map('strval', array_keys($cats)) : null;
        } finally {
            fclose($fh);
        }
    }

    public function datCategories(string $name): ?array
    {
        static $memo = [];
        $path = $this->datPath($name);
        if (!is_file($path)) {
            return null;
        }
        clearstatcache(true, $path);
        $key = $path . '|' . fileinode($path) . '|' . filemtime($path) . '|' . filesize($path);
        if (!array_key_exists($key, $memo)) {
            if (count($memo) > 32) {
                $memo = []; // cron живёт неделями, файлы меняются — не копим
            }
            $memo[$key] = $this->datParseCategories($path);
        }
        return $memo[$key];
    }

    public function datCategoryTypes(string $name): array
    {
        static $memo = [];
        $path = $this->datPath($name);
        clearstatcache(true, $path);
        if (!is_file($path)) return [];
        $key = $path . '|' . fileinode($path) . '|' . filemtime($path) . '|' . filesize($path);
        if (!array_key_exists($key, $memo)) {
            if (count($memo) > 32) $memo = [];
            $this->datParseCategories($path, $types);
            $memo[$key] = $types;
        }
        return $memo[$key];
    }

    // Для записи ext:/extip:/geosite:/geoip: — текст ошибки, если в скачанном
    // файле нет названной категории. null — категория есть либо проверить
    // нечем (файла нет, формат не разобран): тогда решает само ядро.
    public function datCategoryError(array $c): ?string
    {
        if (in_array($c['kind'], ['ext', 'extip'], true)) {
            [$file, $tag] = array_pad(explode(':', (string) $c['value'], 2), 2, '');
            $file = $this->datResolve($file);
        } elseif (isset(self::CORE_DAT[$c['kind']])) {
            $file = self::CORE_DAT[$c['kind']];
            $tag  = (string) $c['value'];
        } else {
            return null;
        }
        $cats = $file === '' ? null : $this->datCategories($file);
        // «!» — отрицание у geoip, «@» — атрибут у geosite: к имени не относятся.
        $tag = explode('@', ltrim(strtolower(trim($tag)), '!'), 2)[0];
        $kind = $this->datCategoryTypes($file)[$tag] ?? null;
        $expected = in_array($c['kind'], ['geoip', 'extip'], true) ? 'ip' : 'domain';
        if ($kind !== null && $kind !== $expected) {
            return $this->t("категория $tag в файле $file содержит ", "category $tag in file $file contains ")
                . ($kind === 'domain' ? $this->t('домены, а не IP-подсети', 'domains, not IP subnets') : $this->t('IP-подсети, а не домены', 'IP subnets, not domains'));
        }
        if ($cats === null || $tag === '' || in_array($tag, $cats, true)) {
            return null;
        }
        return $this->t("в файле $file нет категории $tag", "there is no category $tag in the file $file");
    }

    // Включённые ссылки ext:/extip: в основных списках и маршрутах узлов.
    public function datRefCount(array $conf, string $name): int
    {
        $count = 0;
        $lists = array_map(static fn($list) => $conf[$list] ?? [], self::ROUTE_ENTRY_LISTS);
        foreach ($this->exitNodes($conf) as $node) $lists[] = $node['routes'];
        foreach ($lists as $entries) {
            foreach (array_keys(array_filter($entries)) as $e) {
                $c = $this->classifyRouteEntry((string) $e);
                if (in_array($c['kind'], ['ext', 'extip'], true) && $this->routeEntryUsable($c)
                    && strcasecmp(basename(explode(':', (string) $c['value'], 2)[0]), $name) === 0
                ) {
                    $count++;
                }
            }
        }
        return $count;
    }

    // Имена файлов, объявленных включёнными записями реестра.
    public function datEnabledNames(array $conf): array
    {
        $names = [];
        foreach (array_keys(array_filter($conf['datlist'] ?? [])) as $key) {
            if (preg_match('~^([\w.\-]+\.dat):~i', (string) $key, $m)) {
                $names[basename($m[1])] = true;
            }
        }
        return array_map('strval', array_keys($names));
    }

    // Проверяем уже используемые категории ДО замены asset. Иначе ответ
    // HTML вместо .dat оставлял процесс живым, но ломал следующий рестарт.
    public function validateDatReplacement(string $name, string $temporary): bool
    {
        $config = $this->getXray();
        if (!is_array($config)) return true; // ещё нет серверных правил
        $types = $this->datCategoryTypes($temporary);
        $used = false;
        foreach ($config['routing']['rules'] ?? [] as $i => $rule) {
            foreach (['domain', 'ip'] as $field) {
                foreach ($rule[$field] ?? [] as $j => $token) {
                    $prefix = $field === 'domain' ? 'geosite:' : 'geoip:';
                    if ($name === ($field === 'domain' ? 'geosite.dat' : 'geoip.dat') && str_starts_with($token, $prefix)) {
                        $tag = substr($token, strlen($prefix));
                    } elseif (str_starts_with($token, "ext:$name:")) {
                        $tag = substr($token, strlen("ext:$name:"));
                    } else continue;
                    $category = explode('@', ltrim(strtolower($tag), '!'), 2)[0];
                    if (isset($types[$category]) && $types[$category] !== $field) return false;
                    $config['routing']['rules'][$i][$field][$j] = "ext:$temporary:$tag";
                    $used = true;
                }
            }
        }
        return !$used || $this->validateXrayConfig($config);
    }

    // Синхронизирует /logs/geodata с реестром datlist: качает недостающие файлы
    // ($force=true — перекачивает все, для кнопки «обновить») и удаляет осиротевшие
    // (которых больше нет в реестре). Возвращает карту name=>error для неудач;
    // $changed=true, если хотя бы один файл заменён или удалён.
    public function datSync(bool $force = false, ?bool &$changed = null): array
    {
        $changed = false;
        $conf    = $this->getPacConf();
        $enabled = array_keys(array_filter($conf['datlist'] ?? []));
        $dir     = $this->datDir();
        if (!is_dir($dir)) {
            @mkdir($dir, 0755, true);
        }
        $errors = [];
        // Встроенные geosite.dat/geoip.dat не значатся в реестре datlist, но
        // сборщик осиротевших файлов ниже сносил бы их вместе с чужими — в том
        // числе положенные админом руками (это и происходило на первом же
        // toggle/datrefresh). Держим их всегда, а качаем только когда в списках
        // появилась запись geosite:/geoip:.
        $keep   = array_fill_keys(array_values(self::CORE_DAT), true);
        $source = [];
        // Имена, которые реестр уже объявил сам: свой источник geoip.dat —
        // обычное дело (у него бывает и полнее, и свежее данных апстрима).
        $declared = [];
        foreach ($enabled as $key) {
            if (preg_match('~^([\w.\-]+\.dat):~i', (string) $key, $dm)) {
                $declared[basename($dm[1])] = true;
            }
        }
        foreach ($this->coreDatNeeded($conf) as $file) {
            // Встроенную ссылку добавляем, ТОЛЬКО если файла с таким именем в
            // реестре нет: иначе ниже сработает проверка «имя занято другим
            // источником», и админ получал бы эту ошибку на каждом проходе
            // datSync — при том что файл на месте и правило работает.
            if (isset($declared[$file])) {
                continue;
            }
            $enabled[] = "$file:" . self::CORE_DAT_URL[$file];
        }
        foreach ($enabled as $key) {
            if (!preg_match('~^([\w.\-]+\.dat):(https://.+)$~i', $key, $m)) {
                continue;
            }
            $name = basename($m[1]);
            // Имя файла — первичный ключ на диске, а реестр допускает две записи
            // с одним именем и разными URL. Молча побеждала бы та, что скачалась
            // первой, причём навсегда; сообщаем об этом вместо тихой путаницы.
            if (isset($source[$name]) && $source[$name] !== $m[2]) {
                $errors[$name] = $this->t('имя занято другим источником: ', 'the name is taken by another source: ') . $source[$name];
                continue;
            }
            $source[$name] = $m[2];
            $keep[$name] = true;
            // Пропускаем скачивание, только если на диске лежит файл ИМЕННО с
            // этого URL. Прежде проверялось лишь наличие файла, поэтому смена
            // ссылки в реестре (при сохранённом имени) не подхватывалась никогда.
            if (!$force && is_file($this->datPath($name))
                && ($this->datReadMeta($name)['url'] ?? $m[2]) === $m[2]
            ) {
                continue; // уже скачан — не дёргаем сеть на каждый toggle/delete
            }
            $fileChanged = false;
            if ($err = $this->datDownload($name, $m[2], $fileChanged)) {
                $errors[$name] = $err;
            } elseif ($fileChanged) {
                $changed = true;
            }
        }
        // При ошибке список может быть откачен назад: его assets ещё нужны.
        if ($errors) return $errors;
        foreach (glob($dir . '/*') ?: [] as $f) {
            if (!is_file($f)) {
                continue;
            }
            $base  = basename($f);
            // Временные файлы чужого datDownload/datWriteMeta (".<pid>.<uniqid>")
            // лежат в этом же каталоге и в реестре, разумеется, не значатся. Без
            // этой проверки параллельный запуск (cron + кнопка «обновить»)
            // удалял бы их прямо перед rename() — вторая сторона падала с
            // "rename failed". Их подчистит сам породивший процесс.
            if (preg_match('~\.\d+\.[0-9a-f]+$~', $base)) {
                // Но брошенные (процесс убит посреди загрузки; копии, которые
                // прежние версии оставляли после отклонённой правки реестра)
                // сами не исчезнут и держат место: сутки — заведомо дольше
                // любой загрузки. Возраст — по ctime: у резервной копии,
                // сделанной жёсткой ссылкой, mtime достаётся от старого файла,
                // а ctime — время создания самой ссылки.
                if (time() - (int) @filectime($f) > 86400) {
                    @unlink($f);
                }
                continue;
            }
            // sidecar валидаторов принадлежит своему .dat — чистим их заодно.
            $isMeta = str_ends_with($base, '.meta');
            $owner  = $isMeta ? substr($base, 0, -5) : $base;
            if (!empty($keep[$owner])) {
                continue;
            }
            if (@unlink($f) && !$isMeta) {
                $changed = true; // удаление .meta не требует рестарта xray
            }
        }
        return $errors;
    }

    public function datIntervalValid(int $interval): bool
    {
        return $interval === 0 || ($interval >= self::DAT_UPDATE_MIN && $interval <= self::DAT_UPDATE_MAX);
    }

    // Ввод «90m», «36h», «10d» (и м/ч/д) → секунды; null — не разобрано или
    // вне допустимых пределов.
    public function datParseInterval(string $text): ?int
    {
        if (!preg_match('~^\s*(\d{1,5})\s*(m|h|d|м|ч|д)\s*$~iu', $text, $m)) {
            return null;
        }
        $unit = ['m' => 60, 'м' => 60, 'h' => 3600, 'ч' => 3600, 'd' => 86400, 'д' => 86400][mb_strtolower($m[2])];
        $interval = (int) $m[1] * $unit;
        return $interval > 0 && $this->datIntervalValid($interval) ? $interval : null;
    }

    // Час запуска действует только для интервалов от суток.
    public function datUpdateHour(array $conf): ?int
    {
        $hour = $conf['dat_update_hour'] ?? null;
        return is_int($hour) && $hour >= 0 && $hour <= 23
            && (int) ($conf['dat_update_interval'] ?? 0) >= 86400 ? $hour : null;
    }

    // Время следующего запуска. С заданным часом — первое HH:00 (пояс бота)
    // позже чем через «интервал минус сутки»: запуск держится своего часа и
    // не уезжает, а пауза никогда не длиннее интервала.
    public function datNextRun(int $from, int $interval, ?int $hour = null): int
    {
        if ($hour === null || $interval < 86400) {
            return $from + $interval;
        }
        $after = $from + $interval - 86400;
        [$y, $mo, $d] = array_map('intval', explode('-', date('Y-n-j', $after)));
        $next = mktime($hour, 0, 0, $mo, $d, $y);
        if ($next <= $after) {
            $next = mktime($hour, 0, 0, $mo, $d + 1, $y);
        }
        return $next;
    }

    // Есть ли что обновлять: включённые источники реестра либо встроенные
    // geosite.dat/geoip.dat, нужные записям geosite:/geoip:.
    public function datSourcesPresent(array $conf): bool
    {
        return !empty(array_filter($conf['datlist'] ?? [])) || $this->coreDatNeeded($conf) !== [];
    }

    public function datRecordUpdate(int $at, bool $success = false): void
    {
        $this->pacConfUpdate(function (&$conf) use ($at, $success) {
            if (!is_array($conf)) {
                return;
            }
            $conf['dat_update_last_attempt'] = $at;
            $interval = (int) ($conf['dat_update_interval'] ?? 0);
            if ($this->datIntervalValid($interval) && $interval > 0) {
                $conf['dat_update_next'] = $this->datNextRun($at, $interval, $this->datUpdateHour($conf));
            }
            if ($success) {
                $conf['dat_update_last_success'] = $at;
                unset($conf['dat_update_failed']);
            }
        });
    }

    public function datErrorLines(array $errors): array
    {
        $lines = [];
        foreach ($errors as $name => $err) {
            $lines[] = self::esc(is_string($name) ? "$name — $err" : (string) $err);
        }
        return $lines;
    }

    // Кнопка «обновить»: перекачать все .dat, пересобрать серверные правила, отчёт.
    public function datRefresh()
    {
        $this->withLock('xray', function () {
            $runAt = time();
            $this->datRecordUpdate($runAt);
            $changed = false;
            $errors = $this->datSync(true, $changed);
            if ($changed && $this->xrayUpdateRulesLocked() === false) $errors['xray'] = $this->t('правила не применены', 'rules not applied');
            if (!$errors) {
                $this->datRecordUpdate($runAt, true);
            }
            if ($errors) {
                $this->send($this->input['from'], $this->t("dat: ошибки загрузки:\n", "dat: download errors:\n") . implode("\n", $this->datErrorLines($errors)));
            }
        });
        $this->xtlsdat();
    }

    public function datNotifyAdmins(string $text): void
    {
        $this->notifyAdmins($text);
    }

    // Сообщение всем администраторам из cron: там нет $this->input.
    public function notifyAdmins(string $text): void
    {
        $c = [];
        require __DIR__ . '/config.php';
        $navigation = $this->chatNavigationActive;
        $this->chatNavigationActive = false;
        try {
            foreach ((array) ($c['admin'] ?? []) as $admin) {
                $this->send($admin, $text);
            }
        } finally {
            $this->chatNavigationActive = $navigation;
        }
    }

    // Cron: обновляет включённые источники по выбранному интервалу. Время
    // попытки сохраняется до сети, чтобы ошибка/рестарт cron не создали цикл
    // скачивания каждые 10 секунд. Xray перезапускается только при изменении .dat.
    public function checkDatUpdates(): void
    {
        $this->withLock('xray', function () {
            $conf     = $this->getPacConf();
            $interval = (int) ($conf['dat_update_interval'] ?? 0);
            if (
                !is_array($conf)
                || !$this->datIntervalValid($interval)
                || $interval === 0
                || !$this->datSourcesPresent($conf)
            ) {
                return;
            }
            $now  = time();
            $next = (int) ($conf['dat_update_next'] ?? 0);
            if ($next > $now) {
                return;
            }

            $this->datRecordUpdate($now);
            $changed = false;
            $errors  = $this->datSync(true, $changed);
            if ($changed) {
                if ($this->xrayUpdateRulesLocked() === false) $errors['xray'] = $this->t('правила не применены', 'rules not applied');
            }
            $wasFailing = !empty($conf['dat_update_failed']);
            if (!$errors) {
                $this->datRecordUpdate($now, true);
                if ($wasFailing) {
                    $this->datNotifyAdmins($this->t('✅ dat: автообновление снова работает', '✅ dat: auto-update works again'));
                }
                return;
            }
            // Отказ: повтор не позже чем через час, а не через полный интервал.
            $this->pacConfUpdate(function (&$c) use ($now, $interval) {
                if (!is_array($c)) {
                    return;
                }
                $c['dat_update_next']   = $now + min($interval, self::DAT_UPDATE_RETRY);
                $c['dat_update_failed'] = 1;
            });
            foreach ($errors as $name => $err) {
                error_log("dat auto-update[$name]: $err");
            }
            // Одно сообщение на серию отказов: повторы идут каждый час.
            if (!$wasFailing) {
                $this->datNotifyAdmins($this->t("⚠️ dat: автообновление не удалось, повтор через ", "⚠️ dat: auto-update failed, retry in ")
                    . $this->datUpdateIntervalLabel(min($interval, self::DAT_UPDATE_RETRY)) . ":\n"
                    . implode("\n", $this->datErrorLines($errors)));
            }
        });
    }

    public function datUpdateIntervalLabel(int $interval): string
    {
        if (isset(self::DAT_UPDATE_INTERVALS[$interval])) {
            return self::DAT_UPDATE_INTERVALS[$interval];
        }
        if (!$this->datIntervalValid($interval)) {
            return 'off';
        }
        if ($interval % 86400 === 0) {
            return intdiv($interval, 86400) . 'd';
        }
        return $interval % 3600 === 0 ? intdiv($interval, 3600) . 'h' : (int) ceil($interval / 60) . 'm';
    }

    // Подпись расписания: «1d, 04:00» при заданном часе запуска.
    public function datScheduleLabel(array $conf): string
    {
        $label = $this->datUpdateIntervalLabel((int) ($conf['dat_update_interval'] ?? 0));
        $hour  = $this->datUpdateHour($conf);
        return $hour === null ? $label : sprintf('%s, %02d:00', $label, $hour);
    }

    public function datScheduleSet(int $interval): void
    {
        if (!$this->datIntervalValid($interval)) {
            $this->xtlsdat();
            return;
        }
        $this->pacConfUpdate(function (&$conf) use ($interval) {
            $conf['dat_update_interval'] = $interval;
            if ($interval > 0) {
                // Первая автоматическая проверка — через период (с заданным
                // часом — в этот час); для немедленной загрузки остаётся
                // кнопка «обновить».
                $conf['dat_update_next'] = $this->datNextRun(time(), $interval, $this->datUpdateHour($conf));
            } else {
                unset($conf['dat_update_next'], $conf['dat_update_failed']);
            }
        });
        $this->datSchedule();
    }

    public function datScheduleHour(?int $hour): void
    {
        if ($hour !== null && $hour > 23) {
            $this->datSchedule();
            return;
        }
        $this->pacConfUpdate(function (&$conf) use ($hour) {
            if ($hour === null) {
                unset($conf['dat_update_hour']);
            } else {
                $conf['dat_update_hour'] = $hour;
            }
            $interval = (int) ($conf['dat_update_interval'] ?? 0);
            if ($interval > 0 && $this->datIntervalValid($interval)) {
                $conf['dat_update_next'] = $this->datNextRun(time(), $interval, $this->datUpdateHour($conf));
            }
        });
        $this->datSchedule();
    }

    public function datScheduleCustom(): void
    {
        $r = $this->send(
            $this->input['chat'],
            "@{$this->input['username']} " . $this->i18n('dat interval prompt'),
            $this->input['message_id'],
            reply: '90m / 36h / 10d',
        );
        $this->stashReply($r, [
            'start_message' => $this->input['message_id'],
            'callback'      => 'datScheduleCustomSet',
            'args'          => [],
        ]);
    }

    public function datScheduleCustomSet(string $text): void
    {
        $interval = $this->datParseInterval($text);
        if ($interval === null) {
            $this->send($this->input['from'], $this->i18n('dat interval invalid'));
            $this->datSchedule();
            return;
        }
        $this->datScheduleSet($interval);
    }

    public function datSchedule(): void
    {
        $conf    = $this->getPacConf();
        $current = (int) ($conf['dat_update_interval'] ?? 0);
        $hour    = $this->datUpdateHour($conf ?: []);
        $text = "Menu -> " . $this->i18n('xray') . ' -> ' . $this->i18n('routes')
            . " -> dat -> " . $this->i18n('auto update') . "\n" . $this->i18n('select update interval') . ':';
        $data = [];
        $row  = [];
        foreach (self::DAT_UPDATE_INTERVALS as $seconds => $label) {
            $row[] = [
                'text'          => ($current === $seconds ? '✅ ' : '') . $label,
                'callback_data' => "/datscheduleset $seconds",
            ];
            if (count($row) === 3) {
                $data[] = $row;
                $row = [];
            }
        }
        $custom = !isset(self::DAT_UPDATE_INTERVALS[$current]) && $this->datIntervalValid($current);
        $row[] = [
            'text'          => ($custom ? '✅ ' . $this->datUpdateIntervalLabel($current) . ' · ' : '✏️ ')
                . $this->i18n('custom interval'),
            'callback_data' => '/datschedulecustom',
        ];
        $data[] = $row;
        if ($current >= 86400 && $this->datIntervalValid($current)) {
            $text .= "\n\n" . $this->i18n('dat run hour') . ' (' . date_default_timezone_get() . '): '
                . ($hour === null ? $this->i18n('dat any hour') : sprintf('%02d:00', $hour));
            for ($h = 0; $h < 24; $h += 6) {
                $row = [];
                for ($i = $h; $i < $h + 6; $i++) {
                    $row[] = [
                        'text'          => ($hour === $i ? '✅' : '') . sprintf('%02d', $i),
                        'callback_data' => "/datschedulehour $i",
                    ];
                }
                $data[] = $row;
            }
            $data[] = [[
                'text'          => ($hour === null ? '✅ ' : '') . $this->i18n('dat any hour'),
                'callback_data' => '/datschedulehour off',
            ]];
        }
        $data[] = [[
            'text'          => $this->i18n('back'),
            'callback_data' => '/xtlsdat',
        ]];
        $this->update(
            $this->input['chat'],
            $this->input['message_id'],
            $text,
            $data,
        );
    }

    public function datLastUpdateAt(array $conf): int
    {
        if ((int) ($conf['dat_update_last_success'] ?? 0) > 0) {
            return (int) $conf['dat_update_last_success'];
        }
        $last = 0;
        // Удачной отметки нет (установка обновилась с версии без timestamp
        // либо первая попытка не удалась) — показываем время самого свежего
        // .dat, реально лежащего на диске.
        foreach (glob($this->datDir() . '/*.dat') ?: [] as $file) {
            $last = max($last, (int) @filemtime($file));
        }
        return $last;
    }

    public static function datHumanSize(int $bytes): string
    {
        if ($bytes >= 1 << 20) {
            return round($bytes / (1 << 20), 1) . ' MB';
        }
        return $bytes >= 1024 ? round($bytes / 1024) . ' KB' : "$bytes B";
    }

    // Строки состояния файлов для меню: размер, дата загрузки, итог последней
    // попытки. Встроенные geosite.dat/geoip.dat — когда они используются.
    public function datStatusLines(array $conf): array
    {
        $names = $this->datEnabledNames($conf);
        foreach ($this->coreDatNeeded($conf) as $core) {
            if (!in_array($core, $names, true)) {
                $names[] = $core;
            }
        }
        $lines = [];
        $used  = 0;
        foreach ($names as $name) {
            // Ниже в том же сообщении идёт список реестра со своим бюджетом
            // 3500 символов, а предел Telegram — 4096: блоку состояния
            // оставляем немного.
            if (count($lines) >= 8 || $used > 420) {
                $lines[] = '…';
                break;
            }
            $path = $this->datPath($name);
            $meta = $this->datReadMeta($name);
            $err  = (string) ($meta['error'] ?? '');
            if (is_file($path)) {
                $line = self::esc($name) . ' — ' . self::datHumanSize((int) filesize($path))
                    . ', ' . date('Y-m-d H:i', (int) filemtime($path))
                    . (!empty($meta['verified']) ? ', sha256 ✅' : '');
            } else {
                $line = self::esc($name) . ' — ' . $this->i18n('dat not downloaded');
            }
            $line   .= $err !== '' ? "\n⚠️ " . self::esc(mb_substr($err, 0, 70)) : '';
            $used   += mb_strlen($line);
            $lines[] = $line;
        }
        return $lines;
    }

    // Меню routes -> dat: реестр ссылок, расписание и ручное обновление.
    public function xtlsdat($page = 0)
    {
        $text[] = "Menu -> " . $this->i18n('xray') . ' -> ' . $this->i18n('routes') . ' -> dat';

        $conf     = $this->getPacConf() ?: [];
        $interval = (int) ($conf['dat_update_interval'] ?? 0);
        $last     = $this->datLastUpdateAt($conf);
        $text[]   = $this->i18n('auto update') . ': ' . $this->datScheduleLabel($conf);
        $text[]   = $this->i18n('last update') . ': ' . ($last > 0 ? date('Y-m-d H:i:s', $last) : '—');
        if ($interval > 0) {
            $next = (int) ($conf['dat_update_next'] ?? 0);
            $text[] = $this->i18n('next update') . ': ' . ($next > 0
                ? date('Y-m-d H:i:s', $next)
                : 'soon') . (!empty($conf['dat_update_failed']) ? ' ⚠️' : '');
        }
        if ($status = $this->datStatusLines($conf)) {
            $text[] = '';
            $text   = array_merge($text, $status);
        }

        [$data, $tmp] = $this->listPac('datlist', $page, 'xtlsdat', 1);
        $text = array_merge($text, $tmp ?: []);
        $data[] = [
            [
                'text'          => '⏱ ' . $this->i18n('auto update') . ': ' . $this->datScheduleLabel($conf),
                'callback_data' => '/datschedule',
            ],
        ];
        $data[] = [
            [
                'text'          => '📂 ' . $this->i18n('dat categories'),
                'callback_data' => '/datfiles',
            ],
            [
                'text'          => '🔄 ' . $this->i18n('update'),
                'callback_data' => "/datrefresh",
            ],
        ];
        $data[] = [
            [
                'text'          => $this->i18n('back'),
                'callback_data' => "/routes",
            ],
        ];
        $this->update(
            $this->input['chat'],
            $this->input['message_id'],
            implode("\n", $text ?: ['...']),
            $data ?: false,
        );
    }

    public function datFileKey(string $name): string
    {
        return 'k' . substr(hash('sha256', $name), 0, 12);
    }

    // Скачанные файлы каталога: имя => ключ для кнопки (имя файла в данные
    // кнопки не кладём — у Telegram на них 64 байта).
    public function datDownloadedFiles(): array
    {
        $files = [];
        foreach (glob($this->datDir() . '/*.dat') ?: [] as $file) {
            if (is_file($file)) {
                $files[basename($file)] = $this->datFileKey(basename($file));
            }
        }
        ksort($files);
        return $files;
    }

    // Меню выбора файла для просмотра категорий.
    public function datFiles(): void
    {
        $text = ["Menu -> " . $this->i18n('xray') . ' -> ' . $this->i18n('routes') . ' -> dat -> '
            . $this->i18n('dat categories')];
        $data = [];
        foreach ($this->datDownloadedFiles() as $name => $key) {
            $cats   = $this->datCategories($name);
            $data[] = [[
                'text'          => $name . ' (' . ($cats === null ? '?' : count($cats)) . ')',
                'callback_data' => "/datcats $key",
            ]];
        }
        if (!$data) {
            $text[] = $this->i18n('dat no files');
        }
        $data[] = [[
            'text'          => $this->i18n('back'),
            'callback_data' => '/xtlsdat',
        ]];
        $this->update($this->input['chat'], $this->input['message_id'], implode("\n", $text), $data);
    }

    // Страничный список категорий файла; $query — отбор по подстроке.
    public function datCats(string $key, int $page = 0, string $query = ''): void
    {
        $name = array_search($key, $this->datDownloadedFiles(), true);
        if ($name === false) {
            $this->datFiles();
            return;
        }
        $name = (string) $name;
        $all  = $this->datCategories($name) ?? [];
        sort($all, SORT_STRING);
        $cats = $query === '' ? $all : array_values(array_filter($all, static fn($c) => str_contains($c, $query)));
        $per   = 60;
        $pages = max(1, (int) ceil(count($cats) / $per));
        $page  = max(0, min($page, $pages - 1));
        $prefix = match ($name) {
            'geosite.dat' => ['geosite:'],
            'geoip.dat'   => ['geoip:'],
            default       => ["ext:$name:", "extip:$name:"],
        };
        $text = [
            "Menu -> " . $this->i18n('xray') . ' -> ' . $this->i18n('routes') . ' -> dat -> ' . self::esc($name),
            $this->i18n('dat categories') . ': ' . count($cats)
                . ($query !== '' ? ' / ' . count($all) . ' (' . self::esc($query) . ')' : ''),
            $this->i18n('dat category usage') . ': '
                . implode(' / ', array_map(static fn($p) => '<code>' . self::esc($p) . '…</code>', $prefix)),
            '',
        ];
        $text[] = implode(' ', array_map(
            static fn($c) => '<code>' . self::esc($c) . '</code>',
            array_slice($cats, $page * $per, $per)
        )) ?: '—';
        $suffix = $query !== '' ? " $query" : '';
        $data   = [];
        if ($pages > 1) {
            $data[] = [
                ['text' => '<<', 'callback_data' => "/datcats $key " . ($page > 0 ? $page - 1 : $pages - 1) . $suffix],
                ['text' => ($page + 1) . '/' . $pages, 'callback_data' => "/datcats $key $page$suffix"],
                ['text' => '>>', 'callback_data' => "/datcats $key " . ($page < $pages - 1 ? $page + 1 : 0) . $suffix],
            ];
        }
        $row = [['text' => '🔎 ' . $this->i18n('search'), 'callback_data' => "/datcatsearch $key"]];
        if ($query !== '') {
            $row[] = ['text' => $this->i18n('dat show all'), 'callback_data' => "/datcats $key 0"];
        }
        $data[] = $row;
        $data[] = [['text' => $this->i18n('back'), 'callback_data' => '/datfiles']];
        $this->update($this->input['chat'], $this->input['message_id'], implode("\n", $text), $data);
    }

    public function datCatSearch(string $key): void
    {
        $r = $this->send(
            $this->input['chat'],
            "@{$this->input['username']} " . $this->i18n('dat search prompt'),
            $this->input['message_id'],
            reply: 'google',
        );
        $this->stashReply($r, [
            'start_message' => $this->input['message_id'],
            'callback'      => 'datCatSearchSet',
            'args'          => [$key],
        ]);
    }

    public function datCatSearchSet(string $text, string $key): void
    {
        // В данные кнопок листания запрос уходит как есть — оставляем только
        // символы, из которых состоят имена категорий, и режем длину.
        $query = substr((string) preg_replace('~[^a-z0-9!@._-]~', '', strtolower(trim($text))), 0, 24);
        $this->datCats($key, 0, $query);
    }

    // Разбор пользовательского ввода источников .dat (по строкам), скачивание,
    // сохранение реестра и пересборка серверных правил.
    public function addDat(string $input)
    {
        $errors = []; $entries = [];
        foreach (preg_split('~\r\n|\r|\n~', $input) as $line) {
            $line = trim($line);
            if ($line === '') continue;
            if (!$this->routeListEntryValid('datlist', $line)) {
                $errors[] = $this->t('неверный формат: ', 'invalid format: ') . self::esc($line);
                continue;
            }
            // Имя файла — в нижний регистр: ссылку ext:Foo.dat:… ядро ищет по
            // точному имени, и «Foo.DAT» в реестре с «foo.dat» в правиле
            // расходились молча.
            [$name, $url] = explode(':', $line, 2);
            $entries[strtolower($name) . ':' . $url] = true;
        }
        if ($entries) $this->changeRouteList('datlist', static function (&$list) use ($entries) {
            $list += $entries; // повторное добавление не включает выключенный источник
            ksort($list);
        });
        if ($errors) $this->send($this->input['from'], "dat:\n" . implode("\n", $errors));
        $keys = array_keys($this->getPacConf()['datlist'] ?? []);
        $index = array_search(array_key_last($entries), $keys, true);
        $page = $index === false ? 0 : (int) floor($index / $this->limit);
        $this->xtlsdat($page);
    }

    public function reverse(int $count)
    {
        $r = $this->send(
            $this->input['chat'],
            $this->t("@{$this->input['username']} перечислите домены через запятую", "@{$this->input['username']} list domains separated by commas"),
            $this->input['message_id'],
            reply: $this->t('перечислите домены через запятую', 'list domains separated by commas'),
        );
        $this->stashReply($r, [
            'start_message' => $this->input['message_id'],
            'callback'      => 'addReverse',
            'args'          => [$count],
        ]);
    }

    public function addReverse(string $domains, int $count)
    {
        $domains = explode(',', $domains);
        $domains = array_filter($domains, fn($x) => !empty(trim($x)));
        if (!empty($domains)) {
            $page = $this->pacConfUpdate(function (&$conf) use ($domains, $count) {
                foreach ($domains as $k => $v) {
                    $conf['reverselist'][idn_to_ascii(trim($v))] = true;
                }
                ksort($conf['reverselist']);
                return (int) floor(array_search($v, array_keys($conf['reverselist'])) / $count);
            });
        }
        $page = ($page ?? 0) ?: -2;
        $this->menu('reverselist', $page);
    }

