    // Второй элемент возврата — строки для тела сообщения. Инициализация нужна:
    // на пустом списке ветка ниже до неё не доходила, и `return [$data, $text]`
    // сыпал «Undefined variable $text».
    public function listPac($type, $page, $menu, $basename = false)
    {
        $text = [];
        // ?? [] — как в соседнем скопированном блоке: пока в список не
        // добавлено ни одной записи, ключа в pac.json нет, и открытие меню
        // писало «Undefined array key» на каждый клик (11 типов списков).
        $domains = $this->getPacConf()[$type] ?? [];
        $data[] = [
            [
                'text'          => $this->i18n('add'),
                'callback_data' => "/include $type",
            ],
        ];
        // Кнопка чистки — только когда есть что чистить. Списки, накопленные до
        // появления канона, держат дубли, которые глазами в меню не разглядеть:
        // vk.com и domain:vk.com стоят в разных местах отсортированного списка.
        if ($this->isRouteEntryList($type) && !empty($domains)) {
            $dupes = $this->dedupeRouteList($domains)['removed'];
            if ($dupes > 0) {
                $data[0][] = [
                    'text'          => $this->i18n('dedupe') . " ($dupes)",
                    'callback_data' => "/dedupeList $type $page",
                ];
            }
        }
        if (!empty($domains)) {
            $all     = (int) ceil(count($domains) / $this->limit);
            $page    = min($page, $all - 1);
            $page    = $page < 0 ? $all - 1 : $page;
            $domains = array_slice($domains, $page * $this->limit, $this->limit, true);
            $i = 0;
            // Бюджет на тело сообщения. Telegram отвергает сообщение целиком
            // при длине > 4096 символов, а число записей на странице задаётся
            // пользователем (pacconf limitpage) и по умолчанию равно 5 —
            // достаточно поднять его и добавить длинных regexp/URL, чтобы
            // меню перестало открываться совсем. Кнопки при этом не страдают,
            // поэтому режем только текст и честно помечаем обрыв.
            $budget = 3500;
            $used   = 0;
            $cut    = false;
            $push   = function (string $line) use (&$text, &$used, &$cut, $budget) {
                if ($cut) {
                    return;
                }
                if ($used + mb_strlen($line) > $budget) {
                    $text[] = '…';
                    $cut = true;
                    return;
                }
                $used += mb_strlen($line);
                $text[] = $line;
            };
            foreach ($domains as $k => $v) {
                if (in_array($type, ['rulessetlist', 'datlist'])) {
                    // Ключ — "name.dat:URL"/"outbound:time:URL": в URL встречаются
                    // & и =, а parse_mode=HTML отвергает всё сообщение на
                    // неэкранированном амперсанде, и список переставал открываться.
                    $push('<blockquote><code>' . htmlspecialchars($k, ENT_QUOTES) . '</code></blockquote>'
                        // Источник берёт только одно ядро — подписываем какое,
                        // иначе «правило добавлено, а в клиенте его нет».
                        . ($type === 'rulessetlist' && ($rs = self::parseRuleSetKey((string) $k)) !== null
                            ? '→ ' . self::ruleSetCore($rs['url']) : ''));
                } elseif (in_array($type, ['blocklist', 'warplist', 'includelist'])) {
                    // block/warp/proxy: в кнопке длинная запись обрезается
                    // Telegram'ом, поэтому дублируем её в тело сообщения —
                    // как у rulesset list. Берём routeEntryLabel(), а не сырой
                    // ключ: у него idn-домены разворачиваются из punycode, то
                    // есть в чате видно ровно то же, что на кнопке, но целиком
                    // и с возможностью скопировать. Экранирование обязательно:
                    // в regexp:/keyword: попадаются & и <, а на неэкранированном
                    // амперсанде Telegram отвергает всё сообщение целиком.
                    $push('<blockquote><code>'
                        . htmlspecialchars($this->routeEntryLabel($k), ENT_QUOTES)
                        . '</code></blockquote>');
                }
                $data[] = [
                    [
                        'text'          => $this->i18n($v ? 'on' : 'off') . ' ' . ($basename ? basename($k) . ' ' : '') . (in_array($type, ['rulessetlist', 'datlist', 'packagelist', 'processlist', 'subnetlist']) ? $k : $this->routeEntryLabel($k)),
                        'callback_data' => "/change$type k" . substr(hash('sha256', (string) $k), 0, 20) . " $page",
                    ],
                    [
                        'text'          => 'delete',
                        'callback_data' => "/delete$type k" . substr(hash('sha256', (string) $k), 0, 20) . " $page",
                    ],
                ];
                $i++;
            }
            if ($all > 1) {
                $data[] = [
                    [
                        'text'          => '<<',
                        'callback_data' => "/$menu " . ($page - 1 >= 0 ? $page - 1 : $all - 1),
                    ],
                    [
                        'text'          => $page + 1,
                        'callback_data' => "/$menu $page",
                    ],
                    [
                        'text'          => '>>',
                        'callback_data' => "/$menu " . ($page < $all - 1 ? $page + 1 : 0),
                    ],
                ];
            }
            $data[] = [
                [
                    'text'          => $this->i18n('delete all'),
                    'callback_data' => "/deleteAll $type",
                ],
                [
                    'text'          => $this->i18n('export'),
                    'callback_data' => "/exportList $type",
                ],
                [
                    'text'          => $this->i18n('import'),
                    'callback_data' => "/importList $type",
                ],
            ];
        } else {
            $data[] = [
                [
                    'text'          => $this->i18n('import'),
                    'callback_data' => "/importList $type",
                ],
            ];
        }
        return [$data, $text];
    }

    /**
     * Схлопывает семантические дубли в уже накопленном списке по кнопке.
     *
     * Отдельным действием, а не автоматически в getPacConf()/setPacConf():
     * getPacConf() зовётся десятки раз за запрос, а setPacConf() — из
     * параллельных вебхук-воркеров, и молча переписывать там пользовательские
     * списки нельзя.
     */
    public function dedupeList($type, $page = 0)
    {
        if (!$this->isRouteEntryList($type)) return;
        $removed = 0;
        $this->changeRouteList($type, function (&$list) use (&$removed) {
            ['list' => $list, 'removed' => $removed] = $this->dedupeRouteList($list);
            ksort($list);
        });
        $this->answer($this->input['callback_id'], $this->i18n('duplicates merged') . ": $removed");
        $this->backXtlsList($type, $page);
    }

    public function listPacChange($type, $action, $key, $page = 0)
    {
        $this->changeRouteList($type, function (&$list) use ($action, $key) {
            foreach ($list as $entry => $on) {
                // Индексы из старых сообщений небезопасны после сортировки.
                if ($key !== 'k' . substr(hash('sha256', (string) $entry), 0, 20)) continue;
                if ($action === 'change') $list[$entry] = !$on;
                elseif ($action === 'delete') unset($list[$entry]);
                break;
            }
        });
        $this->backXtlsList($type, $page);
    }

    public function pacZapret()
    {
        $this->pacConfUpdate(function (&$conf) {
            $conf['zapret'] = !$conf['zapret'];
        });
        $this->menu('pac');
    }

    public function pacUpdate($import = '')
    {
        // Единственный exec() в файле, где значения из апдейта Telegram шли без
        // escapeshellarg. Эксплуатации нет (вебхук закрыт сверкой ?k= с токеном,
        // а значения на практике числовые), но соседние точки — sendQr,
        // cleanLogs, createSrs — экранированы, и эта не должна быть исключением.
        exec(
            'php updatepac.php start '
            . escapeshellarg((string) $this->input['chat']) . ' '
            . escapeshellarg((string) $this->input['message_id']) . ' '
            . escapeshellarg((string) $this->input['callback_id']) . ' '
            . escapeshellarg((string) $import) . ' > /dev/null &'
        );
    }

    public function getSSConfig()
    {
        return json_decode(file_get_contents('/config/ssserver.json'), true);
    }

    public function getSSLocalConfig()
    {
        return json_decode(file_get_contents('/config/sslocal.json'), true);
    }

    public function menuSS()
    {
        $hash    = $this->getHashBot();
        $domain  = $this->getDomain();
        $ss      = $this->getSSConfig();
        $p       = $this->getPorts();
        $v2ray   = !empty($ss['plugin']) ? 'ON' : 'OFF';
        $ssl     = $this->nginxGetTypeCert();

        $ck       = $this->getCloakConfig();
        $cloakOn  = !empty($ck['Enabled']);
        $ckPort   = (int) (getenv('CKPORT') ?: 7443);
        $ckSrv    = $ck['ServerName'] ?? ($ck['RedirAddr'] ?? 'www.bing.com');

        $ssWarpOn = self::ssWarpOn($ss);

        $st       = $this->getStlsConfig();
        $stlsOn   = !empty($st['Enabled']);
        $stPort   = (int) (getenv('STLSPORT') ?: 3443);
        $stSrv    = $st['ServerName'] ?? $domain;

        // Порт для display: тот же приоритет, что в buildSSLink
        // (cloak > simple-tls > v2ray > plain).
        if ($cloakOn) {
            $port            = $ckPort;
            $activeTransport = 'cloak';
        } elseif ($stlsOn) {
            $port            = $stPort;
            $activeTransport = 'simple-tls';
        } elseif (!empty($ss['plugin'])) {
            $port            = $ssl ? 443 : 80;
            $activeTransport = 'v2ray-plugin';
        } else {
            $port            = $p['ss']['port'];
            $activeTransport = 'plain';
        }
        $enabledTransports = [];
        if (!empty($ss['plugin'])) {
            $enabledTransports[] = 'v2ray-plugin';
        }
        if ($cloakOn) {
            $enabledTransports[] = 'cloak';
        }
        if ($stlsOn) {
            $enabledTransports[] = 'simple-tls';
        }
        if (empty($enabledTransports)) {
            $enabledTransports[] = 'plain';
        }
        $options = !empty($ss['plugin'])
            ? ($ssl ? 'tls;' : '') . "fast-open;path=/v2ray$hash;host=$domain"
            : "path=/v2ray$hash;host=$domain";

        $ss_link = $this->buildSSLink($hash);
        $text    = [];
        $text[]  = 'Menu -> ShadowSocks';
        $text[]  = '';
        $text[]  = $this->t('<b>Подключение</b>', '<b>Connection</b>');
        $text[]  = "server: <code>$domain:$port</code>";
        $text[]  = "transport: <code>$activeTransport</code>";
        $text[]  = $this->t('включено: <code>', 'enabled: <code>') . implode(', ', $enabledTransports) . '</code>';
        $text[]  = 'dns: <code>10.10.0.5</code>';
        $text[]  = '';
        $text[]  = $this->t('<b>Учётные данные</b>', '<b>Credentials</b>');
        $text[]  = 'method: <code>' . htmlspecialchars($ss['method'] ?? '', ENT_QUOTES) . '</code>';
        $text[]  = "password: <span class='tg-spoiler'>" . htmlspecialchars($ss['password'] ?? '', ENT_QUOTES) . '</span>';
        $text[]  = 'link: <code>' . htmlspecialchars($ss_link, ENT_QUOTES) . '</code>';
        if (!empty($ss['plugin'])) {
            $text[] = '';
            $text[] = '<b>v2ray-plugin</b>';
            $text[] = "options: <code>$options</code>";
        }
        if ($cloakOn) {
            $text[] = '';
            $text[] = '<b>Cloak</b>';
            $text[] = "port: <code>$ckPort</code>";
            $text[] = 'masq: <code>' . htmlspecialchars($ckSrv, ENT_QUOTES) . '</code>';
            $text[] = "UID: <span class='tg-spoiler'>" . htmlspecialchars($ck['UID'] ?? '', ENT_QUOTES) . '</span>';
            $text[] = "pubkey: <span class='tg-spoiler'>" . htmlspecialchars($ck['PublicKey'] ?? '', ENT_QUOTES) . '</span>';
            $ckMethod = $ck['EncryptionMethod'] ?? 'aes-256-gcm';
            // 'plain' оставлен доступным, но помечен: конфиденциальность им не
            // теряется (внутри уже шифрованный shadowsocks), а вот вторая задача
            // слоя — маскировка — теряется целиком: полезная нагрузка Cloak
            // перестаёт быть неотличимой от случайной, то есть детектируется.
            $text[] = 'method: <code>' . htmlspecialchars($ckMethod, ENT_QUOTES) . '</code>'
                . ($ckMethod === 'plain' ? $this->t(' ⚠️ только для отладки: трафик перестаёт быть неотличимым от случайного', ' ⚠️ debugging only: the traffic stops being indistinguishable from random') : '');
        }
        if ($ssWarpOn) {
            // Ядро принимает и цепочку из нескольких хопов (Chain(Vec<String>)
            // в SSOutboundProxyConfig), а такой конфиг приезжает импортом или
            // ручной правкой. Голое приведение к строке дало бы «Array» в меню
            // и «Array to string conversion» в логе.
            $chain = $ss[self::SS_WARP_KEY] ?? '';
            $chain = is_array($chain) ? implode(' → ', $chain) : (string) $chain;
            $text[] = '';
            $text[] = '<b>WARP</b>';
            $text[] = 'egress (TCP): <code>' . htmlspecialchars($chain, ENT_QUOTES) . '</code>';
            $text[] = '<i>' . $this->i18n('ss via warp hint') . '</i>';
        }
        if ($stlsOn) {
            $text[] = '';
            $text[] = '<b>simple-tls</b>';
            $text[] = 'SNI: <code>' . htmlspecialchars($stSrv, ENT_QUOTES) . '</code>';
            $text[] = "port: <code>$stPort</code>";
        }

        $data[] = [
            [
                'text'          => $this->i18n('show QR'),
                'callback_data' => "/qrSS",
            ],
        ];
        $data[] = [
            [
                'text'          => $this->i18n('change password'),
                'callback_data' => "/sspswd",
            ],
            [
                'text'          => $this->i18n('generate password'),
                'callback_data' => "/ssGenPswd",
            ],
        ];
        $data[] = [
            [
                'text'          => "v2ray: $v2ray",
                'callback_data' => "/v2ray",
            ],
            [
                'text'          => 'cloak: ' . ($cloakOn ? 'ON' : 'OFF'),
                'callback_data' => "/cloak",
            ],
        ];
        if ($cloakOn) {
            $data[] = [
                [
                    'text'          => $this->i18n('cloak port:') . " $ckPort",
                    'callback_data' => "/cloakPort",
                ],
                [
                    'text'          => $this->i18n('cloak masq:') . " $ckSrv",
                    'callback_data' => "/cloakDomain",
                ],
            ];
            $data[] = [
                [
                    'text'          => $this->i18n('cloak method:') . ' ' . ($ck['EncryptionMethod'] ?? 'aes-256-gcm'),
                    'callback_data' => "/cloakMethod",
                ],
            ];
            $data[] = [
                [
                    'text'          => $this->i18n('regen cloak keys'),
                    'callback_data' => "/cloakRegen",
                ],
            ];
            $ckUserCount = count($this->getCloakUsers());
            $data[] = [
                [
                    'text'          => $this->i18n('cloak users') . " ($ckUserCount)",
                    'callback_data' => "/ckUsers",
                ],
            ];
        }
        $data[] = [
            [
                'text'          => 'simple-tls: ' . ($stlsOn ? 'ON' : 'OFF'),
                'callback_data' => "/simpleTls",
            ],
        ];
        $data[] = [
            [
                'text'          => $this->i18n('ss via warp') . ': ' . ($ssWarpOn ? 'ON' : 'OFF'),
                'callback_data' => "/ssWarp",
            ],
        ];
        if ($stlsOn) {
            $data[] = [
                [
                    'text'          => $this->i18n('stls port:') . " $stPort",
                    'callback_data' => "/stlsPort",
                ],
                [
                    'text'          => $this->i18n('stls SNI:') . " $stSrv",
                    'callback_data' => "/stlsSNI",
                ],
            ];
        }
        $data[] = $this->menuHelpButton('ss');
        $data[] = [
            [
                'text'          => $this->i18n('back'),
                'callback_data' => "/menu",
            ],
        ];
        return [
            'text' => implode("\n", $text),
            'data' => $data,
        ];
    }

    // ?? перед ?:, а не голое чтение: ключа может не быть (и до аудита
    // 2026-08-12 не было у 62 надписей), а тогда каждая такая кнопка добавляла
    // «Undefined array key» в лог. Фолбэк прежний — сам ключ.
    public function i18n(string $menu): string
    {
        return ($this->i18n[$menu][$this->language] ?? '') ?: $menu;
    }

    // Текст вне словаря: русский, если язык не en (как у тестов без языка).
    public function t(string $ru, string $en): string
    {
        return $this->language === 'en' ? $en : $ru;
    }

    // Пере-пиниваем глобальный выбранный инстанс (wg_instance в pac.json) на
    // инстанс нажатой кнопки. Пишем и в pac.json, а не только в $this->wg:
    // после перерисовки меню остальные кнопки без инстанса (add peer, DNS,
    // torrent, пагинация) резолвятся через wg_instance и должны попадать в тот
    // же инстанс, что и меню, с которым пользователь реально работает.
    public function selectWG($i)
    {
        $i = (int) $i ? 1 : 0;
        $this->pacConfUpdate(function (&$conf) use ($i) { $conf['wg_instance'] = $i; });
        $this->wg = $i;
    }

    // Текущий инстанс как число 0/1 — для подстановки в callback_data.
    public function wgNum(): int
    {
        return $this->getInstanceWG(1) ? 1 : 0;
    }

    // ── WG_CB_INST ──────────────────────────────────────────────────────
    // callback_data кнопки wg-меню с вшитым инстансом: префикс «wgN:» перед
    // самой командой. action() снимает префикс и пере-пинивает инстанс ДО
    // разбора команды, поэтому все существующие роуты остаются как есть, а
    // сообщения, отрисованные до этой правки, продолжают работать по-старому
    // (карта wg_msg → глобальный wg_instance).
    //
    // Зачем: карта «сообщение → инстанс» — LRU и эфемерна, а сообщения в
    // Telegram кликабельны вечно. Вытесненная запись превращала «удалить» на
    // старом меню wg1 в удаление ЧУЖОГО пира (deletePeer необратим). Кнопки с
    // явным инстансом от состояния карты не зависят вовсе.
    //
    // Не оборачивать команды, которые уже несут инстанс аргументом
    // (/menu wg N …, /awg3 N …, /wgLog N, /wgClientLog N …) — двойного
    // указания не нужно.
    public function cbWG(string $cb): string
    {
        return 'wg' . $this->wgNum() . ':' . $cb;
    }

    // ── WG_PROMPT_INST ──────────────────────────────────────────────────
    // Инстанс, переданный ПОСЛЕДНИМ аргументом stash'а промпта (rename,
    // defaultDNS, defaultMTU, changeMTU, changeIps). Ответ на промпт приходит
    // ОТДЕЛЬНЫМ запросом, а reply() резолвит инстанс по карте wg_msg для
    // сообщения-меню — но то же сообщение за это время могло быть перерисовано
    // другим инстансом (кнопка «wg 1» рисует в него же), и ответ уезжал не
    // туда: DNS/MTU ложились в чужой префикс pac.json, переименование и
    // AllowedIPs — в чужой clients.json.
    //
    // null — стэш, созданный до этой правки (в $_SESSION их переживает
    // перезапуск): молча оставляем прежнее поведение (карта → wg_instance).
    // Инстанс идёт последним именно ради этого: у легаси-стэша аргумент просто
    // отсутствует, и различать его от валидной страницы не приходится.
    public function promptInstWG($inst): void
    {
        if ($inst !== null) {
            $this->selectWG($inst);
        }
    }

    // ── Карта «сообщение → инстанс» ─────────────────────────────────────
    // wg_instance в pac.json глобален, а кнопки wg-меню (delete, client,
    // addpeer, torrent, DNS…) не несут инстанс в callback_data. Поэтому
    // каждое сообщение с wg-меню запоминает СВОЙ инстанс в wg_msg.json:
    // при нажатии любой кнопки (action) и при ответе на промпт (reply)
    // инстанс берётся из карты как пер-запросный $this->wg — без записи в
    // глобальный указатель. Сообщения, отрендеренные до этого механизма,
    // в карте отсутствуют и работают по-старому через wg_instance.
    // Файл эфемерный: в бэкап не входит, при потере — просто фолбэк.
    public function wgMsgFile()
    {
        return dirname($this->pac) . '/wg_msg.json';
    }

    public function getWgMsg()
    {
        if (empty($this->input['chat']) || empty($this->input['message_id'])) {
            return null;
        }
        $f = $this->wgMsgFile();
        $m = is_file($f) ? (json_decode(file_get_contents($f), true) ?: []) : [];
        return $m["{$this->input['chat']}:{$this->input['message_id']}"] ?? null;
    }

    // Сколько сообщений держим в карте. Кап общий на ВСЕ чаты, поэтому при
    // нескольких админах прежние 100 вытеснялись за пару дней активной работы,
    // а вытесненная запись — это молчаливый фолбэк на глобальный wg_instance
    // (кнопка старого меню уходит в чужой инстанс). Файл крошечный: 1000
    // записей — это ~30 КБ.
    public const WG_MSG_MAX = 1000;

    // $inst 0/1 — записать; null — удалить (сообщение больше не wg-меню).
    // Read-modify-write без общей блокировки на чтении: параллельные воркеры
    // могут потерять запись. Осознанно — карта эфемерная и LRU, потеря
    // деградирует до фолбэка на глобальный wg_instance, ради этого не тащим
    // сюда файловый лок.
    public function setWgMsg($inst)
    {
        if (empty($this->input['chat']) || empty($this->input['message_id'])) {
            return;
        }
        $k = "{$this->input['chat']}:{$this->input['message_id']}";
        $f = $this->wgMsgFile();
        $m = is_file($f) ? (json_decode(file_get_contents($f), true) ?: []) : [];
        if ($inst === null) {
            if (!array_key_exists($k, $m)) {
                return;
            }
            unset($m[$k]);
        } else {
            if (($m[$k] ?? null) === (int) $inst) {
                return;
            }
            // Пере-вставка в конец + отсечка: карта живёт как LRU,
            // старые записи вытесняются, файл не растёт.
            unset($m[$k]);
            $m[$k] = (int) $inst;
            $m = array_slice($m, -self::WG_MSG_MAX, null, true);
        }
        // tmp + rename, как в setWgConnLog(): LOCK_EX защищал только от
        // одновременной ЗАПИСИ, а getWgMsg() читает без LOCK_SH — на
        // truncate+write он ловил файл в момент усечения, json_decode падал в
        // null, `?: []` отдавал пустую карту и инстанс молча брался из
        // глобального wg_instance. rename() атомарен: читатель видит либо
        // старую, либо новую карту целиком.
        $tmp  = $f . '.' . getmypid() . '.tmp';
        $json = json_encode($m);
        if (false === $json || file_put_contents($tmp, $json) === false) {
            @unlink($tmp);
            return;
        }
        rename($tmp, $f);
    }

    public function changeWG($i)
    {
        $this->selectWG($i);
        $this->menu('wg', 0);
    }

    public function alignColumns(array $columns): string
    {
        // Находим максимальную длину для каждого столбца
        $columnLengths = [];
        foreach ($columns as $column) {
            $maxLength = 0;
            foreach ($column as $cell) {
                $len = mb_strlen($cell, 'UTF-8');
                $maxLength = max($maxLength, $len);
            }
            $columnLengths[] = $maxLength;
        }

        // Получаем количество строк из первого столбца
        $rowCount = count($columns[0]);
        $columnCount = count($columns);

        // Формируем строки с выравниванием
        $result = [];
        for ($row = 0; $row < $rowCount; $row++) {
            $line = '';
            for ($col = 0; $col < $columnCount; $col++) {
                $cell = $columns[$col][$row];
                $padding = str_repeat(' ', $columnLengths[$col] - mb_strlen($cell, 'UTF-8'));
                $line .= $cell . $padding;

                // Добавляем разделитель между столбцами, кроме последнего
                if ($col < $columnCount - 1) {
                    $line .= '  '; // Два пробела между столбцами
                }
            }
            $result[] = $line;
        }

        return implode("\n", $result);
    }

    public function dnsttDomain()
    {
        $r = $this->send(
            $this->input['chat'],
            $this->t("@{$this->input['username']} введите домен", "@{$this->input['username']} enter domain"),
            $this->input['message_id'],
            reply: $this->t('введите домен', 'enter domain'),
        );
        $this->stashReply($r, [
            'start_message' => $this->input['message_id'],
            'callback'      => 'setdnsttDomain',
            'args'          => [],
        ]);
    }

    public function dnsttPassword()
    {
        $r = $this->send(
            $this->input['chat'],
            $this->t("@{$this->input['username']} введите пароль", "@{$this->input['username']} enter password"),
            $this->input['message_id'],
            reply: $this->t('введите пароль', 'enter password'),
        );
        $this->stashReply($r, [
            'start_message' => $this->input['message_id'],
            'callback'      => 'setdnsttPassword',
            'args'          => [],
        ]);
    }

    public function setdnsttPassword($text)
    {
        if (strlen($text) > 128 || preg_match('~[\x00\r\n]~', $text)) {
            $this->send($this->input['chat'], $this->t('dnstt: пароль до 128 символов, без перевода строки', 'dnstt: password up to 128 characters, without line breaks'));
            return;
        }
        $ok = $this->withLock('dnstt', function () use ($text) {
            $this->pacConfUpdate(function (&$c) use ($text) {
                $c['dnstt_apply_pending'] = 1;
                if ($text) {
                    $c['dnsttPassword'] = $text;
                } else {
                    unset($c['dnsttPassword']);
                }
            });
            return $this->dnsttStartLocked();
        }, 120, false);
        if (!$ok) throw new RuntimeException($this->t('DNSTT: применение не подтверждено; прежний доступ может оставаться активным', 'DNSTT apply is unconfirmed; previous access may remain active'));
        $this->dnstt();
    }

    public function setdnsttDomain($text)
    {
        $text = strtolower(trim($text));
        if ($text !== '' && !self::dnsttDomainOk($text)) {
            $this->send($this->input['chat'], $this->t('dnstt: некорректный домен', 'dnstt: invalid domain'));
            return;
        }
        $ok = $this->withLock('dnstt', function () use ($text) {
            $this->pacConfUpdate(function (&$c) use ($text) {
                $c['dnstt_apply_pending'] = 1;
                if ($text) {
                    $c['dnsttDomain'] = $text;
                } else {
                    unset($c['dnsttDomain']);
                }
            });
            return $this->dnsttStartLocked();
        }, 120, false);
        if (!$ok) throw new RuntimeException($this->t('DNSTT: применение не подтверждено; прежний доступ может оставаться активным', 'DNSTT apply is unconfirmed; previous access may remain active'));
        $this->dnstt();
    }

    public function telemt($update = false)
    {
        if (!$this->protocolModuleEnabled('telemt')) { $this->protocolModulesMenu(); return; }
        [$conf, $changed] = $this->normalizeTelemtUsers($this->getPacConf());
        if ($changed) {
            $conf = $this->telemtConfUpdate(function (&$current) {
                [$current] = $this->normalizeTelemtUsers($current);
                return $current;
            });
            $this->restartTelemt();
        }
        $ports  = $this->getPorts()['telemt'];
        $domain = $conf['telemt_domain'] ?? 'www.google.com';
        $users  = $conf['telemt_users'] ?? [];
        $masking = $this->telemtBool($conf, 'telemt_mask_hardening', $this->telemtMaskDefault('telemt_mask_hardening'))
            || $this->telemtBool($conf, 'telemt_mask_aggressive', $this->telemtMaskDefault('telemt_mask_aggressive'))
            || $this->telemtBool($conf, 'telemt_mask_blur', $this->telemtMaskDefault('telemt_mask_blur'))
            || $this->telemtBool($conf, 'telemt_mask_timing', $this->telemtMaskDefault('telemt_mask_timing'));
        $diagnostics = $this->telemtBool($conf, 'telemt_beobachten', false);
        $mode    = $this->telemtModeOf($conf);
        $relays  = is_array($conf['telemt_relays'] ?? null)
            ? array_filter($conf['telemt_relays'], fn($r) => !empty($r['address'])) : [];
        $st     = $this->ssh('pgrep -x telemt', 'telemt') ? 'on' : 'off';

        $text[] = "Menu -> TeleMT (MTProto)\n";
        $text[] = "status: $st";
        $text[] = "version: <code>" . $this->telemtVersion() . "</code>";
        $text[] = "port: " . ($ports['enable'] ? $ports['port'] : $this->i18n('port unavailable'));
        $text[] = "mode: " . $this->i18n("telemt mode $mode");
        $text[] = "fake-TLS domain: <code>" . htmlspecialchars($domain, ENT_QUOTES) . "</code>";
        $text[] = "fast mode: " . $this->i18n('on');
        $text[] = "masking: " . $this->telemtState($masking);
        $text[] = "diagnostics: " . $this->telemtState($diagnostics);
        $text[] = "relays: " . (count($relays) ?: $this->i18n('off'));
        $text[] = "web: " . $this->telemtState($this->telemtWebEnabled($conf));
        $text[] = "users: " . count($users);
        if (!$ports['enable']) {
            $text[] = "\n⚠ " . $this->i18n('telemt set port hint');
        }

        $data[] = [['text' => $this->i18n('telemt users'), 'callback_data' => "/telemtUsers"]];
        $data[] = [['text' => $this->i18n('telemt mode'), 'callback_data' => "/telemtMode"]];
        $data[] = [['text' => $this->i18n('telemt sni'), 'callback_data' => "/telemtSni"]];
        $data[] = [['text' => $this->i18n('telemt web'), 'callback_data' => "/telemtWeb"]];
        $data[] = [['text' => $this->i18n('telemt relays'), 'callback_data' => "/telemtRelays"]];
        $data[] = [['text' => $this->i18n('telemt settings'), 'callback_data' => "/telemtSettings"]];
        $data[] = [['text' => $this->i18n('telemt masking'), 'callback_data' => "/telemtMasking"]];
        $data[] = [['text' => $this->i18n('telemt diagnostics'), 'callback_data' => "/telemtDiagnostics"]];
        $data[] = $this->menuHelpButton('telemt_main');
        $data[] = [['text' => $this->i18n('back'), 'callback_data' => "/menu"]];

        if ($update) {
            $this->update($this->input['chat'], $this->input['message_id'], implode("\n", $text), $data);
        } else {
            $this->send($this->input['chat'], implode("\n", $text), $this->input['message_id'], $data);
        }
    }

    public function telemtUsers($relay = '', int $page = 0)
    {
        $conf = $this->getPacConf();
        $users = is_array($conf['telemt_users'] ?? null) ? $conf['telemt_users'] : [];
        $relays = array_filter($conf['telemt_relays'] ?? [], fn($r) => !empty($r['address']));
        if (!isset($relays[$relay])) $relay = '';
        $pages = max(1, (int) ceil(count($users) / 8));
        $page = max(0, min($page, $pages - 1));
        $this->telemtActivityRefresh();
        $activity = $this->getTelemtActivity();
        $onlineNow = 0;
        foreach (array_keys($users) as $name) {
            $seen = $this->telemtActivityOf((string) $name, $activity);
            if ($seen && ($seen['conns'] > 0 || $seen['online'])) $onlineNow++;
        }
        $text = ['Menu → TeleMT → ' . $this->i18n('telemt users'),
            'users: ' . count($users) . ' · ' . $this->i18n('online') . ': ' . $onlineNow . ' · ' . ($page + 1) . ' / ' . $pages,
            'MTProxy: ' . ($relay === '' ? $this->i18n('telemt direct') : self::esc($relay)),
            $this->i18n('telemt users cards')];
        $quotas = $this->telemtActivityQuotas($conf);
        $data = [];
        foreach (array_slice($users, $page * 8, 8, true) as $name => $secret) {
            $enabled = !array_key_exists($name, $conf['telemt_user_enabled'] ?? []) || !empty($conf['telemt_user_enabled'][$name]);
            // Точка — разрешён ли доступ; «в сети», трафик и квота — справа.
            $tail = $this->telemtActivityTail($this->telemtActivityOf((string) $name, $activity), $quotas[$name] ?? 0);
            $data[] = [['text' => ($enabled ? '🟢 ' : '🔴 ') . mb_strimwidth((string) $name, 0, 60 - mb_strlen($tail), '…') . $tail,
                'callback_data' => $this->telemtUserCallback((string) $name, $page, $relay)]];
        }
        $rarg = $relay === '' ? '' : ' ' . $relay;
        $pager = [];
        if ($page > 0) $pager[] = ['text' => '◀', 'callback_data' => '/telemtUsersPage ' . ($page - 1) . $rarg];
        if ($page + 1 < $pages) $pager[] = ['text' => '▶', 'callback_data' => '/telemtUsersPage ' . ($page + 1) . $rarg];
        if ($pager) $data[] = $pager;
        if ($relays) {
            $choices = [['text' => ($relay === '' ? '✅ ' : '') . $this->i18n('telemt direct'), 'callback_data' => "/telemtUsersPage $page"]];
            foreach ($relays as $name => $r) {
                $callback = "/telemtUsersPage $page $name";
                if (strlen($callback) <= 64) $choices[] = ['text' => ($relay === (string) $name ? '✅ ' : '') . mb_strimwidth((string) $name, 0, 28, '…'), 'callback_data' => $callback];
            }
            array_push($data, ...array_chunk($choices, 2));
        }
        // Длинное имя relay не помещается в 64 байта callback_data: обновляем прямой список.
        $refresh = "/telemtUsersRefresh $page$rarg";
        $data[] = [['text' => '🔄 ' . $this->i18n('refresh'), 'callback_data' => strlen($refresh) <= 64 ? $refresh : "/telemtUsersRefresh $page"]];
        $data[] = [['text' => $this->i18n('telemt add user'), 'callback_data' => '/telemtAddUser']];
        $data[] = [['text' => $this->i18n('back'), 'callback_data' => '/telemt']];
        $this->update($this->input['chat'], $this->input['message_id'], implode("\n\n", $text), $data);
    }

    // Кнопка привязана к текущему секрету: удаление и повторное создание имени
    // или ротация делают старую кнопку недействительной. Ключ повторно
    // проверяется под telemt/pac lock непосредственно перед изменением.
    private function telemtUserIdentity(string $name, array $conf): string
    {
        return substr(hash('sha256', $name . "\0" . ($conf['telemt_users'][$name] ?? '')), 0, 12);
    }

    public function telemtUserCallback(string $name, int $page = 0, string $relay = '', string $action = ''): string
    {
        return '/tuc ' . $this->telemtUserIdentity($name, $this->getPacConf()) . ' ' . max(0, $page) . ' '
            . ($relay === '' ? 'direct' : substr(hash('sha256', $relay), 0, 12)) . ($action === '' ? '' : ' ' . $action);
    }

    public function telemtUserAction(string $key, int $page, string $relayKey, string $action = ''): void
    {
        $conf = $this->getPacConf();
        $names = array_values(array_filter(array_keys($conf['telemt_users'] ?? []), fn($name) => $this->telemtUserIdentity((string) $name, $conf) === $key));
        $relays = array_values(array_filter(array_keys($conf['telemt_relays'] ?? []), fn($name) => substr(hash('sha256', (string) $name), 0, 12) === $relayKey));
        $relay = count($relays) === 1 ? (string) $relays[0] : '';
        if (count($names) !== 1) { $this->telemtUsers($relay, $page); return; }
        $name = (string) $names[0];
        if (preg_match('~^qreset-([a-f0-9]{8})$~D', $action, $match)) {
            $this->telemtResetQuota($name, $page, $relay, $match[1]); return;
        }
        if (preg_match('~^period(?:-(off|daily|weekly|monthly)-([a-f0-9]{8}))?$~D', $action, $match)) {
            $this->telemtQuotaPeriod($name, $page, $relay, $match[1] ?? '', $match[2] ?? ''); return;
        }
        switch ($action) {
            case 'limits': $this->telemtUserLimits($name, $page, $relay); return;
            case 'log': $this->telemtUserLog($name, $page, $relay); return;
            case 'refresh': $this->trackTelemtOnline(true); break;
            case 'logclear': $this->telemtUserLog($name, $page, $relay, true); return;
            case 'quota': $this->telemtLimitPrompt($name, $page, $relay, 'quota'); return;
            case 'ips': $this->telemtLimitPrompt($name, $page, $relay, 'ips'); return;
            case 'deny': $this->telemtLimitPrompt($name, $page, $relay, 'deny'); return;
            case 'reset': $this->telemtResetQuota($name, $page, $relay); return;
            case 'toggle': $this->telemtToggleUser($name, $page, $relay, true, $key); return;
            case 'regen-confirm': $this->telemtRegen($name, $page, $relay, true, $key); return;
            case 'delete-confirm': $this->telemtDelUser($name, $page, $relay, $key); return;
            case 'qr': $this->telemtQr($name, $relay, true); return;
            case 'web': $this->telemtWebLink($name, true); return;
            case 'regen':
            case 'delete':
                $text = '<b>' . self::esc($name) . "</b>\n\n" . $this->i18n('telemt user confirm ' . $action);
                $data = [
                    [['text' => $this->i18n('telemt user ' . $action), 'callback_data' => $this->telemtUserCallback($name, $page, $relay, $action . '-confirm')]],
                    [['text' => $this->i18n('back'), 'callback_data' => $this->telemtUserCallback($name, $page, $relay)]],
                ];
                $this->update($this->input['chat'], $this->input['message_id'], $text, $data);
                return;
        }
        $this->telemtUserCard($name, $relay, $page);
    }

    public function telemtUserCard(string $name, string $relay = '', int $page = 0): void
    {
        $conf = $this->getPacConf();
        if (!isset($conf['telemt_users'][$name])) { $this->telemtUsers($relay, $page); return; }
        $rl = $this->telemtRelay($relay);
        if (!$rl) $relay = '';
        $enabled = !array_key_exists($name, $conf['telemt_user_enabled'] ?? []) || !empty($conf['telemt_user_enabled'][$name]);
        $native = $this->linkTelemt($name, $rl);
        $text = ['Menu → TeleMT → ' . $this->i18n('telemt users'), '<b>' . self::esc(mb_strimwidth($name, 0, 256, '…')) . '</b> · ' . $this->telemtState($enabled)];
        if (!$enabled) $text[] = $this->i18n('telemt user disabled');
        $text[] = implode("\n", $this->telemtActivityLines($name, $this->telemtActivityQuotas($conf)[$name] ?? 0));
        $text[] = $this->i18n('telemt user restart note');
        $text[] = '<b>MTProxy</b> · ' . ($relay === '' ? $this->i18n('telemt direct') : self::esc($relay)) . "\n<code>" . self::esc($native) . '</code>';
        $data = [[['text' => '🔗 MTProxy', 'url' => $native]]];
        $qr = [['text' => 'QR · MTProxy', 'callback_data' => $this->telemtUserCallback($name, $page, $relay, 'qr')]];
        if ($this->telemtWebEnabled($conf) && isset(array_flip($this->telemtWebProfiles($conf))[$name]) && $this->telemtWebVersionOk()) {
            $web = $this->linkTelemtWeb($name, $conf);
            $text[] = "<b>WEB</b>\n<code>" . self::esc($web) . '</code>';
            if ($relay !== '') $text[] = $this->i18n('telemt web direct only');
            $data[] = [['text' => '🌐 WEB', 'url' => $web]];
            $qr[] = ['text' => 'QR · WEB', 'callback_data' => $this->telemtUserCallback($name, $page, $relay, 'web')];
        } else {
            $reason = match (true) {
                empty($conf['telemt_web']) => $this->i18n('off'),
                (bool) $this->telemtWebBlockers($conf) => implode('; ', array_map(fn($key) => $this->i18n($key), $this->telemtWebBlockers($conf))),
                !$this->telemtWebVersionOk() => $this->i18n('telemt web need version'),
                default => $this->i18n('telemt web profiles capped'),
            };
            $text[] = '<b>WEB</b>: ' . $reason;
            $data[] = [['text' => $this->i18n('telemt web'), 'callback_data' => '/telemtWeb']];
        }
        $data[] = $qr;
        $data[] = [['text' => '🔄 ' . $this->i18n('refresh'), 'callback_data' => $this->telemtUserCallback($name, $page, $relay, 'refresh')]];
        $data[] = [['text' => $this->i18n('telemt limits'), 'callback_data' => $this->telemtUserCallback($name, $page, $relay, 'limits')]];
        $data[] = [['text' => '📜 ' . $this->i18n('connection log'), 'callback_data' => $this->telemtUserCallback($name, $page, $relay, 'log')]];
        $data[] = [['text' => $this->i18n($enabled ? 'telemt user disable' : 'telemt user enable'), 'callback_data' => $this->telemtUserCallback($name, $page, $relay, 'toggle')]];
        $data[] = [['text' => $this->i18n('telemt user regen'), 'callback_data' => $this->telemtUserCallback($name, $page, $relay, 'regen')]];
        $data[] = [['text' => $this->i18n('telemt user delete'), 'callback_data' => $this->telemtUserCallback($name, $page, $relay, 'delete')]];
        $data[] = [['text' => $this->i18n('back'), 'callback_data' => '/telemtUsersPage ' . max(0, $page) . ($relay === '' ? '' : ' ' . $relay)]];
        $this->update($this->input['chat'], $this->input['message_id'], implode("\n\n", $text), $data);
    }

    public function telemtMode()
    {
        $conf = $this->getPacConf();
        $mode = $this->telemtModeOf($conf);

        $text[] = "Menu -> TeleMT -> " . $this->i18n('telemt mode') . "\n";
        $text[] = "mode: " . $this->i18n("telemt mode $mode");
        $text[] = "\nℹ " . $this->i18n('telemt mode note');

        foreach (['classic', 'secure', 'tls'] as $m) {
            $data[] = [[
                'text'          => ($mode === $m ? '✅ ' : '') . $this->i18n("telemt mode $m"),
                'callback_data' => "/telemtSetMode $m",
            ]];
        }
        $data[] = $this->menuHelpButton('telemt_mode');
        $data[] = [['text' => $this->i18n('back'), 'callback_data' => "/telemt"]];
        $this->update($this->input['chat'], $this->input['message_id'], implode("\n", $text), $data);
    }

    public function telemtSetMode($mode)
    {
        if (!in_array($mode, ['classic', 'secure', 'tls'], true)) {
            return $this->telemtMode();
        }
        $changed = $this->telemtConfUpdate(static function (&$conf) use ($mode) {
            if (($conf['telemt_mode'] ?? 'tls') === $mode) return false;
            $conf['telemt_mode'] = $mode;
            return true;
        });
        if ($changed) $this->restartTelemt();
        $this->telemtMode();
    }

    // Поведение на ClientHello с чужим SNI (censorship.unknown_sni_action).
    // reject_handshake (дефолт) — как nginx ssl_reject_handshake; mask —
    // прозрачный фронт на mask_host для любого SNI (спасает при рассинхроне
    // домена ссылки и tls_domain); drop — молча закрыть.
    public function telemtSni()
    {
        $conf = $this->getPacConf();
        $sni  = $this->telemtSniOf($conf);

        $text[] = "Menu -> TeleMT -> " . $this->i18n('telemt sni') . "\n";
        $text[] = "unknown SNI: <code>$sni</code>";
        $text[] = "\nℹ " . $this->i18n('telemt sni note');

        foreach (['reject_handshake', 'mask', 'drop'] as $a) {
            $data[] = [[
                'text'          => ($sni === $a ? '✅ ' : '') . $this->i18n("telemt sni $a"),
                'callback_data' => "/telemtSetSni $a",
            ]];
        }
        $data[] = $this->menuHelpButton('telemt_sni');
        $data[] = [['text' => $this->i18n('back'), 'callback_data' => "/telemt"]];
        $this->update($this->input['chat'], $this->input['message_id'], implode("\n", $text), $data);
    }

    public function telemtSetSni($action)
    {
        if (!in_array($action, ['mask', 'reject_handshake', 'drop'], true)) {
            return $this->telemtSni();
        }
        $changed = $this->telemtConfUpdate(static function (&$conf) use ($action) {
            if (($conf['telemt_unknown_sni'] ?? 'reject_handshake') === $action) return false;
            $conf['telemt_unknown_sni'] = $action;
            return true;
        });
        if ($changed) $this->restartTelemt();
        $this->telemtSni();
    }

    // ── Меню WEB-режима ─────────────────────────────────────────────────────
    // Отдельная ветка, а не тумблер в «settings»: WEB — это второй способ
    // подключения к тому же telemt (свой vhost, свой формат ссылки, свои
    // требования к домену и сертификату), и рядом с mode/SNI обычного
    // MTProto-пути он только путал бы.
    public function telemtWeb($update = false)
    {
        $conf     = $this->getPacConf();
        $host     = $this->telemtWebHost($conf);
        $blockers = $this->telemtWebBlockers($conf);
        $on       = $this->telemtWebEnabled($conf);
        $users    = is_array($conf['telemt_users'] ?? null) ? $conf['telemt_users'] : [];
        $profiles = $this->telemtWebProfiles($conf);

        $text[] = "Menu -> TeleMT -> " . $this->i18n('telemt web') . "\n";
        $text[] = "status: " . $this->telemtState($on);
        $text[] = "host: <code>" . htmlspecialchars($host ?: '-', ENT_QUOTES) . "</code>";
        // При включённой негоциации показываем ВСЮ цепочку, а не один carrier:
        // одиночная строка «carrier: https» вводила бы в заблуждение — https
        // тут лишь последний запасной вариант.
        $cands = $this->telemtWebCandidates($conf);
        $text[] = $cands
            ? "carrier: " . implode(' → ', $cands)
            : "carrier: " . $this->telemtWebCarrierOf($conf);
        $text[] = "secret: " . $this->telemtWebSecretModeOf($conf);
        $path   = $this->telemtWebPathOf($conf);
        $diag   = $this->telemtBool($conf, 'telemt_web_diag');
        $text[] = "path: " . ($path === '' ? '/' : htmlspecialchars("/$path/", ENT_QUOTES));
        $decoy  = $this->telemtWebDecoyOf($conf);
        $text[] = "decoy: " . ($decoy === null ? $this->i18n('telemt web decoy builtin')
            : '<code>' . htmlspecialchars($decoy['origin'], ENT_QUOTES) . '</code>');
        $text[] = "profiles: " . count($profiles) . '/' . count($users);
        if (count($users) > count($profiles)) {
            $text[] = "\n⚠ " . $this->i18n('telemt web profiles capped');
        }
        foreach ($blockers as $b) {
            $text[] = "\n⚠ " . $this->i18n($b);
        }
        if (!$this->telemtWebVersionOk()) {
            $text[] = "\n⚠ " . $this->i18n('telemt web need version');
        } elseif ($cands && !$this->telemtWebNegotiationVersionOk()) {
            // Образ мог уехать назад уже ПОСЛЕ включения пресета. Без этой
            // строки оператор видел бы в меню включённый подбор, которого на
            // деле нет: restartTelemt() снял его при первом же старте.
            $text[] = "\n⚠ " . $this->i18n('telemt web negotiation need version');
        }
        // Отдельной строкой, а не в elseif выше: путь и диагностика не зависят
        // от негоциации. Проверяем версию, только когда хоть одна из фич
        // включена, — иначе лишний ssh-заход на каждое открытие меню.
        if (($path !== '' || $diag) && $this->telemtWebVersionOk() && !$this->telemtVersionAtLeast('3.5.8')) {
            $text[] = "\n⚠ " . $this->i18n('telemt web 358 need version');
        }
        if (!$blockers && !empty($conf['telemt_web'])) {
            $text[] = "\nℹ " . $this->i18n('telemt web cert hint');
        }
        if (!$cands && $this->telemtWebCarrierOf($conf) === 'https-lanes') {
            $text[] = "\n⚠ " . $this->i18n('telemt web lanes ios');
        }

        $data[] = [[
            'text'          => $this->i18n('telemt web') . ': ' . $this->telemtState(!empty($conf['telemt_web'])),
            'callback_data' => "/telemtWebToggle",
        ]];
        $data[] = [[
            'text'          => $this->i18n('telemt web transport') . ': '
                . $this->i18n('telemt web mode ' . $this->telemtWebModeOf($conf)),
            'callback_data' => "/telemtWebMode",
        ]];
        $version = ltrim($this->telemtVersion(), 'vV');
        $data[] = [[
            'text' => $this->i18n('telemt web method') . ': ' . strtoupper($this->telemtWebCarrierMethodOf($conf)),
            'callback_data' => '/telemtWebHttp method',
        ]];
        $data[] = [[
            'text' => $this->i18n('telemt web conveyor') . ': '
                . ($version !== 'unknown' && version_compare($version, '3.5.13', '>=')
                    ? $this->telemtState($this->telemtBool($conf, 'telemt_web_conveyor', true))
                    : $this->i18n('telemt web unavailable')),
            'callback_data' => '/telemtWebHttp conveyor',
        ]];
        $data[] = [[
            'text'          => 'secret: ' . $this->telemtWebSecretModeOf($conf),
            'callback_data' => "/telemtWebSecret",
        ]];
        $data[] = [[
            'text'          => $this->i18n('telemt web path') . ': ' . ($path === '' ? '/' : "/$path/"),
            'callback_data' => "/telemtWebPath",
        ]];
        $data[] = [[
            'text'          => $this->i18n('telemt web decoy') . ': '
                . ($decoy === null ? $this->i18n('telemt web decoy builtin') : $decoy['origin']),
            'callback_data' => "/telemtWebDecoy",
        ]];
        $data[] = [[
            'text'          => $this->i18n('telemt web diag') . ': ' . $this->telemtState($diag),
            'callback_data' => "/telemtWebDiag",
        ]];
        $data[] = $this->menuHelpButton('telemt');
        $data[] = [['text' => $this->i18n('back'), 'callback_data' => "/telemt"]];

        if ($update) {
            $this->update($this->input['chat'], $this->input['message_id'], implode("\n", $text), $data);
        } else {
            $this->send($this->input['chat'], implode("\n", $text), $this->input['message_id'], $data);
        }
    }

    // Включение отказывает, пока не выполнены предусловия telemt: без них
    // конфиг не загрузится и упадёт ВЕСЬ прокси, а не только WEB.
    public function telemtWebToggle()
    {
        $changed = $this->telemtConfUpdate(function (&$conf) {
            $new = empty($conf['telemt_web']);
            if ($new && ($this->telemtWebBlockers($conf) || !$this->telemtWebVersionOk())) return false;
            $conf['telemt_web'] = $new ? 1 : 0;
            return true;
        });
        if (!$changed) {
            $this->answer($this->input['callback_id'], $this->i18n('telemt web blocked'), true);
            return $this->telemtWeb(true);
        }
        $this->restartTelemt();
        // nginx: блок #-tgweb появляется и исчезает вместе с тумблером.
        $this->cloakNginx();
        $this->telemtWeb(true);
    }

    public function telemtWebModeOf(array $conf): string
    {
        $preset = $this->telemtWebNegotiationOf($conf);
        return $preset === 'off' ? $this->telemtWebCarrierOf($conf) : 'auto-' . $preset;
    }

    // Явный выбор исключает скрытое значение одиночного carrier при выходе из
    // подбора. Повторное нажатие выбранного режима не рвёт действующие сессии.
    public function telemtWebMode(string $mode = ''): void
    {
        $modes = ['auto-https', 'auto-full', 'https', 'https-lanes'];
        $negotiationOk = $this->telemtWebNegotiationVersionOk();
        if ($mode !== '' && in_array($mode, $modes, true)) {
            $changed = $this->telemtConfUpdate(function (&$conf) use ($mode, $negotiationOk) {
                if ($mode === $this->telemtWebModeOf($conf)) return false;
                if (str_starts_with($mode, 'auto-') && !$negotiationOk) {
                    $this->answer($this->input['callback_id'], $this->i18n('telemt web negotiation need version'), true);
                    return false;
                }
                $conf['telemt_web_negotiation'] = str_starts_with($mode, 'auto-') ? substr($mode, 5) : 'off';
                if (!str_starts_with($mode, 'auto-')) $conf['telemt_web_carrier'] = $mode;
                return true;
            });
            if ($changed && $this->telemtWebEnabled($this->getPacConf())) $this->restartTelemt();
        }
        $conf = $this->getPacConf();
        $selected = $this->telemtWebModeOf($conf);
        $text = ['Menu → TeleMT → WEB → ' . $this->i18n('telemt web transport'),
            $this->i18n('telemt web select mode')];
        if (!$negotiationOk) $text[] = '⚠ ' . $this->i18n('telemt web negotiation need version');
        $data = [];
        foreach ($modes as $choice) {
            $data[] = [['text' => ($choice === $selected ? '✅ ' : '') . $this->i18n('telemt web mode ' . $choice),
                'callback_data' => '/telemtWebMode ' . $choice]];
        }
        $data[] = $this->menuHelpButton('telemt_carrier');
        $data[] = [['text' => $this->i18n('back'), 'callback_data' => '/telemtWeb']];
        $this->update($this->input['chat'], $this->input['message_id'], implode("\n\n", $text), $data);
    }

    // Явный выбор, а не toggle: повтор доставленного callback не меняет
    // настройку второй раз и не переподключает пользователей.
    public function telemtWebHttp(string $setting, string $value = ''): void
    {
        if (!in_array($setting, ['method', 'conveyor'], true)) return;
        [$key, $minimum, $choices] = $setting === 'method'
            ? ['telemt_web_carrier_method', '3.5.12', ['post', 'put']]
            : ['telemt_web_conveyor', '3.5.13', ['on', 'off']];
        $current = fn(array $conf): string => $setting === 'method'
            ? $this->telemtWebCarrierMethodOf($conf)
            : ($this->telemtBool($conf, $key, true) ? 'on' : 'off');
        $version = ltrim($this->telemtVersion(), 'vV');
        $supported = $version !== 'unknown' && version_compare($version, $minimum, '>=');
        $notice = sprintf($this->i18n('telemt web http need version'), $minimum);
        if (in_array($value, $choices, true)) {
            $changed = $this->telemtConfUpdate(function (&$conf) use ($setting, $key, $value, $current, $supported, $notice) {
                if ($current($conf) === $value) return false;
                // POST остаётся доступным для возврата к старому ядру.
                if (!$supported && !($setting === 'method' && $value === 'post')) {
                    $this->answer($this->input['callback_id'], $notice, true);
                    return false;
                }
                $conf[$key] = $setting === 'method' ? $value : (int) ($value === 'on');
                return true;
            });
            if ($changed && $this->telemtWebEnabled($this->getPacConf())) $this->restartTelemt();
        }
        $selected = $current($this->getPacConf());
        $text = ['Menu → TeleMT → WEB → ' . $this->i18n('telemt web ' . $setting),
            $this->i18n('telemt web ' . $setting . ' note')];
        if (!$supported) $text[] = '⚠ ' . $notice;
        $data = [];
        foreach ($choices as $choice) {
            $data[] = [['text' => ($choice === $selected ? '✅ ' : '')
                . ($setting === 'method' ? strtoupper($choice) : $this->i18n('telemt web conveyor ' . $choice)),
                'callback_data' => '/telemtWebHttp ' . $setting . ' ' . $choice]];
        }
        $data[] = $this->menuHelpButton('telemt_' . $setting);
        $data[] = [['text' => $this->i18n('back'), 'callback_data' => '/telemtWeb']];
        $this->update($this->input['chat'], $this->input['message_id'], implode("\n\n", $text), $data);
    }

    // Смена формата секрета инвалидирует ВСЕ выданные webproxy-ссылки: тот же
    // секрет с другим префиксом — другой пользователь для telemt.
    public function telemtWebSecret()
    {
        $conf = $this->telemtConfUpdate(function (&$conf) {
            $conf['telemt_web_secret_mode'] = $this->telemtWebSecretModeOf($conf) === 'dd' ? 'plain' : 'dd';
            return $conf;
        });
        $this->restartTelemt();
        // Модалка, а не строка в меню: предупреждение важно ровно в момент
        // переключения, а висеть в тексте постоянно ему незачем.
        if (!empty($conf['telemt_users'])) {
            $this->answer($this->input['callback_id'], $this->i18n('telemt web secret changed'), true);
        }
        $this->telemtWeb(true);
    }

    // Новый случайный префикс и возврат к корню — отдельные явные действия.
    // location / в nginx уже проксирует оба варианта без изменения пути.
    public function telemtWebPath(string $action = '')
    {
        $ok      = $this->telemtVersionAtLeast('3.5.8');
        $blocked = false;
        $changed = false;
        if (in_array($action, ['generate', 'reset'], true)) {
            $changed = $this->telemtConfUpdate(function (&$conf) use ($action, $ok, &$blocked) {
                if ($action === 'generate' && !$ok) {
                    $blocked = true;
                    return false;
                }
                if ($action === 'reset' && $this->telemtWebPathOf($conf) === '') return false;
                $conf['telemt_web_path'] = $action === 'generate' ? bin2hex(random_bytes(8)) : '';
                return true;
            });
        }
        if ($blocked) {
            $this->answer($this->input['callback_id'], $this->i18n('telemt web 358 need version'), true);
        }
        if ($changed) {
            if ($this->telemtWebEnabled($this->getPacConf())) $this->restartTelemt();
            $this->answer($this->input['callback_id'], $this->i18n('telemt web path changed'), true);
        }
        $path = $this->telemtWebPathOf($this->getPacConf());
        $text = ['Menu → TeleMT → WEB → ' . $this->i18n('telemt web path'),
            'path: <code>' . self::esc($path === '' ? '/' : "/$path/") . '</code>',
            $this->i18n('telemt web path setup')];
        if (!$ok) $text[] = '⚠ ' . $this->i18n('telemt web 358 need version');
        $data = [
            [['text' => $this->i18n('telemt web path generate'), 'callback_data' => '/telemtWebPath generate']],
            [['text' => ($path === '' ? '✅ ' : '') . $this->i18n('telemt web path reset'), 'callback_data' => '/telemtWebPath reset']],
            $this->menuHelpButton('telemt_path'),
            [['text' => $this->i18n('back'), 'callback_data' => '/telemtWeb']],
        ];
        $this->update($this->input['chat'], $this->input['message_id'], implode("\n\n", $text), $data);
    }

    // Свой сайт-приманка: адрес вводится ответом на запрос, возврат к
    // встроенной странице — отдельная кнопка.
    public function telemtWebDecoyMenu(string $action = '', string $notice = '')
    {
        if ($action === 'ask') {
            $r = $this->send(
                $this->input['chat'],
                $this->t("@{$this->input['username']} введите адрес сайта-приманки, например http://", "@{$this->input['username']} enter decoy origin, e.g. http://") . self::TELEMT_WEB_DECOY_GATEWAY . ":8081",
                $this->input['message_id'],
                reply: $this->t('введите адрес сайта-приманки', 'enter decoy origin'),
            );
            $this->stashReply($r, [
                'start_message' => $this->input['message_id'],
                'callback'      => 'telemtWebDecoySet',
                'args'          => [],
            ]);
            return;
        }
        if ($action === 'reset') {
            $was    = $this->telemtWebDecoyOf($this->getPacConf()) !== null;
            $notice = $this->telemtWebDecoyApply('');
            if ($notice === '' && $was) {
                $notice = 'telemt web decoy changed';
            }
        }
        $decoy = $this->telemtWebDecoyOf($this->getPacConf());
        $text  = ['Menu → TeleMT → WEB → ' . $this->i18n('telemt web decoy'),
            'decoy: ' . ($decoy === null ? $this->i18n('telemt web decoy builtin')
                : '<code>' . self::esc($decoy['origin']) . '</code>'),
            $this->i18n('telemt web decoy setup')];
        if ($notice !== '') {
            $text[] = ($notice === 'telemt web decoy changed' ? 'ℹ ' : '⚠ ') . $this->i18n($notice);
        }
        $data = [
            [['text' => $this->i18n('telemt web decoy ask'), 'callback_data' => '/telemtWebDecoy ask']],
            [['text' => ($decoy === null ? '✅ ' : '') . $this->i18n('telemt web decoy builtin'), 'callback_data' => '/telemtWebDecoy reset']],
            [['text' => $this->i18n('back'), 'callback_data' => '/telemtWeb']],
        ];
        $this->update($this->input['chat'], $this->input['message_id'], implode("\n\n", $text), $data);
    }

    public function telemtWebDecoySet($origin)
    {
        $notice = $this->telemtWebDecoyApply((string) $origin);
        $this->telemtWebDecoyMenu('', $notice === '' ? 'telemt web decoy changed' : $notice);
    }

    // Отчёты бриджа Telegram Desktop о сбоях до рукопожатия (web.debug.sideband).
    public function telemtWebDiag()
    {
        $ok      = $this->telemtVersionAtLeast('3.5.8');
        $blocked = false;
        $conf = $this->telemtConfUpdate(function (&$conf) use ($ok, &$blocked) {
            $new = !$this->telemtBool($conf, 'telemt_web_diag');
            // Выключить можно всегда — иначе на откатившемся образе оператор
            // заперт во включённом тумблере.
            if ($new && !$ok) {
                $blocked = true;
                return $conf;
            }
            $conf['telemt_web_diag'] = $new ? 1 : 0;
            return $conf;
        });
        if ($blocked) {
            $this->answer($this->input['callback_id'], $this->i18n('telemt web 358 need version'), true);
            return $this->telemtWeb(true);
        }
        if ($this->telemtWebEnabled($conf)) {
            $this->restartTelemt();
        }
        $this->telemtWeb(true);
    }

    // Ссылка tg://webproxy + QR. Relay здесь не применим: хост обязан
    // совпадать с vhost telemt и с именем в сертификате, а порт — быть 443.
    public function telemtWebLink($name, bool $keepMenu = false)
    {
        $conf = $this->getPacConf();
        // Та же проверка, что и у кнопки: пользователь без WEB-профиля получил
        // бы ссылку, которую telemt не примет. Кнопка Telegram живёт вечно —
        // после появления новых пользователей и сдвига за лимит нажатие может
        // прийти и на неё.
        // Сравнение через array_flip + isset, а не in_array со строгим
        // сравнением: имя из чисел json_decode отдаёт INT-ключом массива, а из
        // callback_data оно всегда приходит строкой — строгое сравнение такого
        // пользователя не нашло бы никогда (та же ловушка описана у relay).
        $webUsers = array_flip($this->telemtWebProfiles($conf));
        if (empty($conf['telemt_users'][$name])
            || !$this->telemtWebEnabled($conf)
            || !isset($webUsers[$name])) {
            return $this->telemtUsers();
        }
        $link = $this->linkTelemtWeb($name, $conf);
        if ($link === '') {
            return $this->telemtUsers();
        }
        if (!$this->telemtSendQr((string) $name, $link, 'WEB')) return;
        if (!$keepMenu && ($this->getPacConf()['blinkmenu'] ?? false)) {
            $this->delete($this->input['chat'], $this->input['message_id']);
            $this->input['message_id'] = $this->send($this->input['chat'], '.')['result']['message_id'];
            $this->telemt();
        }
    }

    // Домен и сертификат едут в [[web.vhosts]], поэтому после их смены конфиг
    // telemt обязан быть перегенерирован — иначе прокси остаётся на старом
    // vhost и молча отдаёт всем decoy.
    public function telemtWebSync(): void
    {
        if (!empty($this->getPacConf()['telemt_web'])) {
            $enabled = $this->protocolModuleEnabled('telemt');
            if ($this->restartTelemt() === false
                || ($enabled && ($this->sshFailed || empty($this->getPacConf()['telemt_web'])))) {
                throw new RuntimeException($this->t('Не удалось применить SSL TeleMT', 'Could not apply TeleMT SSL'));
            }
        }
    }

    // WEB живёт в ДВУХ конфигах сразу — telemt.toml и nginx, — и включаться
    // они обязаны вместе. Вызывается там, где меняется не тумблер, а
    // предусловие (последний пользователь удалён, первый заведён): $was —
    // состояние ДО правки.
    public function telemtWebRefresh(bool $was): void
    {
        if ($was !== $this->telemtWebEnabled($this->getPacConf())) {
            $this->cloakNginx();
        }
    }

    // --- Dedicated TeleMT relays (separate from xray $pac['relays']) ----------
    // Stored as $pac['telemt_relays'][<name>] = ['address'=>'', 'portmap'=>[src=>dst]].
    // Used only to rewrite the tg://proxy link server+port; never restarts telemt.

    public function telemtRelays()
    {
        $relays = $this->getPacConf()['telemt_relays'] ?? [];

        $text[] = "Menu -> TeleMT -> " . $this->i18n('telemt relays');
        $text[] = $this->i18n('relay hint');

        $data = [];
        foreach ($relays as $name => $r) {
            $data[] = [[
                'text'          => "$name: " . ($r['address'] ?: '—'),
                'callback_data' => "/telemtRelayEdit $name",
            ]];
        }
        $data[] = [['text' => '➕ ' . $this->i18n('add relay'), 'callback_data' => '/telemtRelayAdd']];
        $data[] = $this->menuHelpButton('telemt_relays');
        $data[] = [['text' => $this->i18n('back'), 'callback_data' => '/telemt']];
        $this->update($this->input['chat'], $this->input['message_id'], implode("\n", $text), $data ?: false);
    }

    public function telemtRelayAdd()
    {
        $r = $this->send(
            $this->input['chat'],
            "@{$this->input['username']} " . $this->i18n('enter relay name'),
            $this->input['message_id'],
            reply: $this->i18n('enter relay name'),
        );
        $this->stashReply($r, [
            'start_message' => $this->input['message_id'],
            'callback'      => 'telemtRelaySetName',
            'args'          => [],
        ]);
    }

    public function telemtRelaySetName($text)
    {
        $c    = $this->getPacConf();
        $name = trim($text);
        if (!preg_match('~^[\w.\-]{1,32}$~', $name) || isset($c['telemt_relays'][$name])) {
            $this->telemtRelays();
            return;
        }
        $this->telemtConfUpdate(static function (&$current) use ($name) {
            $current['telemt_relays'][$name] ??= ['address' => '', 'port' => '', 'portmap' => []];
        });
        $this->telemtRelayEdit($name);
    }

    public function telemtRelayEdit($name)
    {
        $p = $this->getPacConf();
        $r = $p['telemt_relays'][$name] ?? null;
        if ($r === null) {
            $this->telemtRelays();
            return;
        }

        $text[] = "Menu -> TeleMT -> " . $this->i18n('telemt relays')
            . ' -> <b>' . self::esc($name) . '</b>';
        $text[] = $this->i18n('relay address') . ': <code>' . self::esc($r['address'] ?: '—') . '</code>';
        // Явный порт перебивает карту портов — показываем это прямо в карточке.
        $text[] = $this->i18n('relay port') . ': <code>' . self::esc(($r['port'] ?? '') ?: '—') . '</code>';
        if (!empty($r['portmap'])) {
            $pm = [];
            foreach ($r['portmap'] as $src => $dst) {
                $pm[] = "$src:$dst";
            }
            $text[] = $this->i18n('relay port map') . ': <code>' . self::esc(implode(', ', $pm)) . '</code>';
        } else {
            $text[] = $this->i18n('relay port map') . ': —';
        }

        $data[] = [['text' => $this->i18n('relay address'), 'callback_data' => "/setTelemtRelayAddress $name"]];
        $data[] = [
            ['text' => $this->i18n('relay port'), 'callback_data' => "/setTelemtRelayPort $name"],
            ['text' => $this->i18n('relay port map'), 'callback_data' => "/setTelemtRelayPortMap $name"],
        ];
        $data[] = [['text' => $this->i18n('relay delete'), 'callback_data' => "/telemtRelayDel $name"]];
        $data[] = [['text' => $this->i18n('back'), 'callback_data' => '/telemtRelays']];
        $this->update($this->input['chat'], $this->input['message_id'], implode("\n", $text), $data ?: false);
    }

    public function telemtRelayAddressPrompt($name)
    {
        $r = $this->send(
            $this->input['chat'],
            "@{$this->input['username']} " . $this->i18n('enter relay address'),
            $this->input['message_id'],
            reply: $this->i18n('enter relay address'),
        );
        $this->stashReply($r, [
            'start_message' => $this->input['message_id'],
            'callback'      => 'telemtRelaySetAddress',
            'args'          => [$name],
        ]);
    }

    public function telemtRelaySetAddress($text, $name = '')
    {
        $c = $this->getPacConf();
        if (!isset($c['telemt_relays'][$name])) {
            $this->telemtRelays();
            return;
        }
        // 0/пусто — очистка: relay выпадает из селектора telemtUsers
        // (там фильтр по непустому address).
        if (!$this->relayClearInput($text) && !$this->isHostOrIp($text)) {
            $this->telemtRelayEdit($name);
            return;
        }
        $this->telemtConfUpdate(function (&$current) use ($name, $text) {
            if (isset($current['telemt_relays'][$name])) $current['telemt_relays'][$name]['address'] = $this->relayClearInput($text) ? '' : trim($text);
        });
        $this->telemtRelayEdit($name);
    }

    public function telemtRelayPortPrompt($name)
    {
        $r = $this->send(
            $this->input['chat'],
            "@{$this->input['username']} " . $this->i18n('enter relay port'),
            $this->input['message_id'],
            reply: $this->i18n('enter relay port'),
        );
        $this->stashReply($r, [
            'start_message' => $this->input['message_id'],
            'callback'      => 'telemtRelaySetPort',
            'args'          => [$name],
        ]);
    }

    // У telemt ровно один порт, поэтому явный порт — обычный путь, а portmap
    // остаётся для совместимости со старыми записями. 0/мусор — очистка.
    public function telemtRelaySetPort($text, $name = '')
    {
        $c = $this->getPacConf();
        if (!isset($c['telemt_relays'][$name])) {
            $this->telemtRelays();
            return;
        }
        $this->telemtConfUpdate(function (&$current) use ($name, $text) {
            if (isset($current['telemt_relays'][$name])) $current['telemt_relays'][$name]['port'] = self::relayPortInput($text);
        });
        $this->telemtRelayEdit($name);
    }

    public function telemtRelayPortMapPrompt($name)
    {
        $r = $this->send(
            $this->input['chat'],
            "@{$this->input['username']} " . $this->i18n('enter relay port map'),
            $this->input['message_id'],
            reply: $this->i18n('enter relay port map'),
        );
        $this->stashReply($r, [
            'start_message' => $this->input['message_id'],
            'callback'      => 'telemtRelaySetPortMap',
            'args'          => [$name],
        ]);
    }

    public function telemtRelaySetPortMap($text, $name = '')
    {
        $c = $this->getPacConf();
        if (!isset($c['telemt_relays'][$name])) {
            $this->telemtRelays();
            return;
        }
        // 0/пусто — очистка (parseRelayPortMap('0') и так даст []).
        $this->telemtConfUpdate(function (&$current) use ($name, $text) {
            if (isset($current['telemt_relays'][$name])) $current['telemt_relays'][$name]['portmap'] = $this->relayClearInput($text) ? [] : $this->parseRelayPortMap($text);
        });
        $this->telemtRelayEdit($name);
    }

    public function telemtRelayDel($name)
    {
        $this->telemtConfUpdate(static function (&$current) use ($name) {
            unset($current['telemt_relays'][$name]);
            if (empty($current['telemt_relays'])) unset($current['telemt_relays']);
        });
        $this->telemtRelays();
    }

    public function telemtSettings()
    {
        $conf = $this->getPacConf();
        $domain = $conf['telemt_domain'] ?? 'www.google.com';
        $ports = $this->getPorts()['telemt'];

        $text[] = "Menu -> TeleMT -> " . $this->i18n('telemt settings') . "\n";
        $text[] = "port: " . ($ports['enable'] ? $ports['port'] : $this->i18n('port unavailable'));
        $text[] = "fake-TLS domain: <code>" . htmlspecialchars($domain, ENT_QUOTES) . "</code>";
        $text[] = "fast mode: " . $this->i18n('on');

        $data[] = [['text' => $this->i18n('changeFakeDomain'), 'callback_data' => "/telemtDomain"]];
        $data[] = $this->menuHelpButton('telemt_settings');
        $data[] = [['text' => $this->i18n('back'), 'callback_data' => "/telemt"]];
        $this->update($this->input['chat'], $this->input['message_id'], implode("\n", $text), $data);
    }

    public function telemtMasking()
    {
        $conf = $this->getPacConf();
        $items = [
            'telemt_mask_hardening' => 'shape hardening',
            'telemt_mask_aggressive' => 'aggressive hardening',
            'telemt_mask_blur' => 'above-cap blur',
            'telemt_mask_timing' => 'timing normalization',
        ];

        $text[] = "Menu -> TeleMT -> " . $this->i18n('telemt masking') . "\n";
        foreach ($items as $key => $title) {
            $state = $this->telemtBool($conf, $key, $this->telemtMaskDefault($key));
            $text[] = "$title: " . $this->telemtState($state);
            $data[] = [[
                'text' => "$title: " . $this->telemtState($state),
                'callback_data' => "/telemtToggle $key masking",
            ]];
        }
        // Эти 4 опции усиливают только anti-probe cover-path и не влияют на
        // трафик реальных клиентов. TLS-эмуляция клиентского хендшейка включена;
        // session tickets по дефолту telemt = 0 и переопределяются отдельно.
        $data[] = $this->menuHelpButton('telemt_mask');
        $data[] = [['text' => $this->i18n('back'), 'callback_data' => "/telemt"]];
        $this->update($this->input['chat'], $this->input['message_id'], implode("\n", $text), $data);
    }

    public function telemtDiagnostics()
    {
        $conf = $this->getPacConf();
        $enabled = $this->telemtBool($conf, 'telemt_beobachten', false);
        $minutes = $this->telemtInt($conf, 'telemt_beobachten_minutes', 10, 1, 1440);

        $st      = $this->ssh('pgrep -x telemt', 'telemt') ? 'on' : 'off';
        $bfile   = '/config/telemt/data/beobachten.txt';
        $btxt    = is_file($bfile) ? trim((string) file_get_contents($bfile)) : '';
        $bcount  = $btxt === '' ? 0 : count(preg_split('~\R~', $btxt));

        $text[] = "Menu -> TeleMT -> " . $this->i18n('telemt diagnostics') . "\n";
        $text[] = "service: $st";
        $text[] = "beobachten: " . $this->telemtState($enabled);
        $text[] = "retention: $minutes min";
        $text[] = "JA3/JA4 observed: " . ($enabled ? "$bcount line(s)" : 'off');
        $text[] = "loopback API (127.0.0.1): " . $this->telemtState($enabled);
        if ($enabled) {
            $text[] = "\n📊 " . $this->i18n('telemt report') . " — health · traffic · users · masking · security";
        }

        $data[] = [[
            'text' => 'beobachten: ' . $this->telemtState($enabled),
            'callback_data' => "/telemtToggle telemt_beobachten diagnostics",
        ]];
        $data[] = [[
            'text' => "retention: $minutes min",
            'callback_data' => "/telemtCycleBeobachtenMinutes",
        ]];
        if ($enabled) {
            $data[] = [['text' => $this->i18n('telemt report'), 'callback_data' => "/telemtReport"]];
        }
        $data[] = [['text' => $this->i18n('telemt observe'), 'callback_data' => "/telemtShowBeobachten"]];
        $data[] = $this->menuHelpButton('telemt_diagnostics');
        $data[] = [['text' => $this->i18n('back'), 'callback_data' => "/telemt"]];
        $this->update($this->input['chat'], $this->input['message_id'], implode("\n", $text), $data);
    }

    public function telemtToggle($key, $return)
    {
        $allowed = [
            'telemt_beobachten' => true,
            'telemt_mask_hardening' => true,
            'telemt_mask_aggressive' => true,
            'telemt_mask_blur' => true,
            'telemt_mask_timing' => true,
        ];
        if (empty($allowed[$key])) {
            return $this->telemt(true);
        }
        $this->telemtConfUpdate(function (&$conf) use ($key) {
            $new = $this->telemtBool($conf, $key, $this->telemtMaskDefault($key)) ? 0 : 1;
            $conf[$key] = $new;
            if ($new && in_array($key, ['telemt_mask_aggressive', 'telemt_mask_blur'], true)) $conf['telemt_mask_hardening'] = 1;
            if (!$new && $key === 'telemt_mask_hardening') {
                $conf['telemt_mask_aggressive'] = 0;
                $conf['telemt_mask_blur'] = 0;
            }
        });
        $this->restartTelemt();
        return $return === 'diagnostics' ? $this->telemtDiagnostics() : $this->telemtMasking();
    }

    public function telemtCycleBeobachtenMinutes()
    {
        $this->telemtConfUpdate(function (&$conf) {
            $values = [5, 10, 30, 60, 180, 360, 720, 1440];
            $current = $this->telemtInt($conf, 'telemt_beobachten_minutes', 10, 1, 1440);
            $i = array_search($current, $values, true);
            $conf['telemt_beobachten_minutes'] = $values[$i === false || $i === count($values) - 1 ? 0 : $i + 1];
        });
        $this->restartTelemt();
        $this->telemtDiagnostics();
    }

    public function telemtToggleUser($name, int $page = 0, string $relay = '', bool $card = false, ?string $identity = null)
    {
        $changed = $this->telemtConfUpdate(function (&$conf) use ($name, $identity) {
            if (empty($conf['telemt_users'][$name])) return false;
            if ($identity !== null && $this->telemtUserIdentity((string) $name, $conf) !== $identity) return false;
            if (!is_array($conf['telemt_user_enabled'] ?? null)) $conf['telemt_user_enabled'] = [];
            $cur = array_key_exists($name, $conf['telemt_user_enabled']) ? !empty($conf['telemt_user_enabled'][$name]) : true;
            $conf['telemt_user_enabled'][$name] = $cur ? 0 : 1;
            return true;
        });
        if ($changed) $this->restartTelemt();
        if ($card) $this->telemtUserCard((string) $name, $relay, $page);
        else $this->telemtUsers($relay, $page);
    }

    public function telemtShowBeobachten()
    {
        if (!$this->telemtBool($this->getPacConf(), 'telemt_beobachten', false)) {
            $this->answer($this->input['callback_id'], 'beobachten off', true);
            return $this->telemtDiagnostics();
        }
        // beobachten ведёт журнал JA3/JA4 в файл (telemtToml: beobachten_file).
        // /telemt/data в контейнере telemt = /config/telemt/data в php-контейнере.
        $file = '/config/telemt/data/beobachten.txt';
        $out  = is_file($file) ? trim((string) file_get_contents($file)) : '';
        if ($out === '') {
            $out = 'no beobachten data yet';
        } else {
            // хвост, чтобы уложиться в лимит сообщения Telegram
            $out = ltrim(substr($out, -3500));
        }
        $this->send($this->input['chat'], "<pre>" . htmlspecialchars($out, ENT_QUOTES) . "</pre>", $this->input['message_id']);
    }

    // Один ssh-заход в контейнер telemt: дёргаем перечисленные /v1/* эндпоинты
    // управляющего API на 127.0.0.1:9091. API слушает только loopback внутри
    // контейнера и наружу не публикуется; включён лишь при beobachten = on.
    // Возвращаем path => распакованный envelope.data (или null при ошибке).
    public function telemtApiFetch(array $paths): array
    {
        $cmd = '';
        foreach ($paths as $p) {
            $url  = 'http://127.0.0.1:9091' . $p;
            $cmd .= "printf '@@@%s@@@\\n' " . escapeshellarg($p) . "; "
                  . "wget -qO- -T 3 " . escapeshellarg($url) . " 2>/dev/null; "
                  . "printf '\\n'; ";
        }
        $raw    = (string) $this->ssh($cmd, 'telemt');
        $result = array_fill_keys($paths, null);
        // Режем вывод по маркерам @@@/v1/...@@@ и декодируем тело каждого.
        $parts = preg_split('~@@@(/v1/[^@]+)@@@\n~', $raw, -1, PREG_SPLIT_DELIM_CAPTURE);
        for ($i = 1; $i + 1 < count($parts); $i += 2) {
            $body = trim($parts[$i + 1]);
            if ($body === '') {
                continue;
            }
            $j = json_decode($body, true);
            if (is_array($j) && !empty($j['ok']) && array_key_exists('data', $j)) {
                $result[$parts[$i]] = $j['data'];
            }
        }
        return $result;
    }

    // Счётчики событий диагностики бриджа за последний час: имя события => число.
    // JSON-маршрута для записей трассы у telemt нет, они есть только на
    // HTML-странице /web-status того же loopback-API. Страницу режем grep'ом
    // ещё внутри контейнера: по ssh едут лишь ячейки строк bridge_diagnostic
    // (событие — в колонке status), а не мегабайт разметки с IP клиентов.
    // window_secs = 3600 — дефолтный потолок web.debug.max_window_secs,
    // limit = 1000 — потолок самого маршрута. Одной страницы мало: кольцо
    // делят с событиями бриджа HTTP-записи, а lane-carrier'ы дают их десятки
    // на сессию. Идём по ссылке «Next page» (before_seq): кольцо пинуется на
    // debug_records_capacity = 4096 записей, пяти страниц хватает на всё.
    public function telemtBridgeDiagnostics(): array
    {
        $raw = (string) $this->ssh(<<<'SH'
            b=; i=0; while [ $i -lt 5 ]; do
            p=$(wget -qO- -T 3 "http://127.0.0.1:9091/web-status?window_secs=3600&limit=1000${b:+&before_seq=$b}" 2>/dev/null)
            printf '%s\n' "$p" | grep -o 'bridge_diagnostic</td><td>-</td><td>[a-z_]*</td>'
            b=$(printf '%s\n' "$p" | grep -o 'before_seq=[0-9]*' | tail -n 1 | cut -d= -f2)
            [ -n "$b" ] || break; i=$((i+1)); done
            SH, 'telemt');
        preg_match_all('~bridge_diagnostic</td><td>-</td><td>([a-z_]+)</td>~', $raw, $m);
        return array_count_values($m[1]);
    }

    public function telemtReport()
    {
        $conf = $this->getPacConf();
        if (!$this->telemtBool($conf, 'telemt_beobachten', false)) {
            $this->answer($this->input['callback_id'], 'beobachten off', true);
            return $this->telemtDiagnostics();
        }
        $api = $this->telemtApiFetch([
            '/v1/health', '/v1/health/ready', '/v1/system/info',
            '/v1/stats/summary', '/v1/stats/users', '/v1/security/posture',
            '/v1/runtime/web/status',
        ]);
        $h     = $api['/v1/health'] ?? [];
        $ready = $api['/v1/health/ready'] ?? [];
        $info  = $api['/v1/system/info'] ?? [];
        $sum   = $api['/v1/stats/summary'] ?? [];
        $users = $api['/v1/stats/users'] ?? null;
        $sec   = $api['/v1/security/posture'] ?? [];
        $web   = is_array($api['/v1/runtime/web/status'] ?? null) ? $api['/v1/runtime/web/status'] : [];

        $uptime = function ($s) {
            $s = (int) $s;
            $d = intdiv($s, 86400);
            $s %= 86400;
            return ($d ? "{$d}d " : '') . sprintf('%02d:%02d', intdiv($s, 3600), intdiv($s % 3600, 60));
        };
        $yn = fn($v) => !empty($v) ? '✓' : '✗';

        $L   = ["TeleMT diagnostics"];

        // ── Состояние ──
        $L[] = "\n▌ Health / build";
        if ($h || $ready || $info) {
            $L[] = "live: " . (($h['status'] ?? '') === 'ok' ? '✓ ok' : '✗ ' . ($h['status'] ?? 'n/a'));
            if ($ready) {
                $rl = !empty($ready['ready']) ? '✓ ready' : '✗ ' . ($ready['status'] ?? 'not_ready');
                if (!empty($ready['reason'])) {
                    $rl .= " ({$ready['reason']})";
                }
                $L[] = "ready: $rl";
                $L[] = "upstreams: " . ($ready['healthy_upstreams'] ?? '?') . "/" . ($ready['total_upstreams'] ?? '?') . " healthy";
            }
            if ($info) {
                $L[] = "version: " . ($info['version'] ?? '?') . " (" . ($info['target_arch'] ?? '?') . "/" . ($info['target_os'] ?? '?') . ")";
                $L[] = "uptime: " . $uptime($info['uptime_seconds'] ?? 0);
                $hash = (string) ($info['config_hash'] ?? '');
                $L[] = "config: " . ($hash !== '' ? substr($hash, 0, 12) : '?') . ", reloads: " . ($info['config_reload_count'] ?? 0);
            }
        } else {
            $L[] = "API unreachable — beobachten just enabled? retry in a few seconds";
        }

        // ── Трафик ──
        if ($sum) {
            $L[] = "\n▌ Traffic (since start)";
            $L[] = "connections: " . ($sum['connections_total'] ?? 0) . " (bad " . ($sum['connections_bad_total'] ?? 0) . ")";
            $L[] = "handshake timeouts: " . ($sum['handshake_timeouts_total'] ?? 0);
            foreach (['connections_bad_by_class' => 'bad', 'handshake_failures_by_class' => 'hs-fail'] as $k => $lbl) {
                if (!empty($sum[$k]) && is_array($sum[$k])) {
                    $cl = [];
                    foreach (array_slice($sum[$k], 0, 6) as $c) {
                        $cl[] = ($c['class'] ?? '?') . '=' . ($c['total'] ?? 0);
                    }
                    if ($cl) {
                        $L[] = "$lbl: " . implode(', ', $cl);
                    }
                }
            }
        }

        // ── WEB-бридж ──
        // Секция целиком из /v1/runtime/web/status (telemt >= 3.5.6: до неё в
        // ответе не было ни ingress, ни capacity). Без WEB маршрут отвечает
        // ошибкой, telemtApiFetch отдаёт null — секции просто нет.
        //
        // Счётчики у telemt монотонные и с ФИКСИРОВАННЫМ набором ключей: полный
        // список исходов и причин отказа — это два десятка строк «=0», которые
        // съели бы половину лимита сообщения. Печатаем только ненулевые.
        if ($web) {
            $ing = is_array($web['ingress'] ?? null) ? $web['ingress'] : [];
            $cap = is_array($web['capacity'] ?? null) ? $web['capacity'] : [];
            $lif = is_array($web['lifecycle_counters'] ?? null) ? $web['lifecycle_counters'] : [];
            $nz  = function ($rows, string $key): string {
                $out = [];
                foreach (is_array($rows) ? $rows : [] as $r) {
                    if (is_array($r) && !empty($r['total'])) {
                        $out[] = ($r[$key] ?? '?') . '=' . $r['total'];
                    }
                }
                return $out
                    ? implode(', ', array_slice($out, 0, 8)) . (count($out) > 8 ? ' …' : '')
                    : '—';
            };
            $L[] = "\n▌ WEB (Telegram Desktop / Android)";
            // Единственная строка, которую отдаёт и старый образ: lifecycle,
            // available и reason есть в ответе с самого появления WEB.
            $L[] = "runtime: " . ($web['lifecycle'] ?? '?')
                . (empty($web['available']) ? ' ✗ ' . ($web['reason'] ?? 'unavailable') : ' ✓');
            // Ниже — планы наблюдения из 3.5.6. На образе 3.5.5 этих объектов в
            // ответе нет вовсе, и строки просто не печатаются: показывать «?»
            // там, где данных не существует, хуже, чем не показывать ничего.
            if ($ing) {
                $L[] = "ingress: " . (!empty($ing['accepting_connections'])
                        ? '✓ accepting' : '✗ ' . ($ing['reason'] ?? 'n/a'))
                    . "  acceptors: " . ($ing['live_acceptors'] ?? '?')
                    . "/" . ($ing['configured_listeners'] ?? '?');
                $L[] = "accepted: " . ($ing['tcp_accept_total'] ?? 0)
                    . " (errors " . ($ing['tcp_accept_error_total'] ?? 0) . ")";
            }
            if ($cap) {
                // Ровно то, ради чего в конфиге стоит
                // http_connection_capacity_action: видно и саму политику, и чем
                // кончались попытки принять сокет сверх max_http_connections
                // (wait_admitted — дождались ёмкости, wait_timeout_503 — не
                // дождались и ответили 503).
                $L[] = "overload: " . ($cap['http_connection_capacity_action'] ?? '?')
                    . ", " . ($cap['max_http_overload_connections'] ?? '?') . " slots @ "
                    . ($cap['http_overload_timeout_ms'] ?? '?') . "ms — "
                    . $nz($cap['http_connection_overload_outcomes'] ?? [], 'outcome');
                $sat = array_filter((array) ($cap['saturated_resources'] ?? []), 'is_string');
                $L[] = "saturated: " . ($sat ? implode(', ', array_slice($sat, 0, 6)) : '—');
                $L[] = "rejections: " . $nz($cap['rejections'] ?? [], 'reason');
            }
            if ($lif) {
                // Восстановление бриджа после смены сети или возврата вкладки из
                // фона (3.5.6): сессия пересоздаётся без перезапуска клиента.
                $L[] = "recovery (" . ($lif['bridge_recovery_secs'] ?? '?') . "s): "
                    . $nz($lif['bridge_recovery_events'] ?? [], 'event');
            }
            // Диагностика бриджа (3.5.8): эффективное состояние считаем как
            // сам telemt — все три флага политики сразу. Объект runtime есть
            // только у живого рантайма, у образа старше 3.5.8 нет sideband.
            $dbg = is_array($web['runtime']['debug'] ?? null) ? $web['runtime']['debug'] : [];
            $pol = is_array($dbg['policy'] ?? null) ? $dbg['policy'] : [];
            if (array_key_exists('sideband', $pol)) {
                $side = !empty($pol['enabled']) && !empty($pol['sideband']) && !empty($pol['capture_lifecycle']);
                $L[] = "bridge diag: " . ($side ? '✓ sideband' : '✗ off')
                    . ", records " . ($dbg['records'] ?? '?') . "/" . ($dbg['records_capacity'] ?? '?');
                if ($side) {
                    $ev = $this->telemtBridgeDiagnostics();
                    arsort($ev);
                    $out = [];
                    foreach ($ev as $name => $n) {
                        $out[] = "$name=$n";
                    }
                    $L[] = "bridge events (1h): " . ($out ? implode(', ', $out) : '—');
                }
            }
        }

        // ── Пользователи ──
        $L[] = "\n▌ Users";
        if (is_array($users)) {
            $names = [];
            foreach ($users as $u) {
                $names[] = is_array($u) ? (string) ($u['username'] ?? $u['name'] ?? '?') : (string) $u;
            }
            $L[] = "active views: " . count($users)
                . (isset($sum['configured_users']) ? " (configured " . $sum['configured_users'] . ")" : '');
            if ($names) {
                $L[] = implode(', ', array_slice($names, 0, 20)) . (count($names) > 20 ? ' …' : '');
            }
        } else {
            $L[] = "n/a";
        }

        // ── Маскировка / fingerprint ──
        $L[] = "\n▌ Masking / fingerprint (JA3/JA4)";
        $L[] = "fake-TLS domain: " . ($conf['telemt_domain'] ?? 'www.google.com');
        $maskRow = [];
        foreach (['telemt_mask_hardening' => 'harden', 'telemt_mask_aggressive' => 'aggr', 'telemt_mask_blur' => 'blur', 'telemt_mask_timing' => 'timing'] as $k => $lbl) {
            $maskRow[] = "$lbl " . ($this->telemtBool($conf, $k, $this->telemtMaskDefault($k)) ? 'on' : 'off');
        }
        $L[] = "shaping: " . implode(', ', $maskRow);
        $bfile = '/config/telemt/data/beobachten.txt';
        $btxt  = is_file($bfile) ? trim((string) file_get_contents($bfile)) : '';
        if ($btxt === '') {
            $L[] = "beobachten: no observations yet";
        } else {
            $blines = preg_split('~\R~', $btxt);
            $L[] = "beobachten: " . count($blines) . " line(s), retention "
                . $this->telemtInt($conf, 'telemt_beobachten_minutes', 10, 1, 1440) . "m — last:";
            foreach (array_slice($blines, -8) as $bl) {
                $L[] = "  " . $bl;
            }
        }

        // ── Безопасность ──
        if ($sec) {
            $L[] = "\n▌ Security posture";
            $L[] = "api: loopback 127.0.0.1 (not published, nft-dropped on host)";
            $L[] = "read_only: " . $yn($sec['api_read_only'] ?? false)
                . "  whitelist: " . ($sec['api_whitelist_entries'] ?? 0) . " cidr"
                . "  auth_header: " . $yn($sec['api_auth_header_enabled'] ?? false);
            $L[] = "log_level: " . ($sec['log_level'] ?? '?')
                . "  telemetry: core " . $yn($sec['telemetry_core_enabled'] ?? false)
                . ", user " . $yn($sec['telemetry_user_enabled'] ?? false);
        }

        $msg = implode("\n", $L);
        if (mb_strlen($msg) > 3900) {
            $msg = mb_substr($msg, 0, 3900) . "\n…";
        }
        $this->send($this->input['chat'], "<pre>" . htmlspecialchars($msg, ENT_QUOTES) . "</pre>", $this->input['message_id']);
    }

    public function telemtQr($name, $relay = '', bool $keepMenu = false)
    {
        $conf = $this->getPacConf();
        if (empty($conf['telemt_users'][$name])) {
            $this->telemtUsers($relay);
            return;
        }
        $link    = $this->linkTelemt($name, $relay !== '' ? $this->telemtRelay($relay) : null);
        if (!$this->telemtSendQr((string) $name, $link, 'MTProxy')) return;
        if (!$keepMenu && ($this->getPacConf()['blinkmenu'] ?? false)) {
            $this->delete($this->input['chat'], $this->input['message_id']);
            $this->input['message_id'] = $this->send($this->input['chat'], '.')['result']['message_id'];
            $this->telemt();
        }
    }

    private function telemtSendQr(string $name, string $link, string $kind): bool
    {
        // Разные запросы не должны перезаписывать общий telemt.png с чужой
        // ссылкой. Временный файл приватный и удаляется также при ошибке API.
        $file = tempnam(sys_get_temp_dir(), 'telemt-qr-');
        if ($file === false) {
            $this->answer($this->input['callback_id'], $this->i18n('telemt qr failed'), true);
            return false;
        }
        try {
            exec('qrencode -t png -o ' . escapeshellarg($file) . ' ' . escapeshellarg($link), $out, $rc);
            clearstatcache(true, $file);
            if ($rc !== 0 || filesize($file) === 0) {
                $this->answer($this->input['callback_id'], $this->i18n('telemt qr failed'), true);
                return false;
            }
            $this->sendPhoto($this->input['chat'], curl_file_create($file),
                '<b>' . self::esc(mb_strimwidth($name, 0, 64, '…')) . ' · ' . $kind . "</b>\n" . self::esc($link));
            return true;
        } finally {
            @unlink($file);
        }
    }

    public function telemtAddUser()
    {
        $r = $this->send(
            $this->input['chat'],
            $this->t("@{$this->input['username']} введите имя пользователя", "@{$this->input['username']} enter user name"),
            $this->input['message_id'],
            reply: $this->t('введите имя пользователя', 'enter user name'),
        );
        $this->stashReply($r, [
            'start_message' => $this->input['message_id'],
            'callback'      => 'telemtUserAdd',
            'args'          => [],
        ]);
    }

    public function telemtUserAdd($name)
    {
        $name = preg_replace('~[^A-Za-z0-9_]~', '', trim($name));
        // Сохраняем предел 20 символов для совместимости старых callback-
        // кнопок, в которых передавались полные имена пользователя и relay.
        // Новые карточки используют короткие ключи и для старых длинных имён.
        if ($name === '' || strlen($name) > 20) {
            $this->telemtUsers();
            return;
        }
        $was = $this->telemtWebEnabled($this->getPacConf());
        $changed = $this->telemtConfUpdate(function (&$conf) use ($name) {
            if (isset($conf['telemt_users'][$name])) return false;
            $conf['telemt_users'][$name] = $this->telemtSecret();
            unset($conf['telemt_user_enabled'][$name], $conf['telemt_user_limits'][$name]);
            return true;
        });
        if (!$changed) { $this->telemtUsers(); return; }
        $this->restartTelemt();
        $this->telemtWebRefresh($was);
        $this->telemtUsers();
    }

    public function telemtDelUser($name, int $page = 0, string $relay = '', ?string $identity = null)
    {
        $was = $this->telemtWebEnabled($this->getPacConf());
        $changed = $this->telemtConfUpdate(function (&$conf) use ($name, $identity) {
            if (!isset($conf['telemt_users'][$name])) return false;
            if ($identity !== null && $this->telemtUserIdentity((string) $name, $conf) !== $identity) return false;
            unset($conf['telemt_users'][$name], $conf['telemt_user_enabled'][$name], $conf['telemt_user_limits'][$name]);
            return true;
        });
        // Новый пользователь с тем же именем не наследует чужой журнал и трафик.
        if ($changed) {
            $this->telemtActivityForget((string) $name);
            $this->restartTelemt();
            $this->telemtWebRefresh($was);
        }
        $this->telemtUsers($relay, $page);
    }

    public function telemtRegen($name, int $page = 0, string $relay = '', bool $card = false, ?string $identity = null)
    {
        $changed = $this->telemtConfUpdate(function (&$conf) use ($name, $identity) {
            if (!isset($conf['telemt_users'][$name])) return false;
            if ($identity !== null && $this->telemtUserIdentity((string) $name, $conf) !== $identity) return false;
            $conf['telemt_users'][$name] = $this->telemtSecret();
            return true;
        });
        if ($changed) $this->restartTelemt();
        if ($card) $this->telemtUserCard((string) $name, $relay, $page);
        else $this->telemtUsers($relay, $page);
    }

    public function telemtDomain()
    {
        $r = $this->send(
            $this->input['chat'],
            $this->t("@{$this->input['username']} введите домен fake-TLS (или 0 по умолчанию)", "@{$this->input['username']} enter fake-TLS domain (or 0 for default)"),
            $this->input['message_id'],
            reply: $this->t('введите домен', 'enter domain'),
        );
        $this->stashReply($r, [
            'start_message' => $this->input['message_id'],
            'callback'      => 'setTelemtDomain',
            'args'          => [],
        ]);
    }

    public function setTelemtDomain($domain)
    {
        $domain = trim($domain);
        if ($domain !== '' && $domain !== '0' && !self::dnsttDomainOk($domain)) {
            $this->update($this->input['chat'], $this->input['message_id'], 'wrong domain');
            sleep(2);
            $this->telemtSettings();
            return;
        }
        $this->telemtConfUpdate(static function (&$conf) use ($domain) {
            if ($domain === '' || $domain === '0') unset($conf['telemt_domain']);
            else $conf['telemt_domain'] = strtolower($domain);
        });
        $this->restartTelemt();
        $this->telemtSettings();
    }

    public static function dnsttDomainOk(string $domain): bool
    {
        return (bool) preg_match('~^(?=.{1,253}$)[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?(?:\.[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?)+$~iD', $domain);
    }

    public function dnsttStart()
    {
        return (bool) $this->withLock('dnstt', fn() => $this->dnsttStartLocked(), 120, false);
    }

    private function dnsttStartLocked(): bool
    {
        try {
            $c = $this->getPacConf(); $settings = [];
            if (!empty($c['dnsttDomain']) && !empty($c['dnsttPassword'])) {
                if (!is_string($c['dnsttDomain']) || !self::dnsttDomainOk($c['dnsttDomain'])
                    || !is_string($c['dnsttPassword']) || strlen($c['dnsttPassword']) > 128 || preg_match('~[\x00\r\n]~', $c['dnsttPassword'])) return false;
                $hash = crypt($c['dnsttPassword'], '$6$' . bin2hex(random_bytes(8)) . '$');
                if (!str_starts_with($hash, '$6$')) return false;
                $settings = ['domain' => $c['dnsttDomain'], 'password_hash' => $hash];
            }
            $this->pacConfUpdate(static function (&$pac) { $pac['dnstt_apply_pending'] = 1; });
            $directory = dirname($this->pac) . '/dnstt';
            if (!is_dir($directory) && !@mkdir($directory, 0700, true)) return false;
            if (!$this->writePrivateKey($directory . '/settings.json', json_encode($settings, JSON_THROW_ON_ERROR))) return false;
            if ($this->protocolModuleEnabled('dnstt')) {
                // The wrapper confirms controller readiness AND reloads restored
                // sshd host keys; the marker appears only after both succeed.
                $out = $this->ssh('/bin/sh /start_dnstt.sh --reload', 'dnstt');
                if ($this->sshFailed || trim((string) $out) !== 'dnstt-ready') return false;
                $this->sshHostKeyRememberDnstt();
            }
            $this->pacConfUpdate(static function (&$pac) { unset($pac['dnstt_apply_pending']); });
            return true;
        } catch (Throwable $error) { return false; }
    }

    public function dnsttDownload()
    {
        $this->sendFile($this->input['from'], curl_file_create('/config/dnstt/server.pub'));
    }

    public function dnstt($update = false)
    {
        if (!$this->protocolModuleEnabled('dnstt')) { $this->protocolModulesMenu(); return; }
        $c      = $this->getPacConf();
        $pubkey = is_file('/config/dnstt/server.pub') ? file_get_contents('/config/dnstt/server.pub') : '';
        $text[] = "dnstt";
        if (!empty($c['dnstt_apply_pending'])) $text[] = $this->t('⚠️ Настройки ожидают подтверждения применения. Прежние сеансы могут оставаться активными.', '⚠️ Settings await confirmed apply. Previous sessions may remain active.');
        if (!empty($c['dnsttDomain']) && !empty($c['dnsttPassword'])) {
            // dnsttDomain и dnsttPassword — сырой ввод (сеттеры кладут trim
            // как есть), а сообщение уходит с parse_mode=HTML.
            $dnsttDomain = self::esc($c['dnsttDomain']);
            $text[] = "<pre>set the NS record for $dnsttDomain: tns." . self::esc($c['domain'])
                . "\nset A record for tns." . self::esc($c['domain']) . ": {$this->ip}</pre>";
            $text[] = 'account: <code>vpnbot:' . self::esc($c['dnsttPassword']) . '</code>';
            $text[] = "server name: <code>$dnsttDomain</code>";
            $text[] = "public key: <code>$pubkey</code>";
            $data[] = [
                [
                    'text'          => $this->i18n('download pubkey'),
                    'callback_data' => "/dnsttDownload",
                ],
            ];
        } else {
            $text[] = "set subdomain and password";
        }

        $data[] = [
            [
                'text'          => $this->i18n('set subdomain'),
                'callback_data' => "/dnsttDomain",
            ],
        ];
        $data[] = [
            [
                'text'          => $this->i18n('set password'),
                'callback_data' => "/dnsttPassword",
            ],
        ];
        $data[] = [
            [
                'text'          => $this->i18n('back'),
                'callback_data' => "/menu",
            ],
        ];
        if ($update) {
            $this->update(
                $this->input['chat'],
                $this->input['message_id'],
                implode("\n", $text),
                $data ?: false,
            );
        } else {
            $this->send(
                $this->input['chat'],
                implode("\n", $text),
                $this->input['message_id'],
                $data ?: false,
            );
        }
    }

    // Внешний порт сервиса, когда его секции нет в /docker/compose (маппинг снят
    // через меню портов). По умолчанию берётся порт внутри контейнера, но у wg1
    // он совпадает с wg — а этот фолбэк уезжает клиентам в Endpoint
    // (saveClients/createConfig/getAmneziaShortLink читают
    // ports[getInstanceWG()]['port']), и владельцы пиров ПЕРВОГО инстанса
    // получали конфиг, указывающий на НУЛЕВОЙ. 51821 — как в
    // docker-compose.override.yml.
    // ВНУТРЕННИЙ порт ssserver. Он фиксирован: start_ss.sh переписывает
    // server_port в конфиге на 8388 при каждом старте, docker маппит на него
    // внешний порт, а sslocal/cloak/simple-tls коннектятся именно сюда.
    // Раньше все эти места читали getenv('SSPORT') — то есть заданный кем-то
    // SSPORT (например, внешний порт из override.env) разом ломал и bind
    // ssserver'а, и апстримы cloak/simple-tls. Внешний порт живёт отдельно и
    // идёт только в ss://-ссылку (buildSSLink/menuSS).
    public const SS_INTERNAL_PORT = 8388;

    public const PORT_FALLBACK = [
        'wg' => '51820',
        'wg1' => '51821',
        'telemt' => '9443',
        'hy' => '5443',
    ];

    public function getPorts()
    {
        $f = '/docker/compose';
        $c = is_file($f) ? (yaml_parse_file($f) ?: []) : [];
        $r = [];
        foreach ($this->ports as $k => $v) {
            $r[$k] = [
                'port'   => !empty($c['services'][$k]['ports'])
                    ? explode(':', $c['services'][$k]['ports'][0])[0]
                    : (self::PORT_FALLBACK[$k] ?? explode('/', $v)[0]),
                'enable' => !empty($c['services'][$k]['ports']),
            ];
        }
        return $r;
    }

    // Живые пробы всех сервисов для главного меню: 15+ ssh-раундов + exec —
    // дорого (секунды). Напрямую из меню не вызывать — только через
    // serviceStatuses()/refreshMenuStatusCache().
    public function probeServiceStatuses()
    {
        $pac = $this->getPacConf();
        return [
            'wg'     => (bool) $this->ssh(!empty($pac['amnezia']) ? 'awg' : 'wg', 'wg'),
            'wg1'    => (bool) $this->ssh(!empty($pac['wg1_amnezia']) ? 'awg' : 'wg', 'wg1'),
            'xray'   => (bool) $this->ssh('pgrep xray', 'xr'),
            'naive'  => (bool) $this->ssh('pgrep caddy', 'np'),
            'oc'     => (bool) $this->ssh('pgrep ocserv', 'oc'),
            'hy'     => (bool) $this->ssh('pgrep hysteria', 'hy'),
            'tt'     => (bool) $this->ssh('pgrep -f trusttunnel_endpoint', 'tt'),
            'ovpn'   => (bool) $this->ssh('pgrep openvpn', 'ovpn'),
            'l2tp'   => (bool) $this->ssh('pgrep xl2tpd', 'ipsec'),
            'ikev2'  => (bool) $this->ssh('pgrep charon', 'ipsec'),
            'ad'     => (bool) exec("JSON=1 timeout 2 dnslookup google.com ad"),
            'ss'     => (bool) $this->ssh('pgrep ssserver', 'ss'),
            'dnstt'  => (bool) $this->ssh('pgrep dnstt', 'dnstt'),
            'telemt' => (bool) $this->ssh('pgrep -x telemt', 'telemt'),
            'warp'   => $this->warpStatus(),
            'cron'   => (bool) $this->ssh('pgrep -f cron.php', 'service'),
        ];
    }

    // Статусы для главного меню из кэша (/logs общий у php- и service-
    // контейнеров; cron держит кэш тёплым). Возвращает ['ts' => …, 'st' => …].
    // 90с = три пропущенных cron-цикла: считаем кэш мёртвым (cron лежит?)
    // и пробуем живьём, как раньше.
    public function serviceStatuses($force = false)
    {
        $f = '/logs/menu_status.json';
        if (!$force && is_file($f)) {
            $c = json_decode((string) file_get_contents($f), true);
            if (!empty($c['ts']) && time() - $c['ts'] < 90 && !empty($c['st'])) {
                return $c;
            }
        }
        $r = ['ts' => time(), 'st' => $this->probeServiceStatuses()];
        file_put_contents($f, json_encode($r), LOCK_EX);
        return $r;
    }

    // Шаг cron() (service-контейнер): обновляем кэш каждые ~30с, чтобы рендер
    // главного меню никогда не ходил по ssh сам.
    public function refreshMenuStatusCache()
    {
        $f = '/logs/menu_status.json';
        $c = is_file($f) ? json_decode((string) file_get_contents($f), true) : [];
        if (empty($c['ts']) || time() - $c['ts'] >= 30) {
            $this->serviceStatuses(true);
        }
    }

    // Возраст кэша статусов в секундах; null — кэша ещё нет.
    public function menuStatusAge()
    {
        $f = '/logs/menu_status.json';
        $c = is_file($f) ? json_decode((string) file_get_contents($f), true) : [];
        return empty($c['ts']) ? null : max(0, time() - (int) $c['ts']);
    }

    // ── Версии сервисов для главного меню ────────────────────────────────────
    // Путь вынесен в константу, а не размазан литералом по пяти методам: одно
    // место правки и возможность подменить файл в тестах (обращение через
    // static::, поэтому наследник может переопределить).
    protected const MENU_VERSIONS_FILE = '/logs/menu_versions.json';

    // Кэш ОТДЕЛЬНЫЙ от статусов, и TTL у него на три порядка больше. Статус
    // меняется сам по себе (процесс упал) и потому обновляется каждые ~30с,
    // а версия — только при пересборке образа, то есть между рестартами
    // контейнера не меняется вообще. Гонять 15 ssh раз в полминуты ради
    // неизменных строк незачем.
    //
    // Инвалидация — в selfUpdate(), который зовётся из service.php на КАЖДОМ
    // старте service-контейнера: ровно тогда версии и могли поехать. Так что
    // час здесь — потолок для случая «образ подменили под работающим ботом»,
    // а нормальный путь обновления показывает новые версии сразу.
    public const MENU_VERSIONS_TTL = 3600;

    // Пока снялись не все версии — повторяем через две минуты, а не через час.
    // Нужен ровно для одного, зато частого случая: selfUpdate() снимает кэш на
    // старте service-контейнера, а первый заход cron приходится на момент,
    // когда часть контейнеров ещё поднимает sshd. Без короткого ретрая
    // «медленный» сервис (ipsec, ovpn) выпадал бы из меню на целый час.
    public const MENU_VERSIONS_RETRY_TTL = 120;

    // Потолок коротких ретраев. Без него неполный снимок ретраился бы вечно:
    // достаточно одного контейнера, остановленного насовсем, — и cron каждые
    // две минуты гонял бы 15 ssh, упираясь в 5-секундный таймаут на мёртвом.
    // Пять заходов (~10 минут) хватает, чтобы дождаться медленно стартующих
    // (ipsec, ovpn), дальше переходим на штатный час. Счётчик обнуляется, как
    // только снимок собрался полностью.
    public const MENU_VERSIONS_RETRY_MAX = 5;

    // Ключ пробы → подпись в меню. Константа, а не литерал в рендере: тот же
    // список задаёт ПОЛНОТУ ответа для refreshMenuVersionsCache(), и разъехаться
    // эти два места не должны.
    public const MENU_VERSION_LABELS = [
        'wg'     => 'wg',
        'awggo'  => 'awg-go',
        'awg'    => 'awg-tools',
        'warp'   => 'wgcf',
        'xray'   => 'xray',
        'ad'     => 'adguard',
        'oc'     => 'ocserv',
        'np'     => 'naive',
        'hy'     => 'hysteria',
        'telemt' => 'telemt',
        'ss'     => 'shadowsocks',
        'tt'     => 'trusttunnel',
        'ovpn'   => 'openvpn',
        'ipsec'  => 'strongswan',
        'l2tp'   => 'xl2tpd',
        'ng'     => 'nginx',
        'php'    => 'php',
        'unit'   => 'unit',
    ];

    // Один ssh на КОНТЕЙНЕР, а не на бинарь: несколько версий из одного
    // контейнера снимаются одной командой с printf-метками — приём wgVersions().
    // head -1 обязателен почти везде: hysteria, openvpn, ipsec и unitd печатают
    // многострочные «карточки», а pickVersion() разбирает строку с меткой.
    //
    // Значения СЫРЫЕ, без htmlspecialchars: экранирует рендер. Иначе из кэша
    // они приезжали бы экранированными второй раз (ср. hysteriaVersion() и
    // warpVersion() — те готовят строку сразу для своего экрана, поэтому здесь
    // не переиспользуются).
    public function probeServiceVersions(): array
    {
        // ВНИМАНИЕ: $cmd подставляется в ОДИНАРНЫЕ кавычки — одиночная кавычка
        // внутри команды порвёт строку. Все команды тут литеральные и обходятся
        // двойными; при правке это условие надо сохранять.
        $ask = function (string $service, string $cmd): string {
            return (string) $this->ssh("sh -c '$cmd'", $service);
        };
        $v = [];

        // wg и wg1 — один и тот же образ, поэтому опрашиваем только нулевой.
        $out      = $ask('wg', 'printf "wg:"; wg --version 2>/dev/null | head -1; printf "awg:"; awg --version 2>/dev/null | head -1; '
            . 'printf "\nawggo:"; cat /etc/amneziawg-go_version 2>/dev/null');
        $v['wg']  = $this->pickVersion($out, 'wg');
        $v['awg'] = $this->pickVersion($out, 'awg');
        // Реализация протокола — amneziawg-go; его тег пишется в образ при сборке.
        $v['awggo'] = $this->pickVersion($out, 'awggo');

        // wgcf вписывается в /etc/wgcf_version при сборке: версии 2.2.31+ не
        // знают ни `--version`, ни `version` (подробности в warpVersion()).
        $v['warp'] = $this->pickVersion(
            $ask('wp', 'printf "wgcf:"; cat /etc/wgcf_version 2>/dev/null || wgcf --version 2>&1 | head -1'),
            'wgcf'
        );

        $v['xray']   = $this->pickVersion($ask('xr', 'printf "xray:"; xray version 2>&1 | head -1'), 'xray');
        $v['ad']     = $this->pickVersion($ask('ad', 'printf "ad:"; /opt/adguardhome/AdGuardHome --version 2>&1 | head -1'), 'ad');
        $v['oc']     = $this->pickVersion($ask('oc', 'printf "oc:"; ocserv --version 2>&1 | head -1'), 'oc');
        $v['np']     = $this->pickVersion($ask('np', 'printf "np:"; caddy version 2>/dev/null | head -1'), 'np');
        // hysteria печатает многострочную карточку — версия в строке «Version:».
        $v['hy']     = $this->pickVersion($ask('hy', 'printf "hy:"; hysteria version 2>/dev/null | grep -i -m1 version'), 'hy');
        // telemt версию по CLI не отдаёт (неизвестный флаг уходит в дефолтный
        // Run) — она впечена в образ файлом, см. telemtVersion().
        $v['telemt'] = $this->pickVersion($ask('telemt', 'printf "telemt:"; cat /etc/telemt_version 2>/dev/null | head -1'), 'telemt');
        $v['ss']     = $this->pickVersion($ask('ss', 'printf "ss:"; ssserver --version 2>&1 | head -1'), 'ss');
        $v['tt']     = $this->pickVersion($ask('tt', 'printf "tt:"; trusttunnel_endpoint --version 2>&1 | head -1'), 'tt');
        $v['ovpn']   = $this->pickVersion($ask('ovpn', 'printf "ovpn:"; openvpn --version 2>&1 | head -1'), 'ovpn');

        // strongSwan 6.1 собирается со swanctl, без устаревшего CLI ipsec.
        // Fallback нужен старым образам. Пустую версию отделяем переводом
        // строки, иначе версия xl2tpd попадёт под метку ipsec.
        // У xl2tpd НЕ head -1: `xl2tpd -v` печатает первой строкой пустую, и
        // head отдавал бы её вместо версии (проверено на боевом контейнере).
        $out        = $ask('ipsec', 'sswan_version=$(swanctl --version 2>/dev/null || ipsec version 2>/dev/null); printf "ipsec:%s\n" "$sswan_version"; printf "l2tp:"; xl2tpd -v 2>&1 | grep -i -m1 version');
        $v['ipsec'] = $this->pickVersion($out, 'ipsec');
        $v['l2tp']  = $this->pickVersion($out, 'l2tp');

        $v['ng'] = $this->pickVersion($ask('ng', 'printf "ng:"; nginx -v 2>&1 | head -1'), 'ng');

        // php и Unit — БЕЗ ssh: в php-контейнере sshd не поднимается, коннект
        // туда просто не проходит. Спрашивать некого и не нужно — контейнеры
        // php и service собраны из одного образа (ghcr.io/axiomshiftbit/vpnbot-php),
        // поэтому версии внутри service, где крутится cron, те же самые.
        $v['php']  = PHP_VERSION;
        $v['unit'] = $this->pickVersion('unit:' . trim((string) shell_exec('unitd --version 2>&1 | head -1')), 'unit');

        return array_filter($v, fn($x) => $x !== null && $x !== '');
    }

    public function serviceVersions(bool $force = false): array
    {
        $c = $this->menuVersionsCache();
        // isset, а не !empty: если все пробы легли (контейнеры не отвечают), в
        // кэше лежит пустой массив — и с !empty каждый нефорсированный вызов
        // заново гонял бы 15 ssh, то есть ровно тогда, когда ssh и так не
        // работает. Пустой ответ — тоже ответ, ждём TTL.
        if (!$force && !empty($c['ts']) && time() - $c['ts'] < self::MENU_VERSIONS_TTL && isset($c['v'])) {
            return $c;
        }
        // Объединение с прошлым снимком, а не замена: сервис, не ответивший в
        // этот заход, показывает прежнее значение вместо того, чтобы пропасть
        // из меню до следующего TTL. Принцип тот же, что в awgToolsVersion():
        // «ssh лёг» и «версии нет» — разные вещи, и моргнувший ssh не должен
        // стирать уже известное. Ключи из свежей пробы приоритетны (оператор +
        // сохраняет левый операнд), поэтому обновление версии не теряется.
        $v    = $this->probeServiceVersions() + $this->menuVersions();
        $full = count($v) >= count(self::MENU_VERSION_LABELS);
        $r    = [
            'ts'  => time(),
            'try' => $full ? 0 : ((int) ($c['try'] ?? 0)) + 1,
            'v'   => $v,
        ];
        file_put_contents(static::MENU_VERSIONS_FILE, json_encode($r), LOCK_EX);
        return $r;
    }

    // Шаг cron() (service-контейнер).
    public function refreshMenuVersionsCache()
    {
        $c = $this->menuVersionsCache();
        // Неполный снимок — короткий ретрай: часть контейнеров могла не успеть
        // поднять sshd (см. MENU_VERSIONS_RETRY_TTL). Но не бесконечно — после
        // MENU_VERSIONS_RETRY_MAX заходов считаем, что сервиса просто нет, и
        // возвращаемся к штатному часу.
        $full = is_array($c['v'] ?? null) && count($c['v']) >= count(self::MENU_VERSION_LABELS);
        $ttl  = (!$full && (int) ($c['try'] ?? 0) < self::MENU_VERSIONS_RETRY_MAX)
            ? self::MENU_VERSIONS_RETRY_TTL
            : self::MENU_VERSIONS_TTL;
        if (empty($c['ts']) || time() - $c['ts'] >= $ttl) {
            $this->serviceVersions(true);
        }
    }

    // Пометить кэш версий протухшим, не трогая значения: cron переснимет их на
    // ближайшем цикле (≤10с), а меню до тех пор показывает прошлые. Именно
    // «протухшим», а не удалённым, — иначе блок версий моргал бы пустотой.
    public function expireMenuVersionsCache(): void
    {
        $f = static::MENU_VERSIONS_FILE;
        if (!is_file($f)) {
            return;
        }
        $c = json_decode((string) file_get_contents($f), true);
        if (is_array($c)) {
            $c['ts'] = 0;
            file_put_contents($f, json_encode($c), LOCK_EX);
        }
    }

    // Версии для РЕНДЕРА — только из кэша, без единой пробы. serviceStatuses()
    // при мёртвом кэше идёт опрашивать живьём, и это оправдано: статус, которому
    // полторы минуты, врёт. Здесь так делать нельзя — 15 ssh на каждую отрисовку
    // главного меню (а его перерисовывает почти каждая кнопка) стоят секунд
    // задержки ради строк, которые не меняются неделями. Пока cron не наполнил
    // кэш, блок версий просто не выводится.
    public function menuVersions(): array
    {
        $c = $this->menuVersionsCache();
        return is_array($c['v'] ?? null) ? $c['v'] : [];
    }

    // Разобранный файл кэша целиком (ts / try / v). Отдельный метод, потому что
    // читать его нужно из трёх мест, а json_decode отдаёт null и на пустом
    // файле, и на мусоре: cleanLog() ЗАТИРАЕТ всё в /logs пустотой, так что
    // пустой файл здесь — штатное состояние, а не поломка.
    protected function menuVersionsCache(): array
    {
        $f = static::MENU_VERSIONS_FILE;
        $c = is_file($f) ? json_decode((string) file_get_contents($f), true) : null;
        return is_array($c) ? $c : [];
    }

    // Кнопка 🔄 status главного меню: живые пробы + перерисовка.
    public function refreshMain()
    {
        if (!empty($this->input['callback_id'])) {
            $this->answer($this->input['callback_id'], '🔄 ' . $this->i18n('refreshed'));
        }
        $this->serviceStatuses(true);
        // Версии — только помечаем протухшими, переснимет cron. Опрашивать их
        // здесь живьём нельзя: serviceStatuses(true) выше это уже 16 ssh, и на
        // лежащих контейнерах каждый упирается в 5-секундный таймаут коннекта.
        // Ещё 15 проб удвоили бы худшее время удержания вебхук-воркера (~80с →
        // ~150с), а Telegram на таких паузах успевает переслать апдейт заново.
        // Выгоды никакой: версия меняется только с образом, а этот путь и так
        // накрыт selfUpdate() на старте контейнера.
        $this->expireMenuVersionsCache();
        // The menu compares HEAD with origin/<branch>; checkVersion() fetches it
        // only hourly. "Status" is the explicit check: fetch now (bounded).
        $this->fetchUpdates();
        $this->menu();
    }

    protected function fetchUpdates(): void
    {
        exec('timeout 10 git -C / fetch -q 2>/dev/null');
    }

    public function menu($type = false, $arg = false, $return = false)
    {
        if (is_string($type) && !$this->protocolModuleEnabled($type)) {
            $this->protocolModulesMenu();
            return;
        }
        $conf   = $this->getPacConf();
        $domain = $conf['domain'] ?: $this->ip;
        $hash   = $this->getHashBot();
        $managedProtocolButtons = [];
        if ($type == false) {
            $update = exec('git -C / rev-list --count HEAD..@{u}');
            $branch = exec('git -C / rev-parse --abbrev-ref HEAD');
            // array_values + array_pad: array_filter СОХРАНЯЕТ ключи, поэтому
            // «/1 month» давало [1 => …] без нулевого индекса, а строка без
            // слэша — [0 => …] без первого. И то и другое — Undefined array key
            // плюс strtotime(null) на КАЖДОМ открытии главного меню. Ровно так
            // уже сделано в checkBackup().
            $backup = array_pad(array_values(array_filter(explode('/', $conf['backup'] ?? ''))), 2, '');
            if (!empty(array_filter($backup))) {
                if (!empty(strtotime($backup[0])) && !empty(strtotime($backup[1]))) {
                    $backup = "{$backup[0]} start / {$backup[1]} period";
                } else {
                    $backup = "{$conf['backup']} - wrong format";
                }
            }
            // Статусы сервисов — из кэша (cron обновляет каждые ~30с):
            // рендер главного меню больше не делает 15+ ssh-проб сам.
            $status = $this->serviceStatuses();
            $st     = $status['st'];
            $cron   = $this->dontshowcron ? '' : $this->i18n($st['cron'] ? 'on' : 'off') . ' cron';
            $f      = '/docker/compose';
            $c      = is_file($f) ? (yaml_parse_file($f)['services'] ?? []) : [];
            // BUILD_COMMIT пишется post-receive скриптом в .env перед make r,
            // чтобы в меню был идентификатор сборки даже когда VER
            // (git describe --tags) пустой из-за отсутствия тегов в репе.
            // При установке по ссылке / git clone post-receive не вызывается,
            // поэтому BUILD_COMMIT пуст — в этом случае берём короткий SHA
            // прямо из git, чтобы в меню всё равно был номер коммита.
            $commit = getenv('BUILD_COMMIT') ?: exec('git -C / rev-parse --short HEAD');
            $main[] = 'v' . getenv('VER') . " $branch"
                . ($commit ? " @$commit" : '')
                // Ключи 'have updates' и 'no updates' в словаре есть с самого
                // начала (у en они ещё и с индикатором 🟢/⚪), но подставить их
                // забыли: русскому пользователю показывалась английская строка.
                . ' ' . $this->i18n($update ? 'have updates' : 'no updates');

            // Версии сервисов — сразу под версией самого бота: обе строки про
            // «что здесь стоит», логично держать их вместе. В ДВЕ колонки, а не
            // в одну: 17 строк — половина экрана, а лимит сообщения (4096
            // символов) на сервере с доменом и алиасами расходуется и без того
            // заметно.
            //
            // Цитата обычная, не <blockquote expandable>: сворачиваемый вариант
            // выглядел бы аккуратнее, но проверить его, не отправив сообщение в
            // боевой чат, нельзя, а ошибка разбора HTML роняет не блок версий,
            // а весь рендер главного меню. Обычный <blockquote><code> в этом
            // файле уже используется и работает.
            $ver   = $this->menuVersions();
            $cells = [];
            foreach (self::MENU_VERSION_LABELS as $k => $label) {
                if ($this->protocolModuleEnabled($k) && !empty($ver[$k])) {
                    $cells[] = $label . ' ' . htmlspecialchars((string) $ver[$k], ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
                }
            }
            $cells = array_merge($cells, $this->managedProtocolVersionCells());
            if (!empty($cells)) {
                // Раскладка по столбцам, а не по строкам: alignColumns()
                // выравнивает КАЖДЫЙ столбец по своей ширине, поэтому левый
                // столбец должен содержать первую половину списка целиком.
                $half  = (int) ceil(count($cells) / 2);
                $left  = array_slice($cells, 0, $half);
                // alignColumns() индексирует все столбцы по длине первого —
                // добиваем короткий пустыми ячейками, иначе Undefined key.
                $right = array_pad(array_slice($cells, $half), count($left), '');
                $main[] = '<blockquote><code>';
                $main[] = 'versions';
                $main[] = 'sb = sing-box';
                // rtrim: alignColumns() добивает пробелами и ПОСЛЕДНИЙ столбец,
                // то есть каждая строка тащит хвост из невидимых пробелов. На
                // семнадцати строках это под сотню символов из лимита в 4096,
                // который на сервере с доменом и алиасами не бесконечный.
                $main[] = implode("\n", array_map('rtrim', explode("\n", $this->alignColumns([$left, $right]))));
                $main[] = '</code></blockquote>';
            }

            if (!empty($conf['domain'])) {
                $main[] = '';
                $oc     = $this->getHashSubdomain('oc');
                $np     = $this->getHashSubdomain('np');
                if (!empty($conf['domain'])) {
                    $ssl_expiry = $this->expireCert();
                    $certs      = $this->domainsCert() ?: [];

                    $main[] = "<blockquote>";
                    $main[] = "Domains:";
                    $main[] = $conf['domain'] . (in_array($conf['domain'], $certs) ? ' (ssl: ' . date('Y-m-d H:i:s', $ssl_expiry) . ')' : '');
                    if (!empty($np)) {
                        $main[] = 'naive ' . "$np.{$conf['domain']}" . (in_array("$np.{$conf['domain']}", $certs) ? ' (ssl: ' . date('Y-m-d H:i:s', $ssl_expiry) . ')' : '');
                    }
                    if ($this->protocolModuleEnabled('oc') && !empty($oc)) {
                        $main[] = 'openconnect ' . "$oc.{$conf['domain']}" . (in_array("$oc.{$conf['domain']}", $certs) ? ' (ssl: ' . date('Y-m-d H:i:s', $ssl_expiry) . ')' : '');
                    }
                    array_push($main, ...$this->managedProtocolDomainLines());
                    if (!empty($conf['adguardkey'])) {
                        $main[] = "{$conf['adguardkey']}.{$conf['domain']}" . (in_array("{$conf['adguardkey']}.{$conf['domain']}", $certs) ? ' (ssl: ' . date('Y-m-d H:i:s', $ssl_expiry) . ')' : '') . ' adguard DOT';
                    }
                    foreach ($conf['domain_aliases'] ?? [] as $a) {
                        $main[] = "alias $a" . (in_array($a, $certs) ? ' (ssl: ' . date('Y-m-d H:i:s', $ssl_expiry) . ')' : '');
                        // У алиаса та же точка входа DoT, что и у главного
                        // домена: «renew SSL» кладёт adguardkey.<алиас> в SAN.
                        // Без этой строки её нигде не было видно.
                        if (!empty($conf['adguardkey'])) {
                            $main[] = "{$conf['adguardkey']}.$a" . (in_array("{$conf['adguardkey']}.$a", $certs) ? ' (ssl: ' . date('Y-m-d H:i:s', $ssl_expiry) . ')' : '') . ' adguard DOT';
                        }
                    }
                    $main[] = "</blockquote>";
                } else {
                    $main[] = $this->i18n('domain explain');
                }
            }


            $ports  = $this->getPorts();
            $main[] = '';

            $ipsecPorts = $this->ipsecPorts();

            $main[] = '<code>';
            $protocolColumns = $this->optionalProtocolColumns([
                [
                    $this->i18n($st['wg'] ? 'on' : 'off') . ' ' . $this->i18n(!empty($this->getPacConf()['amnezia']) ? 'amnezia' : 'wg_title'),
                    $this->i18n($st['wg1'] ? 'on' : 'off') . ' ' . $this->i18n(!empty($this->getPacConf()['wg1_amnezia']) ? 'amnezia' : 'wg_title'),
                    $this->i18n($st['xray'] ? 'on' : 'off') . ' ' . $this->i18n('xray'),
                    $this->i18n($st['naive'] ? 'on' : 'off') . ' ' . $this->i18n('naive'),
                    $this->i18n($st['oc'] ? 'on' : 'off') . ' ' . $this->i18n('ocserv'),
                    $this->i18n($st['hy'] ? 'on' : 'off') . ' ' . $this->i18n('hysteria'),
                    $this->i18n($st['tt'] ? 'on' : 'off') . ' ' . $this->i18n('TrustTunnel'),
                    $this->i18n($st['ovpn'] ? 'on' : 'off') . ' ' . $this->i18n('OpenVPN'),
                    $this->i18n($st['l2tp'] ? 'on' : 'off') . ' L2TP/IPsec',
                    $this->i18n($st['ikev2'] ? 'on' : 'off') . ' IKEv2',
                    $this->i18n($st['ad'] ? 'on' : 'off') . ' ' . $this->i18n('ad_title'),
                    $this->i18n($st['ss'] ? 'on' : 'off') . ' ' . $this->i18n('sh_title'),
                    $this->i18n($st['dnstt'] ? 'on' : 'off') . ' ' . $this->i18n('dnstt'),
                    $this->i18n($st['telemt'] ? 'on' : 'off') . ' ' . $this->i18n('telemt'),
                    $this->i18n($st['warp']) . ' ' . $this->i18n('warp'),
                ],
                [
                    $this->i18n($ports['wg']['enable'] ? 'on' : 'off') . ($ports['wg']['enable'] ? ' ' . $ports['wg']['port'] : ' port unavailable'),
                    $this->i18n($ports['wg1']['enable'] ? 'on' : 'off') . ($ports['wg1']['enable'] ? ' ' . $ports['wg1']['port'] : ' port unavailable'),
                    $this->i18n('on') . ' 443',
                    $this->i18n('on') . ' 443',
                    $this->i18n('on') . ' 443',
                    $this->i18n($ports['hy']['enable'] ? 'on' : 'off') . ($ports['hy']['enable'] ? ' ' . $ports['hy']['port'] : ' port unavailable'),
                    $this->i18n($st['tt'] ? 'on' : 'off') . ' ' . (isset($c['tt']['ports'][0]) ? explode(':', $c['tt']['ports'][0])[0] : getenv('TTPORT')),
                    $this->i18n($st['ovpn'] ? 'on' : 'off') . ' ' . (isset($c['ovpn']['ports'][0]) ? explode(':', $c['ovpn']['ports'][0])[0] : getenv('OVPNPORT')),
                    $this->i18n($st['l2tp'] ? 'on' : 'off') . " {$ipsecPorts['ike']},{$ipsecPorts['natt']}",
                    $this->i18n($st['ikev2'] ? 'on' : 'off') . " {$ipsecPorts['ike']},{$ipsecPorts['natt']}",
                    $this->i18n($ports['ad']['enable'] ? 'on' : 'off') . ($ports['ad']['enable'] ? ' ' . $ports['ad']['port'] : ' port unavailable'),
                    $this->i18n($ports['ss']['enable'] ? 'on' : 'off') . ($ports['ss']['enable'] ? ' ' . $ports['ss']['port'] : ' port unavailable'),
                    $this->i18n($ports['dnstt']['enable'] ? 'on' : 'off') . ($ports['dnstt']['enable'] ? ' ' . $ports['dnstt']['port'] : ' port unavailable'),
                    $this->i18n($ports['telemt']['enable'] ? 'on' : 'off') . ($ports['telemt']['enable'] ? ' ' . $ports['telemt']['port'] : ' port unavailable'),
                    '',
                ],
            ]);
            foreach (ManagedProtocol::NAMES as $protocol => $label) {
                if (!$this->protocolModuleEnabled($protocol)) continue;
                try {
                    $store = $this->protocolStore($protocol);
                    $state = $store->read();
                    if (!$state['enabled']) continue;
                    $runtime = $store->status();
                    $portApplied = $this->protocolPortApplied($protocol, $state);
                    $ready = !$runtime['stale'] && !empty($runtime['running']) && empty($runtime['error'])
                        && ($runtime['revision'] ?? null) === $state['revision']
                        && $portApplied;
                    $protocolColumns[0][] = $this->i18n($ready ? 'on' : 'off') . ' ' . $label;
                    $protocolColumns[1][] = $this->i18n($portApplied ? 'on' : 'off') . ' ' . $state['settings']['port'];
                } catch (RuntimeException | InvalidArgumentException $e) {
                    $protocolColumns[0][] = $this->i18n('off') . ' ' . $label;
                    $protocolColumns[1][] = $this->t('— ошибка состояния', ': state error');
                }
                $managedProtocolButtons[] = ['text' => $label, 'callback_data' => "/!protocol $protocol"];
            }
            $main[] = implode("\n", array_map('rtrim', explode("\n", $this->alignColumns($protocolColumns))));
            $main[] = '';
            $main[] = $this->alignColumns([
                [
                    $this->i18n($backup ? 'on' : 'off') . ' autobackup',
                    $this->i18n(!empty($conf['autoupdate']) ? 'on' : 'off') . ' autoupdate',
                    $this->i18n(!empty($conf['autoscan']) ? 'on' : 'off') . ' autoscan',
                ],
                [
                    $this->i18n(!empty($conf['autodeny']) ? 'on' : 'off') . ' autoblock' . (!empty($conf['deny']) ? ': ' . count($conf['deny']) : ''),
                    $this->i18n(!empty($conf['reset_monthly']) ? 'on' : 'off') . ' autoreset',
                    $cron,
                ],
            ]);
            $main[] = '</code>';

        }
        $menu   = [
            'main' => [
                'text' => implode("\n", $main ?? []),
                'data' => array_merge(
                    [
                        [
                            [
                                'text'          => $this->i18n(!empty($this->getPacConf()['amnezia']) ? 'amnezia' : 'wg_title'),
                                'callback_data' => "/changeWG 0",
                            ],
                            [
                                'text'          => $this->i18n(!empty($this->getPacConf()['wg1_amnezia']) ? 'amnezia' : 'wg_title'),
                                'callback_data' => "/changeWG 1",
                            ],
                        ],
                        [
                            [
                                'text'          => $this->i18n('xray'),
                                'callback_data' => "/xray",
                            ],
                            [
                                'text'          => $this->i18n('naive'),
                                'callback_data' => "/menu naive",
                            ],
                        ],
                        [
                            [
                                'text'          => $this->i18n('ocserv'),
                                'callback_data' => "/menu oc",
                            ],
                            [
                                'text'          => $this->i18n('telemt'),
                                'callback_data' => "/telemt",
                            ],
                        ],
                        [
                            [
                                'text'          => $this->i18n('ad_title'),
                                'callback_data' => "/menu adguard",
                            ],
                            [
                                'text'          => $this->i18n('Hysteria'),
                                'callback_data' => "/menu hy",
                            ],
                        ],
                        [
                            [
                                'text'          => $this->i18n('sh_title'),
                                'callback_data' => "/menu ss",
                            ],
                            [
                                'text'          => $this->i18n('pac'),
                                'callback_data' => "/pacMenu 0",
                            ],
                        ],
                    ],
                    [
                        [
                            [
                                'text'          => $this->i18n('DNSTT'),
                                'callback_data' => "/dnstt",
                            ],
                            [
                                'text'          => $this->i18n('warp'),
                                'callback_data' => "/warp",
                            ],
                        ],
                    ],
                    array_chunk($managedProtocolButtons, 2),
                    [
                        [
                            [
                                'text'          => $this->i18n('OpenVPN'),
                                'callback_data' => "/menu ovpn",
                            ],
                            [
                                'text'          => 'L2TP/IPsec',
                                'callback_data' => "/menu l2tp",
                            ],
                        ],
                        [
                            [
                                'text'          => 'IKEv2',
                                'callback_data' => "/menu ikev2",
                            ],
                            [
                                'text'          => $this->i18n('TrustTunnel'),
                                'callback_data' => "/menu tt",
                            ],
                        ],
                        [[
                            'text' => $this->t('🖥 Ноды', '🖥 Nodes'),
                            'callback_data' => '/nodes',
                        ]],
                        [
                            [
                                'text'          => $this->i18n('config'),
                                'callback_data' => "/menu config",
                            ],
                            [
                                // Возраст кэша статусов: видно, насколько свежи
                                // on/off в тексте меню; нажатие — живые пробы.
                                'text'          => ($age = $this->menuStatusAge()) === null ? '🔄 status: …' : "🔄 status: {$age}s ago",
                                'callback_data' => '/refreshMain',
                            ],
                        ],
                    ],
                )
            ],
            'wg'           => $type == 'wg'      ? $this->statusWg($arg)                   : false,
            'client'       => $type == 'client'  ? $this->getClient(...explode('_', $arg)) : false,
            'addpeer'      => $type == 'addpeer' ? $this->addWg(...explode('_', $arg))     : false,
            'pac'          => $type == 'pac'     ? $this->pacMenu((int) $arg)              : false,
            'adguard'      => $type == 'adguard' ? $this->adguardMenu()                    : false,
            'config'       => $type == 'config'  ? $this->configMenu()                     : false,
            'ss'           => $type == 'ss'      ? $this->menuSS()                         : false,
            'lang'         => $type == 'lang'    ? $this->menuLang()                       : false,
            'oc'           => $type == 'oc'      ? $this->ocMenu()                         : false,
            'naive'        => $type == 'naive'   ? $this->naiveMenu()                      : false,
            'hy'           => $type == 'hy'      ? $this->hysteriaMenu()                   : false,
            'tt'           => $type == 'tt'      ? $this->ttMenu((int) $arg)               : false,
            'ovpn'         => $type == 'ovpn'    ? $this->ovpnMenu()                       : false,
            'l2tp'         => $type == 'l2tp'    ? $this->l2tpMenu()                       : false,
            'ikev2'        => $type == 'ikev2'   ? $this->ikev2Menu()                      : false,
            'mirror'       => $type == 'mirror'  ? $this->mirrorMenu()                     : false,
            'update'       => $type == 'update'  ? $this->updatebot()                      : false,
        ];

        $selected = $menu[$type ?: 'main'] ?? null;
        // Некоторые разделы (например PAC) уже отправили своё меню.
        if (!is_array($selected)) return;
        $text = $selected['text'];
        $data = $selected['data'];

        if (empty($type)) {
            $buttons = array_merge(...$this->filterProtocolButtons($data));
            $data = array_chunk($buttons, 2);
        }

        if (empty($type) && $update) {
            $b = exec('git -C / rev-parse --abbrev-ref HEAD');
            array_unshift($data, [
                [
                    'text'    => 'changelog',
                    'web_app' => ['url' => $this->changelogUrl()],
                ],
                [
                    'text'          => $this->i18n('update bot'),
                    'callback_data' => "/applyupdatebot",
                ],
            ]);
        }

        if ($return) {
            return [$text, $data];
        }

        if (!empty($this->input['callback_id']) || $this->replyMenuEdit) {
            $r = $this->update(
                $this->input['chat'],
                $this->input['message_id'],
                $text,
                $data ?: false,
            );
            // Ответ на промпт, который не изменил текст меню (переименование в
            // то же имя, повторный ввод того же DNS/MTU), Telegram отклоняет
            // «message is not modified» — и пользователь не видит НИЧЕГО: его
            // сообщение удалено, меню осталось прежним. До перехода на
            // редактирование здесь отправлялось новое сообщение, подтверждение
            // было всегда. Возвращаем подтверждение явным ответом.
            if ($this->replyMenuEdit && is_array($r) && empty($r['ok'])
                && stripos((string) ($r['description'] ?? ''), 'not modified') !== false) {
                $this->send($this->input['chat'], '✅ ' . $this->i18n('success'));
            }
            // Сообщение показывает wg-меню (или его подменю) — фиксируем его
            // инстанс в карте; любое другое меню — снимаем запись, чтобы
            // устаревшая привязка не влияла на кнопки нового содержимого.
            if (in_array($type, ['wg', 'client', 'addpeer'], true)) {
                $this->setWgMsg($this->wgNum());
            } else {
                $this->setWgMsg(null);
            }
        } else {
            // Команда меню всегда получает новое сообщение: после очистки истории
            // у пользователя правка прежнего меню успешна, но её никто не увидит,
            // а узнать об очистке бот не может. Прежнее меню удалит send().
            $command = $this->chatOwnsOutput($this->input['chat'])
                && in_array($this->input['message'] ?? '', ['/start', '/menu'], true);
            $r = $this->send(
                $this->input['chat'],
                $text,
                $command ? 0 : $this->input['message_id'],
                $data ?: false,
            );
            if (!empty($r['ok']) && $command) {
                $this->delete($this->input['chat'], $this->input['message_id']);
            }
        }
    }

    public function switchScanIp()
    {
        $this->pacConfUpdate(function (&$c) {
            $c['autoscan'] = $c['autoscan'] ? 0 : 1;
        });
        $this->ipMenu();
    }

    public function switchBanIp()
    {
        $this->pacConfUpdate(function (&$c) {
            $c['autodeny'] = $c['autodeny'] ? 0 : 1;
        });
        $this->ipMenu();
    }

    public function switchMonthlyStats()
    {
        $this->pacConfUpdate(function (&$c) {
            $c['reset_monthly'] = !empty($c['reset_monthly']) ? 0 : 1;
            // Отметку ставим сразу при включении: расписание считает «сброс уже
            // был в этом месяце», и первый же тик крона не стирает накопленное.
            // checkResetXrayStats() перестраховывается тем же условием.
            if ($c['reset_monthly'] && empty($c['last_reset_xray_time'])) {
                $c['last_reset_xray_time'] = time();
            }
        });
        $this->xray();
    }

    // uTLS-отпечатки, предлагаемые в меню. Список — PresetFingerprints из
    // Xray-core (transport/internet/tls/tls.go) МИНУС "unsafe".
    //
    // "unsafe" был скопирован из 3x-ui, но пользы от него нет ни в одном
    // сценарии:
    //   * Reality — infra/conf/transport_security.go отвергает конфиг целиком:
    //     `invalid "fingerprint": unsafe` (проверка идёт до GetFingerprint);
    //   * обычный TLS — GetFingerprint() возвращает nil, и все диалеры
    //     (tcp/websocket/grpc/splithttp) откатываются на tls.Client(), то есть
    //     на стандартный Go-ClientHello. Это ровно тот отпечаток, от которого
    //     uTLS и защищает: маскировка молча выключается.
    // Поэтому значение не предлагаем, а уже сохранённое подменяем в
    // fingerprint().
    //
    // "randomized" и "randomizednoalpn" убраны 2026-10-13: рукопожатие с ними
    // срывалось через раз даже с обычным TLS (nginx стенда: 2 из 3 и 1 из 3
    // попыток), а с REALITY — почти всегда. Случайный набор расширений
    // ClientHello не обязан быть приемлемым для сервера. Сохранённое прежде
    // значение читается как chrome (см. fingerprintChosen()).
    public function fingerprints()
    {
        return ['chrome', 'firefox', 'safari', 'ios', 'android', 'edge', '360', 'qq', 'random'];
    }

    // Отпечаток выбирает администратор при любом транспорте: бот не подменяет
    // выбор, а предупреждает (fingerprintWarnings()), если текущее ядро такого
    // клиента не примет. Так новые образцы uTLS с X25519MLKEM768 становятся
    // доступны без правки бота, а пометки в меню считаются по фактическому ядру.
    public function fingerprintsFor(?array $pac = null): array
    {
        return $this->fingerprints();
    }

    // Единая точка чтения отпечатка: пустое, неизвестное или снятое с
    // поддержки значение (например "unsafe" из старого pac.json) превращается
    // в chrome — так же, как это делает сам Xray для пустой строки.
    public function fingerprintChosen(): string
    {
        $fp = (string) ($this->getPacConf()['fingerprint'] ?? '');
        return in_array($fp, $this->fingerprints(), true) ? $fp : 'chrome';
    }

    // Отпечатки, которые несут X25519MLKEM768 и потому принимаются сервером
    // REALITY, требующим ML-KEM. Это знание для предупреждений, а не запрет:
    // набор стенда reality_fingerprints сверяет его с настоящими ядрами сборки и
    // сообщает, если другие образцы uTLS тоже начали проходить.
    //
    // С выпуска Xray 26.9.8 (библиотека REALITY от
    // 2026-09-08: «Reject outdated/strange Client Hello that doesn't have
    // X25519MLKEM768») сервер отвергает ClientHello без постквантовой доли
    // ключа и отдаёт такому клиенту настоящий сайт-маску. В uTLS её несут
    // только свежие образцы: chrome (Chrome 133), firefox (Firefox 148) и
    // safari (Safari 26.3). ios, edge и qq — снимки браузеров 2020–2022 годов
    // (iOS 14, Edge 106, QQ 11.1) без неё; android (OkHttp Android 11) и 360
    // не умеют TLS 1.3 и с REALITY не работали никогда; random при запуске
    // выбирает один из 11 образцов, из которых подходят 4.
    //
    // Перекрёстный замер (2026-10-16): сервер 26.10.10 принимает клиентов
    // Xray всех версий сборки (26.7.28 … форк 26.10.13) с chrome, firefox и
    // safari; Mihomo 1.19.32 — только с chrome (и support-x25519mlkem768);
    // sing-box 1.14.3 — ни с одним. Ядро 26.7.28 и форк без requireMlkem
    // принимают и ios, edge, qq. Решает сервер; выбор уходит в профили как
    // есть, а меню предупреждает (fingerprintWarnings()).
    public const REALITY_FINGERPRINTS = ['chrome', 'firefox', 'safari'];

    // Образцы без TLS 1.3: сервер REALITY их не принимает ни на каком ядре.
    public const REALITY_NO_TLS13 = ['android', '360'];

    // Образцы без h2 в ALPN: uTLS ставит свой список ALPN поверх профиля, и
    // nginx согласует http/1.1, а gRPC и XHTTP бота идут только по HTTP/2.
    // Замер на стенде (2026-10-19, профили бота): Xray и Mihomo с android и
    // 360 не подключаются, sing-box — с android (его образец 360 несёт h2).
    public const FINGERPRINTS_NO_H2 = ['android', '360'];

    // Не примет ли сервер REALITY текущего ядра клиента с этим отпечатком.
    // Требование ML-KEM определяет само ядро (realityRequiresMlkem()); старое
    // ядро и форк без requireMlkem принимают любой образец с TLS 1.3.
    public function fingerprintRejectedByReality(?string $fp = null, ?array $pac = null): bool
    {
        $pac = $pac ?? $this->getPacConf();
        $fp  = $fp ?? $this->fingerprintChosen();
        if (($pac['transport'] ?? '') !== 'Reality') {
            return false;
        }
        if (in_array($fp, self::REALITY_NO_TLS13, true)) {
            return true;
        }
        return !in_array($fp, self::REALITY_FINGERPRINTS, true) && $this->realityRequiresMlkem();
    }

    // Не подключится ли клиент с этим отпечатком при текущих транспорте и
    // ядре: REALITY (fingerprintRejectedByReality) либо gRPC/XHTTP без h2.
    public function fingerprintRejected(?string $fp = null, ?array $pac = null): bool
    {
        $pac = $pac ?? $this->getPacConf();
        $fp  = $fp ?? $this->fingerprintChosen();
        return $this->fingerprintRejectedByReality($fp, $pac)
            || (in_array($pac['transport'] ?? '', ['trojan-grpc', 'xhttp'], true)
                && ($this->fingerprintNoAlpn($fp) || in_array($fp, self::FINGERPRINTS_NO_H2, true)));
    }

    // Предупреждения к выбранному отпечатку при текущем транспорте и ядре:
    // строки для меню и всплывающего ответа. Пусто — клиенты подключатся.
    public function fingerprintWarnings(?string $fp = null, ?array $pac = null): array
    {
        $pac = $pac ?? $this->getPacConf();
        $fp  = $fp ?? $this->fingerprintChosen();
        $out = [];
        if (($pac['transport'] ?? '') === 'Reality') {
            if (in_array($fp, self::REALITY_NO_TLS13, true)) {
                $out[] = sprintf($this->i18n('fp reality no tls13'), $fp);
            } else {
                $mlkem = $this->realityRequiresMlkem();
                // random на ядре без ML-KEM стабилен (замер: 10 из 10 у всех
                // клиентов); с ML-KEM проходит, лишь когда выпал образец с ним.
                if ($mlkem && $fp === 'random') {
                    $out[] = $this->i18n('fp reality random');
                } elseif ($mlkem && !in_array($fp, self::REALITY_FINGERPRINTS, true)) {
                    $out[] = sprintf($this->i18n('fp reality mlkem'), $fp, implode(', ', self::REALITY_FINGERPRINTS));
                }
                if ($mlkem && $fp !== 'chrome') {
                    $out[] = $this->i18n('fp reality mihomo');
                }
            }
        }
        if ($this->fingerprintNoAlpn($fp) && in_array($pac['transport'] ?? '', ['trojan-grpc', 'xhttp'], true)) {
            $out[] = $this->i18n('fp noalpn warn');
        }
        if (in_array($fp, self::FINGERPRINTS_NO_H2, true) && in_array($pac['transport'] ?? '', ['trojan-grpc', 'xhttp'], true)) {
            $out[] = sprintf($this->i18n('fp no h2 warn'), $fp);
        }
        return $out;
    }

    // Отпечаток, который уходит в ссылки, подписки и профили. Это настройка
    // КЛИЕНТА: под какой браузер он маскирует своё TLS-приветствие. Сервер её
    // не хранит и не сверяет. Выбор администратора уходит как есть: если ядро
    // такого клиента не примет, меню предупреждает (fingerprintWarnings()).
    public function fingerprint()
    {
        return $this->fingerprintChosen();
    }

    // Ядра клиентов знают РАЗНЫЕ наборы имён, и ведут себя при незнакомом
    // значении по-разному:
    //   sing-box (common/tls/utls_client.go) — ошибка «unknown uTLS
    //     fingerprint», конфиг не запускается; знает всё, кроме
    //     randomizednoalpn;
    //   mihomo (component/tls/utls.go) — GetFingerprint() пишет warning и
    //     возвращает false, после чего uTLS ПРОСТО НЕ ПРИМЕНЯЕТСЯ и клиент
    //     уходит с Go-отпечатком. Его карта не содержит ни randomized, ни
    //     randomizednoalpn — то есть «рандомизированный» отпечаток там молча
    //     превращался в самый узнаваемый из возможных.
    // Поэтому для mihomo оба рандомных варианта отображаем в его собственный
    // `random` (выбирает chrome/safari/ios/firefox), а не в `randomized`.
    public function normalizeFingerprint($fp, $core)
    {
        if ($core === 'singbox') {
            return ['randomizednoalpn' => 'randomized'][$fp] ?? $fp;
        }
        if ($core === 'mihomo') {
            return ['randomized' => 'random', 'randomizednoalpn' => 'random'][$fp] ?? $fp;
        }
        return $fp;
    }

    // Отпечатки, которые НЕ отправляют ALPN-расширение. Для транспортов, где
    // h2 обязателен (gRPC) или желателен (XHTTP), это ломает согласование:
    // сервер без ALPN откатится на http/1.1, а grpc_pass в nginx требует h2.
    public function fingerprintNoAlpn($fp)
    {
        return $fp === 'randomizednoalpn';
    }

    public function changeFingerprint($fingerprint = false)
    {
        $entered = false;
        $result = $this->withLock('xray', function () use ($fingerprint, &$entered) {
            $entered = true;
            return $this->changeFingerprintLocked($fingerprint);
        });
        if (!$entered) throw new RuntimeException($this->t('Не удалось заблокировать Xray', 'Could not lock Xray'));
        return $result;
    }

    private function changeFingerprintLocked($fingerprint = false)
    {
        $allowed = $this->fingerprintsFor();
        $c       = $this->getPacConf();
        if ($fingerprint && in_array($fingerprint, $allowed, true)) {
            $c['fingerprint'] = $fingerprint;
        } else {
            // bare call (no/invalid arg): cycle to the next fingerprint in the list
            $current          = $this->fingerprint();
            $i                = array_search($current, $allowed, true);
            $c['fingerprint'] = $allowed[($i === false ? 0 : $i + 1) % count($allowed)];
        }
        $this->patchPacFields($c, ['fingerprint']);
        // Выбор сохранён; если клиенты с ним не подключатся — сказать сразу.
        // Окно answerCallbackQuery вмещает 200 символов: в нём главное
        // предупреждение, полный список — в меню ниже.
        $warnings = $this->fingerprintWarnings($c['fingerprint'], $c);
        if ($warnings && !empty($this->input['callback_id'])) {
            $alert = '⚠ ' . $warnings[0];
            if (mb_strlen($alert) > 200) {
                $alert = mb_substr($alert, 0, 199) . '…';
            }
            $this->answer($this->input['callback_id'], $alert, true);
        }
        $this->fingerprintMenu();
    }

    public function fingerprintMenu()
    {
        $pac     = $this->getPacConf();
        $current = $this->fingerprintChosen();
        $reality = ($pac['transport'] ?? '') === 'Reality';
        $text[]  = "Menu -> " . $this->i18n('xray') . ' -> ' . $this->i18n('fingerprint');
        $text[]  = $this->i18n('fingerprint') . ': <code>' . $current . '</code>';
        foreach ($this->fingerprintWarnings($current, $pac) as $warning) {
            $text[] = '⚠ ' . $warning;
        }
        if ($reality) {
            $text[] = $this->i18n($this->realityRequiresMlkem() ? 'fp reality core mlkem' : 'fp reality core any');
        }
        // Один и тот же выбор доезжает до трёх разных ядер под разными
        // именами — показываем, во что он превращается, иначе «почему в clash
        // другой отпечаток» выясняется только чтением исходников.
        $si = $this->normalizeFingerprint($current, 'singbox');
        $cl = $this->normalizeFingerprint($current, 'mihomo');
        if ($si !== $current || $cl !== $current) {
            $text[] = 'sing-box: <code>' . $si . '</code> · mihomo: <code>' . $cl . '</code>';
        }
        $text[] = '<i>' . $this->t('Отпечаток — настройка клиента. Какой отпечаток работает с каким ядром, транспортом и клиентом, в том числе с постквантовым шифрованием, — в справке.',
            'The fingerprint is a client setting. Which fingerprint works with which core, transport and client, including post-quantum encryption, is in the help.') . '</i>';

        $data = [];
        $row  = [];
        $effective = $this->fingerprint();
        foreach ($this->fingerprintsFor($pac) as $fp) {
            // ⚠ — при текущих транспорте и ядре клиент с этим отпечатком не подключится.
            $row[] = [
                'text'          => ucfirst($fp) . ' ' . ($effective === $fp ? $this->i18n('on') : $this->i18n('off'))
                    . ($this->fingerprintRejected($fp, $pac) ? ' ⚠' : ''),
                'callback_data' => "/changeFingerprint $fp",
            ];
            if (count($row) === 2) {
                $data[] = $row;
                $row    = [];
            }
        }
        if ($row) {
            $data[] = $row;
        }
        $data[] = $this->menuHelpButton('fingerprint');
        $data[] = [[
            'text'          => $this->i18n('back'),
            'callback_data' => '/xray',
        ]];

        $this->update(
            $this->input['chat'],
            $this->input['message_id'],
            implode("\n", $text),
            $data,
        );
    }

    // ---- DPI masking submenu (items 1/2/4/5). Everything defaults OFF; each row
    // is an independent toggle/value so a technique can be disabled or retuned if
    // it trips DPI or breaks clients, without code changes. ----
    public function dpiMenu()
    {
        $p  = $this->getPacConf();
        $f  = $p['dpi']['fragment'] ?? [];
        $n  = $p['dpi']['noise'] ?? [];
        $r  = $p['reality'] ?? [];
        $x  = $this->getXray();
        $s  = $this->sniffingSettings($p, $x['inbounds'][0]['sniffing'] ?? null);
        $tr = $p['transport'] ?? '';
        $on = fn($v) => $this->i18n(!empty($v) ? 'on' : 'off');
        $spiderX = $this->normalizeSpiderXValue((string) ($r['spiderX'] ?? ''));
        $mldsaReady = $this->mldsaReady($p);

        $text[] = "Menu -> " . $this->i18n('xray') . ' -> ' . $this->i18n('dpi masking');

        $data = [];
        $data[] = [['text' => $this->i18n('fragment') . ': ' . $on($f['enabled'] ?? 0), 'callback_data' => '/dpiToggle fragment']];
        if (!empty($f['enabled'])) {
            $data[] = [
                ['text' => 'packets: ' . (($f['packets'] ?? '') ?: '1-3'),    'callback_data' => '/dpiSet fragment_packets'],
                ['text' => 'length: ' . (($f['length'] ?? '') ?: '100-200'),  'callback_data' => '/dpiSet fragment_length'],
                ['text' => 'interval: ' . (($f['interval'] ?? '') ?: '10-20'), 'callback_data' => '/dpiSet fragment_interval'],
            ];
            // maxSplit — потолок числа фрагментов; пусто = без лимита (дефолт
            // xray), поэтому показываем «—», а не число.
            $data[] = [
                ['text' => 'maxSplit: ' . (($f['maxSplit'] ?? '') ?: '—'), 'callback_data' => '/dpiSet fragment_maxSplit'],
            ];
            // Готовые наборы спрятаны в отдельное подменю (/dpiFragPresets),
            // чтобы не загромождать основное DPI-меню семью кнопками.
            $data[] = [['text' => '📋 ' . $this->i18n('presets'), 'callback_data' => '/dpiFragPresets']];
        }
        $data[] = [['text' => $this->i18n('noise') . ': ' . $on($n['enabled'] ?? 0), 'callback_data' => '/dpiToggle noise']];
        if (!empty($n['enabled'])) {
            // noises в xray-freedom применяется ТОЛЬКО к UDP-соединениям; все
            // транспорты Vless тут (Reality/Websocket/xhttp/trojan-grpc) — TCP,
            // поэтому по туннелю шум не отправляется и DPI не маскирует. Явно
            // предупреждаем, чтобы не собрать бесполезную комбинацию (noise ON,
            // fragment OFF). $tr пуст только до выбора транспорта.
            if ($tr !== '') {
                $text[] = str_replace('%s', htmlspecialchars($tr, ENT_QUOTES), $this->i18n('noise tcp warn'));
            }
            // noises — массив: несколько пакетов с разными типами/задержками
            // эффективнее против анализа трафика, чем один фиксированный.
            $noises = $this->dpiNoiseList($p);
            foreach ($noises as $i => $ne) {
                $data[] = [
                    ['text' => 'type: ' . (($ne['type'] ?? '') ?: 'rand'),      'callback_data' => "/dpiSet noise{$i}_type"],
                    ['text' => 'packet: ' . (($ne['packet'] ?? '') ?: '10-20'), 'callback_data' => "/dpiSet noise{$i}_packet"],
                    ['text' => 'delay: ' . (($ne['delay'] ?? '') ?: '10-16'),   'callback_data' => "/dpiSet noise{$i}_delay"],
                    ['text' => '🗑',                                            'callback_data' => "/dpiNoiseDel {$i}"],
                ];
            }
            $data[] = [
                ['text' => '➕ noise packet',                        'callback_data' => '/dpiNoiseAdd'],
                ['text' => '📋 ' . $this->i18n('presets'),           'callback_data' => '/dpiNoisePresets'],
            ];
        }
        if (!empty($f['enabled']) || !empty($n['enabled'])) {
            $finalmask = ($p['dpi']['format'] ?? '') === 'finalmask';
            $text[] = $this->i18n($finalmask ? 'dpi format finalmask hint' : 'dpi format freedom hint');
            if ($finalmask) {
                // Что на деле получат клиенты: applyDpiFragment() откатывается на
                // freedom, если finalmask этих значений не примет.
                $probe = ['outbounds' => [['tag' => 'proxy', 'streamSettings' => []]]];
                $this->applyDpiFragment($probe, 0, $p);
                if (!isset($probe['outbounds'][0]['streamSettings']['finalmask'])) {
                    $text[] = '⚠️ ' . $this->i18n('dpi format fallback');
                } elseif (!empty($n['enabled']) && in_array('exp', array_column($this->dpiNoiseList($p), 'type'), true)) {
                    $text[] = '⚠️ ' . $this->i18n('dpi format exp');
                }
            }
            $data[] = [['text' => $this->i18n('dpi format') . ': ' . ($finalmask ? 'finalmask (Xray 26.3.27+)' : 'freedom'),
                'callback_data' => '/dpiToggle format']];
        }
        $text[] = "\n" . $this->i18n('sniffing');
        $data[] = [['text' => $this->i18n('sniffing') . ': ' . $on($s['enabled'] ?? 0), 'callback_data' => '/dpiToggle sniffing']];
        if (!empty($s['enabled'])) {
            $data[] = [[
                'text' => 'destOverride: ' . $this->shortListLabel($s['destOverride'] ?? []),
                'callback_data' => '/dpiSet sniffing_destOverride',
            ]];
            $data[] = [
                ['text' => 'metadataOnly: ' . $on($s['metadataOnly'] ?? 0), 'callback_data' => '/dpiToggle sniffingMetadataOnly'],
                ['text' => 'routeOnly: ' . $on($s['routeOnly'] ?? 0),       'callback_data' => '/dpiToggle sniffingRouteOnly'],
            ];
            $data[] = [
                ['text' => 'ipsExcluded: ' . $this->shortListLabel($s['ipsExcluded'] ?? []),         'callback_data' => '/dpiSet sniffing_ipsExcluded'],
                ['text' => 'domainsExcluded: ' . $this->shortListLabel($s['domainsExcluded'] ?? []), 'callback_data' => '/dpiSet sniffing_domainsExcluded'],
            ];
        }
        if ($tr === 'Reality') {
            $data[] = [
                ['text' => $this->i18n('mldsa') . ': ' . $on($mldsaReady), 'callback_data' => '/dpiToggle mldsa'],
                ['text' => '🎲 ' . $this->i18n('autogen'),                 'callback_data' => '/dpiGenMldsa'],
                ['text' => $this->i18n('clear'),                           'callback_data' => '/dpiDefault r_mldsa65'],
            ];
            $text[] = 'mldsa65 Seed: ' . $this->shortSecretLabel($r['mldsa65Seed'] ?? '');
            $text[] = 'mldsa65 Verify: ' . $this->shortSecretLabel($r['mldsa65Verify'] ?? '');
            $text[] = 'spiderX: <code>' . htmlspecialchars($spiderX ?: '/', ENT_QUOTES) . '</code>';
            // Полные значения не влезают в текст меню (Verify ~2.6k символов) —
            // отдаём отдельным сообщением в <code>, чтобы копировались тапом.
            $data[] = [['text' => '📋 mldsa65 Seed/Verify', 'callback_data' => '/dpiShowMldsa']];
            $data[] = [
                ['text' => 'maxTimeDiff: ' . (int) ($r['maxTimeDiff'] ?? 0), 'callback_data' => '/dpiSet r_maxTimeDiff'],
                ['text' => 'xver: ' . (int) ($r['xver'] ?? 0),               'callback_data' => '/dpiSet r_xver'],
            ];
            $data[] = [
                ['text' => 'minClientVer: ' . (($r['minClientVer'] ?? '') ?: '—'), 'callback_data' => '/dpiSet r_minClientVer'],
                ['text' => 'maxClientVer: ' . (($r['maxClientVer'] ?? '') ?: '—'), 'callback_data' => '/dpiSet r_maxClientVer'],
            ];
            if ($this->xrayCore($p) === 'fork') {
                $text[] = $this->i18n('reality require mlkem hint');
                $data[] = [['text' => $this->i18n('reality require mlkem') . ': ' . $on($r['requireMlkem'] ?? 0),
                    'callback_data' => '/dpiToggle requireMlkem']];
            } else {
                $text[] = $this->i18n('reality mlkem origin always');
            }
            $data[] = [
                ['text' => 'spiderX: ' . ($spiderX ?: '—'),              'callback_data' => '/dpiSet r_spiderX'],
                ['text' => '🎲 ' . $this->i18n('autogen'),               'callback_data' => '/dpiGenSpiderX'],
                ['text' => $this->i18n('default'),                       'callback_data' => '/dpiDefault r_spiderX'],
            ];
        }
        $fm = $this->finalmaskSettings($p);
        $data[] = [['text' => 'finalmask (server): ' . $on($fm['enabled']), 'callback_data' => '/finalmaskMenu']];
        $data[] = $this->menuHelpButton('dpi');
        $data[] = [['text' => $this->i18n('back'), 'callback_data' => '/xray']];

        $this->update($this->input['chat'], $this->input['message_id'], implode("\n", $text), $data);
    }

