        $p = $this->getPorts();
        $t = str_replace([
            '~ip~',
            '~ss~',
            '~wg1~',
            '~wg2~',
        ], [
            getenv('IP'),
            $p['ss']['port'],
            $p['wg']['port'],
            $p['wg1']['port'],
