    // Версия ocserv в контейнере oc. `ocserv --version` печатает
    // «OpenConnect VPN Server 1.5.0», затем «Compiled with: …» и «GnuTLS
    // version: …». Берём и версию сервера, и GnuTLS: именно она определяет
    // доступный набор TLS-шифров, а меняется независимо от пина —
    // её тянет базовый образ, а не OCSERV_VERSION.
    //
    // Фолбэк — build-пин OCSERV_VERSION из .env (контейнер не отвечает);
    // он может расходиться с образом, пока тот не пересобран, поэтому
    // расхождение помечаем в меню — так же, как у caddy (naiveVersion()).
    public function ocservVersion(): array
    {
        $out = (string) $this->ssh('ocserv --version 2>&1', 'oc');
        return [
            'running' => preg_match('~OpenConnect VPN Server\s+(v?\d+(?:\.\d+)+[0-9A-Za-z.\-]*)~i', $out, $m) ? $m[1] : '',
            'pinned'  => trim((string) getenv('OCSERV_VERSION')),
            'gnutls'  => preg_match('~GnuTLS version:\s*(\S+)~i', $out, $m) ? $m[1] : '',
        ];
    }

    public function ocMenu()
    {
        $ocserv = file_get_contents('/config/ocserv.conf');
        $cs     = $this->ocCamouflageSecretForConf($ocserv);
        preg_match('~^dns = ([^\n]+)~sm', $ocserv, $m);
        $dns = $m[1] ?? '';
        preg_match('~^expose-iroutes = (true)~sm', $ocserv, $m);
        $expose = !empty($m[1]);
        $url    = htmlspecialchars($this->ocConnectionUrl($cs), ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
        $clients = $this->getClientsOc();
        $this->syncOcUsers($clients);
        $online = $this->getOcOnlineUsers($clients);
        $text[] = "Menu -> OpenConnect";
        $ver    = $this->ocservVersion();
        if ($ver['running'] !== '' || $ver['pinned'] !== '') {
            $esc  = fn($v) => htmlspecialchars((string) $v, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
            $line = 'ocserv: <code>' . $esc($ver['running'] ?: '—') . '</code>';
            // Три разных состояния, и путать их нельзя: пустой running — это
            // «контейнер не ответил», а не «пин разошёлся с образом».
            // Сравниваем без ведущей «v»: в .env пин записан как «1.5.0».
            if ($ver['pinned'] !== '' && $ver['running'] === '') {
                $line .= $this->t(' (пин: <code>', ' (pin: <code>') . $esc($ver['pinned']) . $this->t('</code>, контейнер не отвечает)', '</code>, the container does not respond)');
            } elseif ($ver['pinned'] !== '' && ltrim($ver['pinned'], 'vV') !== ltrim($ver['running'], 'vV')) {
                $line .= $this->t(' (пин: <code>', ' (pin: <code>') . $esc($ver['pinned']) . $this->t('</code>, нужна пересборка)', '</code>, rebuild needed)');
            }
            if ($ver['gnutls'] !== '') {
                $line .= '  GnuTLS: <code>' . $esc($ver['gnutls']) . '</code>';
            }
            $text[] = $line;
        }
        $text[] = $this->i18n('camouflage') . ': ' . $this->i18n($cs === '' ? 'off' : 'on');
        $text[] = $this->i18n('server') . ": <code>$url</code>";
        $data[] = [
            [
                'text'          => $this->i18n('change subdomain'),
                'callback_data' => "/changeOcDomain",
            ],
        ];
        $row = [
            [
                'text'          => $this->i18n('change secret'),
                'callback_data' => "/changeCamouflage",
            ],
        ];
        if ($cs !== '') {
            $row[] = [
                'text'          => $this->i18n('disable secret'),
                'callback_data' => "/disableOcCamouflage",
            ];
        }
        $data[] = $row;
        $data[] = [
            [
                'text'          => $this->i18n('dns') . ": $dns",
                'callback_data' => "/changeOcDns",
            ],
        ];
        $data[] = [
            [
                'text'          =>  $this->i18n('listSubnet'),
                'callback_data' => "/subnet 0_0_1",
            ],
        ];
        $data[] = [
            [
                'text'          => $this->i18n('expose-iroutes') . ' ' . $this->i18n($expose ? 'on' : 'off'),
                'callback_data' => "/changeOcExpose",
            ],
        ];
        $data[] = [
            [
                'text'          => $this->i18n('add peer'),
                'callback_data' => "/addOcUser",
            ],
        ];
        foreach ($clients as $k => $v) {
            $data[] = [
                [
                    'text'          => (!empty($online[$v]) ? '🟢 ' : '🔴 ') . $v,
                    'callback_data' => "/ocUser $k",
                ],
            ];
        }
        $data[] = $this->menuHelpButton('oc');
        $data[] = [
            [
                'text'          => $this->i18n('back'),
                'callback_data' => "/menu",
            ],
        ];
        return [
            'text' => implode("\n", $text),
            'data' => $data,
        ];
    }

    public function ocUser($i)
    {
        $clients = $this->getClientsOc();
        if (!isset($clients[$i])) {
            $this->menu('oc');
            return;
        }

        $users  = $this->syncOcUsers($clients);
        $ocserv = file_get_contents('/config/ocserv.conf');
        $cs     = $this->ocCamouflageSecretForConf($ocserv);
        $url    = htmlspecialchars($this->ocConnectionUrl($cs), ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
        $user   = htmlspecialchars($clients[$i], ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
        $pass   = htmlspecialchars($users[$clients[$i]] ?? '', ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
        $online = !empty($this->getOcOnlineUsers([$clients[$i]])[$clients[$i]]);

        $text[] = "Menu -> OpenConnect -> $user";
        $text[] = $this->i18n('server') . ": <code>$url</code>";
        $text[] = $this->i18n('username') . ": <code>$user</code>";
        $text[] = $this->i18n('password') . ": <span class='tg-spoiler'>$pass</span>";
        $text[] = $this->i18n('status') . ': ' . ($online ? '🟢 ' . $this->i18n('online') : '🔴 ' . $this->i18n('offline'));
        $text[] = $this->i18n('camouflage') . ': ' . $this->i18n($cs === '' ? 'off' : 'on');

        $data[] = [
            [
                'text'          => $this->i18n('change password'),
                'callback_data' => "/changeOcPass $i",
            ],
            [
                'text'          => $this->i18n('generate password'),
                'callback_data' => "/genOcPass $i",
            ],
        ];
        $data[] = [
            [
                'text'          => $this->i18n('delete'),
                'callback_data' => "/deloc {$i}_" . $this->ocClientToken($clients[$i]),
            ],
        ];
        $data[] = [
            [
                'text'          => $this->i18n('back'),
                'callback_data' => "/menu oc",
            ],
        ];

        $this->update(
            $this->input['chat'],
            $this->input['message_id'],
            implode("\n", $text),
            $data,
        );
    }

    public function changeOcExpose()
    {
        $c = file_get_contents('/config/ocserv.conf');
        preg_match('~^expose-iroutes = ([^\n]+)~sm', $c, $m);
        $t = preg_replace('~^expose-iroutes[^\n]+~sm', "expose-iroutes = " . ($m[1] == 'true' ? 'false' : 'true'), $c);
        $this->restartOcserv($t);
        $this->menu('oc');
    }

    public function ocClientToken(string $name): string
    {
        return substr(hash('sha256', 'oc-user|' . $name), 0, 8);
    }

    public function deloc($i, ?string $token = null)
    {
        $clients = $this->getClientsOc();
        foreach ($clients as $k => $v) {
            if ($i == $k) {
                // Кнопка из устаревшего меню: под этим номером теперь другой пользователь.
                if ($token !== null && !hash_equals($this->ocClientToken((string) $v), $token)) {
                    if (!empty($this->input['callback_id'])) $this->answer($this->input['callback_id'], $this->i18n('confirm stale'), true);
                    break;
                }
                if (!$this->saveOcPassword($v, null)) {
                    $this->send($this->input['chat'], $this->t('OpenConnect: не удалось удалить пользователя', 'OpenConnect: could not delete the user'));
                    break;
                }
                // Пароль уже удалён, но живая сессия держится до отключения.
                $this->ssh('occtl disconnect user ' . escapeshellarg($v), 'oc');
                if ($this->sshFailed || !empty($this->getOcOnlineUsers([$v])[$v])) {
                    $this->send($this->input['chat'], $this->t("OpenConnect: пользователь $v удалён, но его активная сессия не завершена — повторите удаление сессии перезапуском службы",
                        "OpenConnect: user $v is deleted but the active session was not closed — restart the service to end it"));
                }
                break;
            }
        }
        $this->menu('oc');
    }

    public function delxr($i, $menu = true, ?string $expectedSource = null)
    {
        $ok = $this->withLock('xray', fn() => $this->withXrayApplyLock(function () use ($i, $expectedSource) {
            if (!$this->xrayClientMatches((int) $i)) return false;
            $r = $this->getXray();
            $client = $r['inbounds'][0]['settings']['clients'][$i] ?? null;
            if ($client === null || ($expectedSource !== null && !hash_equals($expectedSource, ManagedProtocol::xraySource($client)))) return false;
            $this->captureAccessGroupUsage();
            $beforeClients = $r['inbounds'][0]['settings']['clients'];
            try { $before = $this->getXrayStats(); }
            catch (XrayStatsUnavailable $error) { $before = null; }
            $st = $before ?? [];
            unset($r['inbounds'][0]['settings']['clients'][$i], $st['users'][$i], $st['group_epochs'][ManagedProtocol::xraySource($client)]);
            // restartXray переиндексирует клиентов и сворачивает session в
            // global. Счётчики должны иметь тот же порядок до его вызова.
            $rows = $st['users'] ?? []; $st['users'] = [];
            foreach (array_keys($r['inbounds'][0]['settings']['clients']) as $newIndex => $oldIndex) {
                // A reset user may have no row. Its position still belongs to
                // that user; array_values(rows) would charge its neighbour.
                if (isset($rows[$oldIndex])) $st['users'][$newIndex] = $rows[$oldIndex];
            }
            $applied = false;
            try {
                if ($before !== null && $this->setXrayStats($st) === false) return false;
                if ($this->restartXray($r) === false) return false;
                $applied = true;
            } finally {
                if (!$applied && $before !== null && !$this->rollbackXrayStats($before, $beforeClients)) {
                    throw new RuntimeException($this->t('Не удалось вернуть статистику Xray', 'Could not restore Xray statistics'), self::BACKUP_PARTIAL);
                }
            }
            $this->deleteHwidUser($client['id']);
            // Персональный WARP-профиль удаляем только после принятия конфига.
            $this->deleteWarpClient($client['email'] ?? '');
            $this->adguardXrayClients();
            return true;
        }));
        if ($menu) {
            if (!$ok) $this->send($this->input['chat'], $this->t('Удаление пользователя Xray не подтверждено. Проверьте состояние пользователя.', 'Xray user deletion is unconfirmed. Check the user state.'));
            $this->xray();
        }
        return $ok;
    }

    public function getClientsOc()
    {
        $users = array_filter(explode("\n", file_get_contents('/config/ocserv.passwd')), fn ($e) => !empty($e));
        return array_map(fn($e) => explode(':', $e)[0], $users);
    }

    public function addocus($user)
    {
        $user = $this->normalizeOcUsername($user);
        if ($user === false) {
            $this->send($this->input['chat'], 'OpenConnect username: use 1-64 chars: A-Z a-z 0-9 . _ -');
            $this->menu('oc');
            return;
        }

        $clients = $this->getClientsOc();
        if (in_array($user, $clients, true)) {
            $this->ocUser(array_search($user, $clients, true));
            return;
        }

        $this->setOcUserPassword($user, $this->genOcPassword());
        $clients = $this->getClientsOc();
        $i = array_search($user, $clients, true);
        if ($i === false) {
            $this->menu('oc');
            return;
        }

        $this->ocUser($i);
    }

    public function addxrus($users)
    {
        $entered = false;
        $result = $this->withLock('xray', function () use ($users, &$entered) {
            $entered = true;
            return $this->addxrusLocked($users);
        });
        if (!$entered) throw new RuntimeException($this->t('Не удалось заблокировать Xray', 'Could not lock Xray'));
        return $result;
    }

    private function addxrusLocked($users)
    {
        $c     = $this->getXray();
        $p     = $this->getPacConf();
        $users = array_map(fn ($e) => trim($e), explode(',', $users));
        $users = array_map(fn ($e) => explode(':', $e), $users);
        // Инициализация: без клиентов в конфиге (свежая установка) цикл ниже не
        // выполнялся ни разу, и обе переменные оставались необъявленными.
        $uuids  = [];
        $emails = [];
        foreach ($c['inbounds'][0]['settings']['clients'] as $k => $v) {
            $uuids[]  = $v['id'];
            // Xray compares emails case-insensitively ("User Alice already exists").
            $emails[] = mb_strtolower((string) ($v['email'] ?? ''));
        }
        foreach ($users as $user) {
            // Формат ввода — «email» или «email:uuid»: без второй части ключа
            // $user[1] попросту нет, и на каждом обычном добавлении шло
            // «Undefined array key 1».
            $uuid = ($user[1] ?? '') ?: self::xrayUuid();
            if (in_array($uuid, $uuids) || in_array(mb_strtolower($user[0]), $emails, true)) {
                $this->send($this->input['chat'], 'user ' . self::esc($user[0]) . ' already exists');
                return $this->xray();
            }
            // Also a name repeated within this input.
            $uuids[] = $uuid;
            $emails[] = mb_strtolower($user[0]);
            // subtoken addresses the subscription independently of the id (which
            // is the VLESS credential), so a leaked/shared sub URL never exposes
            // the credential and can be rotated without regenerating the id.
            $stok = bin2hex(random_bytes(16));
            $c['inbounds'][0]['settings']['clients'][] = match($p['transport']) {
                'Reality'     => ['id' => $uuid, 'flow' => 'xtls-rprx-vision', 'email' => $user[0], 'subtoken' => $stok],
                'trojan-grpc' => ['id' => $uuid, 'password' => bin2hex(random_bytes(16)), 'email' => $user[0], 'subtoken' => $stok],
                default       => ['id' => $uuid, 'email' => $user[0], 'subtoken' => $stok],
            } + (($auto = $this->exitAutoNodes($p)) ? ['exit' => $auto] : []);
            // Пополняем списки в цикле: иначе дубликаты ВНУТРИ одной пачки
            // («a@x,a@x») проходили проверку и заводили двух клиентов с одним
            // email — статистика xray считается как раз по email.
            $uuids[]  = $uuid;
            $emails[] = $user[0];
        }
        if ($this->restartXray($c) === false) throw new RuntimeException($this->t('Не удалось применить настройки Xray', 'Could not apply Xray settings'));
        $this->adguardXrayClients();
        // Новый пользователь включён: если список был переключён на выключенных
        // (общий для всех админов xtlslist), его не было бы видно в меню.
        if (!empty($p['xtlslist'])) $this->pacConfUpdate(static function (&$conf) { $conf['xtlslist'] = 0; });
        if (count($users) == 1) {
            $this->userXrLocked(count($c['inbounds'][0]['settings']['clients']) - 1);
        } else {
            $this->xray();
        }
    }

    public function setTimerXr($time, $i)
    {
        $entered = false;
        $result = $this->withLock('xray', function () use ($time, $i, &$entered) {
            $entered = true;
            return $this->setTimerXrLocked($time, $i);
        });
        if (!$entered) throw new RuntimeException($this->t('Не удалось заблокировать Xray', 'Could not lock Xray'));
        return $result;
    }

    private function setTimerXrLocked($time, $i)
    {
        if (!$this->xrayClientMatches((int) $i)) return $this->staleXrayAction();
        $c = $this->getXray();
        if (empty($time)) {
            unset($c['inbounds'][0]['settings']['clients'][$i]['time']);
        } else {
            $time = strtotime($time);
            if ($time === false) {
                $this->send($this->input['chat'], 'wrong format');
                return;
            }
            $c['inbounds'][0]['settings']['clients'][$i]['time'] = $time;
        }
        if ($this->restartXray($c, 1) === false) throw new RuntimeException($this->t('Не удалось применить настройки Xray', 'Could not apply Xray settings'));
        if (!empty($c['inbounds'][0]['settings']['clients'][$i]['off'])) {
            $this->switchXrLocked($i, 0, 1);
        } else {
            $this->userXrLocked($i);
        }
    }

    public function switchXr($i, $nm = 0, $time = false)
    {
        $entered = false;
        $result = $this->withLock('xray', function () use ($i, $nm, $time, &$entered) {
            $entered = true;
            return $this->switchXrLocked($i, $nm, $time);
        });
        if (!$entered) throw new RuntimeException($this->t('Не удалось заблокировать Xray', 'Could not lock Xray'));
        return $result;
    }

    protected function switchXrLocked($i, $nm = 0, $time = false)
    {
        if (!$this->xrayClientMatches((int) $i)) return $this->staleXrayAction();
        $c = $this->getXray();
        if (empty($time)) {
            unset($c['inbounds'][0]['settings']['clients'][$i]['time']);
        }
        if (empty($c['inbounds'][0]['settings']['clients'][$i]['off'])) {
            $c['inbounds'][0]['settings']['clients'][$i]['off'] = $c['inbounds'][0]['settings']['clients'][$i]['id'];
            $c['inbounds'][0]['settings']['clients'][$i]['id']  = self::xrayUuid();
            if (isset($c['inbounds'][0]['settings']['clients'][$i]['password'])) {
                $c['inbounds'][0]['settings']['clients'][$i]['off_pwd']  = $c['inbounds'][0]['settings']['clients'][$i]['password'];
                $c['inbounds'][0]['settings']['clients'][$i]['password'] = self::xrayUuid();
            }
        } else {
            $c['inbounds'][0]['settings']['clients'][$i]['id'] = $c['inbounds'][0]['settings']['clients'][$i]['off'];
            if (isset($c['inbounds'][0]['settings']['clients'][$i]['password'])) {
                $c['inbounds'][0]['settings']['clients'][$i]['password'] = $c['inbounds'][0]['settings']['clients'][$i]['off_pwd']
                    ?: $c['inbounds'][0]['settings']['clients'][$i]['off'];
                unset($c['inbounds'][0]['settings']['clients'][$i]['off_pwd']);
            }
            unset($c['inbounds'][0]['settings']['clients'][$i]['off']);
        }
        // A manual enable/disable overrides any traffic-quota ban: drop the marker
        // so a later stats reset (reenableTrafficClients) can't silently flip this
        // client back, and userXr doesn't show a stale ⛔ on an enabled client.
        unset($c['inbounds'][0]['settings']['clients'][$i]['traffic_off'], $c['inbounds'][0]['settings']['clients'][$i]['traffic_usage_unavailable']);
        if ($this->restartXray($c) === false) throw new RuntimeException($this->t('Не удалось применить настройки Xray', 'Could not apply Xray settings'));
        if (empty($nm)) {
            $this->userXrLocked($i);
        }
    }

    public function changeXrPwd($i)
    {
        $r = $this->send(
            $this->input['chat'],
            $this->t("@{$this->input['username']} введите пароль (или оставьте пустым для автоматического)", "@{$this->input['username']} enter password (or leave empty to auto-generate)"),
            $this->input['message_id'],
            reply: $this->t('введите пароль xr', 'enter xr password'),
        );
        $this->stashReply($r, [
            'start_message'  => $this->input['message_id'],
            'start_callback' => $this->input['callback_id'],
            'callback'       => 'setXrPwd',
            'args'           => [$i],
        ]);
    }

    public function setXrPwd($pwd, $i)
    {
        $entered = false;
        $result = $this->withLock('xray', function () use ($pwd, $i, &$entered) {
            $entered = true;
            return $this->setXrPwdLocked($pwd, $i);
        });
        if (!$entered) throw new RuntimeException($this->t('Не удалось заблокировать Xray', 'Could not lock Xray'));
        return $result;
    }

    private function setXrPwdLocked($pwd, $i)
    {
        if (!$this->xrayClientMatches((int) $i)) return $this->staleXrayAction();
        $c        = $this->getXray();
        if (!isset($c['inbounds'][0]['settings']['clients'][$i])) {
            $this->xray();
            return;
        }
        $password = trim($pwd) ?: bin2hex(random_bytes(16));
        $field = empty($c['inbounds'][0]['settings']['clients'][$i]['off']) ? 'password' : 'off_pwd';
        $c['inbounds'][0]['settings']['clients'][$i][$field] = $password;
        if ($this->restartXray($c) === false) throw new RuntimeException($this->t('Не удалось применить настройки Xray', 'Could not apply Xray settings'));
        $this->userXrLocked($i);
    }

    // Generate a fresh Reality keypair (matched private/public) + shortId.
    // Same commands/parsing as the initial setup in changeTransport(); the pair
    // comes from a single `xray x25519` call so private and public always match.
    // Дефолтные fake-домены Reality. Захардкоженный 'yandex.ru' означал, что у
    // КАЖДОЙ установки vpnbot до первого «change fake domain» стоит
    // serverNames=["yandex.ru"] и dest=yandex.ru:443 — «TLS-сессия с
    // SNI=yandex.ru к хосту, который не Yandex» это дешёвый фильтр и для DPI, и
    // для сканера. Выбираем случайный из списка крупных сайтов с настоящим
    // TLS 1.3 и HTTP/2; админ по-прежнему может задать свой.
    public const REALITY_FAKE_DOMAINS = [
        'www.microsoft.com',
        'www.samsung.com',
        'www.lovelive-anime.jp',
        'www.tesla.com',
        'www.icloud.com',
        'yandex.ru',
    ];

    public function defaultFakeDomain(): string
    {
        $list = self::REALITY_FAKE_DOMAINS;

        return $list[random_int(0, count($list) - 1)];
    }

    // Набор shortId для инбаунда: основной плюс несколько «шумовых» разной
    // длины. Xray принимает клиента с ЛЮБЫМ из перечисленных, а клиентам мы
    // раздаём разные (см. clientShortId), поэтому подписи клиентов одной
    // установки перестают совпадать и коррелировать их становится сложнее.
    // Раньше значение было ровно одно на всю установку.
    public function realityShortIds(string $primary): array
    {
        $ids = [$primary];
        foreach ([4, 6, 8] as $len) {
            $ids[] = bin2hex(random_bytes($len));
        }

        return array_values(array_unique(array_filter($ids)));
    }

    // Какой из shortId отдать конкретному клиенту. Детерминированно и без
    // привязки к индексу: индексы съезжают при удалении соседа, а uuid нет.
    public function clientShortId(array $xr, string $uid): string
    {
        $ids = $xr['inbounds'][0]['streamSettings']['realitySettings']['shortIds'] ?? [];
        $ids = array_values(array_filter((array) $ids, 'strlen'));
        if (empty($ids)) {
            return '';
        }

        return $ids[hexdec(substr(md5($uid), 0, 4)) % count($ids)];
    }

    public function genRealityKeys(): array
    {
        $shortId = trim($this->ssh('openssl rand -hex 8', 'xr'));
        $keys    = $this->ssh('xray x25519', 'xr');
        preg_match('~^PrivateKey:\s([^\s]+)~m', $keys, $m);
        $private = trim($m[1] ?? '');
        preg_match('~^Password(?:\s*\(PublicKey\))?:\s([^\s]+)~m', $keys, $m);
        $public  = trim($m[1] ?? '');
        return ['private' => $private, 'public' => $public, 'shortId' => $shortId];
    }

    // Generate a post-quantum ML-DSA-65 keypair for Reality (item 2). `xray
    // mldsa65` prints two lines: `Seed: ...` (server, realitySettings.mldsa65Seed)
    // and `Verify: ...` (client link param `pqv` / config mldsa65Verify).
    public function genMldsaKeys(): array
    {
        $keys = $this->ssh('xray mldsa65', 'xr');
        preg_match('~^Seed:\s*([^\s]+)~mi', $keys, $m);
        $seed = trim($m[1] ?? '');
        preg_match('~^Verify:\s*([^\s]+)~mi', $keys, $m);
        $verify = trim($m[1] ?? '');
        if (!$this->isRawUrlBase64DecodedLength($seed, 32) || !$this->isRawUrlBase64DecodedLength($verify, 1952)) {
            return ['seed' => '', 'verify' => ''];
        }
        return ['seed' => $seed, 'verify' => $verify];
    }

    // Apply the configurable Reality server-side extras to a realitySettings block:
    // item 4 hardening params (maxTimeDiff/minClientVer/maxClientVer/xver, default
    // to current values so nothing changes until tuned) and item 2 mldsa65Seed
    // (added only when mldsa is enabled and a seed exists, unset otherwise).
    // Centralized so changeTransport()/regenRealityXr()/regenAllXr() stay in sync.
    public function applyRealityServerExtras(array &$rs, array $p): void
    {
        $rs['maxTimeDiff']  = max(0, (int) ($p['reality']['maxTimeDiff'] ?? 0));
        // Since Xray-core v26.7.11 (PR #6181) an empty "minClientVer" no longer means
        // "no restriction": the server defaulted it to 26.3.27, which rejects the
        // many clients built on older cores. Emit "0.0.0" when the user set nothing so
        // the pre-v26.7.11 "accept any client" behaviour is preserved; a real value
        // typed via the hardening menu is still honoured verbatim.
        // Upstream v26.9.8 commented that default out again (and the fork never had
        // it), so on the current pins "0.0.0" and an empty value mean the same thing —
        // we keep emitting it: the image on a given server may still carry a core from
        // the v26.7.11..v26.9.5 window, where dropping it would lock those clients out.
        $rs['minClientVer'] = ((string) ($p['reality']['minClientVer'] ?? '')) ?: '0.0.0';
        $rs['maxClientVer'] = (string) ($p['reality']['maxClientVer'] ?? '');
        $rs['xver']         = max(0, (int) ($p['reality']['xver'] ?? 0));
        if (in_array($rs['dest'] ?? '', ['10.10.1.2:443', '10.10.0.2:443'], true)) {
            // Оба адреса — один штатный сайт: первый без PROXY, второй с ним.
            $rs['dest'] = $rs['xver'] ? '10.10.0.2:443' : '10.10.1.2:443';
        }
        if ($this->mldsaReady($p)) {
            $rs['mldsa65Seed'] = $p['reality']['mldsa65Seed'];
        } else {
            unset($rs['mldsa65Seed']);
        }
        $this->ensureRealityRequireMlkem($rs, $p);
    }

    // Только для форка: апстрим требует гибридную группу всегда. Зовётся и при
    // каждом restartXray(): смена ядра обязана снять или вернуть флаг, не трогая
    // остальные параметры REALITY, которые админ мог поправить вручную.
    public function ensureRealityRequireMlkem(array &$rs, array $p): void
    {
        if ($this->realityRequireMlkemActive($p)) {
            $rs['requireMlkem'] = true;
        } else {
            unset($rs['requireMlkem']);
        }
    }

    // Rotate the shared Reality parameters: pbk (keypair) + sid (shortId).
    // Updates pac.json (pbk/privateKey/shortId) and xray.json in lock-step so the
    // server private key matches the public key embedded in every client link.
    // Invalidates all existing links — every client must re-import.
    // Ротация серверных Reality-ключей: x25519, набор shortId, ML-DSA и
    // spiderX. Одна копия на regenRealityXr() (только Reality) и regenAllXr()
    // (полная ротация): 22 строки жили в двух местах один в один, и любое новое
    // поле Reality пришлось бы добавлять в обе, а расхождение проявилось бы как
    // «полная ротация выдала не то, что ротация только Reality».
    // Возвращает false, если генератор ключей не отработал.
    public function rotateRealityKeys(array &$p, array &$x): bool
    {
        $k = $this->genRealityKeys();
        if (empty($k['private']) || empty($k['public']) || empty($k['shortId'])) {
            return false;
        }
        $p['xray']                  = $k['public'];
        $p['reality']['privateKey'] = $k['private'];
        $p['reality']['shortId']    = $k['shortId'];
        $x['inbounds'][0]['streamSettings']['realitySettings']['privateKey'] = $k['private'];
        $x['inbounds'][0]['streamSettings']['realitySettings']['shortIds']   = $this->realityShortIds($k['shortId']);
        if (!empty($p['reality']['mldsa'])) {
            $mk = $this->genMldsaKeys();
            if (!empty($mk['seed']) && !empty($mk['verify'])) {
                $p['reality']['mldsa65Seed']   = $mk['seed'];
                $p['reality']['mldsa65Verify'] = $mk['verify'];
            }
        }
        // spiderX обновляем вместе с ключами и только если он уже в ходу: у
        // ротации должен быть свежий crawl-путь. На клиенте это ни на что не
        // влияет.
        if (!empty($p['reality']['spiderX'])) {
            $p['reality']['spiderX'] = $this->genSpiderX();
        }
        $this->applyRealityServerExtras($x['inbounds'][0]['streamSettings']['realitySettings'], $p);

        return true;
    }

    public function regenRealityXr()
    {
        $entered = false;
        $result = $this->withLock('xray', function () use (&$entered) {
            $entered = true;
            return $this->regenRealityXrLocked();
        });
        if (!$entered) throw new RuntimeException($this->t('Не удалось заблокировать Xray', 'Could not lock Xray'));
        return $result;
    }

    private function regenRealityXrLocked()
    {
        $x = $this->getXray();
        $p = $this->getPacConf();
        if (empty($x['inbounds'][0]['streamSettings']['realitySettings'])) {
            return $this->answer($this->input['callback_id'], 'reality only', true);
        }
        if (!$this->rotateRealityKeys($p, $x)) {
            return $this->answer($this->input['callback_id'], 'keygen failed', true);
        }
        $this->patchPacFields($p, ['reality', 'xray']);
        if ($this->restartXray($x) === false) throw new RuntimeException($this->t('Не удалось применить настройки Xray', 'Could not apply Xray settings'));
        $this->xray();
    }

    // Rotate a single client's UUID (clientID). For an enabled client this is the
    // live credential; for a disabled one the real id lives in 'off' (the active
    // 'id' is a throwaway), so rotate 'off' too. Invalidates only this client.
    public function regenIdXr($i)
    {
        $entered = false;
        $result = $this->withLock('xray', function () use ($i, &$entered) {
            $entered = true;
            return $this->regenIdXrLocked($i);
        });
        if (!$entered) throw new RuntimeException($this->t('Не удалось заблокировать Xray', 'Could not lock Xray'));
        return $result;
    }

    protected function regenIdXrLocked($i)
    {
        if (!$this->xrayClientMatches((int) $i)) return $this->staleXrayAction();
        $x = $this->getXray();
        if (!isset($x['inbounds'][0]['settings']['clients'][$i])) {
            return $this->xray();
        }
        $x['inbounds'][0]['settings']['clients'][$i]['protocol_source'] = ManagedProtocol::xraySource($x['inbounds'][0]['settings']['clients'][$i]);
        if (!empty($x['inbounds'][0]['settings']['clients'][$i]['off'])) {
            $x['inbounds'][0]['settings']['clients'][$i]['off'] = $this->guidv4();
        }
        $x['inbounds'][0]['settings']['clients'][$i]['id'] = $this->guidv4();
        if ($this->restartXray($x) === false) throw new RuntimeException($this->t('Не удалось применить настройки Xray', 'Could not apply Xray settings'));
        $this->userXrLocked($i);
    }

    // Full rotation: shared Reality pbk+sid (if Reality) AND every client's UUID.
    // One restart, all configs written consistently. Invalidates every link.
    public function regenAllXr()
    {
        $entered = false;
        $result = $this->withLock('xray', function () use (&$entered) {
            $entered = true;
            return $this->regenAllXrLocked();
        });
        if (!$entered) throw new RuntimeException($this->t('Не удалось заблокировать Xray', 'Could not lock Xray'));
        return $result;
    }

    private function regenAllXrLocked()
    {
        $x = $this->getXray();
        $p = $this->getPacConf();
        if (!empty($x['inbounds'][0]['streamSettings']['realitySettings'])) {
            if (!$this->rotateRealityKeys($p, $x)) {
                return $this->answer($this->input['callback_id'], 'keygen failed', true);
            }
        }
        // ?? [] — как в соседнем regenIdXr(): на инбаунде без клиентов (или на
        // конфиге, где ключ потерялся) это был Undefined array key плюс
        // «foreach() argument must be of type array», а кнопка при этом
        // выглядела сработавшей.
        foreach ($x['inbounds'][0]['settings']['clients'] ?? [] as $key => $v) {
            $x['inbounds'][0]['settings']['clients'][$key]['protocol_source'] = ManagedProtocol::xraySource($v);
            if (!empty($v['off'])) {
                $x['inbounds'][0]['settings']['clients'][$key]['off'] = $this->guidv4();
            }
            $x['inbounds'][0]['settings']['clients'][$key]['id'] = $this->guidv4();
        }
        $this->patchPacFields($p, ['reality', 'xray']);
        if ($this->restartXray($x) === false) throw new RuntimeException($this->t('Не удалось применить настройки Xray', 'Could not apply Xray settings'));
        $this->xray();
    }

    public function renXrUs($name, $i)
    {
        $entered = false;
        $result = $this->withLock('xray', function () use ($name, $i, &$entered) {
            $entered = true;
            return $this->renXrUsLocked($name, $i);
        });
        if (!$entered) throw new RuntimeException($this->t('Не удалось заблокировать Xray', 'Could not lock Xray'));
        return $result;
    }

    private function renXrUsLocked($name, $i)
    {
        if (!$this->xrayClientMatches((int) $i)) return $this->staleXrayAction();
        $c = $this->getXray();
        foreach ($c['inbounds'][0]['settings']['clients'] as $k => $other) {
            // Xray refuses a second client with the same email, case-insensitively.
            if ($k !== (int) $i && mb_strtolower((string) ($other['email'] ?? '')) === mb_strtolower((string) $name)) {
                $this->send($this->input['chat'], 'user ' . self::esc((string) $name) . ' already exists');
                return $this->userXrLocked($i);
            }
        }
        $client = &$c['inbounds'][0]['settings']['clients'][$i];
        $client['email'] = $name;
        unset($client);
        if ($this->restartXray($c) === false) throw new RuntimeException($this->t('Не удалось применить настройки Xray', 'Could not apply Xray settings'));
        $this->adguardXrayClients();
        $this->userXrLocked($i);
    }

    public function resetXrUser($i)
    {
        $entered = false;
        $result = $this->withLock('xray', function () use ($i, &$entered) {
            $entered = true;
            return $this->resetXrUserLocked($i);
        });
        if (!$entered) throw new RuntimeException($this->t('Не удалось заблокировать Xray', 'Could not lock Xray'));
        return $result;
    }

    private function resetXrUserLocked($i)
    {
        if (!$this->xrayClientMatches((int) $i)) return $this->staleXrayAction();
        $this->resetXrayStatsAndClients($i);
        $this->userXrLocked($i);
    }

    public function resetXrStats($nomenu = false)
    {
        $entered = false;
        $result = $this->withLock('xray', function () use ($nomenu, &$entered) {
            $entered = true;
            return $this->resetXrStatsLocked($nomenu);
        });
        if (!$entered) throw new RuntimeException($this->t('Не удалось заблокировать Xray', 'Could not lock Xray'));
        return $result;
    }

    protected function resetXrStatsLocked($nomenu = false)
    {
        $this->resetXrayStatsAndClients();
        if (empty($nomenu)) $this->xray();
    }

    private function resetXrayStatsAndClients($only = null): void
    {
        $ok = $this->withXrayApplyLock(function () use ($only) {
            $x = $this->getXray();
            $client = $only === null ? null : ($x['inbounds'][0]['settings']['clients'][$only] ?? null);
            if ($only !== null && $client === null) return false;
            $this->captureAccessGroupUsage();
            // A user reset cannot replace an unknown shared ledger with zero.
            $this->withXrayStatsLock(function () use ($only, $client) {
                $stats = $only === null ? [] : $this->getXrayStats();
                $stats['group_epochs'][$client === null ? 'all' : ManagedProtocol::xraySource($client)] = bin2hex(random_bytes(8));
                if ($only !== null) unset($stats['users'][$only]);
                if ($this->setXrayStats($stats) === false) throw new RuntimeException('Could not reset Xray statistics');
            });
            $this->resetXrayProtocolUsage($client);
            $this->xrayStatsResetting = true;
            try { return $this->restartXray($this->reenableTrafficClients($x, $only)); }
            finally { $this->xrayStatsResetting = false; }
        });
        if ($ok === false) throw new RuntimeException($this->t('Не удалось применить настройки Xray', 'Could not apply Xray settings'));
        $this->syncXrayProtocolUsers();
    }

    public function listXr($i)
    {
        $this->pacConfUpdate(function (&$c) use ($i) {
            $c['xtlslist'] = $i;
        });
        $this->xray();
    }

