        ]);
    }

    public function addTemplate($n, $type)
    {
        if (empty($this->input['caption'])) {
            $this->send($this->input['chat'], 'empty name');
            return;
        }
        $r    = $this->request('getFile', ['file_id' => $this->input['file_id']]);
        $json = json_decode((string) file_get_contents($this->file . $r['result']['file_path']), true);
        // json_decode возвращает null (не false) на битом JSON.
        if (!is_array($json)) {
            $this->send($this->input['chat'], 'wrong format');
            return;
        }
        $v = $this->validateTemplate($type, $json);
        if (!$v['ok']) {
            $this->send($this->input['chat'], "template rejected:\n" . implode("\n", array_slice($v['errors'], 0, 10)));
            return;
        }
        if ($v['warnings']) {
            $this->send($this->input['chat'], "⚠ template warnings:\n" . implode("\n", array_slice($v['warnings'], 0, 10)));
        }
        $this->pacConfUpdate(function (&$pac) use ($type, $json) {
            $pac["{$type}templates"][$this->input['caption']] = $json;
        });
        $this->templates($type);
    }

    // Валидация шаблона перед сохранением: для clash — структура + плейсхолдеры,
    // для sing/v2ray — только опечатки в ~плейсхолдерах~. errors блокируют
    // сохранение, warnings — нет (текст возвращается вызывающему коду).
    public function validateTemplate($type, array $template)
    {
        return $type === 'clash'
            ? ClashTemplateValidator::validate($template)
            : ClashTemplateValidator::validatePlaceholders($template);
    }

    public function saveTemplate($name, $type, $json)
    {
        // $type подставляется в путь "/config/$type.json" (ветка 'origin') и в
        // ключ pac.json. Приходит он из POST — и в /webapp$hash/save, и в
        // панельном /tsave, — а проверялся только на входе load'а: type вида
        // "../app/x" писал бы json мимо /config. Ограничиваем словом, как это
        // уже сделано для ?ty= в index.php.
        if (!is_string($type) || !preg_match('~^\w+$~', $type)) {
            return [
                'status'  => false,
                'message' => 'wrong type',
            ];
        }
        // $name и $json приходят из POST как есть. Массив («name[]=x», «json[]=x»)
        // проходил empty()/preg_match и падал уже внутри: json_decode(array) —
        // TypeError, $pac[...][$name] с массивом-ключом — «illegal offset type».
        // То есть 500 вместо ответа, а в редакторе — немой «error».
        if (!is_string($name) || '' === $name || !is_string($json)) {
            return [
                'status'  => false,
                'message' => 'wrong format',
            ];
        }
        $decoded = json_decode($json, true);
        // json_decode возвращает null (не false) на битом JSON; шаблон обязан
        // быть объектом — скаляр/строка тоже «wrong format».
        if (!is_array($decoded)) {
            return [
                'status'  => false,
                'message' => 'wrong format',
            ];
        }
        $v = $this->validateTemplate($type, $decoded);
        if (!$v['ok']) {
            return [
                'status'  => false,
                'message' => implode('; ', array_slice($v['errors'], 0, 5)),
            ];
        }
        try {
            if ($name === 'origin') {
                if (!is_array($this->getPacConf())) throw new RuntimeException('pac.json unavailable');
                $encoded = json_encode($decoded, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
                if ($encoded === false || file_put_contents("/config/$type.json", $encoded) !== strlen($encoded)) {
                    throw new RuntimeException('template write failed');
                }
            } else {
                $this->pacConfUpdate(function (&$pac) use ($type, $name, $decoded) { $pac["{$type}templates"][$name] = $decoded; });
            }
        } catch (RuntimeException $e) {
            return ['status' => false, 'message' => 'template not saved'];
        }
        return [
            'status'  => true,
            'message' => $v['warnings'] ? '⚠ ' . implode('; ', array_slice($v['warnings'], 0, 5)) : '',
        ];
    }

    public function delTemplate($type, $name)
    {
        if (is_array($this->getPacConf())) {
            $this->pacConfUpdate(function (&$pac) use ($type, $name) { unset($pac["{$type}templates"][base64_decode($name)]); });
        }
        $this->templates($type);
    }

    public function copyTemplate($name, $type)
    {
        if (is_array($this->getPacConf())) {
            $template = json_decode(file_get_contents("/config/$type.json"), true);
            $this->pacConfUpdate(function (&$pac) use ($name, $type, $template) { $pac["{$type}templates"][$name] = $template; });
        }
        $this->templates($type);
    }

    public function downloadOrigin($type)
    {
        $f = new \CURLFile("/config/$type.json", 'application/json', 'origin.json');
        $this->sendFile($this->input['chat'], $f);
    }

    public function downloadTemplate($type, $name)
    {
        $pac = $this->getPacConf();
        $f = new \CURLStringFile(json_encode($pac["{$type}templates"][base64_decode($name)], JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES), base64_decode($name) . '.json', 'application/json');
        $this->sendFile($this->input['chat'], $f);
    }

    public function defaultTemplate($type, $name)
    {
        $this->pacConfUpdate(function (&$pac) use ($type, $name) {
            if (!empty($name)) {
                $pac["default{$type}template"] = $name;
            } else {
                unset($pac["default{$type}template"]);
            }
        });
        $this->templates($type);
    }

    // Штатный шаблон из config/templates/<тип>/<имя>.json: ensureDefaultTemplates()
    // добавляет его один раз, дальше в pac.json живёт копия администратора.
    public static function bundledTemplate(string $type, string $name): ?array
    {
        if (!in_array($type, ['sing', 'clash'], true) || !preg_match('~^[A-Za-z0-9_.-]{1,64}$~D', $name)) return null;
        $file = dirname(__DIR__) . "/config/templates/$type/$name.json";
        if (!is_file($file)) return null;
        $template = json_decode((string) file_get_contents($file), true);
        return is_array($template) ? $template : null;
    }

    // Заменить сохранённую копию штатного шаблона версией из комплекта — так
    // старая копия получает новые плейсхолдеры (например, ~relay_hosts~ вместо
    // вписанных вручную адресов relay). Правки администратора теряются, поэтому
    // сначала подтверждение.
    public function resetTemplate(string $type, string $name64, bool $confirm = false)
    {
        $name = (string) base64_decode($name64, true);
        $bundled = self::bundledTemplate($type, $name);
        if ($bundled === null) return $this->templates($type);
        if (!$confirm) {
            return $this->update($this->input['chat'], $this->input['message_id'],
                "Menu -> " . $this->i18n('xray') . " -> " . $this->i18n($type) . " templates -> " . self::esc($name) . "\n\n⚠ "
                . $this->t('Сохранённый шаблон будет заменён штатным из текущей версии бота. Ваши правки в нём пропадут; адреса relay штатный шаблон берёт из раздела Relay (~relay_hosts~, ~relay_ips~, ~relay_domains~). Скачайте шаблон перед заменой, если правки нужны.',
                    'The saved template will be replaced with the bundled one from the current bot version. Your edits in it will be lost; the bundled template takes relay addresses from the Relay section (~relay_hosts~, ~relay_ips~, ~relay_domains~). Download the template first if you need the edits.'),
                [
                    [['text' => '♻️ ' . $this->t('заменить штатным', 'replace with bundled'), 'callback_data' => "/resetTemplate $type $name64 yes"]],
                    [['text' => $this->i18n('download'), 'callback_data' => "/downloadTemplate $type $name64"]],
                    [['text' => $this->i18n('cancel'), 'callback_data' => "/templates $type"]],
                ]);
        }
        $v = $this->validateTemplate($type, $bundled);
        if (!$v['ok']) return $this->templates($type);
        $this->pacConfUpdate(function (&$pac) use ($type, $name, $bundled) {
            $pac["{$type}templates"][$name] = $bundled;
            $pac['installed_templates'][$type][$name] = true;
        });
        return $this->templates($type);
    }

    public function templates($type)
    {
        $this->ensureDefaultTemplates();
        $pac    = $this->getPacConf();
        $domain = $this->getDomain();
        $hash   = $this->getHashBot();
        $text[] = "Menu -> " . $this->i18n('xray') . " -> " . $this->i18n($type) . " templates";
        $text[] = <<<TEXT
            <code>~outbound~</code>
            <code>~pac~</code>
            <code>~package~</code>
            <code>~process~</code>
            <code>~subnet~</code>
            <code>~block~</code>
            <code>~warp~</code>
            <code>~dns~</code>
            <code>~dnspath~</code>
            <code>~uid~</code>
            <code>~domain~</code>
            <code>~directdomain~</code>
            <code>~cdndomain~</code>
            <code>~short_id~</code>
            <code>~email~</code>
            <code>~public_key~</code>
            <code>~relay_hosts~</code>
            <code>~relay_ips~</code>
            <code>~relay_domains~</code>
            <code>~server_name~</code>
            <code>~fingerprint~</code>
            <code>~ip~</code>
            <code>~smux~</code>
            <code>~smux:h2mux~</code>
            TEXT;
        // Ключ мультиплекса в каждом диалекте свой (см. smuxBlock()): sing-box
        // ждёт multiplex, xray-форк и mihomo — smux. Печатаем имя ТОГО формата,
        // чьё меню открыто, иначе подсказка отправляет класть плейсхолдер под
        // ключ, который клиент этого формата просто проигнорирует.
        $text[] = str_replace('%s', $type === 'sing' ? 'multiplex' : 'smux', $this->i18n('smux tpl hint'));
        $text[] = $this->t(
            'Готовые шаблоны добавляются один раз; ваши правки и удаление сохраняются. Relay: ~relay_hosts~ — ключ словаря hosts/predefined; ~relay_ips~ — элемент списка CIDR; ~relay_domains~ — элемент списка доменов. Адреса берутся из всех каналов меню Relay. DNS обновляется в фоне раз в 10 минут; при сбое сохраняется последний ответ. Пустое правило Relay удаляется.',
            'Bundled templates are added once; your edits and deletions are preserved. Relay: ~relay_hosts~ is a hosts/predefined map key; ~relay_ips~ is a CIDR list item; ~relay_domains~ is a domain list item. All channels in the Relay menu supply addresses. DNS refreshes in the background every 10 minutes; a failure retains the last answer. Empty Relay rules are removed.'
        );
        // ?? [] — до первого сохранённого шаблона ключа нет; ниже по нему идёт
        // foreach.
        $templates = $pac["{$type}templates"] ?? [];

        $data[] = [
            [
                'text'          => $this->i18n('add'),
                'callback_data' => "/templateAdd $type",
            ],
        ];
        $data[] = [
            [
                'text'          => "origin",
                'web_app' => ['url' => "https://$domain/pac$hash?t=te&ty=$type"],
            ],
            [
                'text'          => $this->i18n('download'),
                'callback_data' => "/downloadOrigin $type",
            ],
            [
                'text'          => $this->i18n('copy'),
                'callback_data' => "/templateCopy $type",
            ],
            [
                'text'          => $this->i18n(!empty($pac["default{$type}template"]) && !empty($pac["{$type}templates"][base64_decode($pac["default{$type}template"])]) ? 'off' : 'on'),
                'callback_data' => "/defaultTemplate $type",
            ],
        ];
        foreach ($templates as $k => $v) {
            $data[] = [
                [
                    'text'          => $k,
                    'web_app' => ['url' => "https://$domain/pac$hash?t=te&ty=$type&te=" . urlencode($k)],
                ],
                [
                    'text'          => $this->i18n('download'),
                    'callback_data' => "/downloadTemplate $type " . base64_encode($k),
                ],
                [
                    'text'          => $this->i18n('delete'),
                    'callback_data' => "/delTemplate $type " . base64_encode($k),
                ],
                [
                    'text'          => $this->i18n(($pac["default{$type}template"] ?? '') == base64_encode($k) ? 'on' : 'off'),
                    'callback_data' => "/defaultTemplate $type " . base64_encode($k),
                ],
            ];
            // Копия штатного шаблона отличается от комплекта — можно вернуть штатный.
            $bundled = self::bundledTemplate($type, (string) $k);
            if ($bundled !== null && $bundled !== $v) {
                $data[array_key_last($data)][] = ['text' => '♻️', 'callback_data' => "/resetTemplate $type " . base64_encode($k)];
            }
        }

        $data[] = [
            [
                'text'          => $this->i18n('back'),
                'callback_data' => "/xray",
            ],
        ];
        $this->update(
            $this->input['chat'],
            $this->input['message_id'],
            implode("\n", $text ?: ['...']),
            $data ?: false,
        );
    }

    public function mainOutbound()
    {
        $r = $this->send(
            $this->input['chat'],
            $this->t("@{$this->input['username']} отправьте имя", "@{$this->input['username']} send name"),
            $this->input['message_id'],
            reply: $this->t('отправьте имя', 'send name'),
        );
        $this->stashReply($r, [
            'start_message'  => $this->input['message_id'],
            'start_callback' => $this->input['callback_id'],
            'callback'       => 'setMainOutbound',
            'args'           => [],
        ]);
    }

    public function setMainOutbound($text)
    {
        $this->pacConfUpdate(function (&$pac) use ($text) {
            if (!empty($text)) {
                $pac['outbound'] = $text;
            } else {
                unset($pac['outbound']);
            }
        });
        $this->xray();
    }

    public function getBytes($bytes)
    {
        $t = [
            'B',
            'KB',
            'MB',
            'GB',
            'TB',
        ];
        foreach ($t as $k => $v) {
            if ($k == 0) {
                continue;
            }
            if ($bytes / (1024 ** $k) < 1) {
                return round($bytes / (1024 ** ($k - 1)), 2) . " {$t[$k - 1]}";
            }
        }
        return round($bytes / (1024 ** 4), 2) . ' TB';
    }

    // Новый REALITY требует гибридный key_share. Неизвестная версия/сбой SSH
    // не означают несовместимость и не должны отключать существующие подписки.
    public function realityRequiresMlkem(): bool
    {
        $probe = $this->xrayCoreProbe();
        if (!$probe['ok'] || ($probe['running'] !== '' && $probe['running'] !== $probe['active'])) {
            return false;
        }
        // REALITY из дерева форка принимает ClientHello без гибридной группы
        // через обычный X25519, поэтому sing-box с ним совместим — пока админ
        // не включил requireMlkem (форк 26.10.13+).
        if (!empty($probe['reality_local'])) {
            return $probe['active'] === 'fork' && $this->realityRequireMlkemActive();
        }
        // Форк может выпускаться с новой датой, сохраняя прежний REALITY.
        // Проверяем версию зависимости из Go build info самого бинаря.
        if (preg_match('~^v0\.0\.0-(\d{14})-[0-9a-f]+$~D', $probe['reality'] ?? '', $build)) {
            return strcmp($build[1], '20260908062103') >= 0;
        }
        // Без build info календарная версия неизвестного форка недостаточна.
        return $probe['active'] === 'origin'
            && preg_match('~Xray\s+v?(\d+\.\d+\.\d+)~i', $probe['version'], $match)
            && version_compare($match[1], '26.9.8', '>=');
    }

    // Сайт-маска REALITY. Библиотека REALITY с 3c98159 (Xray 26.10.17)
    // подтверждает SNI в EncryptedExtensions и дополняет свою запись до длины
    // записи маски: её запись — 10 байт сообщения, тип и 16 байт AEAD, то есть
    // 27 байт после заголовка. Маска без ALPN и без подтверждения SNI
    // присылает 23, сервер пишет «padding: -4» и отвергает всех клиентов.
    // Склеенная запись маски (весь ответ одной записью) длиннее заведомо.
    public const REALITY_MASK_MIN_RECORD = 27;
    // Результат проверки: устойчивый держим 6 часов, сбой связи — 10 минут.
    public const REALITY_MASK_TTL   = 21600;
    public const REALITY_MASK_RETRY = 600;
    protected const REALITY_MASK_FILE = '/logs/reality_mask.json';

    // Требует ли ядро от маски непустого EncryptedExtensions. Правило по дате
    // библиотеки REALITY в бинаре, как в realityRequiresMlkem(); у форка со
    // своей копией REALITY дата — от исходной версии (26.10.13: 8cdf7bf).
    public function realityAcksServerName(): bool
    {
        $probe = $this->xrayCoreProbe();
        if (!$probe['ok'] || ($probe['running'] !== '' && $probe['running'] !== $probe['active'])) {
            return false;
        }
        return self::realityBuildAcksServerName((string) ($probe['reality'] ?? ''), (string) $probe['version'], $probe['active'] === 'origin');
    }

    public static function realityBuildAcksServerName(string $reality, string $version, bool $origin): bool
    {
        if (preg_match('~^v0\.0\.0-(\d{14})-[0-9a-f]+$~D', $reality, $build)) {
            return strcmp($build[1], '20260921001439') >= 0;
        }
        return $origin && preg_match('~Xray\s+v?(\d+\.\d+\.\d+)~i', $version, $match)
            && version_compare($match[1], '26.10.17', '>=');
    }

    // То же правило для ядра, на которое переключаются (не для работающего):
    // слоты держат разные версии. null — контейнер xr не ответил.
    public function xrayCoreAcksServerName(string $core): ?bool
    {
        $bin = self::XRAY_BINARIES[$core] ?? null;
        if ($bin === null) return null;
        $out = (string) $this->ssh($bin . ' version 2>&1 | head -n1; printf "\nREALITY_BUILD="; '
            . 'LC_ALL=C grep -a -m 1 -oE \'github\\.com/xtls/reality[[:space:]]+v[0-9A-Za-z.+_-]+\' ' . $bin . ' 2>/dev/null '
            . '| head -n1 | awk \'{printf "%s", $2}\'', 'xr');
        if ($this->sshFailed || !preg_match('~^(.*)\nREALITY_BUILD=(\S*)$~sD', rtrim($out), $m)) return null;
        return self::realityBuildAcksServerName($m[2], $m[1], $core !== 'fork');
    }

    // Защита REALITY: маску без TLS 1.3 не принимает ни одно ядро, маску без
    // ALPN — ядро, подтверждающее SNI ($acks). Ключ i18n отказа или ''.
    // Недоступная маска (fail/error) не повод отказывать: сбой может быть разовым.
    public static function realityMaskRefusal(array $probe, bool $acks): string
    {
        return match ($probe['status'] ?? '') {
            'tls12' => 'reality mask tls12',
            'short' => $acks ? 'reality mask short now' : '',
            default => '',
        };
    }

    // Адрес и SNI маски из рабочего конфига; ['', ''] — проверять нечего.
    public function realityMaskTarget(?array $x = null): array
    {
        $x  = $x ?? $this->getXray();
        $rs = $x['inbounds'][0]['streamSettings']['realitySettings'] ?? [];
        $target = (string) ($rs['target'] ?? $rs['dest'] ?? '');
        $sni    = (string) ($rs['serverNames'][0] ?? '');
        if (!preg_match('~^[A-Za-z0-9.-]+:\d{1,5}$~D', $target) || !$this->isHostname($sni)) {
            return ['', ''];
        }
        return [$target, $sni];
    }

    // Команда пробы: обычное приветствие с ALPN, как у браузерных отпечатков.
    // -msg печатает заголовки записей; длина первой зашифрованной записи и
    // есть то, что сервер REALITY повторяет. grep оставляет нужные строки.
    public static function realityMaskCommand(string $target, string $sni): string
    {
        return 'timeout 10 openssl s_client -connect ' . escapeshellarg($target)
            . ' -servername ' . escapeshellarg($sni) . ' -alpn h2,http/1.1 -msg </dev/null 2>&1'
            . " | grep -E -A1 '^<<< .*RecordHeader|^New, |^ALPN protocol|^No ALPN|errno=|:error:' | head -n 80";
    }

    // Разбор вывода пробы: ok, short (ядро 26.10.17+ маску отвергнет), tls12
    // (REALITY с маской без TLS 1.3 не работает ни на каком ядре), fail.
    public static function realityMaskVerdict(string $out): array
    {
        $alpn = preg_match('~^ALPN protocol: (\S+)~m', $out, $m) ? $m[1] : '';
        if (!preg_match('~^New, (TLSv1\.[0-3]),~m', $out, $m)) {
            $reason = match (true) {
                trim($out) === ''                    => 'timeout',
                str_contains($out, 'BIO_lookup')     => 'DNS',
                str_contains($out, 'errno=111')      => 'connection refused',
                default                              => 'TLS handshake',
            };
            return ['status' => 'fail', 'reason' => $reason, 'alpn' => '', 'record' => 0];
        }
        if ($m[1] !== 'TLSv1.3') {
            return ['status' => 'tls12', 'reason' => $m[1], 'alpn' => $alpn, 'record' => 0];
        }
        if (!preg_match('~^<<< [^\n]*RecordHeader[^\n]*\n\s*17 03 03 ([0-9a-f]{2}) ([0-9a-f]{2})~mi', $out, $r)) {
            return ['status' => 'fail', 'reason' => 'TLS handshake', 'alpn' => $alpn, 'record' => 0];
        }
        $record = (int) hexdec($r[1] . $r[2]);
        return [
            'status' => $record >= self::REALITY_MASK_MIN_RECORD ? 'ok' : 'short',
            'reason' => '',
            'alpn'   => $alpn,
            'record' => $record,
        ];
    }

    // Проба из контейнера xr — тем же путём, которым к маске ходит REALITY.
    public function realityMaskProbe(string $target, string $sni): array
    {
        // openssl не добавляет PROXY-заголовок. Оба штатных входа ведут
        // в тот же TLS server{} NGINX, поэтому проверяем его прямой вход.
        if ($target === '10.10.0.2:443') $target = '10.10.1.2:443';
        $out = (string) $this->ssh(self::realityMaskCommand($target, $sni), 'xr');
        if ($this->sshFailed) {
            return ['status' => 'error', 'reason' => 'ssh', 'alpn' => '', 'record' => 0];
        }
        return self::realityMaskVerdict($out);
    }

    // Последний результат для текущих адреса и SNI маски; null — его нет.
    public function realityMaskCached(?array $x = null): ?array
    {
        [$target, $sni] = $this->realityMaskTarget($x);
        if ($target === '' || !is_file(static::REALITY_MASK_FILE)) {
            return null;
        }
        $c = json_decode((string) @file_get_contents(static::REALITY_MASK_FILE), true);
        if (!is_array($c) || ($c['target'] ?? '') !== $target || ($c['sni'] ?? '') !== $sni) {
            return null;
        }
        return $c;
    }

    // Проверить маску, если результата нет или он устарел ($fresh — всегда).
    public function realityMaskCheck(bool $fresh = false): ?array
    {
        $x = $this->getXray();
        [$target, $sni] = $this->realityMaskTarget($x);
        if ($target === '') {
            return null;
        }
        $c = $this->realityMaskCached($x);
        if (!$fresh && $c !== null) {
            $ttl = in_array($c['status'] ?? '', ['ok', 'short', 'tls12'], true) ? self::REALITY_MASK_TTL : self::REALITY_MASK_RETRY;
            if (time() - (int) ($c['ts'] ?? 0) < $ttl) {
                return $c;
            }
        }
        $r = $this->realityMaskProbe($target, $sni) + ['target' => $target, 'sni' => $sni, 'ts' => time()];
        // Отметка об отправленном уведомлении переживает перепроверку той же маски.
        if (isset($c['alerted'])) $r['alerted'] = $c['alerted'];
        $this->realityMaskSave($r);
        return $r;
    }

    protected function realityMaskSave(array $r): void
    {
        if (@file_put_contents(static::REALITY_MASK_FILE, json_encode($r), LOCK_EX) === false) {
            error_log('realityMaskCheck: cannot write ' . static::REALITY_MASK_FILE);
        }
    }

    // Cron: маска могла перестать отвечать с ALPN или по TLS 1.3. Ядро не
    // меняем, а один раз на каждое новое состояние сообщаем администраторам.
    public function checkRealityMask(): void
    {
        if (($this->getPacConf()['transport'] ?? '') !== 'Reality') return;
        $r = $this->realityMaskCheck();
        if ($r === null || ($r['status'] ?? '') === 'error') return;
        $refusal = self::realityMaskRefusal($r, $this->realityAcksServerName());
        if ($refusal === ($r['alerted'] ?? '')) return;
        if ($refusal !== '') {
            $this->notifyAdmins('⚠ ' . sprintf($this->i18n($refusal), self::esc((string) ($r['sni'] ?? ''))));
            $r['alerted'] = $refusal;
        } else {
            unset($r['alerted']);
        }
        $this->realityMaskSave($r);
    }

    // Предупреждения о маске для меню Xray; только по сохранённому результату.
    public function realityMaskWarnings(?array $r = null): array
    {
        $r = $r ?? $this->realityMaskCached();
        $domain = htmlspecialchars((string) ($r['sni'] ?? ''), ENT_QUOTES);
        return match ($r['status'] ?? '') {
            'short' => [sprintf($this->i18n($this->realityAcksServerName() ? 'reality mask short now' : 'reality mask short'), $domain)],
            'tls12' => [sprintf($this->i18n('reality mask tls12'), $domain)],
            'fail'  => [sprintf($this->i18n('reality mask fail'), $domain, htmlspecialchars((string) ($r['reason'] ?? ''), ENT_QUOTES))],
            default => [],
        };
    }

    // Кнопка «проверить»: проба сразу, итог во всплывающем окне и в меню.
    public function checkFakeDomain()
    {
        $r = $this->realityMaskCheck(true);
        $status = $r['status'] ?? '';
        $warnings = $r === null ? [] : $this->realityMaskWarnings($r);
        // Маска без ALPN, но выбранное ядро её принимает: назвать установленные
        // ядра, которым она подходит и не подходит, вместо общего предупреждения.
        $fit = $status === 'short' && !$this->realityAcksServerName() ? $this->realityMaskCoreFit() : [[], []];
        $text = match (true) {
            $r === null          => 'fake domain: ?',
            $status === 'error'  => 'fake domain: ? (ssh)',
            $status === 'ok'     => '✅ TLS 1.3, ALPN ' . (($r['alpn'] ?? '') ?: '—') . ' — ' . $this->i18n('reality mask fits all'),
            $fit[0] && !$fit[1]  => '✅ TLS 1.3, ' . $this->i18n('reality mask no alpn') . ' — ' . $this->i18n('reality mask fits all'),
            (bool) $fit[0]       => '⚠ ' . sprintf($this->i18n('reality mask fits cores'), implode(', ', $fit[0]), implode(', ', $fit[1])),
            (bool) $warnings     => '⚠ ' . html_entity_decode(strip_tags($warnings[0]), ENT_QUOTES),
            default              => '✅ TLS 1.3, ALPN ' . (($r['alpn'] ?? '') ?: '—'),
        };
        $this->answer($this->input['callback_id'], mb_substr($text, 0, 200), true);
        $this->xray();
    }

    // Установленные ядра, которые примут маску без ALPN, и которые нет — по
    // правилу каждого бинаря. [[], []] — состав или правило узнать не удалось.
    public function realityMaskCoreFit(): array
    {
        $fit = $unfit = [];
        foreach ($this->xrayCoreInventory() as $core => $version) {
            $acks = $this->xrayCoreAcksServerName($core);
            if ($acks === null) return [[], []];
            $label = ($core === 'fork' ? $this->t('форк ', 'fork ') : '') . $version;
            if ($acks) $unfit[$label] = true;
            else $fit[$label] = true;
        }
        return [array_keys($fit), array_keys($unfit)];
    }

    public function subscriptionCompatibilityError(array $xr, array $pac, string $type): string
    {
        $encryption = VlessEncryption::client($xr, $pac);
        if ($encryption === null) {
            return 'vless encryption unavailable';
        }
        if ($type === 'si') {
            if ($encryption !== 'none') {
                return 'vless encryption singbox';
            }
            if (($pac['transport'] ?? '') === 'Reality' && $this->realityRequiresMlkem()) {
                return 'reality singbox mlkem';
            }
        }
        return '';
    }

    public function vlessEncryptionMenu()
    {
        $p = $this->getPacConf();
        $s = is_array($p['vless_encryption'] ?? null) ? $p['vless_encryption'] : [];
        $text = ['Menu -> ' . $this->i18n('xray') . ' -> VLESS Encryption', $this->i18n('vless encryption refresh')];
        $text[] = $this->i18n('vless encryption singbox');
        if (($p['transport'] ?? '') === 'trojan-grpc') {
            $text[] = $this->i18n('vless encryption transport');
        }
        $data = [[['text' => $this->i18n(empty($s['enabled']) ? 'off' : 'on'), 'callback_data' => '/vlessEncryptionSet off native']]];
        foreach (['x25519' => 'X25519', 'mlkem768' => 'ML-KEM-768'] as $auth => $label) {
            $row = [];
            foreach (VlessEncryption::MODES as $mode) {
                $selected = !empty($s['enabled']) && ($s['auth'] ?? '') === $auth && ($s['mode'] ?? '') === $mode;
                $row[] = ['text' => "$label / $mode" . ($selected ? ' ✓' : ''), 'callback_data' => "/vlessEncryptionSet $auth $mode"];
            }
            $data[] = $row;
        }
        if (!empty($s['enabled'])) {
            $data[] = [['text' => $this->i18n('vless encryption rotate'), 'callback_data' => '/vlessEncryptionRotate']];
        }
        $data[] = $this->menuHelpButton('encryption');
        $data[] = [['text' => $this->i18n('back'), 'callback_data' => '/xray']];
        $this->update($this->input['chat'], $this->input['message_id'], implode("\n", $text), $data);
    }

    public function setVlessEncryption(string $auth, string $mode, bool $rotate = false): void
    {
        $error = $this->applyVlessEncryption($auth, $mode, $rotate);
        $this->answer($this->input['callback_id'], $this->i18n($error ?: 'vless encryption updated'), true);
        $this->vlessEncryptionMenu();
    }

    public function applyVlessEncryption(string $auth, string $mode, bool $rotate = false): string
    {
        if (!in_array($auth, ['off', 'x25519', 'mlkem768'], true) || !in_array($mode, VlessEncryption::MODES, true)) {
            return 'vless encryption unavailable';
        }
        return $this->withLock('xray', function () use ($auth, $mode, $rotate) {
            return $this->withLock('pac', function () use ($auth, $mode, $rotate) {
                $p = $this->getPacConf();
                $old = $p;
                $x = $this->getXray();
                if (!is_array($p) || !is_array($x)) {
                    return 'vless encryption unavailable';
                }
                $s = is_array($p['vless_encryption'] ?? null) ? $p['vless_encryption'] : [];
                if ($rotate && empty($s['enabled'])) {
                    return 'vless encryption unavailable';
                }
                if ($auth !== 'off') {
                    if (($x['inbounds'][0]['protocol'] ?? '') !== 'vless') {
                        return 'vless encryption transport';
                    }
                    if ($rotate || ($s['auth'] ?? '') !== $auth || VlessEncryption::pair($s) === null) {
                        // Вывод содержит приватные ключи: не выводить в UI/лог.
                        $pairs = VlessEncryption::parseOutput((string) $this->ssh('xray vlessenc', 'xr'));
                        if ($this->sshFailed || !isset($pairs[$auth])) {
                            return 'vless encryption generate failed';
                        }
                        $s = $pairs[$auth];
                    }
                    $s['mode'] = $mode;
                }
                $s['enabled'] = $auth !== 'off';
                $p['vless_encryption'] = $s;
                if (!VlessEncryption::applyServer($x, $p) || !$this->validateXrayConfig($x)) {
                    return 'vless encryption check failed';
                }
                if ($this->setPacConf($p) === false) {
                    return 'vless encryption save failed';
                }
                if ($this->restartXray($x) === false) {
                    if ($this->setPacConf($old) === false) throw new RuntimeException($this->t('Не удалось восстановить настройки Xray', 'Could not restore Xray settings'));
                    return 'vless encryption save failed';
                }
                return '';
            }, 20, 'vless encryption save failed');
        }, 20, 'vless encryption save failed');
    }

    public function validateXrayConfig(array $config, string $binary = 'xray'): bool
    {
        // Проверка через stdin: закрытые ключи не появляются даже временно
        // в общем /logs. Наружу выходит только маркер успеха.
        // getXray() читает JSON как массив: восстановить stats:{} до проверки,
        // как это делает restartXray() перед записью рабочего конфига.
        if (isset($config['stats']) && $config['stats'] === []) {
            $config['stats'] = new stdClass();
        }
        if (isset($config['policy']['levels']) && is_array($config['policy']['levels'])) {
            $config['policy']['levels'] = (object) $config['policy']['levels'];
        }
        $json = json_encode($config, JSON_UNESCAPED_SLASHES);
        if ($json === false) {
            return false;
        }
        if (strlen($json) > 32 * 1024 * 1024) return false;
        // head завершает поток ровно после JSON: SSH2 не умеет закрыть только
        // stdin канала, а ядро читает конфиг до EOF. BusyBox head есть и в
        // прежних образах, поэтому не нужен временный файл или новый Python.
        $out = $this->sshInputCommand('head -c ' . strlen($json)
            . ' | XRAY_LOCATION_ASSET=/logs/geodata timeout 15 ' . escapeshellarg($binary)
            . ' run -test -format json -config stdin: >/dev/null 2>&1 && printf XRAY_CONFIG_OK', $json, 'xr');
        return !$this->sshFailed && trim($out) === 'XRAY_CONFIG_OK';
    }

    // Версия Xray-core из контейнера. `xray version` печатает строку вида
    // "Xray 1.8.24 (Xray, Penetrates Everything.) ..." — берём номер версии.
    // Не требует запущенного процесса, поэтому работает даже когда xray off.
    public function getXrayVersion()
    {
        // Строку берём из общей пробы контейнера (xrayCoreProbe): меню читает и
        // версию, и состояние ядра — незачем ходить по ssh дважды.
        $out = $this->xrayCoreProbe()['version'];
        if (preg_match('~Xray\s+v?(\S+)~i', (string) $out, $m)) {
            return $m[1];
        }
        return '';
    }

    // ---- Выбор ядра Xray ----------------------------------------------------
    // В образе xr лежат до трёх версий XTLS и форк Jolymmiles со sing-mux.
    // Активное ядро — симлинк /usr/local/bin/xray (в PATH alpine он раньше
    // /usr/bin), желаемое — маркер /logs/xray_core, который переживает
    // пересоздание контейнера и читается start_xray.sh при каждом старте.

    public const XRAY_CORE_MARKER = '/logs/xray_core';
    public const XRAY_BIN_ORIGIN  = '/usr/bin/xray';
    public const XRAY_BIN_FORK    = '/usr/bin/xray-smux';
    public const XRAY_BINARIES = [
        'origin' => self::XRAY_BIN_ORIGIN,
        'origin2' => '/usr/bin/xray-2',
        'origin3' => '/usr/bin/xray-3',
        'fork' => self::XRAY_BIN_FORK,
    ];

    public function xrayCoreMenu(): void
    {
        $versions = $this->xrayCoreInventory();
        $probe = $this->xrayCoreProbe(true);
        $selected = $this->xrayCoreSelection();
        $running = $probe['running_selection'] ?? '';
        $label = static fn($core) => ($core === 'fork' ? 'fork (SMUX)' : 'XTLS')
            . ' ' . ($versions[$core] ?? '?');
        $text = ['Menu → Xray → ' . $this->i18n('xray versions'), $this->i18n('xray versions hint')];
        if (!$probe['ok']) {
            $text[] = $this->i18n('smux xr unreachable');
        } else {
            $text[] = $this->i18n('xray running') . ': ' . ($running !== '' ? $label($running) : '—');
            if (!isset($versions[$selected])) {
                $text[] = $this->i18n('xray version missing');
            } elseif ($running !== '' && $running !== $selected) {
                $text[] = str_replace('%s', $label($running), $this->i18n('smux core mismatch'));
            }
        }
        $data = [];
        foreach ($versions as $core => $version) {
            $data[] = [[
                'text' => ($selected === $core ? '✓ ' : '') . $label($core),
                'callback_data' => '/selectXrayCore ' . $core,
            ]];
        }
        $data[] = [['text' => $this->i18n('back'), 'callback_data' => '/xray']];
        $this->update($this->input['chat'], $this->input['message_id'], implode("\n", $text), $data);
    }

    public function selectXrayCore(string $core): void
    {
        // Ядро, подтверждающее SNI, с маской без ALPN отвергло бы всех клиентов
        // REALITY: не переключаем, пока маска такая.
        if (($this->getPacConf()['transport'] ?? '') === 'Reality' && $this->xrayCoreAcksServerName($core) === true) {
            $mask = $this->realityMaskCheck(true);
            if ($mask !== null && self::realityMaskRefusal($mask, true) === 'reality mask short now') {
                $this->answer($this->input['callback_id'], mb_substr(sprintf($this->i18n('xray core mask alpn'), (string) ($mask['sni'] ?? '')), 0, 200), true);
                $this->xrayCoreMenu();
                return;
            }
        }
        $r = $this->applyXrayCore($core);
        $message = !empty($r['ok']) ? 'xray version switched' : match (true) {
            in_array('rollback failed', $r['note'], true) => 'xray rollback failed',
            in_array('core start failed', $r['note'], true) => 'xray start failed',
            in_array('core missing', $r['note'], true), in_array('fork missing', $r['note'], true) => 'xray version missing',
            in_array('xr unreachable', $r['note'], true) => 'smux xr unreachable',
            in_array('core switch busy', $r['note'], true) => 'xray switch busy',
            in_array('xray configuration check failed', $r['note'], true),
            in_array('vless encryption check failed', $r['note'], true) => 'xray version incompatible',
            default => 'smux apply failed',
        };
        $this->answer($this->input['callback_id'], $this->i18n($message), true);
        $this->xrayCoreMenu();
    }

    public function xrayCoreSelection(?array $p = null): string
    {
        $core = ($p ?? $this->getPacConf())['xray_core'] ?? 'origin';
        return is_string($core) && isset(self::XRAY_BINARIES[$core]) ? $core : 'origin';
    }

    // Версии читаем из образа: .env задаёт сборку, а не состав уже скачанного xr.
    public function xrayCoreInventory(): array
    {
        $commands = [];
        foreach (self::XRAY_BINARIES as $core => $bin) {
            $commands[] = 'if test -x ' . $bin . '; then printf "' . $core . '|"; '
                . $bin . ' version 2>/dev/null | head -n1; fi';
        }
        $out = (string) $this->ssh(implode('; ', $commands), 'xr');
        if ($this->sshFailed) return [];
        $versions = [];
        foreach (explode("\n", $out) as $line) {
            if (preg_match('~^(origin[23]?|fork)\|Xray\s+v?([0-9][\w.+-]*)\s~', $line, $m)) {
                $versions[$m[1]] = $m[2];
            }
        }
        return $versions;
    }

    // Проверяем именно запущенный бинарник, а не симлинк или успешный SSH.
    // Две последовательные проверки процесса и API отсекают немедленное
    // падение и процесс, который ещё не открыл слушатели.
    public function xrayCoreStarted(string $core): bool
    {
        if (!isset(self::XRAY_BINARIES[$core])) return false;
        $out = $this->ssh('n=0; good=0; while [ "$n" -lt 15 ]; do '
            . 'p=$(pgrep -f "[x]ray run" | head -n1); '
            . 'if [ -n "$p" ] && [ "$(readlink -f /proc/$p/exe 2>/dev/null)" = '
            . escapeshellarg(self::XRAY_BINARIES[$core]) . ' ] '
            . '&& timeout 1 xray api statsquery --server=127.0.0.1:8080 >/dev/null 2>&1; then good=$((good+1)); '
            . 'else good=0; fi; [ "$good" -ge 2 ] && { printf XRAY_STARTED; break; }; '
            . 'n=$((n+1)); sleep 0.2; done', 'xr');
        return !$this->sshFailed && trim((string) $out) === 'XRAY_STARTED';
    }

    // Ядро, ВЫБРАННОЕ в настройках. Источник истины для генерации конфигов:
    // smux нельзя класть клиентам, пока сервер не на форке.
    public function xrayCore(?array $p = null): string
    {
        $p = $p ?? $this->getPacConf();

        return ($p['xray_core'] ?? '') === 'fork' ? 'fork' : 'origin';
    }

    // Состояние контейнера xr одним ssh-заходом: есть ли форк-бинарь, куда
    // смотрит симлинк, какие алгоритмы конгестии знает ядро хоста. Меню
    // спрашивает всё это по нескольку раз за отрисовку, а каждый ssh — коннект
    // и авторизация; мемоизация на время запроса убирает лишние.
    public function xrayCoreProbe(bool $fresh = false): array
    {
        if (!$fresh && $this->xrProbe !== null) {
            return $this->xrProbe;
        }
        // Версия — ПОСЛЕДНИМ полем: её строка приходит от ядра и теоретически
        // может содержать разделитель, а испортить она тогда сможет только себя.
        //
        // Запущенный бинарь читаем через /proc: симлинк говорит, что стартует в
        // СЛЕДУЮЩИЙ раз, а клиентов обслуживает процесс, поднятый когда-то
        // раньше — после `ln -sf` без рестарта это разные ядра. Шаблон pgrep
        // намеренно записан как "[x]ray run": иначе он найдёт и сам шелл,
        // выполняющий эту команду, — в его argv строка "xray run" тоже есть.
        // Пустой pid обязательно отсекать до readlink: `/proc//exe` тот
        // схлопывает в существующий путь /proc/exe и печатает ЕГО, то есть
        // незапущенное ядро выглядело бы как чужой бинарь — расхождение на
        // ровном месте, а за ним рестарт по кругу каждые пять минут.
        $out = (string) $this->ssh(
            'printf "%s|%s|%s|%s|%s" '
                . '"$(test -x ' . self::XRAY_BIN_FORK . ' && echo 1)" '
                . '"$(readlink -f /usr/local/bin/xray)" '
                . '"$(cat /proc/sys/net/ipv4/tcp_available_congestion_control 2>/dev/null)" '
                . '"$(p=$(pgrep -f "[x]ray run" | head -n1); test -n "$p" && readlink -f /proc/$p/exe 2>/dev/null)" '
                . '"$(xray version 2>&1 | head -n1; printf "\nREALITY_BUILD="; '
                . 'LC_ALL=C grep -a -m 1 -oE \'github\\.com/xtls/reality[[:space:]]+v[0-9A-Za-z.+_-]+\' /usr/local/bin/xray 2>/dev/null '
                . '| head -n1 | awk \'{printf "%s", $2}\'; '
                // Форк с 26.10.5 собирает REALITY из своего дерева (replace в
                // go.mod): версия зависимости та же, что у апстрима, поведение — нет.
                . 'LC_ALL=C grep -a -q -E \'=>[[:space:]]+\\./third_party/reality[[:space:]]\' /usr/local/bin/xray 2>/dev/null '
                . '&& printf "+local")"',
            'xr'
        );
        // ok=false — контейнер не ответил. Отличать это от «форка нет» ОБЯЗАТЕЛЬНО:
        // лежащий на минуту xr иначе выглядел бы как откат образа, и авторемонт
        // снёс бы рабочую настройку ядра вместе со smux.
        $ok = !$this->sshFailed;
        $p  = explode('|', trim($out));
        // Пустая строка у running — это «ядро не запущено» (start_xray.sh не
        // поднимает xray без клиентов), и она НЕ должна читаться как «работает
        // апстрим»: иначе свежая установка выглядела бы как расхождение и
        // авторемонт гонял бы рестарт по кругу.
        $run = $ok ? trim($p[3] ?? '') : '';
        $version = $ok ? trim(implode('|', array_slice($p, 4))) : '';
        $reality = '';
        $realityLocal = false;
        if (preg_match('~\nREALITY_BUILD=(\S*)$~D', $version, $build)) {
            $reality = $build[1];
            $version = rtrim(substr($version, 0, -strlen($build[0])));
            if (str_ends_with($reality, '+local')) {
                $realityLocal = true;
                $reality = substr($reality, 0, -6);
            }
        }

        $this->xrProbe = [
            'ok'      => $ok,
            'fork'    => $ok && trim($p[0] ?? '') === '1',
            'active'  => $ok && trim($p[1] ?? '') === self::XRAY_BIN_FORK ? 'fork' : 'origin',
            'brutal'  => $ok && in_array('brutal', preg_split('~\s+~', trim($p[2] ?? '')) ?: [], true),
            'running' => $run === '' ? '' : ($run === self::XRAY_BIN_FORK ? 'fork' : 'origin'),
            'selection' => $ok ? (array_search(trim($p[1] ?? ''), self::XRAY_BINARIES, true) ?: '') : '',
            'running_selection' => array_search($run, self::XRAY_BINARIES, true) ?: '',
            'version' => $version,
            'reality' => $reality,
            'reality_local' => $realityLocal,
        ];
        // Кеш — только рядом с настоящим xray.json: тесты с подменой SSH и
        // без своего конфига не пишут поддельную пробу никуда.
        if ($ok && is_file($this->xrayConf)) {
            $this->atomicJson($this->xrayCoreProbeFile(), ['time' => time(), 'probe' => $this->xrProbe]);
        }
        return $this->xrProbe;
    }

    // Проба ядра для выдачи подписок. Живая проба — SSH в xr, 150–250 мс на
    // каждый запрос sing-box; ядро же меняется только кнопкой бота (после неё
    // applyXrayCoreLocked() делает свежую пробу) и обновлением (cron при
    // старте проверяет ядро сразу). Поэтому подписка берёт последнюю удачную
    // пробу не старше XRAY_PROBE_CACHE_TTL: cron освежает её каждые 300 с.
    // Файл лежит в /config, а не в /logs: /logs смонтирован на запись почти
    // всем контейнерам протоколов, /config — только php и service.
    public const XRAY_PROBE_CACHE_TTL = 600;

    protected function xrayCoreProbeFile(): string
    {
        return dirname($this->xrayConf) . '/xray-core-probe.json';
    }

    public function useCachedXrayCoreProbe(): void
    {
        if ($this->xrProbe !== null) return;
        $file = $this->xrayCoreProbeFile();
        $data = is_file($file) ? json_decode((string) @file_get_contents($file), true) : null;
        $probe = is_array($data) ? ($data['probe'] ?? null) : null;
        if (!is_array($probe) || !is_int($data['time'] ?? null) || abs(time() - $data['time']) > self::XRAY_PROBE_CACHE_TTL) return;
        $types = ['ok' => 'boolean', 'fork' => 'boolean', 'active' => 'string', 'brutal' => 'boolean', 'running' => 'string',
            'selection' => 'string', 'running_selection' => 'string', 'version' => 'string', 'reality' => 'string', 'reality_local' => 'boolean'];
        foreach ($types as $key => $type) {
            if (gettype($probe[$key] ?? null) !== $type) return;
        }
        if ($probe['ok'] !== true || !in_array($probe['active'], ['fork', 'origin'], true) || !in_array($probe['running'], ['', 'fork', 'origin'], true)) return;
        $this->xrProbe = array_intersect_key($probe, $types);
    }

    // Есть ли форк в образе вообще. Старый образ (до этой правки) второго
    // бинаря не содержит — тогда кнопку переключения показывать нельзя.
    public function forkAvailable(): bool
    {
        return $this->xrayCoreProbe()['fork'];
    }

    // Ядро, которое РЕАЛЬНО запустится сейчас (куда смотрит симлинк). Отдельно
    // от xrayCore(): расхождение настройки и симлинка — это тихая поломка всех
    // клиентов, поэтому в меню показываем факт, а не намерение.
    public function activeXrayCore(): string
    {
        return $this->xrayCoreProbe()['active'];
    }

    // Доступен ли ядру хоста алгоритм конгестии brutal. Контейнер делит ядро с
    // хостом, поэтому проверка изнутри xr достоверна. Без модуля включённый
    // Brutal рвёт НЕСУЩЕЕ соединение при обмене скоростями, то есть кладёт
    // клиента целиком — кнопку в меню в этом случае не показываем.
    public function brutalAvailable(): bool
    {
        return $this->xrayCoreProbe()['brutal'];
    }

    // Самолечение двух расхождений «настройка говорит форк, а работает не он»:
    //
    //   1. форка нет в образе вообще (откат образа xr на версию без
    //      /usr/bin/xray-smux) — чинить нечем, гасим smux и возвращаем
    //      настройку на апстрим;
    //   2. форк есть, но обслуживает апстрим — симлинк пересоздан контейнером
    //      по устаревшему маркеру, поправлен руками мимо меню или откачен
    //      вместе с образом; здесь чиним по-настоящему: возвращаем симлинк.
    //
    // Оба случая снаружи выглядят одинаково — полная тишина: подписки уехали со
    // smux, а апстримное ядро несущего назначения sp.mux.sing-box.arpa:444 не
    // знает и рвёт КАЖДОЕ соединение, не написав ни строки в лог.
    //
    // Проба стоит ssh, поэтому ходим только когда есть что терять (выбран форк)
    // и не чаще раза в 5 минут — cron крутится каждые 10 секунд. Обратное
    // расхождение (выбран апстрим, а симлинк на форке) не трогаем: форк
    // обслуживает и клиентов без мультиплекса, трафику ничего не грозит, а
    // ssh-проба ради него шла бы на КАЖДОЙ установке, включая те, где форк
    // никогда не включали.
    public function checkXrayCore(): void
    {
        if (!empty($this->time_xraycore) && time() - $this->time_xraycore < 300) {
            return;
        }
        if ($this->xrayCore() !== 'fork') return;
        // Cron не должен чинить промежуточное состояние ручного переключения.
        $this->withLock('xray', fn() => $this->withLock('pac',
            fn() => $this->checkXrayCoreLocked(), 1), 1);
    }

    private function checkXrayCoreLocked(): void
    {
        $p = $this->getPacConf();
        if (!is_array($p) || $this->xrayCore($p) !== 'fork') {
            return;
        }
        $this->time_xraycore = time();
        $probe = $this->xrayCoreProbe(true);
        // Контейнер не ответил — это не повод чинить: рестарт xr или временная
        // недоступность ssh не должны сносить настройку.
        if (!$probe['ok']) {
            return;
        }
        if (!$probe['fork']) {
            $this->repairXrayCoreLocked($p);

            return;
        }
        // Симлинк на форке, и обслуживает его же (либо ядро ещё не поднято —
        // это не расхождение). Всё сходится: счётчик попыток можно обнулить.
        if ($probe['active'] === 'fork' && $probe['running'] !== 'origin') {
            $this->xrLinkFix = 0;
            $this->healSmuxHalfCloseLocked($p);

            return;
        }
        $this->restoreXrayLinkLocked();
    }

    // Откат образа xr на форк старее 26.8.25 оставил бы клиентов с require в
    // подписке без связи: договориться о половинном закрытии такое ядро не
    // умеет, а require запрещает откат на прежний несущий коннект — ровно та
    // поломка, которой не видно, пока кто-нибудь не пожалуется. Понижаем до
    // auto: намерение сохраняется, связь возвращается на следующей же выдаче
    // подписки, а require вернётся кнопкой, как только образ обновят.
    public function healSmuxHalfClose(array $p): void
    {
        $entered = false;
        $result = $this->withLock('xray', function () use ($p, &$entered) {
            return $this->withLock('pac', function () use ($p, &$entered) {
            $entered = true;
            return $this->healSmuxHalfCloseLocked($p);
            });
        });
        if (!$entered) throw new RuntimeException($this->t('Не удалось заблокировать настройки Xray', 'Could not lock Xray settings'));
    }

    private function healSmuxHalfCloseLocked(array $p): void
    {
        $p = $this->getPacConf();
        if (self::smuxHalfClose($p['smux']['half_close'] ?? '') !== 'require'
            || $this->smuxHalfCloseReady()
        ) {
            return;
        }
        $p['smux']['half_close'] = 'auto';
        if ($this->setPacConf($p) === false) throw new RuntimeException($this->t('Не удалось сохранить настройки Xray', 'Could not save Xray settings'));
        error_log('healSmuxHalfClose: xray core older than 26.8.25 — half-close require downgraded to auto');
    }

    // Маркер желаемого ядра. Отдельным методом, потому что писать его нужно из
    // трёх мест (переключение, откат, починка) и всем трём одинаково важно не
    // потерять запись молча: /logs — общий том с контейнером xr, и если она не
    // прошла, следующее пересоздание контейнера уведёт ядро мимо настройки.
    public function writeCoreMarker(string $core): bool
    {
        if (!isset(self::XRAY_BINARIES[$core])) return false;
        $tmp = @tempnam(dirname(self::XRAY_CORE_MARKER), '.xray-core-');
        if ($tmp === false) return false;
        try {
            return dirname($tmp) === dirname(self::XRAY_CORE_MARKER)
                && file_put_contents($tmp, $core . "\n") === strlen($core) + 1
                && @rename($tmp, self::XRAY_CORE_MARKER);
        } finally {
            if (is_file($tmp)) @unlink($tmp);
        }
    }

    // Возврат симлинка на форк — единственное направление, в котором чинить
    // есть смысл (см. checkXrayCore, откуда сюда и приходят). Маркер
    // переписываем заодно: если разъехался именно он, одна лишь ссылка не
    // переживёт следующее пересоздание контейнера — start_xray.sh читает
    // маркер, и починка стала бы вечной. false — починить не вышло.
    public function restoreXrayLink(): bool
    {
        $entered = false;
        $result = $this->withLock('xray', function () use (&$entered) {
            return $this->withLock('pac', function () use (&$entered) {
            $entered = true;
            return $this->restoreXrayLinkLocked();
            });
        });
        if (!$entered) throw new RuntimeException($this->t('Не удалось заблокировать настройки Xray', 'Could not lock Xray settings'));
        return $result;
    }

    private function restoreXrayLinkLocked(): bool
    {
        // Три безуспешные попытки подряд — перестаём дёргать ядро каждые пять
        // минут: рестарт рвёт живые сессии, а причина явно не в симлинке
        // (слой контейнера только для чтения, xray поднят мимо start_xray.sh).
        // Уходим на апстрим штатным путём: клиенты поедут, как только
        // перечитают подписку, — это лучше гарантированной тишины у всех.
        if (++$this->xrLinkFix > 3) {
            $this->xrLinkFix = 0;
            $this->repairXrayCoreLocked(null, 'fork core kept losing to the upstream one');

            return false;
        }
        $this->ssh('mkdir -p /usr/local/bin; ln -sf ' . self::XRAY_BIN_FORK . ' /usr/local/bin/xray', 'xr');
        // Контейнер отвалился между пробой и починкой — рестартовать вслепую
        // нечего: следующий заход через пять минут начнёт с новой пробы.
        if ($this->sshFailed) {
            return false;
        }
        if (!$this->writeCoreMarker('fork')) return false;
        error_log('restoreXrayLink: xray core symlink returned to the fork (attempt ' . $this->xrLinkFix . ')');
        // Рестарт уже уходит в форк: pkill + `xray run` идут через симлинк.
        if ($this->restartXray($this->getXray()) === false) throw new RuntimeException($this->t('Не удалось применить настройки Xray', 'Could not apply Xray settings'));
        // Кеш пробы устарел, но перечитывать его здесь нечем: xray только что
        // стартовал, и /proc отдаст либо ещё старый pid, либо ничего. Просто
        // сбрасываем — следующий checkXrayCore() спросит заново.
        $this->xrProbe = null;

        return true;
    }

    // Откат настройки на апстрим + гашение smux. Возвращает true, если чинить
    // действительно пришлось.
    public function repairXrayCore(?array $p = null, string $why = 'fork binary gone from the xr image'): bool
    {
        $entered = false;
        $result = $this->withLock('xray', function () use ($p, $why, &$entered) {
            return $this->withLock('pac', function () use ($p, $why, &$entered) {
            $entered = true;
            return $this->repairXrayCoreLocked($p, $why);
            });
        });
        if (!$entered) throw new RuntimeException($this->t('Не удалось заблокировать настройки Xray', 'Could not lock Xray settings'));
        return $result;
    }

    private function repairXrayCoreLocked(?array $p = null, string $why = 'fork binary gone from the xr image'): bool
    {
        $p = $this->getPacConf();
        if (!is_array($p) || $this->xrayCore($p) !== 'fork') {
            return false;
        }
        $p['xray_core']                 = 'origin';
        $p['smux']['enabled']           = 0;
        $p['smux']['brutal']['enabled'] = 0;
        $p['xhttp_mux']                 = ['enabled' => 0];
        if ($this->setPacConf($p) === false) throw new RuntimeException($this->t('Не удалось сохранить настройки Xray', 'Could not save Xray settings'));
        if (!$this->writeCoreMarker('origin')) return false;
        error_log('repairXrayCore: ' . $why . ' — smux disabled, core reset to upstream');
        if ($this->restartXray($this->getXray()) === false) throw new RuntimeException($this->t('Не удалось применить настройки Xray', 'Could not apply Xray settings'));

        return true;
    }

    // Переключение ядра: маркер + симлинк + рестарт. Заодно приводит настройки
    // smux в состояние, консистентное с ядром (см. smuxDefaults()), — одна
    // кнопка должна давать рабочую конфигурацию, а не полуфабрикат.
    public function applyXrayCore(string $core): array
    {
        if (!isset(self::XRAY_BINARIES[$core])) {
            return ['ok' => false, 'note' => ['core missing']];
        }
        $busy = ['ok' => false, 'note' => ['core switch busy']];
        // Тот же порядок, что у applyVlessEncryption: xray, затем pac.
        return $this->withLock('xray', fn() => $this->withLock('pac',
            fn() => $this->applyXrayCoreLocked($core), 20, $busy), 20, $busy);
    }

    private function applyXrayCoreLocked(string $core): array
    {
        $p    = $this->getPacConf();
        $previous = $p;
        $note = [];

        $probe = $this->xrayCoreProbe(true);
        if (!$probe['ok']) {
            return ['ok' => false, 'note' => ['xr unreachable']];
        }
        if ($core === 'fork' && !$probe['fork']) {
            return ['ok' => false, 'note' => ['fork missing']];
        }
        if (in_array($core, ['origin2', 'origin3'], true) && !isset($this->xrayCoreInventory()[$core])) {
            return ['ok' => false, 'note' => [$this->sshFailed ? 'xr unreachable' : 'core missing']];
        }

        $candidate = $this->getXray();
        if (!is_array($candidate)) {
            return ['ok' => false, 'note' => ['xray configuration check failed']];
        }
        if (!$this->finalmaskCoreCompatible($p, $core)) {
            return ['ok' => false, 'note' => ['xray configuration check failed']];
        }
        $previousJson = $this->readXrayJson();
        // Вход XDRIVE проверяется в том виде, в каком его соберёт restartXray()
        // для нового ядра: ядру без нужного хранилища (S3 на форке) вход не
        // отдаётся, и отказывать в смене ядра из-за него не нужно.
        $check = $candidate;
        $this->ensureXdriveInbound($check, ['xray_core' => $core] + $p);
        if (($candidate['inbounds'][0]['settings']['decryption'] ?? 'none') !== 'none'
            && !$this->validateXrayConfig($check, self::XRAY_BINARIES[$core])) {
            return ['ok' => false, 'note' => ['vless encryption check failed']];
        }

        $p['xray_core'] = $core;
        if ($core === 'fork') {
            // Первое включение (настройки ещё не трогали руками) — засеваем
            // дефолтами и сразу включаем: ради этого ядро и меняют.
            $fresh    = empty($p['smux']['configured']);
            $p['smux'] = $this->smuxSettings($p);
            $p['smux']['enabled'] = 1;
            $note[] = 'smux on';
            if ($this->brutalAvailable()) {
                if ($fresh) {
                    $p['smux']['brutal']['enabled'] = 1;
                    $note[] = 'brutal on';
                }
            } else {
                // Модуля нет — Brutal обязан быть выключен, иначе ensureSmuxInbound
                // пропишет в xray.json блок, на котором ядро порвёт клиентов.
                $p['smux']['brutal']['enabled'] = 0;
            }
        } else {
            $p['smux']['enabled']           = 0;
            $p['smux']['brutal']['enabled'] = 0;
            // Апстрим TCP-сессии Mux.Cool на XHTTP не принимает.
            $p['xhttp_mux'] = ['enabled' => 0];
            $note[] = 'smux off';
        }
        if ($this->setPacConf($p) === false) {
            return ['ok' => false, 'note' => ['settings save failed']];
        }

        // Маркер пишем из php напрямую: /logs — общий том с контейнером xr.
        // Без сохранённого маркера следующее пересоздание выберет другое ядро.
        $bin = self::XRAY_BINARIES[$core];
        if (!$this->writeCoreMarker($core)) {
            $restored = $this->setPacConf($previous) !== false;
            return ['ok' => false, 'note' => [$restored ? 'marker failed' : 'rollback failed']];
        }
        $linked = $this->ssh('mkdir -p /usr/local/bin && ln -sf ' . $bin
            . ' /usr/local/bin/xray && printf XRAY_LINK_OK', 'xr');
        $linkOk = !$this->sshFailed && trim((string) $linked) === 'XRAY_LINK_OK';
        $this->xrProbe = null;
        // Рестарт уже уходит в НОВОЕ ядро: pkill + `xray run` идут через симлинк.
        $restarted = $linkOk && $this->restartXray($candidate) !== false;
        if (!$restarted || !$this->xrayCoreStarted($core)) {
            // Проверка перед restart сохраняет старый процесс; вернём также
            // его выбор в PAC и симлинке, чтобы подписки соответствовали ему.
            $oldCore = $this->xrayCoreSelection($previous);
            $saved = $this->setPacConf($previous) !== false;
            $marked = $this->writeCoreMarker($oldCore);
            $oldBin = self::XRAY_BINARIES[$oldCore];
            $linked = $this->ssh('ln -sf ' . $oldBin . ' /usr/local/bin/xray && printf XRAY_LINK_OK', 'xr');
            $restored = $saved && $marked && !$this->sshFailed && trim((string) $linked) === 'XRAY_LINK_OK';
            $this->xrProbe = null;
            // writeXrayJson пишет в тот же inode (он примонтирован в xr).
            // Ошибка записи могла обрезать файл ещё до остановки процесса.
            if ($previousJson !== '' && $this->readXrayJson() !== $previousJson) {
                $written = $this->writeXrayJson($previousJson);
                $restored = $restored && $written;
            }
            // При отказе парсера прежний процесс ещё жив. После неудачного
            // старта нужно восстановить также рабочий конфиг и процесс.
            if ($restarted) {
                $restored = $restored && $this->restartXray($candidate) !== false
                    && $this->xrayCoreStarted($oldCore);
            }
            $this->xrayCoreProbe(true);
            return ['ok' => false, 'note' => [
                $restarted ? 'core start failed' : ($linkOk ? 'xray configuration check failed' : 'core link failed'),
                $restored ? 'previous core restored' : 'rollback failed',
            ]];
        }
        // Ручное переключение обнуляет историю автопочинки: администратор только
        // что задал состояние явно, и прошлые неудачи к нему отношения не имеют.
        $this->xrLinkFix = 0;
        // Пробу инвалидируем: следующая отрисовка меню должна показать новое
        // ядро, а не закешированное до переключения.
        $this->xrayCoreProbe(true);

        return ['ok' => true, 'note' => $note];
    }

    public function xray($page = 0)
    {
        $c      = $this->getXray();
        $p      = $this->getPacConf();
        $text[] = "Menu -> " . $this->i18n('xray');
        if (!empty($c['inbounds'][0]['streamSettings']['realitySettings']['serverNames'][0])) {
            // Итог проверки маски — из кеша (checkRealityMask()), без пробы.
            $mask = ($p['transport'] ?? '') === 'Reality' ? $this->realityMaskCached($c) : null;
            $text[] = "fake domain: <code>{$c['inbounds'][0]['streamSettings']['realitySettings']['serverNames'][0]}</code>"
                . (($mask['status'] ?? '') === 'ok' ? ' · ALPN ' . htmlspecialchars(($mask['alpn'] ?? '') ?: '—', ENT_QUOTES) : '');
        }
        $xrayVersion = $this->getXrayVersion();
        $text[] = 'xray version: ' . ($xrayVersion !== '' ? "<code>$xrayVersion</code>" : '?');
        // Ядро показываем ФАКТИЧЕСКОЕ (куда смотрит симлинк), а не выбранное:
        // расхождение с настройкой означает, что подписки со smux уедут на
        // апстримное ядро и клиенты молча перестанут ходить.
        $probe  = $this->xrayCoreProbe();
        // Работающий процесс главнее симлинка: между `ln -sf` и рестартом они
        // расходятся, а обслуживает клиентов процесс.
        $realCore = $probe['running'] !== '' ? $probe['running'] : $probe['active'];
        $text[] = 'core: ' . (!$probe['ok'] ? '?' : ($realCore === 'fork' ? 'fork (smux)' : 'XTLS'))
            . ($this->smuxActive($p) ? ' · SMUX ' . $this->i18n('on') : '');
        $text[] = 'transport: ' . ($p['transport'] ?: 'Websocket');
        // XHTTP в апстримном sing-box отсутствует (он есть только в xray и
        // mihomo), поэтому подписка t=si/hiddify/karing с этим транспортом
        // импортируется лишь в сборках-форках с поддержкой xhttp. Говорим об
        // этом сразу, а не оставляем пользователя с «unknown transport type».
        if (($p['transport'] ?? '') === 'xhttp') {
            $text[] = $this->i18n('xhttp singbox warn');
        }
        if (($p['transport'] ?? '') === 'Reality') {
            foreach (array_merge($this->realityMaskWarnings($mask ?? null), $this->fingerprintWarnings()) as $warning) {
                $text[] = '⚠ ' . $warning;
            }
            if ($this->realityRequiresMlkem()) {
                $text[] = $this->i18n('reality singbox mlkem');
            }
        }
        if (VlessEncryption::client($c, $p) !== 'none') {
            $text[] = $this->i18n('vless encryption singbox');
        }
        $text[] = 'fingerprint: ' . $this->fingerprint();
        try { $st = $this->getXrayStats(); }
        catch (XrayStatsUnavailable $error) { $st = null; }
        // ?? 0 — на свежей установке (или сразу после resetXrStats) файла
        // статистики нет вовсе, и меню xray открывалось с warning'ами.
        $td = $this->getBytes(($st['global']['download'] ?? 0) + ($st['session']['download'] ?? 0));
        $tu = $this->getBytes(($st['global']['upload'] ?? 0) + ($st['session']['upload'] ?? 0));
        $text[] = $st === null ? $this->t("Статистика недоступна; требуется восстановление или сброс", "Statistics unavailable; restore or reset required") : "↓$td  ↑$tu";
        // Строка выше — global+session ПОЛЬЗОВАТЕЛЬСКОГО inbound'а. Ниже —
        // только текущая сессия (счётчики xray обнуляются его рестартом) и
        // только по тем inbound'ам, которых в ней не видно: прежде всего
        // 'wg-in' (socks :10808, через него наружу ходят WG/AWG-клиенты) —
        // его трафик не учитывался нигде. Пустых строк не плодим.
        $mainTag = (string) ($c['inbounds'][0]['tag'] ?? 'vless_tls');
        $extra   = [];
        foreach (($st['inbounds'] ?? []) as $t => $v) {
            // Входы проверки узлов выхода — служебные: их трафик и так в
            // карточке узла («Трафик через узел»).
            if ((string) $t === $mainTag || str_starts_with((string) $t, self::EXIT_PROBE_TAG)
                || ((int) ($v['download'] ?? 0) + (int) ($v['upload'] ?? 0)) <= 0) {
                continue;
            }
            $extra[] = htmlspecialchars((string) $t, ENT_QUOTES)
                . ' ↓' . $this->getBytes((int) ($v['download'] ?? 0))
                . ' ↑' . $this->getBytes((int) ($v['upload'] ?? 0));
        }
        if (!empty($extra)) {
            $text[] = 'session: ' . implode('  ', $extra);
        }
        $data[] = [['text' => $this->t('Группы пользователей', 'User groups'), 'callback_data' => '/ag']];
        $data[] = [
            [
                'text'          => $this->i18n('reset stats'),
                'callback_data' => '/resetXrStats',
            ],
            [
                'text'          => $this->i18n('reset monthly') . ": " . $this->i18n(!empty($this->getPacConf()['reset_monthly']) ? 'on' : 'off'),
                'callback_data' => '/switchMonthlyStats',
            ],
        ];
        $data[] = [
            [
                'text'          => $this->i18n('main outbound name: ') . ($p['outbound'] ?? 'proxy'),
                'callback_data' => '/mainOutbound',
            ],
        ];
        $data[] = [
            [
                'text'          => $p['linkdomain'] ?? $this->i18n('cdn'),
                'callback_data' => '/addLinkDomain',
            ],
        ];
        $data[] = [
            [
                'text'          => '🔗 ' . $this->i18n('relay') . ': ' . (!empty($p['relays']) ? count($p['relays']) : $this->i18n('off')),
                'callback_data' => '/relayMenu',
            ],
        ];
        if ($p['transport'] == 'Reality') {
            $data[array_key_last($data)][] = [
                'text'          => $this->i18n('selfFakeDomain'),
                'callback_data' => '/selfFakeDomain',
            ];
        }
        $data[] = [
            [
                'text'          => $this->i18n('RLTY') . ' ' . ($p['transport'] == 'Reality' ? $this->i18n('on') : $this->i18n('off')),
                'callback_data' => "/changeTransport Reality",
            ],
            [
                'text'          => $this->i18n('WS') . ' ' . ($p['transport'] == 'Websocket' ? $this->i18n('on') : $this->i18n('off')),
                'callback_data' => "/changeTransport Websocket",
            ],
        ];
        $data[] = [
            [
                'text'          => $this->i18n('XHTTP') . ' ' . ($p['transport'] == 'xhttp' ? $this->i18n('on') : $this->i18n('off')),
                'callback_data' => "/changeTransport xhttp",
            ],
            [
                'text'          => 'Trojan-gRPC ' . ($p['transport'] == 'trojan-grpc' ? $this->i18n('on') : $this->i18n('off')),
                'callback_data' => "/changeTransport trojan-grpc",
            ],
        ];
        $data[] = [
            [
                'text'          => $this->i18n('fingerprint') . ': ' . ucfirst($this->fingerprint()),
                'callback_data' => "/fingerprintMenu",
            ],
            [
                'text'          => $this->i18n('dpi masking'),
                'callback_data' => "/dpiMenu",
            ],
        ];
        $torrentBlocked = $this->xrayTorrentBlocked($p);
        $data[] = [[
            'text' => $this->i18n('xray versions'),
            'callback_data' => '/xrayCoreMenu',
        ]];
        $data[] = [[
            'text' => 'VLESS Encryption: ' . $this->i18n(VlessEncryption::client($c, $p) === 'none' ? 'off' : 'on'),
            'callback_data' => '/vlessEncryption',
        ]];
        $data[] = [[
            'text' => 'XDRIVE: ' . $this->i18n(!empty($p['xdrive']['enabled']) ? 'on' : 'off'),
            'callback_data' => '/xdrive',
        ], [
            'text' => $this->t('🌍 Узлы выхода', '🌍 Exit nodes') . (($exitCount = count($this->exitNodes($p))) ? " ($exitCount)" : ''),
            'callback_data' => '/exits',
        ]];
        $data[] = [
            [
                'text'          => 'SMUX: ' . $this->i18n($this->smuxActive($p) ? 'on' : 'off'),
                'callback_data' => '/smuxMenu',
            ],
            [
                // ⚠️ — тумблер включён, но sniffing выключен (или metadataOnly),
                // то есть правило не совпадёт никогда и торренты идут насквозь.
                'text'          => '🚫 ' . $this->i18n('torrent') . ': '
                    . $this->i18n($torrentBlocked ? 'on' : 'off')
                    . ($torrentBlocked && !$this->xrayTorrentReady($p, $c) ? ' ⚠️' : ''),
                'callback_data' => '/switchXrayTorrent',
            ],
        ];

        $ip_count      = ($p['ip_count'] ?? 0) ?: 1;
        $hwidEnabled   = !empty($p['hwid_limit_enabled']);
        $defaultHwids  = max(1, (int) (($p['hwid_device_count'] ?? 0) ?: 1));
        $data[] = [
            [
                'text'          => $this->i18n('ip limit') . ' ' . (!empty($p['ip_limit']) ? ": {$p['ip_limit']} sec & $ip_count" : $this->i18n('off')),
                'callback_data' => "/setIpLimit",
            ],
            [
                'text'          => $this->i18n('hwid limit') . ': ' . $this->i18n($hwidEnabled ? 'on' : 'off') . " ({$defaultHwids})",
                'callback_data' => '/toggleHwidLimit xray',
            ],
        ];
        $data[] = [
            [
                'text'          => $this->i18n('set hwid devices count'),
                'callback_data' => '/setHwidDevices xray',
            ],
        ];
        $data[] = [
            [
                'text'          => '🔒 ' . $this->i18n('subtoken strict') . ': ' . $this->i18n(!empty($p['subtoken_strict']) ? 'on' : 'off'),
                'callback_data' => '/switchSubtokenStrict',
            ],
        ];
        $data[] = [
            [
                'text'          => $this->t('🔄 сменить ссылки подписок', '🔄 rotate sub links'),
                'callback_data' => '/rotateAllSubTokens',
            ],
        ];
        if ($p['transport'] == 'Reality') {
            $data[] = [
                [
                    'text'          => $this->i18n('changeFakeDomain'),
                    'callback_data' => "/changeFakeDomain",
                ],
                [
                    'text'          => '🔍 ' . $this->i18n('check fake domain'),
                    'callback_data' => "/checkFakeDomain",
                ],
            ];
            $data[] = [
                [
                    'text'          => '🔄 ' . $this->i18n('rotate all'),
                    'callback_data' => "/regenAllXr",
                ],
                [
                    'text'          => '🔑 pbk+sid',
                    'callback_data' => "/regenRealityXr",
                ],
            ];
        }
        $data[] = [
            [
                'text'          => $this->i18n('v2ray templates'),
                'callback_data' => "/templates v2ray",
            ],
            [
                'text'          => $this->i18n('sing-box templates'),
                'callback_data' => "/templates sing",
            ],
            [
                'text'          => $this->i18n('mihomo templates'),
                'callback_data' => "/templates clash",
            ],
        ];
        $data[] = [
            [
                'text'          => $this->i18n('routes'),
                'callback_data' => "/routes",
            ],
            [
                'text'          => $this->i18n('tun lists'),
                'callback_data' => "/tun",
            ],
        ];
        $on = $off = 0;
        foreach ($c['inbounds'][0]['settings']['clients'] as $k => $v) {
            if (!empty($v['off'])) {
                $off++;
            } else {
                $on++;
            }
        }
        $type    = !empty($this->getPacConf()['xtlslist']);
        $clients = array_filter($c['inbounds'][0]['settings']['clients'], fn($e) => !$type ? empty($e['off']) : !empty($e['off']));
        // Переключатель списка общий для всех администраторов: пустой выбранный
        // список при непустом другом выглядел как «пользователи пропали».
        if (!$clients && ($type ? $on : $off) > 0) {
            $text[] = '';
            $text[] = $this->i18n($type ? 'xray list off empty' : 'xray list on empty');
        }
        uasort($clients, fn($a, $b) => (($a['time'] ?? 0) ?: PHP_INT_MAX) <=> (($b['time'] ?? 0) ?: PHP_INT_MAX));

        $wg  = json_decode(file_get_contents($this->clients), true) ?: [];
        $wg1 = json_decode(file_get_contents($this->clients1), true) ?: [];

        foreach ($wg as $k => $v) {
            $wg_clients[$v['interface']['PrivateKey']] = [
                'container' => '1',
                'name'      => $v['interface']['## name'],
            ];
        }
        foreach ($wg1 as $k => $v) {
            $wg_clients[$v['interface']['PrivateKey']] = [
                'container' => '2',
                'name'      => $v['interface']['## name'],
            ];
        }

        $all     = (int) ceil(count($clients) / $this->limit);
        $page    = min($page, $all - 1);
        $page    = $page == -2 ? $all - 1 : $page;
        $clients = $page != -1 ? array_slice($clients, $page * $this->limit, $this->limit, true) : $clients;
        foreach ($clients as $k => $v) {
            // Тот же ?? 0, что в userXr() и sub(): у только что добавленного
            // клиента записи в статистике ещё нет.
            $download = $st === null ? $this->t('неизвестно', 'unknown') : $this->getBytes(($st['users'][$k]['global']['download'] ?? 0) + ($st['users'][$k]['session']['download'] ?? 0));
            $upload   = $st === null ? $this->t('неизвестно', 'unknown') : $this->getBytes(($st['users'][$k]['global']['upload'] ?? 0) + ($st['users'][$k]['session']['upload'] ?? 0));
            $time     = !empty($v['time']) ? $this->getTime($v['time']) : '';
            $data[]   = [
                [
                    'text'          => "{$v['email']}" . ($time ? ": $time" : '') . " (↓$download  ↑$upload)" . (!empty($v['awg']) && !empty($wg_clients[$v['awg']]) ? " {$wg_clients[$v['awg']]['container']}-{$wg_clients[$v['awg']]['name']}" : ''),
                    'callback_data' => "/userXr $k",
                ],
            ];
        }
        if ($page != -1 && $all > 1) {
            $data[] = [
                [
                    'text'          => '<<',
                    'callback_data' => "/xray " . ($page - 1 >= 0 ? $page - 1 : $all - 1),
                ],
                [
                    'text'          => $page + 1,
                    'callback_data' => "/xray $page",
                ],
                [
                    'text'          => '>>',
                    'callback_data' => "/xray " . ($page < $all - 1 ? $page + 1 : 0),
                ],
            ];
        }
        $data[] = [
            [
                'text'          => $this->i18n('add'),
                'callback_data' => "/addXrUser",
            ],
            [
                'text'          => $this->i18n('on') . " $on " . (!$type ? "✅" : ''),
                'callback_data' => "/listXr 0",
            ],
            [
                'text'          => $this->i18n('off') . " $off " . ($type ? "✅" : ''),
                'callback_data' => "/listXr 1",
            ],
        ];
        $onlineCount = count($this->onlineClients());
        $data[] = [
            [
                'text'          => '👥 ' . $this->i18n('online') . ($onlineCount ? " ($onlineCount)" : ''),
                'callback_data' => "/onlines",
            ],
            [
                'text'          => $this->t('🔄 Обновить', '🔄 Refresh'),
                'callback_data' => '/xrayRefresh ' . (int) $page,
            ],
        ];
        $data[] = $this->menuHelpButton('xray');

        $data[] = [
            [
                'text'          => $this->i18n('back'),
                'callback_data' => "/menu",
            ],
        ];
        $data = $this->xrayIdentityButtons($data ?: [], $c);
        $this->update(
            $this->input['chat'],
            $this->input['message_id'],
            implode("\n", $text ?: ['...']),
            $data ?: false,
        );
    }

    public function routes()
    {
        $text[] = "Menu -> " . $this->i18n('xray') . ' -> routes';

        $data = [
            [['text' => $this->t('📖 Справка по правилам', '📖 Rules help'), 'callback_data' => '/routeshelp 0']],
            [[
                'text'          => $this->i18n('block'),
                'callback_data' => "/xtlsblock",
            ]],
            [[
                'text'          => $this->i18n('warp'),
                'callback_data' => "/xtlswarp",
            ]],
            [[
                'text'          => 'domains',
                'callback_data' => "/xtlsproxy",
            ]],
            [[
                'text'          => "subnet",
