    // Остановить прокси и туннель. Прокси первым: без туннеля он не должен
    // принимать соединения ни секунды.
    private const WARP_STOP = 'pkill -x warp-socks 2>/dev/null || true; pkill -x microsocks 2>/dev/null || true; '
        . 'wg-quick down /etc/warp/wgcf-profile.conf 2>/dev/null || true';

    // Поднять туннель и дождаться настоящего рукопожатия, как это делает
    // warp_up() в start_wp.sh: wg-quick up успешен и при недоступном endpoint,
    // и бот сообщал «включено» при неработающем туннеле. Без рукопожатия
    // интерфейс убирается, чтобы сторож не принял его за готовый туннель.
    // Fixups, tunnel, real handshake and the endpoint port fallback: one
    // implementation shared with the container watchdog (warp_fixup.sh up).
    private const WARP_UP = '{ sh /warp_fixup.sh up || exit 1; }';

    // Разбудить сторож в контейнере wp: он запускает SOCKS сразу, а не на
    // следующем проходе через минуту. В старом контейнере файл просто не читают.
    private function warpKick(): void
    {
        $this->ssh('touch /run/warp-kick 2>/dev/null || true', 'wp');
    }

    // Незавершённая смена ключа: вернуть прежний аккаунт из копии или убрать копию.
    public function warpBackup(string $action)
    {
        $this->withLock('warp-control', function () use ($action) {
            $chat = $this->input['chat'];
            if (!$this->warpCommand('test -e /etc/warp/.bak')) {
                return;
            }
            // Оборванная смена ключа в режиме MASQUE могла оставить и новое
            // устройство MASQUE неподтверждённым: его судьба та же, что у копии.
            // Отказ вложенного сценария — отказ всей операции: копия остаётся.
            $masque = fn(string $step) => '{ [ ! -f /warp_masque.sh ] || sh /warp_masque.sh ' . $step . '; }';
            if ($action === 'drop') {
                $this->send($chat, $this->i18n($this->warpCommand($masque('commit') . ' && rm -rf /etc/warp/.bak') ? 'warp backup dropped' : 'warp backup failed'));
                return;
            }
            $p   = $this->getPacConf();
            $off = !empty($p['warpoff']);
            // Возвращаются только те файлы, что есть в копии: чего в ней нет,
            // то на момент обрыва ещё не успели заменить.
            $ok = $this->warpCommand(self::WARP_STOP . '; ' . $masque('rollback') . ' && cd /etc/warp && for f in wgcf-profile.conf wgcf-account.toml; do '
                . 'if [ -f ".bak/$f" ]; then cp -p ".bak/$f" "$f" || exit 1; fi; done');
            // В режиме MASQUE туннель WireGuard не поднимается: прокси запустит сторож.
            if ($ok && !$off && $this->warpMode($p) === 'wireguard') {
                $ok = $this->warpCommand(self::WARP_UP);
            }
            if ($ok) {
                $this->warpCommand('rm -rf /etc/warp/.bak');
                $this->warpKick();
            }
            $this->warpprofile = null;
            $this->send($chat, $this->i18n($ok ? 'warp backup restored' : 'warp backup failed'));
        });
        $this->warp();
    }

    // SSH возвращает только stdout: пустой вывод не доказывает exit 0.
    private function warpCommand(string $command): bool
    {
        $out = $this->ssh('sh -c ' . escapeshellarg($command)
            . ' >/dev/null 2>&1 && printf VPNBOT_WARP_OK', 'wp');
        return !$this->sshFailed && trim((string) $out) === 'VPNBOT_WARP_OK';
    }

    public function addWarpPlus($key)
    {
        $key = trim((string) $key);
        if ($key !== '' && !preg_match('~^[A-Za-z0-9-]+$~', $key)) {
            $this->send($this->input['chat'], $this->i18n('warp key format'));
            return;
        }
        // Копия осталась от смены ключа, оборванной посередине (перезапуск
        // контейнера, обрыв связи). Раньше любая следующая смена молча
        // упиралась в неё навсегда; удалять её сами не можем — в ней может
        // лежать единственный экземпляр оплаченного аккаунта.
        if ($this->warpCommand('test -e /etc/warp/.bak')) {
            $this->send($this->input['chat'], '⚠️ ' . $this->i18n('warp backup found'), button: [[
                ['text' => $this->i18n('warp backup restore'), 'callback_data' => '/warpBackup restore'],
                ['text' => $this->i18n('warp backup drop'), 'callback_data' => '/warpBackup drop'],
            ]]);
            return;
        }
        $this->withLock('warp-control', function () use ($key) {
            $before = $this->getPacConf();
            $off = !empty($before['warpoff']);
            // В режиме MASQUE новый ключ получает и устройство MASQUE, а
            // туннель WireGuard после смены аккаунта не поднимается.
            $masque = $this->warpMode($before) === 'masque';
            $chat = $this->input['chat'];
            $log = '';
            $step = function ($label, $command) use ($chat, &$log) {
                $log .= "$label...";
                $this->sendDraft($chat, 1, $log);
                $ok = $this->warpCommand($command);
                $log .= $ok ? " ok\n" : " failed\n";
                $this->sendDraft($chat, 1, $log);
                return $ok;
            };
            // Меняем только свои поля, перечитывая pac под общей блокировкой.
            $save = function ($disabled, $commit = false) use ($before, $key) {
                $this->pacConfUpdate(function (&$p) use ($disabled, $commit, $before, $key) {
                    if ($disabled) $p['warpoff'] = 1;
                    elseif (array_key_exists('warpoff', $before)) $p['warpoff'] = $before['warpoff'];
                    else unset($p['warpoff']);
                    if ($commit) {
                        if ($key === '') unset($p['warp']);
                        else $p['warp'] = $key;
                    }
                });
            };
            // Не удаляем оставшийся после аварии backup: в нём может быть
            // единственная копия оплаченного аккаунта. Копируем до остановки.
            if (!$step('backing up old profile', 'cd /etc/warp && test ! -e .bak && mkdir -m 700 .bak && '
                . 'for f in wgcf-profile.conf wgcf-account.toml; do if [ -f "$f" ]; then cp -p "$f" ".bak/$f" || exit 1; fi; done')) {
                $this->send($chat, $log);
                return;
            }
            $stopped = false;
            // Откатывать устройство MASQUE можно, только если эта смена ключа
            // сама его зарегистрировала: отметка «не подтверждено» могла
            // остаться от другой оборванной операции, и откат по ней убрал бы
            // рабочее устройство.
            $registered = false;
            $restore = function () use ($off, $masque, $save, $chat, &$log, &$stopped, &$registered) {
                $ok = !$stopped || $this->warpCommand('pkill -x warp-socks 2>/dev/null || true; pkill -x microsocks 2>/dev/null || true; '
                    . 'wg-quick down /etc/warp/wgcf-profile.conf 2>/dev/null || true; '
                    . ($registered ? 'sh /warp_masque.sh rollback; ' : '')
                    . 'cd /etc/warp && for f in wgcf-profile.conf wgcf-account.toml; do '
                    . 'if [ -f ".bak/$f" ]; then cp -p ".bak/$f" "$f" || exit 1; else rm -f "$f" || exit 1; fi; done');
                if ($ok && $stopped && !$off && !$masque) $ok = $this->warpCommand(self::WARP_UP);
                if ($ok) {
                    $save($off);
                    $this->warpCommand('rm -rf /etc/warp/.bak');
                }
                $this->warpprofile = null;
                if ($ok) $this->warpKick();
                $log .= $ok ? "previous account restored\n" : "restore failed; backup retained, WARP disabled\n";
                $this->send($chat, $log);
            };
            try {
                // Watchdog не должен поднимать туннель во время смены аккаунта.
                $save(true);
                $stopped = true;
                if (!$step('stopping warp', 'pkill -x warp-socks 2>/dev/null || true; pkill -x microsocks 2>/dev/null || true; '
                    . 'wg-quick down /etc/warp/wgcf-profile.conf 2>/dev/null || true')) { $restore(); return; }
                if (!$step('registering WARP account', 'umask 077; cd /etc/warp && '
                    . 'rm -f wgcf-profile.conf wgcf-account.toml && wgcf register --accept-tos && chmod 600 wgcf-account.toml')) { $restore(); return; }
                if ($key !== '') {
                    if (!$step('applying license key', "cd /etc/warp && sed -i 's/^license_key.*/license_key = \"$key\"/' wgcf-account.toml && wgcf update")) { $restore(); return; }
                }
                if (!$step('generating profile', 'umask 077; cd /etc/warp && wgcf generate && '
                    . 'sh /warp_fixup.sh && chmod 600 wgcf-account.toml wgcf-profile.conf')) { $restore(); return; }
                if ($masque) {
                    // Прежнее устройство MASQUE хранится до commit: rollback в
                    // $restore() вернёт его вместе с аккаунтом WireGuard.
                    if (!$step('registering MASQUE device', "WARP_LICENSE_KEY='$key' WARP_LICENSE_STRICT=1 sh /warp_masque.sh register")) { $restore(); return; }
                    $registered = true;
                    if (!$off && !$step('checking MASQUE connection', 'sh /warp_masque.sh check ' . ($this->warpMasqueH2($before) ? 'h2' : 'h3 ' . ($this->warpSelectedPort(['warp_mode' => 'masque'] + $before) ?? 443)))) { $restore(); return; }
                } elseif (!$off && !$step('starting warp', self::WARP_UP)) { $restore(); return; }
                $save($off, true);
            } catch (\Throwable $e) {
                $restore();
                throw $e;
            }
            $this->warpprofile = null;
            $this->warpCommand(($masque ? 'sh /warp_masque.sh commit; ' : '') . 'rm -rf /etc/warp/.bak');
            $this->warpKick();
            $this->send($chat, $log);
        });
        $this->warp();
    }

    public function warpStatus()
    {
        // socks5h (резолв на стороне SOCKS, т.е. через туннель) и таймаут
        // 8с: с прежним `-m 1` и локальным резолвом живой WARP регулярно
        // показывался как off на медленном первом соединении.
        $st = $this->ssh('curl -m 8 -s -x socks5h://wp:1080 https://www.cloudflare.com/cdn-cgi/trace', 'xr');
        // ?? '' — штатная ветка «WARP выключен»: curl не достучался, совпадения
        // нет, и $m пуст. Раньше на каждом рендере меню warp это давало
        // «Undefined array key 1».
        preg_match('~warp=(\w+)~', $st, $m);
        return trim($m[1] ?? '') ?: 'off';
    }

    public function analyzeXray()
    {
        // iplimit.php запущен в фоне (`php iplimit.php &`): если этот while(true)
        // упадёт с Throwable, процесс тихо умрёт и IP-limit защита отключится
        // навсегда без следов до перезапуска контейнера. Поэтому и внешний
        // (setup: fopen/fseek), и внутренний (per-line обработка) циклы изолируем
        // try/catch — транзиентная ошибка не должна ронять демон.
        while (true) {
            try {
                if (!empty($this->getPacConf()['ip_limit'])) {
                    $this->pool = [];
                    $log = '/logs/xray';
                    $r   = fopen($log, 'r');
                    if ($r === false) {
                        sleep(10);
                        continue;
                    }
                    fseek($r, 0, SEEK_END);
                    while (true) {
                        $pac = $this->getPacConf();
                        if (empty($pac['ip_limit'])) {
                            break;
                        }
                        try {
                            $currentPosition = ftell($r);
                            clearstatcache();
                            $fileSize = filesize($log);
                            if ($fileSize > $currentPosition) {
                                fseek($r, $currentPosition); // сброс флага feof
                                while (!feof($r)) {
                                    $line = fgets($r);
                                    if ($line !== false) {
                                        $this->frequencyAnalyze($line, $pac);
                                    }
                                }
                            }
                        } catch (\Throwable $e) {
                            error_log('analyzeXray: ' . $e->getMessage());
                        }
                        sleep(1);
                    }
                    fclose($r);
                }
            } catch (\Throwable $e) {
                error_log('analyzeXray(setup): ' . $e->getMessage());
            }
            sleep(10);
        }
    }

    // Limit IP: различные адреса клиента за окно ip_limit секунд (так обещает
    // подсказка «300:2 — не больше 2 разных IP за 5 минут»). Аудит 2026-10-31:
    // прежний счёт обнулялся после каждого уведомления, и два постоянно
    // активных адреса давали уведомление каждые несколько строк журнала
    // (на тестовом сервере — 446 сообщений на 3000 строк), IPv6 не учитывался вовсе, а
    // служебный «Профиль для узла» (к нему ходит другой сервер) поднимал
    // тревогу, хотя в HWID он уже исключён. Теперь — одно уведомление на
    // пользователя за окно, оба семейства адресов, служебные профили — мимо.
    public function frequencyAnalyze($line, $pac)
    {
        if (!preg_match('~\sfrom\s(?:tcp:|udp:)?\[?(?<ip>[0-9A-Fa-f:.]+?)\]?:\d+\s.*?email:\s(?<email>.+)~', (string) $line, $m)) {
            return;
        }
        $packed = @inet_pton($m['ip']);
        $email  = trim($m['email']);
        if ($packed === false || $email === '') {
            return;
        }
        $now    = time();
        $window = max(1, (int) $pac['ip_limit']);
        $limit  = max(1, (int) (($pac['ip_count'] ?? 0) ?: 1));
        $ips    = $this->pool[$email]['ips'] ?? [];
        $ips[inet_ntop($packed)] = $now;
        $ips = array_filter($ips, fn($seen) => $seen + $window >= $now);
        $this->pool[$email]['ips'] = $ips;
        if (count($ips) <= $limit || ($this->pool[$email]['alerted'] ?? 0) + $window > $now) {
            return;
        }
        $xr = $this->getXray();
        foreach ($xr['inbounds'][0]['settings']['clients'] ?? [] as $k => $v) {
            if (($v['email'] ?? null) !== $email) {
                continue;
            }
            if (empty($v['off']) && empty($v['exit_relay'])) {
                $this->pool[$email]['alerted'] = $now;
                $this->ipLimitAlert('vless: ' . self::esc($email) . ' limit ip ' . count($ips) . ' > ' . $limit, (int) $k);
            }
            break;
        }
    }

    protected function ipLimitAlert(string $text, int $client): void
    {
        $c = [];
        require __DIR__ . '/config.php';
        $buttons = $this->xrayIdentityButtons([[['text' => $this->i18n('on'), 'callback_data' => "/switchXr $client"]]], $this->getXray());
        foreach ((array) ($c['admin'] ?? []) as $admin) {
            $this->send($admin, $text, button: $buttons);
        }
    }

    // Включение/выключение туннеля. Раньше вся функция была построена на
    // warp-cli/warp-svc (официальный клиент Cloudflare), которых в образе wp
    // НЕТ — там wgcf + wg + SOCKS-прокси. То есть каждая команда
    // возвращала "not found", туннель не менялся, но флаг warpoff в pac.json
    // всё равно переключался: состояние бота расходилось с реальностью.
    // Теперь выключаем ровно тем же способом, каким поднимаем — wg-quick,
    // а флаг читает ещё и watchdog в start_wp.sh (иначе он поднял бы туннель
    // обратно через три минуты).
    public function offWarp()
    {
        $this->withLock('warp-control', function () {
            $off = !empty($this->getPacConf()['warpoff']);
            if (!empty($this->selfupdate)) {
                if ($off) $this->ssh('pkill -x warp-socks 2>/dev/null || true; pkill -x microsocks 2>/dev/null || true; wg-quick down /etc/warp/wgcf-profile.conf 2>/dev/null || true', 'wp');
                return;
            }
            $save = function ($disabled) {
                $this->pacConfUpdate(function (&$p) use ($disabled) {
                    if ($disabled) $p['warpoff'] = 1;
                    else unset($p['warpoff']);
                });
            };
            $stop = 'pkill -x warp-socks 2>/dev/null || true; pkill -x microsocks 2>/dev/null || true; wg-quick down /etc/warp/wgcf-profile.conf 2>/dev/null || true';
            if ($off && $this->warpMode() === 'masque') {
                // Туннель MASQUE держит прокси, а его запускает сторож: снимаем
                // флаг, будим сторож и ждём ответа пробы. Не дождались —
                // возвращаем «выключено», как и при неудаче WireGuard.
                $save(false);
                $this->warpKick();
                if (!$this->warpAwait('masque', $this->warpMasqueH2())) {
                    $save(true);
                    $this->warpCommand($stop);
                    $this->send($this->input['chat'], '❌ ' . $this->i18n('warp masque up failed'));
                    return;
                }
            } elseif ($off) {
                if (!$this->warpCommand('wg show wgcf-profile >/dev/null 2>&1 || ' . self::WARP_UP)) {
                    $this->send($this->input['chat'], '❌ ' . $this->i18n('warp up failed'));
                    return;
                }
                try { $save(false); }
                catch (\Throwable $e) { $this->warpCommand($stop); throw $e; }
                // Только после снятия флага: иначе сторож проснётся, увидит
                // «выключено» и остановит прокси вместо запуска.
                $this->warpKick();
            } else {
                $save(true);
                if (!$this->warpCommand($stop)) $this->send($this->input['chat'], '❌ ' . $this->i18n('warp stop failed'));
            }
        });
        if (empty($this->selfupdate)) $this->warp();
    }

    public function warp()
    {
        $p      = $this->getPacConf();
        $off    = !empty($p['warpoff']);
        $prof   = $this->getWarpProfile();
        $text[] = "Menu -> " . $this->i18n('warp');
        if ($ver = $this->warpVersion()) {
            $text[] = $ver;
        }
        // wgcf печатает trace в stdout, а лог-строки ("Using config file") в
        // stderr — ssh() читает только stdout, поэтому трейс чистый. Если WARP
        // не поднят, trace пуст: показываем явный "off", чтобы строка статуса
        // не выглядела пустой/сломанной.
        // В режиме MASQUE туннеля в контейнере нет, и запрос от root ушёл бы
        // напрямую: состояние WARP видно только через сам прокси.
        $mode   = $this->warpMode($p);
        $h2     = $this->warpMasqueH2($p);
        $trace  = trim((string) $this->ssh($mode === 'masque'
            ? 'curl -m 8 -s -x socks5h://127.0.0.1:1080 https://www.cloudflare.com/cdn-cgi/trace'
            : 'wgcf trace', 'wp'));
        // Содержимое файлов и вывод команд экранируются: один символ «<» в
        // них — и Telegram отклоняет всё сообщение, меню не открывается.
        $esc    = static fn($value) => htmlspecialchars((string) $value, ENT_NOQUOTES);
        $text[] = "status: " . ($trace !== '' ? '<pre>' . $esc($trace) . '</pre>' : '<code>off</code>');
        // trace выше идёт от root напрямую и ничего не говорит о прокси, через
        // который в WARP ходит Xray. Его состояние и возраст рукопожатия —
        // отдельной строкой.
        $state = (string) $this->ssh('pgrep -x warp-socks >/dev/null 2>&1 && echo socks=1 || echo socks=0; '
            . 'hs=$(wg show wgcf-profile latest-handshakes 2>/dev/null | awk \'{print $2}\' | sort -n | tail -1); '
            . 'echo "hs=${hs:-0}"; echo "now=$(date +%s)"', 'wp');
        $text[] = $this->i18n('warp mode') . ': <b>' . $this->warpModeName($mode, $h2) . '</b>';
        $text[] = $this->warpPortLine($p);
        if (preg_match('~socks=([01])~', $state, $ms) && preg_match('~hs=(\d+)~', $state, $mh) && preg_match('~now=(\d+)~', $state, $mn)) {
            $age    = (int) $mh[1] > 0 ? max(0, (int) $mn[1] - (int) $mh[1]) : null;
            if ($mode === 'masque') {
                // Рукопожатия WireGuard здесь нет: показываем устройство MASQUE.
                $device = $this->warpMasqueStatus();
                $text[] = $this->i18n('warp masque device') . ': ' . (empty($device['id']) ? $this->i18n('warp masque no device')
                    : '<code>' . $esc($device['id']) . '…</code> · ' . $this->i18n('warp masque endpoint') . ' <code>'
                        . $esc(preg_replace('~:\d+$~', '', (string) ($device['endpoint_v4'] ?? ''))) . '</code> · '
                        // Тариф, а не признак warp_plus: Cloudflare ставит его и бесплатным аккаунтам.
                        . $this->i18n('warp masque plan') . ' <code>' . $esc(($device['account_type'] ?? '') ?: '?') . '</code>');
                $age = 0;
            } else {
                $text[] = $this->i18n('warp tunnel') . ': ' . ($age === null ? $this->i18n('warp tunnel down')
                    : $this->i18n('warp handshake') . ' ' . $age . ' ' . $this->i18n('warp seconds ago'));
            }
            $text[] = $this->i18n('warp socks') . ': ' . $this->i18n($ms[1] === '1' ? 'on' : 'off')
                . (!$off && $ms[1] !== '1' && $age !== null ? ' <i>(' . $this->i18n('warp socks pending') . ')</i>' : '');
        }
        // Профиль и аккаунт печатаются ЦЕЛИКОМ — осознанное решение владельца:
        // меню warp задумано как «всё под рукой», ключи оттуда копируют в
        // сторонние клиенты. Держим в уме, что в wgcf-account.toml лежат
        // private_key и access_token аккаунта, а в профиле — PrivateKey
        // интерфейса, и всё это остаётся в истории чата.
        // Чтение с @ и ?? — файлов может не быть на свежей установке, и без
        // подавления меню падало бы в PHP-warning вместо показа статуса.
        $a      = (string) @file_get_contents('/etc/warp/wgcf-account.toml');
        $c      = (string) @file_get_contents('/etc/warp/wgcf-profile.conf');
        $text[] = "key: <code>" . $esc($p['warp'] ?? '') . "</code>";
        $text[] = '<pre>' . $esc($a) . '</pre>';
        $text[] = '<pre>' . $esc($c) . '</pre>';
        // В режиме MASQUE профиль WireGuard не нужен и может отсутствовать.
        if (!$prof && $mode === 'wireguard') {
            $text[] = '⚠ ' . $this->i18n('warp no profile');
        }

        $data[] = [
            [
                'text'          => $this->i18n('set key'),
                'callback_data' => "/warpPlus",
            ],
            [
                'text'          => $this->i18n('warp') . ': ' . $this->i18n($off ? 'off' : 'on'),
                'callback_data' => "/offWarp",
            ],
        ];
        $data[] = [[
            'text'          => $this->i18n('warp mode') . ': ' . $this->warpModeName($mode, $h2) . ' → '
                . ($mode === 'masque' ? 'WireGuard' : 'MASQUE'),
            'callback_data' => '/warpMode',
        ]];
        if ($mode === 'masque') {
            $data[] = [[
                'text'          => $this->i18n('warp masque transport') . ': ' . ($h2 ? 'HTTP/2 → HTTP/3' : 'HTTP/3 → HTTP/2'),
                'callback_data' => '/warpMasqueHttp',
            ]];
        }
        $data[] = [['text' => $this->t('🔌 Порт', '🔌 Port'), 'callback_data' => '/warpPorts'],
            ['text' => $this->t('🔄 Новый аккаунт', '🔄 New account'), 'callback_data' => '/warpReg']];
        $data[] = $this->menuHelpButton('warp');
        $data[] = [
            [
                'text'          => $this->i18n('back'),
                'callback_data' => "/menu",
            ],
        ];
        $this->update(
            $this->input['chat'],
            $this->input['message_id'],
            implode("\n", $text ?: ['...']),
            $data ?: false,
        );
    }

    public function choiceTemplate($arg)
    {
        $entered = false;
        $result = $this->withLock('xray', function () use ($arg, &$entered) {
            $entered = true;
            return $this->choiceTemplateLocked($arg);
        });
        if (!$entered) throw new RuntimeException($this->t('Не удалось заблокировать Xray', 'Could not lock Xray'));
        return $result;
    }

    private function choiceTemplateLocked($arg)
    {
        if (!$this->xrayClientMatches((int) (int) (explode('_', $arg)[1] ?? -1))) return $this->staleXrayAction();
        $arg = explode('_', $arg);
        $c   = $this->getXray();
        if (!empty($arg[2])) {
            $c['inbounds'][0]['settings']['clients'][$arg[1]]["{$arg[0]}template"] = $arg[2];
        } else {
            unset($c['inbounds'][0]['settings']['clients'][$arg[1]]["{$arg[0]}template"]);
        }
        $this->saveXray($c);
        $this->userXrLocked($arg[1]);
    }

    public function templateUser($type, $i)
    {
        $entered = false;
        $result = $this->withLock('xray', function () use ($type, $i, &$entered) {
            $entered = true;
            return $this->templateUserLocked($type, $i);
        });
        if (!$entered) throw new RuntimeException($this->t('Не удалось заблокировать Xray', 'Could not lock Xray'));
        return $result;
    }

    private function templateUserLocked($type, $i)
    {
        if (!$this->xrayClientMatches((int) $i)) return $this->staleXrayAction();
        $c   = $this->getXray();
        $pac = $this->getPacConf();
        // Клиент мог быть удалён кнопкой из другого сообщения — тогда меню
        // строилось из undefined index и рисовало пустой заголовок.
        $client = $c['inbounds'][0]['settings']['clients'][$i] ?? null;
        if ($client === null) {
            return $this->xray();
        }
        $text[]    = "Menu -> " . $this->i18n('xray') . " -> {$client['email']}\n";
        $templates = $pac["{$type}templates"] ?? [];
        $data[]    = [
            [
                'text'          => 'default',
                'callback_data' => "/choiceTemplate {$type}_$i",
            ],
        ];
        $data[] = [
            [
                'text'          => 'origin',
                'callback_data' => "/choiceTemplate {$type}_{$i}_" . base64_encode('origin'),
            ],
        ];
        foreach ($templates as $k => $v) {
            $data[] = [
                [
                    'text'          => $k,
                    'callback_data' => "/choiceTemplate {$type}_{$i}_" . base64_encode($k),
                ],
            ];
        }
        $data[] = [
            [
                'text'          => $this->i18n('back'),
                'callback_data' => "/userXr $i",
            ],
        ];
        $data = $this->xrayIdentityButtons($data ?: [], $c);
        $this->update(
            $this->input['chat'],
            $this->input['message_id'],
            implode("\n", $text ?: ['...']),
            $data ?: false,
        );
    }

    public function userXr($i)
    {
        $entered = false;
        $result = $this->withLock('xray', function () use ($i, &$entered) {
            $entered = true;
            return $this->userXrLocked($i);
        });
        if (!$entered) throw new RuntimeException($this->t('Не удалось заблокировать Xray', 'Could not lock Xray'));
        return $result;
    }

    protected function userXrLocked($i)
    {
        if (!$this->xrayClientMatches((int) $i)) return $this->staleXrayAction();
        $xray   = $this->getXray();
        $c      = $xray['inbounds'][0]['settings']['clients'][$i] ?? null;
        if ($c === null) {
            // Stale callback (client deleted/re-indexed): fall back to the list
            // instead of running the whole menu on null fields.
            $this->xray();
            return;
        }
        $pac    = $this->getPacConf();
        $domain = $this->getDomain($pac['transport'] != 'Reality');
        $scheme = empty($this->nginxGetTypeCert()) ? 'http' : 'https';
        $hash   = $this->getHashBot();

        // Backfill the subscription token for clients created before this feature,
        // so their sub links are addressed by the token (not the credential).
        if (empty($c['subtoken'])) {
            $c['protocol_source'] = ManagedProtocol::xraySource($c);
            $c['subtoken'] = bin2hex(random_bytes(16));
            $xray['inbounds'][0]['settings']['clients'][$i]['protocol_source'] = $c['protocol_source'];
            $xray['inbounds'][0]['settings']['clients'][$i]['subtoken'] = $c['subtoken'];
            $this->saveXray($xray);
        }
        $stok = $this->sidOf($c); // subscription locator (not the credential)

        $devices      = $this->getHwidDevicesByUser($c['id']);
        $hwidEnabled  = !empty($pac['hwid_limit_enabled']) && empty($c['hwid_disabled']);
        $defaultHwid  = max(1, (int) (($pac['hwid_device_count'] ?? 0) ?: 1));
        $hwidLimit    = !empty($c['hwid_limit']) ? (int) $c['hwid_limit'] : $defaultHwid;

        $text[] = "Menu -> " . $this->i18n('xray') . " -> " . htmlspecialchars($c['email'], ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8') . "\n";
        array_push($text, ...$this->subscriptionCardSummary($c, $i));
        if ($scheme === 'http') {
            $text[] = $this->subPlaintextWarning() . "\n";
        }
        $text[] = $this->t('<b>Подключение</b>', '<b>Connection</b>');
        if (file_exists(__DIR__ . '/subscription.php')) {
            $text[] = "<a href='$scheme://{$domain}/pac$hash/sub?id={$stok}'>subscription</a>";
        }
        $linkIndex = count($text);
        $text[] = '<pre><code>' . self::esc($this->linkXray($i)) . "</code></pre>\n";

        $text[] = $this->t('<b>Импорт в приложения</b>', '<b>Import into apps</b>');
        array_push($text, ...$this->subscriptionImportLinks("$scheme://{$domain}/pac$hash", $stok, $c['email']));

        $si = "$scheme://{$domain}/pac$hash/" . base64_encode(serialize([
            'h' => $hash,
            't' => 'si',
            's' => $stok,
        ]));
        $xr = "$scheme://{$domain}/pac$hash/" . base64_encode(serialize([
            'h' => $hash,
            't' => 's',
            's' => $stok,
        ]));
        $cl = "$scheme://{$domain}/pac$hash/" . base64_encode(serialize([
            'h' => $hash,
            't' => 'cl',
            's' => $stok,
        ]));
        // base64 vless share-link list (subVless) — the aggregating subscription
        // that also carries this client's external links / remote subscriptions.
        $vl = "$scheme://{$domain}/pac$hash/" . base64_encode(serialize([
            'h' => $hash,
            't' => 'vl',
            's' => $stok,
        ]));

        $text[] = $this->t('<b>Подписки и файлы</b>', '<b>Subscriptions and files</b>');
        $text[] = "\nxray config: <pre><code>$xr</code></pre>";
        $text[] = "sing-box config: <pre><code>$si</code></pre>";
        $text[] = "mihomo config: <pre><code>$cl</code></pre>";
        $text[] = "Happ / v2rayNG (base64): <pre><code>$vl</code></pre>";

        $text[]   = $this->t('Файлы из кнопок загрузки временные: сохраните их до следующего нажатия в этом меню.', 'Files from the download buttons are temporary: save them before the next tap in this menu.');
        $st = [];
        try { $st = $this->getXrayStats(); $protocolUsage = $this->xrayProtocolUsage($c); }
        catch (Throwable $error) { $protocolUsage = null; }
        $download = $protocolUsage === null ? $this->t('неизвестно', 'unknown') : $this->getBytes(($st['users'][$i]['global']['download'] ?? 0) + ($st['users'][$i]['session']['download'] ?? 0) + $protocolUsage['download']);
        $upload   = $protocolUsage === null ? $this->t('неизвестно', 'unknown') : $this->getBytes(($st['users'][$i]['global']['upload'] ?? 0) + ($st['users'][$i]['session']['upload'] ?? 0) + $protocolUsage['upload']);
        $limit    = (int) ($c['traffic'] ?? 0);
        if ($limit > 0) {
            $used = $protocolUsage === null ? $this->t('неизвестно', 'unknown') : $this->getBytes($this->xrUserTraffic($st, $i) + array_sum($protocolUsage));
            $text[] = $this->i18n('traffic limit') . ": $used / " . $this->getBytes($limit)
                . (!empty($c['traffic_off']) ? ' ⛔' : '');
        }
        $data[]   = [
            [
                'text'          => $this->i18n('reset stats') . ": ↓$download  ↑$upload",
                'callback_data' => "/resetXrUser $i",
            ],
        ];
        $data[] = [
            [
                'text'          => '📊 ' . $this->i18n('traffic limit') . ($limit > 0 ? ': ' . $this->getBytes($limit) : ''),
                'callback_data' => "/setTrafficXr $i",
            ],
        ];
        $data[] = [
            [
                'text'    => $this->i18n('v2ray'),
                'web_app' => ['url' => "https://{$domain}/pac$hash?t=s&s={$stok}"]
            ],
            [
                'text'    => $this->i18n('singbox'),
                'web_app' => ['url' => "https://{$domain}/pac$hash?t=si&s={$stok}"]
            ],
            [
                'text'    => $this->i18n('mihomo'),
                'web_app' => ['url' => "https://{$domain}/pac$hash?t=cl&s={$stok}"]
            ],
        ];
        if (!empty(array_filter($pac['relays'] ?? [], fn($e) => $this->relayForSubscription($e)))) {
            $data[] = [
                [
                    'text'          => '🔗 ' . $this->i18n('relay subscriptions'),
                    'callback_data' => "/userRelay $i",
                ],
            ];
        }
        $extOn = count(array_filter($c['ext'] ?? [], fn($e) => empty($e['off'])));
        $data[] = [['text' => $this->t('Протоколы в готовой подписке', 'Protocols in the ready subscription'), 'callback_data' => '/xp ' . ManagedProtocol::xraySource($c)]];
        if (!empty($c['exit_relay'])) {
            $data[] = [['text' => $this->t('🪪 Профиль для узла', '🪪 Node profile'), 'callback_data' => "/exitRelayLink $i"]];
        } elseif ($this->exitNodes($pac)) {
            $exitOn = count(self::exitClientNodes($c));
            $data[] = [['text' => $this->t('🌍 Узлы выхода', '🌍 Exit nodes') . ($exitOn ? " ($exitOn)" : ''), 'callback_data' => "/exitUser $i"]];
        }
        $data[] = [['text' => $this->t('Отдельные подключения · ссылки и файлы', 'Separate connections · links and files'), 'callback_data' => '/xc ' . ManagedProtocol::xraySource($c)]];
        $data[] = [
            ['text' => $this->t('Mihomo JSON · подписка', 'Mihomo JSON · subscription'), 'web_app' => ['url' => "https://{$domain}/pac$hash?t=clj&s={$stok}"]],
            ['text' => $this->t('Mihomo JSON · файл', 'Mihomo JSON · file'), 'callback_data' => "/dw $i clj"],
        ];
        $data[] = [[
            'text'          => '🧩 ' . $this->i18n('external links') . ($extOn ? " ($extOn)" : ''),
            'callback_data' => "/extUser $i",
        ]];
        $data[] = [[
            'text'          => '🔁 ' . $this->i18n('rotate subscription'),
            'callback_data' => "/rotateSub $i",
        ]];
        $data[] = [
            [
                'text'    => $this->i18n('v2ray ⬇️'),
                'callback_data' => "/dw {$i} s",
            ],
            [
                'text'    => $this->i18n('singbox ⬇️'),
                'callback_data' => "/dw {$i} si",
            ],
            [
                'text'    => $this->i18n('mihomo ⬇️'),
                'callback_data' => "/dw {$i} cl",
            ],
        ];
        $data[] = [
            [
                'text'          => !empty($c['time']) ? "timer: " . $this->getTime($c['time']) : $this->i18n('timer'),
                'callback_data' => "/timerXr $i",
            ],
            [
                'text'          => $this->i18n(!empty($c['off']) ? 'off' : 'on'),
                'callback_data' => "/switchXr $i",
            ],
        ];
        // clientID (UUID) is the credential for vless transports; for trojan-grpc
        // auth is by password, so the clientID button is pointless there — hide it.
        if ($pac['transport'] != 'trojan-grpc') {
            $data[] = [
                [
                    'text'          => '🆔 ' . $this->i18n('new clientID'),
                    'callback_data' => "/regenIdXr $i",
                ],
            ];
        }
        $singtemplate  = !empty($c['singtemplate']) ? base64_decode($c['singtemplate']) : 'default(' . (!empty($pac['defaultsingtemplate']) && !empty($pac['singtemplates'][base64_decode($pac['defaultsingtemplate'])]) ? base64_decode($pac['defaultsingtemplate']) : 'origin') . ')';
        $v2raytemplate = !empty($c['v2raytemplate']) ? base64_decode($c['v2raytemplate']) : 'default(' . (!empty($pac['defaultv2raytemplate']) && !empty($pac['v2raytemplates'][base64_decode($pac['defaultv2raytemplate'])]) ? base64_decode($pac['defaultv2raytemplate']) : 'origin') . ')';
        $clashtemplate = !empty($c['clashtemplate']) ? base64_decode($c['clashtemplate']) : 'default(' . (!empty($pac['defaultclashtemplate']) && !empty($pac['clashtemplates'][base64_decode($pac['defaultclashtemplate'])]) ? base64_decode($pac['defaultclashtemplate']) : 'origin') . ')';
        $data[]        = [
            [
                'text'          => $this->i18n('v2ray') . ": $v2raytemplate",
                'callback_data' => "/templateUser v2ray $i",
            ],
            [
                'text'          => $this->i18n('singbox') . ": $singtemplate",
                'callback_data' => "/templateUser sing $i",
            ],
            [
                'text'          => $this->i18n('mihomo') . ": $clashtemplate",
                'callback_data' => "/templateUser clash $i",
            ],
        ];
        $data[] = [
            [
                'text'          => $this->i18n('qr short'),
                'callback_data' => "/qrXray $i",
            ],
            [
                'text'          => $this->i18n('qr v2ray'),
                'callback_data' => "/qrXray {$i}_1",
            ],
            [
                'text'          => $this->i18n('qr singbox'),
                'callback_data' => "/qrXray {$i}_2",
            ],
        ];
        $data[] = [
            [
                'text'          => $this->i18n('hwid limit') . ': ' . ($hwidEnabled ? $hwidLimit : $this->i18n('off')) . ' (' . count($devices) . ')',
                'callback_data' => "/hwidUser $i",
            ],
        ];
        $data[] = [
            [
                'text'          => '📜 ' . $this->i18n('connection log'),
                'callback_data' => "/clientLog $i",
            ],
        ];
        $data[] = [
            [
                'text'          => $this->i18n('rename'),
                'callback_data' => "/renameXrUser $i",
            ],
            [
                'text'          => $this->i18n('delete'),
                'callback_data' => "/delxr $i",
            ],
        ];
        if ($pac['transport'] == 'trojan-grpc') {
            $text[] = "\npassword: <span class='tg-spoiler'>" . ($c['password'] ?? $c['id']) . "</span>";
            $data[] = [
                [
                    'text'          => $this->i18n('change password'),
                    'callback_data' => "/changeXrPwd $i",
                ],
                [
                    'text'          => $this->i18n('generate password'),
                    'callback_data' => "/genXrPwd $i",
                ],
            ];
        }
        $data[] = $this->menuHelpButton('xray_user', (string) $i);
        $data[] = [
            [
                'text'          => $this->i18n('back'),
                'callback_data' => "/xray",
            ],
        ];
        // ML-DSA REALITY + ML-KEM Encryption могут сделать сам URI длиннее
        // сообщения Telegram. Выдаём его целиком файлом по отдельной кнопке;
        // подписки и управление остаются одной карточкой без хвостов в чате.
        if ($this->messageTextLength(implode("\n", $text)) > 4096) {
            $text[$linkIndex] = $this->i18n('xray link file hint') . "\n";
            array_unshift($data, [[
                'text' => $this->i18n('xray link file'),
                'callback_data' => "/dw $i uri",
            ]]);
        }
        $data = $this->xrayIdentityButtons($data ?: [], $xray);
        $this->update(
            $this->input['chat'],
            $this->input['message_id'],
            implode("\n", $text ?: ['...']),
            $data ?: false,
        );
    }

    // Per-client external links / remote subscriptions (3x-ui port). Lists the
    // client's ext rows with per-row toggle / rename / delete, plus add buttons.
    // Rows feed expandClientExt() → the base64 subscription (subVless / t=vl).
    // Короткий отпечаток строки внешней ссылки для callback_data: кнопки
    // адресуют строку по номеру, а номер сдвигается после удаления. Без сверки
    // повторное нажатие 🗑 в старом сообщении удаляло соседнюю строку.
    public static function extRowKey(array $e): string
    {
        return substr(hash('sha256', ($e['kind'] ?? 'link') . "\n" . ($e['value'] ?? '')), 0, 8);
    }

    // Строка ext клиента $i под номером $k, если отпечаток совпал (или не
    // передан — тогда только из свежего меню, см. маршруты).
    private function extRowMatches(array $c, $i, $k, string $h): bool
    {
        $e = $c['inbounds'][0]['settings']['clients'][$i]['ext'][$k] ?? null;
        return $this->xrayClientMatches((int) $i) && is_array($e) && $h !== '' && hash_equals(self::extRowKey($e), $h);
    }

    // Изменение ext под локом xray.json. Ядро поле ext не читает, поэтому
    // перезапуск не нужен — только запись.
    private function extUpdate(callable $fn)
    {
        return $this->withLock('xray', function () use ($fn) {
            $c = $this->getXray();
            if (!is_array($c)) {
                return null;
            }
            $result = $fn($c);
            if ($result !== null && $result !== false) {
                $this->saveXray($c);
            }
            return $result;
        });
    }

    public function extUser($i, string $notice = '')
    {
        if (!$this->xrayClientMatches((int) $i)) return $this->staleXrayAction();
        $xray = $this->getXray();
        $c    = $xray['inbounds'][0]['settings']['clients'][$i] ?? null;
        if ($c === null) {
            $this->xray();
            return;
        }
        $ext   = $c['ext'] ?? [];
        $cache = $this->readExtSubCache();

        // Имя пользователя — ввод, уходит в parse_mode=HTML.
        $text[] = "Menu -> " . $this->i18n('xray') . " -> " . self::esc($c['email']) . " -> " . $this->i18n('external links');
        if ($notice !== '') {
            $text[] = $notice;
        }
        $text[] = $this->i18n('external hint');
        $text[] = $this->t(
            'Попадают только в подписку v2rayNG (base64) — её берут кнопки импорта Happ, Shadowrocket, Streisand и Hiddify. В Xray JSON, sing-box и Mihomo их нет. Удалённые подписки бот обновляет раз в 5 минут.',
            'They go only into the v2rayNG (base64) subscription, which the Happ, Shadowrocket, Streisand and Hiddify import buttons use. Xray JSON, sing-box and Mihomo do not get them. The bot refreshes remote subscriptions every 5 minutes.') . "\n";
        if (!$ext) {
            $text[] = $this->t('Внешних ссылок пока нет.', 'No external links yet.');
        }

        $data = [];
        foreach ($ext as $k => $e) {
            $icon  = ($e['kind'] ?? 'link') === 'sub' ? '📥' : '🔗';
            // The path of a subscription and the authority of a share link can both contain credentials.
            $value = (string) ($e['value'] ?? '');
            $label = ($e['kind'] ?? 'link') === 'sub'
                ? (string) parse_url($value, PHP_URL_HOST)
                : strtoupper((string) parse_url($value, PHP_URL_SCHEME));
            $short = mb_strimwidth(($e['remark'] ?? '') !== '' ? $e['remark'] : $label, 0, 28, '…');
            $line  = ($k + 1) . ". " . (empty($e['off']) ? '✅' : '⛔') . " $icon <code>" . self::esc($short) . "</code>";
            // For remote subscriptions, surface the last-fetch status from cache:
            // node count + age on success, or the recorded error.
            if (($e['kind'] ?? '') === 'sub') {
                $st = $cache[trim((string) ($e['value'] ?? ''))] ?? null;
                if ($st === null) {
                    $line .= ' — ' . $this->i18n('ext status pending');
                } else {
                    $n    = count($st['links'] ?? []);
                    $secs = !empty($st['ts']) ? max(0, time() - (int) $st['ts']) : null;
                    $age  = $secs === null ? '' : ' · ' . ($secs < 3600 ? floor($secs / 60) . 'm' : floor($secs / 3600) . 'h');
                    if (!empty($st['err'])) {
                        // Ошибка последней попытки; в подписке остаются узлы
                        // последней удачной загрузки, если она была.
                        $line .= ' — ⚠️ ' . self::esc((string) $st['err']) . ($n ? ' · ' . $this->i18n('ext status nodes') . ": $n" . $age : '');
                    } else {
                        $line .= ' — ' . $this->i18n('ext status nodes') . ": $n" . $age;
                    }
                }
            }
            $text[] = $line;
            $h      = self::extRowKey($e);
            $data[] = [
                [
                    'text'          => ($k + 1) . '. ' . (empty($e['off']) ? '✅' : '⛔') . " $icon $short",
                    'callback_data' => "/extToggle {$i}_{$k}_$h",
                ],
                [
                    'text'          => '✏️',
                    'callback_data' => "/extRename {$i}_{$k}_$h",
                ],
                [
                    'text'          => '🗑',
                    'callback_data' => "/extDel {$i}_{$k}_$h",
                ],
            ];
        }
        $data[] = [
            [
                'text'          => '🔗 ' . $this->i18n('add external link'),
                'callback_data' => "/extAdd {$i} link",
            ],
        ];
        $data[] = [
            [
                'text'          => '📥 ' . $this->i18n('add external subscription'),
                'callback_data' => "/extAdd {$i} sub",
            ],
        ];
        $data[] = [
            [
                'text'          => $this->t('🕵️ User-Agent загрузки: ', '🕵️ Fetch User-Agent: ') . mb_strimwidth($this->extSubUserAgent(), 0, 30, '…'),
                'callback_data' => "/extUA {$i}",
            ],
        ];
        $data[] = $this->menuHelpButton('ext', (string) $i);
        $data[] = [
            [
                'text'          => $this->i18n('back'),
                'callback_data' => "/userXr $i",
            ],
        ];
        $data = $this->xrayIdentityButtons($data, $xray);
        $this->update(
            $this->input['chat'],
            $this->input['message_id'],
            implode("\n", $text),
            $data,
        );
    }

    // Prompt the admin for a share link (kind=link) or remote subscription URL
    // (kind=sub); the reply is captured and routed to extAddSave().
    public function extAddPrompt($i, $kind)
    {
        $kind = $kind === 'sub' ? 'sub' : 'link';
        $r    = $this->send(
            $this->input['chat'],
            "@{$this->input['username']} " . $this->i18n($kind === 'sub' ? 'enter external subscription' : 'enter external link'),
            $this->input['message_id'],
            reply: $this->i18n($kind === 'sub' ? 'enter external subscription' : 'enter external link'),
        );
        $this->stashReply($r, [
            'start_message'  => $this->input['message_id'],
            'start_callback' => $this->input['callback_id'],
            'callback'       => 'extAddSave',
            'args'           => [$i, $kind],
        ]);
    }

    public const EXT_SUB_USER_AGENT = 'v2rayNG/1.8.5';

    // Готовые User-Agent для внешних подписок. Каждый получает в
    // распространённых панелях (3x-ui, Marzban, Remnawave) список ссылок —
    // единственное, что бот умеет разбирать. Версии v2rayNG, v2rayN и Happ
    // намеренно старые: Marzban новым версиям (v2rayNG 1.8.18+, v2rayN 6.40+,
    // Happ 1.63.1+) отдаёт JSON-конфиг, если владелец включил такой режим.
    // Клиенты Clash/Mihomo, Stash и sing-box (SFA, SFI, Karing, HiddifyNext)
    // получают YAML/JSON — в список не входят.
    public const EXT_SUB_USER_AGENT_PRESETS = [
        'v2rayNG/1.8.5' => ['ru' => 'по умолчанию: старая версия v2rayNG, список ссылок почти в любой панели',
            'en' => 'default: an old v2rayNG version, a list of links from almost any panel'],
        'v2rayN/6.31'   => ['ru' => 'v2rayN для Windows до 6.40: список ссылок и там, где новым версиям отдают JSON',
            'en' => 'v2rayN for Windows before 6.40: a list of links even where newer versions get JSON'],
        'Happ/1.63.0'   => ['ru' => 'для сервисов, которые пускают только Happ; версия до 1.63.1 получает список ссылок',
            'en' => 'for services that let in only Happ; a version before 1.63.1 gets a list of links'],
        'Streisand'     => ['ru' => 'для сервисов, которые пускают только Streisand (iOS, macOS)',
            'en' => 'for services that let in only Streisand (iOS, macOS)'],
        'Shadowrocket'  => ['ru' => 'для сервисов, которые пускают только Shadowrocket (iOS)',
            'en' => 'for services that let in only Shadowrocket (iOS)'],
    ];

    // Список готовых значений для сообщения и справки: каждое в <code>, чтобы
    // в Telegram его можно было скопировать нажатием.
    public function extSubUserAgentPresetLines(): array
    {
        $lines = [];
        foreach (self::EXT_SUB_USER_AGENT_PRESETS as $ua => $note) {
            $lines[] = '<code>' . self::esc($ua) . '</code> — ' . self::esc($note[$this->language === 'ru' ? 'ru' : 'en']);
        }
        return $lines;
    }

    // User-Agent, с которым бот забирает внешние подписки. Провайдеры отдают
    // разное содержимое разным клиентам, поэтому значение настраивается;
    // оно общее для всех подписок.
    public function extSubUserAgent(): string
    {
        $ua = ($this->getPacConf() ?: [])['extsub_user_agent'] ?? '';
        return is_string($ua) && self::extSubUserAgentValid($ua) ? $ua : self::EXT_SUB_USER_AGENT;
    }

    // Только печатные ASCII: перевод строки в значении дописал бы в запрос
    // чужие заголовки.
    public static function extSubUserAgentValid(string $ua): bool
    {
        return (bool) preg_match('~^[\x21-\x7e][\x20-\x7e]{0,199}$~D', $ua);
    }

    public function extUAPrompt($i)
    {
        $r = $this->send(
            $this->input['chat'],
            "@{$this->input['username']} " . $this->i18n('enter ext user agent')
                . "\n<code>" . self::esc($this->extSubUserAgent()) . '</code>'
                . "\n\n" . $this->t('Готовые значения — нажмите, чтобы скопировать, и отправьте ответом:', 'Ready values: tap to copy and send as a reply:')
                . "\n" . implode("\n", $this->extSubUserAgentPresetLines())
                . "\n\n" . $this->t('Не подходят Clash, Mihomo, Stash, sing-box (SFA, SFI), Karing и HiddifyNext: им сервисы отдают готовый конфиг, а боту нужен список ссылок. Подробнее — в справке.',
                    'Clash, Mihomo, Stash, sing-box (SFA, SFI), Karing and HiddifyNext do not fit: services give them a ready config, while the bot needs a list of links. Details are in Help.'),
            $this->input['message_id'],
            reply: self::EXT_SUB_USER_AGENT,
        );
        $this->stashReply($r, [
            'start_message' => $this->input['message_id'],
            'callback'      => 'extUASave',
            'args'          => [$i],
        ]);
    }

    public function extUASave($text, $i)
    {
        $ua = trim((string) $text);
        if ($ua === '-' || $ua === self::EXT_SUB_USER_AGENT) {
            $this->pacConfUpdate(function (&$conf) {
                unset($conf['extsub_user_agent']);
            });
        } elseif (self::extSubUserAgentValid($ua)) {
            $this->pacConfUpdate(function (&$conf) use ($ua) {
                $conf['extsub_user_agent'] = $ua;
            });
        } else {
            $this->extUser($i, '⚠️ ' . $this->i18n('ext user agent invalid'));
            return;
        }
        // С новым User-Agent провайдер может отдать другой состав узлов:
        // сразу перечитываем подписки этого пользователя, чтобы результат был
        // виден в меню (остальные обновит cron в течение 5 минут).
        $client = $this->getXray()['inbounds'][0]['settings']['clients'][$i] ?? [];
        foreach (array_unique(array_map(fn($e) => trim((string) ($e['value'] ?? '')),
            array_filter($client['ext'] ?? [], fn($e) => ($e['kind'] ?? '') === 'sub' && empty($e['off'])))) as $url) {
            if ($url !== '') {
                $this->refreshExtSubOne($url);
            }
        }
        $this->extUser($i, '✅ User-Agent: <code>' . self::esc($this->extSubUserAgent()) . '</code>');
    }

    public function extAddSave($text, $i, $kind)
    {
        $kind  = $kind === 'sub' ? 'sub' : 'link';
        // Одно сообщение может нести несколько ссылок — по одной на строку.
        // Раньше многострочный ввод сохранялся одной строкой ext и попадал в
        // подписку как есть, вместе с любым мусором после первой ссылки.
        $lines = array_values(array_filter(array_map('trim', preg_split('~\R~u', (string) $text)), fn($l) => $l !== ''));
        $add   = [];
        $bad   = 0;
        foreach ($lines as $value) {
            // link: a known-scheme share link; sub: an HTTPS URL (no plaintext
            // http, so the remote provider's configs never traverse the network
            // in clear) with a host and without spaces.
            $valid = $kind === 'sub'
                ? (bool) preg_match('~^https://[^\s/?#]+[^\s]*$~iD', $value) && strlen($value) <= 2048
                : $this->isKnownShareLink($value) && strlen($value) <= 8192;
            if ($valid) {
                $add[$value] = true;
            } else {
                $bad++;
            }
        }
        $result = $add ? $this->extUpdate(function (&$c) use ($i, $kind, $add) {
            if (!$this->xrayClientMatches((int) $i) || !isset($c['inbounds'][0]['settings']['clients'][$i])) {
                return null;
            }
            $have = [];
            foreach ($c['inbounds'][0]['settings']['clients'][$i]['ext'] ?? [] as $e) {
                $have[($e['kind'] ?? 'link') . "\n" . trim((string) ($e['value'] ?? ''))] = true;
            }
            $added = 0;
            foreach (array_keys($add) as $value) {
                if (isset($have["$kind\n$value"])) {
                    continue; // дубль уже есть в списке
                }
                $c['inbounds'][0]['settings']['clients'][$i]['ext'][] = [
                    'kind'   => $kind,
                    'value'  => $value,
                    'remark' => '',
                    'off'    => 0,
                ];
                $added++;
            }
            return $added ?: null;
        }) : null;
        $added = (int) $result;
        // Populate the cache now so the node shows up on the next
        // subscription request without waiting for the cron tick.
        if ($kind === 'sub' && $added) {
            foreach (array_keys($add) as $value) {
                $this->refreshExtSubOne($value);
            }
        }
        $notice = [];
        if ($added) {
            $notice[] = '✅ ' . $this->t('Добавлено: ', 'Added: ') . $added;
        }
        if (count($add) > $added) {
            $notice[] = 'ℹ️ ' . $this->t('Уже были в списке: ', 'Already in the list: ') . (count($add) - $added);
        }
        if ($bad || !$lines) {
            $notice[] = '⚠️ ' . ($kind === 'sub'
                ? $this->t('Не принято: нужен адрес https://… без пробелов (обычный http не допускается).', 'Not accepted: an https://… address without spaces is needed (plain http is not allowed).')
                : $this->t('Не принято: нужна ссылка vless://, vmess://, trojan://, ss://, ssr://, hysteria2://, hy2://, tuic://, wireguard://, anytls://, snell:// или socks://.',
                    'Not accepted: a vless://, vmess://, trojan://, ss://, ssr://, hysteria2://, hy2://, tuic://, wireguard://, anytls://, snell:// or socks:// link is needed.'))
                . ($bad ? ' (' . $bad . ')' : '');
        }
        $this->extUser($i, implode("\n", $notice));
    }

    public function extRename($i, $k, string $h = '')
    {
        $c = $this->getXray();
        if (!$this->extRowMatches($c, $i, $k, $h)) {
            $this->extUser($i, $this->extStaleNotice());
            return;
        }
        $r = $this->send(
            $this->input['chat'],
            "@{$this->input['username']} " . $this->i18n('enter remark'),
            $this->input['message_id'],
            reply: $this->i18n('enter remark'),
        );
        $this->stashReply($r, [
            'start_message'  => $this->input['message_id'],
            'start_callback' => $this->input['callback_id'],
            'callback'       => 'extRenameSave',
            'args'           => [$i, $k, $h],
        ]);
    }

    public function extRenameSave($text, $i, $k, string $h = '')
    {
        // Имя уходит в #remark ссылки (rawurlencode) и в кнопку меню: обрезаем
        // управляющие символы и длину. 0 — вернуть исходное имя ссылки.
        $remark = trim(preg_replace('~[\p{C}]+~u', ' ', (string) $text) ?? '');
        $remark = $remark === '0' ? '' : mb_substr($remark, 0, 64);
        $done   = $this->extUpdate(function (&$c) use ($i, $k, $h, $remark) {
            if (!$this->extRowMatches($c, $i, $k, $h)) {
                return null;
            }
            $c['inbounds'][0]['settings']['clients'][$i]['ext'][$k]['remark'] = $remark;
            return true;
        });
        $this->extUser($i, $done ? '' : $this->extStaleNotice());
    }

    public function extToggle($i, $k, string $h = '')
    {
        $done = $this->extUpdate(function (&$c) use ($i, $k, $h) {
            if (!$this->extRowMatches($c, $i, $k, $h)) {
                return null;
            }
            $e = &$c['inbounds'][0]['settings']['clients'][$i]['ext'][$k];
            $e['off'] = empty($e['off']) ? 1 : 0;
            unset($e);
            return true;
        });
        $this->extUser($i, $done ? '' : $this->extStaleNotice());
    }

    public function extDel($i, $k, string $h = '')
    {
        $done = $this->extUpdate(function (&$c) use ($i, $k, $h) {
            if (!$this->extRowMatches($c, $i, $k, $h)) {
                return null;
            }
            array_splice($c['inbounds'][0]['settings']['clients'][$i]['ext'], (int) $k, 1);
            return true;
        });
        $this->extUser($i, $done ? '' : $this->extStaleNotice());
    }

    private function extStaleNotice(): string
    {
        return '⚠️ ' . $this->t('Список изменился — ничего не сделано. Проверьте его и нажмите кнопку ещё раз.',
            'The list has changed, nothing was done. Check it and tap the button again.');
    }

    // Per-user relay subscriptions: pick a relay, then relaySub() renders that
    // relay's full link set (one screen per relay keeps each message well under
    // the 4096-char editMessageText limit even with many relays).
    public function userRelay($i)
    {
        $xray = $this->getXray();
        $c    = $xray['inbounds'][0]['settings']['clients'][$i] ?? null;
        $pac  = $this->getPacConf();
        if ($c === null) {
            $this->userXr($i);
            return;
        }
        $relays = array_filter($pac['relays'] ?? [], fn($e) => $this->relayForSubscription($e));

        // Имя пользователя приходит из ввода и уходит в parse_mode=HTML:
        // «&» или «<» в нём роняли editMessageText в 400.
        $text[] = "Menu -> " . $this->i18n('xray') . " -> " . self::esc($c['email']) . " -> " . $this->i18n('relay subscriptions');
        $text[] = $this->t(
            'Та же подписка этого пользователя, но клиент подключается через выбранный relay: бот меняет только адрес и порт сервера, ключи, SNI и маршруты остаются прежними. Выберите relay, затем способ импорта.',
            "The same subscription of this user, but the client connects through the chosen relay: the bot changes only the server address and port; keys, SNI and routes stay the same. Pick a relay, then the import method.");
        if (!$relays) {
            $text[] = "\n" . $this->t('Нет relay с адресом для подписок. Задайте его в меню Vless → relay.', 'No relay with an address for subscriptions. Set one in the Vless menu → relay.');
        }

        $data   = [];
        $health = $this->readRelayHealth(); // read once for the whole list
        foreach ($relays as $name => $relay) {
            $name = (string) $name;
            $hl   = !empty($relay['address']) ? $this->relayHealthLabel($name, false, $health) : '';
            $data[] = [
                [
                    'text'          => "🔗 $name: " . mb_strimwidth((string) (($relay['address'] ?? '') ?: ($relay['awg_address'] ?? '') ?: $this->t('протоколы-модули', 'module protocols')), 0, 40, '…') . ($hl !== '' ? "  $hl" : ''),
                    'callback_data' => "/relaySub {$i}_{$name}",
                ],
            ];
        }
        $data[] = $this->menuHelpButton('relay_user', (string) $i);
        $data[] = [
            [
                'text'          => $this->i18n('back'),
                'callback_data' => "/userXr $i",
            ],
        ];
        $this->update(
            $this->input['chat'],
            $this->input['message_id'],
            implode("\n", $text),
            $data,
        );
    }

    // Без сертификата бот выдаёт адреса подписок с http://: токен подписки и
    // первый запрос идут открытым текстом (nginx на 80 только переадресует).
    public function subPlaintextWarning(): string
    {
        return '⚠️ ' . $this->t(
            'Нет TLS-сертификата: адреса подписок начинаются с http://, и токен подписки уходит в сеть открытым текстом. Задайте домен и выпустите сертификат (меню SSL), затем выдайте пользователям новые ссылки.',
            'No TLS certificate: subscription addresses start with http://, and the subscription token travels over the network in plain text. Set a domain and issue a certificate (SSL menu), then give users new links.');
    }

    // Что именно пойдёт через relay в его подписке: по строке на канал.
    // VLESS и прокси awg без канала остаются на адресе сервера; протокол-модуль
    // без канала в relay-подписку не входит вовсе (appendXrayProtocols).
    public function relaySubscriptionRoutes(array $relay): array
    {
        $via  = '→ ';
        $out  = [];
        $out[] = 'VLESS: ' . (!empty($relay['address'])
            ? $via . '<code>' . self::esc($this->relayChannelSummary($relay, 'vless')) . '</code>'
            : $this->t('напрямую на сервер (у relay нет адреса VLESS)', 'directly to the server (the relay has no VLESS address)'));
        if (!empty($relay['awg_address'])) {
            $out[] = $this->t('WG/AWG (прокси awg в шаблоне Mihomo): ', 'WG/AWG (awg proxy in a Mihomo template): ')
                . $via . '<code>' . self::esc($this->relayChannelSummary($relay, 'wg')) . '</code>';
        }
        $modules = [];
        foreach (ManagedProtocol::NAMES as $protocol => $label) {
            if (in_array($protocol, ['snolc', 'masque'], true)) {
                continue; // в общие подписки не входят (отдельные профили)
            }
            if (!empty($relay[$protocol . '_address']) && !empty($relay[$protocol . '_port'])) {
                $modules[] = $label . ' ' . $via . '<code>' . self::esc($relay[$protocol . '_address'] . ':' . $relay[$protocol . '_port']) . '</code>';
            }
        }
        $out[] = $this->t('Протоколы-модули (sing-box, Mihomo): ', 'Module protocols (sing-box, Mihomo): ')
            . ($modules ? implode(', ', $modules) : $this->t('не входят — у relay нет их каналов', 'not included, the relay has no channels for them'));
        return $out;
    }

    // Full link set for one relay, mirroring userXr's client links so every
    // client gets its native one-tap import (the deep-link redirects in
    // subscription()'s r= block are relay-aware), plus copyable content URLs for
    // manual subscription paste. All links carry 'relay' => <name>, so the
    // served config has only its endpoint address+port swapped to the relay.
    public function relaySub($i, $name)
    {
        $xray  = $this->getXray();
        $c     = $xray['inbounds'][0]['settings']['clients'][$i] ?? null;
        $pac   = $this->getPacConf();
        $relay = $pac['relays'][$name] ?? null;
        if ($c === null || !$this->relayForSubscription($relay)) {
            $this->userRelay($i);
            return;
        }
        $domain = $this->getDomain(($pac['transport'] ?? '') != 'Reality');
        $scheme = empty($this->nginxGetTypeCert()) ? 'http' : 'https';
        $hash   = $this->getHashBot();
        $email  = $c['email'];
        $stok   = $this->sidOf($c); // subscription locator (not the credential)
        // Имя relay задаёт админ, а отсюда оно уходит в query-string ссылки:
        // пробел или & в имени резали параметр (и всё, что за ним) — клиент
        // импортировал подписку origin вместо relay.
        $text[] = "Menu -> " . $this->i18n('xray') . " -> " . self::esc($email)
            . " -> " . $this->i18n('relay subscriptions') . " -> <b>" . self::esc($name) . "</b>";
        if (!empty($relay['address']) && ($hl = $this->relayHealthLabel((string) $name, true)) !== '') {
            $text[] = $this->i18n('relay health') . ": $hl";
        }
        array_push($text, ...$this->relaySubscriptionRoutes($relay));
        if ($scheme === 'http') {
            $text[] = $this->subPlaintextWarning();
        }
        $text[] = '';

        array_push($text, ...$this->subscriptionImportLinks("$scheme://{$domain}/pac$hash", $stok, $email, (string) $name));

        // Raw content URLs for clients where a subscription URL is pasted
        // manually. 'vl' is the base64 vless:// share-link list for v2rayNG &
        // other classic xray clients (paste into subscription settings) — the
        // JSON 'xray' format below imports as a custom config (raw JSON), so
        // v2rayNG users should use the v2rayNG line.
        $text[] = '';
        foreach ([
            'vl' => 'Happ / v2rayNG (base64)',
            's'  => 'xray (json)',
            'si' => 'sing-box',
            'cl' => 'Mihomo YAML',
            'clj' => 'Mihomo JSON',
        ] as $t => $label) {
            $url = "$scheme://{$domain}/pac$hash/" . base64_encode(serialize([
                'h'     => $hash,
                't'     => $t,
                's'     => $stok,
                'relay' => (string) $name,
            ]));
            $text[] = "$label: <pre><code>$url</code></pre>";
        }

        $data[] = $this->menuHelpButton('relay_user', (string) $i);
        $data[] = [
            [
                'text'          => $this->i18n('back'),
                'callback_data' => "/userRelay $i",
            ],
        ];
        $this->update(
            $this->input['chat'],
            $this->input['message_id'],
            implode("\n", $text),
            $data ?: false,
        );
    }

    public function hwidUser($i, $page = 0)
    {
        $entered = false;
        $result = $this->withLock('xray', function () use ($i, $page, &$entered) {
            $entered = true;
            return $this->hwidUserLocked($i, $page);
        });
        if (!$entered) throw new RuntimeException($this->t('Не удалось заблокировать Xray', 'Could not lock Xray'));
        return $result;
    }

    private function hwidUserLocked($i, $page = 0)
    {
        if (!$this->xrayClientMatches((int) $i)) return $this->staleXrayAction();
        $xray   = $this->getXray();
        $client = $xray['inbounds'][0]['settings']['clients'][$i];
        $pac    = $this->getPacConf();

        $devices = $this->getHwidDevicesByUser($client['id']);
        $scope   = $this->getHwidTokenScope($i);
        // Сброс scope перед перегенерацией токенов страницы — тоже должен
        // сохраниться (сессия закрыта с диспатча).
        $this->sessionApply(function () use ($scope) {
            if (!isset($_SESSION['hwidTokens'])) {
                $_SESSION['hwidTokens'] = [];
            }
            $_SESSION['hwidTokens'][$scope] = [];
        });
        uasort($devices, fn($a, $b) => ($b['time'] ?? 0) <=> ($a['time'] ?? 0));
        $hwids        = array_keys($devices);
        $perPage      = max(1, $this->limit ?: 5);
        $total        = count($hwids);
        $pages        = max(1, (int) ceil($total / $perPage));
        $page         = min(max((int) $page, 0), $pages - 1);
        $hwidsPage    = array_slice($hwids, $page * $perPage, $perPage);
        $defaultHwid  = max(1, (int) (($pac['hwid_device_count'] ?? 0) ?: 1));

        $text[] = "Menu -> " . $this->i18n('xray') . " -> {$client['email']} -> " . $this->i18n('hwid devices');
        $text[] = $this->i18n('hwid notice');
        if (empty($pac['hwid_limit_enabled'])) {
            $status = $this->i18n('off');
        } elseif (!empty($client['hwid_disabled'])) {
            $status = $this->i18n('off');
        } elseif (!empty($client['hwid_limit'])) {
            $status = (int) $client['hwid_limit'];
        } else {
            $status = "default($defaultHwid)";
        }
        $text[] = $this->i18n('hwid limit') . ': ' . $status;
        $text[] = $this->i18n('hwid devices') . ': ' . $total;

        $data[] = [
            [
                'text'          => $this->i18n(!empty($client['hwid_disabled']) ? 'off' : 'on'),
                'callback_data' => "/hwidUserToggle $i",
            ],
        ];
        $data[] = [
            [
                'text'          => $this->i18n('set hwid devices count'),
                'callback_data' => "/setHwidUserLimit $i",
            ],
        ];
        if (!empty($client['hwid_limit'])) {
            $data[] = [
                [
                    'text'          => $this->i18n('use default hwid limit'),
                    'callback_data' => "/hwidUserDefault $i",
                ],
            ];
        }

        if ($total == 0) {
            $text[] = $this->i18n('no devices');
        }

        foreach ($hwidsPage as $index => $hwid) {
            $info    = $devices[$hwid];
            $number  = $page * $perPage + $index + 1;
            $details = array_filter([
                $info['device_os'] ?? '',
                $info['os_version'] ?? '',
                $info['device_model'] ?? '',
            ], fn($v) => $v !== '');
            $line = $number . '. <code>' . htmlspecialchars($hwid, ENT_HTML5, 'UTF-8') . '</code>';
            if (!empty($details)) {
                $line .= ' - ' . htmlspecialchars(implode(' ', $details), ENT_HTML5, 'UTF-8');
            }
            if (!empty($info['time'])) {
                $line .= ' (' . date('d.m.Y H:i', $info['time']) . ')';
            }
            $text[] = $line;
            if (!empty($info['user_agent'])) {
                $text[] = 'UA: ' . htmlspecialchars($info['user_agent'], ENT_HTML5, 'UTF-8');
            }
            $token = $this->rememberHwidToken($scope, $hwid);
            $data[] = [
                [
                    'text'          => '🗑 ' . $number,
                    'callback_data' => "/hwidUserDel {$i}_{$page} $token",
                ],
            ];
        }

        if ($pages > 1) {
            $data[] = [
                [
                    'text'          => '<<',
                    'callback_data' => "/hwidUser {$i}_" . ($page - 1 >= 0 ? $page - 1 : $pages - 1),
                ],
                [
                    'text'          => ($page + 1) . '/' . $pages,
                    'callback_data' => "/hwidUser {$i}_$page",
                ],
                [
                    'text'          => '>>',
                    'callback_data' => "/hwidUser {$i}_" . (($page + 1) % $pages),
                ],
            ];
        }

        $data[] = [
            [
                'text'          => $this->i18n('back'),
                'callback_data' => "/userXr $i",
            ],
        ];

        $data = $this->xrayIdentityButtons($data ?: [], $xray);
        $this->update(
            $this->input['chat'],
            $this->input['message_id'],
            implode("\n", $text ?: ['...']),
            $data ?: false,
        );
    }

    public function hwidUserToggle($i)
    {
        $entered = false;
        $result = $this->withLock('xray', function () use ($i, &$entered) {
            $entered = true;
            return $this->hwidUserToggleLocked($i);
        });
        if (!$entered) throw new RuntimeException($this->t('Не удалось заблокировать Xray', 'Could not lock Xray'));
        return $result;
    }

    private function hwidUserToggleLocked($i)
    {
        if (!$this->xrayClientMatches((int) $i)) return $this->staleXrayAction();
        $xray = $this->getXray();
        if (!empty($xray['inbounds'][0]['settings']['clients'][$i]['hwid_disabled'])) {
            unset($xray['inbounds'][0]['settings']['clients'][$i]['hwid_disabled']);
        } else {
            $xray['inbounds'][0]['settings']['clients'][$i]['hwid_disabled'] = 1;
        }
        $this->saveXray($xray);
        $this->answer($this->input['callback_id'], $this->i18n('hwid notice'), true);
        $this->hwidUserLocked($i);
    }

