    public function saveTrafficXr($gb, $i)
    {
        $entered = false;
        $result = $this->withLock('xray', function () use ($gb, $i, &$entered) {
            $entered = true;
            return $this->saveTrafficXrLocked($gb, $i);
        });
        if (!$entered) throw new RuntimeException($this->t('Не удалось заблокировать Xray', 'Could not lock Xray'));
        return $result;
    }

    private function saveTrafficXrLocked($gb, $i)
    {
        if (!$this->xrayClientMatches((int) $i)) return $this->staleXrayAction();
        $gb = (float) str_replace(',', '.', trim((string) $gb));
        $this->writeTrafficXrLocked($gb > 0 ? (int) round($gb * 1024 ** 3) : null, $i);
    }

    private function writeTrafficXrLocked(?int $limit, $i): void
    {
        $x = $this->getXray();
        if (!isset($x['inbounds'][0]['settings']['clients'][$i])) { $this->xray(); return; }
        $needsRestart = false;
        if ($limit !== null) {
            $x['inbounds'][0]['settings']['clients'][$i]['traffic'] = $limit;
            // Raising the limit above current usage lifts this client's quota ban.
            if (!empty($x['inbounds'][0]['settings']['clients'][$i]['traffic_off'])
                && !$this->xrayQuotaUnavailableOrExhausted($x['inbounds'][0]['settings']['clients'][$i], $i)) {
                $x = $this->reenableTrafficClients($x, $i);
                $needsRestart = true;
            }
        } else {
            unset($x['inbounds'][0]['settings']['clients'][$i]['traffic']);
            // Clearing the limit also lifts a prior quota ban; restoring the id
            // needs a live restart for xray to accept connections again.
            if (!empty($x['inbounds'][0]['settings']['clients'][$i]['traffic_off'])) {
                $x = $this->reenableTrafficClients($x, $i);
                $needsRestart = true;
            }
        }
        // Persist via restartXray so the stats:{} object is normalized (raw
        // json_encode turns {} into [] and xray rejects it). norestart unless we
        // re-enabled a client — the limit value itself is bot-side only.
        if ($this->restartXray($x, !$needsRestart) === false) throw new RuntimeException($this->t('Не удалось применить настройки Xray', 'Could not apply Xray settings'));
        $this->userXrLocked($i);
    }

    public function hwidUserDel($i, $page, $hwid)
    {
        $entered = false;
        $result = $this->withLock('xray', function () use ($i, $page, $hwid, &$entered) {
            $entered = true;
            return $this->hwidUserDelLocked($i, $page, $hwid);
        });
        if (!$entered) throw new RuntimeException($this->t('Не удалось заблокировать Xray', 'Could not lock Xray'));
        return $result;
    }

    private function hwidUserDelLocked($i, $page, $hwid)
    {
        if (!$this->xrayClientMatches((int) $i)) return $this->staleXrayAction();
        $xray = $this->getXray();
        $uid    = $xray['inbounds'][0]['settings']['clients'][$i]['id'];
        $scope  = $this->getHwidTokenScope($i);
        $decoded = $this->resolveHwidToken($scope, $hwid);
        if ($decoded !== '') {
            $this->deleteHwidDevice($uid, $decoded);
        }
        $this->hwidUserLocked($i, $page);
    }

    public function getDomain($cdn = false)
    {
        $c = $this->getPacConf();
        if ($cdn && !empty($c['linkdomain'])) {
            return $c['linkdomain'];
        }
        return ($c['domain'] ?? '') ?: $this->ip;
    }

    // Хост, из которого строятся все ссылки подписки (страница sub(), URL
    // rule-provider'ов, DoH-эндпоинт в ~dns~). ?cdn= раньше подставлялся как
    // есть: адрес уезжал и в HTML-атрибут href (кавычка ломала страницу), и в
    // конфиг клиента — тот начинал тянуть rule-set'ы и DNS с чужого хоста.
    // Пускаем только валидный хостнейм (та же проверка, что для nginx), иначе
    // ведём себя так, будто параметра не было.
    public function subDomain(array $pac): string
    {
        // Белый список, а не только синтаксическая проверка (аудит 2026-08-18).
        // Домен отсюда уезжает в ~domain~/~dns~, в rule-providers mihomo, в
        // createRuleSet() sing-box и в ссылку самообновления подписки. Пока
        // достаточно было «валидного хостнейма», обладатель чужого sub-URL мог
        // переслать жертве тот же URL с &cdn=evil.tld — и её клиент начинал
        // тянуть правила, DoH и обновление подписки с хоста атакующего, то есть
        // отдавал ему управление своей маршрутизацией и постоянный канал
        // деанона. Разрешаем ровно то, что настроено админом.
        $allowed = array_merge(
            $this->dnsDomains($pac),                       // domain + domain_aliases
            [(string) ($pac['linkdomain'] ?? '')],          // cdn-домен из настроек
            [(string) ($this->ip ?? '')]
        );
        $allowed = array_filter(array_map('strtolower', array_map('trim', $allowed)), 'strlen');

        $cdn = strtolower(trim((string) ($_GET['cdn'] ?? '')));
        if ($cdn !== '' && $this->isHostname($cdn) && in_array($cdn, $allowed, true)) {
            return $cdn;
        }
        // SERVER_NAME приходит из Host запроса — та же мерка и тот же список.
        $host = strtolower(trim((string) ($_SERVER['SERVER_NAME'] ?? '')));
        if ($host !== '' && $this->isHostname($host) && in_array($host, $allowed, true)) {
            return $host;
        }
        return $this->getDomain(($pac['transport'] ?? '') != 'Reality');
    }

    public function sub()
    {
        $this->subSecurityHeaders();
        $this->normalizeSubGet();
        // No token backfill here: this is a public GET endpoint, so we avoid
        // writing xray.json on the hot path (concurrent requests). sidOf() falls
        // back to the uuid when a subtoken is absent; cron/userXr backfill tokens.
        $xr     = $this->getXray();
        // Конфиг нечитаем (файла нет, битый JSON) — findClientBySid(array $xr, …)
        // упал бы с TypeError, то есть 500 вместо честного ответа.
        if (!is_array($xr)) {
            $this->subNotFound('Subscription temporarily unavailable.');
        }
        $pac    = $this->getPacConf();
        $this->subRateLimit($_GET['id'] ?? '');
        // Resolve by subtoken (preferred) or, for pre-subtoken links, the id.
        $k      = $this->findClientBySid($xr, $_GET['id'] ?? '', !empty($pac['subtoken_strict']));
        $client = $k === null ? null : $xr['inbounds'][0]['settings']['clients'][$k];
        // Missing/disabled id: clean 404 instead of rendering the page with
        // undefined fields (which would warn and break the body).
        if ($client === null || !empty($client['off'])
            || ((int) ($client['time'] ?? 0) > 0 && $client['time'] <= time())
            || $this->xrayQuotaUnavailableOrExhausted($client, $k)) {
            // Ведро промахов — см. subscription(): ключ основного ведра
            // содержит sid, поэтому перебор им не ограничивался.
            $this->subRateLimit('', 'miss');
            $this->subNotFound();
        }
        $linksOnly = $this->subscriptionDeviceLimit($client, $pac) > 0 && $this->requestHwid() === '' && $this->isBrowserRequest();
        if (!$this->processHwidRequest($client, $linksOnly)) {
            exit;
        }
        $domain = $this->subDomain($pac);
        $scheme = empty($this->nginxGetTypeCert()) ? 'http' : 'https';
        $hash = $this->getHashBot();
        $stok = $this->sidOf($client);
        // The optional PHP template receives raw connection profiles. A browser
        // without a registered device may see only links back to the guarded endpoints.
        if ($linksOnly) {
            header('Content-Type: text/html; charset=utf-8');
            echo '<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>',
                self::esc($client['email']), '</title><h1>', self::esc($client['email']), '</h1>',
                implode('<br>', $this->subscriptionImportLinks("$scheme://{$domain}/pac$hash", $stok, (string) $client['email']));
            return;
        }
        try { $st = $this->getXrayStats(); }
        catch (XrayStatsUnavailable $error) { $st = null; }
        $email  = $client['email'];
        $expire = $client['time'] ?? '';
        $suburl   = "<a href='$scheme://{$domain}/pac$hash/sub?id={$stok}'>subscription</a>";
        $download = $st === null ? $this->t('неизвестно', 'unknown') : $this->getBytes(($st['users'][$k]['global']['download'] ?? 0) + ($st['users'][$k]['session']['download'] ?? 0));
        $upload   = $st === null ? $this->t('неизвестно', 'unknown') : $this->getBytes(($st['users'][$k]['global']['upload'] ?? 0) + ($st['users'][$k]['session']['upload'] ?? 0));
        $singbox  = "$scheme://{$domain}/pac$hash/" . base64_encode(serialize([
            'h' => $hash,
            't' => 'si',
            's' => $stok,
        ]));
        $xray = "$scheme://{$domain}/pac$hash/" . base64_encode(serialize([
            'h' => $hash,
            't' => 's',
            's' => $stok,
        ]));
        $clash = "$scheme://{$domain}/pac$hash/" . base64_encode(serialize([
            'h' => $hash,
            't' => 'cl',
            's' => $stok,
        ]));
        $vless   = $this->linkXray($k);
        $happ = $this->subscriptionImportUrl('happ', "$scheme://{$domain}/pac$hash", ['h' => $hash, 's' => $stok], $email);
        $_GET['s'] = $stok;
        foreach ([
          'xray'    => 's',
          'singbox' => 'si',
          'clash'   => 'cl'
        ] as $k     => $v) {
            $_GET['t'] = $v;
            $configs[$k] = $this->subscription(1);
        }
        require __DIR__ . '/subscription.php';
    }

    // Client-side Reality settings block for xray (case 's') configs. Base
    // fields use ~placeholders~ filled by replaceTags(); spiderX (item 4) and
    // mldsa65Verify (item 2) are appended only when configured, so a config with
    // nothing tuned is byte-identical to before.
    public function realityClientSettings($fingerprint, array $pac): array
    {
        $rs = [
            "serverName"  => '~server_name~',
            "fingerprint" => $fingerprint,
            "publicKey"   => '~public_key~',
            "shortId"     => '~short_id~',
        ];
        $spx = $this->normalizeSpiderXValue((string) ($pac['reality']['spiderX'] ?? ''));
        if ($spx !== '' && $spx !== '/') {
            $rs['spiderX'] = $spx;
        }
        if ($this->mldsaReady($pac)) {
            $rs['mldsa65Verify'] = $pac['reality']['mldsa65Verify'];
        }
        return $rs;
    }

    // sockopt для inbound'ов, которые слушают ЗА nginx (xhttp, trojan-grpc,
    // websocket). Без него xray видит источником каждого соединения сам nginx
    // (10.10.0.2), а не клиента, потому что TLS терминирует nginx и никакого
    // PROXY-протокола до xray не доходит (он есть только у Reality). Ломается
    // сразу три вещи: `from <ip>` в /logs/xray у всех клиентов одинаковый →
    // журнал подключений (recordConnLog) бесполезен, ip_limit никогда не
    // срабатывает (у email всегда ровно один IP), а сам xray на КАЖДЫЙ запрос
    // пишет warning «received "X-Forwarded-For" … but "sockopt.
    // trustedXForwardedFor" is not configured» — в packet-up это до 30 строк в
    // секунду на клиента, лог пухнет на ровном месте.
    //
    // Значение — список ИМЁН заголовков (не адресов!): xray доверяет XFF, если
    // в запросе присутствует любой из них (common/protocol/http/headers.go,
    // ApplyTrustedXForwardedFor + headers_test.go). X-Real-IP ставит сам nginx
    // через proxy_set_header/grpc_set_header, т.е. клиент его подделать не
    // может — заголовок клиента при этом ЗАМЕЩАЕТСЯ, а не дополняется. Сам IP
    // берётся из ПЕРВОГО элемента X-Forwarded-For, поэтому в nginx он выставлен
    // в $remote_addr, а не в $proxy_add_x_forwarded_for (см. локацию /ws).
    public function nginxFrontedSockopt(): array
    {
        return ['trustedXForwardedFor' => ['X-Real-IP']];
    }

    // Единый источник правды для клиентской части XHTTP (xray-core).
    //
    // Xray собирает xhttpSettings так (infra/conf/transport_method.go, Build()):
    // если задан "extra", он парсится КАК ЦЕЛЫЙ SplitHTTPConfig и заменяет собой
    // внешний объект — из внешнего переносятся только host/path/mode. Поэтому все
    // остальные поля обязаны лежать внутри "extra", а не рядом с ним.
    //
    // Тот же самый набор уходит в vless://…&extra=<urlencoded json> — раньше в
    // ссылке лежал захардкоженный процент-энкоженный блоб, и любая правка JSON-
    // конфига молча расходилась со ссылкой. Теперь оба берут массив отсюда.
    //
    // Значения: xray-дефолты (scMaxEachPostBytes 1000000, scMinPostsIntervalMs 30,
    // xPaddingBytes 100-1000) плюс xmux с maxConcurrency 16-32. maxConnections
    // держим на 0: при обоих ненулевых Build() падает с "maxConnections cannot be
    // specified together with maxConcurrency".
    public function xhttpClientExtra(): array
    {
        return [
            "xmux" => [
                "cMaxReuseTimes"   => 0,
                "maxConcurrency"   => "16-32",
                "maxConnections"   => 0,
                "hKeepAlivePeriod" => 0,
                "hMaxRequestTimes" => "600-900",
                "hMaxReusableSecs" => "1800-3000",
            ],
            "noGRPCHeader"         => false,
            "xPaddingBytes"        => "100-1000",
            "scMaxEachPostBytes"   => 1000000,
            "scMinPostsIntervalMs" => 30,
            // Серверная опция (периодический keep-alive в stream-up); на клиенте
            // инертна, но оставлена — xray её принимает, а конфиг и ссылка должны
            // совпадать байт-в-байт с тем, что уже роздано пользователям.
            "scStreamUpServerSecs" => "20-80",
        ];
    }

    // ---- SMUX (sing-mux форк-ядра Jolymmiles/Xray-core) ---------------------
    // Мультиплексирование всех потоков клиента в ОДНО несущее TLS-соединение:
    // новый запрос не платит за хендшейк, DPI видит одну долгую сессию вместо
    // сотен коротких, серверу дешевле. Работает только на форк-ядре — апстрим
    // знает лишь свой mux.cool и несущий коннект не распознает, поэтому блок
    // уезжает клиентам ТОЛЬКО при xrayCore() === 'fork'.
    //
    // Значения дефолтов — из документации mihomo/sing-box: max-connections 3
    // (в примерах встречается 4, но комментарии рекомендуют 3), min-streams 4,
    // max-streams 0 (без лимита), padding включён.
    public static function smuxDefaults(): array
    {
        return [
            'enabled'         => 0,
            // Флаг «настройки трогали руками»: переключение ядра не должно
            // затирать пользовательские значения дефолтами.
            'configured'      => 0,
            // Форк-сервер принимает ТОЛЬКО smux и h2mux (см. SMuxConfig.Build()).
            // yamux, который есть у sing-box, он отвергает — в меню его нет.
            'protocol'        => 'smux',
            'max_connections' => 3,
            'min_streams'     => 4,
            'max_streams'     => 0,
            'padding'         => 1,
            // only-tcp понимает только mihomo; в sing-box такого поля нет.
            'only_tcp'        => 0,
            // logicalHalfClose форка (26.8.25+): off — прежнее поведение,
            // auto — договориться с сервером и молча откатиться, если он не
            // умеет, require — требовать. Дефолт off: это ровно те байты
            // несущего коннекта, что и раньше.
            'half_close'      => 'off',
            // SETTINGS_MAX_FRAME_SIZE, который сервер объявляет несущим
            // коннектам H2MUX (форк 26.9.3+). 0 — дефолт библиотеки http2
            // (1 МиБ). Настройка ЧИСТО СЕРВЕРНАЯ: в подписку не уезжает.
            'h2mux_frame'     => 0,
            'brutal'          => [
                'enabled' => 0,
                // Занижено сознательно: Brutal игнорирует сигналы перегрузки и
                // льёт ровно с заданной скоростью, поэтому ставка выше реального
                // канала = сплошные потери. Подгонять под свой канал руками.
                'up'      => '100 Mbps',
                'down'    => '100 Mbps',
            ],
        ];
    }

    // Настройки smux с подставленными дефолтами (вложенный brutal тоже).
    public function smuxSettings(?array $p = null): array
    {
        $p = $p ?? $this->getPacConf();
        $s = is_array($p['smux'] ?? null) ? $p['smux'] : [];
        $d = self::smuxDefaults();
        $s['brutal'] = (is_array($s['brutal'] ?? null) ? $s['brutal'] : []) + $d['brutal'];
        unset($d['brutal']);

        return $s + $d;
    }

    // Политика половинного закрытия потока: off | auto | require. Мусор из
    // pac.json (правка руками, чужой конфиг) приводим к off — неизвестное
    // значение SMuxConfig.Build() отвергает на СТАРТЕ, то есть ядро у клиента
    // просто не поднимется.
    public static function smuxHalfClose($v): string
    {
        $v = strtolower(trim((string) $v));

        return in_array($v, ['off', 'auto', 'require'], true) ? $v : 'off';
    }

    // Умеет ли ядро на СЕРВЕРЕ договариваться о половинном закрытии: несущий
    // коннект версии 2 и команда 4 появились в форке 26.8.25.
    //
    // Версия в пробе — это вывод `xray version` по симлинку, то есть версия
    // АКТИВНОГО ядра. Когда активен апстрим (проба молчит, откат образа,
    // расхождение симлинка и настройки) про версию ФОРКА она не говорит
    // ничего — тогда не мешаем: «неизвестно» не повод запрещать настройку, а
    // про недоступный xr и про расхождение ядер меню пишет отдельно.
    public function smuxHalfCloseReady(): bool
    {
        $probe = $this->xrayCoreProbe();
        if (empty($probe['ok']) || ($probe['active'] ?? '') !== 'fork') {
            return true;
        }
        $v = $this->getXrayVersion();

        return $v === '' || version_compare($v, '26.8.25', '>=');
    }

    // Границы SETTINGS_MAX_FRAME_SIZE из RFC 9113 §6.5.2 — ровно те же
    // H2MuxFrameSizeMin/Max, что проверяет форк (common/singmux/h2mux_server.go).
    public const SMUX_H2MUX_FRAME_MIN = 16384;
    public const SMUX_H2MUX_FRAME_MAX = 16777215;

    // Размер кадра H2MUX, приведённый к тому, что форк примет. Мусор и значения
    // вне диапазона заменяем нулём (дефолт библиотеки), а не пропускаем: такой
    // конфиг InboundSMuxConfig.Build() отвергает на СТАРТЕ — то есть xray на
    // сервере просто не поднимется, положив разом всех клиентов.
    public static function smuxFrameSize($v): int
    {
        $v = trim((string) $v);
        if (!preg_match('~^\d+$~', $v)) {
            return 0;
        }
        $n = (int) $v;

        return $n >= self::SMUX_H2MUX_FRAME_MIN && $n <= self::SMUX_H2MUX_FRAME_MAX ? $n : 0;
    }

    // Умеет ли ядро на СЕРВЕРЕ читать h2muxMaxReadFrameSize: ключ появился в
    // форке 26.9.3. Старое ядро его молча игнорирует (encoding/json пропускает
    // неизвестные поля), поэтому запрещать настройку не за что — но и молчать
    // нельзя: пользователь выставит размер и не поймёт, почему ничего не
    // изменилось. Критерий «неизвестно = не мешаем» тот же, что у half-close.
    public function smuxFrameReady(): bool
    {
        $probe = $this->xrayCoreProbe();
        if (empty($probe['ok']) || ($probe['active'] ?? '') !== 'fork') {
            return true;
        }
        $v = $this->getXrayVersion();

        return $v === '' || version_compare($v, '26.9.3', '>=');
    }

    // Минимум, ниже которого форк отвергает ставку Brutal (smuxBrutalMinBPS).
    public const SMUX_BRUTAL_MIN_BPS = 65536;

    // Ставка Brutal в байтах в секунду или null, если строка не по грамматике
    // parseSMuxRate: число и опциональная единица [K|M|G|T](b|B)ps, голое
    // число = Mbps, «b» — биты (делим на 8), «B» — байты.
    public static function smuxRateBytes($v): ?int
    {
        if (!preg_match('~^(\d+)\s?(([KMGT])?([bB])ps)?$~', trim((string) $v), $m)) {
            return null;
        }
        $rate = (int) $m[1];
        if (($m[2] ?? '') === '') {
            return intdiv($rate * 1000000, 8);
        }
        $mult = match ($m[3] ?? '') {
            'K' => 1000,
            'M' => 1000000,
            'G' => 1000000000,
            'T' => 1000000000000,
            default => 1,
        };

        return $m[4] === 'b' ? intdiv($rate * $mult, 8) : $rate * $mult;
    }

    // Полки Brutal, приведённые к грамматике форка. Мусор и слишком низкие
    // ставки заменяем дефолтом, а не пропускаем: при включённом Brutal ядро
    // отвергает такой конфиг на СТАРТЕ — то есть xray просто не поднимется.
    public static function smuxRate($v): string
    {
        $v     = trim((string) $v);
        $bytes = self::smuxRateBytes($v);
        if ($bytes !== null && $bytes >= self::SMUX_BRUTAL_MIN_BPS) {
            return $v;
        }

        return '100 Mbps';
    }

    // sing-box держит ставки брутала ЦЕЛЫМИ МЕГАБИТАМИ в up_mbps/down_mbps, а
    // не строкой «100 Mbps», как xray-форк и mihomo. Строка ему не просто не
    // нравится: конфиг отвергается целиком («unknown field "up"») и клиент не
    // импортирует подписку вовсе. smuxRate() уже нормализовал вход, поэтому
    // разбор здесь заведомо удаётся.
    public static function smuxRateMbps($v): int
    {
        $bytes = (int) self::smuxRateBytes(self::smuxRate($v));

        return max(1, (int) round($bytes * 8 / 1000000));
    }

    // Уезжает ли smux клиентам прямо сейчас: включён И ядро форковое.
    public function smuxActive(?array $p = null): bool
    {
        $p = $p ?? $this->getPacConf();

        return $this->xrayCore($p) === 'fork' && !empty($this->smuxSettings($p)['enabled']);
    }

    // Серверная часть: для самого smux в xray.json НИЧЕГО не нужно — форк ловит
    // несущее назначение sp.mux.sing-box.arpa:444 до роутинга, на любом inbound'е
    // (common/mux/server.go, singmux.IsDestination). Настраивается только Brutal,
    // и только на клиентском inbound'е (нулевом): api/wg-in — служебные.
    public function ensureSmuxInbound(array &$c, ?array $p = null): void
    {
        $p = $p ?? $this->getPacConf();
        $s = $this->smuxSettings($p);
        if (!isset($c['inbounds'][0]) || !is_array($c['inbounds'][0])) {
            return;
        }
        $active = $this->smuxActive($p);
        $brutal = $active && !empty($s['brutal']['enabled']);
        $frame  = $active ? self::smuxFrameSize($s['h2mux_frame']) : 0;
        if (!$brutal && $frame === 0) {
            unset($c['inbounds'][0]['smux']);

            return;
        }
        $block = [];
        if ($brutal) {
            $block['brutal-opts'] = [
                'enabled' => true,
                'up'      => self::smuxRate($s['brutal']['up']),
                'down'    => self::smuxRate($s['brutal']['down']),
            ];
        }
        // Размер кадра пишем независимо от protocol в меню: несущий коннект
        // h2mux может прийти и от шаблона с ~smux:h2mux~, пока глобально стоит
        // smux. Для smux-коннектов поле мёртвое — сервер читает его только в
        // serveH2Mux(), — так что лишним оно не бывает.
        if ($frame !== 0) {
            $block['h2muxMaxReadFrameSize'] = $frame;
        }
        $c['inbounds'][0]['smux'] = $block;
    }

    // ---- finalmask: server-side fragment/noise (streamSettings.finalmask) --
    // В отличие от SMUX это фича самого апстрима XTLS/Xray-core (не эксклюзив
    // форка Jolymmiles/Xray-core — форк её просто наследует, идя впереди
    // апстрима), поэтому работает на ОБОИХ ядрах бота одинаково — гейта по
    // xrayCore() тут нет и не нужно.
    //
    // И в отличие от $p['dpi']['fragment']/['noise'] (applyDpiFragment(),
    // клиентский freedom-outbound, направление клиент→сервер, только t=s),
    // это СЕРВЕРНЫЙ inbound — маскирует то, что сервер пишет обратно клиенту
    // (accept-путь), работает независимо от транспорта/диалекта подписки и
    // ничего в dpiMenu()/applyDpiFragment() не трогает и не дублирует.
    //
    // fragment/noise — единственные две маски finalmask, которые не требуют
    // xray-core с finalmask на ДРУГОЙ стороне: у обеих в исходнике
    // переопределён только Write()/WriteTo(), Read()/ReadFrom() не тронут —
    // обычная перелицовка байт на проводе, любой TCP/UDP-стек собирает как
    // обычно. Остальные маски форка (header-custom/sudoku/xmc/mkcp-legacy/
    // xdns/xicmp/realm) сюда не входят — см. AUDIT-2026-08-1x-finalmask.md.
    public static function finalmaskDefaults(): array
    {
        return [
            'enabled'  => 0,
            'fragment' => [
                'enabled'  => 0,
                'packets'  => 'tlshello',
                'length'   => '100-200',
                // Поле называется "delay" в finalmask (а не "interval", как в
                // старом dpi.fragment/freedom.Fragment) — имя из
                // infra/conf/transport_finalmask.go, FragmentMask.
                'delay'    => '10-20',
                'maxSplit' => '',
            ],
            'noise' => [
                'enabled' => 0,
                'reset'   => '5-10',
                'list'    => [],
            ],
        ];
    }

    // Настройки finalmask с подставленными дефолтами (вложенные fragment/noise тоже).
    public function finalmaskSettings(?array $p = null): array
    {
        $p = $p ?? $this->getPacConf();
        $s = is_array($p['finalmask'] ?? null) ? $p['finalmask'] : [];
        $d = self::finalmaskDefaults();
        $s['fragment'] = (is_array($s['fragment'] ?? null) ? $s['fragment'] : []) + $d['fragment'];
        $s['noise']    = (is_array($s['noise'] ?? null) ? $s['noise'] : []) + $d['noise'];
        unset($d['fragment'], $d['noise']);

        return $s + $d;
    }

    // UDP-noise как список пакетов — тот же формат, что dpiNoiseList(), но
    // собственное хранилище: finalmask и dpi.noise — независимые тумблеры.
    public function finalmaskNoiseList(array $pac): array
    {
        $n = $pac['finalmask']['noise'] ?? [];

        return isset($n['list']) && is_array($n['list']) ? array_values($n['list']) : [];
    }

    // JSON-форма tcp[].settings для type=fragment (infra/conf/transport_finalmask.go,
    // FragmentMask). Клэмпы — потому что ядро отвергает плохие значения на
    // СТАРТЕ (xray просто не поднимется), а не отвечает ошибкой на этот конфиг.
    public function finalmaskFragmentSettings(array $f): array
    {
        $packets = ($f['packets'] ?? '') ?: 'tlshello';
        // Числовой диапазон обязан начинаться с >=1 — "0-3" ядро отвергает при
        // старте (PacketsFrom can't be 0).
        if (preg_match('~^0-(\d+)$~', $packets, $m)) {
            $packets = '1-' . $m[1];
        } elseif ($packets === '0') {
            $packets = 'tlshello';
        }
        $settings = [
            'packets' => $packets,
            'length'  => ($f['length'] ?? '') ?: '100-200',
            'delay'   => ($f['delay']  ?? '') ?: '10-20',
        ];
        // maxSplit пишем ТОЛЬКО когда задан: пустое поле = дефолт ядра (без
        // лимита), как и в applyDpiFragment().
        if (($f['maxSplit'] ?? '') !== '') {
            $settings['maxSplit'] = $f['maxSplit'];
        }

        return $settings;
    }

    // JSON-форма udp[].settings для type=noise (NoiseMask/NoiseItem). Каждый
    // item несёт РОВНО одно из rand+randRange («случайная длина») либо
    // type+packet («фиксированный пакет») — структурно, по типу элемента, а
    // не проверкой постфактум: ядро отвергает item, в котором есть и packet,
    // и rand>0, одновременно.
    public function finalmaskNoiseSettings(array $n, array $list): array
    {
        return XrayNoise::settings($n, $list);
    }

    public function finalmaskUsesExpressions(array $p): bool
    {
        $s = $this->finalmaskSettings($p);
        return !empty($s['enabled']) && !empty($s['noise']['enabled'])
            && in_array('exp', array_column($this->finalmaskNoiseList($p), 'type'), true);
    }

    public function finalmaskCoreCompatible(array $p, string $core): bool
    {
        if (!$this->finalmaskUsesExpressions($p)) return true;
        $version = $this->xrayCoreInventory()[$core] ?? '';
        return $version !== '' && version_compare($version, '26.9.30', '>=');
    }

    public function applyFinalmaskSettings(array $settings): bool
    {
        if (!$this->admin) return false;
        try {
            return $this->withLock('xray', fn() => $this->withLock('pac', function () use ($settings) {
                $before = $this->getPacConf(); $p = $before; $p['finalmask'] = $settings;
                // Validate even disabled masks before saving values that will later be enabled.
                $this->finalmaskNoiseSettings($settings['noise'], $settings['noise']['list']);
                if (!$this->finalmaskCoreCompatible($p, $this->xrayCoreSelection($p))) {
                    throw new InvalidArgumentException($this->t('UDP noise exp требует Xray 26.9.30 или новее. Выберите совместимое ядро либо выключите noise.', 'UDP noise exp requires Xray 26.9.30 or newer. Choose a compatible core or turn noise off.'));
                }
                $old = $this->getXray(); $candidate = $old;
                $this->ensureFinalmaskInbound($candidate, $p);
                if ($this->setPacConf($p) === false) throw new RuntimeException($this->t('Не удалось сохранить finalmask', 'Could not save finalmask'));
                if (($old['inbounds'][0]['streamSettings']['finalmask'] ?? null)
                    === ($candidate['inbounds'][0]['streamSettings']['finalmask'] ?? null)) return true;
                try {
                    if ($this->restartXray($candidate) && $this->xrayCoreStarted($this->xrayCoreSelection($p))) return true;
                } catch (Throwable $e) {
                    // A failed launch can throw after saving PAC; it needs the same rollback.
                }
                $saved = $this->setPacConf($before) !== false;
                try {
                    $restored = $this->restartXray($old) && $this->xrayCoreStarted($this->xrayCoreSelection($before));
                } catch (Throwable $e) {
                    $restored = false;
                }
                throw new RuntimeException($saved && $restored
                    ? $this->t('finalmask не применён; прежние настройки восстановлены.', 'finalmask not applied; the previous settings are restored.')
                    : $this->t('finalmask не применён; восстановление не подтверждено. Проверьте состояние Xray.', 'finalmask not applied; the restore is not confirmed. Check the Xray state.'));
            }, 20, false), 20, false);
        } catch (InvalidArgumentException | RuntimeException $e) {
            $this->answer($this->input['callback_id'] ?? '', $e->getMessage(), true);
            return false;
        }
    }

    // Серверный inbound: единственное место, куда finalmask вообще пишется —
    // безусловная перезапись целиком (не array_merge, как у sockopt: ключ
    // finalmask целиком принадлежит этой фиче, ручных правок сюда не бывает).
    // Выключено или собирать нечего — ключ убираем целиком (self-healing, тот
    // же приём, что у ensureSmuxInbound()).
    public function ensureFinalmaskInbound(array &$c, ?array $p = null): void
    {
        if (!isset($c['inbounds'][0]) || !is_array($c['inbounds'][0])) {
            return;
        }
        $p  = $p ?? $this->getPacConf();
        $s  = $this->finalmaskSettings($p);
        $fm = [];
        if (!empty($s['enabled']) && !empty($s['fragment']['enabled'])) {
            $fm['tcp'] = [['type' => 'fragment', 'settings' => $this->finalmaskFragmentSettings($s['fragment'])]];
        }
        if (!empty($s['enabled']) && !empty($s['noise']['enabled'])) {
            $fm['udp'] = [['type' => 'noise', 'settings' => $this->finalmaskNoiseSettings($s['noise'], $this->finalmaskNoiseList($p))]];
        }
        if (!$fm) {
            unset($c['inbounds'][0]['streamSettings']['finalmask']);

            return;
        }
        $c['inbounds'][0]['streamSettings']['finalmask'] = $fm;
    }

    // ---- finalmask submenu ---------------------------------------------------
    public function finalmaskMenu()
    {
        $p  = $this->getPacConf();
        $s  = $this->finalmaskSettings($p);
        $on = fn ($v) => $this->i18n(!empty($v) ? 'on' : 'off');

        $text[] = 'Menu -> ' . $this->i18n('xray') . ' -> ' . $this->i18n('dpi masking') . ' -> finalmask';

        $data = [];
        $data[] = [['text' => 'finalmask: ' . $on($s['enabled']), 'callback_data' => '/finalmaskToggle enabled']];
        if (!empty($s['enabled'])) {
            $data[] = [[
                'text'          => $this->i18n('fragment') . ': ' . $on($s['fragment']['enabled']),
                'callback_data' => '/finalmaskToggle fragment',
            ]];
            if (!empty($s['fragment']['enabled'])) {
                $data[] = [
                    ['text' => 'packets: ' . $s['fragment']['packets'], 'callback_data' => '/finalmaskSet fragment_packets'],
                    ['text' => 'length: '  . $s['fragment']['length'],  'callback_data' => '/finalmaskSet fragment_length'],
                    ['text' => 'delay: '   . $s['fragment']['delay'],   'callback_data' => '/finalmaskSet fragment_delay'],
                ];
                $data[] = [
                    ['text' => 'maxSplit: ' . (($s['fragment']['maxSplit'] ?? '') ?: '—'), 'callback_data' => '/finalmaskSet fragment_maxSplit'],
                ];
                $data[] = [['text' => '📋 ' . $this->i18n('presets'), 'callback_data' => '/finalmaskFragPresets']];
            }
            $data[] = [[
                'text'          => $this->i18n('noise') . ': ' . $on($s['noise']['enabled']),
                'callback_data' => '/finalmaskToggle noise',
            ]];
            if (!empty($s['noise']['enabled'])) {
                $text[] = $this->i18n('finalmask udp only');
                $data[] = [['text' => 'reset: ' . $s['noise']['reset'], 'callback_data' => '/finalmaskSet noise_reset']];
                foreach ($this->finalmaskNoiseList($p) as $i => $ne) {
                    $data[] = [
                        ['text' => 'type: '   . (($ne['type']   ?? '') ?: 'rand'),      'callback_data' => "/finalmaskSet noise{$i}_type"],
                        ['text' => 'packet: ' . (($ne['packet'] ?? '') ?: '10-20'),     'callback_data' => "/finalmaskSet noise{$i}_packet"],
                        ['text' => 'delay: '  . (($ne['delay']  ?? '') ?: '10-16'),     'callback_data' => "/finalmaskSet noise{$i}_delay"],
                        ['text' => '🗑',                                                'callback_data' => "/finalmaskNoiseDel {$i}"],
                    ];
                }
                $data[] = [
                    ['text' => '➕ noise packet',              'callback_data' => '/finalmaskNoiseAdd'],
                    ['text' => '📋 ' . $this->i18n('presets'), 'callback_data' => '/finalmaskNoisePresets'],
                ];
            }
        }
        $data[] = $this->menuHelpButton('finalmask');
        $data[] = [['text' => $this->i18n('back'), 'callback_data' => '/dpiMenu']];

        $this->update($this->input['chat'], $this->input['message_id'], implode("\n", $text), $data);
    }

    public function finalmaskToggle($what)
    {
        $p = $this->getPacConf();
        $s = $this->finalmaskSettings($p);
        switch ($what) {
            case 'enabled':
                $s['enabled'] = empty($s['enabled']) ? 1 : 0;
                break;
            case 'fragment':
                $s['fragment']['enabled'] = empty($s['fragment']['enabled']) ? 1 : 0;
                break;
            case 'noise':
                $s['noise']['enabled'] = empty($s['noise']['enabled']) ? 1 : 0;
                // При включении с пустым списком засеваем один дефолтный
                // пакет — как dpiToggle('noise'), чтобы в меню сразу была
                // видна редактируемая строка.
                if (!empty($s['noise']['enabled']) && !$this->finalmaskNoiseList($p)) {
                    $s['noise']['list'] = [['type' => 'rand', 'packet' => '10-20', 'delay' => '10-16']];
                }
                break;
            default:
                return $this->finalmaskMenu();
        }
        $p['finalmask'] = $s;
        if (!$this->applyFinalmaskSettings($s)) { $this->finalmaskMenu(); return; }
        $this->finalmaskMenu();
    }

    public function finalmaskSet($field)
    {
        $prompt = "@{$this->input['username']} " . $this->i18n('enter value');
        if ($hint = $this->finalmaskFieldHint($field)) {
            $prompt .= "\n\n" . $hint;
        }
        $r = $this->send(
            $this->input['chat'],
            $prompt,
            $this->input['message_id'],
            reply: $this->i18n('enter value'),
        );
        $this->stashReply($r, [
            'start_message'  => $this->input['message_id'],
            'start_callback' => $this->input['callback_id'],
            'callback'       => 'saveFinalmask',
            'args'           => [$field],
        ]);
    }

    public function saveFinalmask($val, $field)
    {
        $val = trim((string) $val);
        $p   = $this->getPacConf();
        $s   = $this->finalmaskSettings($p);
        // Индексированный noise-пакет (noise{i}_type|packet|delay) — та же
        // развязка, что saveDpi() делает для dpi.noise.
        if (preg_match('~^noise(\d+)_(type|packet|delay)$~', $field, $nm)) {
            $list = $this->finalmaskNoiseList($p);
            $idx  = (int) $nm[1];
            if (isset($list[$idx])) {
                $list[$idx][$nm[2]] = $nm[2] === 'delay' && $val === '0' ? '0' : ($this->isDefaultValue($val) ? '' : $val);
                if ($nm[2] === 'type') {
                    $list[$idx]['packet'] = match ($val) {
                        'exp' => XrayNoise::dynamicPackets()[0]['packet'], 'hex' => 'deadbeef',
                        'base64' => 'SGVsbG8=', 'str' => 'hello', default => '50-150',
                    };
                }
                $s['noise']['list'] = array_values($list);
                $p['finalmask']     = $s;
                if (!$this->applyFinalmaskSettings($s)) { $this->finalmaskMenu(); return; }
            }

            return $this->finalmaskMenu();
        }
        switch ($field) {
            case 'fragment_packets':  $s['fragment']['packets']  = $this->isDefaultValue($val) ? 'tlshello' : $val; break;
            case 'fragment_length':   $s['fragment']['length']   = $this->isDefaultValue($val) ? '' : $val; break;
            case 'fragment_delay':    $s['fragment']['delay']    = $this->isDefaultValue($val) ? '' : $val; break;
            case 'fragment_maxSplit': $s['fragment']['maxSplit'] = $this->isDefaultValue($val) ? '' : $val; break;
            case 'noise_reset':       $s['noise']['reset']       = $this->isDefaultValue($val) ? '' : $val; break;
            default: return $this->finalmaskMenu();
        }
        $p['finalmask'] = $s;
        if (!$this->applyFinalmaskSettings($s)) { $this->finalmaskMenu(); return; }
        $this->finalmaskMenu();
    }

    public function finalmaskFieldHint(string $field): string
    {
        $field = preg_replace('~^noise\d+_(type|packet|delay)$~', 'noise_$1', $field);
        $ru = $this->language === 'ru';

        return match ($field) {
            'fragment_packets' => $ru
                ? 'Что резать: <code>tlshello</code> — только TLS ClientHello, либо диапазон записей вроде <code>1-3</code> (не может начинаться с 0).'
                : "What to slice: <code>tlshello</code> — only the TLS ClientHello, or a write-index range like <code>1-3</code> (can't start at 0).",
            'fragment_length' => $ru
                ? 'Длина куска в байтах, например <code>100-200</code>.'
                : 'Segment length in bytes, e.g. <code>100-200</code>.',
            'fragment_delay' => $ru
                ? 'Пауза между кусками в мс, например <code>10-20</code>.'
                : 'Delay between segments in ms, e.g. <code>10-20</code>.',
            'fragment_maxSplit' => $ru
                ? 'Потолок числа кусков. Пусто — без ограничения (дефолт ядра).'
                : 'Cap on the number of segments. Empty = no cap (core default).',
            'noise_reset' => $ru
                ? 'Время без исходящих UDP-пакетов к адресу, после которого следующая отправка повторяет шум: 1–86400 секунд, например <code>5-10</code>. При непрерывном трафике это не периодический таймер.'
                : 'Idle seconds with no outgoing UDP packets to an address before the next send repeats the burst: 1–86400, e.g. <code>5-10</code>. Continuous traffic resets this timer.',
            'noise_type', 'noise_packet', 'noise_delay' => $this->finalmaskNoiseHint(),
            default => '',
        };
    }

