    public function finalmaskNoiseDel($i)
    {
        $p    = $this->getPacConf();
        $s    = $this->finalmaskSettings($p);
        $list = $this->finalmaskNoiseList($p);
        if (isset($list[$i])) {
            array_splice($list, $i, 1);
        }
        $s['noise']['list'] = array_values($list);
        $p['finalmask']     = $s;
        if (!$this->applyFinalmaskSettings($s)) { $this->finalmaskMenu(); return; }
        $this->finalmaskMenu();
    }

    // Клиентская часть подписки. Один источник значений на три диалекта:
    //   xray-форк  — camelCase   (infra/conf/xray.go, SMuxConfig)
    //   sing-box   — snake_case  (option.OutboundMultiplexOptions, ключ multiplex)
    //   mihomo     — kebab-case  (adapter/outbound/singmux.go, ключ smux)
    // Опечатка в имени ключа не роняет конфиг громко — она молча теряет
    // настройку, поэтому имена сверены с исходниками клиентов и закреплены
    // тестом tests/smux_test.php.
    // Готовый блок в диалекте запрошенного формата. $proto — переопределение
    // протокола из плейсхолдера шаблона (~smux:h2mux~); пусто = глобальный.
    public function smuxBlock(array $pac, string $t, string $proto = ''): array
    {
        $s = $this->smuxSettings($pac);
        // Инвариант форка: maxStreams > 0 конфликтует с ненулевыми
        // maxConnections/minStreams — Build() на таком конфиге не поднимет ядро.
        $maxStreams = max(0, (int) $s['max_streams']);
        $maxConn    = $maxStreams > 0 ? 0 : max(0, (int) $s['max_connections']);
        $minStreams = $maxStreams > 0 ? 0 : max(0, (int) $s['min_streams']);
        $proto      = $proto !== '' ? $proto : (string) $s['protocol'];
        $proto      = in_array($proto, ['smux', 'h2mux'], true) ? $proto : 'smux';
        $padding    = !empty($s['padding']);
        $onlyTcp    = !empty($s['only_tcp']);
        $brutal     = !empty($s['brutal']['enabled']);
        $halfClose  = self::smuxHalfClose($s['half_close']);
        $up         = self::smuxRate($s['brutal']['up']);
        $down       = self::smuxRate($s['brutal']['down']);

        switch ($t) {
            case 's':
                $b = [
                    'enabled'        => true,
                    'protocol'       => $proto,
                    'maxConnections' => $maxConn,
                    'minStreams'     => $minStreams,
                    'maxStreams'     => $maxStreams,
                    'padding'        => $padding,
                    'onlyTcp'        => $onlyTcp,
                ];
                // Половинное закрытие есть ТОЛЬКО у форка и ТОЛЬКО по smux:
                // с h2mux Build() отвергает конфиг («logicalHalfClose is only
                // supported by SMUX»), а у sing-box и mihomo такого ключа нет
                // вовсе — потому поле живёт лишь в этом диалекте.
                if ($proto === 'smux' && $halfClose !== 'off') {
                    $b['logicalHalfClose'] = $halfClose;
                }
                if ($brutal) {
                    $b['brutal-opts'] = ['enabled' => true, 'up' => $up, 'down' => $down];
                }

                return $b;
            case 'si':
                $b = [
                    'enabled'         => true,
                    'protocol'        => $proto,
                    'max_connections' => $maxConn,
                    'min_streams'     => $minStreams,
                    'max_streams'     => $maxStreams,
                    'padding'         => $padding,
                ];
                if ($brutal) {
                    // Именно up_mbps/down_mbps целыми числами — см. smuxRateMbps().
                    $b['brutal'] = [
                        'enabled'   => true,
                        'up_mbps'   => self::smuxRateMbps($up),
                        'down_mbps' => self::smuxRateMbps($down),
                    ];
                }

                return $b;
            case 'cl':
                $b = [
                    'enabled'         => true,
                    'protocol'        => $proto,
                    'max-connections' => $maxConn,
                    'min-streams'     => $minStreams,
                    'max-streams'     => $maxStreams,
                    'only-tcp'        => $onlyTcp,
                    'padding'         => $padding,
                    'statistic'       => false,
                ];
                if ($brutal) {
                    $b['brutal-opts'] = ['enabled' => true, 'up' => $up, 'down' => $down];
                }

                return $b;
        }

        return [];
    }

    // Плейсхолдер шаблона: строка "~smux~" (или "~smux:h2mux~") на месте
    // значения любого ключа. Даёт ПОШАБЛОННЫЙ и поузловой контроль там, где
    // глобального переключателя мало: включить мультиплекс только на одном
    // узле из нескольких или задать этому шаблону свой протокол.
    //
    // Ключ с плейсхолдером УДАЛЯЕТСЯ, когда smux неактивен, — статический блок
    // в шаблоне при апстримном ядре означал бы, что клиент шлёт несущий коннект
    // серверу, который его не распознаёт, то есть перестаёт ходить совсем.
    public const SMUX_PLACEHOLDER = '#^~smux(?::(smux|h2mux))?~$#';

    private function singSmuxCompatible(array $node): bool
    {
        // sing-box 1.14.1 + fork 26.9.5: both SMUX and H2MUX truncate
        // Vision streams; Trojan/gRPC fails completely. VPS A/B tests pass
        // without multiplex. WebSocket passes with both mux protocols.
        return ($node['flow'] ?? '') !== 'xtls-rprx-vision'
            && !(($node['type'] ?? '') === 'trojan' && ($node['transport']['type'] ?? '') === 'grpc');
    }

    public function applySmuxPlaceholders(array &$c, array $pac, string $t, bool $active): int
    {
        $n = 0;
        $this->walkSmuxPlaceholders($c, $pac, $t, $active, $n);

        return $n;
    }

    private function walkSmuxPlaceholders(array &$node, array $pac, string $t, bool $active, int &$n): void
    {
        $hits = [];
        foreach ($node as $k => $v) {
            if (is_array($v)) {
                $this->walkSmuxPlaceholders($node[$k], $pac, $t, $active, $n);
            } elseif (is_string($v) && preg_match(self::SMUX_PLACEHOLDER, $v, $m)) {
                $hits[$k] = $m[1] ?? '';
            }
        }
        // Правим ПОСЛЕ обхода: unset прямо в foreach по тому же массиву — способ
        // потерять соседние ключи.
        foreach ($hits as $k => $proto) {
            $n++;
            // Пустой блок — формат не наш (диалекта для него нет). Оставить
            // строку-маркер нельзя: она уедет клиенту как есть.
            $block = $active ? $this->smuxBlock($pac, $t, $proto) : [];
            if ($t === 'si' && !$this->singSmuxCompatible($node)) {
                $block = [];
            }
            if (!$block) {
                unset($node[$k]);
                continue;
            }
            $node[$k] = $block;
            // mux (mux.cool) и smux на одном outbound'е Build() запрещает явно.
            if ($t === 's') {
                unset($node['mux']);
            }
        }
    }

    public function applyClientSmux(array &$c, $index, array $pac, string $t): void
    {
        $active = $this->smuxActive($pac);
        // Шаблон с плейсхолдером управляет мультиплексом сам — автоматическая
        // вставка в главный узел тогда не нужна (и вредна: продублировала бы
        // блок там, где его сознательно не просили).
        if ($this->applySmuxPlaceholders($c, $pac, $t, $active) > 0) {
            return;
        }
        if (!$active) {
            return;
        }
        switch ($t) {
            case 's':
                if (!isset($c['outbounds'][$index])) {
                    return;
                }
                // mux (mux.cool) и smux на одном outbound'е Build() запрещает
                // явно — снимаем чужой блок, если шаблон его нёс.
                unset($c['outbounds'][$index]['mux']);
                $c['outbounds'][$index]['smux'] = $this->smuxBlock($pac, $t);
                break;
            case 'si':
                if (!isset($c['outbounds'][$index])) {
                    return;
                }
                if (!$this->singSmuxCompatible($c['outbounds'][$index])) {
                    unset($c['outbounds'][$index]['multiplex']);
                    return;
                }
                $c['outbounds'][$index]['multiplex'] = $this->smuxBlock($pac, $t);
                break;
            case 'cl':
                if (!isset($c['proxies'][$index])) {
                    return;
                }
                $c['proxies'][$index]['smux'] = $this->smuxBlock($pac, $t);
                break;
        }
    }

    // Item 1: inject a freedom outbound carrying TLS fragment and/or UDP noise and
    // route the main proxy outbound through it via sockopt.dialerProxy (xray only).
    // No-op unless at least one is enabled, so default configs are unchanged.
    //
    // Формат finalmask (выбор администратора, dpi.format): те же маски прямо в
    // streamSettings.finalmask прокси-выхода. Xray 26.10.29 называет fragment/
    // noises у freedom устаревшими, но finalmask с fragment и noise есть только
    // с 26.3.27: в 26.2.x профиль с ним не загрузится, ядра старше молча
    // пропустят маски (проверено 2026-10-29 на выпусках 25.12.8…26.10.29).
    // Версию ядра клиента бот не знает — поэтому по умолчанию
    // прежний формат, а finalmask включает тот, у кого все клиенты новые.
    public function applyDpiFragment(array &$c, $index, array $pac): void
    {
        $frag  = !empty($pac['dpi']['fragment']['enabled']);
        $noise = !empty($pac['dpi']['noise']['enabled']);
        if (!$frag && !$noise) {
            return;
        }
        if (($pac['dpi']['format'] ?? '') === 'finalmask' && isset($c['outbounds'][$index])) {
            $f = $pac['dpi']['fragment'] ?? [];
            try {
                $fm = $c['outbounds'][$index]['streamSettings']['finalmask'] ?? [];
                if ($frag) {
                    $fm['tcp'][] = ['type' => 'fragment', 'settings' => $this->finalmaskFragmentSettings([
                        'packets'  => ($f['packets'] ?? '') ?: '1-3',
                        'length'   => $f['length'] ?? '',
                        'delay'    => $f['interval'] ?? '',
                        'maxSplit' => $f['maxSplit'] ?? '',
                    ])];
                }
                if ($noise) {
                    $fm['udp'][] = ['type' => 'noise', 'settings' => XrayNoise::settings([], $this->dpiNoiseList($pac))];
                }
                $c['outbounds'][$index]['streamSettings']['finalmask'] = $fm;
                return;
            } catch (InvalidArgumentException) {
                // Значения меню, которых finalmask не принимает (старые записи
                // без проверки): профиль в прежнем формате, а не сломанный.
            }
        }
        $settings = ['domainStrategy' => 'AsIs'];
        if ($frag) {
            $f = $pac['dpi']['fragment'];
            $settings['fragment'] = [
                'packets'  => ($f['packets']  ?? '') ?: '1-3',
                'length'   => ($f['length']   ?? '') ?: '100-200',
                'interval' => ($f['interval'] ?? '') ?: '10-20',
            ];
            // maxSplit пишем ТОЛЬКО когда задан: пустое поле = дефолт xray (без
            // лимита числа фрагментов), поэтому не добавляем его в конфиг.
            // xray принимает и число, и диапазон-строку ("3-5") как Int32Range.
            if (($f['maxSplit'] ?? '') !== '') {
                $settings['fragment']['maxSplit'] = $f['maxSplit'];
            }
        }
        if ($noise) {
            // Xray читает noises как МАССИВ — шлём все заданные пакеты подряд.
            // Пустой список при включённом noise = один дефолтный rand-пакет
            // (прежнее поведение). Для str/hex/base64 packet обязателен —
            // запись без него пропускаем, чтобы xray не упал на парсинге.
            $noises = [];
            foreach ($this->dpiNoiseList($pac) as $n) {
                $type   = ($n['type']   ?? '') ?: 'rand';
                $packet = (string) ($n['packet'] ?? '');
                if ($type !== 'rand' && $packet === '') {
                    continue;
                }
                $noises[] = [
                    'type'   => $type,
                    'packet' => $packet !== '' ? $packet : '10-20',
                    'delay'  => ($n['delay'] ?? '') ?: '10-16',
                ];
            }
            if (!$noises) {
                $noises[] = ['type' => 'rand', 'packet' => '10-20', 'delay' => '10-16'];
            }
            $settings['noises'] = $noises;
        }
        $c['outbounds'][] = [
            'tag'      => 'dpi-fragment',
            'protocol' => 'freedom',
            'settings' => $settings,
        ];
        if (isset($c['outbounds'][$index])) {
            $c['outbounds'][$index]['streamSettings']['sockopt']['dialerProxy'] = 'dpi-fragment';
        }
    }

    // UDP-noise как список пакетов. Новый формат — $pac['dpi']['noise']['list'];
    // старый одиночный noise (type/packet/delay прямо в ['noise']) мигрируем в
    // list[0] на лету, чтобы существующие конфиги не потеряли настройку.
    public function dpiNoiseList(array $pac): array
    {
        $n = $pac['dpi']['noise'] ?? [];
        if (isset($n['list']) && is_array($n['list'])) {
            return array_values($n['list']);
        }
        if (($n['type'] ?? '') !== '' || ($n['packet'] ?? '') !== '' || ($n['delay'] ?? '') !== '') {
            return [[
                'type'   => $n['type']   ?? '',
                'packet' => $n['packet'] ?? '',
                'delay'  => $n['delay']  ?? '',
            ]];
        }
        return [];
    }

    public function applyClientSniffing(array &$c, array $pac): void
    {
        if (!is_array($pac['sniffing'] ?? null)) {
            return;
        }
        $sniffing = $this->sniffingConfig($pac);
        if (empty($c['inbounds']) || !is_array($c['inbounds'])) {
            return;
        }
        foreach ($c['inbounds'] as &$inbound) {
            if (isset($inbound['sniffing'])) {
                $inbound['sniffing'] = $sniffing;
            }
        }
        unset($inbound);
    }

    // Коды one-tap deep-link'ов импорта, приходящие в query-параметре 'r'
    // (ссылки строятся в relaySub() и в карточке клиента). Список намеренно
    // плоский, без привязки к 't': целевой URL редиректа строится независимо от
    // формата подписки, поэтому пары вроде t=si&r=c исторически валидны и
    // остаются рабочими в старых сообщениях чата.
    protected function deepLinkCodes(): array
    {
        return ['v', 'sr', 'st', 'si', 'h', 'happ', 'k', 'c', 'rh', 'incy'];
    }

    public function subscriptionImportLinks(string $base, string $sid, string $name, string $relay = ''): array
    {
        $links = [];
        foreach (['v' => 'v2rayNG', 'sr' => 'Shadowrocket', 'si' => 'sing-box', 'st' => 'Streisand',
            'h' => 'Hiddify', 'happ' => 'Happ', 'k' => 'Karing', 'c' => 'mihomo', 'rh' => 'Rabbit Hole', 'incy' => 'INCY'] as $code => $label) {
            $query = ['t' => 's', 'r' => $code, 's' => $sid];
            if ($relay !== '') $query['relay'] = $relay;
            $url = $base . '?' . http_build_query($query, '', '&', PHP_QUERY_RFC3986) . '#' . rawurlencode($name);
            $links[] = '<a href="' . htmlspecialchars($url, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8') . '">import://' . $label . '</a>';
        }
        return $links;
    }

    public function subscriptionImportUrl(string $code, string $base, array $token, string $name): string
    {
        $token['t'] = match ($code) {
            'si', 'k' => 'si',
            'c', 'rh' => 'cl',
            // Hiddify converts nodes into its own config; full sing-box exports
            // may reference DNS resolvers that its converter does not preserve.
            'sr', 'st', 'h', 'happ' => 'vl',
            default => 's', // v2rayNG also accepts remote Xray JSON (routing/SMUX).
        };
        // URL-safe base64 avoids '/' splitting the path and '+' being decoded
        // as a space by clients that apply URLDecoder more than once.
        $url = $base . '/' . rtrim(strtr(base64_encode(serialize($token)), '+/', '-_'), '=');
        $encoded = rawurlencode($url);
        $title = rawurlencode($name);
        return match ($code) {
            // Android Uri.fragment decodes once; v2rayNG appends that value to
            // a java.net.URI, whose fragment is decoded again for the name.
            'v' => "v2rayng://install-config?url=$encoded#" . rawurlencode($title),
            'si' => "sing-box://import-remote-profile?url=$encoded#$title",
            'sr' => 'shadowrocket://add/sub://' . base64_encode($url) . "?remark=$title",
            'st' => "streisand://import/$encoded#$title",
            // Hiddify uses an explicit fragment verbatim. Profile-Title supplies
            // UTF-8 names without showing percent escapes in the app.
            'h' => "hiddify://import/$url",
            'happ' => "happ://add/$url",
            'k' => "karing://install-config?url=$encoded&name=$title",
            'c' => "clash://install-config?url=$encoded&overwrite=no&name=$title",
            'rh' => "rabbithole://add/$url",
            'incy' => "incy://import/$url",
            default => '',
        };
    }

    // Шаблон подписки для клиента: персональный (client.<type>template) →
    // дефолтный из pac.json → origin (/config/<type>.json). Вынесено из
    // subscription(): тот же шаблон нужен ЗАДОЛГО до сборки конфига — по нему
    // проверяется имя запрошенного rule-set (ruleSetNames), а решение об этом
    // принимается до HWID-проверки и до выбора ведра лимитера.
    public function subTemplate(string $template, string $type, array $pac)
    {
        $default = base64_decode((string) ($pac["default{$type}template"] ?? ''));
        switch (true) {
            case !empty($template) && $template == 'origin':
            case empty($template) && empty($pac["default{$type}template"]):
            case empty($template) && empty($pac["{$type}templates"][$default]):
            case !empty($template) && empty($pac["{$type}templates"][$template]):
                return json_decode((string) @file_get_contents("/config/{$type}.json"), true);
            case !empty($template):
                return $pac["{$type}templates"][$template];
            default:
                return $pac["{$type}templates"][$default];
        }
    }

    // Имена rule-set'ов, которые шаблон ДЕЙСТВИТЕЛЬНО объявляет: только они
    // считаются легальным значением 'r' в токене подписки. Ровно те же места
    // разбирают createRuleSet() (sing-box: route.rules[].createruleset[].name)
    // и clashRules() (mihomo: rules[] с type=RULE-SET и списком).
    public function ruleSetNames($tpl, string $type): array
    {
        $names = [];
        if (!is_array($tpl)) {
            return $names;
        }
        if ($type === 'sing') {
            foreach (($tpl['route']['rules'] ?? []) as $r) {
                foreach ((is_array($r) ? ($r['createruleset'] ?? []) : []) as $rs) {
                    if (!empty($rs['name'])) {
                        $names[] = (string) $rs['name'];
                    }
                }
            }
        } elseif ($type === 'clash') {
            foreach (($tpl['rules'] ?? []) as $r) {
                if (is_array($r) && ($r['type'] ?? '') === 'RULE-SET'
                    && array_key_exists('list', $r) && !empty($r['name'])
                ) {
                    $names[] = (string) $r['name'];
                }
            }
        }
        return $names;
    }

    public function subscription($return = false)
    {
        // Internal admin export only; no HTTP parameter enables this mode.
        $connectionOnly = $return === 'connection';
        $relayRequested = array_key_exists('relay', $_GET);
        $this->normalizeSubGet();
        $this->useCachedXrayCoreProbe();
        $mihomoJson = ($_GET['t'] ?? '') === 'clj';
        if ($mihomoJson) $_GET['t'] = 'cl';
        switch ($_GET['t'] ?? '') {
            case 's':
                $type = 'v2ray';
                break;
            case 'si':
                $type = 'sing';
                break;
            case 'cl':
                $type = 'clash';
                break;
            default:
                // Unknown/missing format: bail cleanly instead of running on with an
                // undefined $type (which would warn and emit a broken body).
                if (!empty($return)) {
                    return '';
                }
                $this->subNotFound('Unknown subscription format.');
        }
        $pac    = $this->getPacConf();
        if ($relayRequested && (empty($_GET['relay']) || !isset($pac['relays'][$_GET['relay']]))) {
            if ($return) return '';
            $this->subNotFound('Relay not found.');
        }
        $domain = $this->subDomain($pac);
        $xr     = $this->getXray();
        // Как в sub(): нечитаемый конфиг — это 404/'', а не TypeError в
        // findClientBySid(array $xr, …) и 500 у клиента.
        if (!is_array($xr)) {
            if (!empty($return)) {
                return '';
            }
            $this->subNotFound('Subscription temporarily unavailable.');
        }
        $scheme = empty($this->nginxGetTypeCert()) ? 'http' : 'https';
        $hash   = $this->getHashBot();

        // Resolve by subtoken (preferred) or id (pre-subtoken links).
        $sid    = $_GET['s'] ?? '';
        $k      = $this->findClientBySid($xr, $sid, !empty($pac['subtoken_strict']));
        $client = $k === null ? null : $xr['inbounds'][0]['settings']['clients'][$k];
        if ($client === null || !empty($client['off'])
            || ((int) ($client['time'] ?? 0) > 0 && $client['time'] <= time())
            || $this->xrayQuotaUnavailableOrExhausted($client, $k)) {
            if (!empty($return)) {
                return '';
            }
            // Перебор sid тормозим отдельным ведром по одному лишь IP: ключ
            // основного ведра содержит sid, поэтому каждый новый sid заводил
            // свой счётчик со значением 1 и до лимита не доходил никогда.
            $this->subRateLimit('', 'miss');
            $this->subNotFound();
        }
        $template = base64_decode($client["{$type}template"] ?? '');
        $uid      = $client['id'];               // credential (embedded in config)
        $clientIndex = $k;
        $email    = $client['email'];
        $stok     = $this->sidOf($client);       // subscription locator only

        // Периодическая выборка rule-set'а ядром: mihomo тянет rule-providers
        // (clashRules(), t=cl), sing-box — SRS (createRuleSet(), t=si). Признак —
        // 'r' в base64-токене пути, но САМ ПО СЕБЕ он ничего не доказывает: токен
        // целиком составляет клиент (см. index.php), и любой владелец рабочей
        // ссылки мог дописать в него 'r' => 'zzz', чтобы пропустить проверку
        // HWID и получить ведро лимитера 'rs' (240 запросов вместо 30) — а раз
        // имя ни с чем не совпало, дальше отдавался обычный конфиг с
        // credential'ами. Поэтому имя обязано совпасть с реальным rule-set'ом
        // шаблона этого клиента — тем же, по которому позже createRuleSet()/
        // clashRules() решают, что отдать.
        $tpl        = $this->subTemplate($template, $type, $pac);
        $rName      = (string) ($this->subToken['r'] ?? '');
        $ruleSetReq = $rName !== ''
            && in_array($type, ['clash', 'sing'], true)
            && in_array($rName, $this->ruleSetNames($tpl, $type), true);
        $isDeepLink = !$ruleSetReq
            && in_array((string) ($_GET['r'] ?? ''), $this->deepLinkCodes(), true);

        // Лимитируем только реальные HTTP-запросы: внутренние вызовы
        // (subscription(true) из кода бота) не должны крутить счётчик.
        // Обновления rule-set'ов идут в отдельном ведре: несколько списков с
        // коротким interval иначе выедали бы общий бюджет, и 429 прилетал бы
        // самой подписке.
        if (empty($return)) {
            $this->subRateLimit($sid, $ruleSetReq ? 'rs' : '');
        }

        // HWID неприменим к выборке rule-set'а: это запрос ядра за списком правил,
        // а не устройство пользователя, и заголовок X-HWID оно не шлёт — иначе
        // лимитер отдавал бы 429 и правила молча оставались пустыми. Утечки нет:
        // rule-set содержит только домены/адреса правил, без credential'ов.
        // Browser redirects carry only the existing subscription locator, never
        // VPN credentials. Register/check HWID when the app fetches the content.
        if (!$return && !$ruleSetReq && ($_GET['r'] ?? '') === 'w') {
            $this->subSecurityHeaders();
            http_response_code(410);
            return;
        }
        if (!$return && !$ruleSetReq && !$isDeepLink && !$this->processHwidRequest($client)) {
            exit;
        }

        // Формат deep-link определяется клиентом r, а не исходным t.
        $targetFormat = $ruleSetReq ? $_GET['t'] : match ($_GET['r'] ?? '') {
            // Hiddify imports a share list but still uses a sing-box-based core.
            'si', 'k', 'h' => 'si',
            'c', 'rh' => 'cl',
            'sr', 'st', 'v', 'happ' => 's',
            default => $_GET['t'],
        };
        $compatibilityError = $ruleSetReq ? '' : $this->subscriptionCompatibilityError($xr, $pac, $targetFormat);
        $replacement = false;
        if (!$connectionOnly && !$ruleSetReq && $targetFormat === 'si' && ($compatibilityError !== '' || ($pac['transport'] ?? '') === 'xhttp')
            && (!$isDeepLink || in_array($_GET['r'], ['si', 'k'], true))) {
            $candidate = $tpl;
            foreach ($candidate['outbounds'] ?? [] as $n => $node) if (($node['tag'] ?? '') === '~outbound~' || ($node['tag'] ?? '') === ($pac['outbound'] ?: 'proxy')) {
                $replacement = $this->appendXrayProtocols($candidate, $client, 'si', $n,
                    !empty($_GET['relay']) ? ($pac['relays'][$_GET['relay']] ?? []) : null, false);
                break;
            }
        }
        if ($compatibilityError !== '' && !$replacement) {
            if ($return) {
                return '';
            }
            $this->subNotFound($this->i18n($compatibilityError));
        }
        $encryption = VlessEncryption::client($xr, $pac);

        // Deep-link импорта — только если 'r' пришёл не из токена (иначе это
        // выборка rule-set'а) и совпадает с известным кодом клиента. Без первого
        // условия rule-set с именем 'c'/'si'/… перехватывался бы этим свитчом и
        // вместо списка правил уходил редирект в клиент.
        if ($isDeepLink) {
            // Relay variant: the import-remote-profile deep links must point at
            // the relay-flavoured content URL (token carries 'relay' => <name>),
            // otherwise the imported subscription would update straight from the
            // origin instead of the relay.
            $relayKey = (!empty($_GET['relay']) && !empty($pac['relays'][$_GET['relay']]))
                ? ['relay' => $_GET['relay']]
                : [];
            $this->subSecurityHeaders();
            header('Location: ' . $this->subscriptionImportUrl($_GET['r'], "$scheme://{$domain}/pac$hash",
                ['h' => $hash, 's' => $stok] + $relayKey, $email));
            exit;
        }
        $c = $tpl;

        $outbound = ($pac['outbound'] ?? '') ?: 'proxy';
        // Prefix the outbound/proxy name with server-country flag(s) so the client
        // shows e.g. "🇫🇷 proxy" next to the node. A relay subscription hops
        // relay → origin, so it gets two flags — the relay endpoint's first, then
        // the origin (destination) server's ("🇫🇷🇩🇪 proxy"); a plain subscription
        // gets just the origin's. The tag is substituted consistently everywhere
        // (proxy-groups, routing), so internal references stay intact — only the
        // visible name changes.
        $relayCfg = (!empty($_GET['relay']) && !empty($pac['relays'][$_GET['relay']]))
            ? $pac['relays'][$_GET['relay']]
            : null;
        $flagHosts = $relayCfg
            ? [($relayCfg['address'] ?: ($relayCfg['awg_address'] ?? '')), $this->ip]
            : [$this->ip];
        $outbound = $this->flagName($outbound, $flagHosts);
        $c = json_decode($this->replaceTags(json_encode($c), [
            '~outbound~' => $outbound,
        ]), true);
        // Clash/mihomo keeps the node in proxies[] (keyed by name); xray/sing-box
        // use outbounds[] (keyed by tag). Search the array that matches the format:
        // searching outbounds first would, for a clash template that also carries an
        // outbounds block, pick an outbounds index and then mis-index into proxies[].
        // The ?? [] also avoids a warning when the template lacks the other key.
        $index = null;
        if (($_GET['t'] ?? '') === 'cl') {
            foreach ($c['proxies'] ?? [] as $k => $v) {
                if (($v['name'] ?? '') == $outbound) {
                    $index = $k;
                    break;
                }
            }
        } else {
            foreach ($c['outbounds'] ?? [] as $k => $v) {
                if (($v['tag'] ?? '') == $outbound) {
                    $index = $k;
                    break;
                }
            }
        }
        // No matching node (e.g. a custom template that hard-codes the tag instead
        // of using the ~outbound~ placeholder, so the flag-prefixed name no longer
        // matches): bail with a clean 404 rather than indexing $c[...][null] and
        // silently serving a config with the real endpoint/uid never injected.
        if ($index === null) {
            if (!empty($return)) {
                return '';
            }
            $this->subNotFound('Subscription template has no matching outbound.');
        }

        // У каждого ядра свой набор допустимых имён — см. normalizeFingerprint().
        $fingerprint = $this->fingerprint();
        if ($_GET['t'] === 'si') {
            $fingerprint = $this->normalizeFingerprint($fingerprint, 'singbox');
        } elseif ($_GET['t'] === 'cl') {
            $fingerprint = $this->normalizeFingerprint($fingerprint, 'mihomo');
        }

        switch ($_GET['t']) {
            case 's':
                $c['outbounds'][$index]['settings']['vnext'][0]['address']  = '~domain~';
                $c['outbounds'][$index]['settings']['vnext'][0]['users'][0] = [
                    'id'         => '~uid~',
                    'encryption' => $encryption,
                ];
                switch ($pac['transport']) {
                    case 'Reality':
                        $c['outbounds'][$index]['settings']['vnext'][0]['users'][0]["flow"] = "xtls-rprx-vision";
                        $c['outbounds'][$index]['streamSettings']                           = [
                            "network"         => "tcp",
                            "security"        => "reality",
                            "realitySettings" => $this->realityClientSettings($fingerprint, $pac),
                        ];
                        $c['outbounds'][$index]['mux'] = [
                            "enabled"     => false,
                            "concurrency" => -1
                        ];
                        break;
                    case 'xhttp':
                        $c['outbounds'][$index]['streamSettings'] = [
                            "network"  => "xhttp",
                            "security" => "tls",

                            // Режим — явный, а не auto: stream-up, если /ws в
                            // nginx переключён на grpc_pass, иначе packet-up
                            // (см. xhttpClientMode()). Сервер слушает mode=auto
                            // и принимает любой.
                            "xhttpSettings" => [
                                "host"  => "~domain~",
                                "mode"  => $this->xhttpClientMode(),
                                "path"  => "/ws$hash",
                                "extra" => $this->xhttpClientExtra(),
                            ],

                            "tlsSettings" => [
                                "allowInsecure" => false,
                                "alpn"          => ["h2", "http/1.1"],
                                "fingerprint"   => $fingerprint,
                                "serverName"    => "~domain~",
                                "show"          => false
                            ]
                        ];
                        unset($c['outbounds'][$index]['mux']);
                        if (($mux = $this->xhttpMuxClient($pac)) !== null) {
                            $c['outbounds'][$index]['mux'] = $mux;
                        }
                        break;
                    case 'trojan-grpc':
                        $c['outbounds'][$index] = [
                            'tag'      => $outbound,
                            'protocol' => 'trojan',
                            'settings' => [
                                'servers' => [
                                    [
                                        'address'  => '~domain~',
                                        'port'     => 443,
                                        'password' => '~uid~',
                                    ]
                                ]
                            ],
                            'streamSettings' => [
                                'network'      => 'grpc',
                                'security'     => 'tls',
                                'grpcSettings' => [
                                    'serviceName' => "grpc$hash",
                                ],
                                'tlsSettings'  => [
                                    'allowInsecure' => false,
                                    'alpn'          => ['h2'],
                                    'fingerprint'   => $fingerprint,
                                    'serverName'    => '~domain~',
                                    'show'          => false
                                ]
                            ]
                        ];
                        break;

                    default:
                        $c['outbounds'][$index]['streamSettings'] = [
                            "network"    => "ws",
                            "security"   => "tls",
                            "wsSettings" => [
                                "path" => "/ws$hash?ed=2560"
                            ],
                            "tlsSettings" => [
                                "allowInsecure" => false,
                                "serverName"    => '~domain~',
                                "fingerprint"   => $fingerprint
                            ]
                        ];
                        unset($c['outbounds'][$index]['mux']);
                        break;
                }
                // Item 1: TLS fragment / UDP noise via freedom dialerProxy (xray only).
                $this->applyDpiFragment($c, $index, $pac);
                $this->applyClientSniffing($c, $pac);

                break;
            case 'si':
                $c['outbounds'][$index]['uuid'] = '~uid~';
                switch ($pac['transport']) {
                    case 'Reality':
                        unset($c['outbounds'][$index]["transport"]);
                        $c['outbounds'][$index]['flow']                         = 'xtls-rprx-vision';
                        $c['outbounds'][$index]['tls']['reality']['public_key'] = '~public_key~';
                        $c['outbounds'][$index]['tls']['server_name']           = '~server_name~';
                        $c['outbounds'][$index]['tls']['reality']['short_id']   = '~short_id~';
                        break;
                    case 'xhttp':
                        unset($c['outbounds'][$index]['flow']);
                        unset($c['outbounds'][$index]['tls']['reality']);

                        // ВАЖНО: XHTTP нет в апстримном sing-box — option/
                        // v2ray_transport.go знает только http/ws/quic/grpc/
                        // httpupgrade и на чужом type падает с "unknown transport
                        // type". Транспорт есть только в сборках-форках
                        // (sing-box-extended и производные), и снейк-кейс ниже —
                        // именно их диалект. Пользователя предупреждаем в меню
                        // xray ('xhttp singbox warn').
                        //
                        // x_padding_bytes обязателен: валидатор форка смотрит на
                        // сырое поле, а не на нормализованное, и при отсутствии
                        // ключа падает с "x_padding_bytes cannot be disabled" —
                        // без него КАЖДЫЙ сгенерированный конфиг отвергался.
                        // Остальные значения выровнены с xhttpClientExtra(),
                        // чтобы один и тот же сервер вёл себя одинаково во всех
                        // клиентах; c_max_reuse_times "0-1" ломал переиспользование
                        // соединений почти на каждом втором (0 = без лимита).
                        // max_connections держим на "0": при обоих ненулевых форк
                        // отвечает "max_connections cannot be specified together
                        // with max_concurrency".
                        // packet-up и при grpc_pass в /ws: он проходит через
                        // оба обработчика nginx, а stream-up форков sing-box
                        // не проверен.
                        $c['outbounds'][$index]["transport"] = [
                            "type" => "xhttp",
                            "host" => "~domain~",
                            "mode" => "packet-up",
                            "path" => "/ws$hash",
                            // Диапазоны шлём строками, как уже работающие
                            // max_concurrency/max_connections: у форка это
                            // Range-тип, строковая форма разбирается заведомо.
                            "x_padding_bytes"          => "100-1000",
                            "sc_max_each_post_bytes"   => "1000000",
                            "sc_min_posts_interval_ms" => "30",
                            "xmux" => [
                                "max_concurrency"   => "16-32",
                                "max_connections"   => "0",
                                "c_max_reuse_times" => "0",
                                "h_max_request_times" => "600-900",
                                "h_max_reusable_secs" => "1800-3000",
                                "h_keep_alive_period" => 60
                            ]
                        ];

                        $c['outbounds'][$index]['tls'] = [
                            "enabled"     => true,
                            "insecure"    => false,
                            "server_name" => "~domain~",
                            "alpn"        => ["h2"],
                            "utls"        => [
                                "enabled"     => true,
                                "fingerprint" => $fingerprint,
                            ],
                        ];
                        break;
                    case 'trojan-grpc':
                        $c['outbounds'][$index]['type']     = 'trojan';
                        $c['outbounds'][$index]['password'] = '~uid~';
                        unset($c['outbounds'][$index]['uuid']);
                        unset($c['outbounds'][$index]['flow']);
                        unset($c['outbounds'][$index]['packet_encoding']);
                        unset($c['outbounds'][$index]['tls']['reality']);

                        $c['outbounds'][$index]['transport'] = [
                            'type'         => 'grpc',
                            'service_name' => "grpc$hash",
                        ];
                        $c['outbounds'][$index]['tls'] = [
                            'enabled'     => true,
                            'insecure'    => false,
                            'server_name' => '~domain~',
                            'alpn'        => ['h2'],
                            'utls'        => [
                                'enabled'     => true,
                                'fingerprint' => $fingerprint,
                            ],
                        ];
                        break;

                    default:
                        unset($c['outbounds'][$index]['tls']['reality']);
                        unset($c['outbounds'][$index]['flow']);
                        $c['outbounds'][$index]["transport"] = [
                            "type" => "ws",
                            "path" => "/ws$hash"
                        ];
                        $c['outbounds'][$index]['tls']['server_name'] = '~domain~';
                        break;
                }
                break;
            case 'cl':
                $c['proxies'][$index]['server'] = '~domain~';
                $c['proxies'][$index]['uuid']   = '~uid~';
                $c['proxies'][$index]['client-fingerprint'] = $fingerprint;
                unset($c['proxies'][$index]['encryption']);
                if ($encryption !== 'none' && $encryption !== null) {
                    $c['proxies'][$index]['encryption'] = $encryption;
                }
                switch (true) {
                    case $pac['transport'] == 'Reality':
                        unset($c['proxies'][$index]["ws-opts"]);
                        unset($c['proxies'][$index]["skip-cert-verify"]);
                        $c['proxies'][$index]["network"]      = "tcp";
                        $c['proxies'][$index]['flow']         = 'xtls-rprx-vision';
                        $c['proxies'][$index]['servername']  = '~server_name~';
                        $c['proxies'][$index]['reality-opts'] = [
                            'public-key' => '~public_key~',
                            'short-id'   => '~short_id~',
                            'support-x25519mlkem768' => true,
                        ];
                        break;
                    case $pac['transport'] == 'xhttp':
                        unset($c['proxies'][$index]['ws-opts']);
                        unset($c['proxies'][$index]['flow']);
                        unset($c['proxies'][$index]['reality-opts']);

                        $c['proxies'][$index]['network']            = 'xhttp';
                        $c['proxies'][$index]['tls']                = true;
                        $c['proxies'][$index]['alpn']               = ['h2'];
                        $c['proxies'][$index]['servername']         = '~domain~';
                        $c['proxies'][$index]['skip-cert-verify']   = false;

                        // Имена ключей — kebab-диалект mihomo (adapter/outbound/
                        // vless.go, XHTTPOptions/XHTTPReuseSettings); xmux там
                        // называется reuse-settings.
                        // Значения выровнены с xhttpClientExtra(): было
                        // max-concurrency 8-16 и h-max-request-times 100-200,
                        // т.е. вдвое меньше параллелизма и переоткрытие соединения
                        // каждые 100-200 POST'ов (в packet-up один POST = один
                        // запрос, это секунды). Дефолт xray — 600-900.
                        // Режим — как у Xray (xhttpClientMode()): mihomo 1.19.33
                        // проверен в stream-up через grpc_pass.
                        $c['proxies'][$index]['xhttp-opts'] = [
                            'host'                     => '~domain~',
                            'path'                     => "/ws$hash",
                            'mode'                     => $this->xhttpClientMode(),
                            'no-grpc-header'           => false,
                            'x-padding-bytes'          => '100-1000',
                            'sc-max-each-post-bytes'   => 1000000,
                            'sc-min-posts-interval-ms' => 30,
                            'reuse-settings'           => [
                                'max-connections'   => '0',
                                'max-concurrency'   => '16-32',
                                'c-max-reuse-times' => '0',
                                'h-max-request-times' => '600-900',
                                'h-max-reusable-secs' => '1800-3000',
                            ],
                        ];
                        break;
                    case $pac['transport'] == 'trojan-grpc':
                        unset($c['proxies'][$index]['ws-opts']);
                        unset($c['proxies'][$index]['flow']);
                        unset($c['proxies'][$index]['reality-opts']);
                        unset($c['proxies'][$index]['xhttp-opts']);
                        unset($c['proxies'][$index]['uuid']);

                        $c['proxies'][$index]['type']             = 'trojan';
                        $c['proxies'][$index]['password']         = '~uid~';
                        $c['proxies'][$index]['network']          = 'grpc';
                        $c['proxies'][$index]['tls']              = true;
                        $c['proxies'][$index]['alpn']             = ['h2'];
                        $c['proxies'][$index]['skip-cert-verify'] = false;
                        // Clash.Meta trojan читает SNI из поля `sni`, а НЕ `servername`
                        // (последнее — только для vless/vmess и trojan'ом игнорируется).
                        unset($c['proxies'][$index]['servername']);
                        $c['proxies'][$index]['sni']              = '~domain~';
                        $c['proxies'][$index]['grpc-opts']        = [
                            'grpc-service-name' => "grpc$hash",
                        ];
                        break;

                    default:
                        unset($c['proxies'][$index]['flow']);
                        unset($c['proxies'][$index]['reality-opts']);
                        $c['proxies'][$index]["network"]          = "ws";
                        $c['proxies'][$index]["ws-opts"]['path']  = "/ws$hash";
                        $c['proxies'][$index]["skip-cert-verify"] = false;
                        $c['proxies'][$index]['servername']       = '~domain~';
                        break;
                }


                    if (!empty($client['awg']) && !empty($awg = $this->getAwgClient($client['awg']))) {
                        $awgproxy = [
                            "name"        => 'awg',
                            "type"        => 'wireguard',
                            "server"      => $awg['server'],
                            "port"        => $awg['port'],
                            "ip"          => $awg['ip'],
                            "private-key" => $awg['private-key'],
                            "public-key"  => $awg['public-key'],
                            "allowed-ips" => [
                                "0.0.0.0/0",
                            ],
                            "mtu"                  => $awg['mtu'],
                            // Целое число: диапазон 3.0 mihomo здесь не примет.
                            "persistent-keepalive" => self::keepaliveInt($awg['persistent-keepalive'] ?? 20),
                            "udp"                  => true,
                        ];
                        if (!empty($awg['pre-shared-key'])) {
                            $awgproxy['pre-shared-key'] = $awg['pre-shared-key'];
                        }
                        if (!empty($awg['amnezia-wg-option'])) {
                            $awgproxy['amnezia-wg-option'] = $awg['amnezia-wg-option'];
                        }
                        $c['proxies'][] = $awgproxy;
                        $c['proxy-groups'][0]['proxies'][] = 'awg';
                    }

                $tunpackage = array_filter($pac['tunpackage'] ?? []);
                $tunprocess = array_filter($pac['tunprocess'] ?? []);
                if (!empty($tunpackage) || !empty($tunprocess)) {
                    if (!empty($tunpackage)) {
                        if (!empty($pac['tunpackagemode'])) {
                            $c['tun']['exclude-package'] = array_keys($tunpackage);
                        } else {
                            $c['tun']['include-package'] = array_keys($tunpackage);
                        }
                    }
                    if (!empty($tunprocess)) {
                        if (!empty($pac['tunprocessmode'])) {
                            $c['tun']['exclude-process'] = array_keys($tunprocess);
                        } else {
                            $c['tun']['include-process'] = array_keys($tunprocess);
                        }
                    }
                }
                break;
        }
        // SMUX кладём ПОСЛЕ веток транспорта: Reality и trojan-grpc пересобирают
        // outbound/proxy целиком, и блок, положенный раньше, они бы стёрли.
        // Внутри — ранний выход, если ядро не форковое или smux выключен.
        $this->applyClientSmux($c, $index, $pac, (string) ($_GET['t'] ?? ''));
        if ($connectionOnly) {
            $c = self::connectionNodes($c, (string) $_GET['t'], (int) $index);
        }
        // WARP-теги шаблона. У каждого клиента СВОЙ wgcf-аккаунт: общий
        // серверный ключ означал бы, что сессии клиентов и самого сервера
        // выбивают друг друга (в WireGuard у пира ровно один endpoint, и
        // handshake с нового источника переписывает предыдущий).
        //
        // Регистрация ленивая и делается только если шаблон реально просит
        // ключ — иначе каждая подписка любого клиента ходила бы в API
        // Cloudflare заводить лишний аккаунт. Если персональный завести не
        // удалось (сеть/лимит), теги останутся пустыми: пусть warp-прокси в
        // конфиге будет нерабочим, чем рабочим, но конфликтующим с сервером.
        $json = json_encode($c);
        $warp = str_contains($json, '~warp_private_key~')
            ? ($this->warpClientProfile($client['email'] ?? '') ?: [])
            : [];
        if ($_GET['t'] === 's' && isset($c['routing']['rules'])) {
            $c['routing']['rules'] = $this->xrayRouteLists($c['routing']['rules'], $pac);
            $json = json_encode($c);
        }
        $c = json_decode($this->replaceTags($json, [
            '"~pac~"'        => json_encode(array_keys(array_filter(($pac['includelist'] ?? []) ?: []))),
            '"~block~"'      => json_encode(array_keys(array_filter(($pac['blocklist'] ?? []) ?: []))),
            '"~warp~"'       => json_encode(array_keys(array_filter(($pac['warplist'] ?? []) ?: []))),
            '"~process~"'    => json_encode(array_keys(array_filter(($pac['processlist'] ?? []) ?: []))),
            '"~package~"'    => json_encode(array_keys(array_filter(($pac['packagelist'] ?? []) ?: []))),
            '"~subnet~"'     => json_encode(array_keys(array_filter(($pac['subnetlist'] ?? []) ?: []))),
            '"~warp_port~"'      => (int) ($warp['port'] ?? 2408),
            '"~warp_mtu~"'       => (int) ($warp['mtu'] ?? 1280),
            '~warp_server~'      => $warp['server'] ?? '',
            '~warp_ip~'          => $warp['ip'] ?? '',
            '~warp_private_key~' => $warp['private-key'] ?? '',
            '~warp_public_key~'  => $warp['public-key'] ?? '',
            '~dns~'          => "https://$domain/dns-query$hash/" . $this->dohClientId($uid),
            '~dnspath~'      => "/dns-query$hash/" . $this->dohClientId($uid),
            '~uid~'          => (($pac['transport'] ?? '') == 'trojan-grpc' ? ($client['password'] ?? $uid) : $uid),
            '~domain~'       => $domain,
            // ?? '' — до задания домена (и без cdn) шаблон подставлял пустоту,
            // но сначала сыпал warning'ами на каждой выдаче подписки.
            '~directdomain~' => $pac['domain'] ?? '',
            '~cdndomain~'    => $pac['linkdomain'] ?? '',
            // ?? '' — Reality-поля есть только у Reality-транспорта, а
            // changeTransport() заменяет streamSettings целиком: на ws/xhttp
            // каждая выдача подписки давала здесь два warning'а.
            '~short_id~'     => $this->clientShortId($xr, (string) $uid),
            '~email~'        => $email,
            '~public_key~'   => $pac['xray'],
            '~server_name~'  => $xr['inbounds'][0]['streamSettings']['realitySettings']['serverNames'][0] ?? '',
            '~fingerprint~'  => $fingerprint,
            '~ip~'           => $this->ip,
            '~outbound~'     => $outbound,
        ]), true);

        $c = self::expandRelayPlaceholders($c, $this->relayTemplateData($pac));

        if ($connectionOnly) {
            return json_encode($c,
                JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_THROW_ON_ERROR);
        }

        switch ($_GET['t']) {
            case 's':
                break;
            case 'si':
                $c['route'] = $this->addRuleSet($c['route']);
                $c['route'] = $this->createRuleSet($c['route'], $stok, $domain);
                // Защита: убрать из dns/route правил ссылки на rule_set, которые
                // не были определены в route.rule_set (напр. запись есть в
                // dns-шаблоне, но отсутствует в rulessetlist) — иначе клиент
                // падает с "rule-set not found" и весь конфиг не импортируется.
                $c = $this->pruneRuleSetRefs($c);
                if (!empty($c['route']['rules'])) {
                    foreach ($c['route']['rules'] as $k => $v) {
                        if (count($v) == 1 && array_key_exists('outbound', $v)) {
                            unset($c['route']['rules'][$k]);
                        }
                    }
                    $c['route']['rules'] = array_values($c['route']['rules']);
                }
                if (empty($c['route'])) {
                    unset($c['route']);
                }
                break;
            case 'cl':
                $c = $this->addClashRuleSet($c);
                if (!empty($c['rules'])) {
                    $c = $this->clashRules($c, $stok, $domain);
                    if (count($c['rules']) == 1) {
                        unset($c['rules']);
                    }
                }
                // Довесок к ~dns~: тот же DoH-эндпоинт на каждом настроенном
                // домене. ~dns~ строится из $domain, а он приходит из
                // ?cdn=/Host запроса — то есть покрывает ровно тот адрес, по
                // которому клиент скачал подписку. Остальные домены сюда
                // никогда не попадали, хотя обслуживаются тем же nginx и тем
                // же сертом. mihomo опрашивает nameserver'ы параллельно, так
                // что это отказоустойчивость: заблокируют один домен —
                // резолвер продолжит работать со второго.
                //
                // Список берём ТОЛЬКО из pac-конфига (dnsDomains), не из
                // $domain: Host-заголовок задаёт клиент, и подмешивать его в
                // выдачу нельзя. Трогаем лишь шаблоны, где nameserver уже
                // есть, — если в шаблоне DNS-блока нет, это осознанный выбор.
                if (isset($c['dns']['nameserver'])) {
                    $ns = $c['dns']['nameserver'];
                    $ns = is_array($ns) ? $ns : [$ns];
                    $own = [];
                    foreach ($this->dnsDomains($pac) as $d) {
                        $own[] = "https://$d/dns-query$hash/" . $this->dohClientId($uid);
                    }
                    if (!empty($own)) {
                        // Свой резолвер ЗАМЕЩАЕТ список, а прежние уезжают в
                        // fallback. Раньше он просто дописывался в конец, а
                        // mihomo опрашивает весь nameserver параллельно и берёт
                        // первый ответ — почти всегда это Cloudflare/Google из
                        // шаблона, а не свой AdGuard. То есть фильтрация и
                        // per-client политика де-факто не работали, а
                        // DNS-профиль пользователей уходил третьей стороне,
                        // хотя админ считал, что настроил свой DoH.
                        $fallback = array_merge(
                            is_array($c['dns']['fallback'] ?? null) ? $c['dns']['fallback'] : [],
                            array_diff($ns, $own)
                        );
                        // SORT_REGULAR, а не дефолтный SORT_STRING: шаблон
                        // пользовательский, и вложенный массив дал бы «Array to
                        // string conversion» на каждой выдаче подписки.
                        $c['dns']['nameserver'] = array_values(array_unique($own, SORT_REGULAR));
                        if (!empty($fallback)) {
                            $c['dns']['fallback'] = array_values(array_unique($fallback, SORT_REGULAR));
                        }
                    }
                }
                break;
        }
        // Relay variant: swap only the endpoint address+port to the chosen relay
        // (selected by name via $_GET['relay']); everything else stays as-is.
        if (!empty($_GET['relay']) && !empty($pac['relays'][$_GET['relay']]) && isset($index)) {
            $this->applyRelay($c, $_GET['t'], $index, $pac['relays'][$_GET['relay']]);
            // Mihomo-конфиг может нести встроенный wireguard/awg-прокси; его
            // эндпоинт подменяем на отдельный WG/AWG-relay (если задан), чтобы
            // основной прокси и awg ходили через разные relay/порты.
            if ($_GET['t'] == 'cl') {
                $this->applyAwgRelay($c, $pac['relays'][$_GET['relay']]);
            }
        }
        if (!$ruleSetReq) $this->appendXrayProtocols($c, $client, (string) $_GET['t'], (int) $index, $relayCfg, !$replacement);
        if (!empty($return)) {
            if ($_GET['t'] == 'cl' && !$mihomoJson) {
                return yaml_emit($c);
            }
            // Mihomo also reads JSON through its YAML parser: escaped slashes
            // and JSON surrogate pairs are not portable YAML scalars.
            return json_encode($c, $mihomoJson ? JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE : 0);
        }

        // The body carries client secrets (UUID/password, reality keys) — keep it
        // out of any cache/index (defense-in-depth).
        $this->subSecurityHeaders();
        header('Profile-Title: base64:' . base64_encode((string) $email));
        $this->xraySubscriptionMetadata($client, $clientIndex);
        if ($_GET['t'] == 'cl' && !$mihomoJson) {
            header('Content-type: text/yaml');
            echo yaml_emit($c);
            return;
        }

        header('Content-type: application/json');
        echo json_encode($c, $mihomoJson ? JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE : 0);
    }

    // Response headers for any subscription body (contains client secrets): no
    // caching, no indexing, no MIME sniffing. Mirrors the relay repo's nginx.
    public function subSecurityHeaders()
    {
        header('Cache-Control: no-store, no-cache, must-revalidate');
        header('Pragma: no-cache');
        header('X-Content-Type-Options: nosniff');
        header('X-Robots-Tag: noindex, nofollow');
        header('Referrer-Policy: no-referrer');
        // Pin TLS so a client that once reached the sub over HTTPS never silently
        // falls back to plaintext http (where the config would be sniffable). Only
        // meaningful when a cert is configured (nginx serves 443); browsers ignore
        // it over plain http anyway.
        if (!empty($this->nginxGetTypeCert())) {
            header('Strict-Transport-Security: max-age=31536000; includeSubDomains');
        }
    }

    // Rate-limit подписочных эндпоинтов: файловый счётчик окно+лимит на пару
    // (sid, IP). Тормозит перебор sid и выкачивание подписок ботами; легитимный
    // клиент обновляется раз в часы — дефолт 30 req / 5 мин не заденет даже
    // ручные переимпорты. Настройка: pac.sub_rate_max (0 = выкл — но только для
    // ведра подписки, ведро 'rs' обнуляется своим pac.sub_rate_max_rs) /
    // pac.sub_rate_window (сек). Вызывается ДО резолва sid — невалидные sid
    // тоже считаются (анти-brute-force).
    // $scope разводит счётчики по независимым вёдрам (напр. 'rs' — периодические
    // выборки rule-set'ов), чтобы фоновый трафик не расходовал бюджет подписки.
    // У ведра 'rs' свой дефолт: ядро тянет КАЖДЫЙ список отдельным запросом с
    // interval из шаблона (30s), т.е. 6 списков дают ~60 запросов за 5-минутное
    // окно. Лимит подписки (30) резал бы их половину, и правила молча оставались
    // бы пустыми — трафик уходил бы в direct мимо block/warp. Запас x4 покрывает
    // переподключения ядра и добавленные списки. Настройка: pac.sub_rate_max_rs
    // (0 = выкл; sub_rate_max=0 это ведро НЕ выключает — ключи независимы).
    // Потолок числа окон в /logs/sub_ratelimit.json (см. подрезку ниже).
    public const SUB_RATE_MAX_ENTRIES = 5000;

    // Отдельным методом, чтобы тест мог подсунуть свой путь: писать в /logs из
    // тестов нельзя, а считать счётчики без файла бессмысленно.
    public function subRateFile(): string
    {
        return '/logs/sub_ratelimit.json';
    }

    public function subRateLimit($sid, $scope = '')
    {
        $pac    = $this->getPacConf();
        $max    = match ($scope) {
            'rs'    => (int) ($pac['sub_rate_max_rs'] ?? 240),
            // Ведро промахов: столько НЕудачных резолвов sid с одного адреса
            // за окно. Легитимный клиент промахивается разве что по устаревшей
            // ссылке — единицы запросов, перебор упирается сразу.
            'miss'  => (int) ($pac['sub_rate_max_miss'] ?? 20),
            default => (int) ($pac['sub_rate_max'] ?? 30),
        };
        $window = (int) ($pac['sub_rate_window'] ?? 300);
        if ($max <= 0 || $window <= 0) {
            return;
        }
        // За nginx REMOTE_ADDR — адрес прокси, реальный адрес приходит
        // заголовком. Порядок предпочтения важен (аудит 2026-08-18): X-Real-IP
        // наш nginx ставит одним значением, а XFF раньше вообще не
        // перетирался на /pac — клиент присылал свой и обходил лимит, потому
        // что ключ ведра это hash(sid|ip|scope), а в ведре 'miss' (анти-перебор
        // sid) sid из ключа исключён намеренно и ip остаётся единственным
        // переменным компонентом. Теперь заголовок ставит nginx (location /pac
        // в config/nginx*.conf), а из XFF берём ПЕРВЫЙ элемент только как
        // фолбэк для нестандартного фронта.
        $ip  = trim((string) ($_SERVER['HTTP_X_REAL_IP'] ?? ''))
            ?: trim(explode(',', (string) ($_SERVER['HTTP_X_FORWARDED_FOR'] ?? ''))[0])
            ?: (string) ($_SERVER['REMOTE_ADDR'] ?? '');
        // В ведре промахов sid НЕ участвует: с ним каждый перебираемый sid
        // заводил собственный счётчик со значением 1 (лимит не срабатывал
        // никогда) и оставлял запись в файле на всё окно — файл целиком
        // читается и переписывается под LOCK_EX на КАЖДЫЙ запрос подписки,
        // так что поток случайных sid ещё и сериализовал легитимные выдачи.
        $key = substr(hash('sha256', ($scope === 'miss' ? '' : $sid) . "|$ip|$scope"), 0, 16);
        $f   = $this->subRateFile();
        $h   = @fopen($f, 'c+');
        if ($h === false) {
            return; // лимитер вспомогательный: не роняем выдачу подписки
        }
        $over = false;
        if (flock($h, LOCK_EX)) {
            $data = json_decode((string) stream_get_contents($h), true) ?: [];
            $now  = time();
            foreach ($data as $k => $v) {
                if (!is_array($v) || ($v[1] ?? 0) + $window < $now) {
                    unset($data[$k]);
                }
            }
            $data[$key] = [($data[$key][0] ?? 0) + 1, $data[$key][1] ?? $now];
            $over = $data[$key][0] > $max;
            // Потолок на размер файла: он читается и переписывается целиком на
            // каждый запрос подписки, поэтому распределённый перебор (по одной
            // записи с адреса) не должен разгонять его до мегабайтов. Режем
            // самые старые окна, своё — оставляем.
            if (count($data) > self::SUB_RATE_MAX_ENTRIES) {
                uasort($data, fn($a, $b) => ($b[1] ?? 0) <=> ($a[1] ?? 0));
                $data = array_slice($data, 0, self::SUB_RATE_MAX_ENTRIES, true) + [$key => $data[$key]];
            }
            ftruncate($h, 0);
            rewind($h);
            fwrite($h, json_encode($data));
            flock($h, LOCK_UN);
        }
        fclose($h);
        if ($over) {
            $this->subSecurityHeaders();
            http_response_code(429);
            header('Retry-After: ' . $window);
            header('Content-Type: text/plain; charset=utf-8');
            echo 'Too Many Requests';
            exit;
        }
    }

    // A missing/disabled/expired subscription must not look like a server crash:
    // return a clean 404 with a short description so the client shows "not found"
    // instead of treating a 500 as a transient error and hammering retries.
    public function subNotFound($reason = 'Subscription not found or disabled.')
    {
        $this->subSecurityHeaders();
        http_response_code(404);
        header('Content-Type: text/html; charset=utf-8');
        $reason = htmlspecialchars($reason, ENT_QUOTES, 'UTF-8');
        echo "<!doctype html><meta charset=\"utf-8\"><title>404 Not Found</title>"
            . "<h1>404 Not Found</h1><p>$reason</p>";
        exit;
    }

    public function getAwgClient($pk)
    {
        $c   = $this->getPacConf();
        $wg  = json_decode(file_get_contents($this->clients), true) ?: [];
        $wg1 = json_decode(file_get_contents($this->clients1), true) ?: [];
        foreach ($wg as $k => $v) {
            if ($v['interface']['PrivateKey'] == $pk) {
                $container = '';
                $cl = $v;
                break;
            }
        }
        foreach ($wg1 as $k => $v) {
            if ($v['interface']['PrivateKey'] == $pk) {
                $container = 'wg1_';
                $cl = $v;
                break;
            }
        }

        if (empty($cl)) {
            return false;
        }

        return [
            // Блок 3.0 уезжает в mihomo только при включённом тумблере
            // mihomo_awg3: его понимают лишь свежие сборки, а нужные ИМЕНА
            // полей у mihomo свои (см. MIHOMO_AWG3_KEYS).
            // Набор прогоняем через amneziaKeysUsable() — тот же срез, что
            // уходит в wg0.conf: иначе подписка объявила бы клиенту header
            // protection, которого на сервере нет, и handshake молча не прошёл
            // бы. Версию tools берём из кеша: ssh на пути подписки нельзя.
            "amnezia-wg-option" => self::amneziaKeysForMihomo(
                self::amneziaKeysUsable(
                    !empty($c["{$container}amnezia"]) ? ($c["{$container}amnezia_keys"] ?? []) : [],
                    $this->awgSupports3Cached($container),
                    $this->awgSupports31Cached($container)
                ),
                !empty($c['mihomo_awg3'])
            ),
            // После выключения Amnezia её пресет/PSK остаётся в PAC для
            // следующего включения. Экспорт берёт ключ действующего peer.
            "pre-shared-key"    => $cl['peers'][0]['PresharedKey'] ?? '',
            // Диапазон приводится к числу уже на месте сборки прокси
            // (keepaliveInt): ssh сюда звать нельзя — это путь подписки.
            "persistent-keepalive" => $c["{$container}amnezia_keepalive"] ?? 20,
            "server"            => explode(':', $cl['peers'][0]['Endpoint'])[0],
            "port"              => explode(':', $cl['peers'][0]['Endpoint'])[1],
            "ip"                => explode('/', $cl['interface']['Address'])[0],
            "private-key"       => $cl['interface']['PrivateKey'],
            "public-key"        => $cl['peers'][0]['PublicKey'],
            "mtu"               => $c["{$container}mtu"] ?? $this->mtu,
        ];
    }

    /**
     * Разбирает ключ реестра rulessetlist: «outbound[:behavior]:interval:URL».
     *
     * Раньше его разбирали в двух местах по-разному — addClashRuleSet делал
     * explode(':', $k, 4), addRuleSet — explode(':', $k, 3), — хотя промпт
     * (include('rulessetlist')) обещает одну форму, а валидация addInclude
     * пропускает обе. В итоге «proxy:86400:https://x/y.mrs» давал mihomo
     * url="//x/y.mrs" с interval=0, а «proxy:domain:86400:https://x/y.srs»
     * давал sing-box url="86400:https://x/y.srs" — то есть форма без behavior
     * ломалась у одного потребителя, форма с behavior у другого.
     *
     * Разбираем С КОНЦА: URL начинается с http(s)://, перед ним интервал
     * (число или длительность вида 1d — трактовку оставляем потребителю), всё,
     * что осталось слева, — outbound и необязательный behavior. Это
     * единственный способ не спутать двоеточие схемы с разделителем полей.
     *
     * @return array{outbound:string,behavior:string,interval:string,url:string}|null
     */
    public static function parseRuleSetKey(string $k): ?array
    {
        if (!preg_match('~^(.*?):([\w.]+):(https?://[^\s]+)$~', trim($k), $m)) {
            return null;
        }
        $head  = explode(':', $m[1]);
        $out   = trim((string) array_shift($head));
        $behav = trim((string) array_shift($head));
        if ($out === '' || $head || str_contains($out, ',')
            || self::ruleSetInterval($m[2]) === null
            || !filter_var($m[3], FILTER_VALIDATE_URL)
            || ($behav !== '' && !in_array($behav, ['classical', 'domain', 'ipcidr'], true))) {
            return null;
        }
        return [
            'outbound' => $out,
            // Дефолт behavior — как у большинства списков mihomo; для sing-box
            // поле не используется вовсе.
            'behavior' => $behav !== '' ? $behav : 'classical',
            'interval' => $m[2],
            'url'      => $m[3],
        ];
    }

    // В меню число означает секунды. sing-box требует duration с единицей,
    // Mihomo — целое число секунд; приведение (int)'1d' давало одну секунду.
    public static function ruleSetInterval(string $value): ?int
    {
        if (preg_match('~^[0-9]+$~D', $value)) $value .= 's';
        if (!preg_match('~^(?:\d+(?:\.\d+)?[smhdw])+$~', $value)) return null;
        preg_match_all('~(\d+(?:\.\d+)?)([smhdw])~', $value, $parts, PREG_SET_ORDER);
        $seconds = 0;
        foreach ($parts as $part) $seconds += (float) $part[1] * ['s' => 1, 'm' => 60, 'h' => 3600, 'd' => 86400, 'w' => 604800][$part[2]];
        return is_finite((float) $seconds) && $seconds >= 1 && $seconds < PHP_INT_MAX ? (int) ceil($seconds) : null;
    }

    public static function ruleSetFormat(string $url): string
    {
        return strtolower(pathinfo((string) parse_url($url, PHP_URL_PATH), PATHINFO_EXTENSION));
    }

    // Каким ядром источник будет использован: формат выбирает ядро, а не
    // наоборот — srs/json понимает только sing-box, остальное только Mihomo.
    public static function ruleSetCore(string $url): string
    {
        return in_array(self::ruleSetFormat($url), ['srs', 'json'], true) ? 'sing-box' : 'Mihomo';
    }

    // Пробная загрузка источника с сервера. '' — всё в порядке либо проверить
    // нечем: ссылки http:// не запрашиваем (защита от обращений во внутреннюю
    // сеть действует только для https), слишком большой файл не разбираем.
    public function ruleSetProbe(string $url): string
    {
        if (!str_starts_with(strtolower($url), 'https://')) {
            return '';
        }
        $r = $this->datHttpGet($url, [], 8 << 20, 15);
        if (empty($r['ok'])) {
            $err = (string) ($r['err'] ?? 'fetch failed');
            return $err === 'response too large' ? '' : $err;
        }
        return self::ruleSetBodyError(self::ruleSetFormat($url), (string) ($r['body'] ?? ''));
    }

    // Похоже ли тело на rule-set своего формата. Ловит главное: страницу
    // ошибки или «просмотр файла» вместо самого файла.
    public static function ruleSetBodyError(string $format, string $body): string
    {
        $html = (bool) preg_match('~^\s*<(?:!doctype|html|\?xml)~i', substr($body, 0, 512));
        if ($format === 'srs') {
            return str_starts_with($body, 'SRS') ? '' : Lang::t('это не файл .srs', 'this is not a .srs file');
        }
        if ($format === 'mrs') {
            return str_starts_with($body, "\x28\xb5\x2f\xfd") ? '' : Lang::t('это не файл .mrs', 'this is not a .mrs file');
        }
        if ($format === 'json') {
            $json = json_decode($body, true);
            return is_array($json) && is_array($json['rules'] ?? null) ? '' : Lang::t('в JSON нет списка rules', 'the JSON has no rules list');
        }
        if (in_array($format, ['yaml', 'yml'], true)) {
            return !$html && preg_match('~^\s*payload\s*:~m', $body) ? '' : Lang::t('в файле нет раздела payload', 'the file has no payload section');
        }
        return $html || trim($body) === '' ? Lang::t('пустой список или страница HTML', 'an empty list or an HTML page') : '';
    }

    public function addClashRuleSet($c)
    {
        $p = $this->getPacConf();
        if (!empty($p['rulessetlist']) && !empty($c['add-rule-providers'])) {
            foreach ($p['rulessetlist'] as $k => $v) {
                if (!empty($v)) {
                    if (($e = self::parseRuleSetKey((string) $k)) === null) {
                        continue;
                    }
                    [$type, $behavior, $time, $url] = [$e['outbound'], $e['behavior'], $e['interval'], $e['url']];
                    $format = self::ruleSetFormat($url);
                    if (in_array($format, ['mrs', 'yaml', 'yml', 'txt'], true)
                        && ($format !== 'mrs' || $behavior !== 'classical')) {
                        $target = match (strtolower($type)) {
                            'block', 'reject' => 'REJECT',
                            'direct' => 'DIRECT',
                            'proxy' => 'PROXY',
                            default => $type,
                        };
                        $targets = array_merge(['DIRECT', 'REJECT', 'REJECT-DROP', 'PASS', 'COMPATIBLE'],
                            array_column($c['proxies'] ?? [], 'name'), array_column($c['proxy-groups'] ?? [], 'name'));
                        if (!in_array($target, $targets, true)) continue;
                        $name = 'rs-' . substr(hash('sha256', (string) $k), 0, 16);
                        $c['rule-providers'][$name] = [
                            'type'     => 'http',
                            'url'      => $url,
                            'proxy'    => 'DIRECT',
                            'interval' => self::ruleSetInterval($time),
                            'behavior' => $behavior,
                            // mihomo знает ровно yaml/text/mrs. На format: yml
                            // (а расширение .yml в ссылке встречается) он
                            // отвечает «unsupported format type: yml» и
                            // отвергает ВЕСЬ конфиг — проверено на 1.19.30.
                            'format'   => match ($format) { 'yml' => 'yaml', 'txt' => 'text', default => $format },
                        ];
                        switch ($target) {
                            case 'REJECT':
                                array_unshift($c['rules'], [
                                    'RULE-SET', $name, $target
                                ]);
                                break;

                            case 'DIRECT':
                                // Как в sing-box: прямые исключения после
                                // блокировки, перед списками VPN.
                                $position = 0;
                                foreach ($c['rules'] as $rule) {
                                    if (!in_array($rule['action'] ?? $rule[2] ?? '', ['REJECT', 'REJECT-DROP'], true)) break;
                                    $position++;
                                }
                                array_splice($c['rules'], $position, 0, [['RULE-SET', $name, $target]]);
                                break;

                            default:
                                $position = count($c['rules']);
                                foreach ($c['rules'] as $i => $rule) {
                                    if (($rule['type'] ?? $rule[0] ?? '') === 'MATCH') { $position = $i; break; }
                                }
                                array_splice($c['rules'], $position, 0, [[
                                    'RULE-SET', $name, $target
                                ]]);
                                break;
                        }
                    }
                }
            }
        }
        unset($c['add-rule-providers']);
        if (empty($c['rule-providers'])) {
            unset($c['rule-providers']);
        }
        return $c;
    }

    public function clashRules($c, $uid, $domain)
    {
        $scheme = empty($this->nginxGetTypeCert()) ? 'http' : 'https';
        $hash   = $this->getHashBot();
        foreach ($c['rules'] as $v) {
            if (array_key_exists('list', $v)) {
                if ($v['type'] == 'RULE-SET') {
                    if (!empty($_GET['r']) && $v['name'] == $_GET['r']) {
                        header("Content-Disposition: attachment; filename={$v['name']}.yaml");
                        header('Content-Type: text/yaml');
                        switch ($v['name']) {
                            case 'process':
                            case 'package':
                                echo yaml_emit(['payload' => array_map(fn($e) => "PROCESS-NAME,$e", $v['list'])]);
                                break;

                            default:
                                // array_unique в конце: vk.com и domain:vk.com дают
                                // одно и то же DOMAIN-SUFFIX-правило, 1.2.3.4 и
                                // 1.2.3.4/32 — один IP-CIDR.
                                echo yaml_emit(['payload' => array_values(array_unique(array_filter(array_map(function($e) {
                                    $cl = $this->classifyRouteEntry($e);
                                    if (!$this->routeEntryUsable($cl)) {
                                        return null; // пустое значение / битый IP
                                    }
                                    switch ($cl['kind']) {
                                        case 'ext':   // xray-only .dat — mihomo не понимает
                                        case 'extip':
                                        case 'geosite': // встроенные категории xray —
                                        case 'geoip':   // у mihomo своя geodata, токен чужой
                                            return null;
                                        case 'ip':
                                            $v = $this->ipWithCidr($cl['value']);
                                            // mihomo/Clash: IPv6 требует правило IP-CIDR6.
                                            return (str_contains($v, ':') ? 'IP-CIDR6,' : 'IP-CIDR,') . $v;
                                        case 'regexp':
                                            return "DOMAIN-REGEX,{$cl['value']}";
                                        case 'keyword':
                                            return 'DOMAIN-KEYWORD,' . mb_strtolower($cl['value']);
                                        case 'full':
                                            return 'DOMAIN,' . $this->hostCanon($cl['value']);
                                        default: // domain, suffix
                                            return 'DOMAIN-SUFFIX,' . $this->hostCanon($cl['value']);
                                    }
                                }, $v['list']), fn($r) => $r !== null)))]);
                                break;

                        }
                        exit;
                    }
                    $c['rule-providers'][$v['name']] = [
                        'type'     => 'http',
                        'url'      => "$scheme://{$domain}/pac$hash/" . base64_encode(serialize([
                            'h' => $hash,
                            't' => 'cl',
                            's' => $uid,
                            'r' => $v['name'],
                        ])),
                        'interval' => $v['interval'],
                        // Загрузка правил не должна зависеть от правил,
                        // которые ещё не загружены, и выбранного VPN-узла.
                        'proxy'    => 'DIRECT',
                        'behavior' => $v['behavior'],
                        'format'   => 'yaml',
                    ];
                    $tmp[] = "{$v['type']}, {$v['name']}, {$v['action']}";
                } else {
                    if (!empty($v['list'])) {
                        foreach ($v['list'] as $j) {
                            $tmp[] = "{$v['type']}, $j, {$v['action']}";
                        }
                    }
                }
            } else {
                $tmp[] = implode(', ', $v);
            }
        }
        $c['rules'] = $tmp;
        return $c;
    }

    /**
     * Parse the server's Cloudflare WARP wgcf profile (/etc/warp/wgcf-profile.conf,
     * IPv6 already stripped by start_wp.sh) into the fields a mihomo wireguard
     * proxy needs. Returns false when the profile is missing/unreadable so callers
     * can fall back gracefully.
     */
    // Разбор wgcf-profile.conf в поля, которые нужны клиентским конфигам.
    // Вынесено из getWarpProfile(), потому что теперь тем же разбором читаются
    // и персональные профили клиентов (warpClientProfile).
    public function parseWarpProfile($conf)
    {
        $conf = (string) $conf;
        if ($conf === '' || !str_contains($conf, '[Peer]')) {
            return false;
        }
        $val = function ($key) use ($conf) {
            return preg_match('~^\s*' . $key . '\s*=\s*(.+?)\s*$~mi', $conf, $m) ? trim($m[1]) : null;
        };
        $endpoint   = $val('Endpoint');
        $privateKey = $val('PrivateKey');
        $publicKey  = $val('PublicKey');
        $address    = $val('Address');
        if (empty($endpoint) || empty($privateKey) || empty($publicKey) || empty($address)) {
            return false;
        }
        // endpoint is host:port, but tolerate an IPv6 literal like [2606:..]:2408
        if (preg_match('~^\[(.+)\]:(\d+)$~', $endpoint, $em)) {
            $server = $em[1];
            $port   = (int) $em[2];
            if (!filter_var($server, FILTER_VALIDATE_IP, FILTER_FLAG_IPV6)) return false;
        } elseif (preg_match('~^([^\s:]+):(\d+)$~', $endpoint, $em)) {
            $server = $em[1];
            $port   = (int) $em[2];
        } else {
            return false;
        }
        if ($port < 1 || $port > 65535) return false;
        return [
            'server'      => $server,
            'port'        => $port,
            'ip'          => explode('/', $address)[0],
            'private-key' => $privateKey,
            'public-key'  => $publicKey,
            'mtu'         => (int) ($val('MTU') ?: 1280),
        ];
    }

    // Каталог персонального WARP-аккаунта клиента внутри тома warp (он же
    // смонтирован в php, поэтому профиль читается напрямую, без ssh).
    // Имя = санитизированный email + хвост sha1: email приходит из Telegram и
    // попадает в shell-команды, а хеш убирает коллизии после санитайза.
    public function warpClientDir($email)
    {
        $email = (string) $email;
        $safe  = substr(preg_replace('~[^a-zA-Z0-9_.\-]~', '_', $email), 0, 32);
        return '/etc/warp/clients/' . $safe . '-' . substr(sha1($email), 0, 8);
    }

    // Персональный WARP-аккаунт клиента: у каждого свой ключ, а не общий
    // серверный. Один и тот же WireGuard-ключ на сервере и у клиентов означал
    // бы, что их сессии выбивают друг друга — у пира в WireGuard ровно один
    // endpoint, и handshake с нового источника переписывает предыдущий.
    //
    // Генерация ленивая (wgcf register — сетевой вызов к API Cloudflare) и
    // выполняется только когда шаблон реально просит warp-теги. Готовый
    // профиль дальше просто читается с тома.
    public const WARP_CLIENT_RETRY = 300;

    public function warpClientProfile($email)
    {
        $email = (string) $email;
        if ($email === '') {
            return false;
        }
        return $this->withLock('warp-client-' . sha1($email), function () use ($email) {
            if (array_key_exists($email, $this->warpclients)) return $this->warpclients[$email];
            $dir = $this->warpClientDir($email);
            $prof = $this->parseWarpProfile(@file_get_contents("$dir/wgcf-profile.conf"));
            if ($prof !== false) return $this->warpclients[$email] = $prof;
            // Неудачная регистрация не повторяется на каждой выдаче подписки:
            // иначе каждое обновление — SSH в wp и запрос к Cloudflare, который
            // ограничивает регистрации с одного адреса.
            $retry = "$dir.retry";
            if ((int) @file_get_contents($retry) > time()) return $this->warpclients[$email] = false;
            $d = escapeshellarg($dir);
            $key = (string) ($this->getPacConf()['warp'] ?? '');
            $lic = preg_match('~^[A-Za-z0-9-]+$~', $key)
                ? "sed -i 's/^license_key.*/license_key = \"$key\"/' wgcf-account.toml && "
                    . 'wgcf update --config wgcf-account.toml >/dev/null 2>&1 && '
                : '';
            $name = escapeshellarg('vpnbot-' . substr(preg_replace('~[^a-zA-Z0-9_.\-]~', '_', $email), 0, 32));
            $this->ssh(
                "umask 077; mkdir -p $d && cd $d && "
                    . "{ [ -s wgcf-account.toml ] || wgcf register --accept-tos --config wgcf-account.toml --name $name >/dev/null 2>&1; } && "
                    . 'chmod 600 wgcf-account.toml && ' . $lic
                    . 'rm -f wgcf-profile.conf && wgcf generate --config wgcf-account.toml --profile wgcf-profile.conf >/dev/null 2>&1 && '
                    . "chmod 600 wgcf-profile.conf && WGCF_CONF=$d/wgcf-profile.conf sh /warp_fixup.sh",
                'wp'
            );
            // Сохраняем аккаунт при сетевой ошибке: повтор генерирует профиль
            // из тех же credentials, не регистрируя ещё одно устройство.
            $prof = $this->parseWarpProfile(@file_get_contents("$dir/wgcf-profile.conf"));
            if ($prof === false) @file_put_contents($retry, (string) (time() + self::WARP_CLIENT_RETRY));
            else @unlink($retry);
            return $this->warpclients[$email] = $prof;
        });
    }

    // Удаляем локальный профиль. Это не удаление устройства из Cloudflare API.
    public function deleteWarpClient($email)
    {
        if ((string) $email === '') return;
        $this->withLock('warp-client-' . sha1((string) $email), function () use ($email) {
            unset($this->warpclients[(string) $email]);
            $this->ssh('rm -rf ' . escapeshellarg($this->warpClientDir($email)), 'wp');
            @unlink($this->warpClientDir($email) . '.retry');
        });
    }

    public function getWarpProfile()
    {
        // Cache per request: this runs on every config download (all types), and
        // when the profile is absent the ssh fallback below would otherwise fire
        // each time. null = not loaded yet; false/array = resolved result.
        if ($this->warpprofile !== null) {
            return $this->warpprofile;
        }
        $conf = @file_get_contents('/etc/warp/wgcf-profile.conf');
        if (empty($conf)) {
            // /etc/warp is mounted into this container, but fall back to the wp
            // container over ssh just in case the volume isn't present.
            $conf = $this->ssh('cat /etc/warp/wgcf-profile.conf 2>/dev/null', 'wp');
        }
        return $this->warpprofile = $this->parseWarpProfile($conf);
    }

    public function replaceTags($subject, $tags)
    {
        $keys = [];
        $vals = [];
        foreach ($tags as $k => $v) {
            $keys[] = $k;
            // Ключи вида "~pac~" (вместе с кавычками) заменяют JSON-значение
            // целиком — их подставляем как есть. Голые ~outbound~/~domain~ стоят
            // ВНУТРИ строкового литерала уже сериализованного JSON, поэтому
            // значение надо экранировать по правилам JSON: одна кавычка в имени
            // аутбаунда (setMainOutbound принимает любой текст из Telegram) рвала
            // документ, json_decode возвращал null, и подписки у ВСЕХ клиентов
            // молча отдавали пустое тело с HTTP 200.
            $raw    = strlen($k) > 1 && '"' === $k[0] && '"' === $k[strlen($k) - 1];
            $vals[] = $raw
                ? $v
                // substr, а не trim: значение может само оканчиваться на \" —
                // trim('"') съел бы и экранированную кавычку.
                : substr(json_encode((string) $v, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES), 1, -1);
        }
        return str_replace($keys, $vals, $subject);
    }

    public function addRuleSet($route)
    {
        if (!empty($route['rules'])) {
            foreach ($route['rules'] as $k => $v) {
                if (!empty($v['addruleset'])) {
                    $ob      = ($v['outbound'] ?? '') ?: 'block';
                    $t[$ob]  = $k;
                    // Имя основного аутбаунда несёт флаг-префикс страны
                    // ("🇫🇷 proxy" через flagName/~outbound~), а ключ rulessetlist
                    // использует логическое имя ("proxy"). Регистрируем и его,
                    // иначе isset($t[$type]) не срабатывает и proxy:-теги теряются.
                    $base = preg_replace('~^[\x{1F1E6}-\x{1F1FF}]+\s+~u', '', $ob);
                    if ($base !== '' && $base !== $ob) {
                        $t[$base] = $k;
                    }
                }
            }
            $p = $this->getPacConf();
            if (!empty($p['rulessetlist'])) {
                foreach ($p['rulessetlist'] as $k => $v) {
                    if (!empty($v)) {
                        // Разбор общий с addClashRuleSet: обе формы ключа
                        // (с behavior и без) читаются одинаково — behavior здесь
                        // просто не нужен, он есть только у mihomo.
                        if (($e = self::parseRuleSetKey((string) $k)) === null) {
                            continue;
                        }
                        [$type, $time, $url] = [$e['outbound'], $e['interval'], $e['url']];
                        if (in_array(strtolower($type), ['block', 'reject', 'proxy', 'direct'], true)) {
                            $type = strtolower($type) === 'reject' ? 'block' : strtolower($type);
                        }
                        $format = self::ruleSetFormat($url);
                        if (isset($t[$type]) && in_array($format, ['srs', 'json'], true) && !empty($route['rules'][$t[$type]])) {
                            $route['rule_set'][] = [
                                "tag"             => $k,
                                "type"            => "remote",
                                "format"          => $format === 'json' ? 'source' : 'binary',
                                "url"             => $url,
                                // http_client вместо download_detour (legacy с
                                // 1.14, снимут в 1.16). БЕЗ detour: он бы
                                // ссылался на аутбаунд "direct", а тот в
                                // шаблонах сплошь и рядом пустой — например
                                // {"type":"direct","tag":"direct",
                                // "tcp_fast_open":false}, где false это нулевое
                                // значение. Ядро 1.14 такую ссылку отвергает
                                // ("detour to an empty direct outbound makes no
                                // sense") и НИ ОДИН rule-set не скачивается.
                                // Клиент без detour дозванивается сам, минуя
                                // маршрутизацию, — то же, что давал
                                // download_detour: "direct".
                                // connect_timeout здесь не ради таймаута: у
                                // пустого объекта ядро откатывается на legacy-
                                // дефолт (дефолтный аутбаунд + предупреждение о
                                // депрекации), а дефолтным может оказаться и
                                // прокси. Одно ненулевое поле это выключает.
                                "http_client"     => ["connect_timeout" => "10s"],
                                "update_interval" => self::ruleSetInterval($time) . 's',
                            ];
                            $route['rules'][$t[$type]]['rule_set'][] = $k;
                        }
                    }
                }
            }
            foreach ($route['rules'] as $k => $v) {
                unset($route['rules'][$k]['addruleset']);
            }
        }
        return $route;
    }

    // Удаляет из dns.rules/route.rules ссылки на rule_set, для которых нет
    // определения в route.rule_set. sing-box отвергает конфиг целиком при
    // ссылке на несуществующий rule-set ("rule-set not found"); лучше тихо
    // пропустить незарегистрированный набор, чем сломать импорт.
    public function pruneRuleSetRefs($c)
    {
        $defined = array_flip(array_column($c['route']['rule_set'] ?? [], 'tag'));
        foreach (['dns', 'route'] as $sec) {
            if (empty($c[$sec]['rules'])) {
                continue;
            }
            foreach ($c[$sec]['rules'] as $k => $v) {
                if (!array_key_exists('rule_set', $v)) {
                    continue;
                }
                $kept = array_values(array_filter(
                    (array) $v['rule_set'],
                    fn($tag) => isset($defined[$tag])
                ));
                if (empty($kept)) {
                    // Все ссылки висячие — правило было rule_set-селектором;
                    // удаляем целиком, иначе останется условие-без-условия,
                    // матчащее весь трафик.
                    unset($c[$sec]['rules'][$k]);
                } else {
                    $c[$sec]['rules'][$k]['rule_set'] = $kept;
                }
            }
            $c[$sec]['rules'] = array_values($c[$sec]['rules']);
        }
        return $c;
    }

    public function cleanEmptyKeys(array $arr)
    {
        // Был ли массив СПИСКОМ до чистки: unset() внутри списка оставляет дыру
        // в нумерации, и json_encode отдаёт объект вместо массива —
        // {"rules":{"1":{…}}} вместо [ … ]. Такой rule-set `sing-box rule-set
        // compile` не принимает вовсе (достижимо при пустом "~pac~").
        $isList = array_is_list($arr);
        foreach ($arr as $k => $v) {
            if (empty($v)) {
                unset($arr[$k]);
            } elseif (is_array($v)) {
                $arr[$k] = $this->cleanEmptyKeys($v);
                if (empty($arr[$k])) {
                    unset($arr[$k]);
                }
            }
        }
        return $isList ? array_values($arr) : $arr;
    }

    /**
     * Раскладывает записи pac-списка по полям sing-box rule-set с учётом
     * префиксов маршрутизации. Порядок ключей задаёт форму итогового правила.
     *
     * Вынесено из createSrs() отдельным методом: та функция пишет заголовки и
     * заканчивается exit, так что покрыть раскладку тестом иначе невозможно.
     *
     * @return array<string,array>
     */
    public function srsBuckets(array $entries): array
    {
        $buckets = [
            'domain_regex'   => [],
            'domain_keyword' => [],
            'domain'         => [], // exact-match (full:)
            'domain_suffix'  => [],
            'ip_cidr'        => [],
        ];
        foreach ($entries as $j) {
            $cl = $this->classifyRouteEntry($j);
            if (!$this->routeEntryUsable($cl)) {
                continue; // пустое значение / битый IP
            }
            switch ($cl['kind']) {
                case 'ext':   // xray-only .dat — sing-box не понимает, пропускаем
                case 'extip':
                case 'geosite': // встроенные категории xray: в sing-box их роль
                case 'geoip':   // играют rule-set'ы, голый токен невалиден
                    continue 2;
                case 'ip':
                    $buckets['ip_cidr'][] = $this->ipWithCidr($cl['value']);
                    break;
                case 'regexp':
                    $buckets['domain_regex'][] = $cl['value'];
                    break;
                case 'keyword':
                    $buckets['domain_keyword'][] = mb_strtolower($cl['value']);
                    break;
                case 'full':
                    $buckets['domain'][] = $this->hostCanon($cl['value']);
                    break;
                default: // domain, suffix
                    $buckets['domain_suffix'][] = $this->hostCanon($cl['value']);
                    break;
            }
        }
        // vk.com и domain:vk.com дают один и тот же domain_suffix, 1.2.3.4 и
        // 1.2.3.4/32 — один ip_cidr: в скомпилированный rule-set они должны
        // попасть по разу.
        return array_map(fn($v) => array_values(array_unique($v)), $buckets);
    }

    public function normalizeSrsRules(array $rules): array
    {
        $result = [];
        foreach ($rules as $rule) {
            if (array_key_exists('domain_suffix', $rule)) {
                $buckets = array_filter($this->srsBuckets((array) $rule['domain_suffix']));
                if (!$buckets) continue;
                unset($rule['domain_suffix']);
                foreach ($buckets as $field => $values) {
                    $rule[$field] = array_values(array_unique(array_merge((array) ($rule[$field] ?? []), $values)));
                }
            }
            if (array_key_exists('ip_cidr', $rule)) {
                $values = array_filter((array) $rule['ip_cidr'], [self::class, 'ipOrCidr']);
                if (!$values) continue;
                $rule['ip_cidr'] = array_values(array_unique(array_map(fn($ip) => $this->ipWithCidr($ip), $values)));
            }
            foreach (['process_name', 'package_name'] as $field) {
                if (array_key_exists($field, $rule) && !$rule[$field]) continue 2;
            }
            $rule = $this->cleanEmptyKeys($rule);
            if ($rule) $result[] = $rule;
        }
        return $result;
    }

    public function createSrs(string $name, array $rules)
    {
        $rules = $this->normalizeSrsRules($rules);
        // $name — имя rule-set'а ИЗ ШАБЛОНА маршрутов (createruleset[].name), то
        // есть данные, а не константа: шаблон приходит из webapp-редактора и из
        // импорта чужих настроек. Раньше оно шло без экранирования и в заголовок
        // (перевод строки = инъекция заголовков), и в имя файла, которое
        // подставлялось в exec() — то есть импорт чужого шаблона означал
        // исполнение произвольных команд в контейнере. Имя ограничиваем словом,
        // путь строим сами и в команду отдаём через escapeshellarg().
        if (!preg_match('~^[\w.\-]{1,64}$~', $name)) {
            http_response_code(400);
            header('Content-Type: text/plain; charset=utf-8');
            echo 'Invalid rule-set name';
            exit;
        }
        header("Content-Disposition: attachment; filename=$name.srs");
        header('Content-Type: application/binary');
        $f = '/tmp/' . $name . '.' . getmypid() . '.' . bin2hex(random_bytes(6));
        file_put_contents($f, json_encode([
            'version' => 1,
            'rules'   => array_values($rules),
        ]));
        exec('sing-box rule-set compile ' . escapeshellarg($f) . ' 2>&1', $out, $code);
        // Раньше результат компиляции не проверялся: при любом сбое клиент
        // получал HTTP 200 с пустым телом (и два warning'а от unlink()) —
        // ядро молча оставалось без правил вместо явной ошибки.
        if ($code !== 0 || !is_file("$f.srs")) {
            error_log("createSrs: compile failed for $name — " . implode(' ', (array) $out));
            @unlink($f);
            http_response_code(500);
            header('Content-Type: text/plain; charset=utf-8');
            echo 'Rule-set compile failed';
            exit;
        }
        echo file_get_contents("$f.srs");
        unlink($f);
        unlink("$f.srs");
        exit;
    }

    public function createRuleSet($route, $uid, $domain)
    {
        $scheme = empty($this->nginxGetTypeCert()) ? 'http' : 'https';
        $hash   = $this->getHashBot();
        $ruleset = [];

        foreach ($route['rules'] ?? [] as $k => $v) {
            if (!empty($v['createruleset'])) {
                foreach ($v['createruleset'] as $r) {
                    if (!empty($_GET['r']) && $r['name'] == $_GET['r']) {
                        $this->createSrs($r['name'], $r['rules']);
                    }
                    $ruleset[] = [
                        "tag"             => $r['name'],
                        "url"             => "$scheme://{$domain}/pac$hash/" . base64_encode(serialize([
                            'h' => $hash,
                            't' => 'si',
                            's' => $uid,
                            'r' => $r['name'],
                        ])),
                        "update_interval" => $r['interval'],
                        "type"            => "remote",
                        "format"          => "binary",
                        // см. addRuleSet(): download_detour снят в пользу
                        // http_client (legacy с 1.14, удаляют в 1.16), detour
                        // не используется — он ломается о пустой аутбаунд
                        // "direct" в шаблоне.
                        "http_client"     => ["connect_timeout" => "10s"],
                    ];
                    $route['rules'][$k]['rule_set'][] = $r['name'];
                }
                unset($route['rules'][$k]['createruleset']);
                if (empty($route['rules'][$k]['rule_set'])) {
                    unset($route['rules'][$k]);
                }
            }
        }
        if (!empty($route['rules'])) {
            $route['rules']    = array_values($route['rules']);
        }
        $route['rule_set'] = array_merge($route['rule_set'] ?? [], $ruleset);
        if (empty($route['rule_set'])) {
            unset($route['rule_set']);
        }
        return $route;
    }

    // null — «конфиг прочитать не удалось» (файла нет, битый JSON, скаляр).
    // Раньше отдавалось всё, что вернул json_decode: строка или число из
    // повреждённого файла доезжали до `$xr['inbounds'][0]` и давали не
    // диагностируемый набор warning'ов вместо явного отказа. Вызывающие,
    // которым null неприемлем, проверяют его — см. backfillSubTokens(),
    // refreshExtSubCache(), sub(), subscription().
    public function getXray()
    {
        $c = json_decode($this->readXrayJson(), true);
        return is_array($c) ? $c : null;
    }

    // Читает xray.json под LOCK_SH — парой к LOCK_EX из writeXrayJson().
    // Без лока читатель ловил файл между ftruncate() и fwrite(): в /config/
    // лежат десятки килобайт клиентов, окно реальное, а json_decode('') = null.
    public function readXrayJson(): string
    {
        $h = @fopen($this->xrayConf, 'r');
        if (false === $h) {
            return '';
        }
        // Лок не взялся (например, файл на ФС без flock) — читаем как раньше:
        // риск порванного чтения лучше гарантированно пустого конфига.
        $locked = flock($h, LOCK_SH);
        $data   = (string) stream_get_contents($h);
        if ($locked) {
            flock($h, LOCK_UN);
        }
        fclose($h);

        return $data;
    }

    /** Валидный хостнейм — единственное, что можно пускать в nginx-конфиг. */
    public function isHostname($d): bool
    {
        return (bool) preg_match('~^[a-zA-Z0-9]([a-zA-Z0-9.-]*[a-zA-Z0-9])?$~', (string) $d);
    }

    // Хостнейм или IP — то, что допустимо положить в адрес relay: значение
    // уходит и в клиентские ссылки, и в tcpProbe(), и в разметку меню.
    public function isHostOrIp($v): bool
    {
        $v = trim((string) $v);
        return $v !== '' && strlen($v) <= 253
            && ($this->isHostname($v) || filter_var($v, FILTER_VALIDATE_IP) !== false);
    }

    // Экранирование для parse_mode=HTML. Сообщения бота собираются из значений,
    // которые пришли из ввода (имена пиров, адреса relay, пароли dnstt, тексты
    // ошибок сети с именем хоста внутри): один символ «<» делает разметку
    // невалидной, Telegram отвечает 400, и экран перестаёт открываться —
    // навсегда, потому что значение уже лежит в pac.json, а починить его можно
    // только с этого же экрана.
    public static function esc($v): string
    {
        return htmlspecialchars((string) $v, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
    }

    public function setUpstreamDomain($domain)
    {
        // $domain правится из Telegram (reality.domain/serverNames) и попадает в
        // replacement preg_replace, где «$1»/«\1» — обратные ссылки, а затем в
        // конфиг nginx. Битый конфиг `nginx -s reload` не применит, поэтому
        // поломка всплыла бы только при следующем рестарте контейнера — 443 не
        // поднимется и весь внешний доступ ляжет.
        if (!$this->isHostname($domain)) {
            return false;
        }
        return $this->editUpstream(fn($nginx) => self::upstreamReplace($nginx, '#domain', "$domain reality;"));
    }

    /**
     * Заменяет тело парного маркерного блока в /config/upstream.conf
     * («#naive … #naive», «#ocserv … #ocserv»).
     *
     * Два требования, каждое из которых уже стоило поломки:
     *  - НЕЖАДНЫЙ .+?: маркер парный, и любое ТРЕТЬЕ его упоминание ниже по
     *    файлу (достаточно слова в комментарии) при жадном матче расширяет
     *    замену до него и сносит всё между — включая соседние server-блоки;
     *  - preg_replace_CALLBACK: тело подставляется литералом, а в replacement
     *    у preg_replace «$1»/«\1» — обратные ссылки, и поддомен с доменом
     *    приходят из пользовательского ввода.
     * Для #naive это уже было исправлено, для #ocserv — нет, хотя комментарий
     * рядом описывал правку как общую.
     */
    public static function upstreamReplace(string $nginx, string $marker, string $body): string
    {
        $m = preg_quote($marker, '~');
        return (string) preg_replace_callback(
            "~$m.+?$m~s",
            fn() => "$marker\n$body\n$marker",
            $nginx,
        );
    }

    public static function ocservDtlsUpstream(string $conf): string
    {
        // Мигрируем только прежний штатный блок: произвольные UDP-прокси
        // администратора не меняем. DTLS не несёт TCP TLS ClientHello/SNI.
        return preg_replace(
            '~server\s*\{\s*listen\s+443\s+udp\s*;\s*proxy_pass\s+\$sni_name\s*;\s*proxy_protocol\s+on\s*;\s*ssl_preread\s+on\s*;\s*\}~',
            "server {\n        listen 443 udp reuseport;\n        proxy_pass ocserv;\n    }",
            $conf
        ) ?? $conf;
    }

    public function setUpstreamDomainOcserv($domain)
    {
        // Пустая строка — штатный «сброс» (см. вызов при удалении домена),
        // остальное обязано быть хостнеймом: см. комментарий в setUpstreamDomain.
        if ('' !== (string) $domain && !$this->isHostname($domain)) {
            return false;
        }
        $sub   = $this->getHashSubdomain('oc');
        $body  = ($domain && $sub) ? "$sub.$domain ocserv;" : "#$sub.\$domain ocserv;";
        // Ровно те же две правки, что были сделаны для #naive, — сюда они тогда
        // не доехали (см. upstreamReplace).
        return $this->editUpstream(fn($nginx) => self::upstreamReplace(self::ocservDtlsUpstream($nginx), '#ocserv', $body));
    }

    // Хосты, которые upstream-nginx по SNI отдаёт контейнеру naive: основной
    // <hash>.<domain> плюс адреса relay ($pac['relays'][*]['np_address']).
    // Relay нужен здесь ОТДЕЛЬНОЙ строкой, в отличие от vless/hysteria: там
    // подмена адреса не трогает SNI (он берётся из конфига клиента), а клиент
    // naive берёт SNI из хоста ссылки — на origin после DNAT приходит SNI
    // relay-домена. Без своей строки в map он попадает в `default other`
    // (cloak-nginx), и вместо прокси клиент получает маскировочный сайт.
    // Отсеиваем: не-хостнеймы и голые IP (по IP клиент SNI не шлёт) и сам
    // основной домен — отдать его в naive значит увести туда панель,
    // подписки и cloak. Чистая функция: конфиг и субдомен передаются извне,
    // чтобы её можно было прогнать тестами без инстанса.
    public static function naiveSniHosts(string $sub, string $domain, array $conf): array
    {
        $hosts = [];
        if ($sub !== '' && $domain !== '') {
            $hosts[] = "$sub.$domain";
        }
        $main = trim((string) ($conf['domain'] ?? ''));
        foreach ($conf['relays'] ?? [] as $r) {
            $h = trim((string) ($r['np_address'] ?? ''));
            if ($h === '' || $h === $main || filter_var($h, FILTER_VALIDATE_IP)) {
                continue;
            }
            if (preg_match('~^[a-zA-Z0-9]([a-zA-Z0-9.-]*[a-zA-Z0-9])?$~', $h)) {
                $hosts[] = $h;
            }
        }
        return array_values(array_unique($hosts));
    }

    public function setUpstreamDomainNaive($domain)
    {
        // См. setUpstreamDomainOcserv: пустая строка допустима, мусор — нет.
        if ('' !== (string) $domain && !$this->isHostname($domain)) {
            return false;
        }
        $sub   = $this->getHashSubdomain('np');
        // Строк может быть несколько: основной поддомен + адреса relay для
        // naive (naiveSniHosts). Пусто — закомментированный плейсхолдер, как до
        // задания домена.
        $hosts = $domain ? self::naiveSniHosts($sub, (string) $domain, $this->getPacConf()) : [];
        $body  = $hosts
            ? implode("\n", array_map(fn($h) => "$h naive;", $hosts))
            : "#$sub.\$domain naive;";
        return $this->editUpstream(fn($nginx) => self::upstreamReplace($nginx, '#naive', $body));
    }

    // Ключ просмотра changelog. Страница показывает историю коммитов
    // приватного репозитория, а адрес /pac<hash> знает любой владелец
    // подписки: без ключа из кнопки администратора отдаётся только прежний
    // общий список версий.
    public function changelogKey(): string
    {
        return substr(hash_hmac('sha256', 'vpnbot-changelog', (string) $this->key), 0, 32);
    }

    public function changelogUrl(): string
    {
        $domain = $this->getPacConf()['domain'] ?: $this->ip;
        return "https://$domain/pac" . $this->getHashBot() . '?t=changelog&k=' . $this->changelogKey();
    }

    // Текст changelog из истории своего репозитория: что установлено и какие
    // изменения уже есть в ветке, но ещё не установлены. Файл version ведёт
    // исходный проект, изменений этой сборки в нём нет — он идёт в конце.
    public function changelogBuild(string $repo = '/'): string
    {
        $git = 'git -C ' . escapeshellarg($repo) . ' ';
        $branch = trim((string) shell_exec($git . 'rev-parse --abbrev-ref HEAD 2>/dev/null'));
        $legacy = trim((string) @file_get_contents(rtrim($repo, '/') . '/version'));
        if ($branch === '' || !preg_match('~^[\w./-]+$~', $branch)) {
            return $legacy;
        }
        shell_exec($git . 'fetch -q 2>/dev/null');
        $format = '--no-merges --date=short ' . escapeshellarg('--format=%h%x09%ad%x09%s');
        $rows = static function (string $out): array {
            $rows = [];
            foreach (array_filter(explode("\n", trim($out)), 'strlen') as $line) {
                $part = explode("\t", $line, 3);
                if (count($part) === 3) {
                    $rows[] = $part;
                }
            }
            return $rows;
        };
        $remote  = escapeshellarg("origin/$branch");
        $pending = $rows((string) shell_exec($git . "log -n 100 $format HEAD..$remote 2>/dev/null"));
        $done    = $rows((string) shell_exec($git . "log -n 60 $format HEAD 2>/dev/null"));
        if (!$done) {
            return $legacy;
        }
        $line = static fn(array $row) => "$row[1]  $row[2]";
        $text = ['vpnbot · ' . $this->i18n('changelog branch') . ' ' . $branch,
            $this->i18n('changelog installed') . ': ' . $done[0][0] . ' · ' . $done[0][1]];
        if ($pending) {
            $text[] = $this->i18n('changelog available') . ': ' . $pending[0][0] . ' · ' . $pending[0][1];
            $text[] = '';
            $text[] = mb_strtoupper($this->i18n('changelog pending')) . ' (' . count($pending) . ')';
            $text[] = $this->i18n('changelog pending note');
            $text = array_merge($text, array_map($line, $pending));
        } else {
            $text[] = $this->i18n('changelog up to date');
        }
        $text[] = '';
        $text[] = mb_strtoupper($this->i18n('changelog history'));
        $text = array_merge($text, array_map($line, $done));
        if ($legacy !== '') {
            $text[] = '';
            $text[] = mb_strtoupper($this->i18n('changelog upstream'));
            $text[] = $legacy;
        }
        return implode("\n", $text) . "\n";
    }

    public function getHashBot($notset = false)
    {
        $p = $this->getPacConf();
        if (!empty($p['hashbot'])) return $p['hashbot'];
        $hash = substr(hash('sha256', $this->key), 0, 8);
        if ($notset) return $hash;
        return $this->pacConfUpdate(function (&$p) use ($hash) {
            if (empty($p['hashbot'])) $p['hashbot'] = $hash;
            return $p['hashbot'];
        });
    }

    // /ws и /grpc ведут на один xr:443. Только транспорт фактического inbound
    // может принимать запросы: HTTP/1-ответ WS нельзя читать как HTTP/2 frame.
    // Старые ссылки получают 404, пока пользователь не обновит подписку.
    // Чужие backend/location и другие inbound Xray не изменяются.
    //
    // В /ws две строки обработчика с метками, активна одна: WebSocket — через
    // proxy_pass (HTTP/1.1 с Upgrade, так у XTLS/Xray-examples VLESS-WSS-Nginx),
    // XHTTP — через grpc_pass, то есть HTTP/2 без TLS до Xray. Это официальная
    // схема XHTTP за nginx для stream-up и stream-one (XTLS/Xray-core#4113:
    // «proxy_pass заменить на grpc_pass»); packet-up через неё тоже проходит,
    // поэтому старые подписки после переключения продолжают работать.
    // Установки до разметки получают строки здесь же (и в холодной миграции
    // protocol_modules.py — тот же результат).
    // client_body_timeout: в stream-up тело POST — весь поток выгрузки, и при
    // скачивании без выгрузки умолчание nginx (60 с между чтениями) рвало
    // туннель на 60–80-й секунде (замер 2026-10-31). Простой ограничивает сам
    // Xray (connIdle 300 с), как в официальных примерах XTLS/Xray-examples.
    // packet-up (/ws/session/seq) читает тело до проверки VLESS: для него
    // оставляем 60 с. Это относится и к некорректному номеру пакета.
    public const NGINX_XRAY_H1  = 'vpnbot-xray-h1';
    public const NGINX_XHTTP_H2 = 'vpnbot-xhttp-h2';
    public const NGINX_XHTTP_LINES = [
        'proxy_pass http://xr_backend; # vpnbot-xray-h1',
        '# grpc_pass grpc://xr_backend; # vpnbot-xhttp-h2',
        'grpc_set_header Host $host;',
        'grpc_set_header X-Real-IP $remote_addr;',
        'grpc_set_header X-Forwarded-For $remote_addr;',
        'grpc_socket_keepalive on;',
        'grpc_read_timeout 5d;',
        'grpc_send_timeout 5d;',
        'client_body_timeout 5d;',
        '# location ~ ^/[^/]+/[^/]+/[^/]+ { grpc_pass grpc://xr_backend; client_body_timeout 60s; } # vpnbot-xhttp-packet-timeout',
    ];

    public static function xrayNginxRoutes(string $text, array $xray): string
    {
        $networks = [];
        foreach ($xray['inbounds'] ?? [] as $inbound) {
            $stream = $inbound['streamSettings'] ?? [];
            $listen = (string) ($inbound['listen'] ?? '');
            if ((string) ($inbound['port'] ?? '') === '443'
                && in_array($stream['security'] ?? '', ['', 'none'], true)
                && $listen !== '::1' && !str_starts_with($listen, '127.')) {
                $networks[] = $stream['network'] ?? '';
            }
        }
        $text = preg_replace('~^[ \t]*(?:#[ \t]*)?return 404; # vpnbot-inactive-xray-route\r?\n~m', '', $text);
        return preg_replace_callback('~(^[ \t]*(?:#[ \t]*)?location[ \t]+/(ws|grpc)[A-Za-z0-9_-]*[ \t]*\{)(.*?^[ \t]*(?:#[ \t]*)?\})~ms',
            static function ($m) use ($networks) {
                $backend = $m[2] === 'grpc' ? '~\bgrpc_pass\s+grpc://xr:443\s*;~' : '~\bproxy_pass\s+http://xr_backend\s*;~';
                if (!preg_match($backend, $m[3])) return $m[0];
                preg_match('~^([ \t]*(?:#[ \t]*)?)location~', $m[1], $prefix);
                $body = $m[2] === 'ws'
                    ? self::xrayNginxHandler($m[3], str_contains($prefix[1], '#'), in_array('xhttp', $networks, true))
                    : $m[3];
                $active = $m[2] === 'grpc' ? in_array('grpc', $networks, true) : (bool) array_intersect(['ws', 'xhttp'], $networks);
                if ($active) return $m[1] . $body;
                return $m[1] . "\n" . $prefix[1] . '    return 404; # vpnbot-inactive-xray-route' . $body;
            }, $text);
    }

    // $commented — блок целиком закомментирован (копия #-domain): к его «#»
    // добавляется или снимается второй.
    private static function xrayNginxHandler(string $body, bool $commented, bool $h2): string
    {
        $lead = $commented ? '[ \t]*#[ \t]*' : '[ \t]*';
        $body = preg_replace_callback('~^(' . $lead . ')proxy_pass\s+http://xr_backend\s*;[ \t]*$~m',
            static fn($l) => implode("\n", array_map(static fn($line) => $l[1] . $line, self::NGINX_XHTTP_LINES)), $body, 1);
        // Обновление уже размеченного HTTP/2-блока; старые строки сохраняются.
        if (!str_contains($body, 'vpnbot-xhttp-packet-timeout')) {
            $body = preg_replace_callback('~^(' . $lead . ')(?:#[ \t]*)?grpc_pass[^\n]*# ' . self::NGINX_XHTTP_H2 . '[ \t]*$~m',
                static fn($l) => $l[0] . "\n" . $l[1] . self::NGINX_XHTTP_LINES[array_key_last(self::NGINX_XHTTP_LINES)], $body, 1);
        }
        $body = preg_replace_callback('~^(' . $lead . ')(?:#[ \t]*)?(location[^\n]*# vpnbot-xhttp-packet-timeout)[ \t]*$~m',
            static fn($l) => $l[1] . ($h2 ? '' : '# ') . $l[2], $body);
        $want = $h2 ? self::NGINX_XHTTP_H2 : self::NGINX_XRAY_H1;
        return preg_replace_callback('~^(' . $lead . ')(?:#[ \t]*)?((?:proxy|grpc)_pass\s[^\n]*?# (' . self::NGINX_XRAY_H1 . '|' . self::NGINX_XHTTP_H2 . '))[ \t]*$~m',
            static fn($l) => $l[1] . ($l[3] === $want ? '' : '# ') . $l[2], $body);
    }

    // Режим клиентов XHTTP. stream-up (один поток выгрузки вместо потока POST)
    // официально требует grpc_pass, поэтому выдаётся только когда он активен
    // в рабочем nginx.conf (тот же файл смонтирован в ng). Иначе — packet-up,
    // который проходит и через proxy_pass: установка, где миграция не дошла,
    // или свой обработчик /ws.
    public function xhttpClientMode(): string
    {
        $path = dirname($this->xrayConf) . '/nginx.conf';
        $conf = is_file($path) ? (string) file_get_contents($path) : '';
        return preg_match('~^[ \t]*grpc_pass\s[^\n#]*;[ \t]*# ' . self::NGINX_XHTTP_H2 . '[ \t]*$~m', $conf) ? 'stream-up' : 'packet-up';
    }

    public function syncXrayNginxRoutes(array $xray): bool
    {
        $path = dirname($this->xrayConf) . '/nginx.conf';
        if (!is_file($path)) return true;
        return $this->editProtocolProxyConfig($path, 'ng',
            static fn($text) => self::xrayNginxRoutes($text, $xray));
    }

    // Адреса, через которые PHP бота доступен из интернета (/pac, /tlgrm,
    // @php после /webapp), multipart/form-data не принимают: загрузки есть
    // только у веб-панели, а она слушает 127.0.0.1:8090. PHP разбирает такое
    // тело до кода бота, и уязвимость разборщика (PHP2Shell, CVE-2026-109618/
    // 109619) достаётся без входа. Строка ставится и в закомментированные
    // копии блоков (#-domain): uncomment() снимает первый «#». На установке
    // cloakNginx() дописывает к /pac хэш бота — отсюда /pac[0-9A-Za-z]*.
    public const NGINX_PHP_GUARD = 'vpnbot-php-multipart-guard';

    public static function nginxPhpMultipartGuard(string $text): string
    {
        return (string) preg_replace_callback('~^([ \t]*(?:#[ \t]*)?)location[ \t]+(?:/pac[0-9A-Za-z]*|/tlgrm|@php)[ \t]*\{[ \t]*\r?\n(?![ \t]*(?:#[ \t]*)?if \(\$http_content_type[^\n]*' . self::NGINX_PHP_GUARD . ')~m',
            static fn($m) => $m[0] . $m[1] . '    if ($http_content_type ~* "multipart/form-data") { return 415; } # ' . self::NGINX_PHP_GUARD . "\n",
            $text);
    }

    // Установки до защиты: шаблон и рабочий nginx.conf лежат в config/ и при
    // обновлении сохраняются как есть, поэтому строку дописывает cron.
    public function ensureNginxPhpMultipartGuard(): bool
    {
        $root = dirname($this->xrayConf);
        $template = "$root/nginx_default.conf";
        $guard = static function (string $text): string {
            // Upgrade the shipped format on existing installations, preserving other log formats.
            $text = preg_replace_callback('~^[ \t]*log_format[ \t]+(?:noargs|nopath)\s+[^;]+;~m',
                static fn($m) => str_replace(' "$http_user_agent"', '', $m[0]), $text);
            return self::nginxPhpMultipartGuard($text);
        };
        if (is_file($template)) {
            $body = (string) file_get_contents($template);
            $guarded = $guard($body);
            if ($guarded !== $body && !$this->backupWriteInPlace($template, $guarded)) return false;
        }
        if (!is_file("$root/nginx.conf")) return true;
        return $this->editProtocolProxyConfig("$root/nginx.conf", 'ng', $guard);
    }

    public function cloakNginx()
    {
        $conf     = $this->getPacConf();
        $template = file_get_contents('/config/nginx_default.conf');
        // $template = preg_replace('~server_name ip~', "server_name {$this->ip}", $template);
        // Алиасы принимаем тем же server-блоком: серт после «renew SSL» их
        // покрывает, upstream шлёт их сюда через `default other`.
        $aliasNames = '';
        foreach ($conf['domain_aliases'] ?? [] as $a) {
            $aliasNames .= " *.$a $a";
        }
        $template = preg_replace('~server_name domain~', "server_name " . ($conf['domain'] ? " *.{$conf['domain']} {$conf['domain']}$aliasNames" : '_'), $template);
        if ($conf['domain'] && !empty($conf['letsencrypt'])) {
            $template = preg_replace('/#~([^\n]+)?/', "#~{$conf['letsencrypt']}", $template);
            preg_match_all('~#-domain.+?#-domain~s', $template, $m);
            foreach ($m[0] as $v) {
                $template = preg_replace('~#-domain.+?#-domain~s', $this->uncomment($v, 'domain'), $template, 1);
            }
        }
        // WEB-режим telemt: отдельный vhost, целиком уезжающий в telemt (блок
        // #-tgweb в шаблоне). Условие — telemtWebEnabled(), а не голый тумблер:
        // nginx не должен проксировать в листенер, которого telemtToml не
        // создал, иначе на WEB-хосте вместо decoy отвечает 502 — а это
        // заметный отпечаток ровно там, где мы прикидываемся обычным сайтом.
        // Проверка включает и домен, и сертификат, поэтому отдельного условия
        // на них здесь нет.
        $twHost = $this->telemtWebEnabled($conf) ? $this->telemtWebHost($conf) : '';
        $template = preg_replace('~server_name tgweb~', 'server_name ' . ($twHost ?: '_'), $template);
        if ($twHost) {
            preg_match_all('~#-tgweb.+?#-tgweb~s', $template, $m);
            foreach ($m[0] as $v) {
                $template = preg_replace('~#-tgweb.+?#-tgweb~s', $this->uncomment($v, 'tgweb'), $template, 1);
            }
        }
        $h = $this->getHashBot();
        // Пропуск в панель AdGuard проверяет бот (adguardGateCheck): подписанная
        // ключом бота cookie, выданная администратору мини-приложением Telegram
        // или его одноразовой ссылкой. Раньше nginx сравнивал cookie с hash из
        // ссылок подписки — его знает любой подписчик, и панель (а с ней
        // блокировка входа AdGuard на 15 минут для всех после 5 неверных
        // паролей) была открыта каждому, кто сам выставит cookie.
        $r = <<<CONF
        location /adguard/ {
                access_log /logs/nginx_adguard_access noargs;
                auth_request /adguard-gate;
                error_page 401 = @adguardlogin;
                proxy_pass http://ad/;
                proxy_redirect / /adguard/;
                proxy_cookie_path / /adguard/;
                # AdGuardHome отдаёт страницы панели без заголовков кеширования,
                # и браузер (особенно встроенный в Telegram) после обновления
                # образа продолжал показывать прежний интерфейс: на двух
                # серверах с одним и тем же образом панель выглядела по-разному.
                # expires, а не add_header: тот отменил бы заголовки
                # безопасности, заданные уровнем выше.
                expires -1;
            }
            location = /adguard-gate {
                internal;
                access_log off;
                proxy_pass http://php;
                proxy_pass_request_body off;
                proxy_set_header Content-Length "";
                proxy_set_header Host \$http_host;
            }
            location @adguardlogin {
                return 302 /webapp;
            }
            location
        CONF;
        $template = preg_replace('~(location /adguard.+?})\s*location~s', $r, $template);
        $template = preg_replace('~(/webapp|/pac|/adguard|/ws|/grpc|/v2ray|location /dns-query)~', '${1}' . $h, $template);
        if (is_string($template)) $template = self::xrayNginxRoutes($template, $this->getXray() ?? []);
        if (!is_string($template) || $template === '') return false;
        // Ретранслятор Telegram API живёт только в nginx.conf (в шаблоне его
        // нет). Если nginx не принял его блок, домен и остальные сервисы
        // всё равно применяются — ретранслятор покажет «не применён».
        $relay = $this->telegramRelayConf();
        $withRelay = self::telegramRelayNginx($template, $relay);
        if (!$this->editProtocolProxyConfig('/config/nginx.conf', 'ng', static fn($before) => $withRelay)) {
            if ($withRelay === $template) return false;
            error_log('cloakNginx: telegram relay block rejected by nginx, applied without it');
            if (!$this->editProtocolProxyConfig('/config/nginx.conf', 'ng', static fn($before) => $template)) return false;
        }
        $this->xrayConfUpdate(function (&$x) use ($h) {
            foreach (['wsSettings', 'xhttpSettings'] as $kind) {
                if (!empty($x['inbounds'][0]['streamSettings'][$kind]['path'])) $x['inbounds'][0]['streamSettings'][$kind]['path'] = "/ws$h";
            }
            if (!empty($x['inbounds'][0]['streamSettings']['grpcSettings']['serviceName'])) {
                $x['inbounds'][0]['streamSettings']['grpcSettings']['serviceName'] = "grpc$h";
            }
        });

        return trim($this->ssh('nginx -t >/dev/null 2>&1 && nginx -s reload >/dev/null 2>&1 && printf VPNBOT_NGINX_READY', 'ng')) === 'VPNBOT_NGINX_READY';
    }

    // Возвращаемое значение подставляется в «<sub>.<domain>» и уезжает в
    // upstream.conf (nginx) и в default-domain ocserv.conf. Сохранённое ранее
    // значение проверяем на выдаче тоже: в pac.json мог остаться мусор от
    // старых версий, а сломанный upstream.conf валит весь внешний 443 при
    // ближайшем рестарте контейнера (живой nginx reload просто отвергнет).
    public function getHashSubdomain($subdomain)
    {
        $key = "{$subdomain}_domain";
        $p = $this->getPacConf();
        if (isset($p[$key])) return self::isSubdomainLabel($p[$key]) ? $p[$key] : '';
        // Called inside a pac transaction (TeleMT WEB checks): the deterministic
        // label is returned now and persisted by the next call outside the lock.
        if (isset($this->heldLocks['pac'])) {
            $label = substr(hash('sha256', "$subdomain{$this->key}"), 0, 8);
            return self::isSubdomainLabel($label) ? $label : '';
        }
        return $this->pacConfUpdate(function (&$p) use ($subdomain, $key) {
            if (!isset($p[$key])) $p[$key] = substr(hash('sha256', "$subdomain{$this->key}"), 0, 8);
            return self::isSubdomainLabel($p[$key]) ? $p[$key] : '';
        });
    }

    public function addWg($page)
    {
        $text = "Menu -> {$this->getTitleWG()} -> Add peer\n\n";
        $data[] = [
            [
                'text'          =>  $this->i18n('all traffic'),
                'callback_data' => $this->cbWG("/add"),
            ]
        ];
        $data[] = [
            [
                'text'          =>  $this->i18n('subnet'),
                'callback_data' => $this->cbWG("/add_ips"),
            ]
        ];
        if ($this->getPacConf()['subnets']) {
            $data[] = [
                [
                    'text'          =>  $this->i18n('listSubnet'),
                    'callback_data' => $this->cbWG("/addSubnets $page"),
                ]
            ];
        }
        $data[] = [
            [
                'text'          => $this->i18n('back'),
                'callback_data' => "/menu wg {$this->wgNum()} $page",
            ]
        ];
        return [
            'text' => $text,
            'data' => $data,
        ];
    }

    public function adguardBasicAuth()
    {
        return base64_encode('admin:' . $this->getPacConf()['adpswd']);
    }

    // ── Пропуск в веб-панель AdGuard ───────────────────────────────────────
    // Токен «срок.случайное.подпись» с HMAC от ключа бота: подделать без ключа
    // нельзя, срок проверяется. cookie — пропуск браузера в /adguard<hash>/,
    // link — одноразовая ссылка администратору для стороннего браузера.
    public const ADGUARD_LINK_TTL = 900;
    public const ADGUARD_GATE_TTL = self::ADGUARD_LINK_TTL;
    public const ADGUARD_BROWSER_TTL = self::ADGUARD_LINK_TTL;

    protected function adguardGateNow(): int { return time(); }

    public function adguardSetPanelOpen(bool $open): void
    {
        $this->pacConfUpdate(static function (&$conf) use ($open) {
            if (empty($conf['adg_panel_closed']) !== $open) {
                $conf['adg_panel_closed'] = !$open;
                $conf['adg_panel_epoch'] = bin2hex(random_bytes(16));
            }
        });
    }

    private function adguardSignature(string $kind, int $exp, string $nonce, array $conf): string
    {
        $epoch = $conf['adg_panel_epoch'] ?? 'initial';
        if (!empty($conf['adg_panel_closed']) || !is_string($epoch) || (string) $this->key === '') return '';
        $browser = in_array($kind, ['link', 'browser'], true) ? ($conf['adg_browser_epoch'] ?? 'initial') : '';
        if (!is_string($browser)) return '';
        return substr(hash_hmac('sha256', "vpnbot-adguard-v2|$kind|$epoch|$browser|$exp|$nonce", (string) $this->key), 0, 40);
    }

    public function adguardGateSign(string $kind, int $exp, string $nonce): string
    {
        return $this->adguardSignature($kind, $exp, $nonce, $this->getPacConf());
    }

    public function adguardGateToken(string $kind, int $ttl): string
    {
        return $this->adguardTokenUntil($kind, $this->adguardGateNow() + $ttl);
    }

    public function adguardTokenUntil(string $kind, int $deadline): string
    {
        $exp = min($this->adguardGateNow() + self::ADGUARD_GATE_TTL, $deadline);
        $nonce = bin2hex(random_bytes(8));
        return "$exp.$nonce." . $this->adguardGateSign($kind, $exp, $nonce);
    }

    public function adguardGateCheck(string $token, string $kind): bool
    {
        if ((string) $this->key === '' || !in_array($kind, ['cookie', 'link'], true)) return false;
        $now = $this->adguardGateNow();
        if (!preg_match('~^(\d{10})\.([a-f0-9]{16})\.([a-f0-9]{40})$~D', $token, $m) || (int) $m[1] <= $now || (int) $m[1] > $now + self::ADGUARD_GATE_TTL) return false;
        $conf = $this->getPacConf();
        if (hash_equals($this->adguardSignature($kind, (int) $m[1], $m[2], $conf), $m[3])) return true;
        return $kind === 'cookie' && !empty($conf['adgbrowser']) && hash_equals($this->adguardSignature('browser', (int) $m[1], $m[2], $conf), $m[3]);
    }

    // Ссылка действует один раз: случайная часть запоминается до истечения
    // срока, повторный переход по ней (пересланное сообщение) отклоняется.
    public function adguardLinkConsume(string $token): bool
    {
        if (!$this->adguardGateCheck($token, 'link')) return false;
        [$exp, $nonce] = explode('.', $token);
        $f = $this->adguardLinksFile();
        if (is_link($f) || is_link($f . '.lock')) return false;
        $lock = @fopen($f . '.lock', 'c');
        if ($lock === false) return false;
        @chmod($f . '.lock', 0600);
        $temporary = null;
        try {
            $until = microtime(true) + 5;
            while (!flock($lock, LOCK_EX | LOCK_NB)) {
                if (microtime(true) >= $until) return false;
                usleep(50000);
            }
            // Повреждённое хранилище нельзя считать пустым: уже использованная
            // ссылка снова стала бы действующей. Запись атомарная; ENOSPC
            // сохраняет прежнюю историю, cookie до её записи не выдаётся.
            if ((int) $exp <= $this->adguardGateNow()) return false;
            $raw = is_file($f) ? @file_get_contents($f) : '{}';
            $used = is_string($raw) ? json_decode($raw, true) : null;
            if (!is_array($used)) return false;
            foreach ($used as $value) if (!is_int($value)) return false;
            $now = $this->adguardGateNow();
            $used = array_filter($used, static fn($e) => $e > $now);
            if (isset($used[$nonce])) return false;
            $used[$nonce] = (int) $exp;
            $temporary = @tempnam(dirname($f), '.adguard-links-');
            if ($temporary === false || dirname($temporary) !== dirname($f)) return false;
            if (!@chmod($temporary, 0600)) return false;
            $json = json_encode($used);
            return @file_put_contents($temporary, $json) === strlen($json) && @rename($temporary, $f);
        } finally {
            if (is_string($temporary) && is_file($temporary)) @unlink($temporary);
            flock($lock, LOCK_UN);
            fclose($lock);
        }
    }

    protected function adguardLinksFile(): string { return '/logs/.adguard-links.json'; }

    public function adguardExchangeLink(string $token): ?string
    {
        $conf = $this->getPacConf();
        if (empty($conf['adgbrowser']) || !$this->adguardLinkConsume($token)) return null;
        [$exp, $linkNonce, $linkSig] = explode('.', $token);
        // A concurrent close/reopen must never issue a cookie under a new epoch.
        if (!hash_equals($this->adguardSignature('link', (int) $exp, $linkNonce, $conf), $linkSig)) return null;
        $nonce = bin2hex(random_bytes(8));
        return "$exp.$nonce." . $this->adguardSignature('browser', (int) $exp, $nonce, $conf);
    }

    public function adguardSetGateCookie(string $hash, string $token): bool
    {
        if (!$this->adguardGateCheck($token, 'cookie')) return false;
        $secure = !empty($_SERVER['HTTPS']) || ($_SERVER['HTTP_X_FORWARDED_PROTO'] ?? '') === 'https';
        $set = setcookie('adg', $token, ['expires' => (int) explode('.', $token, 2)[0], 'path' => "/adguard$hash/",
            'httponly' => true, 'samesite' => 'Lax', 'secure' => $secure]);
        // Прежний пропуск (cookie c = публичный hash) больше ничего не открывает.
        setcookie('c', '', ['expires' => 1, 'path' => '/']);
        return $set;
    }

    // Ссылка для стороннего браузера: только при включённом «сторонний
    // браузер» и только администратору в чат.
    public function adguardBrowserLink(): void
    {
        $conf = $this->getPacConf();
        if (empty($conf['adgbrowser']) || !empty($conf['adg_panel_closed']) || (int) ($this->input['from'] ?? 0) <= 0) { $this->menu('adguard'); return; }
        $hash = $this->getHashBot();
        $url = 'https://' . $this->getDomain() . "/webapp$hash/adg?t=" . $this->adguardGateToken('link', self::ADGUARD_LINK_TTL);
        $this->send($this->input['from'], $this->t('Ссылка открывается один раз. Доступ в браузере истечёт через 15 минут с момента выдачи ссылки. Не пересылайте её.',
            'This link opens once. Browser access expires 15 minutes after the link was issued. Keep it private.')
            . "\n<code>" . self::esc($url) . '</code>');
    }

    public function adguardChBr()
    {
        $c = $this->pacConfUpdate(function (&$c) {
            $c['adgbrowser'] = !empty($c['adgbrowser']) ? 0 : 1;
            $c['adg_browser_epoch'] = bin2hex(random_bytes(16));
            return $c;
        });
        $this->cloakNginx();
        $this->answer($this->input['callback_id'], $this->i18n($c['adgbrowser'] ? 'browser_notify_on' : 'browser_notify_off'), true);
        $this->menu('adguard');
    }

    // Версия AdGuardHome в контейнере ad. `AdGuardHome --version` печатает
    // «AdGuard Home, version v0.107.78» и сразу выходит, конфига не требует.
    // Полный путь обязателен — бинаря нет в PATH; 2>&1 обязателен — ssh()
    // читает только stdout. Тем же транспортом бот уже стартует и гасит демон
    // (startAd/stopAd), так что новых точек отказа не появляется.
    //
    // Не через HTTP API /control/status: порт веб-панели живёт в
    // /config/AdGuardHome.yaml и меняется пользователем, плюс нужен basic-auth —
    // две лишние причины не получить версию там, где хватает одной команды.
    //
    // Фолбэк — build-пин ADGUARD_VERSION из .env (контейнер не отвечает); он
    // расходится с образом, пока тот не пересобран, поэтому расхождение
    // помечаем в меню — так же, как у ocserv и caddy.
    public function adguardVersion(): array
    {
        $out = (string) $this->ssh('/opt/adguardhome/AdGuardHome --version 2>&1', 'ad');
        return [
            'running' => preg_match('~AdGuard\s*Home,?\s*version\s+(v?\d+(?:\.\d+)+[0-9A-Za-z.\-]*)~i', $out, $m) ? $m[1] : '',
            'pinned'  => trim((string) getenv('ADGUARD_VERSION')),
        ];
    }

    public function changeAdguardVersion()
    {
        $r = $this->send(
            $this->input['chat'],
            $this->t("@{$this->input['username']} введите версию AdGuardHome тегом <code>vX.Y.Z</code> (например <code>v0.107.78</code>).\n\n", "@{$this->input['username']} enter the AdGuardHome version as a tag <code>vX.Y.Z</code> (e.g. <code>v0.107.78</code>).\n\n")
            . $this->t("ВНИМАНИЕ: понижать версию нельзя — старая версия не прочитает обновлённый конфиг. ", "WARNING: do not downgrade: an older version cannot read the updated config. ")
            . $this->t("Версия только записывается в .env; как её применить — AdGuard → «📖 Справка» → «Версия, сброс и неполадки».", "The version is only written to .env; how to apply it: AdGuard → 📖 Help → Version, reset and troubleshooting."),
            $this->input['message_id'],
            reply: $this->t('введите версию AdGuardHome', 'enter the AdGuardHome version'),
        );
        $this->stashReply($r, [
            'start_message'  => $this->input['message_id'],
            'start_callback' => $this->input['callback_id'],
            'callback'       => 'chAdguardVersion',
            'args'           => [],
        ]);
    }

    public function chAdguardVersion($v)
    {
        $v = trim((string) $v);
        // Теги AdGuard: v0.107.78, изредка беты вида v0.108.0-b.90.
        if (!preg_match('~^v\d+\.\d+\.\d+(?:-[0-9A-Za-z.]+)?$~', $v)) {
            $this->update($this->input['chat'], $this->input['message_id'], $this->t('нужен тег вида vX.Y.Z (например v0.107.78)', 'a tag like vX.Y.Z is needed (e.g. v0.107.78)'));
            sleep(3);
            return $this->menu('adguard');
        }
        $this->setEnvVar('ADGUARD_VERSION', $v);
        // setEnvVar меняет только .env: без putenv getenv() до рестарта php
        // отдавал бы старый пин, и меню показывало бы, что ничего не изменилось
        // (тот же приём, что в chCaddyVersion).
        putenv("ADGUARD_VERSION=$v");
        $this->menu('adguard');
    }

    public function adguardMenu()
    {
        $conf   = $this->getPacConf();
        $browserLink = !empty($conf['adgbrowser']) && empty($conf['adg_panel_closed']) ? [[[
            'text' => $this->t('🔗 Ссылка для браузера (15 мин)', '🔗 Browser link (15 min)'),
            'callback_data' => '/adguardLink',
        ]]] : [];
        $panelSwitch = [[ 'text' => empty($conf['adg_panel_closed']) ? $this->t('🔒 Закрыть доступ к панели', '🔒 Close panel access') : $this->t('🔓 Открыть доступ к панели', '🔓 Open panel access'),
            'callback_data' => empty($conf['adg_panel_closed']) ? '/adguardPanel close' : '/adguardPanel open' ]];
        if (!$this->adguardPrivateChat()) {
            return ['text' => $this->t('Настройки AdGuard Home и данные доступа доступны в личном чате с ботом.',
                'Open your private chat with the bot for AdGuard Home settings and credentials.'),
                'data' => [$panelSwitch, ...$browserLink, [['text' => $this->i18n('back'), 'callback_data' => '/menu']]]];
        }
        $ip     = $this->ip;
        $domain = $this->getDomain();
        $hash   = $this->getHashBot();
        $scheme = empty($ssl = $this->nginxGetTypeCert()) ? 'http' : 'https';
        // Пароль и ClientID вводит администратор: без экранирования символ
        // «<» или «&» в пароле делал сообщение невалидным HTML, и меню
        // AdGuard переставало открываться совсем.
        $text   = "$scheme://$domain/adguard$hash\nLogin: admin\nPass: <span class='tg-spoiler'>" . self::esc($conf['adpswd'] ?? '') . "</span>\n\n";
        $ad     = $this->adguardConf() ?? [];
        if ($ssl) {
            // Алиасы обслуживаются тем же server-блоком nginx (cloakNginx кладёт
            // их в server_name) и покрыты тем же сертом после «renew SSL» —
            // печатаем точку входа на КАЖДЫЙ домен, иначе вторая половина
            // мультидомена для пользователя просто не существует.
            // Фолбэк на $domain: без настроенного домена это IP, и dnsDomains()
            // пуст — вывод должен остаться прежним.
            $dnsDomains = $this->dnsDomains($conf) ?: [$domain];
            // Ключ, сохранённый до появления проверки, в адреса не подставляем.
            $adkey      = !empty($conf['adguardkey']) && self::adguardClientIdValid((string) $conf['adguardkey']) ? $conf['adguardkey'] : '';
            $doh        = [];
            $dot        = [];
            foreach ($dnsDomains as $d) {
                $doh[] = "<code>$scheme://$d/dns-query$hash" . ($adkey !== '' ? "/$adkey" : '') . "</code>";
                $dot[] = "<code>tls://" . ($adkey !== '' ? "$adkey." : '') . "$d</code>";
            }
            $text .= "DNS over HTTPS:\n<code>$ip</code>\n" . implode("\n", $doh) . "\n\n";
            $text .= "DNS over TLS:\n" . implode("\n", $dot);
        }
        $status = $this->i18n(exec("JSON=1 timeout 2 dnslookup google.com ad 2>/dev/null") ? 'on' : 'off');
        $safesearch = !empty($ad['filtering']['safe_search']['enabled']);
        $text .= "\n\nstatus: $status\t\tsafesearch: " . $this->i18n($safesearch ? 'on' : 'off');
        if ($ad === []) {
            $text .= $this->t("\n⚠️ AdGuardHome.yaml не читается", "\n⚠️ AdGuardHome.yaml cannot be read");
        }
        // Живое состояние — у самого AdGuard: защита, лимит и сводка за период.
        if (($live = $this->adguardApi('GET', 'status', null, 3)) !== null) {
            $paused = (int) ($live['protection_disabled_duration'] ?? 0);
            $text  .= "\n" . $this->i18n('adg protection') . ': ' . (!empty($live['protection_enabled']) ? $this->i18n('on')
                : $this->i18n('off') . ($paused > 0 ? ' (' . (int) ceil($paused / 60000) . ' min)' : '') . ' ⚠️');
            if (($stats = $this->adguardApi('GET', 'stats', null, 3)) !== null) {
                $total   = (int) ($stats['num_dns_queries'] ?? 0);
                $blocked = (int) ($stats['num_blocked_filtering'] ?? 0);
                $text   .= "\n" . $this->i18n('adg queries') . ": $total, " . $this->i18n('adg blocked') . ": $blocked"
                    . ($total > 0 ? ' (' . round($blocked / $total * 100, 1) . '%)' : '');
            }
        }
        $rate = (int) ($ad['dns']['ratelimit'] ?? 20);
        $text .= "\n" . $this->i18n('adg rate limit') . ': ' . ($rate > 0 ? "$rate/s" : $this->i18n('off'));
        $ver = $this->adguardVersion();
        if ($ver['running'] !== '' || $ver['pinned'] !== '') {
            $esc   = fn($v) => htmlspecialchars((string) $v, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
            $text .= "\nAdGuardHome: <code>" . $esc($ver['running'] ?: '—') . '</code>';
            // Три разных состояния, и путать их нельзя: пустой running — это
            // «контейнер не ответил», а не «пин разошёлся с образом».
            // Сравниваем без ведущей «v» — так же, как в ocMenu.
            if ($ver['pinned'] !== '' && $ver['running'] === '') {
                $text .= $this->t(' (пин: <code>', ' (pin: <code>') . $esc($ver['pinned']) . $this->t('</code>, контейнер не отвечает)', '</code>, the container does not respond)');
            } elseif ($ver['pinned'] !== '' && ltrim($ver['pinned'], 'vV') !== ltrim($ver['running'], 'vV')) {
                $text .= $this->t(' (пин: <code>', ' (pin: <code>') . $esc($ver['pinned']) . $this->t('</code>, нужна пересборка)', '</code>, rebuild needed)');
            }
        }
        $allowedClients = array_map('strval', (array) ($ad['dns']['allowed_clients'] ?? []));
        if ($allowedClients) {
            // Весь список, как и раньше; у идентификаторов, выданных ботом, —
            // имя пользователя. Длинный текст update() сам делит на сообщения.
            $names = [];
            foreach ((array) (($this->getXray() ?: [])['inbounds'][0]['settings']['clients'] ?? []) as $client) {
                if (($uid = (string) ($client['id'] ?? '')) === '') {
                    continue;
                }
                $legacy = $this->legacyDohClientId($uid);
                foreach ([$this->dohClientId($uid), $legacy, implode(':', str_split($legacy, 2))] as $id) {
                    $names[$id] = (string) ($client['email'] ?? '');
                }
            }
            $text .= "\n\nallowed clients: \n - " . implode("\n - ", array_map(
                static fn($v) => self::esc($v) . (($names[$v] ?? '') !== '' ? ' — ' . self::esc($names[$v]) : ''), $allowedClients));
        } elseif (!empty($this->getPorts()['ad']['enable'])) {
            // Порт DoT опубликован, список разрешённых пуст — резолвером может
            // пользоваться любой, кто знает адрес сервера.
            $text .= "\n\n⚠️ " . $this->i18n('adg dot open');
        }

        $data = [
            [
                [
                    'text'          => 'web panel',
                    'web_app' => [
                        "url" => "https://$domain/adguard$hash"
                    ],
                ],
                [
                    'text'          => $this->i18n('third party browser') . ': ' . $this->i18n(!empty($conf['adgbrowser']) ? 'on' : 'off'),
                    'callback_data' => '/adguardChBr'
                ],
            ],
            $panelSwitch,
            ...$browserLink,
            [
                [
                    'text'          => $this->i18n('change password'),
                    'callback_data' => "/adguardpsswd",
                ],
                [
                    'text'          => 'ClientID' . (!empty($conf['adguardkey']) ? ": {$conf['adguardkey']}" : ''),
                    'callback_data' => "/setAdguardKey",
                ],
            ],
            [
                [
                    'text'          => '⚙️ ' . $this->i18n('adg settings'),
                    'callback_data' => '/adgSettings',
                ],
                [
                    'text'          => '📊 ' . $this->i18n('adg statistics'),
                    'callback_data' => '/adgStats',
                ],
            ],
        ];
        $data[] = [
            [
                'text'          => 'AdGuardHome: ' . ($ver['pinned'] ?: '—'),
                'callback_data' => '/changeAdguardVersion',
            ],
        ];
        $data[] = [
            [
                'text'          => $this->i18n('fill allowed clients'),
                'callback_data' => "/adgFillAllowedClients 0",
            ],
            [
                'text'          => $this->i18n('delete allowed clients'),
                'callback_data' => "/adgFillAllowedClients 1",
            ],
        ];
        $data[] = [
            [
                'text'          => $this->i18n('check DNS'),
                'callback_data' => "/checkdns",
            ],
            [
                'text'          => $this->i18n('reset settings'),
                'callback_data' => "/adguardreset",
            ],
        ];
        $data[] = [
            [
                'text'          => $this->i18n('add upstream'),
                'callback_data' => "/addupstream",
            ],
        ];
        $upstreams = $ad['dns']['upstream_dns'] ?? [];
        if (!empty($upstreams) && is_array($upstreams)) {
            foreach ($upstreams as $k => $v) {
                $data[] = [
                    [
                        'text'          => (string) $v,
                        'callback_data' => "/menu adguard",
                    ],
                    [
                        'text'          => $this->i18n('delete'),
                        'callback_data' => "/delupstream $k",
                    ],
                ];
            }
        }
        $data[] = $this->menuHelpButton('adguard');
        $data[] = [
            [
                'text'          => $this->i18n('back'),
                'callback_data' => "/menu",
            ],
        ];
        return [
            'text' => $text,
            'data' => $data,
        ];
    }

    // Миграция DoH client-id. Сначала (аудит 2026-08-18) в allowed_clients
    // лежали САМИ UUID клиентов; затем первая версия защиты заменила их на
    // голый 16-hex HMAC, который AdGuard ошибочно трактует как EUI-64. Теперь
    // обе старые формы переводятся в prefixed dohClientId(). Идемпотентна и
    // молчалива — cron/selfUpdate вызывают её многократно, но AdGuard она
    // перезапускает только при фактическом изменении YAML.
    public function migrateDohClientIds(): bool
    {
        if (($c = $this->adguardConf()) === null) {
            return false;
        }
        $uuidMap      = [];
        $legacyMap    = [];
        $legacyAlias  = [];
        foreach (($this->getXray()['inbounds'][0]['settings']['clients'] ?? []) as $v) {
            $id = (string) ($v['id'] ?? '');
            if ($id !== '') {
                $new    = $this->dohClientId($id);
                $legacy = $this->legacyDohClientId($id);
                // Две формы одного и того же старого идентификатора: сырые
                // 16 hex, как они уходили в DoH-URL, и EUI-64 — в этот вид
                // AdGuard переписывает такую строку у себя. Какую из них он
                // держит в dns.allowed_clients, зависит от версии, поэтому
                // держим ОБЕ: иначе «плавная» миграция ломает DNS ровно тем
                // клиентам, ради которых она и делается.
                $forms  = [$legacy, implode(':', str_split($legacy, 2))];
                $uuidMap[$id] = $new;
                foreach ($forms as $f) {
                    $legacyMap[$f]   = $new;
                    $legacyAlias[$f] = $forms;
                }
            }
        }
        if ($uuidMap === []) {
            return false;
        }
        $changed    = false;
        $keepLegacy = $this->dohLegacyAllowed();

        // 1. Список разрешённых клиентов. Сырой UUID убираем окончательно —
        // это credential VLESS. Старый HMAC безопасен, поэтому сохраняем его
        // рядом с новым ID: уже выданные конфиги продолжают резолвить до
        // обновления подписки, а новые сразу получают читаемое имя в AdGuard.
        $list = $c['dns']['allowed_clients'] ?? null;
        if (is_array($list)) {
            $next = [];
            foreach ($list as $v) {
                $v = (string) $v;
                if (isset($uuidMap[$v])) {
                    $next[] = $uuidMap[$v];
                } elseif (isset($legacyMap[$v])) {
                    // Переходный период (см. dohLegacyAllowed): старый id
                    // остаётся рабочим, пока пользователи обновляют подписку,
                    // а после дедлайна пропадает — вечный второй пропуск в DNS
                    // не нужен никому.
                    if ($keepLegacy) {
                        foreach ($legacyAlias[$v] as $alias) {
                            $next[] = $alias;
                        }
                    }
                    $next[] = $legacyMap[$v];
                } else {
                    $next[] = $v;
                }
            }
            $next = array_values(array_unique($next));
            if ($next !== array_values($list)) {
                $c['dns']['allowed_clients'] = $next;
                $changed = true;
            }
        }

        // 2. Персональные записи клиентов: по ним AdGuard раздаёт per-client
        //    политику и разбивает query-лог. Их пишет adguardXrayClients(), и
        //    без этой ветки после смены схемы политика молча переставала
        //    применяться — приходящий идентификатор ни с чем не совпадал.
        foreach (($c['clients']['persistent'] ?? []) as $i => $cl) {
            $ids = array_map('strval', (array) ($cl['ids'] ?? []));
            $next = [];
            foreach ($ids as $v) {
                if (isset($uuidMap[$v])) {
                    $next[] = $uuidMap[$v];
                } elseif (isset($legacyMap[$v])) {
                    $next[] = $legacyMap[$v];
                } else {
                    $next[] = $v;
                }
            }
            $next = array_values(array_unique($next));
            if ($next !== $ids) {
                $c['clients']['persistent'][$i]['ids'] = $next;
                $changed = true;
            }
            // uid НЕ трогаем: см. adguardXrayClients() — AdGuard требует там
            // формат UUID и отказывается читать конфиг целиком, если это не он.
        }

        if (!$changed) {
            return false;
        }
        $this->stopAd();
        $this->adguardWrite($c);
        $this->startAd();
        return true;
    }

    public function adgFillAllowedClients($delete = false)
    {
        $pac = $this->getPacConf();
        if (($c = $this->adguardConf()) === null) {
            $this->send($this->input['from'], $this->t('AdGuardHome.yaml не читается — список не изменён.', 'AdGuardHome.yaml cannot be read; the list is unchanged.'));
            return $this->menu('adguard');
        }
        $out[] = 'Restart Adguard Home';
        $this->update($this->input['chat'], $this->input['message_id'], implode("\n", $out));
        try {
            $this->stopAd();
            if (!empty($delete)) {
                unset($c['dns']['allowed_clients']);
            } else {
                $previous = array_fill_keys(array_map('strval',
                    (array) ($c['dns']['allowed_clients'] ?? [])), true);
                $keepLegacy = $this->dohLegacyAllowed();
                $c['dns']['allowed_clients'] = [];
                $c['dns']['allowed_clients'][] = '10.10.0.0/24';
                // Только корректный ClientID: на любой другой записи AdGuardHome
                // не запускается (ключ мог сохраниться до появления проверки).
                if (!empty($pac['adguardkey']) && self::adguardClientIdValid((string) $pac['adguardkey'])) {
                    $c['dns']['allowed_clients'][] = $pac['adguardkey'];
                }
                $c['dns']['allowed_clients'][] = getenv('WGADDRESS');
                $c['dns']['allowed_clients'][] = getenv('WG1ADDRESS');
                $c['dns']['allowed_clients'][] = '10.0.2.0/24'; // openconnect
                if (!empty($xr = $this->getXray())) {
                    foreach ($xr['inbounds'][0]['settings']['clients'] as $v) {
                        // Производный id, а не сам uuid: он же стоит в DoH-URL,
                        // который клиент дёргает на каждый запрос. См. dohClientId().
                        $uid = (string) ($v['id'] ?? '');
                        $c['dns']['allowed_clients'][] = $this->dohClientId($uid);
                        // Уже выданный конфиг со старым безопасным HMAC должен
                        // продолжить работать. На свежей установке лишний alias не
                        // добавляем: сохраняем его только если он был разрешён до
                        // ручной пересборки списка — и только пока идёт переходный
                        // период (см. dohLegacyAllowed). Кладём обе формы: AdGuard
                        // мог переписать сырые 16 hex в EUI-64 у себя.
                        $legacy    = $this->legacyDohClientId($uid);
                        $legacyMac = implode(':', str_split($legacy, 2));
                        if ((isset($previous[$legacy]) || isset($previous[$legacyMac])) && $keepLegacy) {
                            $c['dns']['allowed_clients'][] = $legacy;
                            $c['dns']['allowed_clients'][] = $legacyMac;
                        }
                    }
                }
                $c['dns']['allowed_clients'] = array_values(array_unique(array_filter(
                    $c['dns']['allowed_clients'], static fn($v) => (string) $v !== '')));
            }
            $this->adguardWrite($c);
            $this->startAd();
        } finally {
            // A failed restart must not leave the buttonless "Restart Adguard Home" screen.
            $this->menu('adguard');
        }
    }

    public function menuLang()
    {
        $data = [];
        $lang = [];
        foreach ($this->i18n as $k => $v) {
            $lang = array_merge($lang, array_keys($v));
        }
        $lang = array_unique($lang);
        foreach ($lang as $v) {
            if ($v != $this->language) {
                $data[] = [
                    [
                        'text'          => $v,
                        'callback_data' => "/lang $v",
                    ],
                ];
            }
        }
        $data[] = [
            [
                'text'          => $this->i18n('back'),
                'callback_data' => "/menu config",
            ],
        ];
        return [
            'text' => 'Language',
            'data' => $data,
        ];
    }

    public function expireCert()
    {
        $cert = @file_get_contents($this->protocolCertRoot . '/cert_public');
        $info = is_string($cert) ? @openssl_x509_parse($cert) : false;
        return $info['validTo_time_t'] ?? false;
    }

    public function domainsCert()
    {
        $cert = @file_get_contents($this->protocolCertRoot . '/cert_public');
        $info = is_string($cert) ? @openssl_x509_parse($cert) : false;
        $domains = $info['extensions']['subjectAltName'] ?? '';
        if (empty($domains)) {
            return false;
        }
        return array_map(fn($e) => trim($e), explode(',', str_replace('DNS:', '', $domains)));
    }

    public function updatebot()
    {
        $b = exec('git -C / rev-parse --abbrev-ref HEAD');
        $track  = trim(file_get_contents('/update/branch'));
        $hash   = $this->getHashBot();
        $domain = $this->getPacConf()['domain'] ?: $this->ip;
        $data = [
            [
                [
                    'text'          => "$b => $track",
                    'callback_data' => "/branches",
                ],
                [
                    'text'    => $this->i18n('changelog'),
                    'web_app' => ['url' => $this->changelogUrl()],
                ],
            ],
            [
                [
                    'text'          => $this->i18n('update bot'),
                    'callback_data' => "/applyupdatebot",
                ],
            ],
        ];
        $data[] = [
            [
                'text'          => $this->i18n('back'),
                'callback_data' => "/menu config",
            ],
        ];
        exec("git -C / branch -vv", $mm);
        // Ветка и канал образов показываются вместе: они обязаны быть парными
        // (dockerfile и рассчитывающий на него PHP лежат в одном коммите), а
        // разъезд виден только так — сам по себе неверный VPNBOT_TAG ничем не
        // проявляется, кроме странных ошибок в рантайме.
        // «→» читается как «станет после нажатия update»: ветку переключит
        // update.sh по /update/branch, тег — scripts/sync_image_tag.sh по этой
        // же ветке.
        $tag  = trim((string) getenv('VPNBOT_TAG')) ?: 'latest';
        $want = self::branchTag($track ?: $b);
        $head = 'branch: <code>' . htmlspecialchars($b) . '</code> → <code>'
            . htmlspecialchars($track ?: $b) . '</code>' . "\n"
            // Пин на сборку (sha-<commit>) синхронизатор не трогает, поэтому и
            // стрелку «станет» рисовать нельзя — она бы обещала смену канала,
            // которой не будет.
            . 'images: <code>' . htmlspecialchars($tag) . '</code>'
            . (str_starts_with($tag, 'sha-')
                ? ' 📌'
                : ' → <code>' . $want . '</code>' . ($tag === $want ? '' : ' ⚠'))
            . "\n";
        return [
            'text' => $head . '<pre><code class="language-shell">' . htmlentities(implode("\n", $mm)) . '</code></pre>',
            'data' => $data,
        ];
    }

    // Канал образов, парный ветке кода. Соответствие задаёт CI
    // (.github/workflows/images.yml): сборка с master публикует тег latest,
    // сборка с любой другой ветки — dev. Здесь тот же выбор, чтобы бот показывал
    // и sync_image_tag.sh ставил ровно то, что реально лежит в registry.
    public static function branchTag(string $branch): string
    {
        return trim($branch) === 'master' ? 'latest' : 'dev';
    }

    // Команду забирает update.sh на хосте. Без него кнопка молча ничего не делала:
    // черновик исчезает сам, а команда остаётся лежать в pipe.
    protected function updateWorkerReady(): bool
    {
        $dir = dirname($this->update);
        return is_file("$dir/update_pid") && trim((string) @file_get_contents("$dir/pipe")) === '';
    }

    public function applyupdatebot()
    {
        if (!$this->updateWorkerReady()) {
            $this->send($this->input['from'], $this->i18n('update worker busy'));
            return;
        }
        if (!$this->pinBackup($this->update)) {
            $this->send($this->input['from'], $this->i18n('update backup failed'));
            return;
        }
        $r = (array) $this->sendDraft($this->input['from'], 1, 'update...');
        if (!$this->queueUpdateCommand('1', $r)) {
            $this->send($this->input['from'], $this->i18n('update write failed'));
            return;
        }
        $this->delete($this->input['from'], $this->input['message_id']);
    }

    public function restart()
    {
        if (!$this->updateWorkerReady()) {
            $this->send($this->input['from'], $this->i18n('update worker busy'));
            return;
        }
        $r = (array) $this->sendDraft($this->input['from'], 1, 'restart...');
        if (!$this->queueUpdateCommand('2', $r)) {
            $this->send($this->input['from'], $this->i18n('update write failed'));
            return;
        }
        $this->delete($this->input['from'], $this->input['message_id']);
    }

    public function queueUpdateCommand(string $command, array $draft): bool
    {
        $files = [
            'reload_message' => "{$this->input['from']}:" . ($draft['result']['message_id'] ?? ''),
            'key' => $this->key,
            // update.sh шлёт ход обновления тем же адресом Bot API, что и бот
            // (ретранслятор из config/telegram_api, а не только .env).
            'api' => $this->telegramApiBase(),
            'curl' => json_encode(['chat_id' => $this->input['chat'],
                'message_id' => $draft['result']['message_id'] ?? null, 'text' => '~t~'], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES),
        ];
        foreach ($files as $name => $content) {
            // The bot token must never be created with the default 0644 mode.
            if (!$this->writePrivateKey('/update/' . $name, $content)) return false;
        }
        // Publish the command only once all data is safely on disk.
        return $this->writePrivateKey('/update/pipe', $command);
    }

    public function configMenu()
    {
        $conf = $this->getPacConf();
        $oc   = $this->getHashSubdomain('oc');
        $np   = $this->getHashSubdomain('np');
        // Панель не зависит от домена (доступ только по 127.0.0.1 + ssh -L),
        // поэтому строка вне блока $conf['domain'] — показываем всегда.
        // Меняется только хеш-часть /panel<hash>/, IP и порт фиксированы.
        $panelPort = (int) (getenv('PANEL_PORT') ?: 8090);
        $text[]    = $this->t("панель: <code>http://127.0.0.1:$panelPort/panel{$this->getHashBot()}/</code>", "panel: <code>http://127.0.0.1:$panelPort/panel{$this->getHashBot()}/</code>");
        if (!empty($conf['domain'])) {
            $ssl_expiry = $this->expireCert();
            $certs      = $this->domainsCert() ?: [];

            $text[] = "<blockquote>";
            $text[] = "Domains:";
            $text[] = $conf['domain'] . (in_array($conf['domain'], $certs) ? ' (ssl: ' . date('Y-m-d H:i:s', $ssl_expiry) . ')' : '');
            $text[] = 'naive ' . "$np.{$conf['domain']}" . (in_array("$np.{$conf['domain']}", $certs) ? ' (ssl: ' . date('Y-m-d H:i:s', $ssl_expiry) . ')' : '');
            $text[] = 'openconnect ' . "$oc.{$conf['domain']}" . (in_array("$oc.{$conf['domain']}", $certs) ? ' (ssl: ' . date('Y-m-d H:i:s', $ssl_expiry) . ')' : '');
            array_push($text, ...$this->managedProtocolDomainLines());
            if (!empty($conf['adguardkey'])) {
                $text[] = "{$conf['adguardkey']}.{$conf['domain']}" . (in_array("{$conf['adguardkey']}.{$conf['domain']}", $certs) ? ' (ssl: ' . date('Y-m-d H:i:s', $ssl_expiry) . ')' : '') . ' adguard DOT';
            }
            // WEB-прокси telemt (тип прокси WEB в Telegram Desktop) живёт на
            // своём поддомене, и без SAN на ЭТО имя Desktop соединение не
            // откроет. Поэтому отсутствие сертификата показываем явно, как у
            // алиасов, а не молчанием, как у naive/openconnect: там имя нужно
            // только своему клиенту, а здесь — единственная точка входа.
            if (!empty($conf['telemt_web']) && ($tw = $this->telemtWebHost($conf)) !== '') {
                $text[] = "telemt web $tw" . (in_array($tw, $certs) ? ' (ssl: ' . date('Y-m-d H:i:s', $ssl_expiry) . ')' : ' (no ssl — renew SSL)');
            }
            foreach ($conf['domain_aliases'] ?? [] as $a) {
                $text[] = "alias $a" . (in_array($a, $certs) ? ' (ssl: ' . date('Y-m-d H:i:s', $ssl_expiry) . ')' : ' (no ssl — renew SSL)');
                // У алиаса та же точка входа DoT, что и у главного домена:
                // «renew SSL» кладёт adguardkey.<алиас> в SAN. До этого строки
                // не было, и DoT на алиасе выглядел несуществующим.
                if (!empty($conf['adguardkey'])) {
                    $text[] = "{$conf['adguardkey']}.$a" . (in_array("{$conf['adguardkey']}.$a", $certs) ? ' (ssl: ' . date('Y-m-d H:i:s', $ssl_expiry) . ')' : ' (no ssl — renew SSL)') . ' adguard DOT';
                }
            }
            $text[] = "</blockquote>";
        } else {
            $text[] = $this->i18n('domain explain');
        }

        $data = [
            [['text' => $this->t('Протоколы и контейнеры', 'Protocols and containers'), 'callback_data' => '/protocolModules']],
            [
                [
                    'text'          => $conf['domain'] ? "{$this->i18n('delete')} {$conf['domain']}" : $this->i18n('install domain'),
                    'callback_data' => $conf['domain'] ? '/deldomain' : '/domain',
                ],
                [
                    'text'          => $this->i18n('nip.io'),
                    'callback_data' => '/addNipdomain',
                ],
            ],
        ];
        if ($conf['domain']) {
            $aliasRow = [
                [
                    'text'          => '+ alias domain',
                    'callback_data' => '/domainAlias',
                ],
            ];
            foreach (array_values($conf['domain_aliases'] ?? []) as $i => $a) {
                $aliasRow[] = [
                    'text'          => "❌ $a",
                    'callback_data' => "/delDomainAlias $i",
                ];
            }
            // Не больше 3 кнопок в ряд — дальше переносим.
            foreach (array_chunk($aliasRow, 3) as $chunk) {
                $data[] = $chunk;
            }
        }
        if ($conf['domain']) {
            if ($cert = $this->nginxGetTypeCert()) {
                switch ($cert) {
                    case 'letsencrypt':
                        $data[] = [
                            [
                                'text'          => $this->i18n('renew SSL'),
                                'callback_data' => "/setSSL letsencrypt",
                            ],
                            [
                                'text'          => $this->i18n('delete SSL'),
                                'callback_data' => "/deletessl",
                            ],
                        ];
                        break;
                    case 'self':
                        $data[] = [
                            [
                                'text'          => $this->i18n('delete SSL'),
                                'callback_data' => "/deletessl",
                            ],
                        ];
                        break;
                }
            } else {
                $data[] = [
                    [
                        'text'          => $this->i18n('Letsencrypt SSL'),
                        'callback_data' => "/setSSL letsencrypt",
                    ],
                    [
                        'text'          => $this->i18n('Self SSL'),
                        'callback_data' => "/selfssl",
                    ],
                ];
            }
        }
        // Служба хоста acme-window продлевает сертификаты этого бота и соседних
