                    'callback_data' => "/restart",
                ],
            ];
        }
        $data[] = [
            [
                'text'          => $this->i18n('back'),
                'callback_data' => "/menu config",
            ],
        ];
        $this->update(
            $this->input['chat'],
            $this->input['message_id'],
            implode("\n", $text ?: ['...']),
            $data ?: false,
        );
    }

    // Сервисы, у которых в текущем тексте override-compose стоит
    // `ports: !override`. PHP yaml_emit не умеет кастомные YAML-теги, поэтому
    // фиксируем их ДО парсинга и восстанавливаем ПОСЛЕ emit
    // (см. emitComposeWithOverrides). Любой yaml_parse→yaml_emit roundtrip без
    // этого молча теряет тег, и docker-compose сольёт ports основного файла и
    // override — контейнер получит и старый, и новый порт.
    private function detectComposeOverrides(string $content): array
    {
        $overrides = [];
        if (preg_match_all('/(\w+):\s*\n\s+ports:\s*!override/m', $content, $matches)) {
            foreach ($matches[1] as $service) {
                $overrides[$service] = true;
            }
        }
        return $overrides;
    }

    // Сериализует compose-структуру обратно в YAML и возвращает `ports: !override`
    // тем сервисам, что перечислены в $overrides (см. detectComposeOverrides).
    private function emitComposeWithOverrides(array $c, array $overrides): string
    {
        $yaml = yaml_emit($c);
        foreach ($overrides as $service => $val) {
            // Заменяем "ports:" на "ports: !override" для конкретного сервиса
            $yaml = preg_replace(
                '/(' . preg_quote($service, '/') . ':\s*\n\s+)ports:/m',
                '${1}ports: !override',
                $yaml
            );
        }
        return $yaml;
    }

    public function hidePort($container)
    {
        $ports = [
            'ad'    => '853:853',
            'dnstt' => '53:53/udp',
        ];
        $f = '/docker/compose';
        $content = is_file($f) ? file_get_contents($f) : '';

        // Находим все сервисы с !override для ports (фиксируем до парсинга)
        $overrides = $this->detectComposeOverrides($content);

        // Парсим YAML
        $c = $content ? yaml_parse($content) : [];

        // Изменяем структуру
        if (!empty($c['services'][$container])) {
            unset($c['services'][$container]);
        } else {
            $c['services'][$container]['ports'][] = $ports[$container];
        }

        // Записываем обратно (с восстановлением !override)
        if (empty($c['services'])) {
            file_put_contents($f, '');
        } else {
            file_put_contents($f, $this->emitComposeWithOverrides($c, $overrides));
        }

        $this->pacConfUpdate(function (&$pac) {
            $pac['restart'] = 1;
        });
        $this->ports();
    }

    public function setPort($port, $container)
    {
        $port  = (int) $port;
        $ports = [
            'hy'   => ['443/udp'],
            'tt'   => ['8443/tcp', '8443/udp'],
            'ovpn' => array_map(static fn($proto) => "1194/$proto", $this->ovpnListenProtos()),
        ];
        foreach ($this->ports as $service => $target) {
            $ports[$service] = [$target];
        }
        // Port value that means "remove from override" for each service.
        // hy uses 443 (its in-container port); tt/ovpn have no port mapping in
        // main compose, so 0/empty disables external exposure.
        $disable = [
            'hy'   => 443,
            'tt'   => 0,
            'ovpn' => 0,
        ];
        $reserved = [80, 443];
        // Сервисы, у которых ports заданы в основном compose — для них
        // override.yml ДОЛЖЕН использовать !override, иначе docker-compose
        // объединит массивы и контейнер получит и старый, и новый порт.
        $forceOverride = ['tt' => true];

        $f = '/docker/compose';
        $content = is_file($f) ? file_get_contents($f) : '';

        // Находим все сервисы с !override для ports (фиксируем до парсинга)
        $overrides = $this->detectComposeOverrides($content);

        // Парсим YAML
        $c = $content ? yaml_parse($content) : [];

        // Изменяем структуру
        if (!empty($port) && is_numeric($port) && !in_array($port, $reserved, true) && $port != ($disable[$container] ?? 0) && !empty($ports[$container])) {
            $c['services'][$container]['ports'] = array_map(
                fn($p) => "$port:$p",
                $ports[$container]
            );
            if (!empty($forceOverride[$container])) {
                $overrides[$container] = true;
            }
        } else {
            unset($c['services'][$container]);
        }

        // Записываем обратно (с восстановлением !override)
        if (empty($c['services'])) {
            file_put_contents($f, '');
        } else {
            file_put_contents($f, $this->emitComposeWithOverrides($c, $overrides));
        }

        // TT идёт через nginx в upstream-контейнере: client → host:PORT
        // → DNAT (Docker iptables ИЛИ ручной nftables) → upstream:PORT
        // → proxy_pass trusttunnel (tt:8443). Меняем listen-порт в
        // upstream.conf и перезагружаем nginx, чтобы новый порт начал
        // приниматься без полного recreate. Заодно синхронизируем
        // TTPORT в .env, чтобы fallback-значение для бота совпадало.
        if ($container === 'tt') {
            $listen = ($port > 0 && $port != ($disable['tt'] ?? 0)) ? $port : (int)(getenv('TTPORT') ?: 2443);
            $this->setUpstreamPortTt($listen);
            $this->setEnvVar('TTPORT', (string) $listen);
        }

        // Same architecture as TT: client → host:PORT → DNAT → upstream:PORT
        // → proxy_pass openvpn (ovpn:1194/udp). Sync upstream listen + .env
        // fallback. Протоколы — по server.conf (udp, tcp или оба).
        if ($container === 'ovpn') {
            $listen = ($port > 0 && $port != ($disable['ovpn'] ?? 0)) ? $port : (int)(getenv('OVPNPORT') ?: 1194);
            $this->setUpstreamPortOvpn($listen);
            $this->setEnvVar('OVPNPORT', (string) $listen);
        }

        $this->pacConfUpdate(function (&$pac) {
            $pac['restart'] = 1;
        });
        $this->ports();
    }

    public function setUpstreamPortTt($port)
    {
        $port  = (int) $port ?: 2443;
        $f     = '/config/upstream.conf';
        if (!file_exists($f)) {
            return;
        }
        $block = "#tt-port\n    server {\n        listen      $port reuseport;\n        proxy_pass  trusttunnel;\n    }\n    server {\n        listen      $port udp reuseport;\n        proxy_pass  trusttunnel;\n    }\n    #tt-port";
        // Маркер должен быть на собственной строке (с необязательным
        // отступом), чтобы не совпасть с упоминанием "#tt-port" внутри
        // комментариев выше по файлу.
        $re = '~^[ \t]*#tt-port[ \t]*\R.+?^[ \t]*#tt-port[ \t]*$~sm';
        $this->editUpstream(fn($nginx) => preg_replace($re, $block, $nginx));
    }

    public function setUpstreamPortOvpn($port, $proto = null)
    {
        $port  = (int) $port ?: 1194;
        $f     = '/config/upstream.conf';
        if (!file_exists($f)) {
            return;
        }
        // Явный $proto — один протокол; без него — то, что слушает сервер
        // (в режиме udp+tcp два блока, как у TrustTunnel).
        $block = self::ovpnUpstreamBlock($port, $proto ? [str_starts_with($proto, 'tcp') ? 'tcp' : 'udp'] : $this->ovpnListenProtos());
        $re = '~^[ \t]*#ovpn-port[ \t]*\R.+?^[ \t]*#ovpn-port[ \t]*$~sm';
        $this->editUpstream(fn($nginx) => preg_replace($re, $block, $nginx));
    }

    public function setEnvVar($key, $value)
    {
        // Контейнер php монтирует корневой .env как /mirror/.env.
        $f = '/mirror/.env';
        if (!file_exists($f) || !preg_match('~^[A-Z_][A-Z0-9_]*$~', $key)) {
            return;
        }
        $content = file_get_contents($f);
        $line    = "$key=$value";
        if (preg_match('~^' . preg_quote($key, '~') . '=.*$~m', $content)) {
            $content = preg_replace('~^' . preg_quote($key, '~') . '=.*$~m', $line, $content);
        } else {
            $content = rtrim($content, "\n") . "\n$line\n";
        }
        file_put_contents($f, $content);
    }

    public function branches()
    {
        exec('git -C / branch -r', $m);
        array_shift($m);
        foreach ($m as $k => $v) {
            $data[] = [
                [
                    'text'          => $v,
                    'callback_data' => "/changeBranch $k",
                ]
            ];
        }
        $data[] = [
            [
                'text'          => $this->i18n('back'),
                'callback_data' => "/menu update",
            ]
        ];
        $this->update($this->input['from'], $this->input['message_id'], 'branches', $data);
    }

    public function changeBranch($i)
    {
        exec('git -C / branch -r', $m);
        array_shift($m);
        foreach ($m as $k => $v) {
            if ($i == $k) {
                file_put_contents('/update/branch', trim(str_replace('origin/', '', $v)));
            }
        }
        $this->menu('update');
    }

    /**
     * Файлы логов в /logs: только обычные файлы, без точечных, без каталогов и
     * без служебных кэшей меню.
     *
     * Каталог там ровно один — geodata (скачанные .dat), и он показывался в
     * меню логов наравне с файлами: «очистить» звало file_put_contents на
     * каталог, «удалить» — unlink. Кэши menu_status/menu_versions логами не
     * являются вовсе.
     */
    protected function logDirectory(): string { return '/logs'; }

    protected function logPaths(): array
    {
        // Служебные файлы, которые лежат в /logs, но логами не являются: кэши
        // меню и счётчики лимитера подписок. Показывать их как логи (и давать
        // кнопку «очистить») незачем.
        $skip = ['menu_status.json', 'menu_versions.json', 'sub_ratelimit.json', 'xray_core'];
        $dir = $this->logDirectory();
        $out  = [];
        foreach (is_dir($dir) ? scandir($dir) : [] as $v) {
            if (!preg_match('/^[A-Za-z0-9_][A-Za-z0-9_.-]{0,53}$/D', $v) || in_array($v, $skip, true)
                || is_link("$dir/$v") || !is_file("$dir/$v")) {
                continue;
            }
            $out[$v] = "$dir/$v";
        }
        $roots = ['hysteria' => $this->hysteriaUsersRoot];
        foreach (['anytls', 'mieru', 'tuic', 'shadowtls', 'snolc', 'masque'] as $protocol) {
            $roots[$protocol] = "$this->protocolRoot/$protocol";
        }
        foreach ($roots as $protocol => $root) {
            foreach (['core.log', 'core.previous.log'] as $name) {
                $path = "$root/runtime/$name";
                if (is_file($path) && !is_link($path)
                    && realpath($path) === realpath(dirname($root)) . '/' . basename($root) . "/runtime/$name") {
                    $out["$protocol.$name"] = $path;
                }
            }
        }
        ksort($out);
        return $out;
    }

    public function logFiles(): array { return array_keys($this->logPaths()); }

    public function logs($page = 0)
    {
        $p = $this->getPacConf();
        $paths = $this->logPathsByTime();
        $pages = max(1, (int) ceil(count($paths) / 20));
        $page = max(0, min((int) $page, $pages - 1));
        $data = [];
        foreach (array_slice($paths, $page * 20, 20, true) as $v => $path) {
            $size   = (int) @filesize($path);
            $time   = (int) @filemtime($path);
            // Кнопка несёт ИМЯ файла, а не позицию в scandir: позиции ехали от
            // появления нового файла, и «очистить» попадало в соседний лог.
            $data[] = [
                [
                    'text'          => "📄 $v · " . ($size ? $this->getBytes($size) : $this->t('пусто', 'empty')) . ($time ? ' · ' . date('d.m H:i', $time) : ''),
                    'callback_data' => "/getLog $v",
                ],
                ['text' => '👁', 'callback_data' => "/tailLog $v"],
                [
                    'text'          => '🧹',
                    'callback_data' => "/clearLog $v",
                ],
            ];
        }
        if ($pages > 1) {
            $navigation = [];
            if ($page > 0) $navigation[] = ['text' => '←', 'callback_data' => '/logs ' . ($page - 1)];
            $navigation[] = ['text' => ($page + 1) . "/$pages", 'callback_data' => "/logs $page"];
            if ($page + 1 < $pages) $navigation[] = ['text' => '→', 'callback_data' => '/logs ' . ($page + 1)];
            $data[] = $navigation;
        }
        $data[] = [
            [
                'text'          => $this->i18n('clean all'),
                'callback_data' => "/cleanLog",
            ],
        ];
        $autocleanlogs = array_values(array_filter(explode('/', $p['autocleanlogs'] ?? '')));
        if (!empty($autocleanlogs)) {
            if (count($autocleanlogs) === 2 && strtotime($autocleanlogs[0]) !== false && strtotime($autocleanlogs[1]) !== false) {
                $autocleanlogs = "{$autocleanlogs[0]} start / {$autocleanlogs[1]} period";
            } else {
                $autocleanlogs = $this->i18n('off') . " {$p['autocleanlogs']} - wrong format";
            }
        }
        $data[] = [
            [
                'text'          => $this->i18n('autoclean'). ': ' . ($autocleanlogs ?: $this->i18n('off')),
                'callback_data' => "/autoCleanLogs",
            ],
        ];
        $data[] = [
            [
                'text'          => $this->i18n('back'),
                'callback_data' => "/menu config",
            ],
        ];
        $this->update(
            $this->input['chat'],
            $this->input['message_id'],
            implode("\n", ['Menu -> config -> ' . $this->t('логи', 'logs'),
                $this->t('Свежие сверху (по времени последней записи). 📄 — скачать файл, 👁 — последние строки в чате, 🧹 — очистить.',
                    'Newest first (by last write). 📄 downloads the file, 👁 shows the last lines here, 🧹 clears it.')]),
            $data ?: false,
        );
    }

    /** Log files, most recently written first; ties by name. */
    protected function logPathsByTime(): array
    {
        $paths = $this->logPaths();
        uksort($paths, static fn($a, $b) => ((int) @filemtime($paths[$b]) <=> (int) @filemtime($paths[$a])) ?: strcmp($a, $b));
        return $paths;
    }

    /** The last lines of a log in the chat, newest first; the whole file stays one tap away. */
    public function tailLog($name)
    {
        $f = $this->logFileOr404((string) $name);
        if ($f === null) return $this->logs();
        $size = (int) @filesize($f);
        $lines = [];
        if ($size > 0 && ($h = @fopen($f, 'rb')) !== false) {
            fseek($h, max(0, $size - 65536));
            $chunk = (string) stream_get_contents($h);
            fclose($h);
            $all = preg_split('~\r?\n~', rtrim(mb_scrub($chunk, 'UTF-8')));
            if ($size > 65536) array_shift($all); // the first line may be cut
            $lines = array_reverse(array_slice($all, -40));
        }
        $text = ['Menu -> config -> ' . $this->t('логи', 'logs') . ' -> ' . htmlspecialchars((string) $name, ENT_QUOTES),
            ($size ? $this->getBytes($size) : $this->t('пусто', 'empty')) . ((int) @filemtime($f) ? $this->t(' · изменён ', ' · modified ') . date('d.m.Y H:i:s', (int) filemtime($f)) : '')];
        if ($lines) {
            $text[] = $this->t('Последние строки, новые сверху:', 'Last lines, newest first:');
            $body = '';
            foreach ($lines as $line) {
                $line = mb_substr(preg_replace('~[[:cntrl:]]~u', ' ', $line), 0, 300);
                if (mb_strlen($body) + mb_strlen($line) > 3300) break;
                $body .= $line . "\n";
            }
            $text[] = '<pre>' . htmlspecialchars(rtrim($body), ENT_QUOTES) . '</pre>';
        } else {
            $text[] = $this->i18n('log empty');
        }
        $this->update($this->input['chat'], $this->input['message_id'], implode("\n", $text), [
            [['text' => '🔄 ' . $this->i18n('refresh'), 'callback_data' => "/tailLog $name"], ['text' => '📄 ' . $this->t('Файл', 'File'), 'callback_data' => "/getLog $name"]],
            [['text' => $this->i18n('back'), 'callback_data' => '/logs']],
        ]);
    }

    // Имя приходит из кнопки, а уходит в путь: принимаем только то, что
    // действительно есть в списке логов (заодно отсекает «..» и любой обход).
    protected function logFileOr404(string $name): ?string
    {
        return $this->logPaths()[$name] ?? null;
    }

    public function getLog($name)
    {
        $f = $this->logFileOr404((string) $name);
        if ($f === null) {
            return $this->logs();
        }
        if (filesize($f) === 0) {
            return $this->answer($this->input['callback_id'], $this->i18n('log empty'));
        }
        $this->sendFile(
            $this->input['chat'],
            curl_file_create($f),
        );
    }

    public function clearLog($name)
    {
        if (($f = $this->logFileOr404((string) $name)) !== null) {
            file_put_contents($f, '');
        }
        $this->logs();
    }

    public function cleanLog($nomenu = false)
    {
        // По списку logFiles(), а не по сырому scandir: раньше сюда попадали и
        // «.», и «..», и каталог geodata — file_put_contents на них сыпал
        // warning'ами при каждой автоочистке по расписанию.
        foreach ($this->logPaths() as $path) {
            file_put_contents($path, '');
        }
        if (!$nomenu) $this->logs();
    }

    public function delLog($name)
    {
        // Старые кнопки удаления тоже очищают файл: unlink оставлял демон
        // писать в удалённый inode, и журнал пропадал до перезапуска сервиса.
        $this->clearLog($name);
    }

    public function selfUpdate(): bool
    {
        // Версии сервисов живут в кэше с часовым TTL — после пересборки образов
        // он бы врал до часа. selfUpdate() зовётся из service.php на каждом
        // старте контейнера, то есть ровно тогда, когда версии и могли
        // измениться: снимаем кэш, cron наполнит его заново на первом же цикле.
        @unlink(static::MENU_VERSIONS_FILE);
        $updateDir                  = dirname($this->update);
        $restored                   = is_file($updateDir . '/state-restored');
        $rm                         = explode(':', trim((string) @file_get_contents($updateDir . '/reload_message')));
        $m                          = (string) @file_get_contents($updateDir . '/message');
        // message_id может прийти пустым (reload_message вида "chat:") — тогда
        // передавать его в send(?int $to) нельзя: '' → TypeError и фатал в
        // service.php до restartTelemt. Приводим к ?int.
        $mid                        = (isset($rm[1]) && $rm[1] !== '') ? (int) $rm[1] : null;
        $this->input['chat']        = $rm[0];
        $this->input['message_id']  = $mid;
        $this->input['callback_id'] = $mid;
        // Старый host-worker сбрасывал конфиги и требовал импорт JSON. Новый
        // возвращает точные runtime-файлы до запуска контейнеров. Оба пути
        // сохраняют последнюю копию; ошибка не превращается в новую установку.
        if (file_exists($this->update)) {
            $this->selfupdate = !$restored;
            try {
                if (!empty($m)) {
                    // htmlspecialchars обязателен: с этого момента в
                    // /update/message приходят СУБЪЕКТЫ коммитов, а в них
                    // встречаются < > & (те же теги CPS вида <b 0x..>).
                    // parse_mode=HTML на таком тексте отдаёт 400, и отчёт об
                    // обновлении молча не доходил бы.
                    $this->send($this->input['chat'], '<pre>' . htmlspecialchars($m) . '</pre>', $mid);
                }
                if (!$restored) {
                    $snapshot = json_decode((string) file_get_contents($this->update), true);
                    if (!is_array($snapshot) || !is_array($snapshot['pac'] ?? null)) {
                        throw new \RuntimeException('invalid update backup');
                    }
                    $r = $this->send($this->input['chat'], "import settings");
                    $this->input['message_id']  = $r['result']['message_id'] ?? $mid;
                    $this->input['callback_id'] = $r['result']['message_id'] ?? $mid;
                    if ($this->importFile($this->update) === false) {
                        throw new \RuntimeException('update backup restore failed');
                    }
                }
                if (!rename($this->update, $this->update . '.last')) {
                    throw new \RuntimeException('could not retain update backup');
                }
                $this->chmodSecret($this->update . '.last');
            } catch (\Throwable $e) {
                error_log('selfUpdate: restore failed; backup retained');
                $this->send($this->input['chat'], $this->i18n('update restore failed'));
                return false;
            }
        }
        @unlink($updateDir . '/state-restored');
        file_put_contents($updateDir . '/message', '');
        file_put_contents($updateDir . '/reload_message', '');
        // Миграция DoH-идентификаторов. Некритична и не должна ронять
        // service.php: ниже по selfUpdate() ничего от неё не зависит.
        try {
            $this->migrateDohClientIds();
        } catch (\Throwable $e) {
            error_log('selfUpdate migrateDohClientIds: ' . $e->getMessage());
        }
        return $this->pacConfUpdate(function (&$pac) { unset($pac['restart']); return true; });
    }

    public function backup()
    {
        $r = $this->send(
            $this->input['chat'],
            $this->t("@{$this->input['username']} введите в формате: начало / период", "@{$this->input['username']} enter like: start / period"),
            $this->input['message_id'],
            reply: $this->t('например: now / 12 hours', 'enter like: now / 12 hours'),
        );
        $this->stashReply($r, [
            'start_message'  => $this->input['message_id'],
            'start_callback' => $this->input['callback_id'],
            'callback'       => 'setBackup',
            'args'           => [],
        ]);
    }

